window.DATA={"questions":[{"id":"o000","subj":"880","chap":"第一章 糖类","type":"名词解释","years":["10"],"q":"构型","points":[{"k":"定义","t":"构型指立体异构体中原子或取代基团的空间排列关系，构型不同的分子在立体化学形式上能够区分。"},{"k":"D型与L型","t":"构型分 D-型与 L-型；构型的改变必须共价键断裂并重新形成，常伴光学活性的变化。"}],"note":"","opts":[],"printed_answer":""},{"id":"o001","subj":"880","chap":"第一章 糖类","type":"名词解释","years":["16"],"q":"凝集素","points":[{"k":"定义","t":"凝集素是从植物、无脊椎动物和高等动物中提纯的一类糖蛋白或结合糖的蛋白，能专一识别并结合糖基。"},{"k":"凝集红细胞","t":"因可与红细胞膜上的血型糖抗原结合而使红细胞凝集（含血型物质），故名凝集素。"}],"note":"","opts":[],"printed_answer":""},{"id":"o002","subj":"880","chap":"第一章 糖类","type":"简答","years":["20","21"],"q":"简述淀粉和纤维素的结构特点，并举例说明纤维素在我们生活中的应用。","points":[{"k":"纤维素线性β链","t":"纤维素是线形葡聚糖，残基间以 β-1,4-糖苷键连接，纤维二糖为其二糖单位；相邻残基相互翻转 180°，链取完全伸展构象。"},{"k":"氢键片层微晶","t":"相邻平行伸展链在残基环面水平方向靠链内、链间氢键连成片层，若干链聚成有周期性晶格的分子束（微晶或胶束），多个胶束再组成微纤维。"},{"k":"淀粉两支链型","t":"淀粉是植物普遍存在的储藏多糖：直链淀粉由 α-1,4-糖苷键连接、不分支；支链淀粉另有 α-1,6-糖苷键，约每 30 个 α-1,4 键出现一个分支点。"},{"k":"调整肠道菌群","t":"纤维素是肠道菌群重要的发酵原料，促益生菌增殖、抑有害菌，对维持肠道微生态有重要调节作用。"},{"k":"促蠕动防便秘","t":"β-1,4-糖苷键不能被人体糖苷酶分解，故纤维素属膳食纤维、不被消化，可机械刺激肠道蠕动，预防和治疗便秘。"},{"k":"吸水膨胀防肥胖","t":"纤维素吸水膨胀、增加饱腹感，避免能量摄入过多，对预防和治疗肥胖作用明显。"}],"note":"","opts":[],"printed_answer":""},{"id":"o003","subj":"880","chap":"第三章 氨基酸","type":"名词解释","years":["12","19"],"q":"氨基酸等电点","points":[{"k":"定义","t":"在某一 pH 溶液中，氨基酸解离成阳离子和阴离子的趋势及程度相等，成为兼性离子、净电荷为零，此时溶液的 pH 称该氨基酸的等电点（pI）。"},{"k":"电场不迁移","t":"等电点时氨基酸在电场中既不向正极也不向负极移动，溶解度最低、最易沉淀析出。"}],"note":"","opts":[],"printed_answer":""},{"id":"o004","subj":"880","chap":"第三章 氨基酸","type":"简答","years":["17","18","19"],"q":"考察的是氨基酸的各种性质。给出 6 种氨基酸的结构式和名称，问分支氨酸是？紫外吸收为 280nm 的氨基酸是？电泳时向负极移动的氨基酸是？可以平衡血液 PH 的氨基酸是？胰蛋白酶降解的氨基酸是？等等 10 个小问","points":[{"k":"分类与结构","t":"按 R 基分五类：非极性脂肪族（Gly、Ala、Pro、Val、Leu、Ile、Met）、非极性芳香族（Phe、Tyr、Trp）、极性不带电（Ser、Thr、Cys、Asn、Gln）、极性带正电（Lys、Arg、His）、极性带负电（Asp、Glu）；各氨基酸的区别在于 R 基不同，蛋白质中的氨基酸都是 L 型 α-氨基酸。"},{"k":"分支氨基酸","t":"即侧链氨基酸，指 Val、Leu、Ile，β 位、γ 位带甲基，结构相似，代谢上走共同途径，可被具共同底物特异性的酶催化。"},{"k":"紫外吸收280","t":"芳香族氨基酸都能吸收紫外光，其中 Trp 在 280 nm 吸收最大，故多数蛋白质在 280 nm 处有特征性光吸收，可用于测定蛋白质含量。"},{"k":"碱性氨基酸","t":"Lys、Arg、His 为极性带正电氨基酸，pH 7 时带正电，电泳时向负极移动；His 的咪唑基 pKa 在 6.0 左右、接近中性，是血液 pH 的重要缓冲基团（对红细胞运输 O₂ 和 CO₂ 重要），还可在酶活性中心作质子供体/接纳体，起酸碱催化。"},{"k":"蛋白酶切点","t":"胰蛋白酶切 Lys、Arg 的 C 端；胰凝乳蛋白酶切 Phe、Trp、Tyr 的 C 端；胃蛋白酶切 Phe、Trp、Tyr、Leu、Val 等疏水残基的 N 端；弹性蛋白酶切 Ala、Gly 等短脂肪链氨基酸的 C 端。"},{"k":"其他特殊性质","t":"Gly 是唯一无侧链者、也是唯一无旋光性者（除 Gly 外都有旋光性）；Met 与 Cys 为两个含硫氨基酸，Met 常作甲基供体；Ser、Thr、Tyr 的羟基是磷酸化位点；Cys 的巯基易氧化成二硫键；Pro 为亚氨基酸，肽键易顺式、易成 β 转角、与茚三酮呈亮黄色；Phe 浓度用于苯丙酮尿症诊断。"}],"note":"口径：依据《真题分类》资料原文。资料给的是各类氨基酸归属，据此把「电泳向负极」「His 平衡血 pH」两问并入「碱性氨基酸」一点；6 种氨基酸的具体结构式资料标注见知识点总结，此处不列。","opts":[],"printed_answer":"","ref":true},{"id":"o005","subj":"880","chap":"第三章 氨基酸","type":"简答","years":["21"],"q":"某一九肽由 2 个 Gly、2 个 Phe、Tyr、Met、Asp、Arg、Pro 组成，经胰凝乳蛋白酶处理后可形成一个五肽和一个四肽，四肽的组成为 Phe、Tyr、Gly、Pro，经 CNBr 处理后产物经阳离子交换树脂层析洗脱后得一组为 Arg、Phe、Gly 的三肽，经胰蛋白酶处理后得 Phe、用 DNFB 处理可得 DNP-Tyr，判断该氨基酸得顺序。","points":[{"k":"N端定Tyr","t":"DNFB 法得 DNP-Tyr，说明九肽 N 端为 Tyr。"},{"k":"胰凝乳定位","t":"胰凝乳蛋白酶切 Phe 的 C 端，把九肽断为四肽 Tyr-Pro-Gly-Phe 与五肽 Asp-Met-Gly-Arg-Phe，与题干「五肽＋四肽」吻合。"},{"k":"CNBr切Met","t":"CNBr 专切 Met 的羧基侧，五肽裂为 Asp-Met 与 Gly-Arg-Phe，从而把 Met 定位在第 6 位。"},{"k":"胰蛋白酶收尾","t":"胰蛋白酶切 Arg 的 C 端，三肽裂为 Gly-Arg 与游离 Phe，说明 Arg 紧邻 Phe 的 N 侧。"},{"k":"序列结论","t":"九肽顺序为 Tyr-Pro-Gly-Phe-Asp-Met-Gly-Arg-Phe。"}],"note":"题干两处与资料序列不自洽：① CNBr 产物写作「Arg、Phe、Gly」三肽，按序列应为 Gly-Arg-Phe；② 按该序列 Tyr 在 N 端，胰凝乳蛋白酶在 Tyr 后亦应切断，与「只切为五肽＋四肽」不符。正文取资料答案，考场把四条约束逐条写清并指出矛盾即可。","opts":[],"printed_answer":""},{"id":"o006","subj":"880","chap":"第三章 氨基酸","type":"简答","years":["21"],"q":"【图示题·原题含图】根据图中 His 在水溶液中的滴定曲线，回答下题 \n（1）写出 A、B、C 的 His 结构式\n（2）求 PI\n（3）写出 His PI 外的结构式\n（4）血红蛋白中富含 His 残基，为什么","points":[{"k":"A正电结构","t":"低 pH 时咪唑基与 α-氨基均质子化、α-羧基不解离，A 为净带正电的结构式。"},{"k":"B兼性离子","t":"等电状态时 α-羧基去质子带负电、咪唑基与 α-氨基带正电，B 为净电荷为零的兼性离子。"},{"k":"C负电结构","t":"高 pH 时羧基与咪唑基均去质子，α-氨基仍带正电，C 为净带负电（−1）的结构式。"},{"k":"计算等电点","t":"pI＝(pK_R＋pK_α-NH₃⁺)/2，取咪唑基与 α-氨基两个 pK 的平均值，按本题曲线得 pI≈7.585。"},{"k":"pI外结构式","t":"pI 之外即 A（净正电）与 C（净负电）两种结构式。"},{"k":"Hb富含His","t":"① His 咪唑基与血红素 Fe²⁺ 配位，影响 T→R 构象转变；② His146/His122 参与盐桥，是 Bohr 效应（H⁺ 结合降氧亲和力）的分子基础；③ 咪唑基 pK≈6.0，生理 pH 附近具缓冲与酸碱催化能力。"}],"note":"原卷滴定曲线图未附具体 pK 值，pI≈7.585 按资料给出的曲线数据。","opts":[],"printed_answer":""},{"id":"o007","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["10","12","19"],"q":"波尔效应（Bohr effect）","points":[{"k":"定义","t":"增加 CO₂ 浓度和降低 pH 都能提高血红蛋白亚基的协同效应，引起红细胞内血红蛋白氧亲和力下降、促进释放氧，这种 pH 与 CO₂ 对血红蛋白氧亲和力的影响称波尔效应。"},{"k":"双向表现","t":"反之，增加氧气浓度可使血红蛋白释放 H⁺ 及 CO₂，即氧合与释氧两个方向互相联动。"},{"k":"生理意义","t":"在组织（高 CO₂、低 pH）处降低氧亲和力、促进放氧，从而提高其运氧能力。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o008","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["13"],"q":"β-转角（β-turn）","points":[{"k":"定义与长度","t":"多肽链中常见的二级结构，是可连接其他二级结构（α 螺旋、β 折叠）并使肽链走向改变的非重复多肽区；一般含 2~16 个氨基酸残基，含 5 个以上者又称环（loops），常见者含 4 个残基。"},{"k":"氢键特征","t":"有两种类型，共同特点为第 1 个残基的羰基氧与第 4 个残基的酰胺氮之间形成氢键。"},{"k":"残基偏好","t":"第 2 个残基大部分是脯氨酸，第 3 个残基往往是甘氨酸，故肽链易在此回折。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o009","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["13"],"q":"亲和层析（affinity chromatography）","points":[{"k":"定义","t":"利用共价连接有特异配体的层析介质，分离蛋白质混合物中能特异结合该配体的目的蛋白或其他分子的层析技术。"},{"k":"常见类型","t":"按配体不同分为免疫亲和层析、凝集素亲和层析等。"},{"k":"补：洗脱与优点","t":"目的蛋白特异结合、杂蛋白直接流走，再以游离配体或改变 pH、离子强度洗脱，选择性高、步骤少，常可一步纯化。"}],"note":"口径：依据《真题分类》资料原文；末点（洗脱方式与一步纯化优点）为资料之外补充分点。","opts":[],"printed_answer":"","ref":true},{"id":"o010","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["13"],"q":"别构蛋白（allosteric protein）","points":[{"k":"别构效应","t":"寡聚蛋白质一般具有多个结合部位，结合在分子特定部位上的配体对该分子其他部位所产生的影响，称为别构效应。"},{"k":"定义","t":"具有别构效应的蛋白质称为别构蛋白。"},{"k":"补：构象调活性","t":"调节物结合别构部位引起构象改变，使蛋白活性升高或降低，是代谢调节的分子基础。"}],"note":"口径：依据《真题分类》资料原文；末点（构象改变调节活性）为按教材口径补充分点。","opts":[],"printed_answer":"","ref":true},{"id":"o011","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["13"],"q":"主动运输","points":[{"k":"定义","t":"主动运输是物质逆化学浓度梯度（逆电化学势）跨膜转运的方式。"},{"k":"需载体耗能","t":"既需借助镶嵌在细胞膜上的特异性传递蛋白作载体，又必须消耗细胞代谢产生的能量才能完成。"}],"note":"","opts":[],"printed_answer":""},{"id":"o012","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["13"],"q":"分子伴侣","points":[{"k":"定义","t":"一类能特异地结合和释放底物蛋白的蛋白分子。"},{"k":"功能","t":"帮助底物蛋白实现正确折叠、寡聚体组装、向特定细胞器转运，或变换活化/去活化构象等。"},{"k":"补：不参与产物","t":"分子伴侣本身并不参与最终产物的形成，只起陪伴作用，故名分子伴侣。"}],"note":"口径：依据《真题分类》资料原文；末点（不参与终产物形成）为按教材口径补充分点。","opts":[],"printed_answer":"","ref":true},{"id":"o013","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["12"],"q":"别构效应","points":[{"k":"定义","t":"又称变构效应：某些寡聚蛋白与别构效应剂作用后，通过蛋白质构象变化改变其活性。"},{"k":"双向调节","t":"这种活性改变既可以是活性的增加，也可以是活性的减少。"}],"note":"","opts":[],"printed_answer":""},{"id":"o014","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["17"],"q":"肽平面","points":[{"k":"定义","t":"肽链中肽键上的 4 个原子（C、O、N、H）与相邻 2 个 Cα 共处一个平面，即肽平面。"},{"k":"刚性平面","t":"肽平面是刚性平面结构，C-N 键具有部分双键性质，不能自由旋转。"}],"note":"","opts":[],"printed_answer":""},{"id":"o015","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["10"],"q":"盐析","points":[{"k":"定义","t":"盐析是向蛋白质溶液中加入高浓度中性盐（常用硫酸铵、硫酸钠），使蛋白质沉淀析出的方法。"},{"k":"夺水化层可复溶","t":"高浓度盐离子与蛋白质争夺水分子、破坏水化层，并中和表面电荷，胶体稳定性下降而聚集沉淀；盐析不引起变性，降低盐浓度即可复溶，不同蛋白质所需盐浓度不同，故可用于分级分离。"}],"note":"原答案误抄的是「结构域」的定义（与 o016 错位），此处按题干「盐析」补写正确内容。","opts":[],"printed_answer":""},{"id":"o016","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["10"],"q":"结构域","points":[{"k":"定义","t":"结构域指多肽链在二级结构或超二级结构基础上形成的三级结构局部折叠区，是相对独立的紧密球状实体。"},{"k":"折叠单位","t":"结构域是球状蛋白的折叠单位，多肽链折叠的最后一步是各结构域之间的缔合。"}],"note":"原答案误抄的是「抗体」的定义（与 o015 错位互换），此处按题干「结构域」更正。","opts":[],"printed_answer":""},{"id":"o017","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["11"],"q":"抗体","points":[{"k":"定义","t":"抗体即免疫球蛋白（Ig），是一类血浆糖蛋白，糖与蛋白共价交联，能与抗原发生特异性免疫反应。"},{"k":"Y型四链五类","t":"呈 Y 型结构，由 2 条重链＋2 条轻链经二硫键连接；可变区（V）决定抗原结合特异性，恒定区（C）介导效应功能；分 IgG、IgA、IgM、IgE、IgD 五类。"}],"note":"","opts":[],"printed_answer":""},{"id":"o018","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["19"],"q":"什么是蛋白质二级结构，它主要有哪几种形式（特点）？","points":[{"k":"二级结构定义","t":"指蛋白质分子中某一段肽链的局部空间结构，即该段肽链主链骨架原子的相对空间位置，不包括侧链构象及与其他肽链的关系；主要靠主链原子之间形成的氢键维系。"},{"k":"α螺旋","t":"肽链主链绕假想中心轴盘绕成右手螺旋，靠链内氢键维持，即每个残基的羰基氧与其 C 端方向第 4 个残基的酰胺氮形成氢键；螺距 0.54 nm，每圈 3.6 个残基，每残基沿长轴上升 0.15 nm。"},{"k":"β折叠","t":"由伸展的多肽链组成，靠一个肽键的羰基氧与同一肽链或相邻肽链的酰胺氮之间的氢键维持；可平行或反平行排列，平行排列更规则、反平行排列更稳定。"},{"k":"β转角","t":"连接其他二级结构并使肽链走向改变的非重复肽段，多位于球状蛋白表面，一般含 2~16 个残基（5 个以上又称环），常见含 4 个残基；第 1 残基羰基氧与第 4 残基酰胺氮形成氢键，第 2 残基多为脯氨酸、第 3 残基常为甘氨酸。"},{"k":"β突起","t":"一般出现在反平行 β 折叠中，因链中多一个氨基酸而引起弯曲凸起。"},{"k":"无规卷曲","t":"泛指不能或未能归入上述明确二级结构的肽段，并非完全无规则，而是柔性较大、有一定任意性。"}],"note":"口径：依据《真题分类》资料原文。资料给出 5 种形式，其中β突起为资料原有、题库旧稿未收；数字 0.54 nm、3.6、0.15 nm、2~16、4 个残基均照原文核对无误。","opts":[],"printed_answer":"","ref":true},{"id":"o019","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["11"],"q":"什么叫蛋白质变性，变性后会引起什么现象，引起蛋白质变性的原因有哪些？","points":[{"k":"变性定义","t":"蛋白质在某些物理和化学因素作用下，其特定的空间构象被改变，导致理化性质改变和生物活性丧失，此现象称蛋白质变性。"},{"k":"一级结构不变","t":"变性并不引起一级结构的破坏，破坏的是二级结构以上的高级结构。"},{"k":"活性丧失","t":"生物活性降低，甚至完全丧失。"},{"k":"理化性质改变","t":"疏水基团外露，溶解度降低而产生沉淀；分子不对称性增加使粘度增加、扩散系数降低；次级键破坏使分子结构松散、不能形成结晶，且易被蛋白酶水解。"},{"k":"物理因素","t":"热、紫外线照射、高压和表面张力等。"},{"k":"化学因素","t":"有机溶剂、尿素和盐酸胍等变性剂、强酸强碱等；这些因素破坏蛋白质内部的氢键与疏水相互作用，从而破坏高级结构、导致变性。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o020","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["13"],"q":"请结合血红蛋白，分析蛋白质的四级结构，比较血红蛋白和肌红蛋白结构和功能的差异？","points":[{"k":"Hb四聚体","t":"血红蛋白是具四级结构的四聚体，含 2 个 α 亚基和 2 个 β 亚基，亚基间以非共价作用力缔合。"},{"k":"珠蛋白与血红素","t":"各亚基在生理条件下盘绕折叠成球形（珠蛋白），每个亚基内部结合 1 分子血红素；血红素为卟啉类小分子，中央配位 1 个 Fe²⁺，可结合 1 分子 O₂。"},{"k":"正协同别构","t":"4 个亚基对氧的结合能力不同：一个亚基结合 O₂ 后构象改变，使其余亚基更易结合氧，呈亚基间正协同效应，即别构调节。"},{"k":"Mb单体贮氧","t":"肌红蛋白为单体，无别构调节，氧合曲线为双曲线：对氧浓度变化不敏感、易结合难释放，适于在肌肉中贮存氧，只在缺氧时放氧。"},{"k":"Hb运输供氧","t":"血红蛋白为四聚体，具正协同别构调节，氧合曲线为 S 型：对氧浓度敏感，在肺部高氧处结合、在组织低氧处释放，适于血液运输供氧。"}],"note":"","opts":[],"printed_answer":""},{"id":"o021","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["13"],"q":"解释 CO 中毒的原理，处理方式是什么？","points":[{"k":"亲和力300倍","t":"CO 与血红蛋白的亲和力比 O₂ 大 300 倍以上，故与 O₂ 竞争性结合血红蛋白。"},{"k":"占据血红素","t":"CO 占据血红素 Fe²⁺ 配位位点形成 CO-Hb，红细胞丧失运输氧的能力，组织缺氧而窒息死亡。"},{"k":"脱离现场给氧","t":"处理：立即转移到 CO 浓度低的地方，并及时补充氧气（高压氧更佳），解除 CO 对血红蛋白的抑制。"}],"note":"","opts":[],"printed_answer":""},{"id":"o022","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["10","12"],"q":"简述 α 角蛋白质的结构，并回答下面问题：人的头发每年以 15-20cm 的速度生长。头发主要是 α-角蛋白纤维在表皮细胞的里面合成和组装的“绳子”，α-角蛋白的基本结构单元是 α-螺旋，如果 α-螺旋的生物合成是头发长长的限制因素，α-螺旋链的肽键每秒钟以什么样的速度合成才能解释头发每年的生长速度？","points":[{"k":"α螺旋双股超螺旋","t":"α-角蛋白以 α-螺旋为基本单元：两股右手 α-螺旋向左缠绕成左手超螺旋，即直径 2 nm 的原纤维，属 αα 超二级结构。"},{"k":"9+2微纤维","t":"原纤维按「9+2」电缆式排列成直径 8 nm 的微纤维，包埋于富硫的无定形基质中，成百根微纤维再聚成直径约 200 nm 的大纤维。"},{"k":"二硫键定软硬","t":"二硫键越多、刚性越强：蹄、爪、角为硬角蛋白，皮肤为软角蛋白。"},{"k":"列式","t":"年生长 20 cm＝2×10⁸ nm，一年约 3.15×10⁷ s，故伸长速度＝2×10⁸÷3.15×10⁷≈6.34 nm/s。"},{"k":"代入","t":"α-螺旋每残基沿轴上升 0.15 nm（螺距 0.54 nm÷3.6），肽键合成速率＝6.34÷0.15≈42.3 个/s。"},{"k":"结论","t":"每秒约需合成 42~43 个肽键（每秒延伸约 6.3 nm），才能解释头发每年 15~20 cm 的生长；按 15 cm 计约为 32 个/s。"}],"note":"","opts":[],"printed_answer":""},{"id":"o023","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["12"],"q":"蛋白酶在 ph=1 时发挥作用，含有什么氨基酸，原因？","points":[{"k":"胃蛋白酶为代表","t":"如胃蛋白酶，最适 pH 为 1.5~2，属天冬氨酸蛋白酶类，活性部位有两个 Asp 残基。"},{"k":"广义酸碱催化","t":"催化机制为广义酸碱催化：两个 Asp 一个羧基质子化、一个羧基解离，形成「催化二联体」；水解时脱质子者作碱从底物接受质子，质子化者作酸向底物提供质子，相互协调完成水解。"},{"k":"羧基解离失活","t":"Asp 为酸性氨基酸，外界 pH 过高时其羧基完全解离、全部以脱质子形式存在，失去一酸一碱的搭配，酶即失活；只有 pH 1 附近才同时存在质子化与脱质子两种形式。"},{"k":"负电荷排斥变形","t":"pH 过高使大部分基团解离、带大量负电荷，蛋白质内氨基酸之间排斥增强，引起构象改变、活性丧失。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o024","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["13"],"q":"聚谷氨酸在 pH<3.0 是呈 α-螺旋状态，在 pH>5.0 时却为松散的 β 折叠，请解释原因？","points":[{"k":"侧链电荷敏感","t":"由可离子化侧链的氨基酸残基构成的 α-螺旋对 pH 变化非常敏感，因为溶液 pH 决定侧链是否带有电荷。"},{"k":"同种电荷相斥","t":"由单一一种氨基酸构成的聚合物，只有当侧链不带电荷时才能形成 α-螺旋；相邻残基侧链带同种电荷会产生静电排斥力，阻止多肽链盘成 α-螺旋构象。"},{"k":"低pH成螺旋","t":"Glu 侧链 pKa 约 4.1，pH 远低于 4.1（约 3 左右）时几乎所有多聚谷氨酸侧链不带电荷，多肽链能够形成 α-螺旋。"},{"k":"高pH转折叠","t":"pH 为 5 或更高时几乎所有侧链带负电荷，邻近电荷之间的静电排斥力阻止螺旋形成，同聚物呈伸展的 β-折叠构象。"},{"k":"对照多聚Lys","t":"如多聚 Lys，只有在 pH 远大于其侧链 pKa（10.5）时才能呈现 α-螺旋。"}],"note":"口径：依据《真题分类》资料原文。pKa 4.1、10.5 与 pH 3、5 的数值均照原文核对。","opts":[],"printed_answer":"","ref":true},{"id":"o025","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["11"],"q":"简述凝胶过滤层析、离子交换层析、亲和层析分离纯化蛋白质的原理","points":[{"k":"凝胶过滤","t":"按分子大小：凝胶珠有孔径，大分子进不去颗粒、只走颗粒间空隙，先出柱；小分子能进颗粒内部、路径长，后出柱，即「大快小慢」。"},{"k":"离子交换","t":"按电荷：pH＞pI 时蛋白带负电、结合阴离子交换剂，pH＜pI 带正电、结合阳离子交换剂；电荷越多结合越紧，用盐梯度或改变 pH 洗脱。"},{"k":"亲和层析","t":"按特异亲和力：将配体（底物类似物、抗体、金属离子）固定在载体上，目标蛋白特异结合、杂蛋白流走，再用游离配体洗脱；高效、快速、简便。"}],"note":"","opts":[],"printed_answer":""},{"id":"o026","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["11"],"q":"Pr 分析是生化一项重要实验，简述考马斯亮蓝法测定蛋白质含量的原理，简述实验方法。列举其他三种常见的试验方法测蛋白质含量，解释为什么不法分子在奶粉中加入三聚氰胺以提高收益？","points":[{"k":"考马斯原理","t":"考马斯亮蓝 G-250 有红、蓝两种形式：酸性条件下呈淡红色，与蛋白质结合后生成蓝色化合物，595 nm 处有最大吸收，且吸光度与蛋白浓度成正比。"},{"k":"实验方法","t":"配制标准蛋白梯度系列并设空白 → 各管加 G-250 试剂 → 室温静置显色 → 595 nm 比色 → 绘制标准曲线 → 由样品吸光度反查浓度。"},{"k":"紫外吸收法","t":"Trp、Tyr 的最大吸收峰在 280 nm，多数蛋白含这两种残基，测 A280 可快速简便估算蛋白含量。"},{"k":"Lowry与双缩脲","t":"Lowry 法：Tyr、Trp 还原 Folin-酚试剂生成深蓝色复合物，745~750 nm 比色；双缩脲法：肽键在碱性液中与 Cu²⁺ 生成紫色物，需至少两个肽键（二肽不反应）。"},{"k":"凯氏定氮","t":"蛋白质平均含氮 16%，测样品含氮量×6.25 即得蛋白质含量。"},{"k":"三聚氰胺掺假","t":"三聚氰胺含氮约 66%，加入奶粉可抬高凯氏定氮测得的含氮量，从而虚增「蛋白质」含量牟利。"}],"note":"","opts":[],"printed_answer":""},{"id":"o027","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["13"],"q":"SDS 聚丙烯酰胺凝胶电泳为什么可以测定蛋白质的分子量，为什么要加入巯基乙醇，为什么要沸水煮沸，为什么在凝胶前要抽气？","points":[{"k":"SDS掩盖电荷","t":"SDS 是阴离子，带很高负电荷，可掩盖不同蛋白质间原有的电荷差别；同时作为变性剂破坏氢键与疏水作用，使大多数蛋白质伸展成同样的棒状。"},{"k":"按分子量分离","t":"该技术完全基于蛋白质质量的不同而分离：由于凝胶的分子筛效应，迁移率与分子质量的对数呈线性关系，用已知分子质量的标准蛋白作标准曲线，即可由未知蛋白的迁移率求出分子质量。"},{"k":"巯基乙醇断二硫键","t":"巯基乙醇是还原剂，可把二硫键还原成巯基而打开二硫键；因 SDS 只能破坏氢键和疏水作用、不能打开二硫键，需二者共同作用使肽链处于伸展状态。"},{"k":"沸水煮沸","t":"加热可破坏氢键与疏水作用，并促进还原剂打开二硫键，把多亚基蛋白解离为单亚基，使蛋白质变性呈伸展棒状，避免外形影响迁移速率。"},{"k":"抽气去气泡","t":"抽气可排净气泡、减少气泡对结果的干扰；若不排净，电泳条带会不齐，且气泡所在位置不会出现蛋白质样品。"}],"note":"口径：依据《真题分类》资料原文（四问对应四点，SDS 掩盖电荷与按质量分离拆为两点）。","opts":[],"printed_answer":"","ref":true},{"id":"o028","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["16"],"q":"去西藏旅行高原反应原因，及预防措施","points":[{"k":"高原缺氧","t":"高原大气压低、氧分压低，肺泡与动脉血氧分压下降，血红蛋白氧饱和度降低，组织供氧不足而出现头痛、乏力、心悸等反应。"},{"k":"曲线右移代偿","t":"缺氧时 2,3-DPG 升高、pH 轻度降低，氧合曲线右移（p50 升高），血红蛋白在组织中更易放氧，属机体代偿。"},{"k":"影响曲线因素","t":"血红蛋白与氧的亲和力除受氧分压影响，还受 pH、CO₂、温度及 2,3-DPG 浓度影响；曲线左移则不利于组织释氧。"},{"k":"阶梯登高适应","t":"预防：阶梯式缓慢登高、初到减少剧烈活动、保暖防脱水、保证碳水摄入，必要时吸氧或服乙酰唑胺。"}],"note":"","opts":[],"printed_answer":""},{"id":"o029","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["17"],"q":"【图示题·原题含图】（1）从下面 SDS-PAGE 电泳图中标出五种蛋白质的大小顺序，并标出相应的位置（2）\n另一种分离蛋白质的机理和方法，以及用这种方法，上述五种蛋白质的排序结果。","points":[{"k":"SDS-PAGE判读","t":"SDS-PAGE 迁移率只取决于分子量、与 lgM 线性负相关：条带由上到下（泳动由慢到快）分子量由大到小，与 Marker 比对即可标出五种蛋白的位置。"},{"k":"另一方法","t":"另一种方法是凝胶过滤（分子排阻），按分子大小分离：大分子不能进入凝胶珠、只走颗粒间空隙，先洗脱；小分子能进颗粒内部、路径长，后洗脱。"},{"k":"两法结果一致","t":"两法均给出分子量由大到小的顺序，故凝胶过滤的洗脱顺序与 SDS-PAGE 自上而下的条带顺序一致。"},{"k":"机理不同","t":"机理不同：SDS-PAGE 靠电荷被掩盖后由分子量决定的电泳迁移率，凝胶过滤靠柱内可及体积与路径长短。"}],"note":"原卷电泳图未提供，无法给出五种蛋白的具体条带位置，排序规则如上。","opts":[],"printed_answer":""},{"id":"o030","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["20"],"q":"阐述血红蛋白的结构，及其与功能之间的关系，还有哪些机制能影响这种别构效应","points":[{"k":"四聚体结构","t":"血红蛋白为四聚体（α₂β₂），亚基间靠非共价作用力结合，各亚基盘绕折叠成球形（珠蛋白）并各结合 1 分子血红素。"},{"k":"血红素载氧","t":"血红素为卟啉结构的小分子，中央配位 1 个 Fe²⁺，可结合 1 分子 O₂，赋予血红蛋白结合氧的能力。"},{"k":"正协同S曲线","t":"一个亚基结合 O₂ 后构象改变，使其余亚基更易结合氧，呈亚基间正协同效应，氧合曲线为 S 型，是别构调节的基础。"},{"k":"波尔效应","t":"H⁺ 与 CO₂ 升高使血红蛋白氧亲和力下降、曲线右移，在组织处促放氧，即波尔效应。"},{"k":"2,3-BPG调节","t":"2,3-二磷酸甘油酸结合于 β 链中央孔穴、稳定 T 态，降低氧亲和力，促组织放氧；温度升高同样使曲线右移。"}],"note":"","opts":[],"printed_answer":""},{"id":"o031","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["20"],"q":"给出一些蛋白质/酶的分子量，让写出两种分离方法，说明其原理和结果","points":[{"k":"SDS-PAGE原理","t":"SDS 为阴离子去污剂，可掩盖不同蛋白原有的电荷差别，又作为变性剂破坏氢键与疏水作用，使蛋白伸展成同样棒状，故分离完全基于分子量。"},{"k":"SDS-PAGE结果","t":"电泳条带由上到下依次为 P4、P2、P1、P3、P5（分子量由大到小）。"},{"k":"凝胶过滤原理","t":"凝胶过滤用葡聚糖凝胶，颗粒交联介质排阻大分子：大分子只走颗粒间空隙、洗脱体积小，先出柱；小分子进入颗粒内部、须流过全部床体积，路程长、后出柱。"},{"k":"凝胶过滤结果","t":"按洗脱时间先后，蛋白质顺序同为 P4、P2、P1、P3、P5。"}],"note":"","opts":[],"printed_answer":""},{"id":"o032","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["21"],"q":"用生物化学简述 CO 中毒时，机体好氧量减少的原因。","points":[{"k":"竞争结合Hb","t":"CO 与血红蛋白的亲和力比 O₂ 大得多（约 200~300 倍），竞争性占据血红素 Fe²⁺ 配位位点，形成 CO-Hb。"},{"k":"携氧量骤降","t":"CO-Hb 不能结合 O₂，血氧容量与血氧含量下降，红细胞向组织输送的氧明显减少。"},{"k":"曲线左移难放氧","t":"CO 还使剩余亚基的氧合曲线左移、亚基间正协同效应减弱，血红蛋白在组织更难释放氧。"},{"k":"肌红蛋白失贮","t":"CO 与肌红蛋白的亲和力也远大于 O₂，肌红蛋白不能正常贮氧，肌肉供氧进一步下降。"}],"note":"题干「好氧量减少」应为「供氧量（组织获氧量）减少」。","opts":[],"printed_answer":""},{"id":"o033","subj":"880","chap":"第五章 酶","type":"名词解释","years":["16"],"q":"别构酶","points":[{"k":"定义","t":"又称变构酶，是代谢途径中的关键酶（限速酶），其催化活性受酶分子三维构象变化的调节。"},{"k":"调节方式","t":"别构效应剂非共价结合于活性中心以外的调节部位，引起构象改变而激活或抑制酶；动力学曲线呈 S 型而非双曲线。"}],"note":"","opts":[],"printed_answer":""},{"id":"o034","subj":"880","chap":"第五章 酶","type":"名词解释","years":["10","11","17","19"],"q":"同工酶","points":[{"k":"定义","t":"同工酶是指催化相同的化学反应，但蛋白质分子结构、理化性质和免疫性能等方面都存在明显差异的一组酶。"},{"k":"典型例子","t":"如乳酸脱氢酶（LDH）有 LDH₁~LDH₅ 五种，由 H、M 两类亚基不同组合成四聚体，各组织分布与动力学性质不同。"}],"note":"","opts":[],"printed_answer":""},{"id":"o035","subj":"880","chap":"第五章 酶","type":"名词解释","years":["10","11"],"q":"竞争性抑制","points":[{"k":"定义","t":"抑制剂与底物结构相似，可与底物竞争酶的活性中心、把底物排斥在反应中心之外，从而抑制酶促反应。"},{"k":"底物可解除","t":"增大底物浓度可竞争性解除抑制；动力学上 Km 增大、Vmax 不变。"}],"note":"","opts":[],"printed_answer":""},{"id":"o036","subj":"880","chap":"第五章 酶","type":"名词解释","years":["10"],"q":"酶的比活力","points":[{"k":"定义","t":"酶的比活力是指每毫克蛋白质所含的酶活力单位数（U/mg），用于表示酶的纯度，比活力越高纯度越高。"}],"note":"","opts":[],"printed_answer":""},{"id":"o037","subj":"880","chap":"第五章 酶","type":"简答","years":["12"],"q":"请简述酶可逆抑制的几种类型及其各自的特点","points":[{"k":"竞争性抑制","t":"抑制剂与底物结构相似、竞争同一结合部位，只与游离酶结合；使 Km 增大而 Vmax 不变，增加底物浓度可减轻抑制（双倒数图交于 y 轴）。"},{"k":"非竞争性抑制","t":"抑制剂与底物结合在不同位点，既可与游离酶结合也可与酶-底物复合物结合；使 Km 不变而 Vmax 变小，抑制程度与底物浓度无关，加大底物不能解除（双倒数图交于 x 轴）。"},{"k":"反竞争性抑制","t":"抑制剂只与酶-底物复合物结合、不与游离酶结合；使 Km 和 Vmax 都变小，但 Km/Vmax 不变，抑制程度随底物浓度增加而增加（双倒数图两线平行）。"}],"note":"口径：依据《真题分类》资料原文。资料原文作「Vmax/Km 不变」，反竞争性抑制应为 Km/Vmax 比值不变，已更正；各点末尾括注的双倒数图特征为按教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"o038","subj":"880","chap":"第五章 酶","type":"简答","years":["10"],"q":"简要说明可以用于判断和确定酶活性中心的一些主要方法(酶活性中心的测定)。","points":[{"k":"专一性研究","t":"研究酶的专一性底物的结构特点，可判断和确定活性中心的结构；研究竞争性抑制剂的必需结构也有助于了解活性中心结构。"},{"k":"酶切除法","t":"如链球菌核酸酶从 N 端切去 6 个氨基酸残基、牛胰核糖核酸酶从 N 端切去 12 个氨基酸残基，均不影响酶活力，表明这些部位与活性中心无关。"},{"k":"化学修饰法","t":"非特异共价修饰用专一性氨基酸试剂标记侧链后测活力变化；特异共价修饰只修饰活性部位某一残基使酶失活；抑制剂标记（亲和标记）用与底物结构相似的修饰剂共价标记活性部位，水解分离后分析。"},{"k":"动力学参数法","t":"活性部位氨基酸残基的解离状态与酶活性直接相关，由动力学方法求得有关参数后，即可判断活性部位的化学性质。"},{"k":"X射线衍射","t":"解析酶分子三维结构，了解活性部位残基的相对位置与实际状态、与活性部位有关的其他基团以及酶与底物的结合模式。"},{"k":"定点诱变","t":"改变编码蛋白质基因中的 DNA 顺序，研究酶活性部位的必需氨基酸。"}],"note":"口径：依据《真题分类》资料原文。资料六种方法（专一性研究、酶切除、化学修饰、动力学参数、X 射线衍射、定点诱变）全部保留；6 个与 12 个残基的数字照原文。","opts":[],"printed_answer":"","ref":true},{"id":"o039","subj":"880","chap":"第五章 酶","type":"简答","years":["10","13","19","21"],"q":"【图示题·原题含图】以丙酮酸为底物，测乳酸脱氢酶 LDH 活性，以 1/V 和 1/[S] 双倒数作图，得直线斜率为 1.2×10⁻³min,1/V 轴上的截距为 0.02 μ M⁻¹·min \n（1）该酶催化反应的方程为（米氏方程）？\n（2）可以用什么方法测该酶促反应，简述原因","points":[{"k":"列式","t":"双倒数式 1/v＝(Km/Vmax)(1/[S])＋1/Vmax，纵轴截距＝1/Vmax，斜率＝Km/Vmax。"},{"k":"求Vmax","t":"1/Vmax＝0.02 μM⁻¹·min → Vmax＝1÷0.02＝50 μM·min⁻¹。"},{"k":"求Km值","t":"Km/Vmax＝1.2×10⁻³ min → Km＝1.2×10⁻³×50＝0.06 μM。"},{"k":"米氏方程","t":"v＝50[S]/(0.06＋[S])，v 单位为 μM·min⁻¹，[S] 单位为 μM。"},{"k":"测定方法","t":"紫外分光光度法：LDH 催化丙酮酸＋NADH＋H⁺→乳酸＋NAD⁺，NADH 在 340 nm 有吸收而 NAD⁺ 没有，测 340 nm 吸光度的下降速率即可反映酶活。"}],"note":"","opts":[],"printed_answer":""},{"id":"o040","subj":"880","chap":"第五章 酶","type":"简答","years":["19"],"q":"简述酶的结构特点","points":[{"k":"简单酶与复杂酶","t":"酶按组成可分为简单酶和复杂酶，复杂酶的全酶由脱辅酶和辅因子构成。"},{"k":"脱辅酶与辅因子","t":"脱辅酶为蛋白质部分，具有结合底物的能力、决定酶催化的专一性；辅因子为非蛋白质部分，多为金属离子、无机阴离子和简单有机化合物，起电子、原子或化学基团的传递作用，决定酶催化的反应类型。"},{"k":"辅酶与辅基","t":"按与脱辅酶结合的松紧分：辅酶非共价松弛结合，可用透析等物理方法除去；辅基共价牢固结合，只能用一定的化学处理除去。"},{"k":"活性部位特点","t":"活性部位只占酶分子的很小部分，是赋予酶催化活性的三维实体，位于酶分子表面的空穴或裂缝内，整体为疏水环境、低介电常数，但也含某些极性氨基酸残基参与催化。"},{"k":"诱导契合与次级键","t":"活性部位并不与底物形状正好互补，而是通过诱导契合过程与底物结合，且具有柔性或可运动性；底物以氢键、盐键、范德华力和疏水相互作用等次级键结合。"},{"k":"结合与催化部位","t":"活性部位可分为结合部位（结合底物、决定专一性）与催化部位（催化底物转变为产物、决定反应类型）；个别酶在活性中心外还有调节部位，可受小分子调节、控制代谢方向。"}],"note":"口径：依据《真题分类》资料原文（原文按组成与功能两部分列出，此处归并为六点）；原文所附金属离子作用一问与本问无关，未列入。","opts":[],"printed_answer":"","ref":true},{"id":"o041","subj":"880","chap":"第五章 酶","type":"简答","years":["19"],"q":"测酶活力实验设计","points":[{"k":"实验目的","t":"在最适条件下测定给定酶的酶活力（U）与比活力（U/mg），据此评价酶制品的活性高低与纯度。"},{"k":"测定原理","t":"测单位时间内底物的减少量或产物的生成量（吸光度变化率 ΔA/min）；1 个酶活力单位定义为在上述条件下每分钟催化 1 μmol 底物转化所需的酶量。"},{"k":"反应体系","t":"配制最适 pH 的底物缓冲液、所需辅因子与酶稀释液；设空白管（不加酶）与测定管，同温预浴至最适温度。"},{"k":"测定步骤","t":"加酶启动反应，立即于特征波长（如 NADH 的 340 nm）连续读取 3~5 min 吸光度，取线性段求 ΔA/min；另用考马斯亮蓝法测蛋白浓度。"},{"k":"活力计算","t":"酶活力(U/mL)＝[ΔA/min÷(ε·d)]×10³×(V总/V酶)，ε 取 L·mol⁻¹·cm⁻¹、d 为光径(cm)、V 为体积(mL)；比活力(U/mg)＝酶活力÷蛋白浓度(mg/mL)。"},{"k":"结果判定","t":"须先作酶量与底物浓度的线性检验以保证初速度条件；各管重复 3 次取均值，比活力越高表示酶越纯、活性越好。"}],"note":"题干未给出具体酶与配套试剂，按分光光度法测酶活力的通用流程作答。","opts":[],"printed_answer":""},{"id":"o042","subj":"880","chap":"第五章 酶","type":"简答","years":[],"q":"【图示题·原题含图】某酶的动力学曲线如下图所示，请回答下列问题： （20 年就是这种类型题）\n（1）Km 和 Vmax 在米氏方程推导过程中的定义。\n（2）计算无抑制剂存在时的 Km 和 Vmax。\n（3）判断该抑制剂的类型。\n[图：双倒数作图，纵轴 1/v (min/nmol)，刻度 0—18；横轴 1/[S] (1/μM)，刻度 -0.15、-0.1、-0.05、0、0.05、0.1、0.15、0.2、0.25、0.3；两条直线分别标注 with inhibitor I、no inhibitor，方程式 y=15.982x + 2.1149]\nE + S ⇌(k₁/k₂) ES →(k₃) P","points":[{"k":"Km定义","t":"Km＝(k₂＋k₃)/k₁，即 ES 分解的各速率常数之和与生成速率常数之比；当 k₂≫k₃ 时近似等于 ES 的解离常数，可表征酶与底物的亲和力。"},{"k":"Vmax定义","t":"Vmax＝k₃[E]₀，即全部酶都以 ES 形式存在时的最大反应速度，由酶总浓度与催化常数决定。"},{"k":"列式","t":"双倒数式 1/v＝(Km/Vmax)(1/[S])＋1/Vmax，故纵轴截距＝1/Vmax，横轴截距＝−1/Km，斜率＝Km/Vmax。"},{"k":"求Vmax","t":"1/Vmax＝2.1149 min/nmol → Vmax＝1÷2.1149≈0.473 nmol·min⁻¹。"},{"k":"求Km值","t":"−1/Km＝−2.1149÷15.982＝−0.1323 μM⁻¹ → Km≈7.56 μM。"},{"k":"抑制剂类型","t":"非竞争性抑制：加抑制剂后纵轴截距上移（Vmax 减小）而横轴截距不变（Km 不变），双倒数图交于 x 轴。"}],"note":"原卷图只标出 no inhibitor 直线方程 y=15.982x+2.1149，with inhibitor I 直线仅有图示而无方程；此处按「Km 不变、Vmax 减小」判为非竞争性。原答案为 0.4728 mM/min、7.557 mM，单位与坐标轴不符，已按 1/v(min/nmol)、1/[S](1/μM) 更正。","opts":[],"printed_answer":""},{"id":"o043","subj":"880","chap":"第五章 酶","type":"简答","years":["16","21"],"q":"葡萄糖-6-磷酸脱氢酶在大肠杆菌的制备 \n（1）该技术属于酶技术的哪个方面，操作步骤是什么？\n（2）用什么方法可以分离纯化酶？\n（3）在测定酶的活性方面时，需要测定哪些特征常数？","points":[{"k":"归属基因工程","t":"属酶技术中基因工程（酶基因的克隆与表达）这一方面，即用重组菌大量生产目的酶。"},{"k":"五步操作","t":"切（取得目的基因）→连（与质粒载体连接）→转（导入大肠杆菌）→筛（筛选正确表达的菌株）→产（扩大培养、诱导表达）。"},{"k":"纯化四依据","t":"按分子大小（凝胶过滤、透析）、电荷（离子交换）、溶解度（硫酸铵盐析）、亲和力（亲和层析）分离；加 His 标签可用镍柱一步纯化。"},{"k":"测活性常数","t":"需测酶活力与比活力、Km 与 Vmax、最适 pH 与最适温度、辅因子需求，以及分子量与等电点（用于鉴定纯度）。"}],"note":"","opts":[],"printed_answer":""},{"id":"o044","subj":"880","chap":"第五章 酶","type":"简答","years":["19"],"q":"给出酶的相对分子质量、等电点，至少写出三种方法分离提纯","points":[{"k":"按分子大小","t":"Mr 不同：透析与超滤、密度梯度离心、凝胶过滤（分子排阻层析）。"},{"k":"按溶解度","t":"等电点沉淀与 pH 控制（pI 处溶解度最低）、蛋白质的盐溶与盐析、有机溶剂分级沉淀。"},{"k":"按电荷分离","t":"pI 不同：离子交换层析、电泳（聚丙烯酰胺凝胶电泳、毛细管电泳）、等电聚焦、层析聚焦。"},{"k":"按亲和力","t":"亲和层析、共价层析、疏水作用层析、羟磷灰石选择性吸附层析，以及 HPLC 与 FPLC。"}],"note":"","opts":[],"printed_answer":""},{"id":"o045","subj":"880","chap":"第五章 酶","type":"简答","years":["22"],"q":"一酶分子抑制剂，如何确定是可逆抑制剂还是不可逆抑制剂","points":[{"k":"透析除抑制剂","t":"用透析、超滤或充分稀释把抑制剂除去后再测活性：活性可以恢复者为可逆抑制，不能恢复者为不可逆抑制。"},{"k":"结合方式","t":"可逆抑制以非共价方式结合、存在酶-抑制剂解离平衡；不可逆抑制多以共价键牢固结合或修饰必需基团，酶分子被永久失活。"},{"k":"动力学佐证","t":"不同抑制剂浓度下作 v-[E] 图：可逆抑制的表观活性随抑制剂浓度下降但有效酶量不变，不可逆抑制使有效酶量减少、需更多酶才能达到同一 Vmax。"}],"note":"","opts":[],"printed_answer":""},{"id":"o046","subj":"880","chap":"第五章 酶","type":"简答","years":["22"],"q":"根据题设条件计算酶活的提取率和纯化倍数","points":[{"k":"比活力口径","t":"比活力＝总活力（U）÷ 总蛋白（mg），单位 U/mg；总活力＝比活力×总蛋白，总蛋白＝蛋白浓度×总体积。"},{"k":"提取率列式","t":"提取率（回收率）＝纯化后总活力 ÷ 粗酶液总活力 ×100%，反映酶的总量回收程度。"},{"k":"纯化倍数列式","t":"纯化倍数＝纯化后比活力 ÷ 粗酶液比活力，反映单位蛋白中酶活提高的倍数。"},{"k":"分步列表求算","t":"按「体积—蛋白浓度—总蛋白—总活力—比活力—回收率—纯化倍数」逐行列表，每一步与上一步及原始粗酶液比较，回收率逐级下降、纯化倍数逐级上升。"}],"note":"原卷题设的各步体积、蛋白浓度、酶活测定值缺失（旧答案亦记「不记得条件」），此处给通式与算法；考试时按卷面数据代入即可。","opts":[],"printed_answer":""},{"id":"o047","subj":"880","chap":"第七章 核酸","type":"名词解释","years":["12"],"q":"Tm","points":[{"k":"定义","t":"DNA 的热变性温度，即加热使双螺旋结构解体一半（增色效应达到最大增量一半）时的温度，又称解链温度，用 Tm 表示。"},{"k":"与GC正相关","t":"G＋C 含量越高，GC 对为三氢键、碱基堆积力强，Tm 越高；经验式 Tm＝69.3＋0.41×（G＋C）%，GC 每增 1%，Tm 约升 0.4 ℃。"},{"k":"数值与应用","t":"一般 DNA 的 Tm 在 70~85 ℃；可用于估算碱基组成、指导 PCR 退火温度与分子杂交的严谨性。"}],"note":"","opts":[],"printed_answer":""},{"id":"o048","subj":"880","chap":"第七章 核酸","type":"名词解释","years":["12"],"q":"减色效应","points":[{"k":"定义","t":"变性 DNA 分子复性重新形成双螺旋结构时，其 260 nm 紫外吸收值降低的现象，是增色效应的逆过程。"},{"k":"机理","t":"复性后碱基重新堆叠、隐蔽于螺旋内侧，碱基间电子相互作用减弱，故吸光度下降。"},{"k":"应用","t":"可据 A260 的回落程度监测复性进程、判断杂交与退火是否充分；测浓度须在双链状态下进行。"}],"note":"","opts":[],"printed_answer":""},{"id":"o049","subj":"880","chap":"第七章 核酸","type":"名词解释","years":["13","15"],"q":"增色效应（hyperchromic effect）","points":[{"k":"定义","t":"DNA 在变性解链过程中，由于碱基中的共轭双键被暴露出来，使 DNA 在 260 nm 波长处的紫外吸光值增加，此现象称增色效应。"},{"k":"结构基础","t":"天然双螺旋中碱基堆积、共轭双键被屏蔽；解链后碱基外露，对 260 nm 紫外光的吸收随之升高。"},{"k":"补：应用","t":"A260 的升幅可反映解链程度（解链曲线），是判断 DNA 变性、复性及是否降解的常用指标。"}],"note":"口径：依据《真题分类》资料原文；资料只有定义，结构基础与末点应用为按教材口径扩展。原答案中「A260 升高 25%~40%」资料未载，未写入。","opts":[],"printed_answer":"","ref":true},{"id":"o050","subj":"880","chap":"第七章 核酸","type":"名词解释","years":["19"],"q":"DNA 变性","points":[{"k":"概念定义","t":"DNA 双链碱基对间的氢键断裂、碱基堆积力被破坏，双链解成单链，天然构象与理化性质改变，但不涉及一级结构（共价键）的改变。"},{"k":"变性因素","t":"加热、极端 pH、有机试剂（甲醇、乙醇、尿素、甲酰胺）、低离子强度等凡能破坏双螺旋稳定的因素均可引起变性。"},{"k":"性质改变","t":"260 nm 增色效应、黏度下降、沉降系数增大、旋光性改变、生物活性丧失；条件撤除后缓慢冷却可复性。"}],"note":"资料无对应原答案，按教材口径。资料该条为「DNA 复性」，问的是复性过程，与本题「DNA 变性」不是同一题。","opts":[],"printed_answer":"","ref":false},{"id":"n0560","subj":"880","chap":"第七章 核酸","type":"简答","years":["12","21"],"q":"Tm 值高低与 G+C 有关。","points":[{"k":"Tm定义","t":"DNA 变性过程中紫外吸收增加值达到最大值的 50% 时所对应的温度称解链温度（Tm），此时 DNA 分子内 50% 的双链结构被解开；Tm 受分子大小与类型、溶液离子强度和 G-C 含量影响。"},{"k":"G-C含量","t":"G-C 碱基对之间有 3 个氢键，更有利于 DNA 的稳定，故 G-C 含量越高 Tm 越高。"},{"k":"离子强度","t":"离子强度低时不能有效屏蔽 DNA 链中磷酸基的负电性，磷酸基间斥力加大、双链不稳，故离子强度升高则 Tm 升高。"},{"k":"核酸类型与长度","t":"双链 RNA 比双链 DNA 更稳定，Tm 更高；一定范围内核酸分子越长，Tm 越高。"},{"k":"经验公式","t":"Tm = 81.5℃＋16.6 lg[Na⁺]＋0.41(%G+C)；如 [Na⁺]＝0.1 mol/L、G+C 为 43% 时，Tm = 81.5－16.6＋17.63 = 82.53℃。"}],"note":"口径：依据《真题分类》资料原文，公式取原文的 81.5＋16.6 lg[Na⁺]＋0.41(%G+C)（未采用常见的 69.3 式）。","opts":[],"printed_answer":"","ref":true},{"id":"o052","subj":"880","chap":"第七章 核酸","type":"简答","years":["12","21"],"q":"设计 DNA 半保留复制的方案","points":[{"k":"15N预标记","t":"先将大肠杆菌放在以 15NH4Cl 为唯一氮源的培养基中生长多代，使几乎所有 DNA 都被 15N 标记（重 DNA 密度约 1.72 g/cm³）。"},{"k":"转入14N培养","t":"把细菌洗后移到只含 14NH4Cl 的培养基中继续培养，按代时（约 20 min）定时取样。"},{"k":"裂解与离心","t":"用十二烷基硫酸钠（SDS）裂解细胞，裂解液与 CsCl 混匀，140000 g 密度梯度离心 20 h，紫外光下观察区带。"},{"k":"各代区带","t":"0 代只见一条重带；第 1 代只见一条介于两者之间的中间带（约 1.7 g/cm³），重带消失；第 2 代中间带与轻带各占一半；此后中间带渐弱、轻带渐强，始终不出现新带。"},{"k":"结论","t":"子代 DNA 一条链来自亲代 15N 链、一条为新合成的 14N 链，且按 2ⁿ 比例分配，证实半保留复制。"}],"note":"","opts":[],"printed_answer":""},{"id":"o053","subj":"880","chap":"第七章 核酸","type":"简答","years":["13"],"q":"sanger 双脱氧链终止法原理","points":[{"k":"ddNTP终止","t":"2′,3′-双脱氧核苷三磷酸（ddNTP）的脱氧核糖 3′ 位少一个羟基，不能同后续 dNTP 形成磷酸二酯键，一旦掺入 DNA 合成立即终止。"},{"k":"四组反应体系","t":"把待测序模板分成四组，每组含四种 dNTP（其中一种用放射性同位素标记）、引物、DNA 聚合酶，并按一定比例各加一种 ddNTP（ddATP、ddGTP、ddCTP、ddTTP）。"},{"k":"浓度控片段","t":"控制 ddNTP 浓度，即可在每管中合成以共同引物为 5′ 端、以某一双脱氧核苷酸为 3′ 端的一系列长度不等的片段，片段长度就代表相应核苷酸的位置。"},{"k":"电泳读序","t":"反应终止后各组样品分四个泳道、用含变性剂的 PAGE 电泳分离，从放射自显影图谱按各片段 3′ 端的双脱氧核苷酸直接读出 DNA 序列。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o054","subj":"880","chap":"第七章 核酸","type":"简答","years":[],"q":"如何测定核酸含量","points":[{"k":"紫外吸收法","t":"核酸在 260 nm 有最大吸收且与浓度成正比：A260＝1 相当于双链 DNA 50 μg/mL、单链 DNA 33 μg/mL、RNA 40 μg/mL，最常用、可无损检测。"},{"k":"定磷法","t":"核酸含磷量约 9.5%，样品经消化后测定无机磷，再由磷量推算核酸总量，适用于较纯制品。"},{"k":"化学显色法","t":"DNA 用二苯胺法（沸水浴显蓝色，595~600 nm 比色）；RNA 用地衣酚法（显绿色，670 nm），两法各有专一性并可区分 DNA 与 RNA。"},{"k":"荧光与电泳","t":"荧光染料（Hoechst 33258 测 DNA、溴化乙锭等）结合后荧光强度与含量成正比，灵敏度可达 ng 级；琼脂糖电泳结合凝胶成像可同时判断含量与完整性。"}],"note":"旧答案主体写的是蛋白质污染检测与考马斯亮蓝法测蛋白，与题干「如何测定核酸含量」不对应，此处按题干重写；蛋白部分见 o055。","opts":[],"printed_answer":""},{"id":"o055","subj":"880","chap":"第七章 核酸","type":"简答","years":["20"],"q":"如何判断一 DNA 样品中是否混入了蛋白质，若含有蛋白质，则说明如何检测 DNA 含量 \n和蛋白质含量，写出原理和步骤","points":[{"k":"A260/A280初判","t":"纯 DNA 的 A260/A280 约为 1.8（RNA 约 2.0）；比值明显偏低（如＜1.6）提示蛋白质污染，偏高提示 RNA 污染。"},{"k":"双缩脲佐证","t":"取样加双缩脲试剂，出现紫色即含肽键，可定性证实混有蛋白质；也可用考马斯亮蓝快速检出。"},{"k":"DNA定量","t":"紫外法：A260＝1 约相当于 50 μg/mL 双链 DNA，浓度＝A260×50×稀释倍数；亦可用二苯胺法显蓝色专一测 DNA。"},{"k":"蛋白定量","t":"考马斯亮蓝 G-250 法：酸性下染料经疏水作用与蛋白结合，最大吸收由 465 nm 移至 595 nm，溶液由棕黑变蓝，A595 与蛋白浓度成正比；先以 BSA 做标准曲线，再据 A595 反算含量。"},{"k":"电泳查完整性","t":"琼脂糖凝胶电泳观察有无降解拖尾与 RNA 条带，判断 DNA 完整性。"}],"note":"","opts":[],"printed_answer":""},{"id":"o056","subj":"880","chap":"第九章 生物膜","type":"名词解释","years":["19"],"q":"生物膜","points":[{"k":"定义","t":"细胞质膜与细胞内膜系统（核膜、内质网、高尔基体、溶酶体、线粒体膜等）的统称，是由脂质、蛋白质和糖类组装成的薄膜体系，厚约 7~8 nm。"},{"k":"组成与功能","t":"以磷脂双分子层为骨架，镶嵌整合蛋白与外周蛋白，外表面连糖链；是物质运输、能量转换、信号转导与细胞识别的结构基础。"},{"k":"两大特征","t":"结构上具流动性（脂与蛋白可侧向运动）和不对称性（脂、蛋白、糖两侧分布不同），功能上具选择透过性。"}],"note":"","opts":[],"printed_answer":""},{"id":"o057","subj":"880","chap":"第九章 生物膜","type":"简答","years":["18"],"q":"生物膜的组成与特征","points":[{"k":"膜脂三类","t":"①磷脂：以甘油磷脂为主（磷脂酰胆碱、磷脂酰乙醇胺）；②鞘脂：以鞘糖脂为主（脑苷脂、神经节苷脂等）；③固醇：动物质膜主要含胆固醇，植物质膜含谷固醇等植物固醇，细菌细胞一般不含固醇。"},{"k":"膜蛋白三类","t":"蛋白质是膜功能的主要体现者，功能复杂的膜（肝细胞膜、叶绿体膜）含量高、功能简单的膜（神经元髓鞘）含量低；按与膜脂的连接方式分外周（周边）膜蛋白、整合（内在）膜蛋白、脂锚定膜蛋白。"},{"k":"膜糖与糖萼","t":"糖质主要以寡糖-蛋白质复合体形式存在，构成糖萼（细胞外壳），主要参与信息的识别功能。"},{"k":"流动性与骨架","t":"生物膜可看成蛋白质在双层脂分子中的二维溶液；磷脂双分子层为基本骨架，极性头朝水相、非极性尾相对，在水相中自发形成封闭膜系统，为细胞与细胞器的生理活动提供界面和相对稳定的环境。"},{"k":"不对称性","t":"蛋白质以不同方式镶嵌或结合于表面，其类型、数量与分布的不对称及与脂分子的协同作用，赋予生物膜不同的特性与功能：利于物质选择运输，提供细胞识别位点和多种酶的结合位点。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o058","subj":"880","chap":"第九章 生物膜","type":"简答","years":["13"],"q":"流体镶嵌模型（写出结构、功能、应用）","points":[{"k":"模型要点","t":"生物膜以连续的磷脂双分子层为骨架，球状蛋白以不同深度镶嵌、贯穿或附着于脂双层，脂层与蛋白均可运动，故称流动镶嵌模型。"},{"k":"膜的流动性","t":"脂分子能在所在单层内迅速侧向扩散，很少翻转至另一层；蛋白分子也能水平扩散，膜整体呈液晶态。"},{"k":"蛋白结合方式","t":"分内嵌（整合）蛋白与外周蛋白，分别以疏水作用插入脂双层、以静电和离子键附着于膜表面。"},{"k":"糖链朝外","t":"糖蛋白的糖链远多于糖脂的糖链，且无论与蛋白还是与脂结合，糖链一律伸向质膜外表面。"},{"k":"功能与应用","t":"解释物质跨膜运输、信号转导、细胞识别与膜融合；指导脂质体载药、靶向给药与人工膜、生物传感器的设计。"}],"note":"","opts":[],"printed_answer":""},{"id":"o059","subj":"880","chap":"第十章 糖酵解 糖异生","type":"名词解释","years":["10"],"q":"底物磷酸化","points":[{"k":"概念定义","t":"物质在生物氧化过程中因脱氢、脱水使能量在分子内部重新分布，生成含高能键的化合物，其高能磷酸基可直接转移给 ADP（GDP）生成 ATP（GTP）的过程。"},{"k":"典型实例","t":"①甘油酸-1,3-二磷酸→甘油酸-3-磷酸＋ATP；②磷酸烯醇式丙酮酸→丙酮酸＋ATP；③琥珀酰 CoA→琥珀酸＋GTP。"},{"k":"生理意义","t":"不依赖呼吸链和氧，缺氧时仍能产能；是糖酵解净得 2 ATP 的唯一方式，TCA 中生成 1 GTP。"}],"note":"资料无对应原答案，按教材口径。资料该条为「氧化磷酸化」，与本题「底物磷酸化」不是同一概念。","opts":[],"printed_answer":"","ref":false},{"id":"o060","subj":"880","chap":"第十章 糖酵解 糖异生","type":"名词解释","years":["12"],"q":"糖异生","points":[{"k":"定义","t":"由非糖物质（丙酮酸、乳酸、甘油、生糖氨基酸等）转变为葡萄糖和糖原的过程。"},{"k":"部位与原料","t":"主要在肝，其次在肾；全过程在胞质与线粒体完成，原料为乳酸、甘油、生糖氨基酸及 TCA 中间物。"},{"k":"关键酶与意义","t":"丙酮酸羧化酶、磷酸烯醇式丙酮酸羧激酶、果糖二磷酸酶-1、葡萄糖-6-磷酸酶；维持空腹血糖、回收乳酸、调节酸碱平衡。"}],"note":"","opts":[],"printed_answer":""},{"id":"o061","subj":"880","chap":"第十章 糖酵解 糖异生","type":"名词解释","years":["19"],"q":"糖酵解","points":[{"k":"定义","t":"糖酵解途径指糖原或葡萄糖分子经 10 步酶促反应分解至生成丙酮酸的阶段，全过程在胞质进行、不需氧，是体内糖代谢的主要途径。"},{"k":"能量","t":"每分子葡萄糖净生成 2 ATP、2 NADH（由糖原起始则为 3 ATP）；含 2 个底物水平磷酸化位点。"},{"k":"意义","t":"是有氧氧化的前段；缺氧时以乳酸为终产物供能；并为脂肪、氨基酸代谢提供中间物。"}],"note":"","opts":[],"printed_answer":""},{"id":"o062","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":["11"],"q":"请结合生物学原理分析，为什么人在剧烈运动之后会感到酸痛，为什么一段时间后，酸痛现象会消失","points":[{"k":"乳酸堆积","t":"剧烈运动时肌肉供氧不足，丙酮酸不能彻底氧化，且为再生 NAD⁺ 维持糖酵解，被 NADH 还原为乳酸；生成速度超过清除速度而堆积。"},{"k":"酸中毒致痛","t":"乳酸堆积使局部 pH 下降、组织酸中毒，抑制磷酸果糖激酶并使肌浆网钙泵受损，肌肉收缩受阻、血流不畅，导致酸痛与疲惫。"},{"k":"乳酸清除","t":"运动停止后乳酸在线粒体内彻底氧化为 CO₂ 和 H₂O；或经血液运至肝，在肝内氧化为丙酮酸后经糖异生生成葡萄糖，再运回肌肉利用（Cori 循环）。"},{"k":"恢复消失","t":"乳酸被清除、局部 pH 回升、肌细胞自身修复后酸痛消失，一般需数小时至 2~3 天。"}],"note":"","opts":[],"printed_answer":""},{"id":"o063","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":["12"],"q":"EMP 与糖异生有差异的酶，其催化反应","points":[{"k":"葡萄糖与6-磷酸葡萄糖","t":"糖酵解：葡萄糖＋ATP —己糖激酶/Mg²⁺→ 6-磷酸葡萄糖＋ADP＋H⁺；糖异生：6-磷酸葡萄糖＋H₂O —葡萄糖-6-磷酸酶→ 葡萄糖＋Pi。"},{"k":"果糖双磷酸对","t":"糖酵解：6-磷酸果糖＋ATP —磷酸果糖激酶（PFK）/Mg²⁺→ 1,6-二磷酸果糖＋ADP＋H⁺；糖异生：1,6-二磷酸果糖＋H₂O —果糖二磷酸酶→ 6-磷酸果糖＋Pi。"},{"k":"PEP与丙酮酸","t":"糖酵解：磷酸烯醇式丙酮酸＋ADP —丙酮酸激酶/Mg²⁺→ 丙酮酸＋ATP；糖异生需两步：丙酮酸＋CO₂＋ATP＋H₂O —丙酮酸羧化酶/生物素→ 草酰乙酸＋ADP＋Pi＋2H⁺，草酰乙酸＋GTP —PEP 羧激酶→ 磷酸烯醇式丙酮酸＋GDP＋CO₂。"},{"k":"三步不可逆需绕行","t":"糖异生并非糖酵解的简单逆转，上述三步反应的 ΔG 很负、生理上不可逆，必须由不同的酶催化迂回绕行，故两途径的酶系与调控各不相同。"}],"note":"口径：依据《真题分类》资料原文；该资料题（6 分）只列三处差异酶，未再展开调控。","opts":[],"printed_answer":"","ref":true},{"id":"o064","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":["18"],"q":"糖酵解的三大步骤（限速步骤）","points":[{"k":"己糖激酶步","t":"葡萄糖＋ATP —己糖激酶/Mg²⁺→ 6-磷酸葡萄糖＋ADP＋H⁺；受 6-磷酸葡萄糖反馈抑制（ATP 高时亦抑制），无机磷酸、柠檬酸可激活。"},{"k":"果糖激酶步","t":"6-磷酸果糖＋ATP —磷酸果糖激酶（PFK）/Mg²⁺→ 1,6-二磷酸果糖＋ADP＋H⁺；受 AMP、ADP、6-磷酸果糖（前馈）激活，2,6-二磷酸果糖为强激活剂；受高浓度 ATP、H⁺、柠檬酸抑制，是最强的限速步。"},{"k":"丙酮酸激酶步","t":"磷酸烯醇式丙酮酸＋ADP —丙酮酸激酶/Mg²⁺→ 丙酮酸＋ATP；受 1,6-二磷酸果糖、磷酸烯醇式丙酮酸、高浓度葡萄糖激活，受高浓度 ATP、长链脂肪酸、乙酰 CoA、丙氨酸抑制。"}],"note":"口径：依据《真题分类》资料原文（原文末尾衍字「是是」已剔除）。资料把 ATP 列为己糖激酶激活剂、ADP 列为抑制剂，与教材口径相反，已按「6-磷酸葡萄糖、ATP 为抑制剂」写；「最强限速步」为教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"o065","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":["18","19"],"q":"6-磷酸葡萄糖作为糖代谢的枢纽，说明它参与哪些糖代谢过程？","points":[{"k":"三条来源","t":"①葡萄糖经己糖激酶（肝为葡萄糖激酶）磷酸化；②糖原分解经 1-磷酸葡萄糖转变为 6-磷酸葡萄糖；③糖异生由乳酸、甘油、生糖氨基酸生成。"},{"k":"去路一氧化","t":"经糖酵解、有氧氧化生成丙酮酸→乙酰 CoA 进入 TCA；缺氧时生成乳酸。"},{"k":"去路二戊糖","t":"经磷酸戊糖途径生成 5-磷酸核糖与 NADPH，供核苷酸合成与还原性合成反应。"},{"k":"去路三糖原","t":"6-磷酸葡萄糖→1-磷酸葡萄糖→UDPG，作为糖原合成的供体贮存能量。"},{"k":"去路四释糖","t":"肝、肾含葡萄糖-6-磷酸酶可水解成葡萄糖入血；肌肉缺此酶，故肌糖原不能直接补充血糖。"}],"note":"","opts":[],"printed_answer":""},{"id":"o066","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":["17","21"],"q":"EMP 途径中间产物磷酸化的重要作用","points":[{"k":"活化底物","t":"磷酸化提高中间产物的自由能，使其处于活化状态，更易被相应酶识别与催化，降低后续反应的活化能。"},{"k":"锁在胞内","t":"引入磷酸基使分子带负电荷，不能自由通过细胞膜，防止中间产物逸出，保证 EMP 连续单向进行。"},{"k":"形成高能键","t":"甘油醛-3-磷酸经脱氢并磷酸化生成甘油酸-1,3-二磷酸，其酰基磷酸键水解自由能高，是底物水平磷酸化的直接供体。"},{"k":"供能与偶联","t":"甘油酸-1,3-二磷酸与磷酸烯醇式丙酮酸的高能磷酸基转给 ADP 生成 ATP，使 EMP 净产 2 ATP；磷酸基还可作为调节信号与其他代谢途径相连接。"}],"note":"旧答案写成了「底物水平磷酸化」的定义，与题干所问「中间产物磷酸化的重要作用」有偏差，此处按题干作答。","opts":[],"printed_answer":""},{"id":"o067","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":["20"],"q":"EMP 途径中的三个限速酶及其活性调节物质有哪些？所参与的详细反应步骤","points":[{"k":"己糖激酶","t":"葡萄糖＋ATP —己糖激酶（肝为葡萄糖激酶）/Mg²⁺→ 6-磷酸葡萄糖＋ADP＋H⁺；受 6-磷酸葡萄糖反馈抑制，无机磷酸、柠檬酸可激活，胰岛素诱导合成。"},{"k":"磷酸果糖激酶","t":"6-磷酸果糖＋ATP —PFK-1/Mg²⁺→ 1,6-二磷酸果糖＋ADP＋H⁺；AMP、ADP、果糖-2,6-二磷酸激活，高 ATP、柠檬酸、H⁺抑制。"},{"k":"丙酮酸激酶","t":"磷酸烯醇式丙酮酸＋ADP —丙酮酸激酶/Mg²⁺→ 丙酮酸＋ATP；1,6-二磷酸果糖与高浓度葡萄糖激活，高 ATP、长链脂肪酸、乙酰 CoA、丙氨酸抑制。"},{"k":"三步即调控点","t":"三步均为不可逆的放能反应，故成为限速步骤；胰高血糖素、胰岛素通过共价修饰与酶量变化对三者进行整体调节。"}],"note":"","opts":[],"printed_answer":""},{"id":"o068","subj":"880","chap":"第十一章 柠檬酸循环","type":"简答","years":["17"],"q":"TCA 为什么是糖，脂肪，核酸，蛋白质的枢纽？糖，脂肪，核酸，蛋白质各类共同代谢的中间产物，相互联系渠道","points":[{"k":"核心分解途径","t":"TCA 是所有需氧生物的核心分解代谢途径，是糖类、脂肪酸、氨基酸等各种燃料分子完全氧化必需经历的途径，是机体获取能量的主要方式。"},{"k":"三大物质入口","t":"TCA 是乙酰 CoA 最终氧化成 CO₂ 和 H₂O 的途径：糖的碳骨架可生成乙酰 CoA 进入；脂肪的甘油经糖酵解生成丙酮酸再转乙酰 CoA，脂肪酸经 β-氧化直接生成乙酰 CoA；蛋白质的氨基酸脱氨后碳骨架进入 TCA。"},{"k":"合成前体来源","t":"中间产物可转成草酰乙酸经糖异生生成葡萄糖，或分解成甘油与乙酰 CoA 而合成脂肪；也可作氨基酸碳骨架，经转氨作用合成多种氨基酸。"},{"k":"两用代谢途径","t":"既承担分解又提供合成前体，故 TCA 为一种两用代谢途径，是代谢反应的核心通路、糖脂蛋白质相互转变的枢纽。"},{"k":"三个枢纽物质","t":"6-磷酸葡萄糖、丙酮酸、乙酰辅酶 A 是四大类物质相互转化中最关键的三个中间代谢物。"},{"k":"相互转化渠道","t":"糖→脂肪：酵解中间产物生成甘油与乙酰 CoA，再合成脂肪；糖→蛋白质：经酵解与 TCA 生成 α-酮酸骨架，转氨后合成氨基酸；糖→核酸：经戊糖磷酸途径氧化脱羧生成核糖，碱基部分需以氨基酸、CO₂ 为原料。"}],"note":"口径：依据《真题分类》资料原文。资料只列糖→脂、糖→蛋白质、糖→核酸三条渠道，缺脂肪、蛋白质向糖的反向渠道，未另行补写；原答案中的「三个枢纽物质」照资料原文保留。","opts":[],"printed_answer":"","ref":true},{"id":"o069","subj":"880","chap":"第十一章 柠檬酸循环","type":"简答","years":["20"],"q":"柠檬酸循环的三个调控酶、调控物质（激活剂/抑制剂），三步反应方程","points":[{"k":"柠檬酸合酶","t":"草酰乙酸＋乙酰 CoA＋H₂O → 柠檬酸＋CoA-SH；受 NADH、ATP、柠檬酸、琥珀酰 CoA 抑制，ADP、NAD⁺激活。"},{"k":"异柠檬酸脱氢酶","t":"异柠檬酸＋NAD⁺ → α-酮戊二酸＋CO₂＋NADH＋H⁺；受 ADP、Ca²⁺、NAD⁺激活，受 NADH、ATP、α-酮戊二酸抑制，是主要限速步。"},{"k":"α-KG脱氢酶系","t":"α-酮戊二酸＋CoA-SH＋NAD⁺ → 琥珀酰 CoA＋CO₂＋NADH＋H⁺；受 ADP、Ca²⁺、NAD⁺激活，受 NADH、ATP、琥珀酰 CoA 抑制。"},{"k":"调节规律","t":"能量不足（ADP/AMP 升高、NAD⁺/NADH 升高、Ca²⁺上升）时激活；ATP、NADH 及产物堆积时抑制。"}],"note":"","opts":[],"printed_answer":""},{"id":"o070","subj":"880","chap":"第十三章 磷酸戊糖途径、乙醛酸循环","type":"名词解释","years":["18"],"q":"乙醛酸循环","points":[{"k":"概念定义","t":"只存在于某些植物和微生物中，是柠檬酸循环的一种修改形式，即由 2 分子乙酰 CoA 净合成 1 分子草酰乙酸的过程，因产生重要中间代谢物乙醛酸而得名。"},{"k":"关键反应","t":"异柠檬酸裂解酶催化异柠檬酸直接分解为乙醛酸和琥珀酸，琥珀酸参与 TCA；乙醛酸与另一分子乙酰 CoA 生成苹果酸，进而氧化成草酰乙酸。"},{"k":"生理意义","t":"草酰乙酸经糖异生途径合成葡萄糖，使萌发种子中贮存的脂质转变为糖类，为种子生长提供充足的能源。"}],"note":"口径：依据《真题分类》资料原文。资料原文作「净合成 1 分子草酰乙酸」（题库旧稿写琥珀酸），按资料原文改正。","opts":[],"printed_answer":"","ref":true},{"id":"o071","subj":"880","chap":"第十四章 氧化磷酸化","type":"名词解释","years":["10"],"q":"呼吸链","points":[{"k":"定义","t":"有机物在体内氧化脱下的氢（电子）经一系列有严格排列顺序的传递体传递，最终与氧结合生成水，这样的递氢/递电子体系称呼吸链或电子传递链。"},{"k":"组成与部位","t":"由复合体Ⅰ（NADH 脱氢酶）、Ⅱ（琥珀酸脱氢酶）、Ⅲ（细胞色素 bc₁）、Ⅳ（细胞色素 c 氧化酶）及辅酶 Q、细胞色素 c 组成，定位于线粒体内膜。"},{"k":"功能","t":"电子逐级传递释放能量，泵出 H⁺ 形成跨膜质子梯度，驱动 ADP＋Pi 合成 ATP，是氧化磷酸化的结构基础。"}],"note":"","opts":[],"printed_answer":""},{"id":"o072","subj":"880","chap":"第十四章 氧化磷酸化","type":"名词解释","years":["12","19"],"q":"氧化磷酸化","points":[{"k":"定义","t":"在线粒体内膜上，代谢物脱下的电子经电子传递链传递给分子氧生成水，并偶联 ADP 和 Pi 生成 ATP 的过程。"},{"k":"地位","t":"是需氧生物生物氧化生成 ATP 的主要方式。"},{"k":"补：偶联部位与数量","t":"三个偶联部位在复合体Ⅰ、Ⅲ、Ⅳ；NADH 氧化 P/O 为 2.5，FADH₂ 氧化 P/O 为 1.5。"}],"note":"口径：依据《真题分类》资料原文；末点（偶联部位与 P/O）为按给定能量口径补充分点。","opts":[],"printed_answer":"","ref":true},{"id":"o073","subj":"880","chap":"第十四章 氧化磷酸化","type":"名词解释","years":["13"],"q":"磷氧比","points":[{"k":"定义","t":"氧化磷酸化中每消耗 1 mol 氧原子（即 1/2 mol O₂）所消耗的无机磷摩尔数，亦即生成的 ATP 摩尔数，记作 P/O。"},{"k":"数值","t":"NADH 经呼吸链氧化 P/O＝2.5；FADH₂（琥珀酸）氧化 P/O＝1.5；抗坏血酸等底物约为 1。"},{"k":"意义","t":"反映氧化与磷酸化的偶联效率，可判断解偶联程度，并用于计算底物彻底氧化的 ATP 产量。"}],"note":"","opts":[],"printed_answer":""},{"id":"o074","subj":"880","chap":"第十四章 氧化磷酸化","type":"简答","years":["10"],"q":"解偶联剂的作用","points":[{"k":"作用本质","t":"一类能抑制偶联磷酸化的化合物，使呼吸链电子传递所释放的能量不能用于 ADP 磷酸化而只能以热的形式散发，即解除氧化与磷酸化的偶联。"},{"k":"作用机制","t":"增大线粒体内膜对质子（H⁺）的通透性，消除跨膜质子梯度，使 ATP 合酶失去驱动力、活性受抑，因而无 ATP 生成。"},{"k":"常见种类","t":"典型代表为 2,4-二硝基苯酚（DNP），为脂溶性弱酸，可携 H⁺ 穿过内膜；氰化物属呼吸链抑制剂，不是解偶联剂。"},{"k":"生理产热意义","t":"解偶联剂不抑制电子传递，氧化释放的能量全部以热散发，是人体非战栗性产热的一种方式，寒冷条件下有利于保持体温恒定。"}],"note":"口径：依据《真题分类》资料原文。资料原文将氰化物列为解偶联剂，已更正：氰化物抑制细胞色素氧化酶、属呼吸链抑制剂；另补充 DNP 为脂溶性弱酸、可携 H⁺ 过膜这一机制细节。","opts":[],"printed_answer":"","ref":true},{"id":"o075","subj":"880","chap":"第十四章 氧化磷酸化","type":"简答","years":["22"],"q":"抗霉素 A 比鱼藤酮更有害的原因","points":[{"k":"作用位点不同","t":"鱼藤酮阻断复合体Ⅰ（NADH→CoQ）；抗霉素 A 阻断复合体Ⅲ中细胞色素 bc₁ 的电子传递。"},{"k":"鱼藤酮只断NADH","t":"FADH₂ 的电子经复合体Ⅱ→CoQ 绕过复合体Ⅰ，故鱼藤酮只封闭来自 NADH 的电子流，来自 FADH₂ 的电子仍可传递产能。"},{"k":"抗霉素A全断","t":"复合体Ⅲ是 NADH 与 FADH₂ 两条来路的共同通道，被封闭后所有电子都无法流向氧，氧化磷酸化全面停止。"},{"k":"毒性更强","t":"鱼藤酮仅部分抑制，细胞尚有 FADH₂ 通路供能；抗霉素 A 使细胞完全丧失氧化产能，故其毒性远大于鱼藤酮。"}],"note":"","opts":[],"printed_answer":""},{"id":"o076","subj":"880","chap":"第十五章 脂类代谢","type":"名词解释","years":["19"],"q":"酮体","points":[{"k":"定义","t":"脂肪酸 β-氧化生成的乙酰 CoA 在肝内转变而成的乙酰乙酸、β-羟丁酸和丙酮三种中间产物，统称酮体。"},{"k":"生成与利用","t":"肝线粒体生成但不能利用（缺琥珀酰 CoA 转硫酶），经血液运至肝外组织（脑、心、肾、肌肉）氧化利用，是肝输出脂类能源的形式。"},{"k":"临床意义","t":"正常血、尿仅含少量；饥饿、高脂低糖饮食、糖尿病时酮体生成过多，出现酮血症、酮尿，并可致酮症酸中毒。"}],"note":"","opts":[],"printed_answer":""},{"id":"o077","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["10"],"q":"糖尿病患者，标记的乙酰辅酶 A 在呼吸中是否存在","points":[{"k":"结论存在","t":"存在。标记的乙酰 CoA 最终仍经 TCA 氧化分解，可在呼吸链中检测到放射性。"},{"k":"草酰乙酸耗尽","t":"糖尿病患者不能贮存糖，糖异生加速，草酰乙酸被大量消耗，而草酰乙酸是乙酰 CoA 进入 TCA 的必需物质，故乙酰 CoA 不能正常进入 TCA 氧化。"},{"k":"转向合成酮体","t":"高浓度的乙酰 CoA 转向生成酮体，酮体供肝外组织利用。"},{"k":"肝外再利用","t":"酮体在肝外组织中转化成乙酰 CoA 和琥珀酸，琥珀酸再转化成草酰乙酸，使 TCA 循环恢复正常进行，乙酰 CoA 得以继续氧化。"}],"note":"口径：依据《真题分类》资料原文。题干所问「在呼吸中是否存在」，资料原文作「呼吸链中检测到」，按资料口径作答。","opts":[],"printed_answer":"","ref":true},{"id":"o078","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["12"],"q":"简述摄入糖量过多容易长胖的原因","points":[{"k":"碳源生成乙酰CoA","t":"过量葡萄糖经有氧氧化生成乙酰 CoA，后者是脂肪酸合成的直接原料，经乙酰 CoA 羧化酶生成丙二酰 CoA 后合成脂肪酸。"},{"k":"甘油骨架","t":"糖酵解中间物磷酸二羟丙酮经 3-磷酸甘油脱氢酶还原为 3-磷酸甘油，提供脂肪的甘油部分。"},{"k":"供氢与供能","t":"糖氧化经磷酸戊糖途径产生大量 NADPH 作还原力，TCA 与氧化磷酸化提供 ATP，满足脂肪酸合成的需要。"},{"k":"储备能力有限","t":"糖原储存总量有限，过量糖超出氧化供能与糖原储备能力后即转化为脂肪贮存，故摄糖过多易长胖。"}],"note":"","opts":[],"printed_answer":""},{"id":"o079","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["12"],"q":"脂肪酸合成途径，脂肪酸氧化途径异同点","points":[{"k":"相同点","t":"①均需酰基载体；②均为 4 步循环反应；③均需转运机制；④均以 2 个碳原子为单位增减；⑤16 碳均经 7 轮循环。"},{"k":"部位与转运","t":"合成在胞质溶胶，经柠檬酸-丙酮酸循环运出乙酰 CoA；β-氧化在线粒体基质，长链脂酰 CoA 靠肉碱载体系统进入。"},{"k":"反应类型相反","t":"合成：缩合—还原—脱水—还原，需 NADPH，属还原性合成；氧化：氧化—水合—氧化—硫解，生成 FADH₂ 与 NADH，属氧化分解。"},{"k":"方向与构型","t":"合成自甲基端向羧基端延长，β-羟酯为 D-构型，酰基载体为 ACP；氧化自羧基端向甲基端降解，β-羟酯为 L-构型，载体为辅酶 A。"},{"k":"能量与限速酶","t":"合成 16 碳软脂酸消耗 7 ATP 与 14 NADPH（约合 49 个 ATP 当量），限速酶为乙酰 CoA 羧化酶；氧化 16 碳净产 106 ATP，限速酶为肉碱脂酰转移酶Ⅰ。"}],"note":"","opts":[],"printed_answer":""},{"id":"o080","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["13"],"q":"脂肪酸 b-氧化和柠檬酸循环的相同点及不同点？","points":[{"k":"相同点","t":"两者均在线粒体进行，均含脱氢—水合—再脱氢的连续步骤，均生成 NADH 与 FADH₂ 进入呼吸链产能。"},{"k":"产物不同","t":"β-氧化把脂酰 CoA 降解为乙酰 CoA，不直接产生 CO₂、不直接生成 ATP；TCA 把乙酰 CoA 氧化为 CO₂，并生成 GTP（ATP）与大量还原当量。"},{"k":"衔接关系","t":"β-氧化是 TCA 的上游反应，为其提供底物乙酰 CoA；TCA 产能状态又通过 NADH/ATP 反馈调节 β-氧化速度。"}],"note":"","opts":[],"printed_answer":""},{"id":"o081","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["13"],"q":"过度饥饿呼出有异味的气体原因及相应反应","points":[{"k":"糖储备耗尽","t":"长期饥饿使肝糖原耗尽，肝糖异生加速以维持血糖，草酰乙酸被大量移去作为异生原料。"},{"k":"脂肪大量动员","t":"脂肪动员加强，脂肪酸 β-氧化生成大量乙酰 CoA；蛋白质分解也加强，为糖异生提供原料。"},{"k":"乙酰CoA转向","t":"草酰乙酸供应不足，乙酰 CoA 不能进入 TCA，转而缩合生成乙酰乙酸、β-羟丁酸和丙酮。"},{"k":"丙酮挥发异味","t":"丙酮具挥发性并有特殊气味，经肺呼出即为异味来源；血酮升高还可致酮症酸中毒。"}],"note":"","opts":[],"printed_answer":""},{"id":"o082","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["16","19"],"q":"解释为什么节食会导致酸中毒？","points":[{"k":"酮体大量生成","t":"节食使糖供给不足，脂肪大量动员，肝内脂肪酸 β-氧化生成大量乙酰 CoA，并转向酮体生成。"},{"k":"TCA受阻","t":"糖异生加速耗竭草酰乙酸，乙酰 CoA 不能与之缩合进入 TCA，只能生成乙酰乙酸、β-羟丁酸和丙酮。"},{"k":"酸性物质蓄积","t":"乙酰乙酸与 β-羟丁酸为有机酸，血中堆积使血液 pH 下降，超出缓冲与排酸能力即发生代谢性酮症酸中毒。"},{"k":"临床表现","t":"呼气烂苹果味、酮尿、脱水与电解质紊乱，严重时出现嗜睡甚至昏迷。"}],"note":"","opts":[],"printed_answer":""},{"id":"o083","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["16","17","21"],"q":"只吃脂类不吃糖会有什么症状？在长期缺糖的情况下，吃奇数碳还是偶数碳脂类好，为什么？","points":[{"k":"症状","t":"出现酮症、酮尿乃至酮症酸中毒：糖不足使草酰乙酸匮乏，乙酰 CoA 转向酮体，血酮升高、pH 下降，并伴乏力、脱水。"},{"k":"奇数碳更优","t":"奇数碳脂肪酸 β-氧化除生成乙酰 CoA 外，末轮还产生丙酰 CoA。"},{"k":"丙酰CoA生糖","t":"丙酰 CoA 经丙酰 CoA 羧化酶（生物素）→甲基丙二酰 CoA→琥珀酰 CoA 进入 TCA，生成草酰乙酸后经糖异生补糖，可缓解低血糖与酮症。"},{"k":"偶数碳局限","t":"偶数碳脂肪酸只生成乙酰 CoA，不能净补充 TCA 中间物、不能净生糖，长期缺糖更易酮症，故奇数碳更好。"}],"note":"","opts":[],"printed_answer":""},{"id":"o084","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["19","20"],"q":"1mol 软脂酸彻底氧化分解成 CO₂ 会产生多少 ATP？","points":[{"k":"列式","t":"净 ATP＝8×10（乙酰 CoA）＋7×1.5（FADH₂）＋7×2.5（NADH）－2（脂肪酸活化）。"},{"k":"分步产物","t":"16 碳软脂酸经 7 轮 β-氧化，生成 8 乙酰 CoA、7 FADH₂、7 NADH；每分子乙酰 CoA 经 TCA 与氧化磷酸化产 10 ATP；活化消耗 2 个高能磷酸键。"},{"k":"代入","t":"80＋10.5＋17.5－2＝106。"},{"k":"结论","t":"1 mol 软脂酸彻底氧化净生成 106 mol ATP。"}],"note":"","opts":[],"printed_answer":""},{"id":"o085","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["19"],"q":"什么是酮体？请说明过量酮体产生的原因及对机体有何危害？","points":[{"k":"定义","t":"β-氧化产生的乙酰 CoA 在肝内转变成的丙酮、乙酰乙酸和 β-羟丁酸，统称酮体，是肝向肝外输出脂类能源的形式。"},{"k":"过量原因","t":"长期饥饿、高脂低糖饮食、糖尿病时糖代谢紊乱，糖异生加速耗竭草酰乙酸，乙酰 CoA 不能进入 TCA 而转向大量生成酮体。"},{"k":"酮血症酮尿","t":"正常人血、尿仅含少量酮体；生成超过肝外组织利用能力时血酮升高形成酮血症，经肾排出形成酮尿。"},{"k":"危害","t":"酮体为酸性物质，可与 Na⁺、K⁺ 等阳离子结合随尿排出，扰乱体内 pH 与水盐代谢，引起酸中毒（血 pH 下降），严重时昏迷。"}],"note":"","opts":[],"printed_answer":""},{"id":"o086","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["18","20","21"],"q":"简述高等生物中乙酰辅酶 A 的代谢去路","points":[{"k":"进入TCA氧化","t":"与草酰乙酸缩合成柠檬酸进入 TCA，氧化为 CO₂ 和 H₂O 并产生大量能量，是主要去路。"},{"k":"合成脂肪酸","t":"在胞质经乙酰 CoA 羧化酶生成丙二酰 CoA，再由脂肪酸合酶合成脂肪酸，进而生成脂肪与磷脂。"},{"k":"合成胆固醇","t":"作为类固醇前体，经甲羟戊酸途径合成胆固醇，再衍生胆汁酸、类固醇激素与维生素 D₃。"},{"k":"生成酮体","t":"在肝线粒体生成乙酰乙酸、β-羟丁酸和丙酮，作为肝输出能源；此外乙酰 CoA 还可供蛋白质乙酰化修饰。"}],"note":"","opts":[],"printed_answer":""},{"id":"o087","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["21"],"q":"1mol 甘油彻底氧化可产生多少 ATP？ （胞液中的 NADH 通过 3-磷酸甘油途径穿梭）","points":[{"k":"列式","t":"净 ATP＝－1（甘油激酶）＋1.5（3-磷酸甘油脱氢的 NADH）＋1.5（3-磷酸甘油醛脱氢的 NADH）＋2（底物水平）＋12.5（丙酮酸入 TCA）。"},{"k":"分步","t":"甘油＋ATP→3-磷酸甘油→磷酸二羟丙酮（产 NADH）→经糖酵解至丙酮酸（再产 1 NADH、2 ATP）→丙酮酸氧化脱羧入 TCA 产 12.5 ATP。"},{"k":"代入","t":"－1＋1.5＋1.5＋2＋12.5＝16.5。"},{"k":"结论","t":"1 mol 甘油彻底氧化净生成 16.5 mol ATP（胞液 NADH 按 3-磷酸甘油穿梭计 1.5）。"}],"note":"旧答案把两个胞液 NADH 各按 2.5 计得 18.5，与题干明确指定的「3-磷酸甘油穿梭」口径（1.5）不符；按题设条件应为 16.5。","opts":[],"printed_answer":""},{"id":"o088","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["22"],"q":"1mol 十八碳甘油三酯完全氧化产生多少 ATP？","points":[{"k":"列式","t":"总 ATP＝甘油部分＋3×硬脂酸部分；硬脂酸＝9×10＋8×1.5＋8×2.5－2。"},{"k":"甘油部分","t":"－1＋1.5＋1.5＋2＋12.5＝16.5 ATP（胞液 NADH 按 3-磷酸甘油穿梭计 1.5）。"},{"k":"硬脂酸部分","t":"C18 经 8 轮 β-氧化生成 9 乙酰 CoA、8 FADH₂、8 NADH：90＋12＋20－2＝120 ATP，三分子共 360 ATP。"},{"k":"结论","t":"16.5＋360＝376.5 mol ATP；若按苹果酸-天冬氨酸穿梭则为 378.5，考场按题干指定的穿梭方式作答。"}],"note":"题干未指定穿梭方式时按 3-磷酸甘油穿梭（1.5）计，得 376.5；若指定苹果酸-天冬氨酸穿梭则为 378.5。","opts":[],"printed_answer":""},{"id":"o089","subj":"880","chap":"第十六章 氨基酸代谢","type":"名词解释","years":["13","16","19"],"q":"丙氨酸-葡萄糖循环","points":[{"k":"定义","t":"肌肉与肝之间以丙氨酸为氨和碳骨架的载体、把氨无毒运至肝并补充血糖的循环过程。"},{"k":"肌肉端","t":"运动时骨骼肌内糖分解生成的丙酮酸，与蛋白质分解释放的支链氨基酸等发生转氨基作用，丙酮酸生成丙氨酸并释放入血。"},{"k":"肝端","t":"丙氨酸随血入肝，经糖异生作用合成葡萄糖，再转运到骨骼肌。"},{"k":"补：生理意义","t":"既把肌肉的氨以无毒形式运至肝处理，又为肌肉补充葡萄糖，故称丙氨酸-葡萄糖循环。"}],"note":"口径：依据《真题分类》资料原文；末点（生理意义）为资料之外补充分点。","opts":[],"printed_answer":"","ref":true},{"id":"o090","subj":"880","chap":"第十六章 氨基酸代谢","type":"名词解释","years":["13"],"q":"γ-谷氨酰胺循环","points":[{"k":"定义","t":"小肠黏膜与肾小管以谷胱甘肽为载体转运氨基酸的跨膜循环，又称 Meister 循环（γ-谷氨酰基循环）。"},{"k":"转运与再生","t":"①γ-谷氨酰转移酶把谷胱甘肽的 γ-谷氨酰基转给胞外氨基酸，生成 γ-谷氨酰氨基酸进入细胞并释出氨基酸；②再经 γ-谷氨酰环化转移酶、5-氧脯氨酸酶等，耗 ATP 重新合成谷胱甘肽。"},{"k":"耗能与意义","t":"每转运 1 分子氨基酸消耗 3 分子 ATP，是氨基酸吸收的主要机制之一。"}],"note":"资料无对应原答案：资料同名条目的原文实际答的是谷氨酰胺的运氨作用（脑、肌中谷氨酸与游离氨合成谷氨酰胺，经血运至肝、肾再分解），与本词条所指 γ-谷氨酰基循环（Meister 循环，氨基酸跨膜吸收）不是同一概念，故按教材口径作答。","opts":[],"printed_answer":"","ref":false},{"id":"o091","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":["11"],"q":"请结合生物学原理分析，为什么牛吃的是草挤出来的却是奶？","points":[{"k":"纤维素被降解","t":"草中含大量纤维素，是由葡萄糖经 β-1,4 糖苷键相连而成的大分子同多糖；被牛吃入后在肠道经一些微生物分解成葡萄糖。"},{"k":"吸收运输入肝","t":"葡萄糖随即被肠道上皮绒毛细胞吸收，并经淋巴运输至肝脏。"},{"k":"碳骨架与转氨","t":"在肝脏中葡萄糖经糖酵解、三羧酸循环等途径转化成 20 种氨基酸的碳骨架，再通过转氨作用生成 20 种氨基酸，作为合成蛋白质的原料。"},{"k":"基因表达合成乳蛋白","t":"待相关基因表达时可产生相应 mRNA 并转运至细胞质基质，以 20 种氨基酸为原料、mRNA 为模板、借助 tRNA 解码，经核糖体合成牛奶所含的蛋白质，从而将草转变为牛奶。"}],"note":"口径：依据《真题分类》资料原文（原文为一段链式叙述，此处按四步拆分）。","opts":[],"printed_answer":"","ref":true},{"id":"o092","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":["10"],"q":"尿素循环和 TCA 的关系。","points":[{"k":"延胡索酸作纽带","t":"尿素循环中天冬氨酸不断被消耗而生成延胡索酸，延胡索酸可经三羧酸循环转为苹果酸，再氧化成草酰乙酸。"},{"k":"转氨再生天冬","t":"草酰乙酸与谷氨酸进行转氨基反应重新生成天冬氨酸，而谷氨酸又可由其他氨基酸把氨基转给 α-酮戊二酸生成，故各种氨基酸的氨基可借天冬氨酸的形式用于合成尿素。"},{"k":"三途径相互联系","t":"「天冬氨酸→精氨琥珀酸→延胡索酸→苹果酸→草酰乙酸→天冬氨酸」把尿素循环、TCA 循环和转氨基作用联系起来，故尿素循环的进行与 TCA、转氨作用密不可分。"},{"k":"二者的区别","t":"氨基酸分解一般先脱氨基，脱下的氨经尿素循环以尿素形式排泄；脱氨后生成的碳骨架则进入 TCA 彻底氧化分解或转变成其他物质。"}],"note":"口径：依据《真题分类》资料原文（联系与区别两部分）。","opts":[],"printed_answer":"","ref":true},{"id":"o093","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":["13","21"],"q":"食物中含有丙氨酸但不含天冬氨酸，为什么能够检测到天冬氨酸？","points":[{"k":"非必需可自造","t":"天冬氨酸属非必需氨基酸，可经人体自身合成，故食物中不含也能在体内检测到。"},{"k":"转氨生丙酮酸","t":"丙氨酸经转氨作用脱氨，生成丙酮酸。"},{"k":"羧化补草酰乙酸","t":"丙酮酸通过添补反应，在丙酮酸羧化酶的催化下羧化生成草酰乙酸。"},{"k":"再转氨成天冬","t":"草酰乙酸再经转氨作用、接受谷氨酸的氨基，生成天冬氨酸。"},{"k":"乙酰CoA激活","t":"丙酮酸还可氧化脱羧生成乙酰 CoA，乙酰 CoA 是丙酮酸羧化酶的激活剂，可激活羧化酶合成更多天冬氨酸。"}],"note":"口径：依据《真题分类》资料原文（原文末尾的 OCR 页码脚注已剔除）。","opts":[],"printed_answer":"","ref":true},{"id":"o094","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":["17"],"q":"Ala 彻底代谢氧化分解产生多少 ATP？代谢过程是什么？","points":[{"k":"联合脱氨基","t":"丙氨酸经 ALT 把氨基转给 α-酮戊二酸，生成丙酮酸和谷氨酸，此步不产生 ATP。"},{"k":"谷氨酸脱氢","t":"谷氨酸经谷氨酸脱氢酶氧化脱氨，生成 1 mol NADH，按 2.5 计得 2.5 mol ATP。"},{"k":"丙酮酸脱氢","t":"丙酮酸经丙酮酸脱氢酶复合体氧化脱羧生成乙酰 CoA，产 1 mol NADH，计 2.5 mol ATP。"},{"k":"三羧酸循环","t":"乙酰 CoA 进入 TCA，每轮产 3 NADH、1 FADH₂、1 GTP，即 7.5＋1.5＋1＝10 mol ATP。"},{"k":"合计十五","t":"总量＝2.5＋2.5＋10＝15 mol ATP/mol 丙氨酸（按 NADH 2.5、FADH₂ 1.5、GTP 1 计）。"}],"note":"","opts":[],"printed_answer":""},{"id":"o095","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":["21"],"q":"正常人血液中含有所有用于蛋白质合成的氨基酸，但不是等浓度，其中 Ala 和 Gln 浓度较其他得高很多，为什么？","points":[{"k":"氨须载体运输","t":"肌肉等外周组织产生的 NH₃ 有毒且不能直接入血，须以氨基酸形式经血液运至肝，丙氨酸、谷氨酰胺即主要载体。"},{"k":"丙氨酸葡萄糖循环","t":"肌肉把氨基交给丙酮酸生成 Ala 入血，肝摄取后脱氨合成尿素，碳骨架异生为葡萄糖回肌肉，构成丙氨酸-葡萄糖循环。"},{"k":"谷氨酰胺运氨","t":"脑与肌肉的氨与谷氨酸结合成无毒的 Gln，易透过细胞膜运输，到肝、肾经谷氨酰胺酶水解释放氨。"},{"k":"周转快故浓度高","t":"二者是氨的「中转站」，生成与去路都极快、血流量大，稳态浓度远高于其他氨基酸，但并非蛋白质合成的原料储备。"}],"note":"","opts":[],"printed_answer":""},{"id":"o096","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":["21"],"q":"根据下列反应回答问题。\n丙氨酸＋谷氨酸→α-酮戊二酸＋丙酮酸\n（1）写出上述酶促反应所需酶及辅酶\n（2）食物中富含 Ala，缺乏 Asp，可看不到缺乏 Asp 的症状，为什么","points":[{"k":"谷丙转氨酶","t":"（1）催化酶为丙氨酸氨基转移酶（ALT，旧称 GPT），催化 Ala 与 α-酮戊二酸之间的可逆转氨反应。"},{"k":"磷酸吡哆醛","t":"辅酶为磷酸吡哆醛（PLP），来自维生素 B₆，作为氨基的中间载体在酶与底物间传递氨基。"},{"k":"反应可逆","t":"反应可逆，正向生成丙酮酸和谷氨酸，是丙氨酸-葡萄糖循环的关键步骤；ALT 主要在肝内活性最高。"},{"k":"羧化生成草酰乙酸","t":"（2）Ala 转氨生成丙酮酸，丙酮酸经丙酮酸羧化酶（生物素、耗 ATP）羧化为草酰乙酸。"},{"k":"转氨即得天冬","t":"草酰乙酸再接受氨基即生成天冬氨酸；Asp 是非必需氨基酸，体内可合成，故食物缺 Asp 无缺乏症状。"}],"note":"","opts":[],"printed_answer":""},{"id":"o097","subj":"880","chap":"第十七章 核苷酸代谢","type":"简答","years":["13"],"q":"嘌呤和嘧啶的合成抑制剂为何有抗癌或抗病毒作用？","points":[{"k":"结构类似底物","t":"抑制剂多为抗代谢物，其结构类似嘌呤、嘧啶、核苷、叶酸或谷氨酰胺，可被误认为正常底物。"},{"k":"竞争抑制关键酶","t":"与正常底物竞争同一酶活性中心，抑制核苷酸合成途径的关键酶（如二氢叶酸还原酶、胸苷酸合成酶），使 dNTP 供应不足。"},{"k":"伪底物掺入核酸","t":"被磷酸化成核苷酸后掺入 DNA 或 RNA，形成异常核酸，造成链终止、错配或突变，影响核酸功能。"},{"k":"选择性杀伤","t":"肿瘤细胞与病毒感染的细胞增殖快、对核苷酸需求大，故被优先杀伤，正常细胞受影响相对小。"},{"k":"六巯基嘌呤例证","t":"6-巯基嘌呤经 HGPRT 转变为巯基嘌呤核苷酸，在核苷酸水平阻断 IMP 转变为 AMP、GMP，用于白血病。"}],"note":"","opts":[],"printed_answer":""},{"id":"o098","subj":"880","chap":"第十七章 核苷酸代谢","type":"简答","years":["21"],"q":"举例说明什么是核苷酸代谢物，并举例如应用","points":[{"k":"定义","t":"核苷酸抗代谢物是结构上与嘌呤、嘧啶、核苷或叶酸相似的化合物，能干扰核苷酸的合成与利用。"},{"k":"作用方式","t":"竞争性抑制核苷酸合成途径的关键酶，或作为伪底物掺入核酸，从而阻断 DNA、RNA 的合成。"},{"k":"嘌呤类似物","t":"6-巯基嘌呤抑制 IMP 转变为 AMP、GMP，用于白血病；别嘌呤醇抑制黄嘌呤氧化酶，治疗痛风。"},{"k":"嘧啶与叶酸类似物","t":"5-氟尿嘧啶抑制胸苷酸合成酶，用于消化道肿瘤；甲氨蝶呤抑制二氢叶酸还原酶，阻断 dTMP 合成。"},{"k":"核苷类似物","t":"阿糖胞苷抑制 DNA 聚合酶，抗白血病与抗病毒；此类药物多需经激酶磷酸化才具活性。"}],"note":"","opts":[],"printed_answer":""},{"id":"o099","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"名词解释","years":["13","16"],"q":"冈崎片段","points":[{"k":"定义","t":"DNA 复制时后随链上不连续合成形成的短 DNA 片段，因日本学者冈崎发现而得名；原核约 1000~2000 nt，真核约 100~200 nt。"},{"k":"生成与连接","t":"每个片段以 RNA 引物起始，沿 5'→3' 合成；随后 Pol Ⅰ 切除引物并填补缺口，DNA 连接酶封口，连成完整子链。"}],"note":"原答案后半段「b-回折/β-转角、第二个残基常为 Pro」与冈崎片段无关（属 β-转角内容），已删除。","opts":[],"printed_answer":""},{"id":"o100","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"名词解释","years":["16"],"q":"转座子","points":[{"k":"定义","t":"又称易位子、跳跃基因，是染色体 DNA 上可自主复制并在基因组内改变位置的一段 DNA 序列。"},{"k":"两端反向重复","t":"两端多为反向重复序列，中间编码转座酶；插入新位点后靶序列两侧产生正向重复。"},{"k":"转座效应","t":"插入可使基因失活或激活，引起突变与基因组重排，也是耐药基因在细菌间传播的载体。"}],"note":"","opts":[],"printed_answer":""},{"id":"o101","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"名词解释","years":["18"],"q":"半不连续复制","points":[{"k":"定义","t":"DNA 复制时前导链连续合成，后随链先分段合成冈崎片段再连接，一条连续、一条不连续，故称半不连续复制。"},{"k":"方向限制原因","t":"两条模板链反向平行，而 DNA 聚合酶只能沿 5'→3' 合成，后随链模板方向与复制叉相反，只能反向分段合成。"},{"k":"片段连接","t":"每个冈崎片段以 RNA 引物起始，Pol Ⅰ 切除引物并填补，DNA 连接酶封口成完整链。"}],"note":"","opts":[],"printed_answer":""},{"id":"o102","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"简答","years":["10","12"],"q":"简要说明什么是 DNA 的半保留复制和半不连续复制","points":[{"k":"半保留复制","t":"复制时两条链之间的氢键断裂、双链分开，各以一条链为模板合成新链，子代 DNA 一条链来自亲代、另一条为新合成，故称半保留复制。"},{"k":"半不连续复制","t":"复制时一条链连续合成、另一条链不连续合成，故称半不连续复制。"},{"k":"前导链连续","t":"两条母链反向平行，而 DNA 聚合酶只能按 5′→3′ 催化合成；前导链以 3′→5′ 的母链为模板，合成方向与复制叉前进方向一致，可连续合成。"},{"k":"冈崎片段连接","t":"后随链以 5′→3′ 的母链为模板，合成方向与复制叉前进方向相反，需先合成许多冈崎片段，再由 DNA 连接酶连接成完整长链。"}],"note":"口径：依据《真题分类》资料原文。资料该条未涉及 Meselson-Stahl 的 ¹⁵N 密度梯度实验，故删去旧稿中的实验证据，只保留资料内容。","opts":[],"printed_answer":"","ref":true},{"id":"o103","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"简答","years":["10"],"q":"09 年诺贝尔奖的端粒酶","points":[{"k":"含RNA的逆转录酶","t":"端粒酶是一种含有 RNA 链的逆转录酶，可利用自身所含 RNA 为模板合成 DNA 的端粒结构，负责延长修复细胞中因复制而缩短受损的端粒。"},{"k":"稳定染色体末端","t":"端粒可稳定染色体末端结构，防止染色体间末端连接。"},{"k":"补偿5端空缺","t":"最重要的是补偿后随链 5′端在去除 RNA 引物后造成的空缺。"},{"k":"决定细胞寿命","t":"端粒因多次复制受损后可引起细胞凋亡，因此端粒决定细胞寿命；端粒酶修复受损端粒，使细胞分裂次数增加、增殖能力增强。"},{"k":"分布与肿瘤","t":"正常人体组织中端粒酶活性被抑制，只有造血细胞、干细胞和生殖细胞中可测到活性；肿瘤细胞中被重新激活，可能参与细胞恶性转化导致癌症。"}],"note":"口径：依据《真题分类》资料原文。资料末尾另有「DNA 复制高度准确性」的补充内容，与本题无关，未收入。","opts":[],"printed_answer":"","ref":true},{"id":"o104","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"简答","years":["17"],"q":"DNA 复制所需要的酶及其它们的作用和相关物质","points":[{"k":"聚合酶Ⅲ主力","t":"原核 Pol Ⅲ 是复制主力酶，具 5'→3' 聚合活性和 3'→5' 外切校对活性，无 5'→3' 外切活性；真核主力为 Pol δ、Pol ε。"},{"k":"聚合酶Ⅰ切引物","t":"原核 Pol Ⅰ 具 5'→3' 外切酶活性，负责切除 RNA 引物并以其聚合活性填补缺口。"},{"k":"引发酶造引物","t":"引发酶（原核由 dnaG 编码）催化合成 RNA 引物，为聚合酶提供 3'-OH；真核 Pol α 兼具引发酶活性。"},{"k":"解旋与单链保护","t":"解链酶（DnaB）识别复制叉、解开双链；单链结合蛋白（SSB）保护单链不被水解、防止复性。"},{"k":"拓扑与连接","t":"拓扑异构酶消除复制叉前方正超螺旋、恢复负超螺旋；DNA 连接酶连接冈崎片段，但不连接游离单链 DNA。"}],"note":"","opts":[],"printed_answer":""},{"id":"o105","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"名词解释","years":["12","17","19"],"q":"启动子","points":[{"k":"定义","t":"DNA 链上能指示 RNA 转录起始的一段序列，是 RNA 聚合酶识别并结合的模板部位。"},{"k":"结构基础","t":"原核启动子含 −35 区（TTGACA）与 −10 区（TATAAT，Pribnow 盒），二者共同决定转录起始位点与转录强度。"}],"note":"","opts":[],"printed_answer":""},{"id":"o106","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"名词解释","years":["16"],"q":"操纵子","points":[{"k":"定义","t":"原核生物在转录水平上控制基因表达的协调单位。"},{"k":"组成","t":"包括启动子（P）、操纵基因（O）和功能上相关的若干结构基因，受调节基因产物（阻遏蛋白或激活蛋白）控制。"},{"k":"转录特点","t":"一个操纵子的结构基因转录在同一条多顺反子 mRNA 上，实现协调表达；如乳糖操纵子、色氨酸操纵子。"}],"note":"","opts":[],"printed_answer":""},{"id":"o107","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"简答","years":["10"],"q":"简述大肠杆菌转录终止信号","points":[{"k":"不依赖ρ结构","t":"终止位点上游有两个特征结构：一是富含 GC 的回文结构（二重对称区），可转录成自身互补的发夹；二是 4~8 个腺苷酸组成的序列，可转录成一段寡聚 U。"},{"k":"不依赖ρ机制","t":"发夹结构可打断转录复合物中的 RNA-DNA 杂交部分并导致 RNA 聚合酶暂停，而 rU·dA 结合不稳定，易使 RNA 从 DNA 上解离。"},{"k":"依赖ρ结构","t":"终止位点上游也具有能使其转录产物 RNA 形成发夹结构的回文序列。"},{"k":"ρ因子活性","t":"ρ 因子具有依赖于 RNA 的 ATPase 活性和解旋酶活性。"},{"k":"穷追模型","t":"ρ 因子结合在新产生的 RNA 链上，借水解 ATP 获得的能量沿 RNA 链移动；RNA 聚合酶遇终止子暂停时 ρ 追上并与酶作用，其解旋酶活性造成 RNA 释放与聚合酶脱落，终止转录。"}],"note":"口径：依据《真题分类》资料原文。4~8 个腺苷酸、两个特征结构、穷追模型均照原文。","opts":[],"printed_answer":"","ref":true},{"id":"o108","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"简答","years":["12"],"q":"为什么 m7GTP 抑制真核蛋白质合成，而不抑制原核，为什么人工合成的 SD 抑制原核蛋白质却不抑制真核？","points":[{"k":"竞争帽子位点","t":"m⁷GTP 结构与 5' 帽子相似，竞争结合真核核糖体的帽子结合位点（eIF4E），使 mRNA 不能与核糖体结合，翻译被阻断。"},{"k":"原核无帽子","t":"原核 mRNA 5' 端没有 m⁷G 帽子，核糖体靠 SD 序列定位，故 m⁷GTP 不影响原核蛋白质合成。"},{"k":"SD是原核结合位","t":"原核 mRNA 起始密码子上游有 SD 序列，与 16S rRNA 3' 端互补配对，是核糖体结合与起始定位的位点。"},{"k":"人工SD占位","t":"人工合成的 SD 序列竞争结合原核核糖体，占据其 mRNA 结合位点，使天然 mRNA 无法起始翻译；真核无 SD 序列、靠帽子结合，故不受影响。"}],"note":"","opts":[],"printed_answer":""},{"id":"o109","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"简答","years":["13"],"q":"细菌存在转录后加工吗？","points":[{"k":"结论存在","t":"存在。细菌的转录后加工主要指对 RNA 聚合酶合成的初级转录物进行切割、修剪、修饰等加工。"},{"k":"rRNA加工","t":"rRNA 前体先甲基化，再由 RNase Ⅲ 切割成各种 rRNA。"},{"k":"tRNA加工","t":"RNase P 加工成熟 5′端，RNase F、D 加工 3′端；tRNA 核苷酸转移酶在 3′端加 CCA；再由 tRNA 修饰酶进行碱基修饰成成熟 tRNA。"},{"k":"mRNA少加工","t":"原核生物 mRNA 大多不需加工，只有极少数需要通过 RNase Ⅲ 进行切割。"}],"note":"口径：依据《真题分类》资料原文。加工酶名称 RNase Ⅲ、RNase P、RNase F、D 与 3′-CCA 均照原文。","opts":[],"printed_answer":"","ref":true},{"id":"o110","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"简答","years":["21"],"q":"DNA 编码链为 5'-ACTAGTAATTTTGCATGT-3' \n（1）写出转录的 mRNA 序列\n（2）翻译出氨基酸的顺序（书上有密码子氨基酸对应表，考试时会给）\n（3）mRNA 的功能\nUUU 苯丙氨酸 │ UCU 丝氨酸 │ UAU 酪氨酸 │ UGU 半胱氨酸\nUUC 苯丙氨酸 │ UCC 丝氨酸 │ UAC 酪氨酸 │ UGC 半胱氨酸\nUUA 亮氨酸 │ UCA 丝氨酸 │ UAA 终止密码 │ UGA 终止密码\nUUG 亮氨酸 │ UCG 丝氨酸 │ UAG 终止密码 │ UGG 色氨酸\nCUU 亮氨酸 │ CCU 脯氨酸 │ CAU 组氨酸 │ CGU 精氨酸\nCUC 亮氨酸 │ CCC 脯氨酸 │ CAC 组氨酸 │ CGC 精氨酸\nCUA 亮氨酸 │ CCA 脯氨酸 │ CAA 谷氨酰胺 │ CGA 精氨酸\nCUG 亮氨酸 │ CCG 脯氨酸 │ CAG 谷氨酰胺 │ CGG 精氨酸\nAUU 异亮氨酸 │ ACU 苏氨酸 │ AAU 天冬酰胺 │ AGU 丝氨酸\nAUC 异亮氨酸 │ ACC 苏氨酸 │ AAC 天冬酰胺 │ AGC 丝氨酸\nAUA 异亮氨酸 │ ACA 苏氨酸 │ AAA 赖氨酸 │ AGA 精氨酸\nAUG 甲硫氨酸 │ ACG 苏氨酸 │ AAG 赖氨酸 │ AGG 精氨酸\nGUU 缬氨酸 │ GCU 丙氨酸 │ GAU 天冬氨酸 │ GGU 甘氨酸\nGUC 缬氨酸 │ GCC 丙氨酸 │ GAC 天冬氨酸 │ GGC 甘氨酸\nGUA 缬氨酸 │ GCA 丙氨酸 │ GAA 谷氨酸 │ GGA 甘氨酸\nGUG 缬氨酸 │ GCG 丙氨酸 │ GAG 谷氨酸 │ GGG 甘氨酸","points":[{"k":"编码链换U","t":"（1）题干给出的是编码链，与 mRNA 序列相同，只把 T 换成 U：mRNA 为 5'-ACUAGUAAUUUUGCAUGU-3'。"},{"k":"按读框翻译","t":"（2）自 5' 端按三联体读框：ACU AGU AAU UUU GCA UGU，对应 Thr-Ser-Asn-Phe-Ala-Cys（苏氨酸-丝氨酸-天冬酰胺-苯丙氨酸-丙氨酸-半胱氨酸）。"},{"k":"AUG与开放读框","t":"全序列仅在第 15~17 位有一个 AUG，其后只剩 1 个碱基，构不成完整开放阅读框；若由此起读只能得到 Met。"},{"k":"mRNA的功能","t":"（3）mRNA 把 DNA 的遗传信息带到核糖体，以密码子序列决定氨基酸排列顺序，是蛋白质合成的直接模板。"}],"note":"原答案提到的对照答案 Met-Gln-Asp-Lys 与该序列的任何读框都不符，属题干或答案抄录失真；正文按「编码链 T→U」直译。若题干实为模板链，须先互补再写 mRNA。","opts":[],"printed_answer":""},{"id":"o111","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"简答","years":["22"],"q":"根据 DNA 排列顺序写 mRNA 的排列顺序，翻译的氨基酸序列，并判断哪种氨基酸在蛋白质分子内部","points":[{"k":"先判链性","t":"与 mRNA 序列互补的那条是模板链，与 mRNA 同序列（T→U）的是编码链；序列一律按 5'→3' 书写。"},{"k":"互补写mRNA","t":"以模板链为准，按 A-U、T-A、G-C、C-G 配对写出 mRNA，方向与模板链反向平行。"},{"k":"查表译序列","t":"从起始密码子 AUG 起按三联体读框查密码子表，得氨基酸序列，遇 UAA、UAG、UGA 终止。"},{"k":"判分子内与外","t":"疏水性氨基酸（Leu、Val、Phe、Ala、Ile）多埋在分子内部构成疏水核心；亲水或带电荷的（Lys、Arg、Asp、Glu）多分布在表面。"}],"note":"原卷未给出具体 DNA 序列，只能给方法与判据；补写具体数值即为编造，故不举例。","opts":[],"printed_answer":""},{"id":"o112","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"简答","years":["12"],"q":"PCR 如何选择反应条件（温度、循环次数、时间）为什么？","points":[{"k":"变性九十三度","t":"① 变性：93~95℃、30 s~1 min，使模板双链解离为单链，便于引物结合；温度过高或时间过长会损伤模板与 Taq 酶。"},{"k":"退火五十五度","t":"② 退火：约 55℃，一般比引物 Tm 低 5℃，引物与模板互补配对；温度过高结合不牢、过低则错配增多。"},{"k":"延伸七十二度","t":"③ 延伸：72℃，为 Taq DNA 聚合酶最适温度，以 dNTP 为原料、靶序列为模板，沿 5'→3' 合成新链。"},{"k":"循环二十五次","t":"循环次数 25~30 次，产物按 2ⁿ 几何级数累积；次数过多进入平台期、非特异产物增加，过少则产量不足。"},{"k":"全程两三小时","t":"每循环约 2~4 min，2~3 h 可把目的基因扩增几百万倍，故时间由片段长度与循环数决定。"}],"note":"","opts":[],"printed_answer":""},{"id":"o113","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"简答","years":["13"],"q":"细菌内产生的限制性内切酶为什么不剪切其本身的 DNA？","points":[{"k":"自身无识别序列","t":"含该限制酶的细胞，其基因组中往往不存在该酶的识别切割序列，酶找不到作用位点。"},{"k":"甲基化保护","t":"宿主甲基化酶把甲基转移到识别序列的碱基上（如 Dam 甲基化），甲基化后的位点不能被限制酶切割。"},{"k":"限制修饰系统","t":"限制酶与甲基化酶配对构成限制-修饰系统：自身 DNA 被修饰而受保护，外源未修饰 DNA 被降解，防止异源 DNA 入侵。"}],"note":"","opts":[],"printed_answer":""},{"id":"o114","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"简答","years":["13"],"q":"质粒要在宿主细胞中复制必需条件","points":[{"k":"自主复制元件","t":"（1）具有自主复制能力，即含与宿主细胞相适应的复制起点（ori）等复制元件，可在胞内独立复制。"},{"k":"选择标记","t":"（2）携带易于筛选的选择标记，如抗药性标记、营养标记、显色标记，便于重组子的筛选鉴定。"},{"k":"单一酶切位点","t":"（3）含多种限制酶的单一识别序列（多克隆位点），供外源基因插入而不破坏必需区。"},{"k":"载体尽量小","t":"（4）除保留必要序列外载体应尽可能小，便于导入细胞、提高转化效率并易于繁殖。"},{"k":"生物安全性","t":"（5）使用安全：宿主范围有限，在体内不发生重组与转移、不产生有害性状，也不能离开工程宿主自由扩散。"}],"note":"题干只问「复制」的必需条件，但教材常按完整克隆载体条件作答，本答案取后者，第（1）条为核心得分点。","opts":[],"printed_answer":""},{"id":"o115","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"简答","years":["19","20"],"q":"简述 PCR 的原理和应用","points":[{"k":"PCR原理","t":"PCR 即聚合酶链式反应，是体外扩增特定 DNA 的技术：依据待扩片段两端序列设计两个互补寡核苷酸引物，在含模板、引物、过量 dNTP、耐热 Taq DNA 聚合酶的体系中循环反应，使模板 DNA 以几何级数扩增。"},{"k":"三温循环","t":"高温变性使 DNA 解链、低温退火使引物与模板结合、适温延伸合成 DNA，三个阶段构成一个循环周期。"},{"k":"合成基因探针","t":"设计专一引物即可大量扩增痕量 DNA，用于基因扩增、医学检测、刑侦与亲缘鉴定；加入不等量引物（如 60∶1）的不对称 PCR 可以线性扩增方式制备单链探针。"},{"k":"测序与RTPCR","t":"第二代 DNA 测序通过 PCR 进行高通量测序；逆转录 PCR（RT-PCR）以 cDNA 为模板扩增 cDNA，可分析基因转录产物、构建 cDNA 文库、克隆特异 cDNA、合成 cDNA 探针。"},{"k":"PCR筛选法","t":"将全部基因保存在多孔培养板上，用目的基因特异引物逐孔扩增鉴定阳性孔，再把阳性孔克隆稀释到次级多孔板重复筛选，直至得到与目的基因对应的单个克隆。"},{"k":"定时定量PCR","t":"非特异法如 SYBR Green Ⅰ 只与双链 DNA 结合而发荧光，荧光强度反映 DNA 合成总量；特异法如 TaqMan 探针，聚合酶外切酶活性降解释放荧光，荧光强度反映被扩增的靶 DNA 总量。"}],"note":"口径：依据《真题分类》资料原文。资料末句被 OCR 截断，仅保留完整要点；应用部分按资料 5 条主干（合成基因探针、测序、RT-PCR、筛选法、定量 PCR）归并成 4 点。","opts":[],"printed_answer":"","ref":true},{"id":"o116","subj":"631","chap":"一、染色体结构","type":"简答","years":["18"],"q":"核小体结构特征","points":[{"k":"染色体基本单位","t":"核小体是染色体的基本单位，也是染色体压缩的第一个阶段。"},{"k":"八聚体核心","t":"组蛋白 H₂A、H₂B、H₃、H₄ 各 2 分子：H₃ 与 H₄ 先组成四聚体（H₃-H₄）₂，两个异二聚体（H₂A-H₂B）分别结合在该四聚体的两侧，形成八聚体核心颗粒。"},{"k":"146bp盘绕","t":"长约 146 bp 的 DNA 以左手超螺旋状在组蛋白八聚体上盘绕约 1.75 圈。"},{"k":"H1封口","t":"核心颗粒两端 DNA 各有约 11 bp 与 H₁ 结合，H₁ 结合在核小体外侧的接头处，使结构更紧凑，形成完整核小体（连 DNA 共约 200 bp）。"},{"k":"压缩约七倍","t":"核小体使 DNA 分子收缩为原来的 1/7。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o117","subj":"631","chap":"一、染色体结构","type":"简答","years":[],"q":"简述 DNA 双螺旋结构模型的特点","points":[{"k":"反向平行右手","t":"① 两条多核苷酸链反向平行，围绕同一中心轴盘成右手双螺旋（B 型 DNA）。"},{"k":"螺旋参数","t":"② 直径 2 nm，螺距 3.4 nm，每圈 10 个碱基对，相邻碱基对上升 0.34 nm、旋转夹角 36°。"},{"k":"骨架外碱基内","t":"③ 磷酸-脱氧核糖骨架位于外侧，碱基位于内侧，碱基对平面与螺旋轴垂直。"},{"k":"大小沟识别","t":"④ 表面存在大沟（宽 2.2 nm）与小沟（宽 1.2 nm），是蛋白质识别并结合 DNA 的部位。"},{"k":"氢键与堆积力","t":"⑤ 维系力为碱基对氢键（A=T 两个、G≡C 三个）、碱基堆积力（主要）以及阳离子中和磷酸斥力。"},{"k":"互补与Tm","t":"⑥ 碱基互补 A-T、G-C，使两链互为模板，是复制、转录、修复的分子基础；GC 含量越高氢键越多、Tm 越高。"}],"note":"","opts":[],"printed_answer":""},{"id":"o118","subj":"631","chap":"一、染色体结构","type":"简答","years":[],"q":"核酶的结构特点及其意义？","points":[{"k":"空间结构定催化","t":"核酶的催化功能与其空间结构有密切关系，并非由一级序列本身决定。"},{"k":"锤头结构","t":"已知多种特殊结构核酶的自我切割区都有锤头结构，由三个茎区构成；茎区是由互补碱基构成的局部双链，包围着由 11~13 个保守核苷酸构成的催化中心。"},{"k":"底物茎区配对","t":"底物即切割部位两端的核苷酸，分别与核酶的茎Ⅰ、茎Ⅲ结合，决定切割位点。"},{"k":"修正中心法则","t":"核酶是继反转录现象之后对中心法则的又一重要修正，说明 RNA 既是遗传物质又是酶，打破了酶是蛋白质的传统观念。"},{"k":"生命起源与治疗","t":"为生命起源研究提供新思路——也许曾存在以 RNA 为基础的原始生命，为先有核酸提供依据；作为生物催化剂可破坏有害基因，为肿瘤等疾病治疗提供手段。"}],"note":"口径：依据《真题分类》资料原文。11~13 个保守核苷酸、三个茎区、茎Ⅰ与茎Ⅲ均照原文。","opts":[],"printed_answer":"","ref":true},{"id":"o119","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["10"],"q":"简述后随链的复制","points":[{"k":"方向相反只能分段","t":"DNA 聚合酶只能沿 5′→3′ 方向合成，而后随链的合成方向与复制叉前进方向相反，故以大量独立片段（冈崎片段）形式合成，每个片段都独立地被引发、聚合和连接，最后连成连续的多核苷酸链。"},{"k":"解旋与引发","t":"解旋酶沿复制叉移动方向把 DNA 解成单链，DNA 引发酶（引发体）识别模板链上一个短的引发序列，合成一短的 RNA 引物。"},{"k":"回环与PolⅢ延伸","t":"后随链绕成一个回环，DNA 聚合酶Ⅲ异二聚体的一个亚基经 β 夹子和 γ 复合物结合在后随链上，把核苷酸加在引物 3′ 端延伸，直至到达先前合成片段的引物处受阻、与模板脱离，一个冈崎片段合成完毕。"},{"k":"PolⅠ切引物填补","t":"DNA 聚合酶Ⅰ识别引物的 5′ 游离末端，用外切核酸酶活性把引物消化掉，同时用聚合酶活性以相应脱氧核糖核苷酸填补缺口。"},{"k":"连接酶封口","t":"糖-磷酸主链上留下的缺口由 DNA 连接酶形成磷酸二酯键，把两个冈崎片段相连。"},{"k":"循环成完整链","t":"复制叉前移后，引发酶在下一引发序列上合成新的引物，聚合酶Ⅲ重新起始新的冈崎片段，多次循环最终合成一条完整连续的 DNA 链。"}],"note":"口径：依据《真题分类》资料原文。资料第（6）步作「RNA 聚合酶Ⅲ」，应为 DNA 聚合酶Ⅲ，已更正。","opts":[],"printed_answer":"","ref":true},{"id":"o120","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["10"],"q":"基因重组（涉及遗传学的知识）","points":[{"k":"同源重组","t":"① 发生在同源序列之间，如减数分裂中同源染色体的交换；关键中间体为 Holliday 交叉，大肠杆菌依赖 RecBCD-RecA-RuvABC。"},{"k":"位点特异重组","t":"② 发生在特异位点（att），需特异重组酶，不需长同源区；如 λ 噬菌体整合与切除、细菌鞭毛相转变、Ig 基因 V(D)J 重排。"},{"k":"转座重组","t":"③ 转座子在转座酶作用下插入新位点，两端为反向重复序列，插入后靶位点两侧产生正向重复。"},{"k":"意义","t":"重组产生新的基因组合，是生物遗传变异、物种进化的重要来源，也是基因工程与基因敲除的技术基础。"}],"note":"","opts":[],"printed_answer":""},{"id":"o121","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["13"],"q":"人类寿命怎么测？设计实验","points":[{"k":"原理端粒缩短","t":"端粒能稳定染色体末端、防止染色体间末端连接，并可补偿后随链 5′ 端去除 RNA 引物后的空缺；DNA 每复制一次端粒缩短一些，短到一定程度即引起细胞凋亡，故端粒决定细胞乃至人体寿命，测端粒长度即可估算寿命，方法为 DNA 印迹法（Southern blot）。"},{"k":"取材白细胞","t":"血液中白细胞最能反映人的生理和病理状态，故取外周血分离白细胞，以苯酚/氯仿抽提法提取总 DNA。"},{"k":"限制酶切","t":"用限制性核酸内切酶 HinfⅠ 或 RsaⅠ 消化 DNA，这两种酶能频繁切断 DNA，可使亚端粒区域变得尽可能小。"},{"k":"电泳转膜","t":"用琼脂糖电泳分离不同大小的 DNA 片段，并转移到硝酸纤维膜或尼龙膜上。"},{"k":"探针杂交","t":"用 ³²P 同位素或生物素、碱性磷酸酶等标记的端粒特异性探针（CCCATT）ₙ 与膜上的 DNA 片段杂交。"},{"k":"定量推算","t":"末端限制酶切片段（TRF）可用光密度计定量测量，据此推算人类寿命。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o122","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["13"],"q":"DNA 聚合酶如何维持复制忠实性？","points":[{"k":"碱基互补配对","t":"DNA 半保留复制，dNTP 按 A-T、G-C 互补配对原则、以每条链为模板对号入座，使子代 DNA 与亲代 DNA 的核苷酸序列相同。"},{"k":"底物高度选择","t":"DNA 聚合酶具模板依赖性，并通过消耗大量能量保证严格按互补原则复制，但此时大约仍有 10⁻⁴ 概率的错配。"},{"k":"三撇外切校对","t":"发生错配时，DNA 聚合酶以 3′→5′ 外切酶活性把错配碱基降解并加以校正，可使错配概率减至 10⁻⁶；起始时使用 RNA 引物正是基于这一特性——确认前面配对正确才继续合成。"},{"k":"错配修复","t":"DNA 修复系统（错配修复）进一步降低错误率，使错配减至 10⁻⁹ 以下。"},{"k":"三重机制保证","t":"半保留复制与碱基配对、聚合酶的双重核对、修复系统三者共同保证 DNA 复制的高度准确性。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o123","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["13"],"q":"细菌抗生素抗性机理？","points":[{"k":"产生灭活酶","t":"产生导致抗生素失效的酶，使抗生素失去活性。"},{"k":"修饰靶位点","t":"通过修饰改变对抗生素敏感的部位，降低抗生素与作用位点的亲和力。"},{"k":"降低膜通透性","t":"改变膜成分或使膜出现新的成分，降低细胞透过抗生素的能力，减少抗生素的摄入。"},{"k":"主动外排泵","t":"编码产生外排泵，消耗能量把抗生素排出菌体外，降低胞内药物浓度、减少对药物的敏感性。"},{"k":"补：耐药传播","t":"耐药基因可经质粒、转座子等水平转移，使敏感菌获得抗性并造成多重耐药。"}],"note":"口径：依据《真题分类》资料原文；末点（耐药基因水平传播）为资料之外补充分点。","opts":[],"printed_answer":"","ref":true},{"id":"o124","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":[],"q":"简述拓扑异构酶的概念、分类、特点及作用机理","points":[{"k":"概念","t":"（1）通过切断、转移、重接磷酸二酯键来改变 DNA 拓扑状态（超螺旋度）的一类酶。"},{"k":"Ⅰ型","t":"（2）Ⅰ 型切一条链、不需 ATP，每次改变连环数 ±1，主要松弛负超螺旋。"},{"k":"Ⅱ型","t":"Ⅱ 型（旋转酶）切两条链、需 ATP，每次改变连环数 ±2；原核旋转酶引入负超螺旋，真核 Ⅱ 型主要解除正超螺旋。"},{"k":"特点","t":"（3）只改变 DNA 的拓扑结构，不改变其一级结构（碱基序列）。"},{"k":"作用机理","t":"（4）酶与 DNA 形成共价磷酸酪氨酸中间体→断链→另一段 DNA 穿过缺口→重新连接并释放。"},{"k":"生理作用","t":"（5）解除复制叉前方正超螺旋、参与解链与复性、染色体分离、重组与转录，是喹诺酮类药物的靶点。"}],"note":"","opts":[],"printed_answer":""},{"id":"o125","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":[],"q":"简述大肠杆菌 DNA 的复制过程和调控机理","points":[{"k":"起始","t":"（1）① DnaA 结合 oriC 打开双链→DnaB 解旋酶装载、SSB 稳定单链→引发酶合成 RNA 引物→Pol Ⅲ 起始双向复制。"},{"k":"延伸","t":"② 前导链连续合成，后随链分段合成冈崎片段；Pol Ⅰ 切除引物并填补，连接酶封口。"},{"k":"终止","t":"③ 两个复制叉在 ter 位点相遇，Tus 蛋白阻断复制叉，拓扑异构酶解链，二聚体解离。"},{"k":"起始调控","t":"（2）DnaA-ATP/ADP 状态、oriC 的 GATC 甲基化与 SeqA 隔离、RIDA 使 DnaA 失活，共同保证每个细胞周期只起始一次。"},{"k":"与生长偶联","t":"复制与细胞周期偶联，生长速率调节起始频率；快生长时上一轮未结束即可再起始，形成多叉复制。"}],"note":"","opts":[],"printed_answer":""},{"id":"o126","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":[],"q":"真核生物与原核生物 DNA 复制的区别","points":[{"k":"复制起点","t":"① 原核单一 oriC 双向复制；真核有多个复制起点，同时双向复制以提高效率。"},{"k":"速度与片段","t":"② 原核约 1000 nt/s、冈崎片段 1000~2000 nt；真核约 50 nt/s、片段仅 100~200 nt，靠多起点并行弥补低速。"},{"k":"酶系","t":"③ 原核 Pol Ⅲ 主力、Pol Ⅰ 切引物；真核 Pol δ、Pol ε 延伸，Pol α 引发，Pol γ 复制线粒体 DNA。"},{"k":"复制周期","t":"④ 原核可连续复制、多轮重叠；真核只在 S 期复制，且每周期每个起点只起始一次（执照因子 licensing 控制）。"},{"k":"末端与染色质","t":"⑤ 原核环状 DNA 无末端问题；真核线状 DNA 需端粒与端粒酶，且须组蛋白解离、重装配与染色质成熟。"}],"note":"","opts":[],"printed_answer":""},{"id":"o127","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":[],"q":"LexA 的降解与 SOS 应答过程","points":[{"k":"损伤积累单链","t":"① DNA 严重损伤使复制叉停滞，产生并积累单链 DNA（ssDNA）。"},{"k":"RecA被激活","t":"② RecA 结合 ssDNA 与 ATP，形成 RecA-ssDNA 核蛋白丝并被激活，成为共蛋白酶。"},{"k":"LexA自切割","t":"③ 激活的 RecA 促使阻遏蛋白 LexA 发生自切割（Ala84-Gly85 肽键断裂），LexA 从操纵基因上解离。"},{"k":"SOS基因去阻遏","t":"④ recA、uvrA、umuC/umuD 等约 20 个 SOS 基因（LexA 调节子）去阻遏表达，切除修复能力增强。"},{"k":"易错修复","t":"⑤ UmuD'₂C 与 Pol Ⅲ 组成 Pol Ⅴ，可越过损伤继续合成，属易错修复，突变率升高。"},{"k":"损伤修复后关闭","t":"⑥ 修复完成后 ssDNA 消失、RecA 失活，LexA 重新积累并结合操纵基因，SOS 应答关闭。"}],"note":"","opts":[],"printed_answer":""},{"id":"o128","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":[],"q":"请解释，为什么复制机器不能对染色体末端进行完整复制，这又会造成什么后果？真核细胞是如何解决这个问题的？","points":[{"k":"引物去除留缺口","t":"后随链 5′ 末端的 RNA 引物除去后需把缺口填补，但 DNA 聚合酶不具有 3′→5′ 的聚合活性，不能填补该缺口，故不能对染色体末端进行完整复制。"},{"k":"末端逐代缩短","t":"由此造成 DNA 后随链 5′ 末端缺失；该 DNA 再复制时，两个子代 DNA 之一将变短，缺失的恰是母代后随链中未被填补的那一段，随复制进行细胞 DNA 越来越短、损伤累积，最终导致细胞死亡。"},{"k":"端粒稳定末端","t":"哺乳动物通过形成端粒结构来防止复制时产生染色体末端缺失，端粒还能稳定染色体末端、防止染色体间末端连接。"},{"k":"端粒酶延长","t":"癌细胞、干细胞等增殖迅速的细胞中存在含 RNA 链的逆转录酶——端粒酶，它是 RNA 与蛋白质的复合体，蛋白组分具逆转录酶活性，可利用自身所含 RNA 为模板合成端粒 DNA、维持端粒长度。"},{"k":"延长细胞寿命","t":"从而延长细胞寿命、增强细胞的分裂能力。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o129","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":[],"q":"请阐述 ColE1 质粒 DNA 的复制调控机制","points":[{"k":"基本参数","t":"ColE1 是 6646 个碱基对的小质粒，在宿主细胞内拷贝数为 20~30；其 DNA 复制不依赖自身编码的蛋白质，而完全依靠宿主的 DNA 聚合酶Ⅰ。"},{"k":"两个负调控因子","t":"质粒编码 Rop 蛋白和反义 RNA（RNA1）两个负调控因子，它们控制起始复制所必需的引物合成。"},{"k":"引物前体加工","t":"引物 RNA 前体的转录起始于复制起点上游 555 个核苷酸处，需经 RNase H 加工后产生有 555 个核苷酸的引物，再由 DNA 聚合酶Ⅰ在引物 3′ 末端起始 DNA 合成。"},{"k":"RNA1负调控","t":"RNA1 的编码区在引物 RNA 编码区的 5′ 末端、转录方向与引物 RNA 相反，故与引物 RNA 的 5′ 末端互补；RNA1 通过氢键配对与引物前体相互作用，阻止 RNase H 加工，使其不能转化为有活性的引物。"},{"k":"Rop蛋白增效","t":"Rop 蛋白能提高 RNA1 与引物前体的相互作用，从而加强 RNA1 的负调控作用。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o130","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["18"],"q":"练习题原题，给出两条 DNA 链，问哪条是模板链，mRNA 对应的序列是什么，如果有 SD 序列，该链来源于真核生物还是原核生物","points":[{"k":"先判模板链","t":"与 mRNA 序列互补的那条为模板链；与 mRNA 序列相同（T 换为 U）的那条为编码链（有义链），两条链与 mRNA 均反向平行。"},{"k":"互补写mRNA","t":"以模板链为准，按 A-U、T-A、G-C、C-G 写出 mRNA，方向为 5′→3′。"},{"k":"SD序列判原核","t":"mRNA 起始密码子上游存在 SD 序列（与 16S rRNA 3′ 端互补、协助核糖体结合）者来源于原核生物。"},{"k":"帽与尾判真核","t":"有 m⁷G 帽子、poly(A) 尾、单顺反子者来源于真核生物；真核靠帽子结构而非 SD 序列招募核糖体。"}],"note":"资料无对应原答案（原名答案仅存「练习册 P97 习题-74」索引），原卷具体序列未给出，按教材口径给判断流程与判据。","opts":[],"printed_answer":"","ref":false},{"id":"o131","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["19"],"q":"写出四种真核生物 RNA 种类及功能","points":[{"k":"mRNA","t":"从 DNA 处携带遗传信息，作为蛋白质多肽链合成的直接模板，决定氨基酸序列，起「指导者」作用；真核 mRNA 的 5′ 端帽子结构可能与蛋白质合成的正确起始有关，原核则由 SD 序列协助核糖体与 mRNA 结合、使翻译在 AUG 处开始。"},{"k":"tRNA","t":"反密码子环可与 mRNA 上的三联体密码子识别配对，受体臂接受活化的氨基酸，故能解读密码子、转运氨基酸，起「转换器」作用。"},{"k":"rRNA","t":"与几十种蛋白质组成核糖体，含多种活性中心：大亚基的肽基转移酶活性中心（rRNA 有催化活性，催化肽键形成）、tRNA 结合位点（A、P、E 位）、小亚基的译码中心与 mRNA 结合部位，是蛋白质合成的场所，起「装配者」作用。"},{"k":"snRNA","t":"核内小 RNA，是真核生物转录后加工中 RNA 剪接体的主要成分，含 U 丰富故分 U1~U7 共 7 类；U3 存在于核仁、参与核仁内 28S rRNA 的加工成熟，其余 6 种在非核仁区核液中与蛋白质结合成 snRNP，参与 mRNA 的加工成熟。"}],"note":"口径：依据《真题分类》资料原文（原文并列有 miRNA、gRNA、micRNA、siRNA，题干只要四种，取前四类）。","opts":[],"printed_answer":"","ref":true},{"id":"o132","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"遗传密码是如何破译的？","points":[{"k":"无细胞翻译体系","t":"① 建立大肠杆菌抽提物无细胞体系：核糖体、tRNA、氨基酸、ATP/GTP，外加人工合成的已知序列 RNA。"},{"k":"单密码子法","t":"② 以 poly(U) 为模板只得到多聚苯丙氨酸，确定 UUU=Phe；同理 poly(A)→Lys、poly(C)→Pro。"},{"k":"三联体结合法","t":"③ 用已知三核苷酸与核糖体、氨酰-tRNA 共孵育，能结合到核糖体上的即对应氨基酸，逐一确定 64 个密码子。"},{"k":"重复共聚物定框","t":"④ 用 poly(UC) 等重复共聚物确定读框与终止信号，由 Nirenberg、Khorana 等完成全部密码子的破译。"}],"note":"","opts":[],"printed_answer":""},{"id":"o133","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"终止密码子的种类及其别名是什么？","points":[{"k":"三种终止密码","t":"共三种：UAA、UAG、UGA，均不编码氨基酸。"},{"k":"三种别名","t":"UAA 称赭石密码子，UAG 称琥珀密码子，UGA 称蛋白石密码子。"},{"k":"补：释放与终止","t":"由释放因子识别：RF1 识别 UAA、UAG，RF2 识别 UAA、UGA，促使肽链从核糖体释放、翻译终止。"}],"note":"口径：依据《真题分类》资料原文；末点（释放因子识别与终止）为资料之外补充分点。","opts":[],"printed_answer":"","ref":true},{"id":"o134","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"简述原核生物 RNA 聚合酶各亚基的功能","points":[{"k":"全酶组成","t":"全酶＝核心酶 α₂ββ'ω＋σ 因子；核心酶负责延伸，σ 因子负责起始识别。"},{"k":"α亚基","t":"两个 α 亚基参与核心酶装配，并识别启动子 UP 元件，影响启动子强度。"},{"k":"β与β撇","t":"β 亚基结合底物 NTP 并参与催化磷酸二酯键形成；β' 亚基结合模板 DNA、参与解链与催化，二者共同构成活性中心。"},{"k":"ω亚基","t":"ω 亚基参与酶装配、稳定 β' 亚基，保护酶免于变性。"},{"k":"σ因子","t":"识别 −10 区与 −35 区，决定转录起始位点与启动子特异性；起始后释放，核心酶进入延伸，不同 σ 因子可切换基因表达程序。"}],"note":"","opts":[],"printed_answer":""},{"id":"o135","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"简述真核生物 mRNA 5'端帽子和 3'端尾巴的功能","points":[{"k":"帽子结构","t":"（1）5' 帽为 m⁷GpppN，通过 5'-5' 三磷酸键与起始核苷酸相连，在核内加帽。"},{"k":"帽子功能","t":"保护 mRNA 免受 5' 外切酶降解；被 eIF4E 识别作为翻译起始信号；参与核输出与剪接加工。"},{"k":"尾巴结构","t":"（2）3' 端有 AAUAAA 加尾信号，切割后在 80~250 个腺苷酸上加上 poly(A) 尾。"},{"k":"尾巴功能","t":"抗 3' 外切酶、提高稳定性；参与核输出；PABP 与 eIF4G 互作使 mRNA 成闭环，提高翻译效率。"}],"note":"","opts":[],"printed_answer":""},{"id":"o136","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"真核生物和原核生物 mRNA 特征的比较","points":[{"k":"顺反子","t":"① 原核 mRNA 多为多顺反子，一条 mRNA 编码多条肽链；真核为单顺反子。"},{"k":"五撇端","t":"② 原核无帽子、有 SD 序列作核糖体结合位点；真核有 m⁷G 帽子。"},{"k":"三撇端","t":"③ 原核无或仅有很短的 poly(A)；真核有 80~250 个腺苷酸的 poly(A) 尾。"},{"k":"内含子","t":"④ 原核一般无内含子、不剪接；真核有内含子，需剪接除去。"},{"k":"时空关系","t":"⑤ 原核半衰期短（数分钟）、边转录边翻译；真核较稳定，转录在核内、翻译在胞质，时空分离。"},{"k":"加工方式","t":"⑥ 原核加工简单，主要是 rRNA、tRNA 的切割与修饰；真核需加帽、加尾、剪接，还可发生 RNA 编辑。"}],"note":"","opts":[],"printed_answer":""},{"id":"o137","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"原核生物转录终止的分类及各自的结构特点、过程","points":[{"k":"不依赖ρ结构","t":"① 回文对称、富含 G-C 的序列转录出发夹结构使 RNAP 暂停；发夹后紧跟约 6 个 U，rU-dA 配对最弱、杂合双链易解开。"},{"k":"不依赖ρ过程","t":"发夹形成→RNAP 暂停→RNA-DNA 杂合体解离→RNA 释放、酶与模板脱落，只需核心酶即可完成。"},{"k":"依赖ρ结构","t":"② 回文区不含富 GC 序列、其后也无寡聚 U，自身不能形成稳定发夹，必须由 ρ 因子参与终止。"},{"k":"依赖ρ过程","t":"ρ 因子为六聚体解旋酶，结合新生 RNA 的 rut 位点，耗 ATP 沿 RNA 5'→3' 追赶，在 RNAP 暂停处解旋杂合体，释放 RNA。"},{"k":"抗终止作用","t":"③ 另有抗终止：λ 噬菌体 N 蛋白结合 nut 位点、Q 蛋白结合 qut 位点，可修饰 RNAP 使其越过终止信号。"}],"note":"","opts":[],"printed_answer":""},{"id":"o138","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"简述密码子的特性","points":[{"k":"三联体编码","t":"3 个相邻核苷酸编码 1 个氨基酸，共 64 个密码子，其中 61 个编码氨基酸、3 个为终止信号。"},{"k":"连续无重叠","t":"密码子首尾相接、无标点、无重叠地依次读取，阅读框一经确定即固定不变。"},{"k":"简并性编码","t":"一个氨基酸可由多个密码子编码，Leu、Ser、Arg 各 6 个，仅 Met（AUG）、Trp（UGG）唯一。"},{"k":"通用性为主","t":"从病毒到人基本共用一套密码子表；例外在线粒体，UGA＝Trp、AGA/AGG＝终止。"},{"k":"起始终止码","t":"起始密码子为 AUG；终止为 UAA（赭石）、UAG（琥珀）、UGA（蛋白石），不编码任何氨基酸。"},{"k":"摆动性配对","t":"密码子第 3 位与反密码子第 1 位配对不严格（G-U 可配），故一个 tRNA 可识别多个同义密码子。"}],"note":"","opts":[],"printed_answer":""},{"id":"o139","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"简述蛋白质合成的 5 个阶段","points":[{"k":"氨基酸活化","t":"氨酰-tRNA 合成酶催化 氨基酸＋ATP＋tRNA → 氨酰-tRNA＋AMP＋PPi，每活化 1 个氨基酸消耗 2 个高能键。"},{"k":"起始复合物","t":"原核：30S＋IF1/2/3＋fMet-tRNA＋mRNA（SD 定位）→ 50S 加入成 70S；真核：帽依赖的 43S 扫描形成 80S。"},{"k":"延伸三步","t":"进位（EF-Tu/GTP 把氨酰-tRNA 送入 A 位）→成肽（肽基转移酶，rRNA 催化）→移位（EF-G/GTP，沿 mRNA 移动一个密码子）。"},{"k":"终止与释放","t":"终止密码子进入 A 位，RF1/RF2/RF3 识别，肽链释放、核糖体解离。"},{"k":"翻译后加工","t":"切除信号肽与前导序列、折叠、共价修饰（磷酸化、糖基化、羟基化）、亚基装配、定向运输。"}],"note":"","opts":[],"printed_answer":""},{"id":"o140","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"简述原核、真核生物在蛋白质合成起始阶段的差异","points":[{"k":"起始tRNA不同","t":"原核用 fMet-tRNA（甲酰化）；真核用 Met-tRNAᵢ（未甲酰化）。"},{"k":"SD对帽子扫描","t":"原核靠 SD 序列与 16S rRNA 互补直接定位 AUG；真核靠帽子＋43S 前起始复合物扫描至首个 AUG（Kozak 序列）。"},{"k":"核糖体大小","t":"原核 70S（50S＋30S）；真核 80S（60S＋40S）。"},{"k":"起始因子数目","t":"原核仅 IF-1/2/3；真核需 eIF1/1A/2/3/4E/4G/5 等十余种。"},{"k":"转录翻译偶联","t":"原核边转录边翻译；真核转录在核内、翻译在胞质，时空分离。"},{"k":"顺反子数目","t":"原核可为多顺反子（每个 ORF 各有 SD 序列）；真核一般单顺反子。"}],"note":"","opts":[],"printed_answer":""},{"id":"o141","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"启动子的作用和结构特征","points":[{"k":"定位转录起点","t":"作用：活化 RNA 聚合酶、使之与模板准确结合，决定转录起始位点与起始特异性，控制起始时间与表达强度。"},{"k":"原核双元件","t":"−10 区（Pribnow 盒，TATAAT）＋−35 区（TTGACA），间距 16~19 bp 时活性最高；上游可有富 A/T 的 UP 元件；由 σ 因子识别。"},{"k":"真核核心启动子","t":"核心启动子含 TATA 盒（−25~−30）、Inr、DPE、BRE，上游元件有 CAAT 盒（−70~−80）、GC 盒（−90~−110）；由 TFⅡD（TBP＋TAF）识别 TATA 盒。"},{"k":"顺式元件共性","t":"均属顺式作用元件，自身不编码蛋白，需反式因子结合才起作用；有方向性，通常位于起点上游（Pol Ⅲ 的 tRNA、5S rRNA 基因例外，启动子在转录单元内部）。"}],"note":"","opts":[],"printed_answer":""},{"id":"o142","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"何为依赖于 DNA 的 DNA 聚合酶？何为依赖于 RNA 的 DNA 聚合酶？说明其在分子生物学中的应用","points":[{"k":"DNA聚合酶定义","t":"即依赖 DNA 的 DNA 聚合酶：能把脱氧核糖核苷酸连续加到双链 DNA 引物链的 3′-OH 末端催化聚合，以 DNA 为模板、产物序列与模板互补；原核有 DNA 聚合酶Ⅰ、Ⅱ、Ⅲ三种。"},{"k":"PolⅠ应用","t":"可用切口平移法标记 DNA 作杂交探针；利用 5′→3′ 外切核酸酶活性降解寡核苷酸，作为合成 cDNA 第二链的引物；对 DNA 分子的 3′ 突出尾巴作末端标记，用于序列分析。"},{"k":"Klenow补平","t":"Klenow 片段具聚合酶和 3′→5′ 外切酶活性：前者合成 cDNA 第二条链，后者把黏末端切成平头末端。"},{"k":"Taq耐热PCR","t":"Taq DNA 聚合酶热稳定性极高，90 ℃ 左右仍有较高聚合活性，广泛用于 PCR。"},{"k":"逆转录酶定义","t":"即依赖 RNA 的 DNA 聚合酶：以 RNA 为模板合成 DNA（逆转录），为具 3 种酶活性的多功能酶。"},{"k":"逆转录酶应用","t":"①将 mRNA 反转录成 cDNA，构建 cDNA 文库、进行克隆；②对具 5′ 突出端的 DNA 片段的 3′ 端填补（补平）和标记，制备探针；③代替 Klenow 片段用于 DNA 序列测定。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o143","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"请比较复制与转录的异同点","points":[{"k":"相同点五条","t":"都以 DNA 为模板；都按碱基互补、沿 5'→3' 合成新链；都需聚合酶、Mg²⁺、模板与底物；都遵循模板依赖（半保留）；都有起始、延伸、终止三阶段。"},{"k":"产物与模板","t":"复制得两条 DNA、两条链都作模板；转录得一条 RNA、只以一条链为模板（不对称转录）。"},{"k":"引物与酶","t":"复制需 RNA 引物、DNA 聚合酶有校对功能；转录不需引物、RNA 聚合酶无校对、可多次起始。"},{"k":"范围不同","t":"复制复制整条染色体；转录只转录基因区段，同一区段可重复转录多次。"},{"k":"忠实性不同","t":"复制忠实性极高（错误率约 10⁻⁹）；转录较低（10⁻⁴~10⁻⁵），可靠多拷贝补偿。"}],"note":"","opts":[],"printed_answer":""},{"id":"o144","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"简述原核生物 RNA 转录过程","points":[{"k":"σ识别启动子","t":"σ 因子引导 RNA 聚合酶全酶识别 −35 区与 −10 区并特异结合，形成闭合复合物。"},{"k":"解链成开放","t":"DNA 局部解链约 17 bp 形成转录泡，转为开放复合物；首个核苷酸加入、形成第一个磷酸二酯键后 σ 因子释放。"},{"k":"核心酶延伸","t":"核心酶沿模板 3'→5' 移动，RNA 按 5'→3' 合成；转录泡内形成约 8 bp 的 RNA-DNA 杂合双链，后方 DNA 复性、前方解链；β/β' 构成催化中心。"},{"k":"两类终止子","t":"不依赖 ρ 的终止子（发夹＋寡聚 U）或依赖 ρ 的终止子（ρ 追赶并解旋杂合体），释放 RNA 与酶，核心酶可重新起始。"}],"note":"","opts":[],"printed_answer":""},{"id":"o145","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"简述抗终止的调控机制","points":[{"k":"抗终止子","t":"抗终止子是一类能在特定位点阻止终止信号发挥作用的蛋白质。"},{"k":"Nut位点","t":"依赖 ρ 因子的终止子上游存在抗终止信号，即 Nut 位点。"},{"k":"修饰酶构象","t":"在 RNA 聚合酶到达终止子之前，抗终止子先结合在 Nut 位点上，待聚合酶经过时修饰其构象，使其对终止信号不敏感。"},{"k":"越过终止子","t":"于是 RNA 聚合酶可以通过终止子，转录得以继续进行。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o146","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"一个基因一个酶的说法对么","points":[{"k":"结论不准确","t":"该说法不准确，宜表述为「一个基因编码一条多肽链」。"},{"k":"只编码RNA的基因","t":"有的基因只编码产生 RNA，如 rRNA、tRNA 基因，不产生蛋白质产物。"},{"k":"非酶蛋白基因","t":"有的基因编码产生其他蛋白质（如血红蛋白、结构蛋白），却不编码酶。"},{"k":"多基因编码一酶","t":"有的酶蛋白由多个亚基组成，各亚基可能由不同基因编码，即多个基因对应一个酶。"},{"k":"一基因多产物","t":"同一转录产物在不同发育阶段、不同细胞中或不同生理状态下经不同剪接方式，得到不同的 mRNA 及编码产物，即一个基因可对应多个酶。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o147","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"论述确保蛋白质翻译精确的机制","points":[{"k":"高耗能保准确","t":"每合成 1 个肽键至少需水解 4 个高能磷酸键，高耗能既保证反应准确，也为修复提供能量。"},{"k":"合成酶双重校对","t":"氨酰-tRNA 合成酶既识别 tRNA、又识别相应氨基酸，保证氨基酸与 tRNA 的专一结合；发现错误可行化学校对与动力学校对。"},{"k":"核糖体译码校对","t":"小亚基的译码中心促进 tRNA 与 mRNA 相应密码子的正确配对，发现配对错误可予校正（化学校对、动力学校对）。"},{"k":"tRNA反密码子","t":"反密码子与密码子的准确识别保证蛋白质合成的准确率；校正 tRNA 可经反密码子区突变，校正错义突变、无义突变和移码突变。"},{"k":"蛋白因子分工","t":"起始因子保证只有起始 tRNA 能进入 P 位点，延伸因子保证非起始 tRNA 都进入 A 位点。"},{"k":"密码简并缓冲","t":"密码子的简并性与安全性保证发生突变时氨基酸性质的变化减到最小，降低危害。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o148","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":["13"],"q":"生长素和细胞分裂素的作用有什么不同？","points":[{"k":"生长素促伸长","t":"能促进细胞纵向伸长，作用具两重性：低浓度促进生长、中浓度抑制、高浓度杀死植物；既促进发芽又抑制发芽，既防止落花落果又可疏花疏果，取决于浓度、细胞年龄和器官种类。"},{"k":"分裂素促分裂","t":"能促进细胞分裂和扩大、延迟衰老和保鲜、诱导芽的分化、促进侧芽发育、防止果树生理落果、打破种子休眠并促进发芽。"},{"k":"二者区别","t":"生长素的化学本质是吲哚乙酸，主要促进细胞的生长和伸长、对细胞分裂没有影响；细胞分裂素既能促进细胞分裂、又能促进生长。"}],"note":"口径：依据《真题分类》资料原文。资料原文作「细胞分裂素的化学本质是蛋白质」，实为腺嘌呤衍生物类（如玉米素），已更正。","opts":[],"printed_answer":"","ref":true},{"id":"o149","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":["13"],"q":"细胞生物学 2012 年诺贝尔奖，诱导性多功能干细胞是什么？有什么意义","points":[{"k":"四因子重编程","t":"诱导性多能干细胞（iPS）：利用病毒载体把 Oct4、Sox2、Klf4 和 c-Myc 四个转录因子的组合转入分化的体细胞，使其重编程为类似胚胎干细胞的一类细胞。"},{"k":"制备与诱导分化","t":"由一些多能遗传基因导入皮肤等受体细胞中制造，再进一步体外诱导分化，得到理想的细胞模型。"},{"k":"病人特异干细胞","t":"能获得病人或疾病特异的多能性干细胞，避免移植过程中的免疫排斥问题。"},{"k":"绕开伦理争议","t":"不涉及破坏人类胚胎，绕开了胚胎干细胞研究所带来的伦理问题。"},{"k":"疾病模型筛药","t":"掌握疾病特异 iPS 向相应功能细胞定向诱导的方法，可以此作模型研究发病机制、对现有药物作个体化评估、发现新的治疗靶点并筛选新药。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o150","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":["18"],"q":"色氨酸操纵子及其调控机制","points":[{"k":"操纵子结构","t":"由结构基因和控制部位组成：结构基因包括 E、D、C、B、A 五种；控制部位包括启动子区、操纵区、前导区和弱化子区。"},{"k":"阻遏负调控","t":"色氨酸含量高时，阻遏蛋白与色氨酸（阻遏物）结合后与操纵区紧密结合，抑制基因表达、减少色氨酸合成酶生成；色氨酸含量低时，不与色氨酸结合的阻遏蛋白不能结合操纵区，基因表达受到激活。"},{"k":"弱化子结构","t":"弱化系统由前导区及其内部的终止子（弱化子）构成，含 1、2、3、4 四段可彼此互补的序列：1、2 配对时 3、4 可配对，形成终止构型使转录终止；2、3 配对则可抑制 3、4 配对，形成抗终止构型，转录继续。"},{"k":"前导肽双Trp","t":"前导区第 10 位和第 11 位是相邻的两个色氨酸密码子：色氨酸浓度高时 tRNA^Trp 高、前导肽合成快，核糖体占据 1、2 位点，3、4 配对成终止构型；色氨酸浓度低时 tRNA^Trp 低、合成慢，核糖体停在 1 位点，2、3 配对抗终止，转录得以继续。"},{"k":"双级协同","t":"负控阻遏系统控制转录的起始，属粗调，可阻止非必需先导 mRNA 的合成，使合成系统更经济；弱化系统控制转录起始后是否继续，属细调，对环境变化反应更快。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o151","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":[],"q":"简述真核生物基因表达调控的三个水平研究技术","points":[{"k":"信号转导水平","t":"以配体刺激配合报告基因检测通路活性，用免疫沉淀、Western blot 查激酶磷酸化，用酵母双杂交钓取受体与级联组分。"},{"k":"转录因子水平","t":"用凝胶滞留（EMSA）与 DNaseⅠ 足迹定位结合序列，用 ChIP-chip/ChIP-seq 全基因组定位结合位点，用酵母单杂交克隆因子、报告基因测活性。"},{"k":"RNA剪接水平","t":"用 RT-PCR、Northern 检测剪接变体，体外剪接体系加突变 minigene 分析剪接元件，用 RNA-seq 找可变剪接事件，敲低剪接因子观察表型。"}],"note":"口径：依据《真题分类》资料原文；资料原文只列出三个水平的名称，具体研究技术按教材口径补足。","opts":[],"printed_answer":"","ref":true},{"id":"o152","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":[],"q":"简述原核生物转录后调控的类型","points":[{"k":"mRNA结构元件","t":"mRNA 自身结构元件（如 SD 序列、核糖开关等）对翻译起始的调节。"},{"k":"mRNA稳定性","t":"mRNA 的稳定性（降解速率）影响可翻译模板的数量，从而影响翻译水平。"},{"k":"调节蛋白阻遏","t":"调节蛋白质对 mRNA 的调控作用，类似于翻译阻遏。"},{"k":"反义RNA配对","t":"反义 RNA 与靶 mRNA 互补结合，阻断翻译或促其降解。"},{"k":"稀有密码子与重叠","t":"稀有密码子的分布影响翻译延伸；重叠基因共用序列，也影响翻译。"},{"k":"魔斑核苷酸","t":"魔斑核苷酸（如 ppGpp）水平同时影响转录和翻译。"}],"note":"口径：依据《真题分类》资料原文（原文八项并为六点：调节蛋白调控与翻译阻遏合为一点，稀有密码子与重叠基因合为一点）。","opts":[],"printed_answer":"","ref":true},{"id":"o153","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":[],"q":"为什么研究真核生物的基因表达调控比原核的困难？","points":[{"k":"基因组大且包装","t":"真核细胞含有更多的遗传信息，作为载体的 DNA 与组蛋白形成核小体结构，并在此基础上形成染色质。"},{"k":"多染色体协调","t":"遗传信息由多个染色体 DNA 携带，使各个基因的协调表达变得复杂。"},{"k":"转录翻译分离","t":"转录与翻译在时空上是分开的，使信使 RNA 的运输成为必要环节。"},{"k":"转录后加工复杂","t":"基因转录物运输到细胞质之前需经历复杂的后加工，许多被转录序列从来没有离开过细胞核。"},{"k":"分化细胞单产物","t":"高度分化的细胞经常合成大量的单一基因产物，而各种分化细胞仍含有一套完整的基因组。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o154","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":[],"q":"什么是表观调控，其主要形式有哪些？","points":[{"k":"不改序列调控","t":"定义：与 DNA 排列顺序改变无关，经染色质结构、组蛋白修饰、DNA 甲基化与非编码 RNA 调节基因表达的频率、速度与程度；不经生殖细胞传递，但可经细胞分裂传给子代。"},{"k":"DNA甲基化","t":"CpG 岛 C5 甲基化，招募 MBD、HDAC，抑制转录。"},{"k":"组蛋白修饰","t":"乙酰化激活；H3K4me3 激活；H3K9me3、H3K27me3 抑制；另有磷酸化、泛素化。"},{"k":"染色质重塑","t":"SWI/SNF 等耗 ATP 滑动或置换核小体，并进行组蛋白变体交换。"},{"k":"非编码RNA","t":"miRNA、siRNA、lncRNA（如 Xist）参与调控。"},{"k":"印记与失活","t":"还包括基因组印记、X 染色体失活与位置效应（端粒、着丝粒附近沉默）。"}],"note":"","opts":[],"printed_answer":""},{"id":"o155","subj":"631","chap":"五、RNA 的调控机制","type":"简答","years":["10"],"q":"snRNA、miRNA、gRNA 各是什么，简述","points":[{"k":"snRNA剪接体","t":"核内小 RNA，是真核生物转录后加工中 RNA 剪接体的主要成分，含 U 丰富故分 U1~U7 共 7 类；除 U3 在核仁参与 28S rRNA 的加工成熟外，其余 6 种在非核仁区核液中与蛋白质结合成 snRNP，参与 mRNA 的加工成熟。"},{"k":"miRNA抑翻译","t":"微 RNA：真核生物中内源的具调控功能的非编码 RNA，约 20~25 个核苷酸，参与控制机体生长发育，具保守性、组织特异性和时序性（故称小分子时序 RNA）；成熟 miRNA 由较长初级转录物经核酸酶剪切加工产生，随后组装进 RNA 诱导的沉默复合体（RISC），按互补程度指导降解靶 mRNA 或阻碍其翻译。"},{"k":"gRNA编辑模板","t":"向导 RNA：一种小型非编码 RNA，在 RNA 编辑中充当模板，可与 mRNA 前体配对并插入尿嘧啶（U），产生具有不同功能的 mRNA，是基因表达调控的重要方式。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o156","subj":"631","chap":"五、RNA 的调控机制","type":"简答","years":["19"],"q":"RNAi（RNA 干扰）使基因沉默机理","points":[{"k":"RNAi定义","t":"RNA 干扰：将一段短双链 RNA 序列导入机体或细胞中，使与之有同源序列的 mRNA 翻译受到抑制或降解，导致该基因表达活性受抑甚至完全消失的现象。"},{"k":"Dicer切割","t":"双链 RNA 一旦进入细胞，即被 Dicer 酶切割成 21~23 个核苷酸长的小分子干涉 RNA（siRNA）。"},{"k":"装配RISC","t":"切割产生的 siRNA 片段与一系列蛋白因子结合组成 RNA 诱导沉默复合体（RISC），激活的 RISC 通过碱基配对结合到与 siRNA 同源的 mRNA 上。"},{"k":"三种沉默方式","t":"可抑制该 mRNA 的翻译，或经 RISC 核酸酶介导其降解；也可与基因组序列配对并招募各种因子修饰染色质，引起异染色质化和基因沉默。"},{"k":"信号放大","t":"siRNA 还可通过 RNA 依赖的 RNA 聚合酶得到扩增、产生次级 siRNA，进一步放大干扰效应、扩大作用范围。"}],"note":"口径：依据《真题分类》资料原文；原文末尾「生物学意义及应用」部分 OCR 缺失，未补写。","opts":[],"printed_answer":"","ref":true},{"id":"o157","subj":"631","chap":"五、RNA 的调控机制","type":"简答","years":[],"q":"反义 RNA 的调节机制","points":[{"k":"阻前体成熟","t":"与 mRNA 前体结合，影响 mRNA 成熟及由核向胞浆的转运。"},{"k":"激活RNase降解","t":"与靶 RNA 结合后激活 RNase，加速靶 RNA 降解。"},{"k":"封起始密码子","t":"与 mRNA 的起始密码子结合，阻止翻译起始。"},{"k":"占据SD区","t":"作用于 SD 区，阻止核糖体与 mRNA 结合。"},{"k":"阻遏转录","t":"还可作用于 DNA，阻断或减轻转录。"}],"note":"","opts":[],"printed_answer":""},{"id":"o158","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["10"],"q":"为什么基因克隆时用 cDNA 文库而不是基因组文库","points":[{"k":"规模小好筛","t":"cDNA 文库只包含能转录表达的基因（功能基因），文库较小，只研究功能基因时可减少筛选工作、提高效率。"},{"k":"假阳性低","t":"cDNA 文库中假阳性基因的概率较低，阳性杂交信号一般都有意义，选出的阳性克隆即含目的基因，利于目的基因筛选。"},{"k":"无内含子可表达","t":"文库基因由成熟 mRNA 逆转录而成，不含内含子，适用于真核基因在原核生物中的直接表达。"},{"k":"留丰度差异","t":"cDNA 文库的基因存在丰度差别、具组织特异性，可用于研究细胞在不同分化时期、不同环境条件下的差异表达。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o159","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["19"],"q":"基因组文库与 cDNA 文库的区别","points":[{"k":"内容与大小","t":"基因组文库包含全部基因（有内含子、有调控序列），文库庞大；cDNA 文库只包含能转录表达的基因（无内含子、无调控序列），文库较小。"},{"k":"丰度与难易","t":"基因组文库基因不存在丰度差别、制备较简单；cDNA 文库基因存在丰度差别、制备较困难。"},{"k":"细胞间差异","t":"基因组文库在不同细胞间一般无差异；cDNA 文库不同细胞间存在差异，可用于分离差别表达的基因。"},{"k":"用途分工","t":"基因组文库用于分离特定基因片段、分析基因结构、研究基因表达调控、构建全基因组物理图谱和全基因组测序；cDNA 文库用于筛选目的基因、分析基因表达水平、大规模测序、基因芯片杂交等功能基因组学研究。"}],"note":"口径：依据《真题分类》资料原文（原文对照表已转成分点）。","opts":[],"printed_answer":"","ref":true},{"id":"o160","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["10","25"],"q":"如何实现外源基因的高效表达","points":[{"k":"强启动与终止","t":"选强启动子（如 tac）；选强的核糖体结合位点（SD 序列），并注意 SD 序列与起始密码子的间距及起始密码子上下游序列；选强终止子（mRNA 过长不仅耗能耗底物，还会干扰翻译及产物蛋白的结构）。"},{"k":"增强子与密码","t":"使用增强子提高转录效率；使用宿主偏爱的密码子提高翻译效率。"},{"k":"提高拷贝数","t":"增加表达载体在细胞内的拷贝数，一般选择松弛型质粒。"},{"k":"蛋白酶缺陷宿主","t":"挑选蛋白酶活性低或有缺陷的菌株作宿主，以免蛋白产物遭到降解。"},{"k":"减轻负荷与伴侣","t":"选用可诱导性表达载体，使宿主细胞生长与外源基因表达分开进行，避免代谢负荷过大；宿主细胞还要能高水平表达分子伴侣，促进新生肽链的正确折叠。"},{"k":"融合分泌复性","t":"以融合蛋白形式表达（与宿主高效表达基因 N 端序列融合）可防止降解、增加稳定性；以分泌蛋白形式表达（融合信号肽，分泌至周质或培养基）便于分离、提高得率；也可用包涵体形式表达后复性，或用基质附着区（MAR）使目的基因形成突环，阻断邻近序列的抑制作用。"}],"note":"口径：依据《真题分类》资料原文（原文十项并为六点）。","opts":[],"printed_answer":"","ref":true},{"id":"o161","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["13"],"q":"如何从野生菌中筛选营养缺陷型菌株","points":[{"k":"环丝氨酸富集","t":"环丝氨酸可杀死正在生长的细菌、对休止状态的细菌无影响；把混合菌悬液置于加环丝氨酸的培养基培养，大部分野生型被杀死，从而富集营养缺陷型细菌。"},{"k":"影印法检出","t":"稀释样品涂布完全培养基，长出菌落后用影印法转印到基本培养基培养；原平板有菌落而基本培养基上未长出的即为营养缺陷型。"},{"k":"夹层法检出","t":"稀释样品与基本培养基混匀倒平板，长出菌落后在皿底标记，再在原平板上倒一层完全培养基；培养后原来未长出、后来长出菌落的多为营养缺陷型菌株。"},{"k":"补：定缺陷类型","t":"在基本培养基上分别添加单一氨基酸、维生素等，观察哪一种能使菌株恢复生长，即可确定其缺陷类型。"}],"note":"口径：依据《真题分类》资料原文；末点（加单一营养物确定缺陷类型）为资料之外补充分点。","opts":[],"printed_answer":"","ref":true},{"id":"o162","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["19"],"q":"科学家发现一株耐盐植物，如何克隆？","points":[{"k":"基因产物途径","t":"分析耐盐基因蛋白质产物的氨基酸顺序，推断编码该蛋白的基因序列，设计一对特异引物经 PCR 扩增，或以探针通过分子杂交从文库中筛选分离出该基因。"},{"k":"转座子标签法","t":"利用转座子或 T-DNA 插入植物基因组获得突变体库，按表型找到耐盐基因失活的突变体，再以相应转座子/T-DNA 杂交取得突变基因部分序列，以此为探针筛出完整耐盐基因。"},{"k":"图位克隆法","t":"前提是基因定位，找出与目的基因最近的分子标记，以其为起点通过染色体步移分离并克隆该片段，最后经分析鉴定筛选出耐盐基因。"},{"k":"载体构建与连接","t":"后续按分子克隆路线：限制酶切目的基因与载体，以 T4 DNA 连接酶连接成重组载体。"},{"k":"转化与筛选","t":"导入植物后以抗性标记、PCR 与 Southern 杂交鉴定，再在高盐胁迫下筛选高表达株系。"}],"note":"口径：依据《真题分类》资料原文（前三点为原文三种取基因途径）；原文末写「后续同分子克隆路线」，载体构建与转化筛选按教材口径补全。","opts":[],"printed_answer":"","ref":true},{"id":"o163","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["18"],"q":"分子克隆路线","points":[{"k":"分取目的基因","t":"已知序列可从基因文库中筛选或人工合成；未知序列可按基因功能用图位克隆法、转座子标签法或分析表达产物筛选，获得 DNA 顺序后再人工合成扩增。"},{"k":"切开载体两臂","t":"选合适质粒载体，用限制酶切开，得到左、右两臂，以便分别与目的 DNA 片段两端连接。"},{"k":"体外连接","t":"目的基因与载体用 T4 DNA 连接酶连接形成重组体，也可人工添加接头后按黏性末端方式连接。"},{"k":"导入宿主细胞","t":"用电穿孔法或氯化钙法导入宿主细胞，得到转化细胞并作适当扩增。"},{"k":"筛选与鉴定","t":"按载体特征（抗药性、营养标记、蓝白斑显色）、目的基因特征（菌落原位杂交、PCR）或基因产物特征（免疫学法、活性与结构性质检测）筛选重组体。"}],"note":"口径：依据《真题分类》资料原文，按“分、切、接、转、筛”五步。原文未涉及农杆菌、显微注射等具体宿主途径，已删去。","opts":[],"printed_answer":"","ref":true},{"id":"o164","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["19"],"q":"蓝白斑筛选原理","points":[{"k":"载体遗传标记","t":"蓝白斑筛选是依据载体遗传特征筛选重组子的方法，属基因工程常用手段。"},{"k":"α肽段与C段","t":"β-半乳糖苷酶可分 α 肽段（N 端 146 个氨基酸）与 C 段；α 肽段基因在载体上并含不影响其 ORF 的多克隆位点（MCS），C 段基因在宿主大肠杆菌 DH5α 上。"},{"k":"互补产酶切X-gal","t":"二者在同一菌株表达时互补成有活性的酶，把无色 X-gal（5-溴-4-氯-3-吲哚-β-D-半乳糖苷）切成半乳糖与深蓝色 5-溴-4-靛蓝。"},{"k":"插入破坏ORF","t":"MCS 插入外源基因即改变 ORF，α 肽段被破坏、不能与 C 段互补，无酶活性故不显蓝，成白斑。"},{"k":"三色判读","t":"无载体宿主无法生存；空载体宿主可生存、产生蓝色菌落；带目的基因载体的宿主可生存、产生白色菌落。"}],"note":"口径：依据《真题分类》资料原文，三色判读按原文表格改写。","opts":[],"printed_answer":"","ref":true},{"id":"o165","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["19"],"q":"基因工程载体特点","points":[{"k":"自主复制起点","t":"有与宿主匹配的复制元件，能在宿主细胞中独立复制。"},{"k":"选择标记","t":"有易筛选的选择标记，如抗药性、营养标记、显色标记。"},{"k":"单一酶切位点","t":"有多个单一限制酶切位点（MCS），便于外源基因插入而不破坏必需区。"},{"k":"分子尽量小","t":"分子尽可能小，便于导入、扩增与回收。"},{"k":"使用安全","t":"宿主范围有限、不随意转移、不产生有害性状；常见载体有质粒、λ 噬菌体、cosmid、BAC、YAC。"}],"note":"资料无对应原答案：该条 ref_a 实为第三十五章考点汇总（分子克隆路线、光敏素 A 转基因流程等），未回答“载体特点”，故保留教材口径。","opts":[],"printed_answer":"","ref":false},{"id":"o166","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":[],"q":"简述将拟南芥光敏素 A 基因转入番茄中表达的过程","points":[{"k":"查库得序列","t":"拟南芥已测序完成，在基因文库中检索到光敏素 A 基因，获得序列信息。"},{"k":"探针筛文库","t":"按序列设计合成 ³²P 标记探针，用菌落原位杂交从文库中检出阳性克隆，取得目的基因。"},{"k":"PCR扩增鉴定","t":"按目的基因两端序列设计特异引物做 PCR 扩增，电泳分离后用 DNA 测序仪鉴定。"},{"k":"接Ti质粒","t":"按载体酶切位点设计接头，用 T4 DNA 连接酶把接头连到目的基因两端（T4 DNA 聚合酶只用于补平或削平末端）；限制酶切开载体得黏性末端，再连接成重组体。"},{"k":"电穿孔转农杆菌","t":"电穿孔法把 Ti 质粒转入农杆菌；按 Ti 质粒抗性标记在选择培养基筛出阳性重组细胞，挑单菌落液体扩大培养。"},{"k":"叶盘法转番茄","t":"取番茄无菌苗，打孔器取直径 0.5 cm 叶盘，预培养、愈伤诱导 1~2 天后菌液侵染 5~20 min，吸干共培养；选择培养基继代分化成试管苗，生根后移栽土壤。"}],"note":"","opts":[],"printed_answer":""},{"id":"o167","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":[],"q":"简述菌落原位杂交的操作过程","points":[{"k":"复印并标记","t":"将菌落复印到硝酸纤维素薄膜上，并做好与平板对应的标记。"},{"k":"碱裂解释放","t":"用 NaOH 处理膜上菌落，强碱裂解细胞释放内容物、降解 RNA，并使蛋白质与 DNA 变性。"},{"k":"中和并固定","t":"转清洗缓冲液浸泡，中和 NaOH、洗去菌体碎片与蛋白质；变性单链 DNA 固定于膜，80 ℃ 烘干。"},{"k":"封闭后杂交","t":"用鱼精子 DNA 温育，封闭未结合单链 DNA 的位点，再置同位素标记探针溶液中适温杂交。"},{"k":"洗膜自显影","t":"杂交后洗膜除去未杂交探针并烘干，放射自显影，曝光黑点即杂交菌落，回找平板对应菌落扩大培养。"}],"note":"","opts":[],"printed_answer":""},{"id":"o168","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":[],"q":"如何从基因文库中筛选并扩增已知序列的目的基因？","points":[{"k":"探针原位杂交","t":"按目的基因已知序列设计一对荧光标记探针，用菌落原位杂交从文库筛出含该基因的阳性克隆。"},{"k":"酶切取基因","t":"裂解细胞、提取总 DNA，用相应核酸内切酶把目的基因切离。"},{"k":"PCR特异扩增","t":"按已知序列设计一对特异引物，PCR 特异扩增目的 DNA，扩增片段纯化。"},{"k":"测序鉴定","t":"纯化片段经 DNA 序列分析鉴定，最终确认并扩增出目的基因。"}],"note":"","opts":[],"printed_answer":""},{"id":"o169","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":[],"q":"请设计方案说明如何通过膜泡运输原理将某一药物直接作用在特定的靶细胞上","points":[{"k":"融合基因设计","t":"把多肽药物的编码基因与靶细胞特异性内吞物基因（如运铁蛋白基因）融合。"},{"k":"融合蛋白表达","t":"使融合基因以融合蛋白形式表达，药物部分与内吞引导部分共存于同一分子。"},{"k":"受体介导内吞","t":"给药时借内容物与靶细胞间的特异性作用，以内吞小泡形式把药物摄入靶细胞，实现靶向用药；构建路线参照分子克隆原理。"}],"note":"","opts":[],"printed_answer":""},{"id":"o170","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["10"],"q":"SDS-PAGE","points":[{"k":"SDS掩盖电荷","t":"SDS（十二烷基硫酸钠）为阴离子、带很高的负电荷，可掩盖不同蛋白质间原有的电荷差别。"},{"k":"变性成棒状","t":"SDS 是变性剂，破坏蛋白质分子中的氢键与疏水作用，使大多数蛋白质伸展成同样的棒状。"},{"k":"按分子量分离","t":"分离完全基于蛋白质分子质量的不同；由于凝胶的分子筛效应，迁移率与分子质量的对数呈线性关系。"},{"k":"标准曲线测Mr","t":"用已知分子质量标准蛋白作标准曲线，可由未知蛋白的迁移率求出其分子质量。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"o171","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["10"],"q":"DNA 与蛋白质相互作用的研究方法","points":[{"k":"酵母单杂交","t":"顺式作用元件构建到启动子上游、报告基因接在启动子下游，待测转录因子 cDNA 与转录激活结构域（AD）融合导入酵母，因子结合元件即激活启动子使报告基因表达。"},{"k":"凝胶滞缓EMSA","t":"体外法：³²P 标记探针与细胞提取物共温育，蛋白结合后相对分子质量增大、电泳受阻滞变慢，放射自显影显示中间部位的滞后带。"},{"k":"DNA足迹法","t":"蛋白结合处受保护不被 DNase 破坏，在 DNA 上留下“足迹”，可分离专一结合片段并经测序确定具体序列。"},{"k":"染色质免疫沉淀","t":"ChIP 通过抗原-抗体特异性识别把转录因子-DNA 复合物沉淀分离，进一步研究二者的相互作用。"}],"note":"口径：依据《真题分类》资料原文。资料原文把 EMSA 写作“SDS-PAGE 电泳”，已更正为非变性聚丙烯酰胺凝胶电泳（EMSA 体系不加 SDS，否则复合物解离）。","opts":[],"printed_answer":"","ref":true},{"id":"o172","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["10"],"q":"影响分子生物学（基因工程）发展的重大技术发明之类的，列举 8 个以上","points":[{"k":"限制酶与载体","t":"限制性内切酶的发现与 DNA 重组技术；质粒、噬菌体克隆载体。"},{"k":"测序与PCR","t":"Sanger 双脱氧测序；PCR 技术。"},{"k":"印迹与杂交","t":"Southern、Northern、Western 印迹与分子杂交。"},{"k":"芯片与RNAi","t":"DNA 芯片与转录组学；RNAi 与基因沉默。"},{"k":"NGS与基因编辑","t":"二代测序（NGS）；CRISPR-Cas9 基因编辑。"},{"k":"蛋白与抗体","t":"双向电泳＋质谱的蛋白质组学；单克隆抗体与杂交瘤技术；逆转录酶与 cDNA 技术。"}],"note":"资料无对应原答案：该条 ref_a 仅有“（参考知识点总结第三十五章、第四点）”一行标注，无任何答案内容，故保留教材口径。","opts":[],"printed_answer":"","ref":false},{"id":"o173","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["18"],"q":"检测核酸提取物质量的方法","points":[{"k":"琼脂糖分子筛","t":"琼脂糖熔化再凝固后形成带孔隙的固体基质，具分子筛效应，孔隙对不同大小 DNA 有不同阻碍。"},{"k":"迁移率反比","t":"DNA 在电场中的迁移速度与其自身分子量的对数值成反比。"},{"k":"标准曲线求量","t":"已知分子量核酸电泳，按迁移率绘制标准曲线，即可由待测核酸的迁移率求出其分子质量。"},{"k":"补：纯度与浓度","t":"提取物质量还包括纯度与完整度：需以 A260/A280 比值判断蛋白与酚的残留，并以电泳条带是否弥散、有无降解判断核酸完整性。"}],"note":"口径：依据《真题分类》资料原文（原文只讲琼脂糖电泳测分子质量）。补：纯度与浓度为按教材口径补充，原资料未涉及。","opts":[],"printed_answer":"","ref":true},{"id":"o174","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["18"],"q":"Southern、Northern、Western 印迹法分别测定什么，以及 Southern 印迹法的原理及步骤","points":[{"k":"三者检测对象","t":"Southern 测 DNA、用标记核酸探针；Northern 测 RNA、用核酸探针；Western 测蛋白质，“探针”是抗体、显色用标记二抗。"},{"k":"Southern流程","t":"限制酶消化 DNA→琼脂糖电泳分开片段→加碱变性并原位解链→转移至尼龙膜或硝酸纤维素膜→干烤或紫外固定→预杂交封闭位点→与标记探针杂交→洗去未杂交探针→放射自显影或酶显色。"},{"k":"Southern原理","t":"具一定同源性的两条核酸单链在一定条件下按碱基互补配对形成双链，杂交高度特异，配合灵敏的检测可绘制 DNA 限制图谱。"},{"k":"Northern要点","t":"变性条件下琼脂糖电泳使 RNA 按大小分离，其后同 Southern 原理杂交；变性不用强碱（强碱使 RNA 降解），用于检测转录水平表达。"},{"k":"Western要点","t":"SDS-PAGE 分离蛋白→原位转移至固相载体（如硝酸纤维素膜）→高浓度蛋白溶液封闭→与一抗起免疫反应→与酶或同位素标记二抗反应→底物显色或自显影，检测翻译水平表达。"}],"note":"口径：依据《真题分类》资料原文，三种印迹的概念、原理与应用均据原文压缩。","opts":[],"printed_answer":"","ref":true},{"id":"o175","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["08","19"],"q":"蛋白质组学","points":[{"k":"定义与本质","t":"以蛋白质组（一种基因组所表达的全套蛋白质）为研究对象，研究细胞、组织或生物体蛋白质组成及其变化规律；本质是在大规模水平上研究蛋白质表达水平、翻译后修饰与蛋白-蛋白相互作用。"},{"k":"研究内容","t":"蛋白质鉴定、蛋白质翻译后修饰、蛋白质功能的确定、蛋白质与蛋白质间的相互作用。"},{"k":"双向电泳分离","t":"第一维等电聚焦按 pI、第二维 SDS-PAGE 按分子质量分离，是分离大量混合蛋白质组分最有效的方法。"},{"k":"质谱鉴定","t":"一级质谱即肽指纹图谱（PMF），与数据库比对确定蛋白信息；二级质谱即肽段碎片指纹（PFF）进一步打碎代表性肽段；串联质谱可按相邻肽段质量差确定氨基酸序列（亮氨酸与异亮氨酸不能区分）。"},{"k":"流程与2D-DIGE","t":"流程：二维电泳分离→取下目的蛋白点→酶切得肽段→高效液相层析分离→质谱分析→图谱与数据库比对。2D-DIGE 用 Cy2、Cy3、Cy5 分别标记不同样本，混合后同一块胶电泳、三次扫描，并以全部样本混合物为内标，使胶间匹配与定量更精确。"}],"note":"口径：依据《真题分类》资料原文（练习册 P126）。资料原文作“经限制酶切割获得酶切肽段”，应为蛋白酶（如胰蛋白酶）酶切，已更正。","opts":[],"printed_answer":"","ref":true},{"id":"o176","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["19"],"q":"核酸分子杂交  原理及应用","points":[{"k":"变性成单链","t":"待测核酸经变性形成单链，在低于变性温度（Tm）20~30 ℃ 时与探针杂交。"},{"k":"探针标记杂交","t":"加入以放射性同位素（³²P）或生物素、地高辛等非放射性物质标记的、与待测核酸有一定同源性的单链 DNA 探针，按碱基配对原则形成双链。"},{"k":"信号检测","t":"通过放射自显影或发光、酶等显示系统检测待测核酸片段，方法高度灵敏、高度特异。"},{"k":"应用范围","t":"用于克隆基因的筛选、酶切图谱制作、基因组中特定基因序列的定性定量检测与疾病诊断；医学上已用于遗传病基因诊断、恶性肿瘤基因分析、传染病病原体检测。"}],"note":"口径：依据《真题分类》资料原文。杂交温度原文为“低于 Tm 20~30 ℃”，旧稿 5~25 ℃ 已按原文更正。","opts":[],"printed_answer":"","ref":true},{"id":"o177","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["19"],"q":"PCR 技术及应用","points":[{"k":"原理与体系","t":"按待扩增片段两端的核苷酸序列设计一对互补的寡核苷酸引物，在过量引物、过量 dNTP、耐热 Taq DNA 聚合酶与模板的体系中，经高温变性、低温退火、适温延伸三步循环，使模板 DNA 几何级数扩增。"},{"k":"三步循环","t":"高温变性使 DNA 解链，低温退火使引物与模板结合，适温延伸合成新链，三步构成一个循环周期。"},{"k":"合成基因与探针","t":"设计专一引物即可大量扩增微量 DNA，用于基因扩增、医学检测、刑侦与亲缘鉴定；加入不等量引物（如 60:1）作不对称 PCR，可线性扩增制备单链探针。"},{"k":"测序与RT-PCR","t":"第二代测序通过 PCR 建库实现高通量测序；RT-PCR 以 cDNA 为模板大量扩增，用于分析基因转录产物、构建 cDNA 文库、克隆特异 cDNA 与合成探针。"},{"k":"定量与突变","t":"RQ-PCR 可用 SYBR GreenⅠ 非特异结合双链，或用 TaqMan 探针借聚合酶外切酶活性解除淬灭而特异定量；易错 PCR、DNA 改组与 PCR 诱变可产生并分析基因突变。"},{"k":"重组与未知序列","t":"重组 PCR 只需 3 个引物即可连接无合适酶切位点的片段；反向 PCR、染色体步移、锅柄 PCR、锚定 PCR 用于扩增未知序列，随机引物 PCR（RAPD）可比较基因组差异。"}],"note":"口径：依据《真题分类》资料原文（练习册 P122），原文九类应用压缩为四组，未删得分点。","opts":[],"printed_answer":"","ref":true},{"id":"o178","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["19"],"q":"【图示题·原题含图】一个电泳图片，分出细菌 DNA，PUA 质粒 DNA 在哪条泳道","points":[{"k":"质粒位于前沿","t":"质粒 DNA 相比细菌 DNA 一般分子量较小，在电场中迁移率较大、跑在最前方，故距电泳起点最远的条带即代表质粒 DNA。"},{"k":"三构型分带","t":"质粒提取过程中受机械力、酸碱度、试剂等影响，可使质粒 DNA 链发生不同程度断裂，故提取物中常有共价闭合环状（超螺旋）、线性、开环状三种构型。"},{"k":"超螺旋最快","t":"共价闭合环状空间位阻最小、跑得最快且条带最亮；开环状位阻最大、最慢；线性居中，故靠后较暗的条带由线性与开环状组成。"}],"note":"口径：依据《真题分类》资料原文（原文在「断」字处截断）；第 2、3 点按教材口径补全，具体泳道编号须对照原图确认。","opts":[],"printed_answer":"","ref":true},{"id":"o179","subj":"631","chap":"七、分子生物学技术","type":"简答","years":[],"q":"简述 PCR 合成 DNA 和体内 DNA 的复制的异同","points":[{"k":"相同点四条","t":"都以 dNTP 为原料、遵循碱基互补配对；都需 DNA 聚合酶且沿 5'→3' 延伸；都需模板、均按半保留方式；都需引物与 Mg²⁺。"},{"k":"场所与温度","t":"体内在细胞中、体温恒定；PCR 在体外、高温并温度循环变化。"},{"k":"酶与解链","t":"体内用 DNA 聚合酶（热稳定性低、校正功能强），靠拓扑异构酶与解链酶部分解链；PCR 用 Taq（热稳定性高、校正功能低），靠热变性完全解链。"},{"k":"引物与方式","t":"体内引物由引物酶合成、为半不连续复制；PCR 引物人工合成、设计要求高，两条链均连续复制。"}],"note":"","opts":[],"printed_answer":""},{"id":"o180","subj":"631","chap":"七、分子生物学技术","type":"简答","years":[],"q":"简述蛋白质相互作用的研究方法","points":[{"k":"免疫共沉淀","t":"用抗体沉淀靶蛋白，与之结合的互作蛋白一同沉淀，再用 Western 或质谱鉴定。"},{"k":"酵母双杂交","t":"诱饵与猎物分别融合 DNA 结合域（BD）与激活域（AD），互作则激活报告基因，可筛文库并比较互作强弱。"},{"k":"亲和拉下","t":"GST/His pull-down 把诱饵蛋白固定于亲和树脂，捕获裂解液中的互作蛋白。"},{"k":"SPR测动力学","t":"表面等离子共振实时测定结合动力学常数 Ka、Kd 与亲和力 KD。"},{"k":"FRET与BiFC","t":"FRET、双分子荧光互补（BiFC）在活细胞内验证互作与空间定位。"},{"k":"交联与展示","t":"补充手段：交联＋质谱、噬菌体展示、蛋白质芯片。"}],"note":"资料无对应原答案，按教材口径：资料该条为「DNA 与蛋白质相互作用的研究方法」（酵母单杂交、EMSA、DNA 足迹法、ChIP），与本题问的蛋白质-蛋白质互作不是同一件事，故不采用。","opts":[],"printed_answer":"","ref":false},{"id":"n0000","subj":"880","chap":"第七章 核酸","type":"考点","years":["24"],"q":"Tm 值","points":[{"k":"答案","t":"Tm 为 DNA 的熔解温度，指双链解开一半、A260 增色效应达到最大值一半时的温度；GC 含量越高、离子强度越大，Tm 越高。"}],"note":"原卷题干只留考点关键词 Tm 值、无选项，按考点作答。","opts":[],"printed_answer":""},{"id":"n0001","subj":"880","chap":"第四章 蛋白质","type":"考点","years":["24"],"q":"蛋白质二级结构","points":[{"k":"二级结构定义","t":"指蛋白质分子中某一段肽链的局部空间结构，即该段肽链主链骨架原子的相对空间位置，不包括氨基酸残基侧链构象的内容和与其他肽链的关系。"},{"k":"维系力","t":"主要借主链原子之间形成的氢键维系构象稳定。"},{"k":"常见形式","t":"主要有 α 螺旋、β 折叠、β 转角、无规卷曲等形式。"}],"note":"口径：依据《真题分类》资料原文（名词解释）。","opts":[],"printed_answer":"","ref":true},{"id":"n0002","subj":"880","chap":"综合","type":"考点","years":["24"],"q":"查格夫规则的计算","points":[{"k":"答案","t":"按查格夫规则 A=T、G=C，故 A+G=T+C；若 A 占 30%，则 T=30%、G=C=20%。"}],"note":"原卷无选项与具体数据，按规则给出通式与示例。","opts":[],"printed_answer":""},{"id":"n0003","subj":"880","chap":"综合","type":"考点","years":["24"],"q":"酶催化和什么没关","points":[{"k":"答案","t":"与反应平衡无关。酶只降低活化能、加速达到平衡，不改变平衡常数、ΔG 和产物与底物的终态比例。"}],"note":"原卷选项缺失，按“酶催化与什么无关”的常规考法作答。","opts":[],"printed_answer":""},{"id":"n0004","subj":"880","chap":"第三章 氨基酸","type":"考点","years":["24"],"q":"纸电泳（给了几个氨基酸，问谁跑得快）","points":[{"k":"答案","t":"酸性氨基酸（Asp、Glu）跑得最快。电泳速度取决于荷质比，pH 6~7 时二者等电点最低、带负电荷最多，向正极泳动最快。"}],"note":"原卷所给氨基酸种类未保存，按等电点最低者泳动最快的通例作答。","opts":[],"printed_answer":""},{"id":"n0005","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"考点","years":["24"],"q":"DNA 连接酶在（DNA 重组，修饰，复制）中哪一个不涉及","points":[{"k":"答案","t":"不涉及 DNA 修饰。DNA 连接酶只催化 3′-OH 与 5′-磷酸形成磷酸二酯键，参与复制、重组和修复；碱基甲基化等修饰由修饰酶完成。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0006","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["24"],"q":"CO 中毒的原理。","points":[{"k":"抢占血红素","t":"CO 与血红蛋白（Hb）的亲和力约为 O₂ 的 210 倍，占据 Fe²⁺ 第六配位位点，形成碳氧血红蛋白（CO-Hb），结合后极难解离。"},{"k":"锁定松弛构象","t":"CO 结合使 Hb 稳定于 R 态，氧解离曲线左移；剩余亚基对 O₂ 亲和力升高，已结合的 O₂ 在外周难以释放。"},{"k":"携氧释氧双降","t":"既减少可结合 O₂ 的血红素数目（携氧量下降），又降低组织处 O₂ 的释放效率，造成组织缺氧。"},{"k":"抑制呼吸链酶","t":"CO 还抑制线粒体细胞色素 c 氧化酶（复合体Ⅳ），阻断电子传递与氧化磷酸化，加重细胞窒息。"},{"k":"高压氧置换","t":"治疗用 2~3 个大气压的高压氧，提高血氧分压竞争性置换 CO、加速其排出，同时以物理溶解氧维持组织供氧。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0007","subj":"880","chap":"第一章 糖类","type":"简答","years":["24"],"q":"试从营养物质代谢的角度解释为什么减肥者要减少糖类物质的摄入量（写出有关的代谢途径及其细胞定位、主要反应、关键酶）。","points":[{"k":"高糖促脂合成","t":"血糖升高→胰岛素↑，肝细胞胞质中糖酵解（己糖激酶/葡糖激酶、磷酸果糖激酶-1、丙酮酸激酶）产生的乙酰 CoA 经乙酰 CoA 羧化酶（ACC）→丙二酰 CoA→脂肪酸合成，再与甘油-3-磷酸酯化成脂肪。"},{"k":"糖氧化抑制脂解","t":"糖充足时丙酮酸脱氢酶复合体（线粒体基质）产乙酰 CoA，草酰乙酸充足，乙酰 CoA 全部进入柠檬酸循环（柠檬酸合酶、异柠檬酸脱氢酶）；同时胰岛素抑制激素敏感脂酶（HSL），脂肪动员被抑制。"},{"k":"低糖启动脂解","t":"减少糖摄入→胰岛素↓、胰高血糖素↑→腺苷酸环化酶 cAMP↑→蛋白激酶 A 磷酸化激活 HSL，甘油三酯水解为甘油和游离脂肪酸；肉碱棕榈酰转移酶Ⅰ（CPT-Ⅰ）活性升高，脂肪酸进入线粒体基质进行 β-氧化。"},{"k":"糖异生净耗能","t":"糖不足时肝以生糖氨基酸、甘油、乳酸为原料糖异生（丙酮酸羧化酶、磷酸烯醇式丙酮酸羧激酶、果糖-1,6-二磷酸酶、葡糖-6-磷酸酶，线粒体+胞质），每生成 1 mol 葡萄糖净耗 6 mol ATP，本身即为耗能过程。"},{"k":"酮体排出浪费","t":"低糖高脂使乙酰 CoA 过剩、草酰乙酸不足，肝线粒体 HMG-CoA 合酶生成酮体；酮体随尿排出带走部分碳源与能量，进一步造成能量负平衡。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0008","subj":"880","chap":"第十七章 核苷酸代谢","type":"简答","years":["24"],"q":"别嘌呤醇治疗痛风的原理。","points":[{"k":"结构类似物","t":"别嘌呤醇是次黄嘌呤的异构体（N7 与 C8 互换），可与黄嘌呤氧化酶（XO）的底物结合位点结合。"},{"k":"抑制黄嘌呤氧化酶","t":"竞争性抑制 XO；本身被 XO 氧化为别黄嘌呤（oxypurinol），后者与酶结合更牢固、解离极慢，形成持久的慢结合抑制。"},{"k":"前体堆积易排","t":"次黄嘌呤→黄嘌呤→尿酸的通路受阻，次黄嘌呤与黄嘌呤堆积；二者水中溶解度远高于尿酸，易经肾排出而不易结晶。"},{"k":"血尿酸下降","t":"尿酸生成减少、血尿酸浓度下降，减少尿酸盐结晶在关节、肌腱和肾小管的沉积，从而缓解痛风发作与痛风肾。"},{"k":"从头合成受抑","t":"别嘌呤醇经 HGPRT 转为别嘌呤醇核苷酸，抑制 PRPP 酰胺转移酶，减少嘌呤从头合成，作用更彻底。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0009","subj":"880","chap":"第八章 抗生素与激素","type":"简答","years":["24"],"q":"Ⅱ型糖尿病。","points":[{"k":"定义与占比","t":"Ⅱ型糖尿病是以胰岛素抵抗为主、伴相对胰岛素分泌不足的慢性高血糖综合征，占糖尿病总数的 90% 以上，多在 40 岁后发病。"},{"k":"胰岛素抵抗","t":"靶细胞胰岛素受体及 IRS-1/PI3K 信号减弱，GLUT4 转位障碍，肌肉与脂肪摄取葡萄糖减少；肝糖输出（糖异生）反而增加。"},{"k":"β细胞衰竭","t":"早期代偿性高胰岛素血症，长期抵抗使 β 细胞负荷过重，分泌功能由代偿走向失代偿，血糖持续升高。"},{"k":"代谢紊乱表现","t":"高血糖、糖化血红蛋白升高；脂代谢紊乱（高甘油三酯、低 HDL）、腹型肥胖；多元醇通路与糖基化终产物增多。"},{"k":"诊断与并发症","t":"空腹血糖≥7.0 mmol/L 或 OGTT 2 h≥11.1 mmol/L 即可诊断；慢性并发症为微血管（视网膜、肾、神经）与大血管（心、脑、下肢）病变。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0010","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["24"],"q":"蛋白质分离纯化。给了一个表格，给了四个蛋白质，其中四个的饱和硫酸铵溶液的沉淀率，其中三个蛋白质的相对分子质量、等电点，采用不同的方法分离纯化。","points":[{"k":"分级盐析","t":"按表中各蛋白沉淀所需的硫酸铵饱和度分段加盐：先加到低饱和度弃沉淀，再升至目标饱和度收集沉淀，利用盐析使不同蛋白在不同饱和度先后析出。"},{"k":"透析除盐","t":"沉淀用缓冲液复溶后透析或超滤，去除硫酸铵，避免高盐干扰后续层析与电泳。"},{"k":"离子交换层析","t":"按等电点差异选 pH：pH>pI 的蛋白带负电结合 DEAE-纤维素（阴离子交换），pH<pI 的结合 CM-纤维素（阳离子交换），用盐梯度洗脱。"},{"k":"凝胶过滤","t":"按相对分子质量差异分离：大分子不能进入凝胶孔被排阻而先出柱，小分子进入孔内滞留而后出柱。"},{"k":"电泳鉴定","t":"SDS-PAGE 按 Mr 核对条带位置与纯度，结合纯化倍数与回收率评价分离效果。"}],"note":"原卷附表数值（各蛋白沉淀率、Mr、pI）未随题保留，无法给出具体饱和度与洗脱条件，只能按各项参数所对应的分离原理作答。","opts":[],"printed_answer":""},{"id":"n0011","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["24"],"q":"为什么两极动物的腿和蹄部分含有大量不饱和脂肪酸（不饱和脂肪酸对北极动物生活的影响）。","points":[{"k":"熔点显著降低","t":"不饱和脂肪酸顺式双键使碳链弯折、分子间范德华力减弱，熔点降低，极寒条件下仍保持液态，防止腿蹄脂肪僵硬、关节活动受限。"},{"k":"维持膜流动性","t":"掺入膜磷脂后降低膜脂相变温度，使膜在低温下仍处于液晶态，保证离子泵、通道与受体蛋白的正常构象与功能。"},{"k":"阻碍紧密堆积","t":"顺式双键造成空间障碍，脂肪酸不能像饱和链那样紧密排列，避免低温下结晶损伤组织。"},{"k":"高效供能与保温","t":"脂肪酸碳氢比例高、单位质量产能约为糖的 2 倍，β-氧化可长期供能；皮下与肢端脂肪层同时起绝热保温作用。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0012","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["24"],"q":"有氧运动为什么能够减肥？","points":[{"k":"能量需求增加","t":"运动使肌细胞 ATP 大量消耗，AMP/ADP 升高，激活 AMP 依赖蛋白激酶（AMPK），开启分解代谢。"},{"k":"脂肪动员增强","t":"儿茶酚胺升高→cAMP-蛋白激酶 A→磷酸化激活激素敏感脂酶（HSL），脂肪组织甘油三酯水解为甘油和游离脂肪酸。"},{"k":"β氧化加速","t":"AMPK 磷酸化失活 ACC，丙二酰 CoA 下降，解除对 CPT-Ⅰ 的抑制，脂肪酸进入线粒体基质 β-氧化，生成大量乙酰 CoA。"},{"k":"有氧彻底氧化","t":"供氧充足时乙酰 CoA 经柠檬酸循环与氧化磷酸化彻底氧化为 CO₂ 和 H₂O，运动中还可见 UCP3 上调，部分能量以热形式散失。"},{"k":"运动后持续耗能","t":"糖原补充、乳酸清除与体温恢复使运动后过量氧耗（EPOC）持续升高；长期训练增加肌肉量，提高基础代谢率。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0013","subj":"880","chap":"第十四章 氧化磷酸化","type":"简答","years":["24"],"q":"鱼藤酮和抗霉素哪个毒性强。","points":[{"k":"答案抗霉素强","t":"抗霉素 A 的毒性显著强于鱼藤酮：前者阻断呼吸链的公共通路，后者仅阻断复合体Ⅰ、可被琥珀酸氧化旁路。"},{"k":"鱼藤酮阻复合体Ⅰ","t":"鱼藤酮与 NADH-泛醌还原酶的泛醌结合位点结合，阻断铁硫中心到泛醌的电子传递，NADH 不能氧化。"},{"k":"抗霉素阻复合体Ⅲ","t":"抗霉素 A 结合细胞色素 bc₁ 复合体的 Qi 位点，阻断半醌循环中电子由 b_H 向泛醌的传递，泛醇不能被氧化。"},{"k":"旁路决定毒性","t":"复合体Ⅱ（琥珀酸脱氢酶）可将 FADH₂ 的电子直接交给泛醌，绕过复合体Ⅰ，故鱼藤酮中毒时仍能部分氧化；抗霉素 A 位于泛醌之后的公共出口，复合体Ⅰ、Ⅱ来源的电子均被堵死，ATP 生成近乎完全停止。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0014","subj":"880","chap":"第七章 核酸","type":"简答","years":["24"],"q":"提取某个细胞中全部的 RNA 如何检测其(1)完整性(2)纯度(3)浓度，并给出判断依据;","points":[{"k":"电泳判完整性","t":"甲醛变性琼脂糖凝胶电泳分离，真核总 RNA 应见清晰的 28S 与 18S rRNA 条带，28S/18S 亮度比约 2:1、无低分子弥散拖尾即完整；Agilent 2100 测 RIN≥7 为合格。"},{"k":"比值判纯度","t":"NanoDrop 测 A260/A280 应在 1.8~2.1（约 2.0），低于 1.8 提示蛋白或酚污染；A260/A230 应≥2.0，偏低提示胍盐、糖或多糖残留。"},{"k":"吸光算浓度","t":"A260=1 相当于 40 μg/mL RNA，浓度 C=A260×40×稀释倍数（μg/mL）；Qubit 荧光法不受降解片段干扰，结果更准。"},{"k":"防降解与去 DNA","t":"全程低温、RNase-free 耗材与 RNase 抑制剂；若 A260/A280>2.1 且电泳见高分子带，提示 DNA 污染，可用 DNase Ⅰ 消化后复查。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0015","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["24"],"q":"脂肪酸氧化也可以放出大量能量，为什么食品营养学中还是将碳水化合物作为主要能源物质","points":[{"k":"供能速率快","t":"糖酵解与三羧酸循环酶系活性高、通路短，单位时间 ATP 输出功率大，可迅速满足应激与运动需要；脂肪动员与 β-氧化启动慢。"},{"k":"缺氧仍可供能","t":"葡萄糖可经无氧酵解净产 2 ATP，红细胞无 mitochondria、视网膜与脑在缺氧时依赖糖；脂肪酸 β-氧化与 TCA 必须有氧。"},{"k":"氧热价更高","t":"每消耗 1 L O₂，糖约产 5.0 kcal、脂肪约 4.7 kcal；供氧受限时糖的能量转化更经济，呼吸商为 1.0 也便于完全氧化。"},{"k":"代谢枢纽地位","t":"葡萄糖代谢的中间物是氨基酸、核苷酸、脂肪酸与甘油合成的共同前体，且脑、红细胞等必须依赖血糖，糖不可完全被替代。"},{"k":"过量脂肪有害","t":"脂肪大量氧化产生乙酰 CoA 过剩，生成酮体可引起酮症酸中毒；高脂膳食还加重血脂紊乱，故不作为主要能源。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0019","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["00"],"q":"什么是蛋白质的变性和复性？","points":[{"k":"变性定义","t":"在高温、强酸强碱、尿素、重金属、有机溶剂等理化因素作用下，蛋白质的空间构象被破坏，理化性质改变、生物学活性丧失，但肽键不断裂、一级结构不变。"},{"k":"变性表现","t":"溶解度下降、黏度升高、紫外吸收红移、旋光性改变、易被蛋白酶水解，且不能再与原有抗体或配体结合。"},{"k":"复性定义","t":"去除变性因素后，变性程度较轻的蛋白质可自发重新折叠，恢复天然构象与生物活性，如核糖核酸酶 A 经尿素与 β-巯基乙醇变性后透析复性。"},{"k":"一级结构决定构象","t":"复性说明蛋白质的高级结构由氨基酸序列决定（Anfinsen 原则）；变性过度、肽链缠绕聚集则不可逆，如煮熟的鸡蛋清。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0020","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":["00"],"q":"请简述糖代谢紊乱可能造成的疾病","points":[{"k":"定义与糖尿病","t":"糖代谢紊乱指调节葡萄糖、果糖、半乳糖、糖原等代谢的激素或酶的结构、功能、浓度异常，或组织器官的病理生理变化而造成疾病，主要指血糖浓度过高或过低；其中糖尿病由胰岛素缺乏或生物效应降低引起血糖升高，可致血管、神经等慢性并发症。"},{"k":"低血糖症","t":"胰岛素分泌过多、胰高血糖素与肾上腺素分泌减少或长期饥饿等使血糖降低，出现全身瘫软无力，甚至昏迷。"},{"k":"半乳糖血症","t":"缺乏 1-磷酸半乳糖尿苷酰转移酶，半乳糖不能转为葡萄糖而在血中积累，晶状体内半乳糖还原为半乳糖醇致晶状体混浊，引起白内障。"},{"k":"乳糖不耐受与果糖不耐","t":"缺乏乳糖酶时乳糖不能被消化吸收，在小肠腔内产生高渗透效应和有毒物质，致腹胀、恶心、绞痛、腹泻；果糖浓度过高使 1-磷酸果糖积累、肝中无机磷酸大量消耗、ATP 浓度下降、糖酵解加速，产生大量乳酸而致酸中毒。"},{"k":"糖原贮积病","t":"糖原分解过程中某些酶缺乏，使糖原在肝、肌肉和肾等脏器大量堆积，造成器官肥大及功能障碍。"},{"k":"丙酮酸代谢障碍","t":"丙酮酸脱氢酶或丙酮酸羧化酶先天性缺乏使丙酮酸代谢受阻，血中丙酮酸及乳酸等堆积，引起神经系统病变（失调、动作幼稚、智力减退、痴呆）及乳酸性酸中毒。"}],"note":"口径：依据《真题分类》资料原文（原文七条，此处将乳糖不耐受与果糖不耐并为一题点，合计六点）。","opts":[],"printed_answer":"","ref":true},{"id":"n0021","subj":"880","chap":"第九章 生物膜","type":"简答","years":["00"],"q":"请列举生物膜有哪些生理功能","points":[{"k":"界膜与区室化","t":"围成细胞边界并分隔细胞器，使不同代谢途径在独立区室中进行、互不干扰，如线粒体基质与胞质的分工。"},{"k":"物质运输","t":"通过简单扩散、通道与载体介导的易化扩散、离子泵与协同转运完成主动运输，以及胞吞、胞吐进行大分子转运。"},{"k":"信息传递","t":"膜上受体接受激素、递质与细胞因子信号，经 G 蛋白、第二信使或受体酪氨酸激酶级联放大并传入细胞内。"},{"k":"能量转换","t":"线粒体内膜进行氧化磷酸化、叶绿体类囊体膜进行光合磷酸化，将电子传递的自由能转为 ATP 与跨膜质子梯度。"},{"k":"识别黏附与支架","t":"糖蛋白、糖脂的糖链参与细胞识别、免疫与血型决定；膜蛋白与细胞骨架相连，为酶提供有序排列的支架。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0022","subj":"880","chap":"第七章 核酸","type":"简答","years":["00"],"q":"DNA 作为遗传物质，其直接和间接证据是什么？","points":[{"k":"直接证据-转化","t":"肺炎双球菌的转化实验：无毒 R 型可被加热杀死的 S 型转化为有毒型，说明存在转化因子。"},{"k":"直接证据-噬菌体","t":"噬菌体侵染细菌的实验：只有 DNA 进入菌体并传给子代，蛋白质外壳留在菌外，证明 DNA 是遗传物质。"},{"k":"含量与染色体平行","t":"DNA 分布在染色体内、是染色体的主要成分，而染色体直接与遗传有关；核内 DNA 含量十分稳定并与染色体数目呈平行关系，同种生物体细胞 DNA 含量是生殖细胞的 2 倍。"},{"k":"代谢稳定","t":"DNA 在代谢中较稳定，不受生物体营养条件、年龄等因素的影响。"},{"k":"理化因素致突变","t":"作用于 DNA 的一些物理和化学因素，如紫外线、X 射线、氮芥等，都可以引起生物体遗传特性的改变。"}],"note":"口径：依据《真题分类》资料原文（直接证据两项、间接证据四项，此处间接证据并为三点）。","opts":[],"printed_answer":"","ref":true},{"id":"n0023","subj":"880","chap":"第四章 蛋白质","type":"问答","years":["00"],"q":"生物酶在生物体中起着十分重要的作用，请说出它作为生物催化剂与其他催化剂比较有哪些异同，并论述与酶高效率催化作用有关的因素","points":[{"k":"催化共性","t":"都能显著改变化学反应速率但不改变平衡常数；都通过降低活化能提高反应速率；都只催化热力学上允许的反应；反应前后化学本质和数量不变。"},{"k":"酶的特性","t":"高度专一性（可区分光学异构底物，是最重要特点，也是与一般催化剂最主要的区别）；易失活；反应条件温和（常温、常压、近中性）；催化效率比非生物催化剂高 10⁷~10¹³ 倍；活性可受调节控制。"},{"k":"基元催化","t":"酸碱催化（瞬间供出或接受质子以稳定过渡态）、共价催化（含亲核与亲电催化，形成不稳定的共价中间复合物）、金属离子催化（配位定向、静电屏蔽负电荷、氧化态变化参与氧化还原）。"},{"k":"邻近与定向","t":"表现为熵减：把两个底物束缚在酶表面，提高局部底物浓度与有效碰撞概率，使分子间反应变成类似分子内的反应。"},{"k":"形变与诱导契合","t":"表现为熵增：使反应化学键产生电子张力，底物能量增加、接近过渡态，从而加快反应。"},{"k":"协同与微环境","t":"多元催化可几个基元催化协同作用；活性部位是低介电区域，能提高酶与底物的结合作用，并可造成高浓度酸与高浓度碱并存的环境。"}],"note":"口径：依据《真题分类》资料原文。原文把酶量调节、活性调节（反馈、别构、共价修饰、酶原激活、同工酶、细胞与激素水平）列在“不同点”第⑤条，此处并入“酶的特性”以控制条数。","opts":[],"printed_answer":"","ref":true},{"id":"n0024","subj":"880","chap":"第七章 核酸","type":"问答","years":["00"],"q":"什么是后基因组研究，请简述其现实意义","points":[{"k":"后基因组定义","t":"后基因组学即功能基因组学，利用结构基因组所提供的信息和产物、发展和应用新的实验手段，在基因组或系统水平上全面分析基因功能，使研究从单一基因或蛋白质转向多个基因或蛋白质的系统研究。"},{"k":"研究内容","t":"包括基因组功能注释、发现并了解基因功能、基因表达分析、突变检测、认识基因与疾病的关系、掌握基因产物及其在生命活动中的作用。"},{"k":"表达及调控研究","t":"在全细胞水平识别所有基因组表达的 mRNA 与蛋白质及两者相互作用，阐明基因组表达在发育过程和不同环境压力下的时空整体调节网络。"},{"k":"识别与功能鉴定","t":"基因识别需生物信息学技术与生物学实验手段结合；功能信息提取包括人类基因突变体的系统鉴定、表达谱绘制、「基因改变-功能改变」鉴定、蛋白质水平与修饰状态及相互作用的检测。"},{"k":"基因多样性与SNP","t":"个体基因组序列存在差异并反映为表型差异，其中出现最多的基因多态性是单核苷酸多态性（SNP）。"},{"k":"比较基因组学","t":"将人类基因组与模式生物基因组比较，既有助于按同源方法分析人类基因功能，又有助于发现种间本质差异、探索遗传语言、揭示生命起源与进化。"}],"note":"口径：依据《真题分类》资料原文（定义＋五条现实意义，此处将「基因信息识别」与「功能信息提取」并为一点）。","opts":[],"printed_answer":"","ref":true},{"id":"n0025","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"问答","years":["00"],"q":"什么是酶工程？目前进行酶工程研究的手段有哪些？请说明用定点突变的方法进行酶工程研究的原理","points":[{"k":"酶工程定义","t":"又称酶技术，围绕酶特有的生物催化特性，结合现代技术手段，在体外模拟或在常温常压下生成酶反应的产品，或利用 DNA 重组技术定向改造酶、进行酶的修饰或基因改造，获得具有特殊功能的非天然蛋白质的技术。"},{"k":"化学酶工程","t":"借助化学手法，又称初级酶工程：天然酶（微生物发酵所得粗酶）、化学修饰酶（功能基团修饰、交联反应、大分子修饰）、固定化酶、模拟酶、分子印迹酶。"},{"k":"固定化与修饰","t":"固定化分物理法（吸附、包埋）与化学法（共价偶联、交联），可提高对酸碱和温度的稳定性、延长使用寿命、简化分离工艺、提高使用次数；化学修饰主要提高稳定性。"},{"k":"生物酶工程","t":"借助 DNA 重组技术，又称高级酶工程：克隆酶（大量生产酶）、突变酶（定点突变或定向进化产生遗传修饰酶）、新酶（设计新基因合成自然界没有的新酶）。"},{"k":"定点突变原理","t":"按已知化学组成、空间结构与特性设计新酶的氨基酸排列并确定置换位点→反向设计核苷酸序列、确定需置换的碱基→合成 1~2 个碱基被置换的寡核苷酸作引物，经 PCR 或 M13 定位突变获得突变基因→克隆后体外表达获得新酶。"}],"note":"口径：依据《真题分类》资料原文，定点突变按原文“设计—定碱基—得突变基因—表达得新酶”四步压缩。","opts":[],"printed_answer":"","ref":true},{"id":"n0026","subj":"880","chap":"第四章 蛋白质","type":"问答","years":["00"],"q":"在生物大分子的分离纯化中，柱层析分离是最常用最有效的分离手段，请列举 5 种柱层析方法，并说明其中 3 种方法的分离原理。","points":[{"k":"五种柱层析","t":"分配柱层析、离子交换柱层析、凝胶过滤（分子筛）柱层析、羟基磷灰石柱层析、亲和柱层析。"},{"k":"分配层析原理","t":"基于流动相组分在溶解度性质上的差异分离，各组分分配系数差异越大越易分开；不仅可用于分离，还可用于样品鉴定。"},{"k":"离子交换原理","t":"基于电荷行为，利用交换剂上可解离基团对各种离子的亲和力不同而分离；阳离子交换树脂含酸性基团、解离出 H⁺ 交换阳离子，阴离子交换树脂含碱性基团、解离出 OH⁻ 交换阴离子。"},{"k":"凝胶过滤原理","t":"又称分子筛、大小排阻层析，基于蛋白质体积大小和形状不同分离，也可测相对分子质量；体积大、线型的蛋白质走的路程少、先被洗脱，体积小、球型的路程多、后被洗脱。"},{"k":"羟基磷灰石原理","t":"基于羟基磷灰石中钙离子对核酸磷酸基的吸附，用于单双链核酸分离：双链刚性伸展、磷酸基暴露在表面，吸附力强被吸附；单链柔软呈无规线团、磷酸基多折在分子内，吸附弱而不被吸附。"},{"k":"亲和层析原理","t":"利用生物学亲和力分离纯化，包括凝集素亲和（糖蛋白）、免疫亲和（抗原）、金属螯合（含金属蛋白）；优点是可从复杂混合物中一步分离出目标蛋白、纯度和产率高，并可排除已失活的目标蛋白。"}],"note":"口径：依据《真题分类》资料原文，五种方法按原文列举（分配、离子交换、凝胶过滤、羟基磷灰石、亲和），未采用教材另举的疏水与反相层析。","opts":[],"printed_answer":"","ref":true},{"id":"n0027","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"名词解释","years":["07"],"q":"DNA 光复活修复","points":[{"k":"定义","t":"DNA 受紫外线照射形成嘧啶二聚体后，由光裂合酶在可见光下直接解开二聚体、恢复原结构的修复方式，属直接修复。"},{"k":"光裂合酶解二聚体","t":"光裂合酶先与二聚体结合，吸收光能以电子传递断裂环丁烷环，恢复两个嘧啶单体；不切碱基、不产生错配，属无误修复。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0029","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"名词解释","years":["07"],"q":"锌指结构域","points":[{"k":"定义","t":"真核转录因子中常见的小型 DNA 结合结构域，约 30 个氨基酸借 1 个 Zn²⁺ 与 2 个 Cys、2 个 His 配位，折叠成指状构象。"},{"k":"α-螺旋嵌大沟","t":"α-螺旋嵌入 DNA 大沟，靠氨基酸侧链与碱基特异识别；常串联重复出现，重复越多识别序列越长，为转录因子的典型模块。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0030","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"名词解释","years":["07"],"q":"ρ 因子","points":[{"k":"定义","t":"原核生物中参与转录终止的六聚体蛋白，具依赖 ATP 的 RNA-DNA 解旋酶活性，介导不依赖终止因子的 ρ 依赖性终止。"},{"k":"追聚合酶解杂合体","t":"ρ 结合新生 RNA 5′ 端 rut 位点，沿 RNA 5′→3′ 移动并水解 ATP，追上暂停的聚合酶，解开 RNA-DNA 杂交体而释放 RNA。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0034","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"填空","years":["07"],"q":"DNA 文库包括哪两类","points":[{"k":"答案","t":"基因组文库和 cDNA 文库。前者由基因组 DNA 酶切后克隆而成，含内含子与调控序列；后者由 mRNA 反转录而来，只含表达序列。"}],"note":"","opts":[],"printed_answer":"基因组文库和 cDNA 文库"},{"id":"n0035","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"填空","years":["07"],"q":"剪接的外显子两边的保守序列","points":[{"k":"答案","t":"外显子 5′ 端为 GT、3′ 端为 AG，即 GT-AG 法则；剪接体识别该保守序列完成剪接。"}],"note":"","opts":[],"printed_answer":"分别是 GT 和 AG，这个叫做 GT-AG 法则"},{"id":"n0036","subj":"631","chap":"七、分子生物学技术","type":"填空","years":["07"],"q":"Western、Northern、Southern 分别来检测","points":[{"k":"答案","t":"Southern 检测 DNA，Northern 检测 RNA，Western 检测蛋白质；三者均先电泳分离，再用探针或抗体识别。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0037","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["07"],"q":"大肠杆菌 RNA 聚合酶在启动子上的定位机制","points":[{"k":"全酶与σ因子","t":"大肠杆菌 RNA 聚合酶全酶为 α₂ββ′ωσ⁷⁰，核心酶负责催化，σ⁷⁰ 专司启动子识别，可显著提高对启动子的亲和力。"},{"k":"识别-35区","t":"σ⁷⁰ 的 4.2 区识别 -35 区保守序列 TTGACA，提供初始结合能，是首先被识别的位点。"},{"k":"识别-10区","t":"σ⁷⁰ 的 2.4 区识别 -10 区 TATAAT（Pribnow 盒），-10 与 -35 之间间隔 17±1 bp 时定位最有效。"},{"k":"闭合转开放","t":"全酶结合形成闭合复合物后，DNA 在活性中心解链约 12~14 bp，形成开放复合物（转录泡），模板链进入催化位点。"},{"k":"起始后σ释放","t":"合成前几个核苷酸后 σ 因子释放，核心酶对一般 DNA 的亲和力下降、沿模板前移进入延伸，σ 可循环使用于新的起始。"},{"k":"UP元件辅助","t":"部分强启动子在 -40~-60 有富含 AT 的 UP 元件，由 α 亚基 C 端结构域识别并结合，进一步增强全酶的结合。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0038","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["07"],"q":"PCR 的基本原理","points":[{"k":"高温变性","t":"94~95 ℃ 加热 30 s，模板双链间的氢键断裂，解为单链模板。"},{"k":"引物退火","t":"降至 50~65 ℃ 约 30 s，一对引物分别与两条模板链上的互补序列特异杂交，形成引物-模板复合物。"},{"k":"聚合延伸","t":"升至 72 ℃，耐热 Taq DNA 聚合酶以 dNTP 为原料，从引物 3′-OH 端沿 5′→3′ 方向合成互补链。"},{"k":"循环扩增","t":"三步循环重复 25~35 次，每轮产物又成为下轮模板，目的片段以 2ⁿ 指数扩增，最终经琼脂糖凝胶电泳鉴定。"},{"k":"反应体系要素","t":"需模板 DNA、一对特异引物、dNTP、Mg²⁺、缓冲液与耐热 DNA 聚合酶，并由热循环仪精确控温。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0039","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"论述","years":["07"],"q":"克隆一个基因，再大量表达，纯化基因产物，最后再研究基因的生物学功能，说出完成这些工作的实验设计","points":[{"k":"目的基因获取","t":"由 cDNA 文库或基因组文库筛取，或按序列设计引物 PCR 扩增，两端引入酶切位点与保护碱基；也可全基因化学合成。"},{"k":"表达载体构建","t":"目的基因与表达载体（如 pET-28a）双酶切，T4 DNA 连接酶连接，转化 DH5α，经抗性、蓝白斑、菌落 PCR 与双酶切筛选，阳性克隆测序验证读框。"},{"k":"转化与诱导表达","t":"重组质粒转入 BL21(DE3)，OD₆₀₀ 达 0.6 时加 IPTG 诱导 T7 启动子；优化诱导温度（16~37 ℃）、IPTG 浓度与时间，低温慢诱导以减少包涵体。"},{"k":"分离纯化","t":"超声或高压均质破碎菌体，离心取上清；利用 N 端 His₆ 标签做 Ni-NTA 亲和层析，再经离子交换与凝胶过滤精制；SDS-PAGE 与 Western blot 鉴定纯度，必要时切除标签。"},{"k":"体外功能研究","t":"测定酶活与动力学参数（Km、Vmax、kcat、最适 pH 与温度）、底物专一性；用定点突变验证关键残基，用结合实验检测相互作用。"},{"k":"体内功能研究","t":"基因敲除、敲低或过表达后比较表型；荧光融合蛋白定位；酵母双杂交、免疫共沉淀、pull-down 寻找互作蛋白；必要时解析三维结构。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0040","subj":"880","chap":"第七章 核酸","type":"选择","years":[],"q":"两条 DNA 单链在适宜条件下形成双螺旋结构的原因是","points":[{"k":"答案","t":"A 碱基互补。两条单链靠 A-T、G-C 间氢键及碱基堆积力配对，才能形成双螺旋。"}],"note":"","opts":["A. 碱基互补","B. 重复序列多","C. Tm 相似"],"printed_answer":""},{"id":"n0041","subj":"880","chap":"第十四章 氧化磷酸化","type":"选择","years":[],"q":"下列不是琥珀酸呼吸链部分的是","points":[{"k":"答案","t":"B FMN。琥珀酸呼吸链自复合体Ⅱ的 FAD 起步，经 Cytb560、Cytb566、Cytc1 到 Cyt aa₃；FMN 是 NADH 呼吸链复合体Ⅰ的辅基。"}],"note":"","opts":["A. FAD","B. FMN","C. Cytb 560","D. Cytb566"],"printed_answer":""},{"id":"n0042","subj":"880","chap":"第十四章 氧化磷酸化","type":"选择","years":[],"q":"氧化呼吸链存在于什么部位 ：","points":[{"k":"答案","t":"A 线粒体内膜。呼吸链四个复合体都嵌于线粒体内膜，氧化磷酸化即在内膜上完成。"}],"note":"","opts":["A. MIT 内膜","B. 内质网","C. 线粒体外膜","D. 线粒体基质"],"printed_answer":""},{"id":"n0043","subj":"880","chap":"第五章 酶","type":"选择","years":[],"q":"米氏方程中[S]=1/2Km,V=","points":[{"k":"答案","t":"A 0.33Vm。代入米氏方程 V=Vmax[S]/(Km+[S])，[S]=0.5Km 时 V=Vmax×0.5/1.5=Vmax/3。"}],"note":"","opts":["A. 0.33Vm","B. 0.5","C. 0.75","D. 0.25"],"printed_answer":""},{"id":"n0044","subj":"880","chap":"第七章 核酸","type":"选择","years":[],"q":"在 DNA 复制中 DNA 聚合酶的作用，属于","points":[{"k":"答案","t":"B 合成酶。DNA 聚合酶把 dNTP 的核苷酸基转移到引物 3′-OH 上形成磷酸二酯键，催化小分子合成大分子。"}],"note":"","opts":["A. 裂合酶","B. 合成酶"],"printed_answer":""},{"id":"n0045","subj":"880","chap":"第五章 酶","type":"选择","years":[],"q":"酶原无活性的原因是","points":[{"k":"答案","t":"A 活性中心未形成或未暴露。酶原以无活性前体存在，需水解切除一段肽后才折叠出完整活性中心。"}],"note":"","opts":["A. 酶活性中心未形成或未暴露","B. 有抑制蛋白存在"],"printed_answer":""},{"id":"n0046","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"组氨酸的解离曲线如图\n（1）请写出组氨酸在 A、B、C 三点的结构\n（2）请计算组氨酸的 PI\n（3）请写出组氨酸在 PI 处的结构\n（4）为什么血红蛋白中含有大量的组氨酸？\n[图：右上角标注 A —pK₁→ B —pK_R→ C —pK₂→ 三点及组氨酸结构式；主图为滴定曲线，横轴 OH⁻（equivalents）0～3.0，纵轴 pH 0～10，曲线为 Histidine 的 S 形解离曲线，标注 pK₁=1.82、pK_R=6.0、pK₂=9.17]","points":[{"k":"A点完全质子化","t":"pH<pK₁，α-羧基、α-氨基与咪唑基均质子化：HOOC—CH(NH₃⁺)—CH₂—咪唑鎓，净电荷 +2。"},{"k":"B点羧基解离","t":"pK₁<pH<pK_R，α-COOH 失去质子成 —COO⁻，α-NH₃⁺ 与咪唑鎓保留，净电荷 +1。"},{"k":"C点咪唑解离","t":"pK_R<pH<pK₂，咪唑基去质子成中性形式，—COO⁻ 与 —NH₃⁺ 共存，形成兼性离子，净电荷 0。"},{"k":"等电点计算","t":"pI=(pK_R+pK₂)/2=(6.0+9.17)/2=7.59。"},{"k":"pI处结构","t":"与 C 点相同：H₃N⁺—CH(COO⁻)—CH₂—咪唑（中性），净电荷为零，电泳时不迁移。"},{"k":"血红蛋白富组氨酸","t":"咪唑基 pK_R≈6.0 接近生理 pH，是体内最主要的缓冲基团，赋予 Hb 缓冲能力并参与 Bohr 效应；β146His 与 Asp94 形成盐桥稳定 T 态，F8 近端 His 与 Fe²⁺ 配位，E7 远端 His 以氢键稳定 O₂ 结合，β 链 His 还参与 2,3-BPG 结合。"}],"note":"pI 计算按 pK_R 与 pK₂ 的平均值；若将 C 点理解为 pK_R 之前的形态，则 pI 处结构仍以本条所述兼性离子为准。","opts":[],"printed_answer":""},{"id":"n0047","subj":"880","chap":"第七章 核酸","type":"简答","years":[],"q":"给了一段 DNA 序列和密码子表\n（1）写出以该序列为模板转录出的 mRNA 序列\n（2）写出翻译出的蛋白质的序列\n（3）mRNA 的作用是什么？","points":[{"k":"转录出mRNA","t":"以 DNA 模板链（3′→5′）为模板，按 A-U、T-A、G-C、C-G 互补，沿 5′→3′ 合成 mRNA；其序列与编码链相同，只是 T 换成 U。"},{"k":"翻译出肽链","t":"核糖体从 5′ 端扫描，遇起始密码子 AUG 开始，按三联体密码子表逐个翻译，至 UAA、UAG 或 UGA 终止，释放肽链。"},{"k":"mRNA的作用","t":"mRNA 携带 DNA 的遗传信息，是蛋白质合成的直接模板，其密码子顺序决定氨基酸顺序。"},{"k":"结构与调控元件","t":"5′ 帽与 3′ poly(A) 尾保护 mRNA、协助核糖体起始并影响稳定性；原核 mRNA 的 SD 序列确定翻译起始位点。"}],"note":"原卷所给 DNA 序列与密码子表未随题保留，无法写出具体 mRNA 与肽链序列，只能给出推导规则。","opts":[],"printed_answer":""},{"id":"n0048","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"论述","years":[],"q":"大概是研究出一种新型酶，应用现代技术在大肠杆菌中生产酶\n（1）应用了什么技术手段？详细步骤是什么？\n（2）分离纯化酶的手段和技术有哪些？\n（3）测定该酶催化的反应，需要测定酶的哪些参数？","points":[{"k":"基因工程技术路线","t":"按酶蛋白氨基酸序列反推设计基因（或从产酶菌株克隆），全基因合成并优化大肠杆菌偏好密码子，两端加酶切位点。"},{"k":"载体构建与转化","t":"插入 pET 系列表达载体，与 His₆ 标签融合以利于纯化；双酶切连接后转化 DH5α 筛选、测序，再转入 BL21(DE3)。"},{"k":"诱导与高密度发酵","t":"IPTG 诱导 T7 启动子，控制温度、诱导时机与时间，必要时用自动诱导培养基或发酵罐高密度培养；形成包涵体时需变性复性。"},{"k":"分离纯化手段","t":"破碎菌体→离心→硫酸铵分级盐析→透析→Ni-NTA 亲和层析→离子交换→凝胶过滤；以 SDS-PAGE、Western blot、比活测定监控纯度与回收率。"},{"k":"酶学参数测定","t":"测 Km、Vmax、kcat 与 kcat/Km（双倒数作图）、最适 pH 与温度、pH 与热稳定性、激活剂与抑制剂、底物专一性，并验证是否符合米氏方程。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0049","subj":"880","chap":"第五章 酶","type":"计算","years":[],"q":"乳酸脱氢酶催化的反应符合米氏方程动力学，1/v 对 1/[s] 的双倒数曲线作图得到的直线斜率为＿＿＿min⁻¹，在 1/v 轴上的截距为＿＿＿mol·L⁻¹·min⁻¹\n（1）请写出乳酸脱氢酶所催化的反应\n（2）应用什么方法检测该酶的活性？原理是什么？\n（3）请计算该酶的 Vmax 和 Km","points":[{"k":"反应式","t":"L-乳酸+NAD⁺ ⇌ 丙酮酸+NADH+H⁺，乳酸脱氢酶催化，pH 8.8~9.9 时平衡偏向丙酮酸生成，便于测正反应速率。"},{"k":"340nm比色法","t":"NADH 在 340 nm 有强吸收（ε=6.22×10³ L·mol⁻¹·cm⁻¹），NAD⁺几乎无吸收；连续监测 A₃₄₀ 的上升速率即反映酶活性。"},{"k":"双倒数关系","t":"1/v 对 1/[S] 作图为直线：斜率=Km/Vmax（单位 min），纵轴截距=1/Vmax，横轴截距=−1/Km。"},{"k":"截距反推Vmax","t":"Vmax=1/纵轴截距，单位 mol·L⁻¹·min⁻¹。"},{"k":"斜率计算Km","t":"Km=斜率×Vmax=斜率/纵轴截距，单位 mol·L⁻¹。"}],"note":"原卷两条横线处（斜率、截距）的数值未保留，无法代入得具体数值，故给通式；另题干所标截距单位应为 mol⁻¹·L·min，mol·L⁻¹·min⁻¹ 是反应速度 v 的单位。","opts":[],"printed_answer":""},{"id":"n0050","subj":"880","chap":"第十章 糖酵解 糖异生","type":"计算","years":[],"q":"请计算 1 mol 甘油彻底氧化分解共生成多少 mol ATP？","points":[{"k":"活化耗一ATP","t":"甘油 + ATP → 3-磷酸甘油 + ADP，甘油激酶催化，主要在肝、肾，消耗 1 ATP。"},{"k":"脱氢产FADH₂","t":"3-磷酸甘油经线粒体内膜甘油-3-磷酸脱氢酶（FAD 辅基）氧化为磷酸二羟丙酮，生成 FADH₂，产 1.5 ATP。"},{"k":"酵解段产能","t":"磷酸二羟丙酮 → 3-磷酸甘油醛 → 丙酮酸，净产 2 ATP + 1 胞质 NADH（走 3-磷酸甘油穿梭计 1.5 ATP）。"},{"k":"丙酮酸入TCA","t":"丙酮酸经丙酮酸脱氢酶复合体生成乙酰 CoA，产 1 NADH（2.5 ATP）。"},{"k":"TCA产能","t":"1 乙酰 CoA 经柠檬酸循环产 3 NADH + 1 FADH₂ + 1 GTP = 10 ATP。"},{"k":"合计","t":"−1 + 1.5 + 2 + 1.5 + 2.5 + 10 = 16.5 mol ATP。"}],"note":"按 3-磷酸甘油穿梭计。若该胞质 NADH 走苹果酸-天冬氨酸穿梭（2.5），结果为 17.5——注意第一步脱氢是 FADH₂，恒为 1.5。","opts":[],"printed_answer":""},{"id":"n0051","subj":"880","chap":"第七章 核酸","type":"选择","years":[],"q":"DNA 复制中不含下列哪一个酶","points":[{"k":"答案","t":"A RNA 合成酶。复制需要解旋酶、拓扑异构酶、引物酶、DNA 聚合酶和连接酶；转录用的 RNA 聚合酶不参与复制。"}],"note":"引物酶本身即依赖 DNA 的 RNA 聚合酶，此处 A 指转录用的 RNA 聚合酶。","opts":["A. RNA 合成酶","B. 拓扑异构酶","C. 引物酶","D. 解旋酶"],"printed_answer":""},{"id":"n0052","subj":"880","chap":"第七章 核酸","type":"选择","years":[],"q":"DNA 复制中 RNA 引物的作用是","points":[{"k":"答案","t":"D 为 dNTP 提供附着点。引物的 3′-OH 是 DNA 聚合酶添加脱氧核苷酸的起点，引发后引物被切除并由 DNA 填补。"}],"note":"","opts":["A. 引导合成冈崎片段","B. 作为合成冈崎片段的模板","C. 激活 DNA 聚合酶","D. 为 DNA 合成原料 dNTP 提供附着点"],"printed_answer":""},{"id":"n0053","subj":"880","chap":"第九章 生物膜","type":"选择","years":[],"q":"跨膜蛋白质与膜脂在膜内结合部位为","points":[{"k":"答案","t":"A 大多疏水。跨膜段由约 20 个疏水氨基酸组成 α-螺旋，靠疏水作用与膜脂脂肪酸链结合。"}],"note":"","opts":["A. 大多疏水","B. 酸性","C. 碱性"],"printed_answer":""},{"id":"n0054","subj":"880","chap":"第八章 抗生素与激素","type":"选择","years":[],"q":"身体处于短期饥饿状态，下列错误的是","points":[{"k":"答案","t":"B 组织利用葡萄糖增大。短期饥饿时胰岛素降、胰高血糖素升，脂肪动员与糖异生增强、肌蛋白分解增加，组织反而减少葡萄糖利用以保血糖。"}],"note":"","opts":["A. 脂肪动员增大","B. 组织利用 G 增大","C. 糖异生作用增强","D. 肌蛋白分解增强"],"printed_answer":""},{"id":"n0055","subj":"880","chap":"第七章 核酸","type":"选择","years":[],"q":"2022 年诺贝尔生理学奖颁给了","points":[{"k":"答案","t":"A 基因组。2022 年奖授予 Svante Pääbo，表彰其对已灭绝古人类基因组测序及人类演化的发现，属古基因组学。"}],"note":"原卷选项缺项且 B、D 重复标注，实际考点为古基因组学。","opts":["A. 基因组","D. 蛋白质组学","C. 医学工程","D. 高通量测序"],"printed_answer":""},{"id":"n0057","subj":"880","chap":"第十六章 氨基酸代谢","type":"名词解释","years":["13"],"q":"Y-谷氨酰胺循环","points":[{"k":"定义","t":"以 γ-谷氨酰转移酶为关键酶、转运氨基酸入胞并回收谷胱甘肽的循环途径，每转运 1 分子氨基酸消耗 3 分子 ATP。"},{"k":"γ-GT转移谷氨酰基","t":"γ-谷氨酰转移酶把胞内谷胱甘肽的 γ-谷氨酰基转给胞外氨基酸；产物入胞后经环化转移酶、5-氧脯氨酸酶等再生谷胱甘肽。"}],"note":"资料无对应原答案，按教材口径：资料该条答的是「谷氨酰胺作为氨的运输形式」，与 γ-谷氨酰循环（γ-glutamyl cycle）不是同一概念，故不采用。题干「Y」为 γ 的误植。","opts":[],"printed_answer":"","ref":false},{"id":"n0059","subj":"880","chap":"第十四章 氧化磷酸化","type":"名词解释","years":["13"],"q":"P/O 比值","points":[{"k":"定义","t":"在氧化磷酸化中，一对电子经呼吸链传递至氧时所产生的 ATP 分子数，即每消耗 1 mol 氧原子所产生 ATP 的摩尔数。"},{"k":"数值口径","t":"NADH 经复合体Ⅰ、Ⅲ、Ⅳ 氧化时 P/O 为 2.5，FADH₂ 经Ⅱ、Ⅲ、Ⅳ 氧化时为 1.5，反映氧化与磷酸化的偶联效率。"}],"note":"口径：依据《真题分类》资料原文（仅定义）；2.5 与 1.5 按 NADH＝2.5、FADH₂＝1.5 的能量口径标注，属教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0065","subj":"880","chap":"第七章 核酸","type":"简答","years":["13"],"q":"细菌内产生的限制性内切酶为什么不剪切其本身的 DNA？\n（大肠杆菌中合成 DAN 限制性内切酶的意义及其在细胞中的作用 5 分）","points":[{"k":"自身DNA被甲基化","t":"宿主 DNA 中该酶的识别序列已被相应的 DNA 甲基化酶修饰，多为 N⁶-甲基腺嘌呤或 5-甲基胞嘧啶，甲基位于识别序列的关键碱基上。"},{"k":"限制修饰系统配对","t":"限制性内切酶与甲基化酶成对存在（R-M 系统），二者识别同一序列，甲基化酶先修饰自身基因组，限制酶则切割未修饰的外源 DNA。"},{"k":"甲基阻碍结合切割","t":"甲基的位阻与疏水效应妨碍限制酶与识别序列结合或阻止其催化切割，故自身 DNA 不被水解。"},{"k":"防御外源DNA","t":"该系统的生物学意义是降解侵入的噬菌体与质粒 DNA，限制外源基因表达，相当于细菌的免疫防御；自身染色体因修饰而受保护。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0066","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["13"],"q":"脂肪酸 β-氧化和柠檬酸循环的相同点(两步类似反应，方程式)及不同点?","points":[{"k":"相同三步","t":"β-氧化顺序为活化→脱氢→水合→再脱氢→硫解；TCA 为缩合→异构化→氧化脱羧→再氧化脱羧→分解→脱氢→水合→再脱氢，二者相同的步骤是脱氢→水合→再脱氢。"},{"k":"β氧化方程式","t":"脂酰-CoA + FAD →反式-Δ²-烯酰-CoA + FADH₂；反式-Δ²-烯酰-CoA + H₂O → L-3-羟脂酰-CoA；L-3-羟脂酰-CoA + NAD⁺ → β-酮脂酰-CoA + NADH + H⁺。"},{"k":"TCA方程式","t":"琥珀酸 + FAD → 延胡索酸 + FADH₂；延胡索酸 + H₂O → L-苹果酸；L-苹果酸 + NAD⁺ → 草酰乙酸 + NADH + H⁺。"},{"k":"底物产物不同","t":"β-氧化是氧化分解脂肪酸的途径，产物为乙酰 CoA；TCA 是氧化分解乙酰 CoA 的途径，产物是 CO₂、ATP 和大量还原型物质（NADH、FADH₂）。"},{"k":"上下游关系","t":"脂肪酸 β-氧化是 TCA 循环的上游反应，其产物乙酰 CoA 正是 TCA 的底物，使循环得以进行。"}],"note":"口径：依据《真题分类》资料原文，三步步骤、酶名与方程式照录；原文写作“TCA 循环”，未误作 TAC。","opts":[],"printed_answer":"","ref":true},{"id":"n0067","subj":"880","chap":"第十五章 脂类代谢","type":"计算","years":["13"],"q":"一个甘油三酯彻底氧化分解为 CO2 和 H20 释放多少能量？","points":[{"k":"计算前提","t":"假定甘油三酯中的脂肪酸为 16 碳的软脂酸，则 1 分子甘油三酯分解为 1 分子甘油和 3 分子软脂酸。"},{"k":"甘油产能","t":"甘油活化耗 1 ATP，脱氢生成 NADH 后经磷酸二羟丙酮进入酵解，两次底物水平磷酸化得 2 ATP，丙酮酸氧化脱羧与 TCA 再产能，净生成 16.5 ATP（胞质 NADH 走 3-磷酸甘油穿梭）。"},{"k":"软脂酸β氧化","t":"16 碳软脂酸经 7 次循环的 β-氧化，产生 7 分子 FADH₂、7 分子 NADH 和 8 分子乙酰 CoA。"},{"k":"软脂酸净产能","t":"8 乙酰 CoA 经 TCA 共 80 ATP；7 FADH₂ = 1.5×7 = 10.5；7 NADH = 2.5×7 = 17.5；再减去活化消耗的 2 个高能磷酸键，净得 80+10.5+17.5−2 = 106 ATP。"},{"k":"三者合计","t":"3 分子软脂酸净产能 106×3 = 318 ATP。"},{"k":"总产能与折能","t":"1 分子甘油三酯彻底氧化净生成 16.5+318 = 334.5 mol ATP（胞质 NADH 若走苹果酸-天冬氨酸穿梭则为 18.5+318 = 336.5）；按 1 mol ATP 约 30.5 kJ 计，334.5×30.5 ≈ 1.02×10⁴ kJ。"}],"note":"口径：依据《真题分类》资料原文。334.5/336.5 ATP、106、318、80、10.5、17.5 与资料逐位核对无误；1 mol ATP≈30.5 kJ 为能量换算常数，资料未给，系补充（末点「折能」一句）。","opts":[],"printed_answer":"","ref":true},{"id":"n0074","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["01"],"q":"简述血红蛋白的结构，这种结构和它的功能有何关系？","points":[{"k":"四聚体组成","t":"血红蛋白为四聚体，两个 α 亚基与两个 β 亚基借非共价作用力缔合，亚基在生理条件下盘绕折叠成球形（珠蛋白）。"},{"k":"血红素结合氧","t":"每个亚基内部结合 1 分子血红素，血红素为具卟啉结构的小分子，中央配位结合 1 个铁离子，铁离子可结合 1 分子氧，从而赋予血红蛋白结合氧的能力。"},{"k":"正协同效应","t":"4 个亚基对氧的结合能力不同，一个亚基结合氧后构象改变，使其余亚基更易结合氧，呈亚基间正协同效应。"},{"k":"结构与功能关系","t":"四聚体亚基间的非共价作用使其具有别构调节效应，氧合曲线呈 S 形，对氧浓度变化敏感。"},{"k":"补：运输氧的适配","t":"S 形曲线使其在氧浓度大的肺中结合氧、在氧浓度小的组织中释放氧，适于在血液中运输氧；2,3-二磷酸甘油酸结合于 β 链中央孔，稳定 T 态、进一步降低亲和力。"}],"note":"口径：依据《真题分类》资料原文（原文只讲亚基组成、血红素、正协同与 S 形曲线）。补：His F8/E7 配位、Bohr 效应、2,3-BPG 等细节原资料未列，仅末点按教材口径补充 2,3-BPG。","opts":[],"printed_answer":"","ref":true},{"id":"n0075","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"简答","years":["01"],"q":"列出转录酶和反转录酶的催化反应式","points":[{"k":"转录酶反应式","t":"转录酶即 DNA 指导的 RNA 聚合酶：wATP + xGTP + yCTP + zUTP ─转录酶→ RNA + (w + x + y + z) PPi，以 DNA 一条链为模板。"},{"k":"反转录酶反应式","t":"逆转录酶即依赖 RNA 的 DNA 聚合酶：wdATP + xdGTP + ydCTP + zdUTP ─逆转录酶→ DNA + (w + x + y + z) PPi，以 RNA 为模板。"},{"k":"逆转录酶三活性","t":"兼有三种酶活性：RNA 指导的 DNA 合成、水解 RNA（RNase H）、DNA 指导的 DNA 合成。"}],"note":"口径：依据《真题分类》资料原文。反应式按资料以 w/x/y/z 表示四种核苷酸的分子数，未改为具体数字。","opts":[],"printed_answer":"","ref":true},{"id":"n0076","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["01"],"q":"请简要说明真核生物编码蛋白质基因的表达调节的作用特点","points":[{"k":"整体多级调节","t":"真核基因组与染色体结构比原核复杂，进化潜力大、调节精确、适应性强，主要受激素水平和发育阶段调控，存在多级调节系统。"},{"k":"染色质水平","t":"真核 DNA 与组蛋白结合成染色质结构，须先经染色质重塑在染色质水平活化；原核一般认为无染色质结构，直接对 DNA 调节。"},{"k":"DNA水平重排","t":"功能相近的基因成簇存在但不组成操纵子、各自调节，且 DNA 常发生重排、扩增等现象。"},{"k":"转录水平正调节","t":"有三种 RNA 聚合酶，调节区大，受多种转录因子间接调控，以正调节为主。"},{"k":"转录后与翻译水平","t":"转录与翻译不偶联、有时间间隔，含内含子需加工成熟；mRNA 较稳定、半衰期较长，通过帽子、尾巴等空间结构调控表达，为单顺反子、形成单一产物。"},{"k":"翻译后与降解","t":"有内质网、高尔基体等系统，加工复杂；有溶酶体和泛素-蛋白酶体系统，可对蛋白质进行选择性降解。"}],"note":"口径：依据《真题分类》资料原文（原文以原核-真核对比表给出，此处只取真核一列并归并）。","opts":[],"printed_answer":"","ref":true},{"id":"n0077","subj":"880","chap":"第九章 生物膜","type":"简答","years":["01"],"q":"试述生物膜的两侧不对称性","points":[{"k":"不对称性总述","t":"质膜内外两层组分与功能有明显差异称膜的不对称性；膜脂、膜蛋白与糖质均呈不对称分布，使物质传递、信号接受与传递具有方向性。"},{"k":"膜脂不对称","t":"脂分子在脂双层中不均匀分布，磷脂酰胆碱主要在胞外面、磷脂酰丝氨酸主要在胞质面；膜表面还有胆固醇与鞘磷脂形成的微结构域即脂筏。"},{"k":"膜蛋白不对称","t":"每种膜蛋白在膜上都有明确的方向性与分布区域性，使膜有“正反面”；受体、载体按一定方向传递信号与运输物质，膜相关酶促反应只发生在膜的某一侧面。"},{"k":"糖质不对称","t":"糖脂与糖蛋白的糖链无论何种情况只分布于细胞膜外表面，这些成分可能是细胞表面受体，并与细胞抗原性有关。"}],"note":"口径：依据《真题分类》资料原文（原文止于糖质不对称）。翻转酶、爬行酶等维持机制与凋亡标志原资料未提，未收入。","opts":[],"printed_answer":"","ref":true},{"id":"n0078","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["01"],"q":"要测定蛋白质的二硫键位置需要什么方法?请简述之","points":[{"k":"对角线电泳法","t":"测定蛋白质二硫键位置的方法是对角线电泳。"},{"k":"酶切肽段","t":"用胃蛋白酶酶切未经还原的蛋白质，得到含二硫键的肽段混合物，点于滤纸中央。"},{"k":"第一向电泳","t":"在 pH 6.5 条件下进行第一向电泳，肽段根据其大小及电荷的不同而分离。"},{"k":"过甲酸断键","t":"把滤纸暴露在过甲酸蒸汽中使二硫键断裂，每个含二硫键的肽段被氧化成一对含磺基丙氨酸的肽。"},{"k":"第二向电泳","t":"将滤纸旋转 90°，在与第一向完全相同的条件下做第二向电泳；多数肽段迁移率未变而位于对角线上，含磺基丙氨酸的成对肽段因变小且负电荷增加而偏离对角线。"},{"k":"显色与测序","t":"肽斑用茚三酮显色确定；将每对未显色的含磺基丙氨酸肽段分别取下做氨基酸序列分析，与多肽链序列比较，即可推断二硫键在肽链间或链内的位置。"}],"note":"口径：依据《真题分类》资料原文（原文六个步骤，逐条保留）。","opts":[],"printed_answer":"","ref":true},{"id":"n0079","subj":"880","chap":"第二十一章 细胞代谢与基因表达","type":"问答","years":["01"],"q":"试述乳糖操纵子的调控机制","points":[{"k":"操纵子组成","t":"由结构基因与控制部位组成：lacZ 编码 β-半乳糖苷酶（水解乳糖为半乳糖和葡萄糖）、lacY 编码 β-半乳糖苷透过酶（介导乳糖跨膜入菌）、lacA 编码 β-硫代半乳糖苷乙酰基转移酶（非必需，有一定解毒功能）；控制部位含启动子 P、操纵区 O 与阻遏基因 lacI。"},{"k":"负控阻遏","t":"不含乳糖时，阻遏蛋白以四聚体活性形式结合于操纵区；因操纵区与启动子有重叠序列，阻遏蛋白结合可阻碍 RNA 聚合酶与启动子结合，从而阻碍基因表达。"},{"k":"诱导去阻遏","t":"含乳糖时，乳糖的异构体（如 IPTG）作为诱导物结合阻遏蛋白，引起构象改变、降低与 DNA 的特异结合，阻遏蛋白从操纵区脱落，RNA 聚合酶得以结合启动子而开启转录。"},{"k":"本底组成型合成","t":"诱导物需 β-半乳糖苷酶催化乳糖生成、又需透过酶帮助才能进入细胞，故无诱导物时这两种酶仍少量合成，以应答诱导效应，称为本底水平的组成型合成。"},{"k":"cAMP-CRP正调节","t":"不含葡萄糖时，CRP 与 cAMP 形成复合物结合于启动子上游的 CAP 位点，使 DNA 双螺旋弯曲，有利于形成稳定的开放型启动子-RNA 聚合酶结构而激活表达；含葡萄糖时降解物抑制腺苷酸环化酶、活化磷酸二酯酶，cAMP 下降，cAMP-CRP 减少，正调节受抑，即葡萄糖效应（降解物阻遏）。"},{"k":"正负协同","t":"正调节不能激活被负调节抑制的基因，没有正调节时即使解除抑制基因仍无转录活性；只有正调节激活且负调节解除，即存在乳糖而不含葡萄糖时，操纵子才高效表达。"}],"note":"口径：依据《真题分类》资料原文。资料「图示」中的基因排布与 mRNA 翻译产物照原文；葡萄糖效应并入正调节一点，未删内容。","opts":[],"printed_answer":"","ref":true},{"id":"n0080","subj":"880","chap":"第五章 酶","type":"问答","years":["01"],"q":"对于下列反应：\nE + S ⇔ ES ⇔ E + P\n（1）用稳态方法推出米氏方程（要求写出推导过程）\n（2）如果此酶有两个底物（S1，S2）如何判断哪个是该酶的最适底物？为什么？","points":[{"k":"反应模型","t":"E+S ⇌(k₁/k₋₁) ES →(k₂) E+P，k₂ 为催化常数，ES 的生成与分解决定反应速度 v=k₂[ES]。"},{"k":"稳态假设","t":"反应初期 [ES] 近似恒定，d[ES]/dt=k₁[E][S]−k₋₁[ES]−k₂[ES]=0。"},{"k":"酶守恒代入","t":"总酶量 [E]ₜ=[E]+[ES]，得 [ES]=[E]ₜ[S]/((k₋₁+k₂)/k₁+[S])。"},{"k":"导出米氏方程","t":"令 Km=(k₋₁+k₂)/k₁、Vmax=k₂[E]ₜ，则 v=Vmax[S]/(Km+[S])，Km 单位与底物浓度相同。"},{"k":"比较kcat与Km","t":"以 kcat/Km（专一性常数）判断最适底物：值最大者催化效率最高、最适；其理论上限为 10⁸~10⁹ mol⁻¹·L·s⁻¹，达此值即为催化完美酶。"},{"k":"实验验证方法","t":"固定酶量、改变一种底物浓度测初速度，作双倒数图求 Km 与 Vmax；也可在相同 [S] 下直接比较两底物的反应速度。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0081","subj":"880","chap":"第十一章 柠檬酸循环","type":"问答","years":["01"],"q":"说明天冬氨酸是如何成糖的，天冬氨酸的成糖过程与丙氨酸成糖过程有何异同？","points":[{"k":"转氨脱氨","t":"天冬氨酸 + α-酮戊二酸 —谷草转氨酶→ 谷氨酸 + 草酰乙酸。"},{"k":"草酰乙酸到PEP","t":"草酰乙酸 + GTP —磷酸烯醇式丙酮酸羧激酶→ 磷酸烯醇式丙酮酸 + GDP + CO₂。"},{"k":"逆向酵解","t":"PEP + H₂O→2-磷酸甘油酸⇌3-磷酸甘油酸→（耗 ATP）1,3-二磷酸甘油酸→（耗 NADH）3-磷酸甘油醛⇌磷酸二羟丙酮→醛缩合成 1,6-二磷酸果糖→水解为 6-磷酸果糖。"},{"k":"脱磷酸成糖","t":"6-磷酸果糖异构为 6-磷酸葡萄糖，再由 6-磷酸葡萄糖磷酸酯酶水解生成葡萄糖与 Pi，完成成糖。"},{"k":"丙氨酸成糖","t":"丙氨酸 + α-酮戊二酸 —谷丙转氨酶→ 谷氨酸 + 丙酮酸；丙酮酸 + CO₂ + ATP + H₂O —丙酮酸羧化酶/生物素→ 草酰乙酸 + ADP + Pi + 2H⁺，后续反应同上。"},{"k":"异同比较","t":"相同：均以 α-酮戊二酸为氨受体生成谷氨酸，从草酰乙酸起的糖异生反应相同。不同：丙氨酸多一步丙酮酸羧化，多耗 1 分子 ATP、需消耗 CO₂ 并以生物素为辅酶；天冬氨酸由 4 碳草酰乙酸直接脱羧生成 PEP，不需 CO₂ 与生物素。"}],"note":"口径：依据《真题分类》资料原文，反应式、酶名与能量差异均照录（原文按“多耗 1 分子 ATP”表述，未给总高能键数）。","opts":[],"printed_answer":"","ref":true},{"id":"n0082","subj":"880","chap":"第十四章 氧化磷酸化","type":"问答","years":["01"],"q":"氰化物为什么能引起细胞窒息死亡？其解救机理是什么？","points":[{"k":"结合aa3断电子流","t":"CN⁻ 的 N 原子含孤对电子，与细胞色素 aa₃ 的氧化形式（高价铁 Fe³⁺）以配位键结合成氰化高铁细胞色素 aa₃，使其失去传递电子的能力。"},{"k":"呼吸链中断窒息","t":"电子不能传递给 O₂，呼吸链中断，氧化磷酸化停止，细胞因窒息而死亡。"},{"k":"亚硝酸盐竞争解救","t":"亚硝酸（盐）把血红蛋白血红素辅基上的 Fe²⁺ 氧化为 Fe³⁺ 形成高铁血红蛋白，含量达 20%~30% 时也可与氰化物结合，竞争性抑制 CN⁻ 与 aa₃ 结合，使 aa₃ 活力恢复。"},{"k":"硫代硫酸钠促排","t":"氰化高铁血红蛋白数分钟后逐渐解离放出 CN⁻，故须同时用硫代硫酸钠使 CN⁻ 转变为无毒的 SCN⁻，经肾随尿排出而解毒。"}],"note":"口径：依据《真题分类》资料原文，20%~30% 数字照录。","opts":[],"printed_answer":"","ref":true},{"id":"n0083","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"问答","years":[],"q":"请运用分子生物的原理与方法，就你所了解到的某一种基因工程产品（如基因工程乙肝疫苗、转基因抗虫棉等）或分子检测与治疗方法(如基因治疗、细菌分子鉴定、遗传病分析等)进行说明，要求：(1)基本原理，(2)分子操作步骤\n(注:此题只选一个产品或一个方法进行说明，具体哪种基因工程产品或分子检测方法自行决定，可以是题中所列，也可以是其他的内容。)","points":[{"k":"产品选择","t":"以基因工程乙肝疫苗为例：将乙肝病毒表面抗原（HBsAg）基因导入酵母或 CHO 细胞表达，用重组 HBsAg 颗粒作疫苗，避免血源疫苗的病原污染。"},{"k":"目的基因获取","t":"从 HBV 基因组中扩增 S 基因，或按 HBsAg 氨基酸序列全基因合成并优化酵母偏好密码子，两端加酶切位点。"},{"k":"表达载体构建","t":"S 基因插入含 AOX1（或 CMV）启动子的酵母（或哺乳动物）表达载体，双酶切连接后转化大肠杆菌筛选、酶切与测序鉴定。"},{"k":"转化与诱导表达","t":"线性化质粒电转化毕赤酵母 GS115，筛选高拷贝整合株；甲醇诱导 AOX1 启动子，高密度发酵，细胞可分泌或胞内积累 HBsAg，并自组装为 22 nm 类病毒颗粒。"},{"k":"分离纯化","t":"收集菌体破碎或取发酵上清，经离心、超滤浓缩、离子交换层析、凝胶过滤与密度梯度离心，获得纯度合格的 HBsAg 颗粒，SDS-PAGE 与 Western blot 鉴定。"},{"k":"配制与免疫原理","t":"抗原吸附于铝佐剂制成疫苗；接种后 HBsAg 作为外来抗原被抗原提呈细胞处理，激活辅助性 T 细胞与 B 细胞，产生抗-HBs 中和抗体，阻断 HBV 与肝细胞结合。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0084","subj":"880","chap":"第七章 核酸","type":"简答","years":[],"q":"（3）RNA 携带的 AUG 是什么氨基酸","points":[{"k":"答案甲硫氨酸","t":"AUG 编码甲硫氨酸（Met），同时是翻译起始密码子；原核生物起始为甲酰甲硫氨酸（fMet），真核为 Met。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0085","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":[],"q":"（1）淀粉液化和糖化的酶及水解特点\n（2）脂肪酸 b 氧化酶和产物","points":[{"k":"淀粉液化用α淀粉酶","t":"α-淀粉酶为内切酶，随机水解淀粉分子内部的 α-1,4 糖苷键，使长链迅速断裂、黏度骤降（液化），产物为糊精和少量麦芽糖；工业用耐高温 α-淀粉酶最适 95~105 ℃、pH 5.5~6.5。"},{"k":"糖化用糖化酶","t":"糖化酶（葡萄糖淀粉酶）为外切酶，从非还原端逐个切下葡萄糖，水解 α-1,4 键，也能缓慢切 α-1,6 分支点，最终产物为葡萄糖；最适 pH 4.0~4.5、60 ℃。"},{"k":"脱支酶协同","t":"普鲁兰酶或异淀粉酶专一水解 α-1,6 糖苷键，与糖化酶协同可提高葡萄糖收率；β-淀粉酶为外切酶、产麦芽糖，但不能越过分支点，需脱支酶配合。"},{"k":"β氧化四酶","t":"脂酰 CoA 脱氢酶（FAD，产反-Δ²-烯脂酰 CoA+FADH₂）→烯脂酰 CoA 水化酶（加水，产 β-羟脂酰 CoA）→β-羟脂酰 CoA 脱氢酶（NAD⁺，产 β-酮脂酰 CoA+NADH）→β-酮脂酰 CoA 硫解酶（加 CoA，产乙酰 CoA+缩短两个碳的脂酰 CoA）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0086","subj":"880","chap":"第七章 核酸","type":"简答","years":[],"q":"为什么 RNA 聚合酶在延伸过程当中不像 DNA 聚合酶也要解链酶和 SSB?","points":[{"k":"酶自身可解链","t":"RNA 聚合酶本身具有解旋活性，全酶与启动子结合后即可使 DNA 在活性中心局部解链约 12~14 bp，形成转录泡，无需另加解旋酶。"},{"k":"转录泡小而封闭","t":"解开的单链区很短，且始终被酶蛋白包裹覆盖，没有游离的单链暴露，故不需要单链结合蛋白（SSB）保护。"},{"k":"RNA-DNA杂合稳定","t":"新合成的 RNA 与模板链形成约 8~9 bp 的 RNA-DNA 杂合体，本身即可稳定解开的模板链。"},{"k":"只有一条模板链","t":"转录只以一条链为模板，不要求两条链同时分离与分别复制，解链负担远小于 DNA 复制；转录泡随酶前移不断开合，单链存在时间极短。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0087","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"计算","years":[],"q":"简述天冬氨酸转化为葡萄糖的反应历程，并计算消耗的 ATP 摩尔数","points":[{"k":"转氨生成草酰乙酸","t":"天冬氨酸+α-酮戊二酸 ⇌(AST，磷酸吡哆醛) 草酰乙酸+谷氨酸，此步不耗 ATP。"},{"k":"苹果酸穿梭出膜","t":"草酰乙酸经线粒体苹果酸脱氢酶还原为苹果酸出线粒体内膜，胞质中再氧化为草酰乙酸并生成 NADH，碳骨架得以转运。"},{"k":"脱羧耗GTP","t":"2 mol 草酰乙酸经磷酸烯醇式丙酮酸羧激酶（PEPCK）脱羧，各耗 1 GTP，共耗 2 GTP，生成 2 mol 磷酸烯醇式丙酮酸。"},{"k":"逆向酵解耗ATP","t":"2 mol 3-磷酸甘油酸经磷酸甘油酸激酶逆行生成 2 mol 1,3-二磷酸甘油酸，共耗 2 ATP；随后还原为 3-磷酸甘油醛（耗 2 NADH）。"},{"k":"脱磷酸不耗能","t":"果糖-1,6-二磷酸酶与葡糖-6-磷酸酶催化的是水解反应，只释能、不耗 ATP，故由 2 mol 三碳糖合成 1 mol 葡萄糖不需额外高能键。"},{"k":"合计4个高能键","t":"总消耗 2 ATP+2 GTP=4 个高能磷酸键（另耗 2 NADH），故 2 mol 天冬氨酸净生成 1 mol 葡萄糖消耗 4 mol ATP 当量。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0088","subj":"880","chap":"第七章 核酸","type":"简答","years":[],"q":"DNA复制的相关酶及其作用","points":[{"k":"解旋酶","t":"DnaB 解旋酶水解 ATP、拆开双链氢键，在复制叉处沿模板移动，产生单链模板。"},{"k":"单链结合蛋白","t":"SSB 覆盖解开的单链，防止其重新退火并保护单链不被核酸酶降解。"},{"k":"拓扑异构酶","t":"DNA 拓扑异构酶Ⅰ/Ⅱ（促旋酶）消除解旋产生的正超螺旋、引入负超螺旋，解除复制叉前方的扭转张力。"},{"k":"引物酶与聚合酶Ⅲ","t":"引物酶（DnaG）合成短 RNA 引物；DNA 聚合酶Ⅲ 从引物 3′-OH 起沿 5′→3′ 延伸，具 3′→5′ 外切校对活性，是主要的复制酶。"},{"k":"聚合酶Ⅰ与连接酶","t":"DNA 聚合酶Ⅰ 以 5′→3′ 外切活性切除 RNA 引物并填补缺口；DNA 连接酶（耗 ATP 或 NAD⁺）封闭冈崎片段间的磷酸二酯键缺口。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0089","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"关于蛋白质的，画了一个电泳图，写蛋白质的位置，分离方法（蛋白质分离）","points":[{"k":"SDS电泳按Mr","t":"SDS-PAGE 中蛋白被 SDS 包裹、电荷与形状被统一，迁移率只取决于相对分子质量：小分子迁移快、靠近泳道下端，大分子迁移慢、靠近加样孔。"},{"k":"等电聚焦按pI","t":"等电聚焦在 pH 梯度中电泳，蛋白迁移至 pH 等于其 pI 处净电荷为零而停止，据此读出 pI；双向电泳第一向即用此法。"},{"k":"非变性电泳看电荷","t":"非变性 PAGE 保留天然构象与电荷，迁移方向与快慢由电荷性质、分子大小与形状共同决定，带正电者向负极、带负电者向正极。"},{"k":"判断方法","t":"以标准分子量 Marker 或已知 pI 标记并行电泳，对照条带位置确定待测蛋白的 Mr 或 pI，并据条带单一性评价纯度。"}],"note":"原卷电泳图未保留，无法写出具体条带位置，只能给出各类电泳的判读原则。","opts":[],"printed_answer":""},{"id":"n0090","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":[],"q":"关于奇数 C 脂肪与偶数 C 脂肪，哪个好?","points":[{"k":"偶数链产乙酰CoA","t":"偶数碳脂肪酸经 β-氧化全部生成乙酰 CoA，直接进入柠檬酸循环彻底氧化，不需额外酶与辅因子。"},{"k":"奇数链产丙酰CoA","t":"奇数碳脂肪酸经 β-氧化最后一轮生成 1 分子丙酰 CoA 和若干乙酰 CoA，丙酰 CoA 不能再直接入循环。"},{"k":"丙酰CoA三酶转化","t":"丙酰 CoA 经生物素依赖的丙酰 CoA 羧化酶（耗 1 ATP）→D-甲基丙二酰 CoA→甲基丙二酰 CoA 消旋酶→L-甲基丙二酰 CoA→维生素 B₁₂ 依赖的甲基丙二酰 CoA 变位酶→琥珀酰 CoA，进入柠檬酸循环。"},{"k":"结论偶数碳较优","t":"偶数碳脂肪酸氧化路径短、不耗额外 ATP、不需 B₁₂，产能更经济；奇数碳虽同样能供能（反刍动物与海洋生物中常见），但依赖生物素与 B₁₂，B₁₂ 缺乏时丙酰 CoA 堆积、甲基丙二酸排出，故从代谢经济性看偶数碳更好。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0091","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":[],"q":"糖酵解，带磷酸的中间产物，与别的代谢有关的方程式写出来(几大代谢共有的中间产物)","points":[{"k":"葡糖6磷酸枢纽","t":"葡糖-6-磷酸是糖酵解（己糖激酶/葡糖激酶产物）、糖原分解、糖异生与磷酸戊糖途径的共同中间物：葡糖-6-磷酸+2 NADP⁺+H₂O→核糖-5-磷酸+2 NADPH+CO₂。"},{"k":"果糖6磷酸分支","t":"果糖-6-磷酸由磷酸果糖激酶-1 磷酸化为果糖-1,6-二磷酸进入酵解，也可经磷酸戊糖途径、己糖胺途径（→葡糖胺-6-磷酸）用于糖蛋白合成。"},{"k":"丙糖磷酸共用","t":"3-磷酸甘油醛与磷酸二羟丙酮是酵解与糖异生的交汇点：磷酸二羟丙酮可还原为甘油-3-磷酸，用于甘油磷脂与甘油三酯合成；甘油也可经此进入酵解。"},{"k":"PEP与3磷酸甘油酸","t":"磷酸烯醇式丙酮酸与赤藓糖-4-磷酸缩合生成分支酸，是芳香族氨基酸合成的起点；3-磷酸甘油酸经 3-磷酸羟基丙酮酸生成丝氨酸，进而生成甘氨酸与半胱氨酸。"},{"k":"1,3二磷酸甘油酸","t":"1,3-二磷酸甘油酸是酵解中底物水平磷酸化的供体，也可经二磷酸甘油酸变位酶生成 2,3-二磷酸甘油酸，调节血红蛋白的氧亲和力。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0092","subj":"880","chap":"第三章 氨基酸","type":"简答","years":[],"q":"写出氨基酸的结构是，哪些是酸性氨基酸，哪些是碱性氨基酸等（氨基酸分类、性质）","points":[{"k":"共同骨架","t":"除脯氨酸（Pro）为亚氨基酸外，均为 α-氨基酸：同一个 α-碳上连 —NH₂、—COOH、—H 和侧链 R，R 基的种类决定其性质与分类。"},{"k":"酸性两类","t":"侧链另含一个羧基：天冬氨酸（Asp）、谷氨酸（Glu）。pI 约 2.8~3.2，生理 pH 下带负电，电泳向正极移动。"},{"k":"碱性三类","t":"侧链含氨基、胍基或咪唑基：赖氨酸（Lys）、精氨酸（Arg）、组氨酸（His）。pI 约 7.6~10.8，生理 pH 下带正电。"},{"k":"极性分类","t":"按侧链极性分四组：非极性（Gly、Ala、Val、Leu、Ile、Pro、Phe、Met、Trp）、极性不带电（Ser、Thr、Cys、Tyr、Asn、Gln）、酸性、碱性。"},{"k":"两性电离","t":"α-羧基 pKa≈2，α-氨基 pKa≈9~10，故氨基酸是两性电解质；pH<pI 带正电、pH>pI 带负电、pH=pI 净电荷为零、溶解度最低，可用于等电点沉淀。"},{"k":"紫外吸收","t":"Trp、Tyr、Phe 侧链含苯环，280 nm 有吸收，Trp 最强，是蛋白质 280 nm 定量的基础。"}],"note":"题面为回忆版，只写“结构、酸性/碱性、分类性质”，答案按常见考法给全；若只问分类可略去最后两点。","opts":[],"printed_answer":""},{"id":"n0093","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":[],"q":"乳酸循环（肝糖原、肌糖原的区别）","points":[{"k":"乳酸循环","t":"肌肉剧烈运动时糖无氧酵解生成乳酸，乳酸经血液运至肝，在肝内异生为葡萄糖再回流入肌，称乳酸循环（Cori 循环）。"},{"k":"肌无磷酸酶","t":"肌肉缺乏葡萄糖-6-磷酸酶，糖原分解只到 6-磷酸葡萄糖即进入酵解，故肌糖原不能直接补充血糖，只能供自身收缩用。"},{"k":"肝有磷酸酶","t":"肝有葡萄糖-6-磷酸酶，糖原分解与糖异生都能输出游离葡萄糖，是维持血糖的主要器官。"},{"k":"储量用途不同","t":"肝糖原约占肝重 5%~8%，用于维持血糖；肌糖原约占肌重 1%~2%，只供肌肉自身氧化，储量受肌重限制。"},{"k":"循环耗能","t":"2 分子乳酸异生为 1 分子葡萄糖需消耗 6 个 ATP，净得 2 个；意义是把不能直接产糖的乳酸回收利用，防止乳酸酸中毒。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0094","subj":"880","chap":"第五章 酶","type":"计算","years":[],"q":"葡萄糖 6 磷酸脱氢酶的酶促反应（计算题）酶促反应的各种分析，加抑制剂后画图","points":[{"k":"列式","t":"米氏方程 v=Vmax[S]/(Km+[S])，双倒数线性化 1/v=(Km/Vmax)(1/[S])+1/Vmax；测活按 U=(ΔA/min×V总)/(6220×d×V样)，比活力=U/mg 蛋白。"},{"k":"代入","t":"以 1/[S] 为横轴、1/v 为纵轴描点回归，得截距 b、斜率 m，则 Vmax=1/b、Km=m/b。例：b=0.02、m=0.04，则 Vmax=50、Km=2.0（单位随所用浓度、速度单位）。"},{"k":"结论","t":"由 Km、Vmax 即可算出任意 [S] 时的 v：v=Vmax[S]/(Km+[S])，代入即得；Km 越小表示酶对底物亲和力越大。"},{"k":"抑制类型判定","t":"加抑制剂后纵截距不变、斜率变大、横截距左移为竞争性抑制；纵截距增大、横截距不变为非竞争性；两截距同向变化、斜率不变为反竞争性；交点落在第二象限为混合型。"},{"k":"作图要点","t":"至少取 5~6 个 [S]（跨 Km 上下各 3~5 倍，[S]≫[E]），同一坐标纸画对照线与加抑制剂线，标明轴名、单位与截距数值，用截距读数而不是目测斜率下结论。"}],"note":"原卷数据与图缺失，此处给通式、算法与判据；考场按给定数据代入即可。","opts":[],"printed_answer":""},{"id":"n0095","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"简答","years":[],"q":"给出 64 个密码子，写出起始密码子，终止密码子","points":[{"k":"密码子总数","t":"4³=64 个；其中 61 个编码氨基酸，3 个为终止信号，故有 18~20 种氨基酸存在简并。"},{"k":"起始密码子","t":"原核为 AUG（起始甲硫氨酸被甲酰化为 fMet），GUG、UUG 也可起始；真核几乎只用 AUG，起始为未甲酰化的 Met。"},{"k":"终止三码","t":"UAA（赭石）、UAG（琥珀）、UGA（乳白/蛋白石），不编码任何氨基酸，由释放因子 RF1/RF2 识别并终止肽链延伸。"},{"k":"密码简并","t":"除 Met（AUG）、Trp（UGG）各仅 1 个外，多数氨基酸有 2~6 个同义密码子，第三位碱基变化常不改变氨基酸。"},{"k":"摆动配对","t":"反密码子 5' 位与密码子 3' 位可非严格配对（摆动假说），一种 tRNA 可识别 1~3 个同义密码子，减少 tRNA 种类。"},{"k":"连续通用","t":"阅读方向 5'→3'，无标点、无重叠、阅读框固定；遗传密码基本通用，仅线粒体、某些原核有少数例外。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0096","subj":"880","chap":"第六章 维生素与辅酶","type":"计算","years":[],"q":"能量计算：1mol 丙氨酸氧化产生多少 ATP?","points":[{"k":"转氨脱氨","t":"丙氨酸经联合脱氨生成丙酮酸，同时使谷氨酸脱氢产生 1 NADH（2.5 ATP）。"},{"k":"氧化脱羧","t":"丙酮酸 → 乙酰 CoA，丙酮酸脱氢酶复合体产 1 NADH（2.5 ATP）。"},{"k":"进入TCA","t":"乙酰 CoA 经柠檬酸循环产 3 NADH + 1 FADH₂ + 1 GTP = 10 ATP。"},{"k":"合计","t":"2.5 + 2.5 + 10 = 15 mol ATP。"}],"note":"本手册统一计法：把联合脱氨时谷氨酸脱氢产生的 NADH 计入，得 15。若只算丙酮酸以后的碳骨架（不计转氨步骤的 NADH），则为 12.5——答题时写明是否计入即可。","opts":[],"printed_answer":""},{"id":"n0097","subj":"880","chap":"第四章 蛋白质","type":"论述","years":[],"q":"糖、脂、蛋白质在几大循环中的作用及联系","points":[{"k":"共同枢纽","t":"糖、脂、蛋白质分解最终都生成乙酰 CoA 进入三羧酸循环氧化供能；乙酰 CoA 又是合成脂肪酸、胆固醇的原料，是三者互变的总枢纽。"},{"k":"三羧酸桥梁","t":"α-酮戊二酸、草酰乙酸、琥珀酰 CoA 等中间产物把氨基酸碳骨架与糖、脂代谢连成网络；草酰乙酸既供乙酰 CoA 缩合，又是糖异生起点。"},{"k":"乳酸循环","t":"肌糖原酵解产乳酸→血→肝异生为葡萄糖→回肌，实现糖的器官间循环；生糖氨基酸脱氨后经丙酮酸、三羧酸中间物也能成糖。"},{"k":"转氨尿素","t":"氨基酸脱氨基的氨以丙氨酸-葡萄糖循环运至肝，经尿素循环合成尿素解毒；碳骨架转成丙酮酸、乙酰 CoA 或三羧酸中间物进入糖脂代谢。"},{"k":"脂解酮体","t":"脂肪动员产生甘油与脂肪酸：甘油成糖，脂肪酸 β 氧化产乙酰 CoA；糖不足时草酰乙酸减少，乙酰 CoA 转向生成酮体供脑、心等使用。"},{"k":"流向调节","t":"胰岛素/胰高血糖素、ATP/AMP、NADH/NAD⁺、柠檬酸/异柠檬酸等共同调节关键酶（PFK-1、ACC、丙酮酸脱氢酶），决定物质在各通路间的分配。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0098","subj":"880","chap":"第四章 蛋白质","type":"计算","years":[],"q":"根据实验结果回答下列问题（6 分）\n某科研人员在对酶分离纯化过程中得到以下实验结果：\n（1）计算每步分离后的酶活。\n（2）根据上述计算，指出哪步分离纯化效果最好，为什么？\n（3）根据上述结果能否说明该蛋白质纯度已经很高？还有哪些手段可以检测蛋白质的纯度?\n[表：酶分离纯化实验结果；分离步骤／总蛋白质含量(mg)／活力单位数：1 粗分离 20 000／4 000 000；2 盐析 5 000／3 000 000；3 等电点分离 4 000／1 000 000；4 离子交换 200／900 000；5 亲和层析 50／750 000；6 分子筛层析 45／675 000]","points":[{"k":"列式","t":"比活力=活力单位总数÷总蛋白（U/mg）；纯化倍数=该步比活力÷粗提比活力；回收率=该步总活力÷粗提总活力×100%。"},{"k":"代入","t":"比活力=活力单位÷蛋白量：①4 000 000÷20 000=200；②3 000 000÷5 000=600；③1 000 000÷4 000=250；④900 000÷200=4 500；⑤750 000÷50=15 000；⑥675 000÷45=15 000 U/mg。"},{"k":"结论","t":"各步比活力为 200、600、250、4 500、15 000、15 000 U/mg；以 200 为基准的纯化倍数为 1、3、1.25、22.5、75、75 倍；回收率依次为 100%、75%、25%、22.5%、18.75%、16.9%。"},{"k":"离子交换最优","t":"第 4 步离子交换层析效果最好：比活力由 250 升至 4 500 U/mg，提高 18 倍，该步回收率 900 000/1 000 000=90%，纯度与收率兼顾；第 3 步等电点分离反而由 600 降到 250，最差。"},{"k":"纯度还需佐证","t":"不能只凭比活力断言纯度高。比活力只反映单位蛋白的活性，需 SDS-PAGE 单一条带、HPLC/毛细管电泳、等电聚焦、质谱、N 端测序等证明均一性。"},{"k":"亲和效率高","t":"第 5 步亲和层析比活力达 15 000 U/mg、累计纯化 75 倍，专一性强；但样品容量小、洗脱条件苛刻，故常放在流程后段。"}],"note":"原表数据按题干录入；若“酶活”按总活力理解，则为 4.0×10⁶、3.0×10⁶、1.0×10⁶、9.0×10⁵、7.5×10⁵、6.75×10⁵ U，此时应另算比活力才能比较纯化效果。","opts":[],"printed_answer":""},{"id":"n0099","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"简答","years":[],"q":"质粒要在宿主细胞中复制的必要条件（重组质粒哪些特征有利于在宿主细胞内复制）","points":[{"k":"自主复制元件","t":"必须具有自主复制的能力，即含有与宿主细胞相对应的复制元件（复制起点及能被宿主复制机器识别的序列），否则不能在宿主细胞内复制。"},{"k":"选择标记","t":"携带易于筛选的选择标记，如抗药性标记、营养标记、显色标记，以便对外源基因进行筛选鉴定。"},{"k":"单一酶切位点","t":"含有多种限制酶的单一识别序列，供外源基因插入而不破坏复制与选择功能。"},{"k":"载体尽量小","t":"除保留必要序列外，载体应尽可能小，便于导入细胞和进行繁殖。"},{"k":"使用安全","t":"克隆载体应只存在有限范围的宿主，在体内不进行重组、不发生转移、不产生有害性状，并且不能离开工程宿主自由扩散。"},{"k":"补：拷贝数与相容性","t":"资料未列：宜选合适拷贝数（松弛型高拷贝利于高表达、严谨型稳定），同一细胞共存的两个质粒须属不同不相容群。"}],"note":"口径：依据《真题分类》资料原文；末点拷贝数与不相容群为教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0100","subj":"880","chap":"第二章 脂类","type":"简答","years":[],"q":"流体镶嵌模型及其特点（一道关于磷脂双分子层的题，好像问到其特点）","points":[{"k":"流动镶嵌模型","t":"1972 年 Singer 与 Nicolson 提出：生物膜以磷脂双分子层为骨架，蛋白质镶嵌其中，整体呈二维流体，故称流动镶嵌模型。"},{"k":"脂双层骨架","t":"磷脂亲水头朝两侧、疏水尾相对朝内；脂分子可侧向扩散、旋转、摆动、弯曲，极少发生翻转（flip-flop），需翻转酶协助。"},{"k":"蛋白镶嵌方式","t":"内在蛋白跨膜或嵌入脂双层（跨膜 α 螺旋），外在/周边蛋白靠静电与氢键附着于膜表面；膜蛋白也能侧向移动，但受细胞骨架限制。"},{"k":"膜不对称性","t":"糖脂、糖蛋白的糖链一律朝向膜外侧；磷脂酰丝氨酸（PS）正常位于内叶，翻到外叶即为凋亡信号；两侧蛋白与脂组成不同。"},{"k":"膜流动性","t":"流动性受磷脂脂肪酸不饱和度、链长、胆固醇含量与温度影响：不饱和度高、链短则流动性大；胆固醇在相变温度上下双向调节。"},{"k":"通透与局限","t":"疏水小分子可自由通过，离子与极性分子需通道或载体，形成选择通透的屏障；但模型不能解释脂筏、膜骨架约束的微区与蛋白-脂特异作用，后由脂筏模型补充。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0101","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":[],"q":"乳酸脱氢酶的活性测定(说明乳酸脱氢酶催化的化学反应，并怎样测该酶的活性)","points":[{"k":"催化反应","t":"LDH 是由两种亚基按一定比例组成的四聚体蛋白，体内有 5 种同工酶，是糖酵解途径的关键酶之一，催化可逆反应：乳酸＋NAD⁺ ⇌（乳酸脱氢酶）丙酮酸＋NADH＋H⁺。"},{"k":"紫外分光光度法","t":"NADH、NAD⁺ 在 340 nm 及 260 nm 处各有最大吸收峰，故可通过 340 nm 处光吸收值的改变定量测定酶量，该法简单、快速。"},{"k":"活力单位定义","t":"在 25℃、pH 7.5 条件下，A340nm/min 下降 1.0 的酶量为 1 个单位。"},{"k":"测定步骤","t":"从肌肉匀浆中提取 LDH 并以缓冲液保存；取一只比色杯作对照，加酶与缓冲液后在 340 nm 处调零；另一只依次加丙酮酸钠溶液、NADH 溶液，摇匀后加稀释酶液 10 μL，立即在 A340nm 处每隔 0.5 min 测一次、连续 3 min。"},{"k":"数据处理","t":"以 A 对时间作图，取反应最初线性部分计算 A340nm/min 的减少值；比活力（U/mL）＝ΔA340nm×稀释倍数/酶液加入量（10 μL）×10⁻³，总活力单位＝比活力×总体积（mL）。"}],"note":"口径：依据《真题分类》资料原文（原文另述 LDH 分布与同工酶功能，此处择要并入第一点）。","opts":[],"printed_answer":"","ref":true},{"id":"n0102","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"多聚谷氨酸（glu）n 在 pH<3.0 时呈 α 螺旋状态，在 pH>5.0 时却为松散的 β 折叠，请解释之。（5 分）","points":[{"k":"侧链电荷随pH变","t":"Glu 侧链 pKa 约为 4.1：pH 远低于 4.1（约 3）时几乎所有侧链不带电荷，pH 为 5 或更高时几乎所有侧链都带负电荷。"},{"k":"低pH成α螺旋","t":"侧链不带电、无同种电荷静电排斥，多肽链能够形成 α 螺旋。"},{"k":"高pH静电排斥","t":"邻近残基侧链带同种负电荷，静电排斥力阻止螺旋形成，使同聚物呈伸展的 β 折叠构象。"},{"k":"同类规律","t":"如多聚赖氨酸需 pH 远大于其侧链 pKa（10.5）时才能呈 α 螺旋，说明可离子化侧链构成的螺旋对 pH 高度敏感。"}],"note":"口径：依据《真题分类》资料原文，Glu 侧链 pKa 按原文 4.1（旧稿 4.2 已改）。","opts":[],"printed_answer":"","ref":true},{"id":"n0103","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"简答","years":[],"q":"细菌存在转录后加工吗（5 分）","points":[{"k":"存在但加工少","t":"存在。细菌的转录后加工主要指对 RNA 聚合酶合成的初级转录物进行切割、修剪、修饰等加工，但加工方式远少于真核。"},{"k":"rRNA前体加工","t":"RNA 前体先甲基化，再经 RNaseⅢ切割，生成各种 rRNA 与 tRNA。"},{"k":"tRNA前体加工","t":"tRNA 前体由 RNase P 加工成熟 5′端、RNase F 与 D 加工成熟 3′端，再由 tRNA 核苷酸转移酶在 3′端加-CCA，最后由 tRNA 修饰酶进行碱基修饰，生成成熟 tRNA。"},{"k":"mRNA前体加工","t":"原核生物 mRNA 大多不需加工，只有极少数需要通过 RNaseⅢ进行切割。"},{"k":"补：与原核特点相关","t":"资料未列：细菌无核膜、转录与翻译偶联，mRNA 半衰期仅数分钟，一般不加帽、不加尾、无剪接，主要靠快速降解与 sRNA 调控实现基因表达的快速响应。"}],"note":"口径：依据《真题分类》资料原文（rRNA、tRNA、mRNA 三类加工）；末点与真核对比的加工特点为教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0104","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["16"],"q":"蛋白质合成后的加工修饰内容有哪些?","points":[{"k":"切除与修剪","t":"去除 N 端甲硫氨酸、信号肽与前体肽段，酶原激活（胰蛋白酶原→胰蛋白酶、胰岛素原切去 C 肽）。"},{"k":"二硫键形成","t":"内质网中蛋白二硫键异构酶（PDI）催化两个 Cys 的 —SH 氧化成 —S—S—，稳定三级结构（抗体、胰岛素）。"},{"k":"化学修饰","t":"磷酸化（Ser/Thr/Tyr）、糖基化（N-连接 Asn、O-连接 Ser/Thr）、乙酰化、甲基化、羟化（Pro→羟脯氨酸）、γ-羧化（凝血因子）、泛素化。"},{"k":"辅基装配","t":"血红素与珠蛋白结合、金属离子（Fe、Zn、Cu）配位、生物素与硫辛酸共价连接，形成有活性的全酶。"},{"k":"伴侣折叠","t":"Hsp70、Hsp60（GroEL-GroES）与 PDI、肽酰脯氨酰顺反异构酶（PPI）协助折叠；错误折叠蛋白经泛素-蛋白酶体降解。"},{"k":"亚基组装","t":"多亚基聚合（血红蛋白 α₂β₂）、跨膜转运与亚细胞定位（信号肽、NLS、线粒体前导肽），组装完成才具完整功能。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0105","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"论述","years":["16"],"q":"论述真核生物和原核生物在翻译起始的异同。","points":[{"k":"共同框架","t":"都以 mRNA 为模板，需核糖体大小亚基、起始 tRNA、起始因子、GTP 与 Mg²⁺；都按 5'→3' 读码，起始 tRNA 均进入 P 位。"},{"k":"起始tRNA不同","t":"原核为 fMet-tRNAf^Met（甲酰化），由 IF2 带入；真核为 Met-tRNAi（未甲酰化），由 eIF2 带入。"},{"k":"识别机制","t":"原核靠 mRNA 的 SD 序列（AGGAGG）与 16S rRNA 3' 端配对，起始位点常在多顺反子内部 AUG；真核靠 5' m⁷G 帽结合 eIF4F，沿 mRNA 扫描至第一个 AUG（Kozak 序列）。"},{"k":"因子与核糖体","t":"原核 70S（30S+50S），用 IF1、IF2、IF3；真核 80S（40S+60S），用 eIF1、1A、2、2B、3、4A、4B、4E、4G、5，需 eIF2B 催化 GDP/GTP 交换。"},{"k":"组装顺序","t":"原核：30S+mRNA+fMet-tRNA+IF2→30S 起始复合物→50S 加入→70S；真核：40S+Met-tRNA+eIF2→43S→结合 mRNA 成 48S→扫描→60S 加入成 80S。"},{"k":"能量与调控","t":"两者都耗 GTP（原核 IF2 水解 GTP；真核 eIF2 水解 GTP 并由 eIF2B 再生）；真核起始是翻译调控主要节点（eIF2α 磷酸化、4E-BP），原核相对少见。"},{"k":"时空关系","t":"原核无核膜，边转录边翻译；真核转录在核内、翻译在胞质，时空分离，且 mRNA 需先加工、出核。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0106","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["16"],"q":"写出 DNA 聚合酶 I 和 DNA 聚合酶 III 在功能上的至少三个不同点。","points":[{"k":"功能分工","t":"DNA 聚合酶Ⅲ是染色体复制的主酶，负责前导链与后随链的延伸；DNA 聚合酶Ⅰ主要切除 RNA 引物、填补缺口，并参与 DNA 损伤修复。"},{"k":"持续合成能力","t":"Pol Ⅲ 全酶含 β 滑动夹，持续合成性强，可一次合成上千 kb；Pol Ⅰ 持续合成短，约 20 nt 即脱落，适合短片段填补。"},{"k":"酶活性组成","t":"Pol Ⅰ 单条多肽同时具 5'→3' 聚合、3'→5' 外切（校对）与 5'→3' 外切（切口平移、切引物）；Pol Ⅲ 有聚合与 3'→5' 外切，无 5'→3' 外切。"},{"k":"亚基结构","t":"Pol Ⅲ 为多亚基全酶（α 催化、ε 校对、θ、γ 复合物、β 夹），Pol Ⅰ 为单链多肽（可切成 Klenow 大片段）。"},{"k":"速率与保真","t":"Pol Ⅲ 延伸速率约 1 000 nt/s，错配率约 10⁻⁷；Pol Ⅰ 约 10~20 nt/s，保真度较低。"},{"k":"丰度与基因","t":"polA 编码 Pol Ⅰ，每个细胞约 400 拷贝；polC 编码 Pol Ⅲ，拷贝数仅 10~20，但催化效率高。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0107","subj":"631","chap":"一、染色体结构","type":"简答","years":["16"],"q":"简述真核生物染色体上组蛋白的种类，组蛋白修饰的种类及其生物学意义。","points":[{"k":"五种组蛋白","t":"H1、H2A、H2B、H3、H4 五类；H2A、H2B、H3、H4 各 2 个组成核心八聚体，H1 为连接组蛋白，结合核小体之间的连接 DNA。"},{"k":"富含碱性氨基酸","t":"富含赖氨酸与精氨酸，带正电，与 DNA 磷酸骨架静电结合；H1 赖氨酸最多，H3、H4 精氨酸较多，故与 DNA 结合最紧。"},{"k":"乙酰化","t":"组蛋白乙酰转移酶（HAT）在 Lys 的 ε-氨基加乙酰基，中和正电、减弱与 DNA 结合，染色质松弛，促进转录；去乙酰化酶（HDAC）逆转。"},{"k":"甲基化","t":"组蛋白甲基转移酶在 Lys/Arg 上加甲基，可单、双、三甲基化；H3K4me3、H3K36me3 激活转录，H3K9me3、H3K27me3 抑制转录并形成异染色质。"},{"k":"磷酸化","t":"H3S10 磷酸化与染色体凝集有关；H2AX S139 磷酸化生成 γH2AX，是 DNA 双链断裂的标志，参与损伤修复。"},{"k":"泛素化等","t":"H2A K119、H2B K120 泛素化参与转录抑制与损伤应答；另有 SUMO 化、ADP-核糖基化、脯氨酸异构化等。"},{"k":"组蛋白密码","t":"多种修饰的组合被效应蛋白特异识别，决定染色质开放或关闭，调控复制、转录、修复与重组；修饰可遗传，属表观遗传信息。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0108","subj":"631","chap":"综合","type":"简答","years":["16"],"q":"简述利用双脱氧末端终止法（Sanger 法）测定 DNA 一级结构的原理。","points":[{"k":"双脱氧终止","t":"ddNTP 的 2' 与 3' 位均无羟基，掺入后无法与下一个 dNTP 形成 3',5'-磷酸二酯键，链延伸就此终止，故称末端终止法。"},{"k":"四组反应","t":"同一模板、同一引物、DNA 聚合酶与四种 dNTP，分四管各加入少量一种 ddNTP（ddATP/ddTTP/ddGTP/ddCTP），得到四组以不同碱基结尾、长度不等的片段。"},{"k":"标记与检测","t":"用放射性 ³²P 标记引物或荧光标记 ddNTP；早期四泳道放射自显影，现用毛细管电泳四色荧光，激光激发后按颜色与迁移时间判读。"},{"k":"由短到长读序","t":"电泳按分子量分离，片段越短迁移越快；从凝胶最底部（最短）向上依次读，得到新合成链 5'→3' 的序列，再按碱基互补写出模板链序列。"},{"k":"必要条件","t":"需单链模板、特异引物、Klenow 片段或 T7 DNA 聚合酶（3'→5' 外切活性低）、dNTP 与 ddNTP 比例约 100:1，保证片段长度连续分布。"},{"k":"方法局限","t":"单次只能读 500~1 000 bp，需克隆分段；现已多被二代测序取代，但仍是验证测序结果与定点突变的金标准。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0109","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["16"],"q":"原核生物与真核生物存在哪些类型的转座子? 转座机理有哪些?","points":[{"k":"插入序列","t":"原核最简转座子为 IS 元件：仅含转座酶基因，两端为反向重复序列（IR），插入后使靶位点产生正向重复（TSD）。"},{"k":"复合转座子","t":"复合转座子（Tn）两端为同向或反向的 IS，中间携带抗性基因，如 Tn10（四环素）、Tn5（卡那霉素）；转座靠两端 IS 提供的转座酶。"},{"k":"复制型转座","t":"Tn3、γδ、Tn501 带转座酶与解离酶（resolvase），经复制型共整合中间体，再由解离酶在 res 位点拆分；转座子复制一份插入新位点、供体原位保留，不造成供体缺失，Tn3 与 Mu 属此。"},{"k":"真核转座子","t":"DNA 型：Ac/Ds、Spm/dSpm（玉米）、P 元件（果蝇）、Tc1/Mariner；逆转座子：LTR 型 Ty1/copia，非 LTR 型 LINE（L1）与 SINE（Alu）。"},{"k":"剪切粘贴","t":"转座酶切下供体元件，插入靶位点；供体位点留下双链断裂需修复，IS、P 元件、Tc1 属此；过程不复制，转座子数目不变。"},{"k":"逆转座机理","t":"以 RNA 为中间体，逆转录酶合成 cDNA，整合酶（IN）插入基因组；LTR 型经病毒样颗粒，非 LTR 型（LINE）用 ORF2 的内切酶/逆转录酶经 TPRT 直接原位反转录。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0110","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["16"],"q":"简述真核生物 rRNA 基因、tRNA 基因和 mRNA 基因的转录机制。","points":[{"k":"三种聚合酶","t":"真核有 RNA 聚合酶Ⅰ（核仁，转录 45S rRNA 前体→18S、5.8S、28S）、Ⅱ（核质，转录 mRNA 及多数 snRNA）、Ⅲ（核质，转录 tRNA、5S rRNA、U6 snRNA）。"},{"k":"聚合酶Ⅰ机制","t":"启动子含核心元件与上游控制元件（UCE），由 UBF 结合、SL1（TBP+TAF）定位，Rrn3 协助起始，在核仁中转录出 45S 前体后切割修饰。"},{"k":"聚合酶Ⅱ机制","t":"核心启动子含 TATA 盒、BRE、Inr、DPE；TFIID 的 TBP 识别 TATA，TFIIA/B/F/E/H 依次组装成起始前复合物（PIC），TFIIH 的激酶磷酸化 CTD Ser5 而启动。"},{"k":"聚合酶Ⅲ机制","t":"tRNA 基因用内部启动子（A 盒、B 盒），由 TFIIIC 识别、TFIIIB（TBP+Brf1+Bdp1）定位，Pol Ⅲ 起始；5S rRNA 基因用 C 盒，需 TFIIIA。"},{"k":"终止方式","t":"Pol Ⅰ 依赖终止因子 TTF-Ⅰ；Pol Ⅱ 无明确终止子，在 poly(A) 位点切割后由 Xrn2 的“鱼雷”模型终止；Pol Ⅲ 遇 poly(T) 即终止。"},{"k":"转录后加工","t":"rRNA 甲基化、假尿苷化并切割成熟；tRNA 切 5'/3' 端、加 CCA、碱基修饰；mRNA 加帽、加尾、剪接，且边转录边加工。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0111","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["16"],"q":"简述真核与原核基因转录方面存在的差异。（2024 年也考了原题）","points":[{"k":"酶与定位","t":"原核只有一种 RNA 聚合酶（核心酶 α₂ββ'ω，σ 因子识别启动子），转录与翻译同在胞质并偶联；真核有三种聚合酶，转录在核内、翻译在胞质。"},{"k":"启动子差异","t":"原核靠 −10 区（TATAAT）与 −35 区（TTGACA），由 σ 因子识别；真核有 TATA 盒、CAAT 盒、GC 盒，需通用转录因子与特异转录因子共同识别。"},{"k":"起始机制","t":"原核 σ 因子识别启动子后全酶形成闭合复合物，解链不需 ATP；真核需 TFIID/TBP 结合 TATA、TFIIH 水解 ATP 解链并磷酸化 CTD。"},{"k":"转录单位","t":"原核多为多顺反子，一个启动子转录多个基因，mRNA 不加工；真核多为单顺反子，初级转录物需加帽、加尾、剪接。"},{"k":"终止调控","t":"原核靠 ρ 因子依赖终止或 GC 发夹加 poly(U) 的不依赖 ρ 终止；真核 Pol Ⅱ 靠 poly(A) 位点与鱼雷模型终止，并有增强子、沉默子、绝缘子远距离调控。"},{"k":"调控层级","t":"原核以操纵子（阻遏/诱导、CAP-cAMP）在转录水平调控为主；真核有染色质重塑、转录因子、加工、出核、翻译与降解多级调控。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0112","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":["16"],"q":"在基因的表达调控中增强子的作用特点有哪些? 有哪些类型的增强子?","points":[{"k":"增强子定义","t":"能显著提高同源启动子转录效率的 DNA 序列，通常含多个转录因子结合位点，本身不是启动子，不能单独起始转录。"},{"k":"远距离作用","t":"可位于基因上游、下游、内含子中，甚至距启动子数十 kb 至上 Mb，作用不受距离限制。"},{"k":"方向无关","t":"正、反两个方向插入都能起作用，与启动子的相对方向无关；但组织特异性强，位置效应明显。"},{"k":"组织特异性","t":"常含组织特异转录因子结合位点，决定基因的时空表达，如免疫球蛋白增强子只在 B 细胞中起作用。"},{"k":"成环机制","t":"通过 DNA 成环（looping）与启动子、转录工厂接触，招募中介体（Mediator）、HAT 与 Pol Ⅱ，不依赖其与启动子的线性距离。"},{"k":"增强子类型","t":"①组成型（通用）增强子；②诱导型（激素反应元件、NF-κB 位点）；③组织特异型；④超级增强子（super-enhancer，成簇富集 Mediator）；⑤沉默子为负调控元件。"},{"k":"与沉默子区别","t":"沉默子同样远距离、方向无关，但抑制转录；绝缘子（insulator）阻断增强子-启动子作用，划定染色质结构域。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0113","subj":"631","chap":"综合","type":"简答","years":["14"],"q":"什么是 DNA 的 Tm 值？它受哪些因素的影响？","points":[{"k":"Tm定义","t":"DNA 双链加热变性时，增色效应达到最大增幅一半（A260 升至最大值的 50%）所对应的温度，即解链温度或熔解温度。"},{"k":"GC含量","t":"GC 含量越高 Tm 越高，因 G≡C 有三个氢键；经验式 Tm=69.3+0.41×GC%（1×SSC），短寡核苷酸用 Tm=2(A+T)+4(G+C)。"},{"k":"长度与离子强度","t":"片段越长、DNA 浓度越高，Tm 越高，20 bp 以下寡核苷酸更明显；Na⁺ 等一价阳离子可中和磷酸骨架负电、减少链间排斥，使 Tm 升高，Mg²⁺ 作用更强。"},{"k":"pH与变性剂","t":"极端 pH（<5 或 >9）使碱基质子化/去质子化，氢键不稳，Tm 下降；尿素、甲酰胺、乙醇等变性剂降低 Tm。"},{"k":"序列不均一","t":"AT 富集区先解链、GC 富集区后解链，Tm 是整体平均指标；实测曲线常呈多相，反映序列不均匀。"},{"k":"实际应用","t":"用于 PCR 退火温度设计（常取 Tm−5℃）、杂交严谨性控制、DNA 纯度判断与 GC 含量估算。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0114","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["14"],"q":"真核生物 DNA 的复制在哪些水平上受到调控？","points":[{"k":"起始许可","t":"G1 期组装前复制复合物（pre-RC：ORC-Cdc6-Cdt1-MCM2-7），S 期 CDK 与 DDK 磷酸化激活，实现“每个起点只起始一次”。"},{"k":"起点选择","t":"真核有多个复制子，起点（ARS/ORI）的启用顺序受染色质状态与核内位置影响，常染色质早复制、异染色质晚复制。"},{"k":"检查点调控","t":"S 期内检查点（ATR-Chk1）感知复制叉停滞与单链 DNA，抑制晚期起点激活、稳定复制叉，保证基因组的完整复制。"},{"k":"染色质偶联","t":"复制与组蛋白合成、装配偶联（CAF-1、ASF1），旧组蛋白修饰分配至子链，实现表观遗传信息的继承。"},{"k":"端粒调控","t":"端粒酶活性受发育与细胞类型调控，决定复制性衰老；端粒结合蛋白 TRF1/TRF2/POT1 调控端粒长度与保护。"},{"k":"周期与信号","t":"细胞周期蛋白与 CDK（Cyclin D-E/A）、生长因子、癌基因与抑癌基因（p53、Rb）共同控制 G1/S 转换，决定是否进入复制。"},{"k":"修复保真","t":"错配修复、跨损伤合成、同源重组修复与复制偶联；Pol δ/ε 的 3'→5' 外切校对保证复制保真度。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0115","subj":"631","chap":"一、染色体结构","type":"简答","years":["14"],"q":"原核、真核基因组的结构特点？","points":[{"k":"大小形态","t":"原核基因组小（0.6~10 Mb），多为单拷贝环状双链 DNA，无核膜，形成类核；真核基因组大（人约 3 000 Mb），多条线状染色体，与组蛋白结合。"},{"k":"基因密度","t":"原核基因密度高、基因间区短、一般无内含子，基因常成簇为操纵子共同转录；真核基因密度低、多含内含子、以单顺反子转录为主。"},{"k":"重复序列","t":"原核几乎无重复序列（除 IS、rRNA 基因）；真核有大量重复序列：卫星 DNA、小卫星、微卫星、LINE/SINE（Alu）、rRNA 基因串联重复。"},{"k":"非编码区","t":"原核非编码区占比小；真核基因间区与内含子占绝大部分，人类编码序列不足基因组 2%。"},{"k":"染色质包装","t":"真核经核小体—30 nm 纤维—环状结构域—染色体多级包装，有着丝粒、端粒与复制起点；原核靠超螺旋与类核蛋白包装。"},{"k":"遗传组织","t":"原核有质粒、噬菌体与转座子，基因水平转移常见；真核有基因家族、假基因、可变剪接与表观遗传，还有线粒体/叶绿体自身基因组。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0116","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["14"],"q":"简述泛素化修饰介导的蛋白质降解","points":[{"k":"三级酶促","t":"泛素经 E1（激活，耗 ATP）→E2（载体）→E3（连接酶）级联，将泛素 C 端 Gly 与底物 Lys 的 ε-氨基形成异肽键。"},{"k":"K48链标记","t":"底物上再接多个泛素，形成 K48 连接的多聚泛素链（一般≥4 个），才能被 26S 蛋白酶体高效识别。"},{"k":"蛋白酶体降解","t":"19S 调节颗粒识别泛素链、去折叠并去泛素化，把底物送入 20S 核心颗粒，由 β1、β2、β5 水解；E1 激活、19S 展开与转运均耗 ATP，产物为 7~9 肽，再由胞质肽酶水解为氨基酸。"},{"k":"E3决定特异","t":"人类有 600 多种 E3（RING、HECT 两类），决定底物识别与时相；SCF、APC/C 通过识别磷酸化降解决定子调控细胞周期。"},{"k":"生理意义","t":"调控细胞周期（Cyclin、p27）、信号转导（IκB、p53）、蛋白质量控制（ERAD）、抗原呈递（MHC-Ⅰ）与 DNA 修复。"},{"k":"疾病与药物","t":"泛素化异常与肿瘤、神经退行性疾病相关；蛋白酶体抑制剂（硼替佐米）治疗多发性骨髓瘤；PROTAC 技术利用泛素化降解靶蛋白。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0117","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["14"],"q":"tRNA 在组成和结构上有哪些特点？","points":[{"k":"组成与修饰","t":"74~95 nt 单链 RNA，含 10%~20% 稀有碱基（假尿苷 ψ、二氢尿苷 D、次黄嘌呤 I 及甲基化碱基）；修饰碱基稳定结构、影响配对，tRNA 身份由反密码子、鉴别碱基与可变臂共同决定。"},{"k":"三叶草结构","t":"二级结构呈三叶草形，含氨基酸臂、D 臂、反密码子臂、TψC 臂与可变臂；各臂由 3~5 bp 的茎和 7~8 nt 的环组成。"},{"k":"倒L形三级","t":"进一步折叠成倒 L 形，氨基酸接受臂与反密码子相距约 7 nm，正好跨越核糖体 A、P 位，与 mRNA 和肽酰转移中心同时接触。"},{"k":"3'端CCA","t":"3' 端一律为 CCA-OH，氨基酸通过酯键连接在末端腺苷酸的 3'-OH 上，由氨酰-tRNA 合成酶催化，形成氨酰-tRNA。"},{"k":"反密码子","t":"反密码子环中部 3 个碱基与 mRNA 密码子反向平行互补；反密码子第一位可与密码子第三位摆动配对。"},{"k":"生理功能","t":"携带并转运氨基酸、解读密码子、作为连接氨基酸与核酸的适配器参与肽链合成，还参与细胞壁合成与基因表达调控。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0118","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["14"],"q":"什么是信号肽？它在序列组成上有哪些特点，有何功能？","points":[{"k":"信号肽定义","t":"分泌蛋白 N 端的一段 15~30 个氨基酸短肽，引导新生肽链进入内质网，完成转运后被信号肽酶切除。"},{"k":"三段结构","t":"N 端带正电的 n 区（1~5 个碱性残基）→中央疏水核心 h 区（6~15 个 Leu、Val、Phe 等疏水残基）→C 端极性 c 区（含 Ala-X-Ala 切割位点）。"},{"k":"识别与停靠","t":"信号肽被信号识别颗粒（SRP）识别，SRP-核糖体复合物结合内质网上的 SRP 受体，GTP 水解后转入易位子 Sec61。"},{"k":"共翻译转运","t":"肽链边合成边经 Sec61 孔道进入内质网腔，信号肽被信号肽酶切除，寡糖转移酶加 N-糖链，分子伴侣协助折叠。"},{"k":"功能与定位","t":"决定蛋白进入分泌途径（内质网→高尔基→分泌泡、膜或溶酶体）；也是工程菌分泌表达外源蛋白的常用元件。"},{"k":"其他靶向序列","t":"线粒体/叶绿体前导肽为两性 α 螺旋，跨膜需 ATP；核定位信号（NLS）富含碱性残基；过氧化物酶体用 PTS1（C 端 SKL）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0119","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":["14"],"q":"简述乳糖操纵子的调控模型。","points":[{"k":"操纵子组成","t":"调节基因 lacI、启动子 P、操纵基因 O 与结构基因 lacZ（β-半乳糖苷酶）、lacY（乳糖透性酶）、lacA（硫代半乳糖苷转乙酰酶）串联组成。"},{"k":"负调控","t":"无诱导物时 LacI 阻遏蛋白四聚体结合 O，阻挡 RNA 聚合酶；乳糖经 β-半乳糖苷酶转为异乳糖，结合阻遏蛋白使其构象改变、脱离 O，实现去阻遏。"},{"k":"正调控","t":"葡萄糖缺乏时 cAMP 升高，cAMP-CAP 复合物结合启动子上游 CAP 位点，促进 RNA 聚合酶结合，转录效率提高约 50 倍。"},{"k":"双信号整合","t":"只有“有乳糖且无葡萄糖”时才高水平表达；有葡萄糖则 cAMP 低、CAP 不结合，即使去阻遏也仅低水平转录，即葡萄糖效应。"},{"k":"诱导物","t":"异乳糖为天然诱导物，IPTG 为人工不可代谢诱导物；诱导的本质是解除阻遏，并非诱导基因突变。"},{"k":"调控类型","t":"lac 操纵子是可诱导型、负调控为主并受 CAP 正调控的典型；lacY 负责乳糖转运，lacZ 水解乳糖供菌利用。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0120","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":["14"],"q":"什么是葡萄糖效应？","points":[{"k":"葡萄糖效应","t":"培养基中同时含葡萄糖与乳糖时，细菌优先利用葡萄糖，乳糖操纵子表达受抑制，生长曲线出现两个对数期的“二次生长”现象。"},{"k":"cAMP下降","t":"葡萄糖经 PTS 系统转运时，EⅡA^Glc 去磷酸化，腺苷酸环化酶（Cya）激活减少，胞内 cAMP 浓度下降。"},{"k":"CAP不结合","t":"cAMP 不足则不能形成 cAMP-CAP 复合物，CAP 位点空置，RNA 聚合酶不能高效结合启动子，转录水平低。"},{"k":"与阻遏协同","t":"即使有乳糖使阻遏蛋白脱离 O，缺乏 CAP-cAMP 正调控仍不能高效转录；两种信号同时满足才充分表达。"},{"k":"二次生长曲线","t":"先利用葡萄糖快速生长，葡萄糖耗尽后出现停滞期，菌体合成乳糖利用酶，随后以乳糖为碳源再次生长。"},{"k":"生理意义","t":"优先利用最易代谢、产能最高的碳源，避免同时合成不必要的酶，节省能量；属碳源代谢物阻遏的典型，也影响半乳糖、麦芽糖、阿拉伯糖操纵子。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0121","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"简答","years":[],"q":"什么是 DNA 的半不连续复制?","points":[{"k":"半不连续复制","t":"DNA 复制时前导链连续合成，后随链以冈崎片段形式不连续合成，整体表现为“半不连续”，是半保留复制在两条链上的不同表现。"},{"k":"前导链连续","t":"以 3'→5' 走向的模板链为模板，新链沿复制叉前进方向 5'→3' 连续延伸，只需一个引物。"},{"k":"后随链分段","t":"以 5'→3' 走向的模板为模板，必须分段合成；每段由 RNA 引物起始，生成 1~2 kb（真核 100~200 bp）的冈崎片段。"},{"k":"片段连接","t":"RNase H 与 FEN1 切除 RNA 引物，Pol δ 填补缺口，DNA 连接酶封口，把冈崎片段连成完整子链。"},{"k":"复制体不对称","t":"两条链由同一复制体合成，后随链模板成环（trombone 模型）以调整方向，使两条链的合成在空间上协调。"},{"k":"证据与意义","t":"冈崎片段的发现是半不连续复制的直接证据；该机制保证新链只能 5'→3' 合成，与 DNA 聚合酶的合成方向一致。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0122","subj":"880","chap":"第五章 酶","type":"论述","years":[],"q":"下图是具有别构效应的酶与非调节酶的动力学曲线，请指出曲线 1，2 分别代表那种酶，并依图中的数据说明什么是酶的别构效应以及别构效应是怎样对酶反应速度进行调节控制的。（15 分）\n[图：酶促反应速度对底物浓度的曲线；纵轴 V，标出 100%、90%、50%；横轴 [S] 刻度 0～8；曲线 1 为矩形双曲线，上升较快后趋于平台，旁注 [S]90%Vm/[S]10%Vm=8；曲线 2 为 S 形曲线，上升较缓，旁注 [S]90%Vm/[S]10%Vm=3；两曲线共同趋向 Vmax]","points":[{"k":"曲线归属","t":"曲线 1 为矩形双曲线，符合米氏方程，代表非调节酶；曲线 2 为 S 形曲线，代表别构酶。"},{"k":"数据解读","t":"曲线 1 的 [S]90%/[S]10% = 81（米氏酶的固定值：v=0.9Vmax 时 [S]=9Km，v=0.1Vmax 时 [S]=Km/9）；曲线 2 仅约 3，比值越小说明协同性越强。"},{"k":"别构效应定义","t":"效应物结合酶的别构部位（调节部位），引起构象改变，从而改变活性中心的催化效率；效应物不结合活性中心。"},{"k":"同促与异促","t":"底物自身作效应物称同促效应，产生 S 形曲线；其他代谢物作效应物称异促效应，可为别构激活或别构抑制。"},{"k":"协同机制","t":"别构酶为多亚基寡聚体，经序变模型（KNF）或齐变模型（MWC）在 T 态与 R 态间转换，一个亚基结合底物促进其余亚基结合。"},{"k":"调节控制","t":"别构激活剂使曲线左移、K0.5 减小；别构抑制剂使曲线右移、S 形更陡；Vmax 可不变，靠效应物浓度快速调节通路流量。"}],"note":"原图只给两个比值，据此作定性说明；若要定量，可用 Hill 方程 log[v/(Vmax−v)] = nH·log[S] − nH·logK0.5 求 Hill 系数。","opts":[],"printed_answer":""},{"id":"n0123","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"问答","years":[],"q":"tRNA 的二级结构有何特点，请用简图形式画出其基本结构，并说明 tRNA 的生理功能（10 分）","points":[{"k":"三叶草形二级结构","t":"tRNA 由 73~93 个核苷酸组成，一级序列含大量稀有碱基，二级结构呈三叶草形，含「三环一臂」：D 环、反密码子环、TψC 环三环构成叶片，氨基酸臂（受体臂）构成叶柄，另有一个可变环（多余环）。"},{"k":"氨基酸臂","t":"即受体臂，是结合氨基酸的位点，其 3′端最后 3 个碱基均为 CCA 并伸出双链之外，末端腺苷酸的 3′-OH（或 2′-OH）可被氨酰化，在氨酰-tRNA 合成酶催化下与氨基酸连接成氨酰-tRNA。"},{"k":"D环","t":"因含二氢尿嘧啶而得名，是 tRNA 三环之一。"},{"k":"TψC环","t":"据所含 3 个核苷酸得名：T 表示胸苷酸、ψ 表示假尿苷酸（tRNA 特有的不常见核苷酸）、C 表示胞苷酸。"},{"k":"反密码子环","t":"因套索中央的三联反密码子得名，反密码子可与 mRNA 三联密码子互补配对，环两端由 5′端尿嘧啶与 3′端嘌呤界定；可变环则因核苷酸序列长度变化大而得名，是 tRNA 核苷酸数不同的主要原因。"},{"k":"生理功能","t":"①参与蛋白质合成：反密码子环识别 mRNA 密码子、受体臂接受活化氨基酸，起解读密码子、转运氨基酸的作用；②作为逆转录酶的引物参与逆转录；③作为校正 tRNA 在 RNA 再编码中校正错义、无义与移码突变；④作为激素、转录调节因子参与细胞代谢与基因表达调节；⑤参与叶绿素、细胞壁、细胞膜成分的合成。"}],"note":"口径：依据《真题分类》资料原文。简图按资料三叶草式：上端叶柄为氨基酸臂并标 3′-CCA，三片叶分别为 D 环、反密码子环、TψC 环，另附一小可变环。","opts":[],"printed_answer":"","ref":true},{"id":"n0124","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"论述","years":[],"q":"什么是逆转录酶？试论述其生物学意义（10 分）","points":[{"k":"逆转录酶定义","t":"以 RNA 为模板合成 DNA（cDNA）的 DNA 聚合酶，即 RNA 依赖的 DNA 聚合酶；存在于逆转录病毒、逆转座子中，端粒酶是其特化形式。"},{"k":"三种活性","t":"①RNA 依赖的 DNA 聚合酶活性（合成负链）；②RNase H 活性（水解 RNA-DNA 杂交链中的 RNA）；③DNA 依赖的 DNA 聚合酶活性（合成正链）。"},{"k":"反应过程","t":"宿主 tRNA 作引物结合病毒 RNA→合成负链 DNA→RNase H 降解 RNA 模板→合成正链，形成双链前病毒 DNA→整合酶介导插入宿主基因组。"},{"k":"无校对活性","t":"缺乏 3'→5' 外切酶校对活性，错配率约 10⁻⁴~10⁻⁵，比宿主 DNA 聚合酶高得多，是病毒快速变异与免疫逃逸的分子基础。"},{"k":"补充中心法则","t":"证明遗传信息可由 RNA→DNA 反向传递，打破“DNA→RNA→蛋白质”的单向流动，完善了中心法则，解释 RNA 病毒的复制与致瘤机制。"},{"k":"生物学意义","t":"①逆转录病毒（HIV）复制与致病；②逆转座子塑造基因组与进化；③端粒酶延伸端粒，维持干细胞与癌细胞增殖；④基因工程合成 cDNA。"},{"k":"应用与药物","t":"用于 cDNA 克隆、RT-PCR、qRT-PCR、转录组测序与 cDNA 文库构建；核苷类逆转录酶抑制剂（AZT、替诺福韦）与非核苷类抑制剂用于抗 HIV。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0125","subj":"880","chap":"第四章 蛋白质","type":"问答","years":[],"q":"对于蛋白质混合物的分离，一般是根据（1）分子的大小（2）溶解度（3）电荷（4）吸附性质（5）对其它分子的生物学亲和力等来设计分离的，请列举出以上 5 个方面所涉及的蛋白质分离方法，每个方面至少列举 2 种方法（10 分）","points":[{"k":"按分子大小","t":"凝胶过滤层析（分子排阻，Sephadex/Sephacryl）、透析与超滤、SDS-PAGE、蔗糖密度梯度超速离心。"},{"k":"按溶解度","t":"盐析（硫酸铵分级沉淀）、有机溶剂沉淀（乙醇、丙酮）、等电点沉淀、聚乙二醇沉淀、双水相萃取。"},{"k":"按电荷","t":"离子交换层析（DEAE-纤维素阴离子、CM-纤维素阳离子）、电泳（非变性 PAGE、等电聚焦）、等电点沉淀、毛细管电泳。"},{"k":"按吸附性质","t":"吸附层析（羟基磷灰石、硅胶）、疏水层析（HIC，苯基/丁基柱）、反相层析、活性炭吸附。"},{"k":"按生物学亲和","t":"亲和层析（His-tag/Ni-NTA、GST 标签、抗体-抗原、凝集素-糖链）、免疫沉淀（IP/Co-IP）、亲和电泳。"},{"k":"组合策略","t":"先粗分级（差异离心、盐析）再精细纯化（离子交换→凝胶过滤→亲和层析）；全程 0~4℃、加蛋白酶抑制剂，以比活力与回收率评价每步。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0126","subj":"880","chap":"第四章 蛋白质","type":"选择","years":["21"],"q":"请指出①肌红蛋白（MW：16900）②过氧化氢酶（MW：247500）③细胞色素 c（MW：13[?]）和④糜蛋白酶原（MW：23240）在凝胶过滤柱上洗脱出来的顺序。","points":[{"k":"答案","t":"B（②-④-①-③）。凝胶过滤按分子由大到小出峰：过氧化氢酶 247500 最先行，糜蛋白酶原 23240 其次，肌红蛋白 16900，细胞色素 c 最小最后。"}],"note":"","opts":["A. ①-③-②-④","B. ②-④-①-③","C. ③-①-④-②","D. ④-③-①-②"],"printed_answer":"B"},{"id":"n0127","subj":"880","chap":"第一章 糖类","type":"选择","years":["21"],"q":"下列______含有果糖。","points":[{"k":"答案","t":"A 蔗糖。蔗糖由葡萄糖与果糖各一分子组成；乳糖为半乳糖+葡萄糖，麦芽糖、纤维二糖均为葡萄糖二聚体。"}],"note":"","opts":["A. 蔗糖","B. 乳糖","C. 麦芽糖","D. 纤维二糖"],"printed_answer":"A"},{"id":"n0128","subj":"880","chap":"第十五章 脂类代谢","type":"选择","years":["21"],"q":"______是脂肪酸β-氧化的限速酶。","points":[{"k":"答案","t":"A 脂酰肉碱移位酶Ⅰ（CPTⅠ）。它催化脂酰肉碱生成并跨内膜转运，是 β-氧化的限速步骤，受丙二酰 CoA 抑制。"}],"note":"","opts":["A. 脂酰肉碱移位酶Ⅰ","B. 脂酰肉碱移位酶Ⅱ","C. 脂酰CoA脱氢酶","D. 脂酰CoA合成酶"],"printed_answer":"A"},{"id":"n0129","subj":"880","chap":"综合","type":"选择","years":["21"],"q":"下列______在280nm处具有紫外光吸收。","points":[{"k":"答案","t":"A 酪氨酸。Tyr、Trp、Phe 含苯环共轭体系，在 280 nm 有特征吸收，故可用 A280 测蛋白浓度。"}],"note":"","opts":["A. 酪氨酸","B. 亮氨酸","C. 组氨酸","D. 半胱氨酸"],"printed_answer":"A"},{"id":"n0130","subj":"880","chap":"第十四章 氧化磷酸化","type":"选择","years":["21"],"q":"下列哪种物质能专一性的抑制ATP合酶的Fo因子。","points":[{"k":"答案","t":"B 寡霉素。它结合 ATP 合酶 Fo 亚基阻断质子通道；鱼藤酮、安密妥抑制复合体Ⅰ，抗霉素 A 抑制复合体Ⅲ。"}],"note":"","opts":["A. 鱼藤酮","B. 寡霉素","C. 抗霉素A","D. 安密妥"],"printed_answer":"B"},{"id":"n0131","subj":"880","chap":"第十五章 脂类代谢","type":"选择","years":["21"],"q":"脂肪酸的合成代谢中，乙酰CoA是通过______转运的。","points":[{"k":"答案","t":"A 柠檬酸-丙酮酸循环。线粒体内乙酰 CoA 与草酰乙酸缩成柠檬酸运出，胞质中再裂解出乙酰 CoA 供合成，同时产生 NADPH。"}],"note":"","opts":["A. 柠檬酸-丙酮酸循环","B. 柠檬酸-苹果酸循环","C. 丙酮酸-葡萄糖循环","D. 丙氨酸-葡萄糖循环"],"printed_answer":"A"},{"id":"n0132","subj":"880","chap":"第十一章 柠檬酸循环","type":"选择","years":["21"],"q":"“Krebs bicycle”中______是两个循环的连接物质。","points":[{"k":"答案","t":"A 延胡索酸。尿素循环中精氨酸琥珀酸裂解生成延胡索酸，后者进入 TCA 变为苹果酸、草酰乙酸，故称 Krebs 双循环。"}],"note":"","opts":["A. 延胡索酸","B. 苹果酸","C. 柠檬酸","D. α-酮戊二酸"],"printed_answer":"A"},{"id":"n0133","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"选择","years":["21"],"q":"决定tRNA携带氨基酸特异性的关键部位是______。","points":[{"k":"答案","t":"D 反密码子环。反密码子与 mRNA 密码子互补配对，决定该 tRNA 携带的氨基酸能否正确就位；3′ 端 CCA 只负责连接氨基酸。"}],"note":"","opts":["A. 3’末端","B. 二氢尿嘧啶环","C. 额外环","D. 反密码子环"],"printed_answer":"D"},{"id":"n0134","subj":"880","chap":"第四章 蛋白质","type":"选择","years":["21"],"q":"______是蛋白质的不可逆沉淀。","points":[{"k":"答案","t":"B 加单宁酸。单宁酸、三氯乙酸、重金属盐使蛋白变性沉淀且不可逆；硫酸铵盐析与低温有机溶剂沉淀属可逆沉淀。"}],"note":"","opts":["A. 加入硫酸铵使蛋白质析出","B. 加入单宁酸使蛋白析出","C. 加入正丁醇使蛋白质析出","D. 用1M NaOH 调 pH 使蛋白析出"],"printed_answer":"B"},{"id":"n0135","subj":"880","chap":"第十章 糖酵解 糖异生","type":"选择","years":["21"],"q":"乳酸脱氢酶在心肌中含量最高的是______。","points":[{"k":"答案","t":"D H₄。心肌以 H 型亚基为主（LDH₁），对乳酸亲和力低、利于乳酸氧化供能；骨骼肌以 M₄（LDH₅）为主。"}],"note":"","opts":["A. M₄","B. M₃H","C. MH₃","D. H₄"],"printed_answer":"D"},{"id":"n0136","subj":"880","chap":"第十七章 核苷酸代谢","type":"选择","years":["21"],"q":"嘌呤核苷酸和嘧啶核苷酸合成都需要的物质是______。","points":[{"k":"答案","t":"C 天冬氨酸。嘌呤环的 N1 与嘧啶环的 N1、C4、C5、C6 均由天冬氨酸提供，故二者合成都需要它。"}],"note":"","opts":["A. 延胡索酸","B. 甘氨酸","C. 天冬氨酸","D. 谷氨酸"],"printed_answer":"C"},{"id":"n0137","subj":"880","chap":"第十六章 氨基酸代谢","type":"选择","years":["21"],"q":"尿素循环中尿素分子上的两个氨基，一个氨基来源于外周组织转运和肝脏代谢产生的氨，另一个氨基来源于______。","points":[{"k":"答案","t":"A 天冬氨酸。尿素的一个氨基来自氨，另一个由天冬氨酸经精氨酸琥珀酸合成酶提供。"}],"note":"","opts":["A. 天冬氨酸","B. 精氨酸","C. 瓜氨酸","D. 谷氨酰胺"],"printed_answer":"A"},{"id":"n0138","subj":"880","chap":"第五章 酶","type":"选择","years":["21"],"q":"不能用透析方法除去的抑制剂______。","points":[{"k":"答案","t":"A 二异丙基氟磷酸（DIFP）。它与丝氨酸蛋白酶活性中心 Ser 共价结合，属不可逆抑制，透析除不去；EDTA、丙二酸、亮氨酸均可逆。"}],"note":"","opts":["A. 丝氨酸蛋白酶抑制剂二异丙基氟磷酸（DIFP）","B. 金属酶抑制剂乙二胺四乙胺（EDTA）","C. 琥珀酸脱氢酶抑制剂丙二酸","D. 精氨酸酶抑制剂亮氨酸"],"printed_answer":"A"},{"id":"n0139","subj":"880","chap":"第四章 蛋白质","type":"选择","years":["21"],"q":"不是根据抗原抗体特异性，检测生物大分子的分析和制备方法______。","points":[{"k":"答案","t":"A 离子交换法。它按电荷差异分离；亲和层析、ELISA、免疫印迹均依赖抗原抗体特异性结合。"}],"note":"","opts":["A. 离子交换法","B. 亲和层析法","C. 酶联免疫吸附法","D. 免疫印迹法"],"printed_answer":"A"},{"id":"n0140","subj":"880","chap":"第十四章 氧化磷酸化","type":"考点","years":["21"],"q":"处于两条线粒体呼吸链的交汇点的物质是______。","points":[{"k":"答案","t":"辅酶 Q（CoQ，泛醌）。NADH 呼吸链与琥珀酸呼吸链都在复合体Ⅰ/Ⅱ之后汇入 CoQ，再经复合体Ⅲ、Ⅳ传至 O₂。"}],"note":"原卷无选项，按教材通行的“呼吸链交汇点”作答。","opts":[],"printed_answer":""},{"id":"n0149","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"简答","years":["19"],"q":"简述PCR技术原理","points":[{"k":"PCR基本原理","t":"PCR 是体外扩增特定 DNA 的技术：依据待扩增片段两端的核苷酸序列设计两个互补的寡核苷酸引物，在含模板、引物、过量 dNTP、耐热 Taq DNA 聚合酶的体系中循环反应，使模板 DNA 以几何级数扩增。"},{"k":"三温循环","t":"经高温变性（DNA 解链）、低温退火（引物与模板 DNA 结合）和适温延伸（DNA 合成）三个阶段构成一个循环周期。"},{"k":"引物定特异性","t":"两个引物分别与待扩片段两端互补，其序列决定扩增片段的专一性与两端边界。"},{"k":"补：保真度与退火","t":"Taq 酶耐热但无 3′→5′ 校对活性、保真度较低，可用高保真酶；退火温度过高使扩增效率降低，过低则出现非特异条带与引物二聚体。"},{"k":"补：指数扩增与平台","t":"每循环产物加倍，n 次循环理论为 2ⁿ 倍，30 次可达约 10⁹；扩增后期因引物与酶耗尽、dNTP 不足及产物抑制而进入平台期。"}],"note":"口径：依据《真题分类》资料原文（资料该条标题含「及应用」，本题只问原理，故只取原理部分）。保真度与退火、指数扩增与平台两点为教材口径补充（k 前标「补」）。","opts":[],"printed_answer":"","ref":true},{"id":"n0150","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"简答","years":["19"],"q":"给了一条已知的双链DNA(标有5′、3′方向)题干说转录方向是从右向左，问哪条链作为模板来转录，给出各个氨基酸的密码子，问编码出的氨基酸序列，给反密码子，问对应哪个氨基酸","points":[{"k":"模板链判定","t":"转录方向从右向左，RNA 聚合酶沿模板链 3'→5' 移动；在图上沿从右到左方向读、极性为 3'→5' 的那条链即模板链，另一条为编码链。"},{"k":"写mRNA","t":"以模板链为准按 A-U、T-A、G-C、C-G 互补，写出 5'→3' 的 mRNA；mRNA 的 5' 端对应模板链的 3' 端（即图的最右端）。"},{"k":"读密码子","t":"从 mRNA 5' 端起，找到起始密码子 AUG，按 5'→3' 每 3 个碱基一组连续阅读，遇 UAA/UAG/UGA 终止。"},{"k":"查表定氨基酸","t":"用标准遗传密码表查每组密码子对应的氨基酸，AUG 编码甲硫氨酸（原核为甲酰甲硫氨酸），写出从 N 端到 C 端的肽链。"},{"k":"反密码子","t":"反密码子与密码子反向平行互补：密码子 5'-AUG-3' 对应反密码子 3'-UAC-5'，按 5'→3' 书写为 CAU；据此定该 tRNA 携带的氨基酸。"},{"k":"易错点","t":"勿把编码链直接翻译；注意标清 5'/3' 端，方向颠倒会使序列完全错误；终止密码子不编码氨基酸，不计入肽链。"}],"note":"原卷 DNA 序列与密码子表缺失，此处给判定规则与解题步骤，考场代入具体序列即可。","opts":[],"printed_answer":""},{"id":"n0151","subj":"880","chap":"第六章 维生素与辅酶","type":"计算","years":["19"],"q":"给了一个可逆反应式乙醛-乙醇，乙醇脱氢酶，涉及到NADH的转变，米氏方程计算题，问怎样确定反应的进行，问怎样确定哪个是该酶的最适反应底物","points":[{"k":"列式","t":"反应：乙醛 + NADH + H⁺ ⇌（乙醇脱氢酶 ADH）乙醇 + NAD⁺；动力学用 v=Vmax[S]/(Km+[S])，双倒数 1/v=(Km/Vmax)(1/[S])+1/Vmax。"},{"k":"代入","t":"340 nm 连续监测 NADH 的减少（正反应）或增加（逆反应），取线性段 ΔA/min 算初速度；以 1/[S] 对 1/v 回归，截距 b=1/Vmax、斜率 m=Km/Vmax，故 Vmax=1/b、Km=m/b。"},{"k":"结论","t":"代入米氏方程即可求任意底物浓度下的反应速度；比较不同底物的 kcat/Km=Vmax/([E]t·Km)，最大者为最适底物。"},{"k":"判断反应方向","t":"热力学看 ΔG=ΔG°'+RTlnQ，ΔG<0 正向进行；实验上以 340 nm 吸光度随时间的变化方向判断净反应方向，ΔA 下降为正反应（NADH 消耗），上升为逆反应。"},{"k":"确定最适底物","t":"固定酶量，分别测各候选底物的 Km 与 Vmax，计算 kcat/Km（催化效率），最大者即最适底物；也可比较相同 [S] 下的 v。"},{"k":"实验要点","t":"底物浓度须远大于酶浓度、pH 与温度固定、设不加酶空白；产物积累会逆反应，应取初速度（转化率<10%）。"}],"note":"原卷数值缺失，此处给公式与判据；若给出具体 Km、Vmax 与 [S]，直接代入 v=Vmax[S]/(Km+[S]) 即得速度。","opts":[],"printed_answer":""},{"id":"n0152","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["19"],"q":"简述酶分子结构","points":[{"k":"化学组成","t":"单纯酶仅由蛋白质构成；结合酶=酶蛋白+辅助因子（辅酶、辅基或金属离子），两者结合成全酶才有催化活性。"},{"k":"一级结构","t":"氨基酸的排列顺序决定折叠方式与活性中心；一级结构改变可致酶活性丧失（如镰状细胞贫血的血红蛋白突变类比）。"},{"k":"二级结构","t":"α 螺旋、β 折叠、β 转角与无规卷曲，由主链 —CO 与 —NH 间的氢键维持，是局部空间构象。"},{"k":"三级结构","t":"单条肽链折叠成紧密球状，形成疏水内核与亲水表面；由二硫键、疏水作用、氢键、离子键、范德华力维持。"},{"k":"四级结构","t":"两条以上亚基通过非共价键聚合（如 LDH 四聚体、血红蛋白 α₂β₂），亚基间可产生别构调节，是寡聚酶的特征。"},{"k":"活性中心","t":"由少数必需基团在空间上靠近形成，分结合部位（固定底物）与催化部位（催化反应）；其余基团为结构基团，维持构象。"},{"k":"结构域","t":"分子量较大的酶常含 2 个以上相对独立的结构域（如免疫球蛋白样折叠），结构域间相对运动参与催化与调节。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0153","subj":"880","chap":"第三章 氨基酸","type":"简答","years":["19"],"q":"给出一个八肽，给出氨基酸，但是顺序不确定，分别用胰蛋白酶、胰凝乳蛋白酶、BrCN等水解得到各个肽段，问确定氨基酸排列顺序","points":[{"k":"重叠法策略","t":"先用一种专一试剂把八肽切成若干片段并测定片段内顺序，再用另一种试剂切出含重叠区的片段，通过重叠序列拼出完整顺序。"},{"k":"断裂专一性","t":"胰蛋白酶切 Lys/Arg 的羧基侧；胰凝乳蛋白酶切 Phe/Tyr/Trp 的羧基侧；溴化氰（BrCN）切 Met 的羧基侧，Met 处生成高丝氨酸内酯。"},{"k":"片段测序","t":"各片段用 Edman 降解法从 N 端逐轮释放并鉴定 PTH-氨基酸，得到每个片段内部的排列顺序。"},{"k":"末端测定","t":"用丹磺酰氯（DNS-Cl）或 DNFB 法测 N 端，用羧肽酶 A/B 测 C 端，先确定八肽的两端残基，减少拼接歧义。"},{"k":"重叠拼接","t":"比较两组片段的重叠序列，把短片段首尾相连，唯一确定全序列；若仍有多种可能，用第三种试剂（如嗜热菌蛋白酶、胃蛋白酶）断裂验证。"},{"k":"结果验证","t":"按推定序列预测各试剂应产生的片段，与实际电泳/层析结果比对；必要时用质谱串联测序（MS/MS）确认。"}],"note":"原卷八肽与各酶解片段数据缺失，此处给标准测序流程；考场按给定片段按“重叠区唯一”原则拼接。","opts":[],"printed_answer":""},{"id":"n0154","subj":"880","chap":"第三章 氨基酸","type":"简答","years":["19"],"q":"给了五个氨基酸分子式，问哪个是碱性氨基酸、分支氨基酸、哪个有吸光值、哪个在PH=5时显酸性、哪个能形成二硫键","points":[{"k":"碱性判定","t":"分子式中含 2 个以上氮原子、侧链带氨基/胍基/咪唑基者为碱性氨基酸：赖氨酸 C₆H₁₄N₂O₂、精氨酸 C₆H₁₄N₄O₂、组氨酸 C₆H₉N₃O₂。"},{"k":"分支判定","t":"侧链含分支甲基者为支链氨基酸：缬氨酸、亮氨酸、异亮氨酸（BCAA），三者在肝外（肌肉）氧化。"},{"k":"紫外吸收","t":"含苯环者在 280 nm 有吸收：苯丙氨酸、酪氨酸、色氨酸；色氨酸与酪氨酸吸收强，苯丙氨酸弱。"},{"k":"pH5显酸性","t":"pI<5 者在 pH 5 时净带负电：天冬氨酸（pI≈2.8）、谷氨酸（pI≈3.2），因 —COO⁻ 多于 —NH₃⁺，电泳向正极。"},{"k":"二硫键","t":"含巯基（—SH）的半胱氨酸可氧化形成胱氨酸（—S—S—）；甲硫氨酸含硫但为硫醚，不形成二硫键。"},{"k":"判定技巧","t":"数氮原子定碱性、看支链定 BCAA、看苯环定紫外吸收、比 pI 与 pH 定电荷、找 —SH 定二硫键。"}],"note":"原卷五个分子式缺失，此处给各类的判定标准与代表氨基酸，考场对号入座。","opts":[],"printed_answer":""},{"id":"n0155","subj":"880","chap":"第十五章 脂类代谢","type":"计算","years":["19"],"q":"计算软脂酸彻底氧化分解生成多少能量","points":[{"k":"列式","t":"软脂酸（16C）活化耗 2 ATP；β 氧化次数=16/2−1=7；每次产 1 FADH₂+1 NADH+1 乙酰 CoA，共 8 个乙酰 CoA 进入三羧酸循环。"},{"k":"代入","t":"7×(1.5+2.5)=28 ATP；8×10=80 ATP；小计 108 ATP；减去活化消耗 2 ATP。"},{"k":"结论","t":"净生成 106 mol ATP/mol 软脂酸；若按旧 P/O 值（NADH=3、FADH₂=2）计为 129 ATP；若把活化 ATP→AMP+PPi 视为耗 2 个高能键，仍为 106。"}],"note":"两种口径均常见：新 P/O 值得 106，老教材得 129，答题时注明所用 P/O 值；若题目给 129 则以卷面为准。","opts":[],"printed_answer":""},{"id":"n0156","subj":"880","chap":"第四章 蛋白质","type":"论述","years":["19"],"q":"说明蛋白质的二级结构并简述特点","points":[{"k":"二级结构定义","t":"多肽链主链局部的空间盘曲折叠，不涉及侧链构象与不同肽段间的空间关系；主要由主链 —CO 与 —NH 之间的氢键维持。"},{"k":"α螺旋","t":"右手螺旋，每圈 3.6 个残基、螺距 0.54 nm、每个残基上升 0.15 nm；第 n 个残基的 C=O 与 n+4 残基的 N-H 形成氢键，侧链伸向螺旋外侧。"},{"k":"β折叠","t":"肽链伸展成锯齿状，相邻肽段平行（同向）或反平行（反向）排列，链间形成氢键；反平行更稳定，侧链交替伸向片层两侧。"},{"k":"β转角","t":"由 4 个残基构成 180° 回折，甘氨酸与脯氨酸常见，连接两条 β 链，使球状蛋白结构紧凑。"},{"k":"无规卷曲","t":"无确定周期性规律，但仍是确定的空间构象，常构成活性中心、结构域连接区与表面环。"},{"k":"影响因素","t":"侧链大小与电荷、脯氨酸（破坏螺旋）、甘氨酸（增加柔性）、盐键与二硫键均影响二级结构；可用 Chou-Fasman 法预测。"},{"k":"超二级结构","t":"αα、ββ、βαβ 等组合成超二级结构与结构域，是三级结构的构件；二级结构是蛋白折叠与功能的基础。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0157","subj":"880","chap":"第十七章 核苷酸代谢","type":"填空","years":["11"],"q":"痛风是由于（　　　　　）代谢紊乱造成的","points":[{"k":"答案","t":"嘌呤。尿酸是嘌呤核苷酸的终产物，生成过多或排泄减少使尿酸盐结晶沉积于关节，即为痛风。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0158","subj":"880","chap":"第一章 糖类","type":"填空","years":["11"],"q":"常见的鞘糖脂包括（　　　　　）和（　　　　　）","points":[{"k":"答案","t":"脑苷脂（脑糖脂）和神经节苷脂。二者均由神经酰胺与糖基相连，后者另含唾液酸。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0159","subj":"880","chap":"第十六章 氨基酸代谢","type":"填空","years":["11"],"q":"肝炎患者一般检测（　　　　　）","points":[{"k":"答案","t":"丙氨酸氨基转移酶（ALT），辅以天冬氨酸氨基转移酶（AST）和胆红素。肝细胞受损时 ALT 释放入血，是肝炎最敏感的指标。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0160","subj":"880","chap":"第四章 蛋白质","type":"填空","years":["11"],"q":"蛋白质常见的二级结构是","points":[{"k":"答案","t":"α-螺旋、β-折叠、β-转角和无规卷曲。前两者由主链羰基氧与亚氨基氢形成氢键维持。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0161","subj":"880","chap":"第十一章 柠檬酸循环","type":"填空","years":["11"],"q":"代谢中三个重要的中间代谢产物是","points":[{"k":"答案","t":"乙酰 CoA、丙酮酸和 α-酮戊二酸。三者分别连接糖、脂与氨基酸代谢，是物质互变的枢纽。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0162","subj":"880","chap":"第七章 核酸","type":"填空","years":["11"],"q":"cech 和 altman 发现了（　　　　　）获得诺贝尔奖","points":[{"k":"答案","t":"核酶（ribozyme，催化性 RNA）。Cech 发现四膜虫 rRNA 前体自我剪接，Altman 证明 RNA 具催化活性，二人共获 1989 年诺贝尔化学奖。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0163","subj":"880","chap":"第四章 蛋白质","type":"填空","years":["11"],"q":"蛋白质通过加______用来酸碱滴定","points":[{"k":"答案","t":"甲醛。甲醛与氨基加成消除其碱性并释放 H⁺，使氨基氮可用 NaOH 滴定，即甲醛滴定法。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0166","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["11"],"q":"请结合血红蛋白，分析蛋白质的四级结构的意义，比较血红蛋白与肌红蛋白结构和功能的差异，解释CO中毒的机理，解救办法是什么 12分","points":[{"k":"四级结构意义","t":"血红蛋白（Hb）由 2 个 α 与 2 个 β 亚基组成四聚体，亚基间以盐桥相连；一个亚基结合 O₂ 引起 T 态→R 态转变，其余亚基亲和力升高，产生正协同效应。"},{"k":"协同效应","t":"协同使氧解离曲线呈 S 形，Hill 系数约 2.8；在肺高氧分压处高效装载，在外周低氧分压处高效释放，运输效率远高于单链蛋白。"},{"k":"肌红蛋白对比","t":"肌红蛋白（Mb）为单链、含 1 个血红素，p50 约 2.8 mmHg，氧解离曲线为双曲线，只储氧；Hb 为四聚体、含 4 个血红素，p50 约 26 mmHg，负责运输。"},{"k":"波尔效应","t":"Hb 对 pH、CO₂ 与 2,3-BPG 敏感：组织酸性、CO₂ 升高使亲和力下降、促进释氧（波尔效应）；Mb 不受这些因素影响。"},{"k":"抢占血红素","t":"CO 与 Hb 亲和力约为 O₂ 的 210~250 倍，占据 Fe²⁺ 第六配位形成 CO-Hb，且解离极慢，可结合 O₂ 的血红素数目大幅减少。"},{"k":"构象锁定与双降","t":"CO 结合使 Hb 稳定在 R 态、氧解离曲线左移，剩余亚基结合的 O₂ 在外周难以释放；携氧量与释氧效率同时下降，造成组织缺氧。"},{"k":"抑制呼吸链","t":"CO 还抑制线粒体细胞色素 c 氧化酶（复合体Ⅳ），阻断电子传递与氧化磷酸化，加重细胞窒息；CO-Hb 呈樱桃红色，皮肤黏膜可呈樱红。"},{"k":"高压氧解救","t":"立即脱离现场、吸纯氧；高压氧（2~3 个大气压）提高血氧分压竞争性置换 CO、加速排出（半衰期由约 4 h 降至 20 min），并以物理溶解氧维持组织供氧；重症可换血、对症支持。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0167","subj":"880","chap":"第三章 氨基酸","type":"简答","years":[],"q":"有问某个密码子突变后产生什么氨基酸。","points":[{"k":"定码查表","t":"由 DNA 模板链按碱基互补推出 mRNA（或编码链直接把 T 换成 U），定位突变三联体；按 5'→3' 方向查标准密码表，即得新的氨基酸。"},{"k":"同义突变","t":"密码子第三位改变仍编码同一氨基酸（简并性），如 UCU→UCC 仍为丝氨酸，蛋白质序列不变。"},{"k":"错义突变","t":"编码不同的氨基酸，可改变蛋白功能；如 HbS 的 GAG→GUG，谷氨酸变为缬氨酸。"},{"k":"无义突变","t":"密码子变为终止密码子（UAA、UAG、UGA），肽链提前终止，多导致蛋白功能丧失。"},{"k":"移码突变","t":"插入或缺失非 3 倍数个碱基，阅读框改变，下游氨基酸全部改变，后果通常最严重。"},{"k":"起始终止改变","t":"起始密码子 AUG 突变可致翻译不能起始；终止密码子突变为有义密码子则通读，肽链延长。"}],"note":"原卷具体密码子缺失，此处给判定步骤与各类突变后果。","opts":[],"printed_answer":""},{"id":"n0168","subj":"880","chap":"第五章 酶","type":"计算","years":[],"q":"考察的是酶相关知识。给出琥珀酸脱氢酶的Km、Vmax让画双倒数曲线，求酶促反应的速度，问FADH₂的全称，让画丙二酸的双倒数曲线。","points":[{"k":"双倒数方程","t":"将米氏方程两侧取倒数得 1/v₀ =（Km/Vmax）·（1/[S]）＋1/Vmax，即一次函数 y＝kx＋b。"},{"k":"作图与截距","t":"以 1/v₀ 为纵坐标、1/[S] 为横坐标作图得直线，纵截距为 1/Vmax、横截距为 −1/Km、斜率为 Km/Vmax；一组数据可求 Km 与 Vmax，多组数据可看出 Km、Vmax 随抑制剂浓度的变化规律。"},{"k":"求反应速度","t":"可直接代入 v＝Vmax[S]/(Km＋[S]) 求得，也可由 1/[S] 在图上读出 1/v₀ 再取倒数；测酶活须在最适温度（25℃）、最适 pH 与足够大的底物浓度（约为 Km 的 5 倍）下测初速度，初速度取底物变化在起始浓度 5% 以内的速率。"},{"k":"FADH₂全称","t":"还原型黄素腺嘌呤二核苷酸，是琥珀酸脱氢酶的辅基（该酶即呼吸链复合体Ⅱ，催化琥珀酸脱氢生成延胡索酸）。"},{"k":"丙二酸抑制曲线","t":"丙二酸是琥珀酸脱氢酶的竞争性抑制剂：v-[S] 图中 Vmax 不变、Km 变大（K′m）；双倒数图中直线变陡、纵截距 1/Vmax 不变，横截距由 −1/Km 变为 −1/[Km(1＋[I]/Ki)]。"}],"note":"口径：依据《真题分类》资料原文（双倒数作图、酶活测定、FADH₂ 全称、丙二酸曲线四项）；原文另列多种酶活测定方法，与本题问法无关，未列入。","opts":[],"printed_answer":"","ref":true},{"id":"n0174","subj":"880","chap":"第六章 维生素与辅酶","type":"填空","years":["12"],"q":"写出英文的中文名字（20个，共10分）\nPEP　　　　5-HT\nLDL　　　　ALP\nSRP　　　　NAD\nHIV　　　　HBV\nTPP　　　　PLP\nG33G (GSSG?)　　IgG\nSDS　　　　PCR\nELISA　　　PAGE\nNMRI　　　HPLC\nCamp　　　FAD\nNAD","points":[{"k":"答案","t":"PEP 磷酸烯醇式丙酮酸；5-HT 5-羟色胺；LDL 低密度脂蛋白；ALP 碱性磷酸酶；SRP 信号识别颗粒；NAD 烟酰胺腺嘌呤二核苷酸；HIV 人类免疫缺陷病毒；HBV 乙型肝炎病毒；TPP 焦磷酸硫胺素；PLP 磷酸吡哆醛；GSSG 氧化型谷胱甘肽；IgG 免疫球蛋白 G；SDS 十二烷基硫酸钠；PCR 聚合酶链式反应；ELISA 酶联免疫吸附测定；PAGE 聚丙烯酰胺凝胶电泳；NMRI 核磁共振成像；HPLC 高效液相色谱；cAMP 环腺苷酸；FAD 黄素腺嘌呤二核苷酸；NADP 烟酰胺腺嘌呤二核苷酸磷酸。"}],"note":"原卷缩略语个别字迹不清（G33G 应为 GSSG，Camp 应为 cAMP），按通行写法给出。","opts":[],"printed_answer":""},{"id":"n0175","subj":"880","chap":"综合","type":"考点","years":["12"],"q":"2011年诺贝尔医学奖获得者是谁","points":[{"k":"答案","t":"Beutler、Hoffmann 与 Steinman。Steinman 发现树突状细胞，Beutler 与 Hoffmann 揭示先天免疫的 Toll 样受体激活机制。"}],"note":"原卷无选项，按史实作答。","opts":[],"printed_answer":""},{"id":"n0176","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":["20"],"q":"核糖开关（英文）","points":[{"k":"定义","t":"mRNA 5′ 非翻译区中能直接结合小分子代谢物、并因此改变自身构象以调控下游基因表达的 RNA 元件（riboswitch）。"},{"k":"适体加表达平台","t":"由适体（aptamer）与表达平台组成，配体结合后构象重排，形成或破坏终止子/抗终止子、或遮蔽 SD 序列，在转录或翻译水平开关基因。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0179","subj":"631","chap":"综合","type":"名词解释","years":["20"],"q":"切口平移","points":[{"k":"定义","t":"利用 DNA 聚合酶Ⅰ的 5′→3′ 外切酶活性与聚合活性，从双链 DNA 的单链切口处边切边补、使切口沿链移动的反应。"},{"k":"标记掺入制探针","t":"切口 5′ 端被外切酶水解，聚合酶在 3′ 端延伸；体系中加标记 dNTP 即可把标记掺入 DNA，常用于制备放射性或荧光探针。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0180","subj":"631","chap":"一、染色体结构","type":"名词解释","years":["20"],"q":"基因家族（英文）","points":[{"k":"定义","t":"真核基因组中由同一祖先基因经重复和变异而来、序列高度同源、编码产物结构与功能相似的一组基因（gene family）。"},{"k":"重复致分化假基因","t":"成员常成簇排列（组蛋白、rRNA、珠蛋白基因家族），重复拷贝累积突变可分化为新功能基因或成为假基因。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0181","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"名词解释","years":["20"],"q":"表观遗传学","points":[{"k":"定义","t":"研究 DNA 序列不变而基因表达发生可遗传改变的学科，主要涉及 DNA 甲基化、组蛋白修饰、染色质重塑和非编码 RNA。"},{"k":"修饰改变染色质活性","t":"CpG 岛甲基化抑制转录，组蛋白乙酰化激活、甲基化因位点而异；参与细胞分化、X 染色体失活、基因组印记与肿瘤发生。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0182","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["20"],"q":"真核和原核基因组特点","points":[{"k":"大小形态","t":"原核基因组小（0.6~10 Mb），多为单拷贝环状 DNA，无核膜，形成类核；真核基因组大（人约 3 000 Mb），为多条线状染色体，与组蛋白结合成染色质。"},{"k":"基因结构","t":"原核基因无内含子（少数例外）、基因间区短、常组成操纵子共转录；真核基因多含内含子与外显子，单顺反子转录，初级转录物需剪接。"},{"k":"重复序列","t":"原核几乎无重复序列（除 IS 与 rRNA 基因）；真核含大量重复序列：卫星 DNA、微卫星、LINE/SINE（Alu）、rRNA 基因串联重复。"},{"k":"非编码比例","t":"原核非编码区占比小、基因密度高；真核基因间区与内含子占绝大部分，人类编码序列不足基因组 2%。"},{"k":"包装与元件","t":"真核经核小体—染色质—染色体多级包装，有着丝粒与端粒；原核靠超螺旋与类核蛋白包装，并常有质粒、噬菌体与转座子。"},{"k":"遗传特征","t":"原核基因水平转移普遍、共转录共翻译；真核有基因家族、假基因、可变剪接、表观遗传，以及线粒体与叶绿体的独立环状基因组。"}],"note":"与 n0115 为同一考点，2020 年重复命题；两处表述互补，可合并背诵。","opts":[],"printed_answer":""},{"id":"n0183","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["20"],"q":"举2个例子说明单链RNA茎环结构的重要性","points":[{"k":"茎环结构","t":"单链 RNA 局部自身回折，互补区形成双链茎（A-U、G-C），非互补区膨出成环，是 RNA 二级结构的基本单元，也是蛋白识别与催化的结构基础。"},{"k":"tRNA三叶草","t":"tRNA 的 D 环、反密码子环、TψC 环均为茎环结构，共同折叠成倒 L 形，使其能同时接触 mRNA 密码子与核糖体肽酰转移中心。"},{"k":"核酶催化","t":"23S/28S rRNA 的多个茎环围成肽酰转移酶中心，催化肽键形成；Ⅰ/Ⅱ类内含子靠 P1~P10 茎环结构自剪接，锤头核酶靠茎环Ⅰ/Ⅱ/Ⅲ 定位切割位点。"},{"k":"转录终止","t":"大肠杆菌不依赖 ρ 的终止子含 GC 富集回文序列，转录出的 RNA 形成发夹（茎环）加 3' 端 poly(U)，使 RNA 聚合酶暂停并脱落。"},{"k":"RNA干扰","t":"pri-miRNA 与 shRNA 的茎环被 Drosha、Dicer 识别并加工成小 RNA，茎环结构本身就是加工与识别的信号。"},{"k":"病毒翻译","t":"部分病毒 5' 非翻译区的复杂茎环（如 HCV 的 IRES）可直接招募核糖体，实现不依赖 5' 帽的翻译起始。"}],"note":"题干只要 2 例，答案给 4 例备用；考试选 tRNA 与转录终止最稳妥。","opts":[],"printed_answer":""},{"id":"n0184","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["20"],"q":"什么是感受态细胞，说出两种制备的方法，及其原理","points":[{"k":"感受态定义","t":"细菌处于易于接受外源 DNA 的生理状态，细胞表面通透性增高、可摄取质粒或噬菌体 DNA，经复制与表达使表型改变，称转化。"},{"k":"氯化钙法","t":"取对数期大肠杆菌，0~4℃ 用 0.1 mol/L CaCl₂ 低渗处理，使细胞膨胀、膜通透性改变；加 DNA 后 42℃ 热激 90 s，再冰浴复苏。"},{"k":"钙离子原理","t":"Ca²⁺ 中和 DNA 磷酸骨架与细胞表面的负电荷，形成羟基磷酸钙-DNA 复合物，促进 DNA 吸附并穿过细胞壁与膜；低温维持膜的低流动性、减少损伤。"},{"k":"电穿孔法","t":"细菌用 10% 甘油洗去培养基盐分，加 DNA 后在 1.5~2.5 kV/cm、数毫秒的高压脉冲下穿孔，DNA 进入，随即加培养基复苏 1 h。"},{"k":"电穿孔原理","t":"瞬时高压使膜脂双层形成可逆的水通道（孔），DNA 沿电场方向迁移进入细胞；脉冲极短，孔随后自行闭合，细胞得以存活。"},{"k":"其他与效率","t":"另有 TSS 法（PEG、Mg²⁺、DMSO）、RbCl 法、原生质体转化与农杆菌介导；转化效率约 10⁶~10⁹ cfu/μg DNA，操作需全程低温、DNA 纯度高、避免反复冻融，转化后先复苏表达抗性再涂板。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0185","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["20"],"q":"真核基因表达的特点","points":[{"k":"转录翻译分区","t":"转录在细胞核内完成，翻译在细胞质核糖体上进行，两步在时间和空间上分开，不存在偶联。"},{"k":"断裂基因结构","t":"编码区被内含子隔断，呈外显子-内含子镶嵌排列，需经剪接去除内含子才能形成连续读框。"},{"k":"初级转录本加工","t":"hnRNA 必须经 5′加帽、3′加 poly(A) 尾、剪接及碱基编辑，才成为成熟 mRNA 出核。"},{"k":"单顺反子为主","t":"一条 mRNA 一般只编码一种多肽，转录单位与蛋白质一一对应，故表达调控更精细。"},{"k":"多级分层调控","t":"染色质重塑、转录起始、加工与转运、翻译效率、翻译后修饰均可调控，其中转录起始最关键。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0186","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["20"],"q":"什么是蛋白质组学，研究对象、目的、方法和瓶颈是什么","points":[{"k":"整体蛋白质组","t":"蛋白质组（proteome）指一个细胞、组织或机体在特定时空表达的全部蛋白质；蛋白质组学即大规模研究其组成、结构、修饰与功能。"},{"k":"研究对象","t":"全部蛋白及其表达水平、翻译后修饰、相互作用、亚细胞定位与动态变化。"},{"k":"研究目的","t":"绘制表达谱与功能网络，寻找疾病标志物与药物靶点，把基因序列信息落到表型与功能上。"},{"k":"核心方法","t":"以双向电泳或液相色谱分离、质谱鉴定为主，辅以酵母双杂交、噬菌体展示、蛋白芯片与生物信息学。"},{"k":"主要瓶颈","t":"低丰度蛋白难检出、疏水膜蛋白难溶解、动态范围达 10⁷、修饰高度不均一，且蛋白不能像核酸那样 PCR 扩增。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0187","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"论述","years":["20"],"q":"PCR的原理、过程和应用","points":[{"k":"模拟半保留复制","t":"以单链 DNA 为模板，引物提供 3′-OH，耐热 DNA 聚合酶按碱基互补规则沿 5′→3′ 合成子链。"},{"k":"三步热循环","t":"变性 94 ℃ 使双链解开；退火 55~60 ℃ 引物与模板特异结合；延伸 72 ℃ Taq 酶延伸，每轮完成一次复制。"},{"k":"指数扩增","t":"n 轮循环后目的片段约扩增 2ⁿ 倍，30 轮可达 10⁹ 倍，故极微量模板也能检出。"},{"k":"关键组分","t":"模板、一对特异引物、四种 dNTP、Mg²⁺、缓冲体系、耐热 Taq DNA 聚合酶与热循环仪。"},{"k":"主要应用","t":"基因克隆与定点突变、病原体检测、法医与亲权鉴定、实时定量 PCR、测序建库与文库构建。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0188","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"论述","years":["20"],"q":"如何检测一段基因序列是否具有启动子活性，简述三种方法，和其中一种的原理步骤","points":[{"k":"报告基因法","t":"把候选序列接在荧光素酶、LacZ 或 GFP 基因上游，转染细胞后测报告分子活性，活性显著升高即具启动子功能。"},{"k":"系列缺失分析","t":"对 5′端做梯度缺失后接报告基因，比较各缺失体活性，可定位核心启动子区与关键调控元件。"},{"k":"体外转录法","t":"在核提取物中加入该序列模板与核苷酸，检测特异转录本，直接反映启动子被转录机器识别的能力。"},{"k":"凝胶阻滞实验","t":"以含启动子序列的标记探针与核蛋白结合后电泳，出现滞后带说明有转录因子特异结合；加抗体可做超迁移。"},{"k":"报告基因步骤","t":"①构建启动子-荧光素酶质粒并设空载体对照；②转染细胞培养 24~48 h；③裂解后加荧光素底物测发光值；④用海肾荧光素酶或蛋白量校正，比较相对活性。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0189","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"论述","years":["20"],"q":"什么是CRISPR? CRISPR/Cas9技术的原理? dCas9的特点?","points":[{"k":"细菌免疫记忆","t":"CRISPR 即成簇规律间隔短回文重复，细菌把噬菌体片段作为间隔序列存入基因座，转录为 crRNA 记忆入侵者。"},{"k":"sgRNA 引导识别","t":"Cas9 与 sgRNA 结合，sgRNA 的 20 nt 与靶 DNA 互补配对，并在靶点旁要求 PAM（5′-NGG-3′）才能识别。"},{"k":"双链断裂","t":"HNH 结构域切互补链、RuvC 结构域切非互补链，在 PAM 上游约 3 bp 处产生平末端双链断裂。"},{"k":"修复决定结果","t":"NHEJ 修复易产生插入或缺失造成移码敲除；提供同源模板时 HDR 可精确替换或插入外源序列。"},{"k":"只结合不切割","t":"D10A 与 H840A 双突变使两个核酸酶活性中心失活，保留 sgRNA 引导的靶向结合能力而无切割活性。"},{"k":"dCas9 用途","t":"融合 KRAB 或 VP64 可行 CRISPRi/a 转录调控，融合碱基编辑器或荧光蛋白可行单碱基转换与基因组定位成像。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0190","subj":"631","chap":"七、分子生物学技术","type":"简答","years":[],"q":"Southern、Northern、Western 的操作流程和应用","points":[{"k":"共同技术路线","t":"三者均为「分离→转膜固定→标记探针杂交→显影」，区别在于靶分子与探针种类不同。"},{"k":"DNA 印迹法","t":"DNA 经限制酶消化、琼脂糖电泳、碱变性后转尼龙膜，用标记 DNA 探针杂交，检测特定基因片段。"},{"k":"RNA 印迹法","t":"RNA 经变性电泳后转膜，用 DNA 或 RNA 探针杂交，检测某基因 mRNA 的大小与表达量。"},{"k":"蛋白印迹法","t":"蛋白经 SDS-PAGE 后转 PVDF 膜，封闭后用特异一抗、酶标二抗杂交，显色或化学发光检测目的蛋白。"},{"k":"应用各有侧重","t":"Southern 查基因拷贝数、缺失与重排；Northern 查转录水平；Western 查蛋白表达量与修饰状态。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0191","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":[],"q":"克隆载体、表达载体的特点（应具备的基本特征）","points":[{"k":"克隆载体四要素","t":"①复制起点保证自主复制；②抗性筛选标记；③多克隆位点供外源片段插入；④分子小、拷贝数高、转化效率高。"},{"k":"克隆载体用途","t":"只用于目的 DNA 的保存、扩增与亚克隆，不要求外源基因表达，故不需启动子等表达元件。"},{"k":"表达载体加强启动子","t":"须带 lac、T7、trc 等强启动子及相应操纵基因，可由 IPTG 诱导，实现可控的高效转录。"},{"k":"翻译元件齐备","t":"启动子下游须有核糖体结合位点（SD 序列）、起始密码子，插入片段与 MCS 读框一致，并有终止密码子与转录终止子。"},{"k":"附加便利特征","t":"常带 His、GST 等纯化标签与蛋白酶切位点，并要求质粒稳定、拷贝数合适、筛选标记可靠。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0192","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":[],"q":"同时用葡萄糖和乳糖培养大肠杆菌有什么现象？机制是什么？","points":[{"k":"二次生长双峰","t":"同时供给葡萄糖与乳糖时，大肠杆菌先利用葡萄糖快速生长，出现短暂停滞，再利用乳糖生长，生长曲线呈双峰（diauxie）。"},{"k":"葡萄糖效应","t":"葡萄糖经磷酸转移酶系统（PTS）转运，使 EⅡA 保持去磷酸化，不能激活腺苷酸环化酶，胞内 cAMP 低。"},{"k":"CAP 无法结合","t":"cAMP 不足则不能形成 cAMP-CRP 复合物，lac 启动子上游的正调控位点空置，转录效率极低。"},{"k":"诱导排斥","t":"葡萄糖存在时 lac 透性酶活性低、诱导物进入少，即使有乳糖也难以充分去阻遏，操纵子只低水平表达。"},{"k":"葡萄糖耗尽后","t":"cAMP 升高形成 cAMP-CRP 并结合启动子上游，同时别乳糖解除 LacI 阻遏，lac 基因大量表达，进入第二生长峰。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0193","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":[],"q":"说明基因测序（双脱氧链终止法）的原理；给两个测序的图谱，写出 DNA 序列","points":[{"k":"双脱氧终止","t":"ddNTP 的 2′、3′位均无羟基，掺入后不能形成下一个磷酸二酯键，链延伸在该碱基处特异终止。"},{"k":"四管反应体系","t":"模板、引物、DNA 聚合酶与四种 dNTP，分四管各加一种 ddNTP，每管得到一组以该碱基结尾的长度不等片段。"},{"k":"电泳按长读序","t":"变性聚丙烯酰胺凝胶可分辨相差一个核苷酸的片段，片段越短迁移越快，自下而上逐带读即新合成链 5′→3′序列。"},{"k":"读图规则","t":"读出的是合成链序列，与模板链互补；求目的基因序列须取其互补链，并注意引物之后才是待测区起点。"}],"note":"原卷附带的两个测序图谱缺失，无法给出具体序列；作答按「自短到长、逐带读碱基、再取互补」的规则书写。","opts":[],"printed_answer":""},{"id":"n0194","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"翻译的准确性是如何保证的","points":[{"k":"合成酶双重校对","t":"氨酰-tRNA 合成酶先在活化位点选正确氨基酸，再由编辑位点水解误配产物，保证氨基酰-tRNA 的专一性。"},{"k":"密码反密码配对","t":"摆动位点之外的两对碱基严格互补，配对形成的几何形状被 30S 亚基解码中心识别。"},{"k":"A 位点筛选","t":"16S rRNA 解码中心监测密码子-反密码子小沟，只有正确配对才诱导构象改变，错误 tRNA 被排斥。"},{"k":"动力学校对","t":"EF-Tu 的 GTP 水解与 tRNA 接纳存在时间差，错误配对解离速度快于成肽速度，被动力学剔除。"},{"k":"延伸后校对","t":"肽键形成后核糖体构象改变，错配 tRNA 更易解离；终止密码子只被释放因子识别，保证终止准确。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0195","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"论述","years":[],"q":"CRISPR-Cas9 对于现代合成分子生物学的机遇与挑战","points":[{"k":"精准编辑平台","t":"可在任意基因组位点定点切割，配合同源重组实现敲除、敲入与点突变，大幅缩短育种、建模与元件构建周期。"},{"k":"调控与线路拓展","t":"dCas9 融合调控域或荧光蛋白，可构建基因开关、代谢流量重编程与活细胞基因组定位，是合成生物学核心模块。"},{"k":"疾病治疗潜力","t":"已用于镰状细胞病、β 地中海贫血的体外造血干细胞编辑，并在 CAR-T、抗病毒与遗传病方向推进。"},{"k":"脱靶与安全风险","t":"PAM 附近错配可致脱靶切割，引起易位与致癌风险；需高保真 Cas9、双切口酶策略及全基因组脱靶检测。"},{"k":"递送与免疫障碍","t":"体内递送效率低（AAV 载量有限、脂质纳米颗粒靶向性差），Cas9 细菌来源可引发免疫反应，重复给药受限。"},{"k":"伦理与监管","t":"生殖系编辑涉及不可逆的遗传改变与代际影响，须禁止临床应用，并完善法规、标准与公众伦理讨论。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0196","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"论述","years":[],"q":"RNA 病毒为什么传染性强？说明原因，现在研究的冠状病毒疫苗的类型有哪些？","points":[{"k":"聚合酶无校对","t":"RNA 依赖的 RNA 聚合酶缺乏 3′→5′外切校对，错配率约 10⁻⁴，易形成准种（quasispecies）与免疫逃逸株。"},{"k":"基因组小而多变","t":"基因组容量有限，复制快、世代短，高突变率叠加基因重组，使抗原不断漂移，疫苗与抗体易失效。"},{"k":"直接翻译省步骤","t":"正链 RNA 病毒基因组本身可作 mRNA 直接翻译，感染早期即可大量产毒，潜伏期短。"},{"k":"传播途径有利","t":"多有囊膜，可经飞沫、气溶胶与黏膜传播，上呼吸道排毒量大，基本传染数高。"},{"k":"传统疫苗类型","t":"灭活疫苗安全性好但免疫原性弱、需佐剂加强；减毒活疫苗免疫持久但存在毒力回复风险。"},{"k":"新型疫苗平台","t":"mRNA-脂质纳米颗粒疫苗、腺病毒载体疫苗、重组 S 蛋白亚单位疫苗与病毒样颗粒疫苗，可快速设计并诱导中和抗体与 T 细胞应答。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0197","subj":"880","chap":"第十五章 脂类代谢","type":"填空","years":[],"q":"在脂肪酸的分解代谢种长链脂酰辅酶 A 以（　　）形式运转到线粒体内，经过（　　）生成（　　）参加三羧酸循环","points":[{"k":"答案","t":"脂酰肉碱；β-氧化；乙酰 CoA。长链脂酰 CoA 不能直接过内膜，先转为脂酰肉碱经移位酶运入，再经 β-氧化 生成乙酰 CoA 进入 TCA。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0198","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"什么是抗原决定簇？单链抗体又是指什么？","points":[{"k":"抗原决定簇","t":"抗原物质上能够刺激淋巴细胞产生应答、并与其产物特异反应的化学基团，也称表位。"},{"k":"决定簇特点","t":"大多存在于抗原物质表面，一个天然抗原可有多种和多个决定簇，一般抗原分子越大决定簇数目越多。"},{"k":"单链抗体构建","t":"用基因工程技术在大肠杆菌中表达的人工抗体，由抗体重链可变区与轻链可变区通过 15~20 个氨基酸的短肽连接而成。"},{"k":"单链抗体特点","t":"能较好保留对抗原的亲和活性，分子量小、穿透力强、抗原性弱；因只有完整抗体的一条链，故称单链抗体。"}],"note":"口径：依据《真题分类》资料原文。原文只写“15~20 个氨基酸短肽”，未给 (Gly₄Ser)₃ 具体序列，故不写。","opts":[],"printed_answer":"","ref":true},{"id":"n0199","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":[],"q":"为什么糖尿病人代谢过程中容易产生酮体？过量的酮体对机体有何危害？","points":[{"k":"糖贮存耗竭","t":"严重饥饿或未经治疗的糖尿病（胰岛素水平过低）时，体内糖的贮存被耗尽，肝外组织不能从血液中获得充分的葡萄糖。"},{"k":"脂肪动员加速","t":"为获取能量，肝中糖异生加速，脂肪细胞进行脂肪动员、加速脂肪酸氧化分解，产生大量乙酰 CoA，必要时还动员蛋白质分解供能。"},{"k":"草酰乙酸耗尽","t":"糖异生作用使草酰乙酸耗尽，而草酰乙酸是乙酰 CoA 进入 TCA 循环所必需的关键物质，乙酰 CoA 因而不能正常进入 TCA。"},{"k":"转向酮体生成","t":"乙酰 CoA 转向生成酮体（乙酰乙酸、丙酮、D-β-羟丁酸），血酮升高超过肝外组织利用能力时引起酮血、酮尿，以致酸中毒。"},{"k":"特殊气味诊断","t":"血中出现大量丙酮，易进入呼吸系统；丙酮有毒、具挥发性和特殊气味，可经气息嗅到，借此可对疾患作出诊断。"},{"k":"酮症与酸中毒","t":"尿酮显著增高为酮尿症、血酮显著增高为酮血症，统称酮症；乙酰乙酸与 D-β-羟丁酸使血液 pH 降低发生酸中毒，严重时昏迷甚至死亡。"}],"note":"口径：依据《真题分类》资料原文。资料首句括注三种酮体与「D-β-羟丁酸」写法照原文；危害按资料三条（气味、酮症、酸中毒）分列。","opts":[],"printed_answer":"","ref":true},{"id":"n0200","subj":"880","chap":"第五章 酶","type":"简答","years":[],"q":"生物化学过程的调控有哪几种形式？","points":[{"k":"酶量调节","t":"分子水平之一，起效较慢：通过诱导或抑制酶的合成（涉及基因表达调控）与调节酶的降解（如泛素化降解途径）改变酶量。"},{"k":"酶活性调节","t":"分子水平之二，起效较快：包括前馈/反馈调节、别构调节（别构剂结合调节亚基影响催化亚基）、抑制剂/激活剂调节、激活蛋白/抑制蛋白（如钙调蛋白）调节。"},{"k":"共价修饰调节","t":"可逆共价修饰中最重要的是酶的磷酸化与去磷酸化；不可逆共价修饰如酶原激活，可形成活性中心而激活酶。"},{"k":"细胞水平调控","t":"细胞结构把酶与代谢物分隔成多个区室，使不同代谢途径分开；膜运输控制底物与产物的流通以调节其浓度；膜结构还影响酶的物理状态与性质。"},{"k":"整体神经激素","t":"通过激素进行全身性调节，分快调节（磷酸化改变现存酶活性）与慢调节（改变基因表达、改变酶的数量）。"},{"k":"同工酶调节","t":"同工酶催化相同化学反应但功能不同、具组织特异性，在不同器官中起不同作用，从而实现器官间的协调调节。"}],"note":"口径：依据《真题分类》资料原文。按资料三个水平（分子、细胞、整体）重组为 6 点，分点顺序与资料一致，未删得分点。","opts":[],"printed_answer":"","ref":true},{"id":"n0201","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"简答","years":[],"q":"转录后加工是基因表达种的一个非常重要的步骤，试举出六种 RNA 水平上的加工方式","points":[{"k":"切割与修剪","t":"原核中 rRNA 基因与某些 tRNA 基因组成混合操纵子，转录成多顺反子后需经 RNaseⅢ切割成各自的 rRNA、tRNA 前体；tRNA 前体再经 RNase P、F、D 修剪除去 5′端和 3′端多余序列。"},{"k":"3′端加CCA","t":"有些 tRNA 前体 3′端不含-CCA，需由 tRNA 核苷酸转移酶添加，使所有成熟 tRNA 的 3′端均为-CCA。"},{"k":"碱基修饰","t":"如 mRNA 的内部甲基化，在前体加工中起一定的识别作用；tRNA、rRNA 还有甲基化、假尿苷化、二氢尿苷化等修饰。"},{"k":"5′端加帽","t":"真核 mRNA 特有的加工方式，有三种帽子类型，在剪接、运输尤其是翻译方面起重要调控作用，并具有抗外切核酸酶降解、维持 mRNA 稳定性的作用。"},{"k":"3′端加尾","t":"真核 mRNA 3′端由多聚腺苷酸聚合酶以 ATP 为原料加上 Poly(A) 尾，可提高 mRNA 稳定性、增强可翻译能力、调控其从细胞核到细胞质的运输。"},{"k":"剪接与RNA编辑","t":"选择性剪接含Ⅰ、Ⅱ类自我剪接、剪接体剪接与 tRNA 酶促剪接，是真核切除内含子、调控表达产物的方式；RNA 编辑通过插入、删除或取代核苷酸使 mRNA 序列不同于模板 DNA，从而改变 DNA 所编码的遗传信息。"}],"note":"口径：依据《真题分类》资料原文（原文共九条，此处取其中六类加工方式）；原文另有「再编码」，属翻译水平，未计入。","opts":[],"printed_answer":"","ref":true},{"id":"n0202","subj":"880","chap":"第五章 酶","type":"简答","years":[],"q":"简要说明可用于判断和确定酶活性中心的一些主要方法","points":[{"k":"专一性研究","t":"研究酶的专一性底物的结构特点以判断活性中心结构；研究竞争性抑制剂的必需结构也有助于了解活性中心。"},{"k":"酶切除法","t":"链球菌核酸酶从 N 端切去 6 个氨基酸残基、牛胰核糖核酸酶从 N 端切去 12 个，均不影响酶活力，表明这些部位与活性中心无关。"},{"k":"化学修饰法","t":"非特异共价修饰用专一性氨基酸试剂标记侧链后测活力变化，判断该侧链是否属活性中心；特异共价修饰用只作用于活性部位某一残基的试剂使酶失活，水解分离带标签肽段即可定位。"},{"k":"亲和标记","t":"与底物结构相似的修饰剂可专一引入活性部位，与某一基团共价结合而将其标记，水解分离后进行分析。"},{"k":"动力学参数","t":"活性部位氨基酸残基的解离状态与酶活性直接相关，由动力学方法求得参数即可判断活性部位的化学性质。"},{"k":"衍射与定点诱变","t":"X 射线晶体衍射解析三维结构，了解活性部位残基的相对位置、实际状态与酶-底物结合模式；定点诱变改变基因中 DNA 顺序以研究活性部位的必需氨基酸。"}],"note":"口径：依据《真题分类》资料原文六种方法；末点把原文第（5）（6）两条合并为一点。","opts":[],"printed_answer":"","ref":true},{"id":"n0203","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"分析下图的氧和曲线，指出哪一个代表肌红蛋白的氧和过程，哪一个代表血红蛋白的氧和过程，请从蛋白质的结构和别构效应调节等方面来解释为什么两者的氧和过程有如此大的差别，并说明其生理意义\n[图：横轴为 Oxygen pressure（mmHg），0/20/40/60/80/100；纵轴为 Fraction of hemoglobin bound with oxygen；曲线 a 为双曲线型（上方），曲线 b 为 S 形（下方），0.5 处有水平虚线与 20 处垂直虚线]","points":[{"k":"曲线归属","t":"曲线 a 为双曲线、低氧分压下饱和度即高，代表肌红蛋白（Mb）；曲线 b 为 S 形、P₅₀ 约 26 mmHg，代表血红蛋白（Hb）。"},{"k":"结构差异","t":"Mb 为单亚基、只含一个血红素，无亚基间作用；Hb 为 α₂β₂四聚体、含四个血红素，亚基间有盐桥与接触面。"},{"k":"协同效应","t":"Hb 结合 O₂ 后由 T 态转为 R 态，后续亚基亲和力逐级升高，故呈 S 形；Hill 系数约 2.8~3.0，Mb 为 1。"},{"k":"别构调节","t":"H⁺、CO₂、2,3-BPG、Cl⁻浓度升高及温度上升均稳定 T 态，使曲线右移、放氧增多；Mb 无此调节。"},{"k":"生理意义","t":"Mb 在低氧肌组织高亲和储氧；Hb 在肺泡高氧区高效结合、在组织低氧区沿陡峭段大量释放，实现高效运输。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0204","subj":"880","chap":"第九章 生物膜","type":"简答","years":[],"q":"什么是生物膜的流动性？请从生物膜的化学组成上说明为什么生物膜会具有流动性，并说明生物膜的流动性对生物体的重要意义","points":[{"k":"流动性定义","t":"指膜的运动状态，即膜内部脂质和蛋白质分子的运动性，是生物膜的主要特征之一。"},{"k":"膜脂流动","t":"包括侧向扩散与翻转扩散：侧向扩散较快、不需能量，翻转扩散较慢且需提供能量。"},{"k":"膜蛋白流动","t":"主要进行侧向扩散，一般不进行翻转的跨膜运动，这也是膜蛋白呈不对称分布的原因。"},{"k":"流动基础与因素","t":"脂双层中脂分子间的非共价相互作用赋予膜柔性，是流动性的基础；磷脂脂肪酸链的不饱和程度与链长（短链、不饱和均提高流动性）、胆固醇含量、温度、pH、离子强度、金属离子均影响流动性。胆固醇可降低含不饱和脂肪酸磷脂的流动性、提高含长饱和脂肪酸磷脂的流动性，使相变温度变宽。"},{"k":"生理意义","t":"适宜流动性可保证膜上结合的蛋白质或酶具有相应活性，是膜行使正常功能的必要条件；流动性大有利于酶分子侧向扩散与旋转、酶活性增加；物质运输依赖膜流动性，流动性降低使载体蛋白不能发挥功能。"}],"note":"口径：依据《真题分类》资料原文。原文在“物质运输依赖于膜的流动性，膜流动性降低可使膜上的载体蛋白不能发挥功能，导”处中断（末字残缺），此点据残句补足完整表述，未另加数据。","opts":[],"printed_answer":"","ref":true},{"id":"n0205","subj":"880","chap":"第三章 氨基酸","type":"简答","years":[],"q":"请你设计一个实验合成一个四肽库，这个肽库必须满足 C 端为 Ala，其他三个氨基酸为 Glu，Phe，Lys（氨基酸为现成）请问共有多少种组合方式，实验的基本过程是怎样的？","points":[{"k":"组合数为6","t":"不考虑氨基酸侧链基团参与肽键形成时，C 端固定 Ala，其余三位由 Glu、Phe、Lys 各用一次排列，共 3×2×1=6 种组合。"},{"k":"树脂挂接","t":"Glu、Phe、Lys、Ala 的 N 末端全部用叔丁氧甲酰基（BOC）保护，再由氨基被保护的 Ala 与氯甲基聚苯乙烯树脂反应，共价挂接在树脂上。"},{"k":"混合缩合延长","t":"除去 Ala 的 N 端保护基并中和后，以 DCC 为缩合剂，把 BOC 保护的 Glu、Phe、Lys 混合液连接到 Ala 氨基上，重复去保护、中和、缩合直到肽链合成最后一步。"},{"k":"切割脱保护","t":"把树脂悬浮在无水三氟乙酸中并通入干燥 HBr，使肽链从树脂上脱落，同时切除部分保护基团。"},{"k":"纯化鉴定","t":"所得产物中还含二肽、三肽、五肽等，可经凝胶电泳进一步纯化；整个过程可在程序控制的自动固相合成仪上完成，靠控制反应时间达到只合成四肽的目的。"}],"note":"口径：依据《真题分类》资料原文（BOC 保护、氯甲基聚苯乙烯树脂、DCC 缩合、三氟乙酸/HBr 切割均照录）。原文另列“考虑侧链参与”为 22 种，但其算式 6×2×2×1×2 的乘积为 48，前后矛盾，故未采用该数字。","opts":[],"printed_answer":"","ref":true},{"id":"n0206","subj":"880","chap":"第四章 蛋白质","type":"填空","years":["04"],"q":"Pauling 等人提出的蛋白质二级结构螺旋模型，每圈螺旋包含（ ）个氨基酸，每个氨基酸的高度为（ ）","points":[{"k":"答案","t":"3.6 个氨基酸；0.15 nm（1.5 Å）。α-螺旋每圈上升 0.54 nm，故每个残基沿轴升高 0.15 nm。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0207","subj":"880","chap":"第七章 核酸","type":"填空","years":["04"],"q":"DNA 变性后粘度（ ）A260 值（ ）影响 DNA Tm 值的因素有（ ）和（ ）","points":[{"k":"答案","t":"粘度下降；A260 升高（增色效应）；影响因素为 G+C 含量与离子强度——GC 越多、离子强度越高，Tm 越高。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0208","subj":"880","chap":"第三章 氨基酸","type":"填空","years":["04"],"q":"Leu、Ile 和 Val 是三种（ ）氨基酸，它们的脱氨基反应是由（ ）酶催化","points":[{"k":"答案","t":"支链氨基酸（BCAA）；支链氨基酸转氨酶（BCAT）。三者先转氨生成支链 α-酮酸，再由支链 α-酮酸脱氢酶氧化。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0209","subj":"880","chap":"第十六章 氨基酸代谢","type":"填空","years":["04"],"q":"在鸟氨酸循环中，精氨酸是生成（ ）和（ ）的前体","points":[{"k":"答案","t":"尿素和鸟氨酸。精氨酸在精氨酸酶催化下水解生成尿素并再生鸟氨酸，完成尿素循环。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0210","subj":"880","chap":"第三章 氨基酸","type":"填空","years":["04"],"q":"二十种氨基酸中（ ）无不对称碳原子（ ）与茚三酮反应生成黄色物质（ ）可以参与形成二硫键","points":[{"k":"答案","t":"甘氨酸（Gly）无不对称碳；脯氨酸（Pro）与茚三酮生成黄色物质；半胱氨酸（Cys）的 —SH 可形成二硫键。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0211","subj":"880","chap":"第七章 核酸","type":"填空","years":["04"],"q":"DNA 双螺旋是由（ ）和（ ）于（ ）年提出来的","points":[{"k":"答案","t":"Watson 和 Crick；1953 年。二人依据 Franklin 的 X 射线衍射照片提出 DNA 双螺旋模型。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0212","subj":"880","chap":"综合","type":"填空","years":["04"],"q":"酶与底物结合的主要化学键是（ ）（ ）和（ ）","points":[{"k":"答案","t":"氢键、离子键（盐键）和疏水作用。此外还有范德华力，均为非共价弱键，可逆且具协同性。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0213","subj":"880","chap":"第四章 蛋白质","type":"填空","years":["04"],"q":"带负电荷的蛋白质与阴离子交换树脂结合很紧，必须用（ ）pH 或用（ ）离子强度的洗脱液才能把该蛋白质洗下来","points":[{"k":"答案","t":"降低 pH；提高离子强度。降 pH 使蛋白负电荷减少、结合减弱，高盐竞争电荷，二者均可把蛋白洗下。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0214","subj":"880","chap":"第四章 蛋白质","type":"填空","years":["04"],"q":"测定蛋白质分子量的方法主要是（ ）（ ）（ ）等三种方法","points":[{"k":"答案","t":"SDS-聚丙烯酰胺凝胶电泳、凝胶过滤层析和超速离心法（沉降法）。质谱亦可精确测定分子量。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0215","subj":"880","chap":"第十章 糖酵解 糖异生","type":"填空","years":["04"],"q":"（ ）（ ）（ ）是酵解的关键酶","points":[{"k":"答案","t":"己糖激酶（肝内为葡萄糖激酶）、磷酸果糖激酶-1（PFK-1）和丙酮酸激酶。三者催化不可逆反应，是糖酵解的调节点。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0216","subj":"880","chap":"第四章 蛋白质","type":"填空","years":["04"],"q":"原核生物和真核生物的蛋白质生物合成，起始复合物分别是（ ）和（ ）","points":[{"k":"答案","t":"原核为 30S 起始复合物（30S·mRNA·fMet-tRNA_f），真核为 40S 起始复合物（40S·mRNA·Met-tRNA_i），再装配成 70S 与 80S。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0217","subj":"880","chap":"第五章 酶","type":"填空","years":["04"],"q":"调节酶的反应速度 V 对 [S] 作图得到（ ）形曲线","points":[{"k":"答案","t":"矩形双曲线。低 [S] 时 V 与 [S] 近似成正比，高 [S] 时趋于 Vmax，符合米氏方程。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0220","subj":"880","chap":"第五章 酶","type":"名词解释","years":["04"],"q":"酶促反应的前馈与反馈","points":[{"k":"定义","t":"反馈指反应产物反过来影响酶活性或酶合成，负反馈抑制、正反馈激活；前馈指底物或上游中间物预先调节后续酶活性。"},{"k":"变构与共价修饰","t":"二者均通过变构调节或共价修饰快速改变酶活性；前馈使终产物尚未生成即启动或关闭通路，反馈维持终产物浓度稳态。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0221","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":[],"q":"高尔夫基体","points":[{"k":"定义","t":"真核细胞内由数层扁平囊泡及小泡组成的细胞器，分顺面与反面，位于内质网与细胞膜之间，是蛋白质加工分选的枢纽。"},{"k":"加工分选与运输","t":"对来自内质网的蛋白质和脂质进行糖基化、硫酸化等加工与分选，形成分泌泡和溶酶体，并参与植物细胞壁成分合成。"}],"note":"卷面「高尔夫基体」应为「高尔基体」（Golgi apparatus），按高尔基体作答。","opts":[],"printed_answer":""},{"id":"n0224","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":[],"q":"蛋白质的二级结构","points":[{"k":"定义","t":"蛋白质分子中主链的局部空间盘曲折叠方式，不涉及侧链构象及肽段间关系，靠主链肽键的 C=O 与 N-H 间氢键维持。"},{"k":"氢键维持 α-螺旋","t":"主要类型有 α-螺旋（每圈 3.6 个残基、螺距 0.54 nm）、β-折叠、β-转角和无规卷曲，由主链氢键的方向与周期性决定。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0226","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"简述什么是波尔效应","points":[{"k":"效应定义","t":"增加 CO₂ 浓度和降低 pH 都能提高血红蛋白亚基的协同效应，使红细胞内血红蛋白氧亲和力下降、促进放氧；反之增高氧浓度使血红蛋白释放 H⁺ 与 CO₂，这种 pH 和 CO₂ 对氧亲和力的影响称波尔效应。"},{"k":"组织处放氧","t":"血液流经组织时，细胞呼吸代谢使 O₂ 低而 CO₂、H⁺ 高，降低血红蛋白亲和力促进放氧；放氧又促进血红蛋白结合 CO₂ 与 H⁺，清除 CO₂ 并缓冲 pH 下降。"},{"k":"肺部结合氧","t":"血液流经肺部时 O₂ 浓度高，有利于血红蛋白结合氧，并因此促进 CO₂ 与 H⁺ 的释放，完成气体交换。"},{"k":"生理意义","t":"通过波尔效应提高血红蛋白运输氧的能力，以满足组织对氧气的需求。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"n0227","subj":"880","chap":"第五章 酶","type":"简答","years":[],"q":"在很多酶的活性中心均由 His 残基参与，请解释原因","points":[{"k":"咪唑基pKa适中","t":"组氨酸侧链咪唑基的 pKa 为 6.0~7.0，在生理条件下约一半解离、一半不解离。"},{"k":"广义酸碱催化","t":"不解离部分可作质子供体、解离部分可作质子受体，既是酸又是碱，可进行广义酸碱共同催化，因此常参与构成酶的活性中心。"},{"k":"质子传递迅速","t":"咪唑基供出或接受质子的速度十分迅速，有利于酶进行高效的催化反应。"}],"note":"口径：依据《真题分类》资料原文，pKa 按原文 6.0~7.0。","opts":[],"printed_answer":"","ref":true},{"id":"n0228","subj":"880","chap":"第二十一章 细胞代谢与基因表达","type":"简答","years":[],"q":"简述什么是增强子","points":[{"k":"增强子定义","t":"真核基因组中一段能显著提高同源启动子转录效率的 DNA 调控序列。"},{"k":"位置方向无关","t":"作用与位置、方向、距离无关，可位于启动子上游、下游或内含子中，远距离亦可发挥效应。"},{"k":"组织特异性","t":"常含多个转录因子结合位点，与启动子组合决定基因的时空与组织特异表达。"},{"k":"作用机制","t":"结合特异反式因子后，经中介体与启动子空间成环接触，招募并激活 RNA 聚合酶Ⅱ。"},{"k":"与沉默子对应","t":"沉默子作用相反，二者共同精细调节转录水平；多个增强子簇集可形成超级增强子放大表达。"}],"note":"资料无对应原答案，按教材口径。资料该条为「波尔效应」，与本题「增强子」不是同一题。","opts":[],"printed_answer":"","ref":false},{"id":"n0229","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"简述蛋白质变性","points":[{"k":"变性定义","t":"理化因素破坏次级键与二硫键，使蛋白质空间构象改变、理化性质变化、生物活性丧失，而一级结构不变。"},{"k":"结构本质","t":"氢键、疏水作用、离子键被破坏，肽链由紧密折叠变为松散伸展，疏水基团暴露于表面。"},{"k":"性质改变","t":"溶解度降低、黏度升高、易被蛋白酶水解，紫外吸收与旋光性改变，失去结晶能力。"},{"k":"可逆与不可逆","t":"去除变性因素后恢复原构象称复性（如核糖核酸酶）；变性过度则分子聚集沉淀，不可逆。"},{"k":"实际应用","t":"高温、乙醇、紫外照射用于消毒灭菌；制备活性蛋白需低温、避免剧烈搅拌与强酸碱以防失活。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0230","subj":"880","chap":"第十四章 氧化磷酸化","type":"简答","years":[],"q":"简述什么是光合磷酸化","points":[{"k":"概念","t":"在叶绿体类囊体膜上，光能被捕光色素分子吸收并传给反应中心，反应中心把光能转化为电能、沿电子传递链传递，与磷酸化过程相偶联生成 ATP，称光合磷酸化。"},{"k":"两种类型","t":"按电子传递的方式可分为非循环式和循环式两种类型。"},{"k":"非循环光合磷酸化","t":"在基粒片层进行，是光合磷酸化的主要形式，涉及 PSⅡ复合体（P680）、细胞色素 b₆f 复合体、PSⅠ复合体（P700）三种复合体，电子传递为开放通路，结果产生 ATP 和 NADPH。"},{"k":"循环光合磷酸化","t":"在基质片层进行，仅涉及细胞色素 b₆f 和 PSⅠ、不涉及 PSⅡ，无 NADPH 产生与 O₂ 释放，只产生 ATP，可用于调节 ATP 与 NADPH 的比例。"}],"note":"口径：依据《真题分类》资料原文（概念＋两种类型）。","opts":[],"printed_answer":"","ref":true},{"id":"n0231","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"说明原核生物的蛋白质生物合成过程，并比较原核生物与真核生物在蛋白质生物合成过程中的异同","points":[{"k":"氨基酸活化","t":"甲酰甲硫氨酸（fMet）与 tRNA 在氨酰-tRNA 合成酶作用下消耗 2 个高能磷酸键，生成 fMet-tRNAf，使氨基酸活化。"},{"k":"起始复合物","t":"30S 先与 IF-1、IF-3 结合，经 SD 序列与 mRNA 形成 30S-mRNA 复合物；IF-2-GTP 携 fMet-tRNAf 进入 P 位并与起始密码子配对；起始因子离开、50S 加入，GTP 水解改变构象形成活化的起始复合物。"},{"k":"延伸三步循环","t":"进位：EF-Tu-GTP 送氨酰-tRNA 入 A 位，EF-Ts 使 EF-Tu·GDP 再生；转肽：肽基转移酶把 P 位氨基酸转到 A 位氨基上成肽键；移位：EF-G 水解 GTP 使核糖体与 mRNA 移位，P 位空载 tRNA 入 E 位脱落。"},{"k":"终止与释放","t":"UAA、UAG 或 UGA 进入 A 位时 RF-1、RF-2 识别，以水为底物使肽链水解脱落；RF-3 水解 GTP 使 RF 脱落，tRNA、mRNA 解离、核糖体大小亚基解体。"},{"k":"折叠与加工修饰","t":"新生肽链在酶与分子伴侣作用下边翻译边折叠，并在翻译时或翻译后切除 N 端 fMet、信号肽，形成二硫键、糖基化、连接辅基等。"},{"k":"原核真核异同","t":"相同：均由 N 端向 C 端合成、共用一套密码、均需三类 RNA 与蛋白因子、均经活化-起始-延伸-终止-加工五步、均耗能、均可被氯霉素和嘌呤霉素抑制。不同：原核转录翻译偶联、三种起始因子、SD 序列起始、fMet、EF-Tu/Ts/G、RF 三种、抑制剂为链霉素与四环素；真核转录翻译分开、起始因子十多种、帽子扫描模型起始并耗 ATP、Met、无 E 位点、eRF1/eRF3、抑制剂为白喉毒素与蓖麻毒素；两者每合成 1 个肽键均耗 4 个高能磷酸键。"}],"note":"口径：依据《真题分类》资料原文（原文含过程与对比表，此处归并为六点）；异同一点合并了原表整体、起始、延伸、终止、能量、抑制剂各行。","opts":[],"printed_answer":"","ref":true},{"id":"n0232","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"凝胶过滤和 SDS-聚丙烯酰胺凝胶电泳这两种分离蛋白质的方法均建筑在分子大小的基础上，而且两种方法均采用交联的多聚物作为支持介质，为什么在凝胶过滤时，相对分子质量小的蛋白质有较长的保留时间，而在 SDS-聚丙烯酰胺凝胶电泳时，它又跑得最快","points":[{"k":"凝胶过滤排阻","t":"葡聚糖凝胶颗粒交联介质排阻大分子，只允许小分子进入颗粒内部；大分子只能在颗粒间空隙通过，流经体积为床体积减去凝胶颗粒本身所占体积。"},{"k":"小分子保留久","t":"小分子能进入凝胶颗粒内部，须通过全部床体积才能流出，流经体积大、路程长，故比大分子保留时间长。"},{"k":"SDS赋予负电荷","t":"SDS 与蛋白质结合使其均带负电荷并呈伸展棒状，使迁移率与分子质量的对数呈线性关系。"},{"k":"电泳介质无间隙","t":"SDS-PAGE 的凝胶支持物相当于一整块，没有颗粒之间的空隙，蛋白质分子不论大小都须在交联介质内部移动。"},{"k":"小分子阻力小","t":"在网孔中移动时分子量越小受到的阻力越小，移动速度越快，故小分子跑得最快。"}],"note":"口径：依据《真题分类》资料原文（该条为 15 分真题）。","opts":[],"printed_answer":"","ref":true},{"id":"n0233","subj":"631","chap":"五、RNA 的调控机制","type":"论述","years":[],"q":"请论述 RNA 干扰的原理及其应用","points":[{"k":"现象定义","t":"双链 RNA 导入细胞后特异、高效地降解同源 mRNA，导致基因表达沉默，属转录后基因沉默。"},{"k":"Dicer切割","t":"dsRNA 被 RNaseⅢ家族核酸酶 Dicer 切成 21~23 nt 的小干扰 RNA（siRNA），带 5′磷酸与 3′两个碱基突出。"},{"k":"RISC装配","t":"siRNA 双链装入 RNA 诱导沉默复合物，AGO2 切割过客链，保留引导链形成有活性的 RISC。"},{"k":"靶向切割","t":"引导链与靶 mRNA 完全互补，AGO2 的 PAZ 与 PIWI 结构域在配对区中部切割，片段随后被外切酶降解。"},{"k":"催化放大","t":"一个 RISC 可循环切割多份 mRNA；植物中 RdRP 扩增次级 siRNA 并可系统性传播，沉默效应持久。"},{"k":"主要应用","t":"基因功能鉴定、抗病毒与抗虫作物、肿瘤与遗传病治疗（如 patisiran）、药物靶点筛选与基因敲低。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0234","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":[],"q":"试叙述 DNA 的遗传保真性是如何保证的","points":[{"k":"碱基互补配对","t":"A-T、G-C 的氢键数目与几何构型被聚合酶活性中心精确识别，是保真的第一道关卡。"},{"k":"聚合酶校对","t":"DNA 聚合酶具 3′→5′外切酶活性，错配末端难以延伸而被切除重合成，错误率降至约 10⁻⁷。"},{"k":"错配修复","t":"MutS 识别错配、MutL 与 MutH 在新链缺口处切割，以母链甲基化为标记切除并重合成，再降 10²~10³ 倍。"},{"k":"损伤修复网络","t":"碱基切除修复、核苷酸切除修复、重组修复与跨损伤合成共同清除各类损伤，SOS 反应为最后应急手段。"},{"k":"复制监控机制","t":"复制起点有序激活保证每周期只复制一次；细胞周期检查点与凋亡清除不可修复的损伤细胞。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0235","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"请比较原核生物和真核生物的 mRNA 的异同","points":[{"k":"相同之处","t":"均为单链、方向 5′→3′，含起始与终止密码子，均由 DNA 转录而来，都需核糖体翻译成蛋白质。"},{"k":"顺反子数目","t":"原核多为多顺反子，一条 mRNA 编码多种蛋白；真核通常为单顺反子，一条 mRNA 编码一种蛋白。"},{"k":"两端结构","t":"原核 5′端无帽子、靠 SD 序列定位起始；真核有 m⁷G 帽与 3′poly(A) 尾，靠帽子结合与扫描起始。"},{"k":"内含子与加工","t":"原核一般无内含子、不需剪接；真核有内含子，需剪接、加帽、加尾等加工后才能出核翻译。"},{"k":"时空与寿命","t":"原核无核膜，转录与翻译偶联、mRNA 半衰期仅数分钟；真核核内转录加工、胞质翻译，寿命较长。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0236","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":[],"q":"请画一个用于在细菌内表达原核基因的表达载体示意图","points":[{"k":"复制与筛选","t":"含 ColE1 类复制起点保证高拷贝自主复制，另带氨苄青霉素抗性基因（Amp 抗性）用于筛选转化子。"},{"k":"启动与操纵","t":"上游为强启动子（如 T7、lac、trc）及 lac 操纵基因，可由 IPTG 诱导，控制转录起始与强度。"},{"k":"核糖体结合位点","t":"启动子下游接 SD 序列（RBS），与 16S rRNA 3′端配对，决定翻译起始效率。"},{"k":"克隆位点与读框","t":"多克隆位点紧随 RBS 之后，插入片段须与起始密码子处于同一读框，避免移码。"},{"k":"终止与标签","t":"下游设终止密码子与转录终止子防止通读；可加 His 标签及蛋白酶切位点，便于检测与纯化。"},{"k":"环状排布示意","t":"线性顺序：ori—Amp 抗性基因—P/lacO—RBS—ATG—MCS—终止密码子—T7 终止子，首尾相接成环状质粒。"}],"note":"原题为作图题，此处以元件清单与线性排布示意代替图形。","opts":[],"printed_answer":""},{"id":"n0237","subj":"880","chap":"第三章 氨基酸","type":"简答","years":[],"q":"用标记的丙氨酸饲喂缺乏该氨基酸的机体，即使在天冬氨酸缺乏的情况下，也能在机体内检测到带标记的天冬氨酸，请运用你所学的生化知识解释这个现象。","points":[{"k":"丙氨酸脱氨基","t":"标记丙氨酸经转氨酶作用或氧化脱氨生成丙酮酸，放射性进入丙酮酸的碳骨架。"},{"k":"羧化成草酰乙酸","t":"丙酮酸羧化酶以生物素为辅基，消耗 ATP 与 CO₂，把丙酮酸羧化为草酰乙酸。"},{"k":"转氨生成天冬氨酸","t":"草酰乙酸在天冬氨酸氨基转移酶催化下接受氨基，生成带标记的天冬氨酸。"},{"k":"非必需可自合成","t":"天冬氨酸属非必需氨基酸，机体可经上述途径自行合成，故即使膳食缺乏也能检出其存在。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0238","subj":"880","chap":"第十五章 脂类代谢","type":"问答","years":[],"q":"脂肪酸 β 氧化过程与 TCA 循环有两步类似反应，写出这两步反应的化学方程式。","points":[{"k":"第一步脱氢","t":"脂酰 CoA + FAD → Δ²-反式-烯脂酰 CoA + FADH₂（脂酰 CoA 脱氢酶）；对应 TCA 中琥珀酸 + FAD → 延胡索酸 + FADH₂（琥珀酸脱氢酶）。"},{"k":"第二步脱氢","t":"β-羟脂酰 CoA + NAD⁺ → β-酮脂酰 CoA + NADH + H⁺（β-羟脂酰 CoA 脱氢酶）；对应苹果酸 + NAD⁺ → 草酰乙酸 + NADH + H⁺（苹果酸脱氢酶）。"},{"k":"相似的实质","t":"两步均为以 FAD 或 NAD⁺为受氢体的脱氢反应，反应类型相同而酶与底物不同。"}],"note":"若把水化与脱水也算作类似反应，则烯脂酰 CoA 水合酶与延胡索酸酶亦属同类。","opts":[],"printed_answer":""},{"id":"n0239","subj":"880","chap":"第十五章 脂类代谢","type":"计算","years":[],"q":"1mol 甘油酯酰（脂肪酸酰链为软脂酸）在体内彻底氧化成 H₂O 和 CO₂，净产生多少 mol ATP?","points":[{"k":"软脂酸活化","t":"软脂酸 + CoA + ATP → 软脂酰 CoA + AMP + PPi，消耗 2 个高能磷酸键。"},{"k":"β氧化产能","t":"16C 经 7 轮：7 FADH₂（10.5）+ 7 NADH（17.5）= 28 ATP。"},{"k":"乙酰CoA产能","t":"8 分子乙酰 CoA × 10 = 80 ATP；故每分子软脂酸净产 80 + 28 − 2 = 106 ATP。"},{"k":"甘油产能","t":"甘油活化 −1，脱氢 1.5，酵解段 2 + 1.5，丙酮酸氧化 2.5，TCA 10 = 16.5 ATP。"},{"k":"合计","t":"3 × 106 + 16.5 = 334.5 mol ATP（约 335 mol）。"}],"note":"按 3-磷酸甘油穿梭、NADH=2.5、FADH₂=1.5 计；旧 P/O 口径约 406 mol ATP。","opts":[],"printed_answer":""},{"id":"n0240","subj":"880","chap":"第十六章 氨基酸代谢","type":"填空","years":["05"],"q":"人类对氨基酸代谢的终产物是（　　　　）鸟类对氨基酸代谢的终产物是（　　　　）。植物解除氨的毒害的方法是（　　　　）","points":[{"k":"答案","t":"尿素；尿酸；生成酰胺（谷氨酰胺、天冬酰胺）。植物把氨固定到酰胺中储存运输，降低游离氨的毒性。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0241","subj":"880","chap":"第十三章 磷酸戊糖途径、乙醛酸循环","type":"填空","years":["05"],"q":"脂酸的（　　　　）学说是由 Knoop 于 1904 年提出的，脂酸合成过程中，乙酰 CoA 来源于（　　　　）或（　　　　）NADPH 来源于（　　　　）途径","points":[{"k":"答案","t":"β-氧化；糖（葡萄糖）或脂肪酸（β-氧化产物）；磷酸戊糖途径。Knoop 用标记脂肪酸证实每次切下二碳单位。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0242","subj":"880","chap":"第十四章 氧化磷酸化","type":"填空","years":["05"],"q":"TCA 循环的第一个产物是（　　　　）由（　　　　）（　　　　）和（　　　　）催化的反应是该循环的主要限速反应，TCA 循环中大多数酶位于（　　　　）只有（　　　　）位于线粒体内膜","points":[{"k":"答案","t":"柠檬酸；柠檬酸合酶、异柠檬酸脱氢酶和 α-酮戊二酸脱氢酶复合体；大多数酶在基质，只有琥珀酸脱氢酶位于线粒体内膜。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0243","subj":"880","chap":"第二章 脂类","type":"填空","years":["05"],"q":"激素的一种更广泛的定义是指（　　　　）根据溶解性质，激素可分为（　　　　）和（　　　　）两类。所有的固醇类激素都是由（　　　　）合成来的","points":[{"k":"答案","t":"由内分泌细胞分泌、经体液运输、作用于靶细胞受体的微量高效信息分子；按溶解性分脂溶性（亲脂性）与水溶性（亲水性）两类；固醇类激素均由胆固醇合成。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0244","subj":"880","chap":"第六章 维生素与辅酶","type":"填空","years":["05"],"q":"维生素是维持生物体正常生长所必需的一类（　　　　）有机物质，主要作用是作为（　　　　）的组分参与体内代谢。根据维生素的（　　　　）性质，可以将维生素分为两类，即（　　　　）和（　　　　）","points":[{"k":"答案","t":"低分子有机化合物；辅酶或辅基；溶解；脂溶性维生素、水溶性维生素。维生素不供能、不构成组织，主要作为辅酶（辅基）组分参与代谢，故按溶解性质分为两类。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0245","subj":"880","chap":"第六章 维生素与辅酶","type":"填空","years":["05"],"q":"按国际酶学委员会的规定，每一种酶都有一个唯一的编号，醇脱氢酶的编号是 EC1.1.1.1，EC 代表（　　　　）4 个数字分别代表（　　　　）（　　　　）（　　　　）（　　　　）","points":[{"k":"答案","t":"酶学委员会（Enzyme Commission）；四个数字依次代表大类（反应类型）、亚类、亚亚类、流水号。如 EC1.1.1.1 即氧化还原酶类、作用于 CH—OH、以 NAD⁺/NADP⁺ 为受体、第 1 号。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0246","subj":"880","chap":"第四章 蛋白质","type":"填空","years":["05"],"q":"T.R.Cech 和 S.Altman 因各自发现了（　　　　）而共同获得 1989 年的诺贝尔化学奖","points":[{"k":"答案","t":"核酶（ribozyme），即具有催化活性的 RNA。Cech 与 Altman 发现 RNA 可自身催化剪接，动摇了“酶都是蛋白质”的传统观念。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0247","subj":"880","chap":"第七章 核酸","type":"填空","years":["05"],"q":"核酸的基本结构单位是（　　　　）两类核酸在细胞中的分布不同，DNA 主要位于（　　　　）中，RNA 主要位于（　　　　）中","points":[{"k":"答案","t":"核苷酸；细胞核（染色体）；细胞质（核糖体）。核酸的基本单位是核苷酸，DNA 集中在核内，RNA 在核内合成后主要分布于细胞质。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0248","subj":"880","chap":"第七章 核酸","type":"填空","years":["05"],"q":"硝酸纤维素膜可结合（　　　　）链核酸，将 RNA 变性后转移到硝酸纤维素膜上再进行杂交，称（　　　　）印迹法","points":[{"k":"答案","t":"单链核酸；Northern 印迹法。硝酸纤维素膜以疏水作用结合变性的单链核酸，RNA 转移后与探针杂交即 Northern blot。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0249","subj":"880","chap":"第九章 生物膜","type":"填空","years":["05"],"q":"生物膜的流动性主要是由（　　　　）（　　　　）和（或（　　　　）所决定的，并且受温度的影响","points":[{"k":"答案","t":"磷脂（膜脂）分子；胆固醇；膜蛋白。脂肪酸链越短、不饱和度越高流动性越大，胆固醇双向调节，膜蛋白与脂双层的相互作用也影响流动性。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0250","subj":"880","chap":"第一章 糖类","type":"填空","years":["05"],"q":"糖类是具有（　　　　）结构的一大类化合物。糖类物质的主要生物学作用为","points":[{"k":"答案","t":"多羟基醛或多羟基酮（及其缩合物）。主要作用：①氧化供能与碳源；②结构成分（纤维素、几丁质、糖胺聚糖）；③细胞识别与信息传递（糖蛋白、糖脂）；④构成核酸的核糖与脱氧核糖；⑤代谢中间产物。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0252","subj":"880","chap":"第十章 糖酵解 糖异生","type":"名词解释","years":["16"],"q":"Cori 循环","points":[{"k":"定义","t":"肌肉糖酵解产生的乳酸经血液运至肝、在肝内异生为葡萄糖后再返回肌肉利用的循环，又称乳酸循环。"},{"k":"肝糖异生耗能","t":"肌内 NAD⁺ 得以再生、乳酸不至堆积中毒；肝中乳酸异生为糖需耗 6 分子 ATP，相当于把产能负担由肌肉转给肝。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0253","subj":"880","chap":"第十六章 氨基酸代谢","type":"名词解释","years":["16"],"q":"葡萄糖-丙氨酸循环","points":[{"k":"定义","t":"肌肉氨基酸以丙氨酸形式经血运至肝，肝内脱氨并将碳骨架异生为葡萄糖后送回肌肉的循环，兼运氨与补糖。"},{"k":"运氨兼补血糖","t":"肌内丙酮酸经转氨生成丙氨酸入血，肝中脱氨后碳骨架糖异生、氨进尿素循环；与 Cori 循环共同构成肌肉-肝代谢协作。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0255","subj":"880","chap":"第三章 氨基酸","type":"判断","years":["16"],"q":"一个化合物如果能同茚三酮反应生成紫色说明这个化合物是氨基酸、肽和蛋白质","points":[{"k":"答案","t":"正确。茚三酮与含 α-氨基的氨基酸、肽、蛋白质共热生成蓝紫色（Ruhemann 紫），可用作三者的呈色检出（脯氨酸生成黄色）。"}],"note":"严格说茚三酮阳性只证明存在 α-氨基，伯胺等也可显色；按通行口径判为正确。","opts":[],"printed_answer":""},{"id":"n0256","subj":"880","chap":"第十章 糖酵解 糖异生","type":"判断","years":["16"],"q":"酵母利用葡萄糖有氧代谢中，当 EMP 途径中的 3-磷酸甘油醛脱氢酶受到抑制后，此时代谢由于不能进入 TCA 循环，因而无 CO₂ 产生","points":[{"k":"答案","t":"错误。EMP 受阻后葡萄糖仍可经磷酸戊糖途径（HMP）氧化，6-磷酸葡萄糖酸脱氢酶催化的脱羧反应释放 CO₂，故不能说无 CO₂ 产生。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0257","subj":"880","chap":"第五章 酶","type":"判断","years":["16"],"q":"在结构上与底物无关的各种代谢物有可能改变酶的 Km 值","points":[{"k":"答案","t":"正确。与底物结构无关的代谢物可作为别构效应剂或混合型、反竞争型抑制剂，改变酶对底物的表观 Km，如 ATP 对磷酸果糖激酶-1。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0258","subj":"880","chap":"第十章 糖酵解 糖异生","type":"判断","years":["16"],"q":"ATP 是磷酸果糖激酶的底物，因而高浓度 ATP 可以加快磷酸果糖激酶催化果糖-6-磷酸生成果糖-1,6-二磷酸的速度","points":[{"k":"答案","t":"错误。ATP 既是底物又是别构抑制剂，高浓度 ATP 结合别构位点降低酶对果糖-6-磷酸的亲和力，表现为抑制而非加速。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0259","subj":"880","chap":"第七章 核酸","type":"判断","years":["16"],"q":"有一核酸的两个制剂，A 的 A260/A280=2.0，B 的 A260/A280=1.0，因此可判断 A 比 B 纯","points":[{"k":"答案","t":"正确。纯 RNA 的 A260/A280 约为 2.0、纯 DNA 约 1.8；A280 主要来自蛋白质，B 仅 1.0 说明蛋白污染重，故 A 较纯。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0260","subj":"880","chap":"第四章 蛋白质","type":"判断","years":["16"],"q":"某一基因发生了点突变，则必然导致其编码的蛋白质的氨基酸序列改变","points":[{"k":"答案","t":"错误。因密码子简并性，同义（沉默）突变不改变氨基酸；突变位于内含子或非编码区同样不影响氨基酸序列。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0261","subj":"880","chap":"第七章 核酸","type":"判断","years":["16"],"q":"DNA 样品 A 版 B 分别与样品 C 进行杂交实验，得到杂交情况如下图:那么可以说明样品 A 与 C 的同源性比样品 B 与 C 的同源性高","points":[{"k":"答案","t":"原卷缺图，无法判断。判断同源性应比较杂交信号强度与异源双链的解链温度：信号越强、Tm 越高，同源性越高。"}],"note":"题干所述杂交结果图缺失，无图不可判定。","opts":[],"printed_answer":""},{"id":"n0262","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"判断","years":["16"],"q":"蛋白质合成起始后，核糖体中每形成一个肽都会消耗两个 GTP 生成 GDP 和 Pi","points":[{"k":"答案","t":"错误。肽键形成由肽酰转移酶（核糖体 RNA）催化，本身不耗 GTP；每延长一个氨基酸才消耗 2 个 GTP（EF-Tu 进位、EF-G 转位各 1 个）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0263","subj":"880","chap":"第一章 糖类","type":"判断","years":["16"],"q":"由两个葡萄糖通过糖苷键相连总共形成 8 种葡二糖，他们都具有还原性，这是因为葡萄糖具有还原性的缘故","points":[{"k":"答案","t":"错误。两分子葡萄糖可形成多种糖苷键异构体，但并非都有还原性：海藻糖为 α,α-1,1 键，两个异头碳均参与成键，属非还原糖。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0264","subj":"880","chap":"第一章 糖类","type":"判断","years":["16"],"q":"在观察淀粉的酶水解是常用 KI-I2 显色，当从蓝色变至碘液的本色时，说明淀粉已完全水解成葡萄糖了","points":[{"k":"答案","t":"错误。碘液褪色只表明淀粉与糊精已水解到不再显色的程度，产物可为糊精、麦芽糖；证明生成葡萄糖须用斐林试剂或葡萄糖氧化酶法。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0390","subj":"880","chap":"第十一章 柠檬酸循环","type":"论述","years":["16","17"],"q":"为什么 TCA 循环是糖、脂、蛋白质的重要中间环节?","points":[{"k":"三大物质入口","t":"糖经丙酮酸、脂肪经 β 氧化、蛋白质经脱氨，最终都生成乙酰 CoA，统一进入 TCA 氧化。"},{"k":"共同供能通路","t":"每轮 TCA 产 3 NADH、1 FADH₂、1 GTP，经氧化磷酸化生成大量 ATP，是三大物质共同的产能中心。"},{"k":"提供合成前体","t":"α-酮戊二酸→谷氨酸，草酰乙酸→天冬氨酸，琥珀酰 CoA→卟啉，为氨基酸、核苷酸、血红素合成供碳架。"},{"k":"糖异生必经","t":"草酰乙酸经 PEP 羧激酶生糖，是乳酸、生糖氨基酸异生为葡萄糖的必经环节。"},{"k":"联系脂肪合成","t":"柠檬酸穿梭把乙酰 CoA 运至胞质供脂肪酸合成，TCA 中间物也参与碳链延伸。"},{"k":"回补与调节","t":"丙酮酸羧化酶回补草酰乙酸；NADH/ATP、Ca²⁺ 别构调节关键酶，使循环通量随能量需求改变。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0266","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["16"],"q":"有一份核酸样品，可能含有少量蛋白质，只允许测定一种元素即可确定其有无蛋白质污染，您选哪一种元素，为什么?","points":[{"k":"选择硫元素","t":"测定样品的含硫量：蛋白质含 Met 与 Cys 而带硫，核酸组成中不含硫，检出硫即说明有蛋白污染。"},{"k":"对照磷元素","t":"核酸含磷约 9%，蛋白质一般不含磷，测磷可定量核酸；但磷蛋白会造成误判，故测硫更特异。"},{"k":"操作要点","t":"先充分透析除去含硫缓冲液与巯基试剂，再用元素分析或比色法测硫，与纯核酸对照比较判定。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0267","subj":"880","chap":"第七章 核酸","type":"简答","years":["16"],"q":"有多种方法可区分高分子量的 DNA 和 RNA 分子，请写出一种简单可行的生物分析方法，并简要说明理由","points":[{"k":"碱水解电泳法","t":"0.3 mol/L KOH 37 ℃ 过夜，RNA 被水解为单核苷酸，DNA 保持完整；中和后琼脂糖电泳，出现完整条带者为 DNA。"},{"k":"原理依据","t":"RNA 核糖的 2′-OH 可形成 2′,3′-环磷酸中间体，使磷酸二酯键在碱中易水解；DNA 脱氧核糖无 2′-OH，故耐碱。"},{"k":"备选显色法","t":"二苯胺法 DNA 显蓝色、地衣酚法 RNA 显绿色；或用 DNase 与 RNase 分别处理后电泳判断。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0268","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":["16"],"q":"假如膳食中含有丰富的丙氨酸，但缺乏天冬氨酸，是否出现天冬氨酸缺乏现象?为什么?","points":[{"k":"丙氨酸转丙酮酸","t":"膳食中丰富的丙氨酸经转氨或氧化脱氨生成丙酮酸，成为糖异生与非必需氨基酸合成的碳源。"},{"k":"羧化生草酰乙酸","t":"丙酮酸羧化酶以生物素为辅基、消耗 ATP 与 CO₂，将丙酮酸羧化为草酰乙酸。"},{"k":"转氨得天冬氨酸","t":"草酰乙酸经天冬氨酸氨基转移酶接受氨基，生成天冬氨酸，供蛋白质合成。"},{"k":"结论不出现缺乏","t":"天冬氨酸是非必需氨基酸，体内可自行合成，故膳食缺乏时不出现缺乏现象。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0269","subj":"880","chap":"第五章 酶","type":"简答","years":["16"],"q":"请解释什么是酶的活力和比活力，并说出这两个指标在酶的纯化过程中可以说明什么","points":[{"k":"酶活力定义","t":"酶催化化学反应的能力，以最适条件下单位时间内底物转化量表示；1 U 为每分钟催化 1 μmol 底物。"},{"k":"比活力定义","t":"每毫克蛋白所含的酶活力单位数（U/mg），代表酶的纯度。"},{"k":"纯化中的含义","t":"总活力反映酶的回收率与得率，比活力反映纯度，两者之比给出纯化倍数。"},{"k":"结果判断","t":"比活力与纯化倍数升高说明分离有效；总活力骤降提示失活或损失，比活力不升说明未去除杂蛋白。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0270","subj":"880","chap":"第五章 酶","type":"简答","years":["16"],"q":"有时别构酶的活性可以被低浓度的竞争性抑制剂激活，请解释","points":[{"k":"优先结合活动构象","t":"竞争性抑制剂结构与底物相似，优先结合 R 态酶的活性中心，使平衡偏向 R 态。"},{"k":"稳定R态促协同","t":"结合后构象改变使其余亚基对底物的亲和力升高（正协同），低浓度时表现为活性被激活。"},{"k":"低浓度才激活","t":"抑制剂浓度低时构象激活效应大于占位竞争，净效应为活性升高；浓度升高则转为竞争性抑制。"},{"k":"别构位点激动","t":"部分抑制剂实际结合于别构部位，作为别构激活剂或阻断负协同信号，使酶由 T 态转向 R 态。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0271","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":["16"],"q":"糖酵解，戊糖磷酸途径，糖异生途径之间如何联系","points":[{"k":"G6P共同起点","t":"葡萄糖-6-磷酸是糖酵解与磷酸戊糖途径的共同中间物，分流比例由 G6PD 与 PFK-1 的活性决定。"},{"k":"PPP回流糖酵解","t":"PPP 产生的果糖-6-磷酸与甘油醛-3-磷酸可返回糖酵解；核糖-5-磷酸供核苷酸合成，NADPH 供还原性合成。"},{"k":"糖异生底物来源","t":"糖酵解产物丙酮酸、乳酸及生糖氨基酸经丙酮酸羧化与 PEPCK 等步骤逆转生成葡萄糖，绕过三个不可逆反应。"},{"k":"反向调控防空转","t":"胰高血糖素经 cAMP 促糖异生、抑糖酵解，胰岛素相反；PFK-1 与 FBPase-1、PK 与 PEPCK 反向调节避免无效循环。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0272","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["16"],"q":"乙酰辅酶 A 羧化酶在脂肪酸合成中起调控作用，试述这个调控机制","points":[{"k":"柠檬酸别构激活","t":"柠檬酸、异柠檬酸结合乙酰 CoA 羧化酶（ACC），促其由无活性的二聚体聚合成有活性的纤维状多聚体。"},{"k":"长链脂酰CoA抑制","t":"软脂酰 CoA 等长链脂酰 CoA 反馈抑制 ACC 并促其解聚失活，防止脂肪酸过度合成。"},{"k":"磷酸化共价调节","t":"AMPK 磷酸化 ACC 的丝氨酸位点使其失活；胰岛素激活蛋白磷酸酶去磷酸化而恢复活性。"},{"k":"酶含量调节","t":"高糖、胰岛素与甲状腺素促进 ACC 基因转录，长期高脂摄入则下调，改变酶蛋白总量。"},{"k":"丙二酰CoA下游效应","t":"丙二酰 CoA 既是脂肪酸合成底物，又抑制肉碱棕榈酰转移酶Ⅰ（CPT-1），阻断脂肪酸入线粒体氧化。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0273","subj":"880","chap":"第二十一章 细胞代谢与基因表达","type":"简答","years":["16"],"q":"利用操纵子学说，叙述酶的生物合成有哪些调节机制","points":[{"k":"负调控诱导型","t":"lac 操纵子：无诱导物时阻遏蛋白结合操作基因封闭转录，乳糖异构为别乳糖后结合阻遏蛋白使其脱落，恢复转录。"},{"k":"负调控阻遏型","t":"trp 操纵子：色氨酸作为辅阻遏物与阻遏蛋白结合后才具活性，结合操作基因关闭合成途径。"},{"k":"正调控与双控","t":"lac 还需 cAMP-CRP 复合物结合启动子上游进行正调控；葡萄糖缺乏时 cAMP 升高，形成正负双重控制。"},{"k":"衰减子调节","t":"trp 前导区可翻译前导肽，色氨酸充足时翻译顺利形成 3-4 终止发夹，转录提前终止。"},{"k":"全局与级联控制","t":"严谨反应（ppGpp）、分解代谢物阻遏、调节子与双组分系统协调多个操纵子，实现整体适应。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0277","subj":"880","chap":"第四章 蛋白质","type":"问答","years":["10"],"q":"a 角蛋白的结构，计算头发生长速度","points":[{"k":"α螺旋基本参数","t":"多肽链以右手 α-螺旋盘绕，每圈 3.6 个残基、螺距 0.54 nm，每残基沿轴上升约 0.15 nm。"},{"k":"卷曲螺旋组装","t":"两条 α-螺旋以七残基重复（heptad）的疏水面缠绕成二聚体，再聚成原纤维、微纤维与宏纤维。"},{"k":"二硫键交联","t":"角蛋白富含半胱氨酸，链间二硫键使其坚硬不溶；烫发本质是打断并重排二硫键。"},{"k":"生长速度计算","t":"生长速度 v = 生长长度/时间；按每残基轴向 0.15 nm 折算，合成速率 = v ÷ 0.15 nm（个残基/单位时间）。"},{"k":"示例估算","t":"若头发每天长 0.35 mm，则每天约合成 0.35×10⁶ nm ÷ 0.15 nm ≈ 2.3×10⁶ 个残基，按每条链 300 残基计约 7.8×10³ 条链。"}],"note":"原卷未给出具体生长长度与时间数据，只能给出计算式；代入题目所给数据即可。","opts":[],"printed_answer":""},{"id":"n0278","subj":"880","chap":"第十章 糖酵解 糖异生","type":"问答","years":["10"],"q":"乳酸脱氢酶活性的测定","points":[{"k":"反应原理","t":"乳酸 + NAD⁺ ⇌ 丙酮酸 + NADH + H⁺；NADH 在 340 nm 有特异吸收，故测吸光度变化速率即可反映酶活性。"},{"k":"测定方向选择","t":"正向需 pH 8.8~9.0 并加足量 NAD⁺；逆向以丙酮酸与 NADH 为底物、pH 7.4，速率快、灵敏度高，临床常用。"},{"k":"操作步骤","t":"缓冲液、底物与 NAD⁺预温至 37 ℃，加入酶液混匀，立即在 340 nm 连续读取 3 min 的 ΔA/min，同时做空白管。"},{"k":"活性计算","t":"U/L = ΔA/min × 反应总体积 ×10⁶ ÷（6220 × 光径 × 取样体积），6220 为 NADH 的摩尔吸光系数。"},{"k":"注意事项","t":"避免溶血（红细胞富含 LDH），样品稀释使 ΔA/min 处于线性范围，控制温度与 pH，防止底物与产物抑制。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0279","subj":"880","chap":"第七章 核酸","type":"问答","years":["10"],"q":"DNA 的复制","points":[{"k":"半保留复制","t":"双链解开后各自作模板，子链与母链互补，每个子代分子含一条母链与一条新链。"},{"k":"半不连续合成","t":"DNA 聚合酶只能 5′→3′延伸，前导链连续合成，随从链以冈崎片段不连续合成后由连接酶封口。"},{"k":"复制酶系分工","t":"解旋酶解链、SSB 稳定单链、拓扑异构酶解除正超螺旋、引物酶合成 RNA 引物、PolⅢ延伸、PolⅠ切除引物并填补缺口。"},{"k":"起始与双向延伸","t":"原核自 oriC 起始形成两个复制叉双向推进，呈 θ 形；真核有多个复制起点，且每个周期只复制一次。"},{"k":"终止与忠实性","t":"复制叉相遇处由 Tus-ter 系统终止；碱基配对、3′→5′校对与错配修复共同使误差率降至 10⁻⁹~10⁻¹⁰。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0280","subj":"880","chap":"第四章 蛋白质","type":"问答","years":["10"],"q":"SDS-PAGE ）阳离子交换层析","points":[{"k":"SDS掩盖电荷","t":"蛋白质与 SDS（十二烷基硫酸钠）结合，SDS 为阴离子、带很高负电荷，掩盖不同蛋白质间原有的电荷差别；SDS 又是变性剂，破坏分子内氢键与疏水作用，使大多数蛋白质伸展成同样的棒状。"},{"k":"按质量分离","t":"该技术完全基于蛋白质质量的不同进行分离；由于凝胶的分子筛效应，迁移率与分子质量的对数呈线性关系，用已知分子质量标准蛋白作标准曲线即可由未知蛋白迁移率求其分子质量。"},{"k":"离子交换原理","t":"基于氨基酸的电荷行为，利用离子交换剂上可解离基团对各种离子亲和力不同而分离，分为阳离子交换层析与阴离子交换层析。"},{"k":"阳离子交换树脂","t":"树脂含酸性基团，可解离出 H⁺，与溶液中的其他阳离子发生交换，使相应阳离子结合在树脂上而与其他物质分开。"},{"k":"洗脱回收","t":"洗脱时逐渐提高 pH 和盐离子浓度，使结合的阳离子被置换下来，回收目标产物。"}],"note":"口径：依据《真题分类》资料原文。资料该条只讲阳离子交换树脂，未提阴离子交换的具体基团，故第 4 点仅写阳离子交换。","opts":[],"printed_answer":"","ref":true},{"id":"n0281","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"问答","years":["10"],"q":"大肠杆菌转录终止信号","points":[{"k":"不依赖ρ终止","t":"终止位点上游有富含 GC 的回文结构（二重对称区）可转录成自身互补的发夹，其后为 4~8 个腺苷酸组成的序列、可转录成寡聚 U；发夹使 RNA 聚合酶暂停，rU·dA 结合不稳定使 RNA 从 DNA 解离。"},{"k":"依赖ρ终止","t":"终止位点上游也具有能使转录产物 RNA 形成发夹结构的回文序列，故必须借助 ρ 因子才能终止。"},{"k":"ρ因子活性","t":"ρ 因子具有依赖于 RNA 的 ATPase 活性和解旋酶活性。"},{"k":"穷追模型","t":"ρ 因子结合在新产生的 RNA 链上，借水解 ATP 获得的能量沿 RNA 移动，RNA 聚合酶遇终止子暂停时追上，其解旋酶活性造成 RNA 释放与聚合酶脱落。"}],"note":"口径：依据《真题分类》资料原文。与 o107 同源，按资料两类终止子分述，未采用旧稿中资料以外的 NusA/NusG 与抗终止内容。","opts":[],"printed_answer":"","ref":true},{"id":"n0282","subj":"880","chap":"第五章 酶","type":"问答","years":["10"],"q":"酶活性中心的测定","points":[{"k":"化学修饰定位","t":"用专一性化学试剂（如 DFP 标记丝氨酸、TPCK 标记组氨酸、碘乙酸标记半胱氨酸）修饰侧链，若修饰后酶失活，说明该残基参与催化。"},{"k":"底物保护实验","t":"在底物或竞争性抑制剂存在下重复修饰，若关键残基被保护、酶活保留，则证明被保护的基团位于活性中心。"},{"k":"亲和标记","t":"合成与底物结构相似的标记试剂（亲和标记物），它先与活性中心特异结合再共价标记邻近残基，可 pinpoint 结合部位。"},{"k":"定点突变验证","t":"把推测的关键残基逐一突变为丙氨酸，测 kcat/Km，活性大幅下降者即为活性中心残基。"},{"k":"结构解析","t":"X 射线晶体衍射或冷冻电镜解析酶与底物类似物的复合物结构，直接看到结合与催化基团的空间位置。"},{"k":"pH 速率曲线","t":"测 kcat/Km 对 pH 的钟形曲线，由拐点 pKa 推断活性中心必需基团的类型（如 His 咪唑基 pKa≈6）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0283","subj":"880","chap":"第十章 糖酵解 糖异生","type":"问答","years":["10"],"q":"跑步中乳酸的变化","points":[{"k":"安静水平低","t":"安静时血乳酸约 1~2 mmol/L，生成与清除（心肌、肝、肾氧化利用）处于动态平衡。"},{"k":"起跑氧亏","t":"起跑瞬间供氧跟不上，丙酮酸脱氢酶受 NADH/乙酰 CoA 抑制，丙酮酸只能经乳酸脱氢酶还原为乳酸。"},{"k":"强度决定浓度","t":"强度越大，Ⅱ型肌纤维糖酵解越快、乳酸生成越多；超过乳酸阈（约 4 mmol/L）后呈指数上升。"},{"k":"运动中清除","t":"心肌与红肌直接氧化乳酸，肝经 Cori 循环异生为葡萄糖，故乳酸是燃料而非终废物。"},{"k":"恢复期回落","t":"运动后乳酸半衰期约 15~25 min，靠氧化与糖异生清除；积极性恢复（慢跑）比静息清除更快。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0284","subj":"880","chap":"第十三章 磷酸戊糖途径、乙醛酸循环","type":"问答","years":["10"],"q":"种子萌发，脂肪转换成糖，乙醛酸循环和 TCA 的中间代谢物","points":[{"k":"总过程","t":"脂肪—脂酶→甘油＋脂肪酸—β 氧化→乙酰 CoA—乙醛酸循环→草酰乙酸—糖异生→葡萄糖。"},{"k":"乙醛酸循环体","t":"动物体内乙酰 CoA 不能转变成糖，而一些植物含乙醛酸循环体；乙醛酸循环是柠檬酸循环的修改形式，由 2 分子乙酰 CoA 净合成 1 分子草酰乙酸，因产生重要中间物乙醛酸而得名。"},{"k":"异柠檬酸裂解","t":"前两步与 TCA 相同：乙酰 CoA 与草酰乙酸缩合成柠檬酸，经乌头酸酶异构为异柠檬酸；在异柠檬酸裂解酶催化下，异柠檬酸直接分解为乙醛酸和琥珀酸，琥珀酸参与 TCA 循环。"},{"k":"苹果酸合酶","t":"乙醛酸在苹果酸合酶催化下与另一分子乙酰 CoA 生成苹果酸，苹果酸转运至细胞质基质后再氧化为草酰乙酸。"},{"k":"糖异生供能","t":"草酰乙酸经糖异生途径生成葡萄糖，使萌发种子中贮存的脂质转变为糖类、为生长提供能源，这就是油料种子「由脂变糖」的关键。"}],"note":"口径：依据《真题分类》资料原文；原文净产物写为草酰乙酸（非琥珀酸），已照录。","opts":[],"printed_answer":"","ref":true},{"id":"n0285","subj":"880","chap":"第七章 核酸","type":"问答","years":[],"q":"从组织中提取细胞 DNA 后，如何鉴定其纯度?","points":[{"k":"紫外比值","t":"纯 DNA 的 A260/A280 约为 1.8；低于 1.6 提示蛋白污染，高于 1.9 提示 RNA 污染。"},{"k":"盐酚残留","t":"A260/A230 应大于 2.0，偏低说明胍盐、酚、糖类等残留。"},{"k":"电泳看条带","t":"0.8% 琼脂糖凝胶电泳，看是否为单一锐利条带、有无降解拖尾与 RNA 条带。"},{"k":"荧光定量","t":"用 Hoechst 33258、PicoGreen 或 qPCR 定量，只测双链 DNA，比紫外法准确。"},{"k":"浓度换算","t":"A260=1 相当于 50 μg/mL 双链 DNA，据此折算浓度与得率。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0286","subj":"880","chap":"第五章 酶","type":"问答","years":[],"q":"有一个酶分子抑制剂，不清楚它是可逆抑制剂还是不可逆抑制剂，请设计两种实验方案，说明它是属于哪一类抑制剂?","points":[{"k":"透析去药","t":"方案一：抑制剂与酶预孵育后透析、超滤或凝胶过滤除去游离抑制剂，再测活；活性恢复为可逆抑制，不恢复为不可逆抑制。"},{"k":"稀释复性","t":"大幅稀释使抑制剂浓度骤降，可逆抑制因解离平衡移动而活性回升，不可逆抑制的酶已被共价修饰，活性不回升。"},{"k":"酶量作图","t":"方案二：固定抑制剂浓度、改变酶量作 v-[E] 图；可逆抑制为过原点直线（斜率降低），不可逆抑制直线右移出现“死酶”截距。"},{"k":"双倒数判型","t":"确认可逆后再作 Lineweaver-Burk 图：交于纵轴为竞争性，交于横轴为非竞争性，平行线为反竞争性。"},{"k":"预孵育时间","t":"不可逆抑制的程度随预孵育时间延长而加深，可逆抑制很快达平衡、不随时间加剧。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0287","subj":"880","chap":"第十章 糖酵解 糖异生","type":"问答","years":[],"q":"碘乙酸抑制酵母糖酵解的实验中，\n（1）酵母+葡萄糖溶液+三氯乙酸的试管中没有气泡产生\n（2）酵母+葡萄糖溶液+碘乙酸的试管中有少量气泡产生\n（3）酵母+葡萄糖溶液的试管中有大量气泡产生\n试解释产生上述现象的生化本质。","points":[{"k":"正常产气多","t":"酵母酒化酶系把葡萄糖经 EMP 生成丙酮酸，再脱羧为乙醛并释放 CO₂，故（3）气泡大量。"},{"k":"烷化巯基","t":"碘乙酸与 3-磷酸甘油醛脱氢酶（GAPDH）活性中心的 Cys 巯基共价烷化，酶不可逆失活。"},{"k":"阻断 EMP","t":"糖酵解在 GAPDH 处断流，丙酮酸生成锐减、CO₂ 随之减少，故（2）只有少量气泡（残余中间物继续短暂发酵）。"},{"k":"三氯乙酸灭活","t":"三氯乙酸是强酸，使蛋白变性、酵母立即死亡，全部酶失活，故（3）无气泡产生。"},{"k":"对照定抑制点","t":"（1）为空白对照排除非酶产气；（2）与（3）比较说明碘乙酸抑制的位点在 GAPDH 而非己糖激酶。"}],"note":"题干（1）指“酵母+葡萄糖+三氯乙酸”管，为原卷排版笔误（原文序号与描述错位），按化学实质作答。","opts":[],"printed_answer":""},{"id":"n0288","subj":"880","chap":"第一章 糖类","type":"问答","years":[],"q":"五只试剂瓶中分别装的是核糖、葡萄糖、果糖、蔗糖和淀粉溶液，试用最简便的化学方法鉴别。","points":[{"k":"碘液检淀粉","t":"各取 1 mL 加碘液，变蓝者为淀粉，其余四管不显蓝色。"},{"k":"间苯二酚检酮糖","t":"Seliwanoff 试验（间苯二酚-浓盐酸，沸水浴）迅速显红色者为果糖与蔗糖，葡萄糖、核糖不显色。"},{"k":"班氏检还原糖","t":"Benedict 试验中果糖生成砖红色 Cu₂O 沉淀，蔗糖为非还原糖仍呈蓝色，借此把二者分开。"},{"k":"地衣酚检戊糖","t":"Bial 试验（地衣酚-盐酸）显蓝绿色者为核糖，葡萄糖呈淡黄色，至此五瓶全部鉴别。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0289","subj":"880","chap":"第四章 蛋白质","type":"问答","years":[],"q":"合成的多肽多聚谷氨酸(Glu)n，当处于 pH 3.0 以下时，在水溶液中形成α-螺旋,而在 pH5.0 以上时，却为伸展的状态。(Glu: pK1=2.19、pK2=4.25、pK3=9.67; Lys: pKi=2.18、pK2=8.95、pK3=10.53)\n（1）解释该现象\n（2）在哪那种 pH 条件下，多聚赖氨酸(Lys) n 会形成α-螺旋。","points":[{"k":"低 pH 成螺旋","t":"Glu 侧链 pKr=4.25，pH<3 时羧基基本不解离、侧链不带电，无同种电荷排斥，肽链卷曲成 α-螺旋。"},{"k":"高 pH 去螺旋","t":"pH>5 时侧链解离为 -COO⁻，同种负电荷相互排斥，氢键维持的螺旋被撑开而呈伸展状态。"},{"k":"电荷决定构象","t":"结论：侧链净电荷密度是螺旋稳定性的决定因素，同性电荷排斥破坏 α-螺旋。"},{"k":"多聚赖氨酸螺旋","t":"Lys 侧链 pKr=10.53，pH>10.5（约 11 以上）时 ε-氨基去质子化为中性，无排斥，多聚赖氨酸形成 α-螺旋；pH<9 时带正电而伸展。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0290","subj":"880","chap":"第十五章 脂类代谢","type":"计算","years":[],"q":"1mol 的油酸彻底氧化能产生多少摩尔的 ATP? 写出分析过程。","points":[{"k":"分步列式","t":"总 ATP = 9 乙酰 CoA×10 + 8 NADH×2.5 + 7 FADH₂×1.5 − 活化 2。"},{"k":"代入轮数","t":"油酸为 18 碳单不饱和脂肪酸，经 8 轮 β 氧化生成 9 分子乙酰 CoA、8 分子 NADH、8 分子 FADH₂。"},{"k":"双键省一步","t":"Δ9 顺式双键经烯脂酰 CoA 异构酶转为 Δ2 反式，跳过一轮脂酰 CoA 脱氢酶，少生成 1 分子 FADH₂（−1.5 ATP）。"},{"k":"结果汇总","t":"90 + 20 + 10.5 − 2 = 118.5，即 1 mol 油酸彻底氧化净生成约 118.5 mol ATP。"}],"note":"按现代 P/O 比（NADH=2.5、FADH₂=1.5）计算；若用旧教材 P/O 比（NADH=3、FADH₂=2），结果为 144 mol ATP。","opts":[],"printed_answer":""},{"id":"n0291","subj":"880","chap":"第八章 抗生素与激素","type":"简答","years":[],"q":"肝脏是重要调节血糖器官，简述如何维持血糖平衡的","points":[{"k":"餐后合成糖原","t":"血糖升高时胰岛素促进肝细胞经葡萄糖激酶磷酸化葡萄糖，以 UDPG 为供体合成肝糖原贮存。"},{"k":"空腹分解糖原","t":"胰高血糖素、肾上腺素经 cAMP-PKA 激活糖原磷酸化酶，肝糖原分解为 G-6-P，再由葡萄糖-6-磷酸酶水解成葡萄糖入血。"},{"k":"饥饿启动异生","t":"肝以乳酸、甘油、生糖氨基酸为原料经糖异生补糖，是空腹 8 h 后维持血糖的主要方式。"},{"k":"激素双向调节","t":"胰岛素降糖，胰高血糖素与肾上腺素升糖，二者比值决定肝糖输出方向。"},{"k":"储备有限","t":"肝糖原仅约 100 g，只能维持数小时，长时间饥饿靠糖异生与脂肪供能节省葡萄糖。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0292","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"问答","years":[],"q":"根据核酸的生物功能，回答下列问题。\n（1）DNA 双链：3'-GTGTTAACGT-5'\n　　　　　　　5'-CACAATTGCA-3'\n① DNA 双链转录的方向是由右向左进行，写出 mRNA 序列。\n② 指出 RNA 聚合酶在 DNA 模板链上移动的方向。\n（2）根据 mRNA 序列：5'-GCACAUGCAAAAUUACUCUGUAGCGCA-3'\n① 写出翻译后氨基酸的序列，指出 N-端氨基酸是哪个？\n② 如果 tRNA 上的反密码子是 CUA，这个 tRNA 转递哪个氨基酸？\n[图：右上角为竖排的\"遗传密码子表（mRNA）\"，16 行×5 列，首列与后续列为 UUU 苯丙氨酸、UCU 丝氨酸…等密码子-氨基酸对照，表格整体旋转 90°]","points":[{"k":"转录产物","t":"卷面答：mRNA 为 3′-CUGUUAAGGU-5′；按下方模板链反向互补推导应为 5′-UGCAAUUGUG-3′（见 note）。"},{"k":"聚合酶移动","t":"RNA 聚合酶沿模板链 3′→5′ 方向移动，卷面记作“向右，沿下方 DNA 链的 3′→5′ 方向”，合成 RNA 的方向为 5′→3′。"},{"k":"起始氨基酸","t":"从 mRNA 中第一个 AUG 开始读码，N-端为 Met（甲硫氨酸），原核为甲酰甲硫氨酸 fMet。"},{"k":"肽链序列","t":"卷面答 N-Met-Gln-Asn-Tyr-Leu-C；按密码表逐组读码实为 Met-Gln-Asn-Tyr-Ser-Val-Ala（见 note）。"},{"k":"反密码子","t":"反密码子 CUA 与密码子 5′-GAU-3′ 反向互补，对应 Asp（天冬氨酸）；卷面作 Lys（见 note）。"}],"note":"卷面印答与推导不符，疑为排版串行：① 以模板链 5′-CACAATTGCA-3′（3′ 端在右）反向互补，mRNA 应为 5′-UGCAAUUGUG-3′；② 按 mRNA 5′-GCACAUGCAAAAUUACUCUGUAGCGCA-3′ 自 AUG 读码为 Met-Gln-Asn-Tyr-Ser-Val-Ala；③ 反密码子若为 3′-CUA-5′，对应密码子 5′-GAU-3′ 即 Asp，若为 5′-CUA-3′ 则对应终止密码子 UAG，均非 Lys。考点以“模板链反向互补、AUG 起始、反密码子反向配对”为准。","opts":[],"printed_answer":"① 3'-CUGUUAAGGU-5'；② 向右，沿下方 DNA 链的 3'→5' 方向移动；① N-Met-Gln-Asn-Tyr-Leu-C；② Lys（反密码子 3'-GAU-5'）"},{"id":"n0293","subj":"880","chap":"第十六章 氨基酸代谢","type":"论述","years":[],"q":"氨对机体毒害的作用机制，怎么代谢氨。","points":[{"k":"耗竭酮戊二酸","t":"氨与 α-酮戊二酸生成谷氨酸，抽走 TCA 中间物使循环减速、ATP 生成下降，脑细胞能量衰竭。"},{"k":"谷氨酰胺耗能","t":"氨与谷氨酸合成谷氨酰胺消耗 ATP，脑内谷氨酰胺蓄积产生渗透效应，引起星形胶质细胞肿胀、脑水肿。"},{"k":"递质失衡","t":"谷氨酸、GABA 合成受阻，兴奋性与抑制性递质失衡，出现震颤、扑翼样震颤乃至昏迷（肝性脑病）。"},{"k":"丙氨酸运氨","t":"肌肉把氨交给丙酮酸生成丙氨酸，经血运至肝，脱氨后进尿素循环，即丙氨酸-葡萄糖循环。"},{"k":"谷氨酰胺运氨","t":"脑与肌肉以无毒的谷氨酰胺形式运氨，入肝、肾经谷氨酰胺酶释放氨；肾排 NH₄⁺ 兼调酸碱。"},{"k":"尿素循环解氨","t":"肝内 NH₃+CO₂+2ATP 生成氨甲酰磷酸，经鸟氨酸循环合成尿素由肾排出，是解氨毒的主要途径。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0294","subj":"880","chap":"第八章 抗生素与激素","type":"论述","years":[],"q":"胰岛素有 A B 两条链\n①是否代表有两个亚基\n②设计实验进行测定\n③胰岛素治疗糖尿病的生化机制","points":[{"k":"同链两段","t":"胰岛素 A 链 21 肽、B 链 30 肽由同一前体胰岛素原切除 C 肽而来，两链以 A7-B7、A20-B19 两个二硫键共价相连。"},{"k":"亚基定义","t":"亚基指寡聚蛋白中靠非共价键结合的独立肽链，可被尿素、SDS 等解离；胰岛素两条链由共价二硫键连接，不能解离为独立肽链，故不代表两个亚基。"},{"k":"还原断链","t":"实验：8 mol/L 尿素加 β-巯基乙醇（或 DTT）还原二硫键，再做 SDS-PAGE 或凝胶过滤测分子量。"},{"k":"分子量对比","t":"还原前为单一约 5.8 kD 条带，还原后出现 A、B 两条小肽，证明两链以二硫键相连；若真为亚基，变性剂只改变构象、不改变肽链条数。"},{"k":"末端与质谱","t":"辅以 N-端氨基酸分析、肽图与质谱，确认两条链来自同一前体而非独立亚基。"},{"k":"受体信号通路","t":"治疗机制：胰岛素结合受体 α 亚基，激活 β 亚基酪氨酸激酶，经 IRS-1/PI3K/Akt 促 GLUT4 转位，增加肌、脂组织摄糖，促糖原与脂肪合成、抑制糖异生。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0295","subj":"880","chap":"第五章 酶","type":"计算","years":[],"q":"称取 25mg 蛋白酶粉配制成 25mL 酶溶液，从中取出 0.1mL 酶液，以酪蛋白为底物，用 Folin-酚比色法测定酶活力，得知每小时产生 1500μg 酪氨酸。另取 2mL 酶液，用凯氏定氮法测得蛋白质为 0.2mg ，若以每分钟产生 1μg 酪氨酸的酶量为 1 个活力单位计算，根据以上数据，求出：\n（1）1mL 酶液中所含蛋白质量及活力单位。\n（2）比活力。\n（3）1g 酶制剂的总蛋白含量及总活力。","points":[{"k":"蛋白浓度","t":"2 mL 酶液含蛋白 0.2 mg，故 1 mL 含 0.2÷2=0.1 mg 蛋白。"},{"k":"活力单位","t":"0.1 mL 酶液每小时产酪氨酸 1500 μg，即 25 μg/min=25 U；换算到 1 mL 为 250 U。"},{"k":"比活力计算","t":"比活力 = 250 U/mL ÷ 0.1 mg/mL = 2500 U/mg 蛋白。"},{"k":"总蛋白含量","t":"25 mg 酶粉配成 25 mL 即 1 mg/mL，含蛋白 0.1 mg/mL，故蛋白占 10%；1 g 酶制剂含总蛋白 0.1 g=100 mg。"},{"k":"总活力计算","t":"每毫克酶粉 250 U，1 g 酶制剂总活力 = 1000×250 = 2.5×10⁵ U。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0296","subj":"880","chap":"第十章 糖酵解 糖异生","type":"计算","years":[],"q":"一摩尔乳酸完全氧化成二氧化碳和水产生多少 ATP。","points":[{"k":"脱氢生成 NADH","t":"乳酸脱氢酶把乳酸氧化为丙酮酸，生成 1 分子 NADH，经苹果酸-天冬氨酸穿梭计 2.5 ATP。"},{"k":"氧化脱羧","t":"丙酮酸脱氢酶复合体生成乙酰 CoA，再产 1 分子 NADH，计 2.5 ATP。"},{"k":"TCA 产能","t":"1 分子乙酰 CoA 经 TCA 产 3 NADH+1 FADH₂+1 GTP，共 10 ATP。"},{"k":"结果汇总","t":"2.5+2.5+10 = 15，即 1 mol 乳酸彻底氧化净生成 15 mol ATP。"}],"note":"按苹果酸-天冬氨酸穿梭计；若胞质 NADH 经甘油磷酸穿梭（1.5 ATP），则为 13.5 mol。","opts":[],"printed_answer":""},{"id":"n0297","subj":"880","chap":"第十章 糖酵解 糖异生","type":"计算","years":[],"q":"一摩尔磷酸烯醇式丙酮酸完全氧化成二氧化碳和水产生多少 ATP。","points":[{"k":"底物水平磷酸化","t":"磷酸烯醇式丙酮酸经丙酮酸激酶生成丙酮酸，同时把高能磷酸转给 ADP，得 1 ATP。"},{"k":"氧化脱羧","t":"丙酮酸→乙酰 CoA，由丙酮酸脱氢酶复合体产 1 分子 NADH，计 2.5 ATP。"},{"k":"TCA 产能","t":"乙酰 CoA 经 TCA 彻底氧化产 10 ATP。"},{"k":"结果汇总","t":"1+2.5+10 = 13.5，即 1 mol 磷酸烯醇式丙酮酸彻底氧化净生成 13.5 mol ATP。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0298","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"名词解释","years":["22"],"q":"QNT 测序技术","points":[{"k":"定义","t":"牛津纳米孔技术（ONT）单分子测序：单链核酸穿过膜上纳米孔时引起特征性电流变化，据此实时直接读出碱基序列。"},{"k":"长读长直读修饰","t":"无需 PCR 与荧光标记，读长可达数十至上百 kb，可直读 RNA 及甲基化修饰；早期单次准确率偏低，需生物信息学校正。"}],"note":"卷面「QNT」疑为 ONT（Oxford Nanopore Technologies）的 OCR 误识，按纳米孔单分子测序作答。","opts":[],"printed_answer":""},{"id":"n0300","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["22"],"q":"PCR 原理及应用","points":[{"k":"变性退火延伸","t":"94 ℃ 使模板解链，降温至 50~60 ℃ 引物与模板互补退火，72 ℃ 由 Taq DNA 聚合酶从引物 3′-OH 延伸。"},{"k":"指数扩增","t":"每轮产物又作模板，n 轮后目标片段约扩增 2ⁿ 倍，30 轮可达 10⁹ 倍。"},{"k":"引物定边界","t":"一对引物决定扩增片段的两端与特异性，dNTP、Mg²⁺、缓冲液与耐热酶提供反应条件。"},{"k":"克隆与建库","t":"应用：目的基因扩增与克隆、引入酶切位点、定点突变、测序模板制备、cDNA 文库构建。"},{"k":"检测与定量","t":"病原核酸检测、遗传病与肿瘤基因筛查、法医个体识别；qPCR 定量、RT-PCR 检测 RNA 表达。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0301","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":["22"],"q":"乳糖操纵子","points":[{"k":"结构基因组成","t":"lacZ（β-半乳糖苷酶）、lacY（通透酶）、lacA（乙酰转移酶）共用一个启动子，转录成多顺反子 mRNA。"},{"k":"负调控阻遏","t":"无乳糖时 LacI 阻遏蛋白结合操纵基因 O，阻碍 RNA 聚合酶；乳糖经 β-半乳糖苷酶转为异乳糖，作为诱导物使阻遏蛋白脱落。"},{"k":"正调控CAP","t":"葡萄糖缺乏时 cAMP 升高，cAMP-CAP 复合物结合 CAP 位点，促进 RNA 聚合酶结合，转录增强。"},{"k":"葡萄糖效应","t":"葡萄糖充足时 cAMP 低、CAP 不能结合，即使有乳糖转录也很弱，故乳糖与葡萄糖并存时优先利用葡萄糖。"}],"note":"资料无对应原答案：该条 ref_a 仅有“（参考生化真题总结 / 练习册P162）”一行标注，无答案内容，故保留教材口径。","opts":[],"printed_answer":"","ref":false},{"id":"n0302","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["22"],"q":"动物转基因的方法","points":[{"k":"显微注射","t":"原核期受精卵雄原核显微注射线性 DNA，再移植入假孕母体，最经典、整合率与表达率较高。"},{"k":"病毒载体","t":"逆转录病毒或慢病毒载体感染胚胎或体细胞，外源基因整合入基因组，效率高但容量小、有安全风险。"},{"k":"胚胎干细胞打靶","t":"ES 细胞经同源重组定点整合后注入囊胚，可做基因敲除与定点改造，能传代形成生殖系嵌合体。"},{"k":"体细胞核移植","t":"转染体细胞后取其核移入去核卵母细胞，重构胚移植代孕，获得转基因克隆动物（如转基因克隆猪）。"},{"k":"精子介导","t":"精子携带外源 DNA 受精，或睾丸内注射；操作简便但效率低、多为嵌合体。"},{"k":"基因编辑","t":"CRISPR/Cas9、TALEN、ZFN 在受精卵或体细胞定点整合，效率与精确性最高，为当前主流。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0303","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":["22"],"q":"原核生物基因表达调控的特点","points":[{"k":"以转录起始为主","t":"调控主要发生在转录起始，其次为转录终止与翻译水平，无核膜分隔、转录翻译可偶联。"},{"k":"操纵子模式","t":"功能相关基因串联成操纵子，共转录为多顺反子 mRNA，由一个开关统一控制。"},{"k":"正负双重调控","t":"阻遏蛋白介导负调控，CAP 等激活蛋白介导正调控，两种信号可叠加整合。"},{"k":"衰减子微调","t":"前导序列形成终止或抗终止发夹，在转录水平细调（如 trp 操纵子的衰减作用）。"},{"k":"mRNA 寿命短","t":"mRNA 半衰期仅数分钟，可快速启停；另有 σ 因子更换、严谨反应（ppGpp）等全局调控。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0304","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["22"],"q":"原核和真核基因的区别","points":[{"k":"基因结构","t":"原核基因连续、无内含子；真核基因多含内含子与外显子，转录后需剪接。"},{"k":"组织方式","t":"原核多为操纵子、多顺反子；真核为单顺反子，一个基因转录一条 mRNA。"},{"k":"染色体包装","t":"原核 DNA 裸露于拟核；真核 DNA 与组蛋白结合成核小体、再折叠为染色体。"},{"k":"启动子元件","t":"原核为 -10/-35 区、由 σ 因子识别；真核有 TATA 框、CAAT 框、GC 框及增强子，需多种转录因子。"},{"k":"复制与表达","t":"原核单复制起点、转录翻译偶联；真核多复制起点，转录在核内、翻译在胞质，分室进行。"},{"k":"核外基因组","t":"真核另有线粒体、叶绿体基因，半自主复制，遗传密码与核基因略有差异（如 UGA 编码 Trp）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0305","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"实验","years":["22"],"q":"双酶切实验 给你一个双酶切之后的片段长度 然后让你计算这个片段长度以及把这些片段拼接起来","points":[{"k":"读图算长度","t":"先由各酶切位点在质粒与片段上的位置算出片段长度，核对“总长=各片段之和”，并判断插入方向。"},{"k":"双酶切体系","t":"载体与目的片段分别用两种限制酶在各自最适缓冲液中 37 ℃ 酶切 1~2 h，注意避免星活性；位点不兼容时分步酶切。"},{"k":"胶回收纯化","t":"琼脂糖电泳分离，切胶回收目的片段与载体骨架，去除小片段、酶与盐。"},{"k":"定向连接","t":"T4 DNA 连接酶 16 ℃ 过夜，两对不同粘性末端保证定向插入；载体去磷酸化防止自连。"},{"k":"转化鉴定","t":"转化感受态 E. coli，抗生素平板筛选，菌落 PCR、酶切图谱与测序验证拼接正确。"}],"note":"原卷仅描述“给双酶切后片段长度，计算并拼接”，未给出具体序列、酶名与数值，故按通用流程与计算原则作答。","opts":[],"printed_answer":""},{"id":"n0306","subj":"880","chap":"第十章 糖酵解 糖异生","type":"填空","years":[],"q":"在糖酵解途径中，有三个酶是调节控制酶，它们分别是(己糖激酶)(6-磷酸 果糖激酶)(丙酮酸激酶)","points":[{"k":"答案","t":"己糖激酶（葡萄糖激酶）、6-磷酸果糖激酶-1、丙酮酸激酶。三者催化糖酵解中三步不可逆反应，是限速步骤与别构调节位点。"}],"note":"","opts":[],"printed_answer":"己糖激酶；6-磷酸果糖激酶；丙酮酸激酶"},{"id":"n0307","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"填空","years":[],"q":"σ亚基是(RNA聚合酶)酶的一个亚基，其主要功能与(RNA聚合酶识别并结合启动子)有关","points":[{"k":"答案","t":"RNA 聚合酶；识别并结合启动子。σ 亚基与核心酶组成全酶，专一识别 −35 与 −10 区，转录起始后即脱落。"}],"note":"","opts":[],"printed_answer":"RNA聚合酶；RNA聚合酶识别并结合启动子"},{"id":"n0308","subj":"880","chap":"第七章 核酸","type":"填空","years":[],"q":"DNA作为遗传物质的直接证据是(肺炎双球菌转化实验、噬菌体侵染细菌实验)，间接证据是(DNA 分布在染色体内,是染色体的主要成分,而染色体是直接与遗传有关的).\n（细胞核内 DNA 的含量十分稳定,而且与染色体的数目存在着平行关系，在同一种生物的细胞中,体细胞(二倍体)中 DNA 的含量是生殖细胞(单倍体)中 DNA 含量的 2 倍，体细胞中染色体的数量也正好是生殖细胞的 2 倍）、(DNA在代谢中较稳定,不受生物体的营养条件、年龄等因素的影响)、(作用于 DNA 的一些物理和化学因素，如紫外线、X 射线、氮芥等都可以引起生物体遗传特性的改变)","points":[{"k":"答案","t":"肺炎双球菌转化实验、噬菌体侵染细菌实验；DNA 位于染色体内、是染色体的主要成分并与遗传直接相关。前者直接证明 DNA 携带遗传信息，后者由 DNA 的分布、含量恒定及与染色体数目的平行关系提供间接证据。"}],"note":"","opts":[],"printed_answer":"肺炎双球菌转化实验、噬菌体侵染细菌实验；DNA 分布在染色体内，是染色体的主要成分，而染色体是直接与遗传有关的"},{"id":"n0309","subj":"880","chap":"第十一章 柠檬酸循环","type":"填空","years":[],"q":"在 TCA 循环中，唯一一步底物磷酸化的步骤是(琥珀酰 CoA→琥珀酸)，联系糖酵解和 TCA循环的物质是(丙酮酸)","points":[{"k":"答案","t":"琥珀酰 CoA→琥珀酸；丙酮酸。该步由琥珀酰 CoA 合成酶催化经底物水平磷酸化生成 GTP；丙酮酸氧化脱羧成乙酰 CoA 进入 TCA，是糖酵解与 TCA 的连接点。"}],"note":"","opts":[],"printed_answer":"琥珀酰 CoA→琥珀酸；丙酮酸"},{"id":"n0310","subj":"880","chap":"第五章 酶","type":"填空","years":[],"q":"米氏方程中 Km 的物理意义是(当酶反应速率达到最大反应速率一半时的底物浓度)其单位为(molL1)根据 1/Km 的大小，可以推断酶与底物(亲和力大小)","points":[{"k":"答案","t":"当反应速率达到最大速率一半时的底物浓度；mol/L；亲和力大小。Km 是酶的特征常数，1/Km 越大表示酶与底物亲和力越强。"}],"note":"","opts":[],"printed_answer":"当酶反应速率达到最大反应速率一半时的底物浓度；mol/L；亲和力大小"},{"id":"n0311","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"填空","years":[],"q":"DNA 重组的步骤包括(同源 DNA 分子间对应部位单链同时断裂，并交换连接，形成Holliday 中间体)( 分支移动,产生异源双链 DNA )( 中间体切开并修复,完成重组)","points":[{"k":"答案","t":"①同源 DNA 对应部位单链同时断裂并交换连接，形成 Holliday 中间体；②分支移动，产生异源双链 DNA；③中间体切开并修复，完成重组。"}],"note":"","opts":[],"printed_answer":"同源 DNA 分子间对应部位单链同时断裂，并交换连接，形成 Holliday 中间体；分支移动，产生异源双链 DNA；中间体切开并修复，完成重组"},{"id":"n0312","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"填空","years":[],"q":"AUG 这- 密码子编码(甲硫氨酸)氨酸，同时它又是(起始)密码子","points":[{"k":"答案","t":"甲硫氨酸；起始。AUG 是唯一兼作起始密码子的氨基酸密码子，原核起始掺入的是甲酰甲硫氨酸（fMet）。"}],"note":"","opts":[],"printed_answer":"甲硫氨酸；起始"},{"id":"n0313","subj":"880","chap":"第四章 蛋白质","type":"选择","years":["23"],"q":"血红蛋白氧合曲线右移的原因","points":[{"k":"答案","t":"A。CO₂ 分压升高产生 Bohr 效应，Hb 对 O₂ 亲和力下降、曲线右移；pH 升高使曲线左移，O₂ 分压降低只是沿曲线移动而非曲线移动。"}],"note":"","opts":["A. 二氧化碳分压增大","B. N2 分压减小","C. pH 值增加","D. O2 分压降低"],"printed_answer":""},{"id":"n0314","subj":"880","chap":"第十五章 脂类代谢","type":"选择","years":["23"],"q":"脂肪酸合成中需要 NADPH+H+来自于","points":[{"k":"答案","t":"A。磷酸戊糖途径的 6-磷酸葡萄糖脱氢酶与 6-磷酸葡萄糖酸脱氢酶产生 NADPH，是脂肪酸合成还原力的主要来源，胞质苹果酸酶亦可供氢。"}],"note":"","opts":["A. 磷酸戊糖途径","B. TCA 循环","C. 葡萄糖无氧降解","D. 糖异生途径"],"printed_answer":""},{"id":"n0315","subj":"880","chap":"第十六章 氨基酸代谢","type":"选择","years":["23"],"q":"月份男婴血清中检测到苯丙氨酸和苯丙酮酸，被诊断为尿毒症，以下检测与病例一致的是","points":[{"k":"答案","t":"A。苯丙酮尿症由苯丙氨酸羟化酶（PAH）缺陷所致，酶活性常降至正常 2% 以下；尿黑酸升高见于尿黑酸尿症。"}],"note":"题干“尿毒症”应为“苯丙酮尿症”，属笔误。","opts":["A. 苯丙氨酸羟化酶活性为普通人的 2%","B. 血清尿黑酸水平升高","C. 维生素 B12 缺乏","D. 血清磷酸比多醛水平升高"],"printed_answer":""},{"id":"n0316","subj":"880","chap":"第十六章 氨基酸代谢","type":"选择","years":["23"],"q":"一碳单位可以合成下列哪个物质","points":[{"k":"答案","t":"C。一碳单位（N⁵,N¹⁰-亚甲基四氢叶酸等）为 dTMP 的甲基化及嘌呤环 C2、C8 提供碳原子，故可合成胸腺嘧啶。"}],"note":"","opts":["A. 脑磷脂","B. 胆固醇","C. 胸腺嘧啶","D. 血红素"],"printed_answer":""},{"id":"n0317","subj":"631","chap":"综合","type":"名词解释","years":["08"],"q":"同源基因","points":[{"k":"定义","t":"由共同祖先基因经进化分化而来、序列与功能具相似性的一组基因，含种间的直系同源与种内的旁系同源。"},{"k":"直系旁系两类型","t":"直系同源源于物种形成、功能多相同；旁系同源源于基因重复、易分化新功能；序列一致性是推断功能与构建进化树的基础。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0318","subj":"631","chap":"综合","type":"名词解释","years":["08"],"q":"生物大分子","points":[{"k":"定义","t":"由许多小分子单体以共价键聚合而成、相对分子质量巨大（通常大于 10⁴）的有机分子，如蛋白质、核酸、多糖。"},{"k":"单体脱水缩合","t":"单体经脱水缩合形成肽键、磷酸二酯键、糖苷键；空间结构决定功能，是遗传信息表达与生命活动的物质基础。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0320","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":["08"],"q":"TATAbox","points":[{"k":"定义","t":"真核Ⅱ类基因启动子中位于转录起始点上游约 −25~−30 bp 处、富含 A/T 的保守序列（TATAAA）。"},{"k":"TBP 定位起始点","t":"TATA 结合蛋白（TBP，属 TFⅡD）识别并结合 TATA box，使 TFⅡD 定位、组装前起始复合物，决定转录起始位点的准确性。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0321","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":["08"],"q":"转录单位","points":[{"k":"定义","t":"从启动子开始到终止子结束、被 RNA 聚合酶完整转录为一条 RNA 的 DNA 片段，是基因转录的结构与功能单位。"},{"k":"可含多基因","t":"一个转录单位可只含一个基因，也可含多个基因（操纵子、多顺反子 mRNA）；产物可为 mRNA、tRNA 或 rRNA，界限由启动子与终止子界定。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0323","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"名词解释","years":["08"],"q":"基本转录因子","points":[{"k":"定义","t":"真核 RNA 聚合酶Ⅱ 转录所必需、与 TATA box 及起始位点结合并组装成前起始复合物的一组通用转录因子。"},{"k":"TFⅡD 起步装配","t":"TFⅡD 含 TBP 识别 TATA box，TFⅡB 桥接聚合酶，TFⅡH 具解旋与 CTD 激酶活性；与聚合酶装配成前起始复合物，为Ⅱ类基因共用。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0324","subj":"631","chap":"综合","type":"判断","years":["08"],"q":"生物大分子的螺旋结构普遍存在于二级结构","points":[{"k":"答案","t":"×（错）。螺旋只是二级结构的一种形式，二级结构还包括 β-折叠、β-转角与无规卷曲，并非“普遍存在”于所有生物大分子。"}],"note":"该表述笼统，按卷面答案判错。","opts":[],"printed_answer":"×"},{"id":"n0325","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":["08"],"q":"通过改变原核生物启动子或 SD 序列可能会大大提高外源基因的表达水平。","points":[{"k":"答案","t":"√（对）。启动子强弱决定转录起始频率，SD 序列与 16S rRNA 的互补程度决定翻译起始效率，改造二者可显著提高外源基因表达量。"}],"note":"","opts":[],"printed_answer":"√"},{"id":"n0326","subj":"631","chap":"综合","type":"判断","years":["08"],"q":"基因重叠的现象主要发生在真核基因组中。","points":[{"k":"答案","t":"×（错）。基因重叠主要见于原核生物与病毒（尤其噬菌体）基因组以压缩遗传信息，真核基因组中较少见。"}],"note":"","opts":[],"printed_answer":"×"},{"id":"n0327","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":["08"],"q":"在同源基因中外显子序列保守性","points":[{"k":"答案","t":"×（错）。同源基因间的保守性主要体现于外显子编码区，内含子变异较大；题面表述不完整，故按卷面判错。"}],"note":"题干不完整，仅存“在同源基因中外显子序列保守性”。","opts":[],"printed_answer":"×"},{"id":"n0328","subj":"631","chap":"一、染色体结构","type":"判断","years":["08"],"q":"所有细胞遗传物质都是与蛋白质","points":[{"k":"答案","t":"×（错）。原核生物 DNA 不与组蛋白结合、无核小体，部分病毒遗传物质为 RNA，故不能说所有细胞遗传物质都与蛋白质结合。"}],"note":"题干残缺，按“遗传物质均与蛋白质结合”理解。","opts":[],"printed_answer":"×"},{"id":"n0329","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":["08"],"q":"结构基因可能会转录及翻译成不同的蛋白质","points":[{"k":"答案","t":"√（对）。真核结构基因经可变剪接、不同启动子起始或翻译后加工，可产生多种 mRNA 与不同蛋白质。"}],"note":"","opts":[],"printed_answer":"√"},{"id":"n0330","subj":"631","chap":"七、分子生物学技术","type":"填空","years":["08"],"q":"Western 印迹是针对(蛋白质)特异性鉴定技术，Northern 印迹法则是针对( RNA)进行的分\n子杂交技术。","points":[{"k":"答案","t":"蛋白质；RNA。Western 印迹用抗体检测蛋白，Northern 印迹用核酸探针检测 RNA，Southern 印迹检测 DNA。"}],"note":"","opts":[],"printed_answer":"蛋白质；RNA"},{"id":"n0331","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"填空","years":["08"],"q":"反式作用因子通常有三个结构域，(DNA 结合结构域)、(转录激活结构域)、(链接域)","points":[{"k":"答案","t":"DNA 结合结构域；转录激活结构域；连接域（卷面作“链接域”）。DNA 结合域识别顺式元件，激活域招募辅激活因子，连接域维持结构完整。"}],"note":"","opts":[],"printed_answer":"DNA 结合结构域；转录激活结构域；链接域"},{"id":"n0332","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"填空","years":["08"],"q":"原核生物基因的终止子两种主要类型(依赖ρ因子)和(不依赖ρ因子)","points":[{"k":"答案","t":"依赖 ρ 因子；不依赖 ρ 因子。前者由 ρ 蛋白水解 ATP 解离转录复合物，后者靠转录产物 3′端寡聚 U 与发夹结构使聚合酶停顿脱落。"}],"note":"","opts":[],"printed_answer":"依赖ρ因子；不依赖ρ因子"},{"id":"n0333","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"填空","years":["08"],"q":"环状双链 DNA 的复制可以分为(滚环复制)、(θ环复制)和(D 环复制)三种类型。","points":[{"k":"答案","t":"滚环复制；θ 环复制（θ 型复制）；D 环复制。分别见于噬菌体单链 DNA、质粒与大肠杆菌染色体、线粒体 DNA。"}],"note":"","opts":[],"printed_answer":"滚环复制；θ环复制；D 环复制"},{"id":"n0334","subj":"631","chap":"综合","type":"选择","years":["08"],"q":"基因组代表一个细胞或生物体的","points":[{"k":"答案","t":"B。基因组指一个细胞或生物体所含的全部遗传信息，包括编码与非编码序列。"}],"note":"","opts":["A. 部分遗传信息","B. 整套遗传信息","C. 可转录基因","D. 可表达基因"],"printed_answer":"B"},{"id":"n0335","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"选择","years":["08"],"q":"对转座子的叙述还不正确的是","points":[{"k":"答案","t":"C。简单转座子（IS 序列）只编码转座酶、不携带抗药基因；携带抗药基因的是复合转座子（Tn），故 C 项“简单转座子可编码抗药基因”为不正确项。"},{"k":"干扰项","t":"A、B、D 三项表述本身成立：转座可引起插入突变、可在基因组内移位、需要转座酶催化。"}],"note":"卷面标注为 D，但逐项核对后 C 才是“不正确”的表述，本库按 C 收录，考场若遇此题建议写明理由。","opts":["A. 转座子是位于 DNA 上可自主复制和位移的基本单位。","B. 插入序列是最简单的转座子","C. 简单转座子可以编码某些抗药基因","D. 简单转座子编码转座酶","E. 复合转座子两侧是相同或高度同源的 IS 序列，可编码转座酶等。"],"printed_answer":"D"},{"id":"n0336","subj":"631","chap":"综合","type":"考点","years":["08"],"q":"关于蛋白质折叠的","points":[{"k":"答案","t":"原卷题干与选项缺失，无法作答。通行考点：蛋白质折叠由一级结构决定，需分子伴侣（Hsp70、GroEL/GroES）辅助，经熔球态形成最低自由能的天然构象。"}],"note":"题干仅“关于蛋白质折叠的”，选项为空。","opts":[],"printed_answer":""},{"id":"n0337","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"选择","years":["08"],"q":"在已知序列信息的情况下，获取目的基因的最方便方法是","points":[{"k":"答案","t":"D。已知序列时可设计特异性引物，用聚合酶链反应（PCR）快速扩增目的基因，简便高效。"}],"note":"","opts":["A. 化学合成法","B. 基因组文库法","C. cDNA 文库法","D. 聚合酶链反应","E. 差异显示法"],"printed_answer":"D"},{"id":"n0338","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"选择","years":["08"],"q":"不会影响 mRNA 翻译的是","points":[{"k":"答案","t":"A。密码子改变只改变掺入的氨基酸种类，不阻断翻译过程本身；5′帽子、3′poly(A)尾与起始密码子均直接影响翻译起始和 mRNA 稳定性。"}],"note":"选项文字残缺（E 项仅“5′”），按语义取 A。","opts":["A. 无 ACG 但是有 GUA","B. 5′链子结构","C. 3′ poly(A)尾","D. 起始密码子 AU G","E. 5′"],"printed_answer":""},{"id":"n0339","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"选择","years":["08"],"q":"具有磷酸化 RNA 聚合酶 II 的结构域(CTD)的转录因子是","points":[{"k":"答案","t":"D。TFIIH 具 CDK7 激酶活性，磷酸化 RNA 聚合酶 II CTD 的 Ser5/Ser7，使聚合酶由起始转入延伸，并兼具解旋酶活性。"}],"note":"","opts":["A. TFIIA","B.TFIIB","C.TFIIF","D.TFIIH","E.TFIIE"],"printed_answer":""},{"id":"n0340","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["08"],"q":"原核生物启动子-","points":[{"k":"答案","t":"原卷题干与选项缺失，无法作答。通行考点：原核启动子含 −35 区（TTGACA）与 −10 区（TATAAT，Pribnow 盒），越接近共识序列启动子越强。"}],"note":"题干仅“原核生物启动子-”，选项为空。","opts":[],"printed_answer":""},{"id":"n0342","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"蛋白质的氨基酸排列顺序和核酸的排列顺序以及生物功能有怎样的关系？简述蛋白质的\n氨基酸顺序和他们的立体结构之间有什么关系","points":[{"k":"核酸决定氨基酸序列","t":"按中心法则，DNA 模板链以碱基互补先转录成 mRNA，mRNA 再翻译成多肽链，故核酸序列决定蛋白质的氨基酸序列。"},{"k":"并非一一对应","t":"转录与翻译过程中存在不同水平的加工，如 mRNA 的选择性剪接，因此蛋白质的氨基酸序列与其核酸序列并非一一对应。"},{"k":"一级决定高级结构","t":"不同氨基酸性质不同、成构象倾向不同，如丙氨酸易形成 α 螺旋，脯氨酸和甘氨酸易形成 β 转角；极性氨基酸易存在于表面，非极性氨基酸易折叠藏于内部。"},{"k":"高级结构决定功能","t":"血红蛋白 β 亚基 N 端第 6 位氨基酸突变即导致结构改变、功能丧失，引起镰刀型细胞贫血病。"},{"k":"序列功能总链条","t":"不同的氨基酸顺序形成不同的高级结构，从而赋予蛋白质不同的生物学功能。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"n0343","subj":"631","chap":"综合","type":"简答","years":[],"q":"简述关于酶专一性的学说","points":[{"k":"锁钥学说","t":"酶与底物结合时活性中心结构与底物结构必须吻合，如同锁与钥匙配合形成中间复合物，使底物分子的键被扭曲、变形而断裂，转变为产物。"},{"k":"锁钥学说的局限","t":"该学说认为酶结构固定不变；若如此，酶就不能在同一反应中同时与底物和产物的结构相匹配，难以解释逆反应。"},{"k":"诱导契合学说","t":"酶（含辅酶）与底物的构象原来并非完全吻合，底物与酶相碰时诱导酶的结构变得能与底物结合，形成中间复合物后引起底物发生化学变化而转为产物；该学说被大多数人认同。"},{"k":"补：过渡态互补","t":"酶与底物过渡态的互补性最强，结合能主要用于降低活化能，这是催化效率与专一性的本质。"}],"note":"口径：依据《真题分类》资料原文（原文只列锁钥学说与诱导契合学说）。补：过渡态互补为按教材口径补充，原资料未涉及。","opts":[],"printed_answer":"","ref":true},{"id":"n0344","subj":"631","chap":"综合","type":"简答","years":[],"q":"简述 RNA 和 DNA 二级结构的异同","points":[{"k":"相同点","t":"DNA 与 RNA 二级结构的形成都是通过氢键结合，符合碱基互补配对原则。"},{"k":"DNA双螺旋","t":"DNA 二级结构由两股链反向互补构成，进一步形成双螺旋，结构更加规整，极少出现单链区。"},{"k":"RNA单链回折","t":"RNA 一般为单链右手螺旋，或由单股链自身回折、链内互补部分构成局部双螺旋，不配对部分形成环状结构，单链区较多、形成很多环。"},{"k":"螺旋构型差异","t":"DNA 双螺旋分 A 型、B 型、Z 型，其中 A、B 型为右手螺旋、Z 型为左手螺旋；RNA 只有右手螺旋。"},{"k":"规整度差异","t":"DNA 双链配对严格、结构规整稳定；RNA 以局部双螺旋为主、单链环多，稳定性较低、更易被降解。"}],"note":"口径：依据《真题分类》资料原文（原文以表列差异，此处按点展开）；末点规整度与稳定性为对原文两行内容的归纳。","opts":[],"printed_answer":"","ref":true},{"id":"n0345","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"问答","years":[],"q":"核糖核酸（RNA）和蛋白质的生物合成有什么关系？试简述蛋白质生物合成的过程","points":[{"k":"mRNA作模板","t":"mRNA 从 DNA 处携带遗传信息、决定蛋白质的氨基酸序列，是蛋白质生物合成的直接模板，起「指导者」作用。"},{"k":"tRNA作转换器","t":"tRNA 可识别（解读）密码子并转运氨基酸，起「转换器」作用。"},{"k":"rRNA作装配者","t":"rRNA 与几十种蛋白质组成核糖体，为蛋白质合成的场所，起「装配者」作用；合成各环节都需不同类型的 RNA 参与。"},{"k":"活化与起始","t":"fMet 与 tRNA 经氨酰-tRNA 合成酶消耗 2 个高能磷酸键生成 fMet-tRNAf；30S 先与 IF-1、IF-3 结合并经 SD 序列结合 mRNA，IF-2-GTP 携 fMet-tRNAf 入 P 位，50S 加入、GTP 水解形成起始复合物。"},{"k":"延伸三步","t":"EF-Tu 携 GTP 送氨酰-tRNA 入 A 位（EF-Ts 使 EF-Tu·GDP 再生）；肽基转移酶催化 P 位氨基酸转到 A 位氨基上成肽键；EF-G 水解 GTP 使核糖体与 mRNA 移位，P 位空载 tRNA 入 E 位脱落。"},{"k":"终止与加工","t":"UAA、UAG、UGA 由 RF-1、RF-2 识别，以水为底物使肽链水解脱落，RF-3 水解 GTP 后各组分解离；新生肽链还需折叠，并切除 N 端 fMet、信号肽，形成二硫键、糖基化、磷酸化、连接辅基等。"}],"note":"口径：依据《真题分类》资料原文（RNA 三种作用＋原核合成五步，此处合并加工入终止点）。","opts":[],"printed_answer":"","ref":true},{"id":"n0346","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"问答","years":[],"q":"大肠杆菌含有 2000 种以上的蛋白质，为了分离它所表达的一个外源基因的产物并保持\n它的活性，常有很大的困难。但为了某种目的，请根据下列要求写出具体的方法。\n1) 利用溶解度差别进行分离\n2) 利用蛋白质分子大小进行分离\n3) 根据不同电荷进行分离\n4) 已制备有该产物的抗体进行分离\n5) 产物的浓缩\n6) 产物纯度的鉴定","points":[{"k":"盐析分级","t":"用硫酸铵分段盐析，不同饱和度沉淀不同蛋白；先低盐去杂蛋白，再提高盐浓度收集目的蛋白，沉淀可复溶。"},{"k":"按分子大小","t":"凝胶过滤（Sephadex、Superose）中大分子先出峰、小分子后出；也可用超滤、透析按截留分子量分级。"},{"k":"按电荷分离","t":"离子交换层析：DEAE（阴离子）或 CM（阳离子）交换，调 pH 与盐梯度洗脱；辅以等电聚焦、电泳。"},{"k":"亲和层析","t":"把抗体（或配体）偶联到琼脂糖，目的蛋白特异结合，改变 pH 或加竞争配体洗脱，一步可纯化上百倍。"},{"k":"浓缩与保存","t":"超滤（Amicon、PEG 浓缩）、反透析、冻干或硫酸铵沉淀复溶；全程低温、加缓冲液与保护剂防失活。"},{"k":"纯度鉴定","t":"SDS-PAGE 看单一条带、HPLC 或毛细管电泳看单峰、质谱定分子量、等电聚焦与活性测定证明构象正确。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0347","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":[],"q":"乳糖操纵子的调节机理是什么?","points":[{"k":"组成元件","t":"调节基因 lacI、启动子 P、操纵基因 O 与结构基因 lacZ/Y/A 组成，P 与 O 部分重叠。"},{"k":"无糖时阻遏","t":"lacI 产物为四聚体阻遏蛋白，结合 O 位点阻挡 RNA 聚合酶，操纵子关闭。"},{"k":"有糖时诱导","t":"异乳糖与阻遏蛋白结合，使其构象改变、亲和力下降而脱落，转录开启。"},{"k":"CAP 正调控","t":"葡萄糖缺乏使 cAMP 升高，cAMP-CAP 结合 CAP 位点促进聚合酶结合；葡萄糖充足则转录受抑（葡萄糖效应）。"},{"k":"双信号整合","t":"只有“有乳糖且无葡萄糖”时 lac 操纵子高效表达，实现碳源的优先与经济利用。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0348","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"简述蛋白质生物合成与核酸的关系","points":[{"k":"DNA 存信息","t":"DNA 是遗传信息的贮存者，基因序列经转录传为 mRNA，为蛋白质合成提供模板。"},{"k":"三类 RNA 分工","t":"mRNA 传信息、tRNA 运氨基酸、rRNA 组成核糖体并催化成肽，三者均由 DNA 转录而来。"},{"k":"密码与反密码","t":"mRNA 密码子与 tRNA 反密码子反向互补，保证氨基酸按序入位，简并性与摆动配对由此实现。"},{"k":"RNA 催化成肽","t":"肽键形成由 rRNA（肽基转移酶中心）催化，说明蛋白质合成既依赖核酸的信息也依赖其催化功能。"},{"k":"中心法则","t":"信息流为 DNA→RNA→蛋白质；逆转录与 RNA 复制说明 RNA 也可流向 DNA，但蛋白质不能反向决定核酸序列。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0349","subj":"631","chap":"综合","type":"简答","years":[],"q":"某酶可以作用于多种底物，如何用实验方法判断哪种底物是该酶的最适底物?","points":[{"k":"测 Km","t":"固定酶量，测各底物不同浓度下的初速度，用双倒数图或非线性拟合求 Km，Km 最小者亲和力最大。"},{"k":"算专一性常数","t":"由 Vmax 求 kcat=Vmax/[E]ₜ，再算 kcat/Km；该值最大者即为最适底物。"},{"k":"同条件比较","t":"必须在同一 pH、温度、缓冲液与同一批酶下平行测定，数据才可比。"},{"k":"竞争验证","t":"用竞争实验佐证：两种底物共存时，若其中一种显著抑制另一种的反应，说明它亲和力更高。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0350","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":[],"q":"简述基因定点突变的基本原理","points":[{"k":"酶切定位诱变","t":"选择合适的限制酶将基因切开，再插入或删除有关序列，可在切点处改造基因序列。"},{"k":"寡核苷酸诱变","t":"在单链噬菌体 DNA（单链 M13 载体）体外复制的基础上，用寡核苷酸指导的定位诱变技术改造基因序列。"},{"k":"PCR诱变","t":"设计突变引物，向目的 DNA 片段中引入碱基添加、删除或点突变等变化，目前主要用重叠延伸技术和大引物诱变法。"},{"k":"重叠延伸技术","t":"模板分别与引物对 1（正向诱变引物 FM 与反向引物 R2）、引物对 2（正向引物 F2 与反向诱变引物 RM）扩增出两种靶片段；变性后两片段在重叠区退火、补平缺口成全长双链，再用 F2 与 R2 扩增出带突变的全长 DNA。"},{"k":"大引物诱变法","t":"先用正向突变引物 M 与反向引物 R1 扩增模板产生双链大引物，与野生型 DNA 混合退火复性，再加入正向引物 F2 与其中一条互补链配对，扩增出带突变的双链 DNA。"},{"k":"测序验证","t":"两种 PCR 诱变最后都用 DNA 序列分析仪检测带突变的 DNA 片段，确认突变位点。"}],"note":"口径：依据《真题分类》资料原文。按资料「三条基本原理 + 两套实验过程 + 测序检测」重组为 6 点，引物代号 FM、R2、F2、RM、M、R1 照原文。","opts":[],"printed_answer":"","ref":true},{"id":"n0351","subj":"631","chap":"综合","type":"简答","years":[],"q":"简述抗体具有哪些性质?","points":[{"k":"结合特异性","t":"只与诱导其产生的抗原表位（或结构高度相似的表位）结合，是免疫诊断与靶向治疗的基础。"},{"k":"种类多样性","t":"可变区 CDR 基因重排与体细胞高频突变造就千万种抗体，可识别几乎任意结构。"},{"k":"结合亲和力","t":"抗原结合部位与表位以非共价键可逆结合，亲和力高；Fab 单价、IgG 双价。"},{"k":"结构特征","t":"四肽链 Y 形（2 重链+2 轻链），N 端可变区结合抗原，C 端恒定区决定类别与效应功能。"},{"k":"五类与效应","t":"IgG、IgM、IgA、IgD、IgE；可激活补体、调理吞噬、介导 ADCC，IgG 能通过胎盘。"},{"k":"异质性与免疫原","t":"免疫原性（异种抗体可诱导抗抗体）、不均一性，故诊断治疗多用单克隆抗体保证均一。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0352","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"问答","years":[],"q":"原核生物基因表达的调节有哪些机制，请一一列出，如果必要，可以用图示的方式表示\n出来。","points":[{"k":"操纵子调节","t":"功能相关的基因串联在染色体上组成操纵子，受调控基因调控而共同表达，为原核特有，如乳糖操纵子（负控诱导系统与正调节系统）、色氨酸操纵子（负控阻遏系统与弱化作用）、半乳糖及阿拉伯糖操纵子。"},{"k":"σ因子调节","t":"σ 因子本身活性受蛋白水解酶调控，也能被同源的抗 σ 因子失活，从而改变启动子识别。"},{"k":"辅助蛋白与抗终止","t":"细菌不含组蛋白，但存在组蛋白类似蛋白等非特异性 DNA 结合蛋白参与调控；转录因子可与启动子区结合而激活或抑制转录；抗终止因子如 NusA 可增加 RNA 聚合酶在终止子发夹结构处的暂停、促进抗终止。"},{"k":"翻译阻遏与ppGpp","t":"核糖体蛋白与 rRNA 的结合力大于与自身 mRNA 的结合力，多余游离时结合自身 mRNA 而阻遏翻译，保证 rRNA 与核糖体蛋白数量平衡；氨基酸饥饿时经 mRNA、未负载 tRNA 与 SF 蛋白催化形成 (p)ppGpp（魔斑、超级调控因子、警报素），抑制 RNA 聚合酶活性、降低 rRNA 合成，即严紧型控制。"},{"k":"mRNA水平因素","t":"原核 mRNA 半衰期很短；SD 序列影响与小亚基的结合强度，起始密码子以 AUG 起始效率最高，SD 序列到起始密码子以 4~10 个为宜（9 个最佳），稀有密码子多、二级结构复杂都会降低翻译效率，重叠基因可产生翻译偶联。"},{"k":"小RNA调节","t":"反义 RNA 与 mRNA 互补结合后阻断翻译，属翻译水平调控；核糖开关由适体域感受配体、表达平台调节表达，属顺式作用。"}],"note":"口径：依据《真题分类》资料原文（原按转录水平、翻译水平、小 RNA 三层列出，此处归并为六点）。","opts":[],"printed_answer":"","ref":true},{"id":"n0353","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"问答","years":[],"q":"在生物体内发生的复杂的生物化学过程中，酶除了具有催化功能外，还具有调节和控制\n各类生物化学反应速率，方向和途径的功能。请论述酶的调节作用有哪些方式。","points":[{"k":"酶量调节","t":"较慢：通过诱导或抑制酶的合成（涉及基因表达调控）以及调节酶的降解（如泛素化降解途径）改变酶量。"},{"k":"前馈与反馈","t":"底物等前一级代谢物影响后续酶活为前馈调节；产物等后一级代谢物影响前面酶活为反馈调节，结果可为正调节或负调节。"},{"k":"别构与抑制剂","t":"别构剂一般结合调节亚基进而影响催化亚基活性；抑制剂多为底物类似物可抑制酶活，激活剂多为金属离子可作辅基增强酶活；钙调蛋白等蛋白质也可作为激活或抑制蛋白。"},{"k":"共价修饰","t":"可逆共价修饰中最重要的是酶的磷酸化与去磷酸化；不可逆共价修饰如酶原激活，可形成活性中心、激活酶活性。"},{"k":"细胞水平调控","t":"通过酶与细胞膜结合状态的不同调整酶活性，并通过细胞区室的区域化分布调节酶促反应。"},{"k":"整体水平调控","t":"神经-激素调节分快调节（磷酸化改变现存酶活性）与慢调节（改变基因表达水平从而改变酶数量）；同工酶具组织特异性，在不同器官起不同作用，实现器官间协调。"}],"note":"口径：依据《真题分类》资料原文，按原文分子水平、细胞水平、整体水平三层次压缩为六点。","opts":[],"printed_answer":"","ref":true},{"id":"n0357","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"名词解释","years":["13"],"q":"转分化","points":[{"k":"定义","t":"一种已分化的细胞跨谱系转变为另一种分化细胞类型的现象，如成纤维细胞转为肌细胞、肝细胞转为胆管细胞。"},{"k":"转录因子重编程","t":"需关闭原谱系基因、开启新谱系基因，常经去分化或直接重编程，由 MyoD、C/EBP 等转录因子组合诱导，是再生医学的基础。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0359","subj":"880","chap":"第三章 氨基酸","type":"判断","years":["13"],"q":"氨基酸（甘氨酸特殊）的旋光性","points":[{"k":"答案","t":"正确。除甘氨酸外，组成蛋白质的氨基酸 α-碳均为手性碳，都有旋光性；甘氨酸侧链为 H，无手性、无旋光性。"}],"note":"题干残缺，按“除甘氨酸外氨基酸都有旋光性”理解。","opts":[],"printed_answer":""},{"id":"n0360","subj":"880","chap":"第四章 蛋白质","type":"判断","years":["13"],"q":"蛋白质与水和茚三酮反应的颜色","points":[{"k":"答案","t":"正确。蛋白质与肽同氨基酸一样含 α-氨基，与水合茚三酮共热生成蓝紫色，可用于显色定量与纸层析显色。"}],"note":"题干残缺，按“蛋白质与茚三酮显蓝紫色”理解。","opts":[],"printed_answer":""},{"id":"n0361","subj":"880","chap":"第五章 酶","type":"名词解释","years":["13"],"q":"active transport","points":[{"k":"定义","t":"指物质逆浓度梯度或电化学梯度跨膜转运的过程，该过程需要能量供给和载体蛋白的协助。"},{"k":"两类主动运输","t":"按能量来源分：一级主动运输依靠水解 ATP 供能，二级主动运输利用浓度梯度或电化学梯度供能，也称协同运输。"}],"note":"口径：依据《真题分类》资料原文（定义与两类分型）。","opts":[],"printed_answer":"","ref":true},{"id":"n0364","subj":"880","chap":"第十四章 氧化磷酸化","type":"名词解释","years":["13"],"q":"磷氧比值","points":[{"k":"概念定义","t":"即 P/O 比值：一对电子经呼吸链传递至氧时所产生的 ATP 分子数，也就是每消耗 1 mol 氧原子所产生 ATP 的摩尔数。"},{"k":"理论数值","t":"由泵出质子数与 ATP 合酶质子回流比决定，能量口径为 NADH 2.5、FADH₂ 1.5。"},{"k":"补：偶联判断","t":"实测 P/O 低于理论值提示解偶联或呼吸链损伤，比值是判断氧化与磷酸化偶联程度的指标。"}],"note":"口径：依据《真题分类》资料原文。资料只给定义（每消耗 1 mol 氧原子所产 ATP 摩尔数），2.5、1.5 与偶联判断一句为按能量口径补充（k 前标「补」）。","opts":[],"printed_answer":"","ref":true},{"id":"n0365","subj":"880","chap":"第三章 氨基酸","type":"考点","years":["13"],"q":"紫外吸收最大的氨基酸","points":[{"k":"答案","t":"色氨酸（Trp）。其吲哚环共轭体系最大，ε₂₈₀ 约 5700 M⁻¹cm⁻¹，远高于酪氨酸（约 1300）和苯丙氨酸（约 200）。"}],"note":"原卷选项缺失，按考点作答。","opts":[],"printed_answer":""},{"id":"n0366","subj":"880","chap":"第七章 核酸","type":"考点","years":["13"],"q":"几种核酸内切酶的作用位点;","points":[{"k":"答案","t":"原卷未给酶种与序列，无法定值。通行考点：限制性核酸内切酶识别 4~8 bp 回文序列并在其内或附近切割，如 EcoRI 切 G↓AATTC 产生黏性末端、SmaI 切 CCC↓GGG 产生平末端。"}],"note":"题干与选项缺失。","opts":[],"printed_answer":""},{"id":"n0367","subj":"880","chap":"第三章 氨基酸","type":"考点","years":["13"],"q":"给出几个氨基酸的等电点，选择合适的 pH 使 5 个氨基酸有四个带负电。","points":[{"k":"答案","t":"应选介于 5 个氨基酸 pI 之间、高于其中 4 个（最低者）pI 而低于最高 pI 的 pH：pH>pI 者带负电，故这 4 个带负电、余 1 个带正电。"}],"note":"原卷未给各氨基酸 pI 数值，只能给判定原则。","opts":[],"printed_answer":""},{"id":"n0368","subj":"880","chap":"第十六章 氨基酸代谢","type":"考点","years":["13"],"q":"一个环肽由胰蛋白酶切割产生（ ）条肽段","points":[{"k":"答案","t":"取决于环肽中 Lys/Arg 的数目。环肽无末端，切点数即肽段数，n 个精氨酸/赖氨酸位点被切开得 n 条肽段。"}],"note":"原卷未给肽的序列，无法算出具体条数。","opts":[],"printed_answer":""},{"id":"n0369","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"考点","years":["13"],"q":"细胞内各种 RNA 的含量排序（rRNA>tRNA>mRNA）","points":[{"k":"答案","t":"rRNA>tRNA>mRNA。rRNA 约占细胞 RNA 的 80%、tRNA 约 15%、mRNA 仅 1~5%。"}],"note":"","opts":[],"printed_answer":"rRNA>tRNA>mRNA"},{"id":"n0370","subj":"880","chap":"第十二章 糖原的合成与分解","type":"考点","years":["13"],"q":"CTP、ATP、GTP、UDPG 分别合成?","points":[{"k":"答案","t":"CTP 生成 CDP-胆碱、CDP-甘油二酯用于合成磷脂，并作为 RNA 前体；ATP、GTP 作为 RNA 前体并供能（GTP 参与蛋白质合成与糖异生）；UDPG 是糖原合成的活化葡萄糖供体。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0371","subj":"880","chap":"第十章 糖酵解 糖异生","type":"考点","years":["13"],"q":"TCA 循环中底物水平磷酸化产生:","points":[{"k":"答案","t":"琥珀酰 CoA→琥珀酸。由琥珀酰 CoA 合成酶催化，经底物水平磷酸化生成 1 分子 GTP（植物为 ATP），是 TCA 中唯一此类反应。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0372","subj":"880","chap":"第七章 核酸","type":"考点","years":["13"],"q":"哪些生物过程需要引物?","points":[{"k":"答案","t":"DNA 复制、逆转录与 PCR 需要引物：DNA 聚合酶不能从头起始，复制用 RNA 引物、逆转录用 tRNA 引物；RNA 聚合酶催化的转录不需要引物。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0373","subj":"880","chap":"第十二章 糖原的合成与分解","type":"考点","years":["13"],"q":"糖原分解后产生什么?","points":[{"k":"答案","t":"主要生成 1-磷酸葡萄糖（糖原磷酸化酶产物），脱支酶水解 α-1,6 键释出游离葡萄糖；肝糖原经葡萄糖-6-磷酸酶生成葡萄糖入血，肌糖原只生成 6-磷酸葡萄糖进入酵解。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0374","subj":"880","chap":"第十章 糖酵解 糖异生","type":"考点","years":["13"],"q":"哪种物质不含高能磷酸键?","points":[{"k":"答案","t":"不含高能键的是 3-磷酸甘油酸（及 6-磷酸葡萄糖等普通磷酸酯）；ATP、磷酸烯醇式丙酮酸、1,3-二磷酸甘油酸、磷酸肌酸均含高能磷酸键。"}],"note":"原卷选项缺失，按题型给出判断依据。","opts":[],"printed_answer":""},{"id":"n0375","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"考点","years":["13"],"q":"大肠杆菌复制酶是什么?","points":[{"k":"答案","t":"DNA 聚合酶 III。它是大肠杆菌复制叉上的主要延伸酶，聚合速度快并具 3′→5′外切校对活性；Pol I 负责切除 RNA 引物并填补缺口。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0376","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"简答","years":["13"],"q":"细菌中存在 RNA 转录后加工过程吗？","points":[{"k":"存在加工","t":"有。细菌 rRNA、tRNA 前体必须加工，mRNA 多数不需剪接但也存在内切修饰。"},{"k":"核酶切 5′端","t":"tRNA 前体 5′端由 RNase P（含催化 RNA）切去，3′端由 RNase E、RNase F 等外切酶修整。"},{"k":"加 CCA 末端","t":"3′端由 tRNA 核苷酸转移酶加上 CCA-OH，作为氨基酸连接位点。"},{"k":"碱基修饰","t":"甲基化、假尿苷化、脱氨等生成稀有碱基（m⁷G、D、ψ、I），保证识别与摆动配对。"},{"k":"rRNA 切割成熟","t":"16S、23S、5S rRNA 由长前体经 RNase Ⅲ 等切割成熟；mRNA 可被内切酶切割后再翻译。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0377","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"简答","years":["13"],"q":"载体的哪些特征能使其在真核生物细胞中顺利复制？","points":[{"k":"真核复制起点","t":"含 ARS（自主复制序列）/ori，能被起始识别复合物 ORC 识别，实现游离于染色体外的自主复制。"},{"k":"穿梭双功能","t":"同时含大肠杆菌 ori 与真核 ori、两套标记，可在大肠杆菌中扩增、在真核细胞中表达。"},{"k":"真核选择标记","t":"带 neo、hyg、puro 等抗性基因或营养缺陷标记，配合 G418 等筛选稳定转化子。"},{"k":"表达元件","t":"含多克隆位点、真核强启动子与增强子、poly(A) 加尾信号，保证插入基因正确转录与加工。"},{"k":"染色体元件","t":"人工染色体（YAC）另需着丝粒与端粒，才能随染色体稳定分配、复制时不丢失。"},{"k":"游离与整合两型","t":"附加型载体靠 ori 游离复制，整合型载体靠同源重组插入基因组，长期稳定但需筛选。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0378","subj":"880","chap":"第十七章 核苷酸代谢","type":"简答","years":["13"],"q":"嘌呤类似物和嘧啶类似物为什么可以作为抗癌药物或者抗病毒药物？","points":[{"k":"结构相似","t":"嘌呤或嘧啶类似物（6-MP、5-FU、阿糖胞苷、阿昔洛韦）与天然碱基结构相近，可被酶误认。"},{"k":"伪反馈抑制","t":"作为假底物竞争或伪反馈抑制，阻断嘌呤、嘧啶核苷酸的从头合成（如 6-MP 抑制 IMP→AMP/GMP）。"},{"k":"掺入终止链","t":"缺 3′-OH 或结构异常，掺入 DNA 后不能继续延伸，使复制终止、断裂（阿糖胞苷）。"},{"k":"抑制关键酶","t":"5-FU 转为 FdUMP 抑制胸苷酸合酶，dTTP 缺乏造成“胸苷酸饥饿”，DNA 合成受阻。"},{"k":"病毒选择性","t":"阿昔洛韦须经病毒胸苷激酶磷酸化才活化，故只杀伤感染细胞，对宿主毒性低。"},{"k":"抑制聚合酶","t":"抑制病毒 DNA 聚合酶或逆转录酶（AZT、拉米夫定），或使病毒基因组错误突变而灭活。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0379","subj":"880","chap":"第七章 核酸","type":"简答","years":["13"],"q":"大肠杆菌中合成 DAN 限制性内切酶的意义及其在细胞中的作用。","points":[{"k":"限制修饰系统","t":"细菌同时有内切酶与甲基化酶：自身 DNA 在识别位点被甲基化而受保护，外源 DNA 未甲基化即被切割。"},{"k":"防御外源 DNA","t":"降解侵入的噬菌体与质粒 DNA，是细菌的“免疫”机制，限制外源基因进入。"},{"k":"分子生物学工具","t":"特异识别回文序列并产生粘性或平末端，是基因克隆、酶切图谱、RFLP 与 DNA 重组的基础工具。"},{"k":"命名与分型","t":"按菌属、种、株命名（EcoRI），分 Ⅰ、Ⅱ、Ⅲ 型；Ⅱ 型只切割不修饰，识别序列专一，最常用。"},{"k":"与甲基化配对","t":"限制活性与修饰活性成对存在，缺失甲基化会自切致死，二者协同维持基因组稳定。"}],"note":"题干“DAN”为“DNA”笔误。","opts":[],"printed_answer":""},{"id":"n0380","subj":"880","chap":"第九章 生物膜","type":"简答","years":["13"],"q":"简述细胞膜流动镶嵌模型及其特点。","points":[{"k":"脂双层骨架","t":"磷脂双分子层为膜的基本骨架，亲水头朝两侧、疏水尾向内，构成通透屏障。"},{"k":"蛋白镶嵌","t":"膜蛋白以 α 螺旋跨膜或附着于表面，分内在（整合）与外在（周边）两类，可贯穿全膜。"},{"k":"膜具流动性","t":"脂分子与蛋白可侧向扩散，翻转极少；流动性受胆固醇、不饱和脂肪酸与温度调节。"},{"k":"不对称分布","t":"膜脂、膜蛋白与糖链在两侧分布不同，糖蛋白、糖脂的糖链只朝细胞外，是识别与信号的结构基础。"},{"k":"选择透过性","t":"脂溶性小分子自由扩散，离子与极性物靠通道、载体与泵转运，形成跨膜电化学梯度。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0381","subj":"880","chap":"第七章 核酸","type":"简答","years":["13"],"q":"简述双脱氧法测序的原理。","points":[{"k":"ddNTP 终止","t":"双脱氧核苷酸 3′ 位无羟基，掺入后不能形成下一个磷酸二酯键，链延伸就此终止。"},{"k":"四组反应","t":"模板+引物+DNA 聚合酶+dNTP，分四管各加少量 ddATP、ddTTP、ddGTP、ddCTP，得到以对应碱基结尾的片段群。"},{"k":"长度分离","t":"片段经变性聚丙烯酰胺凝胶电泳按长度分离，片段越短迁移越快。"},{"k":"读取序列","t":"由短到长读各条带所在管，即得新合成链 5′→3′ 序列，再互补得模板序列。"},{"k":"荧光自动化","t":"四色荧光 ddNTP 单管反应，毛细管电泳激光检测，实现自动读序（Sanger 法）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0382","subj":"880","chap":"第五章 酶","type":"简答","years":["13"],"q":"给出一种酶的两个数据，求该酶活力并设计一个实验测定该酶活。","points":[{"k":"活力公式","t":"活力（U）=ΔA/min×V总 ÷（ε×d×V样）；规定每分钟生成 1 μmol 产物（或 1 μg 酪氨酸）为 1 U。"},{"k":"比活力换算","t":"比活力=活力单位÷毫克蛋白；纯化倍数=各步比活力之比，回收率=各步总活力之比。"},{"k":"实验设计","t":"底物+缓冲液（固定 pH、温度、离子强度）预温，加酶启动，立即在特定波长连续测吸光度（如 340 nm 测 NADH）。"},{"k":"标准曲线","t":"用已知浓度产物作标准曲线，或用 NADH 的 ε=6220 L/(mol·cm) 换算，并扣除非酶空白。"},{"k":"初速度条件","t":"取反应初期线性段（底物消耗<5%~10%），验证活力与酶量、时间呈线性，保证测的是初速度。"}],"note":"原题为“给该酶的两个数据求活力并设计测定实验”，卷面未给出具体数值，故给通用公式与测定方案。","opts":[],"printed_answer":""},{"id":"n0383","subj":"880","chap":"第十六章 氨基酸代谢","type":"考点","years":["17"],"q":"婴儿患苯丙酮尿症缺什么酶(苯丙氨酸羟化酶(PAHD))","points":[{"k":"答案","t":"苯丙氨酸羟化酶（PAH）。该酶缺陷使苯丙氨酸不能羟化为酪氨酸，经旁路转氨生成苯丙酮酸由尿排出，形成苯丙酮尿症。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0384","subj":"880","chap":"第十七章 核苷酸代谢","type":"考点","years":["17"],"q":"嘌呤环的组成","points":[{"k":"答案","t":"嘌呤环由天冬氨酸（N1）、谷氨酰胺（N3、N9）、甘氨酸（C4、C5、N7）、CO₂（C6）与 N¹⁰-甲酰四氢叶酸（C2、C8）构成。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0386","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":["17"],"q":"EMP 途径磷酸化中间物的重要作用","points":[{"k":"滞留胞内","t":"葡萄糖进细胞即被磷酸化为 G-6-P，带负电不能自由透膜，底物不外漏、反应单向进行。"},{"k":"降低活化能","t":"磷酸化使底物带负电、更易与酶活性中心结合，降低异构化、烯醇化等步骤的活化能。"},{"k":"保留高能键","t":"1,3-二磷酸甘油酸与 PEP 的磷酸基以高能键存在，可经底物水平磷酸化转给 ADP，净得 2 ATP。"},{"k":"能量投资回收","t":"前段己糖激酶、PFK-1 消耗 2 ATP 使葡萄糖活化，后段回收 4 ATP，净产 2 ATP。"},{"k":"变构调节位点","t":"G-6-P、F-6-P、F-1,6-BP 等磷酸酯是 PFK-1 的效应物，磷酸化水平反映能量状态并调节流速。"},{"k":"碳流分叉枢纽","t":"G-6-P 可入磷酸戊糖途径、合成糖原；DHAP 可还原为甘油，3-磷酸甘油酸可生成丝氨酸。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0387","subj":"880","chap":"第三章 氨基酸","type":"简答","years":["17"],"q":"根据氨基酸的特性选择\n(1)具备二硫键的氨基酸是\n(2) pH=6 时，带正电荷的氨基酸\n(3)带负电荷的氨基酸","points":[{"k":"含二硫键","t":"半胱氨酸（Cys），侧链 -SH 可氧化形成胱氨酸的二硫键，稳定三级结构。"},{"k":"pH 6 带正电","t":"精氨酸（Arg，pKr≈12.5）、赖氨酸（Lys，pKr≈10.5）完全质子化带正电；组氨酸（His，pKr≈6.0）部分带正电。"},{"k":"pH 6 带负电","t":"天冬氨酸（Asp，pKr≈3.9）、谷氨酸（Glu，pKr≈4.3）侧链羧基解离为 -COO⁻，净带负电。"}],"note":"题干只给“根据氨基酸特性选择”，未列选项，按通行答案作答。","opts":[],"printed_answer":""},{"id":"n0388","subj":"880","chap":"第三章 氨基酸","type":"简答","years":["17"],"q":"(1)给出一段氨基酸序列进行蛋白质的翻译\n(2)翻译出来的氨基酸肽链是什么构象 β 转角\n(3)RNA 携带的 AUG 是什么氨基酸","points":[{"k":"按密码读序","t":"自起始密码 AUG 起，按 5′→3′ 每三个碱基一组查密码表，即得氨基酸序列。"},{"k":"β 转角","t":"由 4 个残基组成，常含 Pro、Gly，第 1 与第 4 残基间形成氢键，使肽链回折 180°，多位于蛋白表面。"},{"k":"AUG 为 Met","t":"AUG 编码甲硫氨酸（Met），同时是起始密码子；原核起始为甲酰甲硫氨酸（fMet）。"}],"note":"原卷未给出具体核苷酸序列，图（密码子表）为通用 mRNA 密码表，故按通法作答。","opts":[],"printed_answer":""},{"id":"n0389","subj":"880","chap":"第六章 维生素与辅酶","type":"简答","years":["17"],"q":"酶(1)活力测定的方法，机理\n(2)给一个图片，作图，并且答 5 小问题，2010 年原题","points":[{"k":"分光光度法","t":"最常用：NADH 在 340 nm 有吸收，连续监测吸光度变化，由 ΔA/min 换算产物生成速率。"},{"k":"其他测定法","t":"荧光法（灵敏）、滴定法（pH-stat 测酸释放）、同位素法、电化学或测压法测 O₂/CO₂。"},{"k":"取样终点法","t":"定时取样加终止剂（三氯乙酸）停反应，再用 Folin-酚、DNS 等显色比色，如蛋白酶测酪氨酸。"},{"k":"作图求参数","t":"以初速度 v 对 [S] 作矩形双曲线，或用 1/v 对 1/[S] 双倒数图求 Km 与 Vmax，并可判断抑制类型。"},{"k":"测定条件","t":"固定 pH、温度、离子强度，底物过量、酶量为限速，取线性初速度段并做空白校正。"}],"note":"原题“给一张图作 5 小问”的图缺失，按酶动力学常考五问（Km、Vmax、抑制类型、kcat、最适 pH）作答。","opts":[],"printed_answer":""},{"id":"n0391","subj":"880","chap":"第三章 氨基酸","type":"填空","years":["02"],"q":"氨基酸的等电点是指（ ）如 Asp 的 pK1(COOH)为 1.88，pK2（COOH）为 3.65，pK3（NH3⁺）为 9.60，其等电点是（ ）根据等电点的不同进行的氨基酸分离的电泳法是（ ）","points":[{"k":"答案","t":"氨基酸净电荷为零（正负电荷相等）时的溶液 pH；2.77；等电聚焦电泳。Asp 的 pI 取两性离子两侧 pK 的平均值，即 (pK1+pK2)/2=(1.88+3.65)/2≈2.77；各氨基酸 pI 不同，在 pH 梯度中分别停留在各自 pI 处而被分离。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0392","subj":"880","chap":"第三章 氨基酸","type":"填空","years":["02"],"q":"肌酸可形成（ ）在肌肉和神经的贮能中占有重要地位，肌酸的生物合成是由（ ）（ ）（ ）等氨基酸生物合成的","points":[{"k":"答案","t":"磷酸肌酸；甘氨酸、精氨酸、甲硫氨酸。肌酸经肌酸激酶接受 ATP 的磷酸生成磷酸肌酸，作为肌肉、神经的高能磷酸贮库；合成时甘氨酸与精氨酸（提供胍基）缩合生成胍乙酸，再由 S-腺苷甲硫氨酸提供甲基甲基化。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0393","subj":"880","chap":"第九章 生物膜","type":"填空","years":["02"],"q":"在生物膜内的蛋白质（ ）氨基酸朝向分子外侧，而（ ）氨基酸朝向分子内侧","points":[{"k":"答案","t":"极性（亲水）；非极性（疏水）。膜蛋白跨膜段以疏水残基朝向脂双层内部稳定存在，极性残基朝向膜两侧水相，形成跨膜通道或与膜外环境接触。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0394","subj":"880","chap":"第四章 蛋白质","type":"填空","years":["02"],"q":"抗体就是（ ）球蛋白","points":[{"k":"答案","t":"γ（丙种）球蛋白，即免疫球蛋白（Ig）。抗体电泳时主要位于 γ 球蛋白区，由两条重链和两条轻链经二硫键连接，N 端可变区识别抗原。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0395","subj":"880","chap":"第五章 酶","type":"填空","years":["02"],"q":"酶蛋白可被共价修饰，如酶原激活和磷酸化，此外还有（ ）（ ）（ ）等","points":[{"k":"答案","t":"腺苷酰化、尿苷酰化、ADP-核糖基化（甲基化、乙酰化、二硫键氧化还原亦属）。共价修饰酶通过可逆地加入或去掉小基团改变活性，是快速调节方式，级联放大效率高。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0396","subj":"880","chap":"第七章 核酸","type":"填空","years":["02"],"q":"核酸分子中含有（ ）所以在波长（ ）nm 处有强烈的吸收","points":[{"k":"答案","t":"嘌呤和嘧啶碱基的共轭双键；260。碱基共轭体系在 260 nm 有强紫外吸收，可用于核酸定量与纯度判断（A260/A280≈1.8 为纯 DNA）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0397","subj":"880","chap":"第十四章 氧化磷酸化","type":"填空","years":["02"],"q":"染色质中的 DNA 主要是以与（ ）结合成复合体的形式存在，并形成串珠的（ ）结构","points":[{"k":"答案","t":"组蛋白；核小体。8 个组蛋白（H2A、H2B、H3、H4 各 2）构成核心，DNA 绕 1.75 圈（约 146 bp），H1 结合连接区，串珠再盘绕成 30 nm 纤维。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0398","subj":"880","chap":"第十五章 脂类代谢","type":"填空","years":["02"],"q":"植物油在常温下一般为液态，这是因为他们含有大量的（ ）的缘故","points":[{"k":"答案","t":"不饱和脂肪酸（油酸、亚油酸、亚麻酸等）。顺式双键使碳链弯曲、分子间排列疏松，熔点低，故常温下为液态；动物脂肪以饱和脂肪酸为主，常温为固态。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0399","subj":"880","chap":"综合","type":"填空","years":["02"],"q":"一个 ATP 分子含有（ ）个高能磷酸键","points":[{"k":"答案","t":"2 个。ATP 为腺苷—P～P～P，α-β 与 β-γ 之间为高能磷酸键，末端磷酸水解约释放 30.5 kJ/mol；去掉末端磷酸成 ADP，再去一个成 AMP。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0404","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":["02"],"q":"写出尿素循环，并简述其生理意义","points":[{"k":"循环定义","t":"尿素循环是将含氮化合物分解产生的氨（游离氨和天冬氨酸的氨）转变为尿素的过程，因中间产物鸟氨酸可循环再生，又称鸟氨酸循环，是脊椎动物肝脏中的代谢循环，也是人体主要的排氨方式。"},{"k":"转氨与氧化脱氨","t":"肝细胞胞浆中氨基酸经转氨作用把氨基交给 α-酮戊二酸生成谷氨酸，谷氨酸透过线粒体膜进入基质，在谷氨酸脱氢酶作用下氧化脱氨，生成 1 分子 NADH 和 1 分子游离氨。"},{"k":"氨甲酰磷酸与瓜氨酸","t":"游离氨与 TCA 产生的 1 分子 CO₂、2 分子 ATP 在氨甲酰磷酸合成酶Ⅰ催化下生成氨甲酰磷酸，再经鸟氨酸转氨甲酰酶与鸟氨酸生成瓜氨酸；瓜氨酸离开线粒体进入胞浆。"},{"k":"精氨酸代琥珀酸","t":"胞浆中瓜氨酸以 ATP 供能，在精氨酸代琥珀酸合成酶催化下与天冬氨酸（另一氨基的供体）缩合成精氨酸代琥珀酸。"},{"k":"裂解与水解","t":"经裂解酶催化裂解生成 1 分子精氨酸与 1 分子延胡索酸（延胡索酸入 TCA，经苹果酸脱氢生成 NADH，从而沟通尿素循环与 TCA），精氨酸再由精氨酸酶水解生成尿素并再生鸟氨酸。"},{"k":"调控与生理意义","t":"限速酶为 CPSⅠ，可被 N-乙酰谷氨酸别构激活：氨基酸脱氨加快时谷氨酸升高、刺激 N-乙酰谷氨酸合成，激活 CPSⅠ 乃至整个循环；意义是维持正常血氨水平、把有毒氨转为尿素排出，防止高氨危害中枢神经系统，合成 1 分子尿素耗 3 ATP、4 个高能磷酸键。"}],"note":"口径：依据《真题分类》资料原文。原文把 NADH 直接列于裂解步骤，此处按「延胡索酸入 TCA 后生成 NADH」的正确表述写；末句 3 ATP／4 个高能磷酸键为教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0405","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":["02"],"q":"什么是一碳单位？一碳单位有哪些？氨基酸与一碳单位之间有何关系？","points":[{"k":"一碳单位定义","t":"指某些氨基酸分解代谢过程中产生的仅含一个碳原子的基团；特点是不能以游离形式存在，必须以四氢叶酸（FH₄）为载体，因此 CO₂ 不属于一碳单位。"},{"k":"按氧化态分类","t":"甲醇（-2）：甲基、羟甲基；甲醛（0）：亚甲基；甲酸（+2）：次甲基、甲酰基、亚胺甲基。"},{"k":"氨基酸提供者","t":"丝氨酸、甘氨酸可产生 N⁵,N¹⁰-CH₂-FH₄；组氨酸可产生 N⁵=CH-NH-FH₄；色氨酸可产生 N¹⁰-CHO-FH₄；甲硫氨酸经 S-腺苷甲硫氨酸提供“活性甲基”，也可提供一碳单位。"},{"k":"相互转变","t":"各种一碳单位之间可相互转变，并以四氢叶酸为载体。"},{"k":"与核酸代谢","t":"一碳单位参与体内嘌呤和嘧啶的合成，联系氨基酸与核酸代谢，是体内多种甲基化作用的枢纽。"}],"note":"口径：依据《真题分类》资料原文。旧稿写“五种形式”，原文按氧化态列 6 种（甲基、羟甲基、亚甲基、次甲基、甲酰基、亚胺甲基），已照录。","opts":[],"printed_answer":"","ref":true},{"id":"n0406","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"名词解释","years":["17"],"q":"密码子的简并性","points":[{"k":"定义","t":"一种氨基酸可由两个或两个以上不同密码子编码的现象，除 Met 与 Trp 外多数氨基酸都有多个密码子。"},{"k":"摆动假说容错","t":"同义密码子多在第 3 位碱基不同，按摆动假说配对可减少突变对蛋白质的影响、提高翻译容错；不同物种存在密码子使用偏好。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0407","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"名词解释","years":["17"],"q":"PCR","points":[{"k":"定义","t":"聚合酶链式反应：体外以 DNA 为模板，用一对特异引物和耐热 DNA 聚合酶，经变性、退火、延伸循环使目的片段指数扩增。"},{"k":"指数扩增 2ⁿ","t":"每轮循环产物约加倍，n 轮后扩增约 2ⁿ 倍；关键要素为模板、引物、dNTP、Mg²⁺、Taq 酶与温度程序。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0408","subj":"880","chap":"第三章 氨基酸","type":"判断","years":["17"],"q":"一种特定的氨基酸序列通常能决定几种不同的稳定的特定三维结构。","points":[{"k":"答案","t":"×。按 Anfinsen 原理，一级结构决定唯一的天然构象，一种序列在给定条件下通常只折叠成一种最稳定的三维结构。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0409","subj":"880","chap":"第十五章 脂类代谢","type":"判断","years":["17"],"q":"脂肪酸经 β 氧化作用而分解的反应都是可逆的，所以体内脂肪酸的合成是经过 β 氧化作用的逆过程进行的。","points":[{"k":"答案","t":"×。β 氧化第一步酰基 CoA 脱氢（产 FADH₂）不可逆，整条途径不能逆行；脂肪酸合成走丙二酰 CoA 途径，发生于胞质，酶系、酰基载体（ACP）与还原剂（NADPH）均不同。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0410","subj":"880","chap":"第四章 蛋白质","type":"判断","years":["17"],"q":"核酶与蛋白质酶的差别之一在于核酶不怕变性。","points":[{"k":"答案","t":"√。核酶本质是 RNA，结构靠碱基配对的氢键维持，热变性后缓慢冷却可复性，不出现蛋白质那样凝集沉淀的不可逆变性。"}],"note":"若强调 RNA 在高温下发生磷酸二酯键水解而彻底失活，个别教材判为错误；主流口径按可复性判 √。","opts":[],"printed_answer":""},{"id":"n0411","subj":"880","chap":"第五章 酶","type":"判断","years":["17"],"q":"别构酶又称变构酶，催化反应物从一个构型变成另一种同分异构体。","points":[{"k":"答案","t":"×。别构酶是效应物结合调节部位、改变酶构象从而改变活性的调节酶；催化同一分子构型或同分异构体互变的是异构酶，与别构调节无关。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0412","subj":"880","chap":"第七章 核酸","type":"判断","years":["17"],"q":"同一个带有 poly(T)的亲和层析柱，可以方便地从核酸提取液中分离出真核和原核细胞的 mRNA","points":[{"k":"答案","t":"×。oligo(dT)-纤维素靠 mRNA 的 poly(A) 尾配对；真核 mRNA 有 poly(A)，原核 mRNA 一般没有，故同一柱子只能方便地分离真核 mRNA。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0413","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"判断","years":["17"],"q":"DNA 复制，转录，重组，损伤修复和翻译都依赖于特定的 watson-crick 碱基对","points":[{"k":"答案","t":"√。复制、转录、反转录、重组与损伤修复都靠碱基互补配对识别模板；翻译中密码子与反密码子配对亦以 Watson-Crick 配对为基础（第三位可摇摆）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0414","subj":"880","chap":"第十四章 氧化磷酸化","type":"判断","years":["17"],"q":"抗生素对呼吸链的毒性要比鱼藤酮大，是因为它与呼吸链的接合能力更强。","points":[{"k":"答案","t":"×。毒性差异源于作用位点不同：鱼藤酮阻断 NADH 脱氢酶到泛醌，抗霉素 A 阻断 Cyt b 到 c₁，越靠后阻断、被跨越的质子泵越多，ATP 生成受阻越彻底，与“结合力更强”无关。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0415","subj":"880","chap":"第十章 糖酵解 糖异生","type":"判断","years":["17"],"q":"在糖酵解过程中，因葡萄糖和果糖的活化都需要 ATP,故 ATP 浓度高时，糖酵解的速度加快。","points":[{"k":"答案","t":"×。ATP 是己糖激酶和磷酸果糖激酶-1（PFK-1）的别构抑制剂，ATP 升高时糖酵解减慢；只有 AMP、ADP 升高（能荷降低）才使糖酵解加速。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0416","subj":"880","chap":"第二十一章 细胞代谢与基因表达","type":"判断","years":["17"],"q":"腺苷酸环化酶基因的缺失将导致细菌在有葡萄糖的情况下 lac 操纵子表达水平的提高。","points":[{"k":"答案","t":"×。腺苷酸环化酶缺失使 cAMP 无法生成，CAP-cAMP 复合物不能形成，lac 操纵子即使在没有葡萄糖时也难以高水平转录，表达水平下降而非提高。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0417","subj":"880","chap":"第七章 核酸","type":"判断","years":["17"],"q":"在嘌呤核苷酸的从头合成途径中，嘌呤碱基的 N3 和 N9 均来自于 GLN 的氨基 N.","points":[{"k":"答案","t":"√。嘌呤环 N3、N9 均来自谷氨酰胺的酰胺氮；N1 来自天冬氨酸，C2、C8 来自一碳单位（甲酸盐），C4、C5、N7 来自甘氨酸，C6 来自 CO₂。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0418","subj":"880","chap":"第三章 氨基酸","type":"简答","years":["17"],"q":"(1)给出一段氨基酸序列进行蛋白质的翻译\n(2)翻译出来的氨基酸肽链是什么构象?","points":[{"k":"起始密码定位","t":"从 mRNA 5′端扫描，以第一个 AUG 为起始密码子，确定开放读框，按 5′→3′ 方向每 3 个碱基读一组。"},{"k":"查密码子表","t":"逐个三联体对照遗传密码表写出对应氨基酸；UAA、UAG、UGA 为终止密码，不编码氨基酸，翻译在此停止。"},{"k":"肽链一级结构","t":"所得为氨基酸自 N 端到 C 端线性排列的肽链，残基间以肽键相连，这就是蛋白质的一级结构。"},{"k":"自发折叠成构象","t":"肽链在水相中自发折叠：局部盘绕成 α-螺旋、伸展成 β-折叠等二级结构，再盘曲为三级结构，构象由序列决定。"}],"note":"原卷未给出具体核苷酸序列，无法列出具体氨基酸，只能给出翻译方法与所得肽链的构象层次。","opts":[],"printed_answer":""},{"id":"n0419","subj":"880","chap":"第十五章 脂类代谢","type":"考点","years":["25"],"q":"前列腺素是什么。","points":[{"k":"答案","t":"前列腺素是花生四烯酸经环加氧酶（COX）生成的二十碳不饱和脂肪酸衍生物，属类花生酸（局部激素），在合成部位就近起旁分泌/自分泌作用，不在细胞内储存。"}],"note":"原卷选项缺失，按教材定义作答。","opts":[],"printed_answer":""},{"id":"n0420","subj":"880","chap":"第四章 蛋白质","type":"考点","years":["25"],"q":"肌红蛋白的氧解离曲线相关表述。","points":[{"k":"答案","t":"肌红蛋白只有单个血红素、无亚基间协同，氧解离曲线为矩形双曲线；P50 仅 1～3 mmHg，远低于血红蛋白，故低氧分压下仍保持高亲和力，主要起肌内储氧作用。"}],"note":"原卷选项缺失，无法核对具体选项。","opts":[],"printed_answer":""},{"id":"n0421","subj":"880","chap":"第十章 糖酵解 糖异生","type":"考点","years":["25"],"q":"糖降解的终产物。","points":[{"k":"答案","t":"糖酵解终产物是丙酮酸，净得 2 ATP 与 2 NADH；无氧时丙酮酸被还原为乳酸，酵母中则脱羧生成乙醇和 CO₂。"}],"note":"原卷选项缺失；若题干指无氧降解，答案应为乳酸。","opts":[],"printed_answer":""},{"id":"n0422","subj":"880","chap":"第十章 糖酵解 糖异生","type":"考点","years":["25"],"q":"糖有氧氧化的产物。","points":[{"k":"答案","t":"终产物为 CO₂ 和 H₂O，同时释放能量生成 30～32 分子 ATP；丙酮酸、乙酰 CoA、柠檬酸都是中间产物而非终产物。"}],"note":"原卷选项缺失。","opts":[],"printed_answer":""},{"id":"n0423","subj":"880","chap":"综合","type":"考点","years":["25"],"q":"分离技术中，大分子和小分子哪一个先出来。","points":[{"k":"答案","t":"大分子先出。凝胶过滤（分子筛）中，大分子不能进入凝胶珠内孔隙，只走颗粒外水体积，路程短、先被洗脱；小分子进入孔隙、流程长，后出。"}],"note":"原卷选项缺失；此处按凝胶过滤层析作答，若为超滤或透析则结论方向相同。","opts":[],"printed_answer":""},{"id":"n0424","subj":"880","chap":"第七章 核酸","type":"考点","years":["25"],"q":"DNA 复制相关错误说法判断。","points":[{"k":"答案","t":"错误说法常见为“复制是全保留的”“新链沿 3'→5' 合成”“复制不需要引物”。正确口径：DNA 复制为半保留、双向、半不连续，新链只能沿 5'→3' 延伸，须由引物酶先合成 RNA 引物。"}],"note":"原卷选项缺失，无法确定具体错项，按常见错误表述给出。","opts":[],"printed_answer":""},{"id":"n0425","subj":"880","chap":"第七章 核酸","type":"考点","years":["25"],"q":"DNA 聚合酶与后随链、冈崎片段相关表述。","points":[{"k":"答案","t":"后随链模板方向与解旋叉前进方向相反，只能分段不连续合成冈崎片段：引物酶合成 RNA 引物，DNA 聚合酶Ⅲ 延伸，聚合酶Ⅰ 切除引物并填补缺口，DNA 连接酶封口成完整链。"}],"note":"原卷选项缺失。","opts":[],"printed_answer":""},{"id":"n0426","subj":"880","chap":"第五章 酶","type":"考点","years":["25"],"q":"哪一种抑制剂不会改变酶的最适底物浓度或表观 Km。","points":[{"k":"答案","t":"非竞争性抑制剂。它结合 E 或 ES 的调节部位，不改变酶与底物的亲和力，故表观 Km 不变，只降低 Vmax；竞争性抑制 Km 增大，反竞争性抑制 Km 减小。"}],"note":"原卷选项缺失。","opts":[],"printed_answer":""},{"id":"n0427","subj":"880","chap":"第三章 氨基酸","type":"考点","years":["25"],"q":"哪种氨基酸有缓冲作用。","points":[{"k":"答案","t":"组氨酸。其咪唑基 pKa≈6.0，接近生理 pH，既可作质子供体又可作受体，缓冲能力最强；半胱氨酸的巯基、酪氨酸的酚羟基也有一定缓冲作用。"}],"note":"原卷选项缺失。","opts":[],"printed_answer":""},{"id":"n0428","subj":"880","chap":"第一章 糖类","type":"考点","years":["25"],"q":"什么糖不具备还原性，不能生成糖脎。","points":[{"k":"答案","t":"蔗糖。它由葡萄糖与果糖以 α1→β2 糖苷键相连，两个半缩醛（酮）羟基都参与成键，无游离羰基，故为非还原糖，不能还原 Fehling 试剂，也不生成糖脎。"}],"note":"原卷选项缺失。","opts":[],"printed_answer":""},{"id":"n0433","subj":"880","chap":"第十章 糖酵解 糖异生","type":"考点","years":["25"],"q":"糖代谢相关限速酶（其中哪个限速酶在线粒体膜上）。","points":[{"k":"答案","t":"糖酵解的三个限速酶己糖激酶、磷酸果糖激酶-1（PFK-1）、丙酮酸激酶都在胞质；在线粒体一侧的限速酶是丙酮酸羧化酶（糖异生）与柠檬酸合酶（三羧酸循环）。若问结合在线粒体膜上的酶，则为己糖激酶（经 VDAC 锚定于外膜）。"}],"note":"原卷选项缺失；“线粒体膜上”表述含混，若指线粒体区室则答案为丙酮酸羧化酶，需按卷面选项取舍。","opts":[],"printed_answer":""},{"id":"n0434","subj":"880","chap":"第四章 蛋白质","type":"考点","years":["25"],"q":"哪种情况可使血红蛋白（Hb）氧解离曲线右移?","points":[{"k":"答案","t":"pH 降低（H⁺ 升高）、pCO₂ 升高、温度升高、2,3-BPG 浓度升高均使曲线右移（波尔效应），即亲和力下降、向组织释氧增多；反向变化使曲线左移。"}],"note":"原卷选项缺失；具体选项应从上述右移因素中选。","opts":[],"printed_answer":""},{"id":"n0435","subj":"880","chap":"第四章 蛋白质","type":"考点","years":["25"],"q":"肌红蛋白/血红蛋白的氧解离曲线形状.","points":[{"k":"答案","t":"肌红蛋白为矩形双曲线（单一血红素、无协同效应）；血红蛋白为 S 形曲线（四个亚基协同效应），P50 约 26 mmHg，故肺部高亲和结合氧、组织低氧时高效释氧。"}],"note":"原卷选项缺失。","opts":[],"printed_answer":""},{"id":"n0436","subj":"880","chap":"第七章 核酸","type":"考点","years":["25"],"q":"转录过程中，催化 RNA 合成的酶是","points":[{"k":"答案","t":"DNA 依赖的 RNA 聚合酶。它以 DNA 为模板、NTP 为底物，沿 5'→3' 方向合成 RNA，起始不需引物，但需 σ 因子（原核）识别启动子。"}],"note":"原卷选项缺失。","opts":[],"printed_answer":""},{"id":"n0437","subj":"880","chap":"第七章 核酸","type":"考点","years":["25"],"q":"选 Tm 最高的","points":[{"k":"答案","t":"GC 含量最高（且链最长）的片段 Tm 最高。G≡C 有 3 个氢键，比 A=T 更稳定，Tm 可用 69.3+0.41×GC%（离子强度 0.15 mol/L）估算。"}],"note":"原卷选项缺失，无法指明具体选项。","opts":[],"printed_answer":""},{"id":"n0438","subj":"880","chap":"第四章 蛋白质","type":"考点","years":["25"],"q":"用凯氏定氮法测得某样品含氮量，则该样品中蛋白质含量?","points":[{"k":"答案","t":"蛋白质含量 = 含氮量 × 6.25。蛋白质平均含氮 16%，换算系数 100/16=6.25；凯氏定氮测的是总氮，若样品含非蛋白氮会高估。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0439","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["25"],"q":"试结合镰刀型细胞贫血症，说明蛋白质一级结构与生物学功能之间的关系。","points":[{"k":"单个残基替换","t":"HbS 的 β 链第 6 位谷氨酸（亲水带负电）被缬氨酸（疏水）取代，一级结构只差一个氨基酸。"},{"k":"疏水斑块暴露","t":"分子表面出现疏水侧链，脱氧构象下与相邻 HbS 分子的疏水口袋结合，聚合成长纤维。"},{"k":"红细胞镰变","t":"纤维束牵拉使红细胞变成镰刀形，变形性下降，易破裂溶血并阻塞微血管。"},{"k":"功能随之改变","t":"携氧与释氧能力下降，出现溶血性贫血、疼痛危象与器官缺血；杂合子反获抗疟优势。"},{"k":"序列决定构象","t":"一级结构决定空间构象、构象决定功能；序列中一个残基改变即可引起构象与功能的重大变化。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0440","subj":"880","chap":"第七章 核酸","type":"简答","years":["25"],"q":"简述沃森—克里克提出的 DNA 双螺旋结构模型的主要特点。","points":[{"k":"反向平行双链","t":"两条多核苷酸链围绕同一中心轴形成右手螺旋，一条 5′→3′、另一条 3′→5′，反向平行。"},{"k":"骨架在外碱基在内","t":"脱氧核糖-磷酸骨架居螺旋外侧，碱基对居内侧，螺旋直径 2 nm。"},{"k":"碱基互补配对","t":"A 与 T 之间 2 个氢键，G 与 C 之间 3 个氢键；嘌呤配嘧啶，保证螺旋直径恒定。"},{"k":"螺距与堆积力","t":"每 10 个碱基对上升一圈，螺距 3.4 nm，相邻碱基对间距 0.34 nm，碱基堆积力与氢键共同维持稳定。"},{"k":"大小沟识别位点","t":"螺旋表面形成大沟与小沟，是蛋白质特异识别 DNA 的部位，为复制、转录调控提供结构基础。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0441","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["25"],"q":"什么是蛋白质的二级结构？蛋白质二级结构主要有哪些类型？","points":[{"k":"二级结构定义","t":"指蛋白质分子中主链骨架原子的局部空间排布，不涉及侧链构象，主要靠主链间的氢键维持。"},{"k":"α-螺旋","t":"主链沿螺旋轴盘绕，每圈 3.6 个残基、上升 0.54 nm，第 n 与 n+4 位残基间形成氢键，侧链伸向外侧。"},{"k":"β-折叠","t":"肽段充分伸展，多条肽链平行或反平行排列成片层，链间形成氢键，侧链交替伸向片层上下。"},{"k":"β-转角","t":"由 4 个氨基酸残基构成，第一个残基的 C=O 与第四个残基的 N-H 形成氢键，使肽链回折 180°。"},{"k":"无规卷曲","t":"无确定规律的松散肽段，赋予蛋白质柔性，常位于功能部位；相邻二级结构单元还可聚成 αα、βαβ 等模体。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0442","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["25"],"q":"现有一蛋白质混合物，请分别根据以下四种性质设计分离方法，并各举一具体例子说明其原理：\n（1）分子量大小\n（2）溶解度差异\n（3）所带电荷不同\n（4）生物亲和力不同","points":[{"k":"按分子量—凝胶过滤","t":"用葡聚糖凝胶（Sephadex）层析，大分子不能进入凝胶网孔、先被洗出，小分子进入网孔后洗出，按大小分开。"},{"k":"按溶解度—盐析","t":"加硫酸铵使蛋白质水化层脱水、表面电荷被中和而沉淀；不同蛋白质沉淀所需盐浓度不同，如球蛋白与清蛋白分段盐析。"},{"k":"按电荷—离子交换","t":"用 DEAE-纤维素（阴离子交换）或 CM-纤维素（阳离子交换），不同等电点的蛋白质结合力不同，用盐浓度或 pH 梯度洗脱。"},{"k":"按亲和力—亲和层析","t":"把配体（底物类似物、抗原、Ni²⁺）固定于载体，目的蛋白特异结合、杂蛋白洗去，再改变条件洗脱，如镍柱纯化 His 标签蛋白。"},{"k":"电泳补充手段","t":"SDS-PAGE 按分子量分离、等电聚焦按等电点分离，双向电泳可同时按两种性质分离并鉴定纯度。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0443","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"简答","years":["25"],"q":"简述 PCR 技术的原理、基本流程及其主要应用。","points":[{"k":"原理是模拟复制","t":"以单链 DNA 为模板，引物提供 3′-OH，耐热 DNA 聚合酶按碱基互补沿 5′→3′ 延伸，体外模拟半保留复制，指数扩增。"},{"k":"高温变性","t":"94~95 ℃ 使双链间氢键断裂，模板解成单链。"},{"k":"低温退火","t":"降至 50~65 ℃，一对引物与模板两侧互补序列特异结合。"},{"k":"适温延伸","t":"72 ℃ 左右，Taq DNA 聚合酶以 dNTP 为原料，从引物 3′端合成新链。"},{"k":"循环与应用","t":"三步循环 25~35 次，目的片段按 2ⁿ 扩增；用于基因克隆、突变与病原体检测、法医鉴定、实时定量 PCR。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0444","subj":"880","chap":"第七章 核酸","type":"简答","years":["25"],"q":"已知一段 DNA 序列:","points":[{"k":"辨认模板链","t":"按习惯 5′→3′ 写出的序列为编码链（有意义链），其互补链 3′→5′ 才是转录模板。"},{"k":"写出 mRNA","t":"mRNA 序列与编码链一致，只需把 T 全部换成 U，方向仍为 5′→3′。"},{"k":"翻译得肽链","t":"自起始密码 AUG 起按三联体查密码子表，写出 N 端到 C 端氨基酸序列，遇终止密码停止。"},{"k":"步骤通用","t":"凡给 DNA 序列求肽链，均按“定模板→写 mRNA→查密码子”三步作答，注意读框与方向。"}],"note":"原卷的 DNA 序列及小问缺失（题干只有一句），无法给出具体碱基与氨基酸，只能给通用解题步骤。","opts":[],"printed_answer":""},{"id":"n0445","subj":"880","chap":"第十二章 糖原的合成与分解","type":"简答","years":["25"],"q":"为什么糖原分解主要采用磷酸解而不是水解？请从能量利用和代谢意义等方面加以说明。","points":[{"k":"磷酸解产物","t":"糖原磷酸化酶催化糖原非还原端 α-1,4 糖苷键磷酸解，直接生成 1-磷酸葡萄糖（G-1-P），不消耗 ATP。"},{"k":"省一个 ATP","t":"若水解成游离葡萄糖，入细胞后需己糖激酶磷酸化，消耗 1 分子 ATP；磷酸解产物已带磷酸基，相当于净省 1 个 ATP。"},{"k":"产物不外漏","t":"G-1-P 带负电荷，不能自由通过细胞膜，就地被利用，避免葡萄糖外逸，保证肌细胞快速供能。"},{"k":"变位后入糖酵解","t":"G-1-P 经磷酸葡萄糖变位酶转为 6-磷酸葡萄糖，进入糖酵解；在肝脏再由葡萄糖-6-磷酸酶脱磷酸补充血糖。"},{"k":"代谢意义","t":"应激时能迅速动员、供能效率高，且不产生大量游离葡萄糖、不升高细胞内渗透压。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0446","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["25"],"q":"什么是酮体？酮体包括哪几种？其合成原料是什么？酮体具有什么生理意义？","points":[{"k":"酮体定义","t":"脂肪酸在肝脏氧化不完全时生成的中间产物，包括乙酰乙酸、β-羟丁酸和丙酮三种，经血液运至肝外组织氧化。"},{"k":"只在肝内合成","t":"肝细胞线粒体含 HMG-CoA 合酶，是唯一能生成酮体的组织；肝外组织缺此酶，只能利用不能生成。"},{"k":"原料为乙酰CoA","t":"两分子乙酰 CoA 缩合成乙酰乙酰 CoA，再与乙酰 CoA 生成 HMG-CoA，裂解为乙酰乙酸，进而还原成 β-羟丁酸、脱羧成丙酮。"},{"k":"生理意义供能","t":"长期饥饿、糖尿病时供能，脑、心、骨骼肌可大量利用，减少葡萄糖消耗与蛋白质分解。"},{"k":"过多致酮症","t":"生成超过利用即酮血症、酮尿症；酮体为酸性，堆积引起酮症酸中毒。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0447","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":["25"],"q":"人体内有哪几种脱氨基作用？请简述其过程及生理意义。","points":[{"k":"氧化脱氨基","t":"L-谷氨酸脱氢酶催化谷氨酸脱氢、加水生成 α-酮戊二酸和 NH₃，是肝、肾最主要的脱氨方式，需 NAD⁺/NADP⁺。"},{"k":"转氨基作用","t":"转氨酶（ALT、AST）以磷酸吡哆醛为辅酶，把氨基酸的氨基转移给 α-酮酸，生成新氨基酸和 α-酮酸，本身不产生游离氨。"},{"k":"联合脱氨基","t":"先转氨基生成谷氨酸，再由谷氨酸脱氢酶氧化脱氨，是体内氨基酸脱氨的主要方式，肝、肾中旺盛。"},{"k":"嘌呤核苷酸循环","t":"肌肉中氨基酸经转氨把氨基交给天冬氨酸，再经腺苷酸脱氨酶释放 NH₃，适合谷氨酸脱氢酶活性低的组织。"},{"k":"生理意义","t":"生成的 α-酮酸可氧化供能或转变为糖、脂；NH₃ 经尿素循环解毒，或以谷氨酰胺形式运输。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0448","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["25"],"q":"关于 SDS-PAGE 电泳：","points":[{"k":"变性掩盖电荷","t":"SDS 为阴离子、带很高负电荷，可掩盖不同蛋白质间原有的电荷差别；SDS 又是变性剂，破坏蛋白质分子中的氢键与疏水作用，使大多数蛋白质伸展成同样的棒状。"},{"k":"按质量分离","t":"因此该技术完全基于蛋白质质量的不同这一性质进行分离。"},{"k":"分子筛效应","t":"由于凝胶的分子筛效应，蛋白质在电场中的迁移率与其分子质量的对数呈线性关系。"},{"k":"标准曲线测Mr","t":"用已知分子质量的标准蛋白作标准曲线，即可根据未知蛋白的迁移率求出其分子质量。"},{"k":"补：应用与局限","t":"用于纯度鉴定、亚基组成与分子量测定及 Western blot 前分离；还原条件下测得的是亚基分子量，不代表完整分子的分子量。"}],"note":"口径：依据《真题分类》资料原文。资料只讲原理与测分子量，末点应用与局限为教材口径补充（k 前标「补」）。","opts":[],"printed_answer":"","ref":true},{"id":"n0449","subj":"880","chap":"第十六章 氨基酸代谢","type":"选择","years":[],"q":"调节尿素循环的关键酶是","points":[{"k":"答案","t":"A、氨甲酰磷酸合成酶-1（CPS-1）。它是尿素循环的限速酶，位于线粒体，需 N-乙酰谷氨酸（AGA）变构激活；精氨酸代琥珀酸合成酶是第二步关键酶，但不是限速酶。"}],"note":"","opts":["A、氨甲酰磷酸合成酶-1","B、精氨酸代琥珀酸合成酶","C、鸟氨酸氨甲酰基转移酶","D、精氨酸代琥珀酸裂解酶"],"printed_answer":""},{"id":"n0450","subj":"880","chap":"第七章 核酸","type":"选择","years":[],"q":"下列不属于嘌呤核苷酸从头合成的原料是","points":[{"k":"答案","t":"A、谷氨酸。嘌呤从头合成的原料是天冬氨酸、甘氨酸、谷氨酰胺、CO₂ 和一碳单位（甲酸盐），谷氨酸不参与提供嘌呤环原子。"}],"note":"","opts":["A、谷氨酸","B、天冬氨酸","C、二氧化碳","D、一碳单位"],"printed_answer":""},{"id":"n0451","subj":"880","chap":"第十七章 核苷酸代谢","type":"选择","years":[],"q":"肿瘤病人化疗时，在尿液中可以检测到","points":[{"k":"答案","t":"B、尿酸、β-氨基异丁酸。化疗杀伤肿瘤细胞使核酸大量分解，嘌呤终产物尿酸与嘧啶（胸腺嘧啶）分解产物 β-氨基异丁酸经尿排出明显增多。"}],"note":"","opts":["A、苯丙酮酸","B、尿酸、β-氨基异丁酸"],"printed_answer":""},{"id":"n0452","subj":"880","chap":"第四章 蛋白质","type":"选择","years":[],"q":"检测蛋白质含量时，取决于完整肽链的检测方法是","points":[{"k":"答案","t":"B、双缩脲法。双缩脲反应需 ≥2 个肽键与 Cu²⁺ 络合显色，故必须存在完整肽链；茚三酮测氨基酸，紫外法测芳香族氨基酸，凯氏定氮测总氮。"}],"note":"","opts":["A、茚三酮","B、双缩脲","C、紫外吸收法","D、凯氏定氮法"],"printed_answer":""},{"id":"n0453","subj":"880","chap":"第三章 氨基酸","type":"选择","years":[],"q":"下列关于 20 种氨基酸说法正确的是：","points":[{"k":"答案","t":"D、除甘氨酸外其他都是 L 型。甘氨酸 α-碳连两个氢，无手性；其余 19 种 α-碳为不对称碳，蛋白质中均为 L 型，D 型仅见于细菌细胞壁肽聚糖等少数肽。"}],"note":"","opts":["A、全部是 L","B、全部是 D","C、部分是 L、部分是 D","D、除了甘氨酸外，其他都是 L"],"printed_answer":""},{"id":"n0454","subj":"880","chap":"第十二章 糖原的合成与分解","type":"选择","years":[],"q":"合成糖原过程中 G-1-P 需要　　活化","points":[{"k":"答案","t":"A、UTP。葡萄糖-1-磷酸在 UDPG 焦磷酸化酶催化下与 UTP 反应生成 UDP-葡萄糖（UDPG）并释放 PPi，再由糖原合酶把葡萄糖基转给糖原引物非还原端。"}],"note":"","opts":["A、UTP","B、ATP","C、CTP","D、GTP"],"printed_answer":""},{"id":"n0455","subj":"880","chap":"第十六章 氨基酸代谢","type":"选择","years":[],"q":"糖酵解、脂肪氧化、氨基酸代谢途径进入柠檬酸途径的主要物质是","points":[{"k":"答案","t":"A、乙酰 CoA。糖、脂肪、氨基酸分解产生的乙酰 CoA 与草酰乙酸缩合成柠檬酸进入三羧酸循环，故乙酰 CoA 是三大物质代谢进入该途径的共同枢纽。"}],"note":"","opts":["A、乙酰 CoA","B、草酰乙酸","C、柠檬酸","D、琥珀酸单酰辅酶 A"],"printed_answer":""},{"id":"n0456","subj":"880","chap":"第十章 糖酵解 糖异生","type":"选择","years":[],"q":"下列乳酸循环生理意义错误的是","points":[{"k":"答案","t":"A、能量浪费。乳酸循环的意义是回收肌糖酵解产生的乳酸、在肝异生成糖再利用、防止乳酸酸中毒、为只能进行无氧糖酵解的红细胞供能；净消耗 2 分子 ATP 只是代价，不是“能量浪费”这一生理意义。"}],"note":"","opts":["A、能量浪费","B、酸中毒","C、为红细胞供能"],"printed_answer":""},{"id":"n0457","subj":"880","chap":"第十六章 氨基酸代谢","type":"选择","years":[],"q":"血氨的来源有","points":[{"k":"答案","t":"B、氨基酸的脱氨基作用（主要来源）。此外肠道腐败作用产氨及尿素在肠道分解产氨吸收入血、肾小管谷氨酰胺水解产氨也供氨；A 胺类氧化脱氨亦属来源，D 表述不成立。"}],"note":"若为多选题，则 A、B、C 均为血氨来源。","opts":["A、体内胺类物质的释放","B、氨基酸的脱氨基作用","C、蛋白质腐败释放的胺","D、尿道中由酶催化的胺"],"printed_answer":""},{"id":"n0458","subj":"880","chap":"第十六章 氨基酸代谢","type":"选择","years":[],"q":"活性最强的转氨酶是将氨基转移给","points":[{"k":"答案","t":"B、α-酮戊二酸。谷丙转氨酶（ALT）与谷草转氨酶（AST）都以 α-酮戊二酸为氨基受体，生成谷氨酸，故其参与时转氨活性最强。"}],"note":"","opts":["A、草酰乙酸","B、α-酮戊二酸","C、谷氨酸"],"printed_answer":""},{"id":"n0459","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"选择","years":[],"q":"选择下列正确的叙述（）","points":[{"k":"答案","t":"A。外显子在基因组 DNA 与成熟 mRNA（cDNA）中顺序和内容一致，只是内含子被剪除；内含子不翻译，体细胞基因组相同而基因表达不同。"}],"note":"","opts":["A.外显子以相同的顺序存在于基因组和 cDNA 中","B.内含子经常可以被翻译","C.人体不同的细胞具有不相同的一套基因","D.人体内所有的细胞表达相同的一套基因"],"printed_answer":"A"},{"id":"n0460","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"选择","years":[],"q":"反密码子中哪个碱基对参与了密码子的简并性(摇摆)（）","points":[{"k":"答案","t":"A、第一个。反密码子 5' 端第 1 位与密码子 3' 端第 3 位配对不严格（摆动配对），故一个 tRNA 可识别几个同义密码子，是密码简并性的结构基础。"}],"note":"","opts":["A.第一个","B.第二个","C.第三个","D.第二或第三个"],"printed_answer":"A"},{"id":"n0461","subj":"631","chap":"综合","type":"选择","years":[],"q":"限制性内切酶可以特异性的识别（）","points":[{"k":"答案","t":"B、双链 DNA 的特定碱基序列。限制性内切酶识别 4～8 bp 的反向重复（回文）序列并在固定位点切割，产生黏性或平末端，不识别三联密码。"}],"note":"","opts":["A.双链 DNA 的特定碱基对","B.双链 DNA 的特定碱基序列","C.特定的三联密码","D.以上都不正确"],"printed_answer":"B"},{"id":"n0462","subj":"631","chap":"综合","type":"选择","years":[],"q":"在长链模板链的指引上引物延伸含成长的 DNA 互补链时应选用（）","points":[{"k":"答案","t":"B、Klenow 酶。它是大肠杆菌 DNA 聚合酶Ⅰ 的大片段，保留 5'→3' 聚合酶和 3'→5' 外切（校对）活性而失去 5'→3' 外切活性，沿长模板延伸引物时不降解引物、产物均一。"}],"note":"","opts":["A.T4DNA 聚合酶","B.Klenow 酶","C.大肠杆菌 DNA 聚合酶","D.T7DNA 聚合酶"],"printed_answer":"B"},{"id":"n0463","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"选择","years":[],"q":"关于 cDNA 的最正确的说法是（）","points":[{"k":"答案","t":"C、以 mRNA 为模板合成的双链 DNA。反转录酶先合成第一条 cDNA 链，RNase H 水解 RNA 后以第一条链为模板合成第二条链，所得 cDNA 不含内含子，可用于表达与文库构建。"}],"note":"","opts":["A.同 mRNA 互补的单链 DNA","B.同 mRNA 互补的 s 双链 DNA","C.以 mRNA 为模板合成的双链 DNA","D.以上都正确"],"printed_answer":"C"},{"id":"n0464","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"选择","years":[],"q":"下面哪一种特性不是遗传密码子所具有的（）","points":[{"k":"答案","t":"C、重叠性。遗传密码具有连续性、简并性、通用性、方向性和偏爱性，但密码子不重叠、之间无标点，故重叠性不是其特点。"}],"note":"","opts":["A.偏爱性","B.简并性","C.重叠性","D.连续性"],"printed_answer":""},{"id":"n0465","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"选择","years":[],"q":"CsCl-ErBr 密度梯度离心法纯化质粒 DNA 原理是","points":[{"k":"答案","t":"C、EB 可以较多地插入到线状 DNA 中。溴化乙锭嵌入碱基对之间使 DNA 密度降低；线状与开环 DNA 嵌入量大、密度低，超螺旋（SC）质粒嵌入少、密度高，故在 CsCl 密度梯度中分成不同区带。"}],"note":"","opts":["A.氯化铯可以较多地插入到线状 DNA 中","B.氯化铯可以较多地插入到 SC DNA 中","C.EB 可以较多地插入到线状 DNA 中","D.EB 可以较多的插入到 SC DNA 中"],"printed_answer":""},{"id":"n0466","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"判断","years":[],"q":"真核生物的复制子长度为 150bp 左右，包括数个复制起始必需的保护区（）","points":[{"k":"答案","t":"×。真核生物复制子（复制单位）长度约 50～300 kb，每个复制起点含多个复制起始必需的保守序列；150 bp 与之相差三个数量级。"}],"note":"","opts":[],"printed_answer":"×"},{"id":"n0467","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"判断","years":[],"q":"当 DNA 上相应位置的核苷酸发生损伤，导致双链之间无法形成氢键，则由核苷酸切除修复系统负责修复（）","points":[{"k":"答案","t":"√。碱基损伤使双链间无法配对时，由核苷酸切除修复（NER）系统识别扭曲、切除含损伤的寡核苷酸片段，再以对侧链为模板由聚合酶填补、连接酶封口。"}],"note":"","opts":[],"printed_answer":"√"},{"id":"n0468","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"判断","years":[],"q":"转座子是孟德尔在玉米实验中发现的决定体细胞变异的控制因子（）","points":[{"k":"答案","t":"×。转座子是 Barbara McClintock（麦克林托克）在玉米中发现的可移动控制因子，与孟德尔的豌豆遗传定律无关。"}],"note":"","opts":[],"printed_answer":"×"},{"id":"n0469","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":[],"q":"真核生物的转录和翻译过程是偶联的（）","points":[{"k":"答案","t":"×。真核细胞有核膜分隔，转录在核内进行、翻译在胞质核糖体上进行，二者在时空上分开；只有原核生物才转录与翻译偶联。"}],"note":"","opts":[],"printed_answer":"×"},{"id":"n0470","subj":"631","chap":"一、染色体结构","type":"判断","years":[],"q":"免疫球蛋白 IgG 分子由 Igκ、Igλ 和 IgH 基因编码，且位于同一条染色体上（）","points":[{"k":"答案","t":"×。IgH 基因位于 14 号染色体，Igκ 在 2 号、Igλ 在 22 号染色体，三者不在同一条染色体上，经基因重排与类别转换共同编码 IgG。"}],"note":"","opts":[],"printed_answer":"×"},{"id":"n0471","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"问答","years":[],"q":"简述真核生物 RNA 的加工过程。","points":[{"k":"前体在核内生成","t":"RNA 聚合酶 II 转录出 hnRNA（mRNA 前体），加工在细胞核内进行，成熟后才出核。"},{"k":"5′端加帽","t":"在 5′端加上 7-甲基鸟苷三磷酸（m⁷GpppN）帽子，保护 5′端不被外切酶降解，并帮助核糖体识别与出核。"},{"k":"3′端加尾","t":"3′端信号下游切断后，由 poly(A) 聚合酶加上 80~250 个腺苷酸的尾，增加稳定性、参与出核与翻译起始。"},{"k":"剪接去内含子","t":"剪接体（snRNP）识别 GU-AG 剪接位点，切除内含子、连接外显子；可变剪接使一个基因产生多种 mRNA。"},{"k":"两类RNA加工","t":"45S 前体 rRNA 经剪切、甲基化生成 18S、5.8S、28S；tRNA 前体切除两端多余序列、加 3′-CCA、进行碱基修饰。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0472","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"问答","years":[],"q":"简述蛋白质生物合成的几个主要阶段。","points":[{"k":"氨基酸活化","t":"氨酰-tRNA 合成酶消耗 ATP，把氨基酸的羧基与对应 tRNA 的 3′端连接成氨酰-tRNA，保证译码准确。"},{"k":"起始复合物","t":"mRNA、起始 tRNA（真核为 Met-tRNAi）、核糖体小亚基在起始因子参与下结合，识别起始密码 AUG，再结合大亚基。"},{"k":"延长三步循环","t":"进位（氨酰-tRNA 入 A 位）→转肽（形成肽键）→移位（核糖体沿 mRNA 移动一个密码子），仅进位与移位各耗 1 GTP，转肽由肽基转移酶催化、不耗 GTP。"},{"k":"终止与释放","t":"终止密码进入 A 位，释放因子识别并催化肽链水解，核糖体解离，需 GTP。"},{"k":"折叠与加工","t":"新生肽链自发折叠，并在内质网、高尔基体切除信号肽、糖基化、磷酸化、形成二硫键等翻译后修饰。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0473","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"问答","years":[],"q":"请指出 DNA 半保留复制的基本过程。","points":[{"k":"起始与解旋","t":"起始蛋白识别复制起点（oriC），DnaB 解旋酶打开双链形成复制叉，SSB 结合单链防止复性。"},{"k":"引物提供3′端","t":"引物酶合成一段短 RNA 引物，为 DNA 聚合酶提供延伸所需的 3′-OH。"},{"k":"前导链连续","t":"与解旋同向的模板上，DNA 聚合酶 III 沿 5′→3′ 连续合成，只需一个引物。"},{"k":"后随链成片段","t":"反向模板上分段合成冈崎片段，各自带引物；再由 RNase H/聚合酶 I 切除引物、填补缺口，连接酶封口。"},{"k":"半保留与校对","t":"每个子代分子含一条母链、一条新链；聚合酶 3′→5′ 外切活性即时校对，保证复制高保真。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0474","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"问答","years":[],"q":"请比较真核生物和原核生物转录和翻译调控的总体特征。","points":[{"k":"原核操纵子调控","t":"功能相关基因成簇组成操纵子，共用启动子与操纵基因，转录多顺反子 mRNA，以阻遏蛋白的负调控为主。"},{"k":"真核单基因独立","t":"每个基因有独立启动子，转录单顺反子 mRNA，靠多种转录因子与增强子组合调控，精细且具组织特异性。"},{"k":"时空是否耦联","t":"原核无核膜，转录与翻译耦联进行；真核转录在核内、翻译在胞质，两者在时间和空间上分开。"},{"k":"真核多级调控","t":"真核有染色质重塑与表观修饰、转录、加工、出核、翻译、翻译后修饰等多级调控；原核调控主要在转录起始。"},{"k":"翻译调控方式","t":"原核靠 mRNA 二级结构、衰减子与反义 RNA；真核靠 5′帽、poly(A)、miRNA 与 eIF2α 磷酸化调节。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0475","subj":"631","chap":"综合","type":"问答","years":[],"q":"简述你所了解的分子生物学实验设备及其用途(3 种以上)","points":[{"k":"PCR仪","t":"精确程序控温，完成变性—退火—延伸循环，用于基因扩增、突变检测与定量分析。"},{"k":"高速冷冻离心机","t":"高速低温离心分离细胞、细胞器、核酸与蛋白沉淀，低温可防止生物大分子降解。"},{"k":"核酸电泳系统","t":"琼脂糖或聚丙烯酰胺凝胶电泳按分子大小分离 DNA/RNA，配紫外凝胶成像仪观察条带并估算大小。"},{"k":"紫外分光光度计","t":"测 A260、A280 及比值，对核酸定量并判断蛋白质污染程度。"},{"k":"无菌与培养设备","t":"超净工作台/生物安全柜保证无菌操作，恒温摇床与培养箱用于细菌和细胞培养，为克隆表达提供材料。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0476","subj":"880","chap":"第十三章 磷酸戊糖途径、乙醛酸循环","type":"简答","years":[],"q":"大多数未控制的糖尿病患者，往往会伴随苯丙酮尿症的出现，请从生物化学角度解释。","points":[{"k":"蛋白分解增强","t":"胰岛素绝对或相对不足，肌肉与肝的蛋白质分解加速，血中苯丙氨酸等芳香族氨基酸底物明显增多。"},{"k":"辅因子供应不足","t":"苯丙氨酸羟化酶需四氢生物蝶呤（BH4）作辅酶，BH4 再生依赖 NADPH；糖尿病时磷酸戊糖途径减弱、NADPH 不足，酶活性下降。"},{"k":"羟化通路受阻","t":"苯丙氨酸不能正常羟化为酪氨酸，改经转氨基生成苯丙酮酸，在血中蓄积、由尿排出，出现苯丙酮尿。"},{"k":"糖异生分流底物","t":"糖异生增强，生糖氨基酸大量动员入肝，肝对芳香族氨基酸的代谢负荷超过处理能力，进一步堆积。"},{"k":"属继发性改变","t":"本质是继发性高苯丙氨酸血症，而非苯丙氨酸羟化酶基因缺陷，控制血糖后多可缓解。"}],"note":"严格讲糖尿病引起的是继发性高苯丙氨酸血症（类苯丙酮尿症表现），并非遗传性 PKU，答题时应点明这一区别。","opts":[],"printed_answer":""},{"id":"n0477","subj":"880","chap":"第十四章 氧化磷酸化","type":"简答","years":[],"q":"请解释氰化物对电子呼吸链的抑制作用。","points":[{"k":"结合细胞色素氧化酶","t":"CN⁻ 与细胞色素 c 氧化酶（复合体 IV）中血红素 Fe³⁺ 高亲和结合，形成稳定复合物使酶失活。"},{"k":"电子传递中断","t":"复合体 IV 不能把电子交给 O₂，NADH、FADH₂ 无法继续氧化，质子泵停止转运，质子梯度消失。"},{"k":"ATP合成骤停","t":"氧化磷酸化停止，ATP 产量急剧下降，细胞只能依赖糖酵解供能，乳酸大量堆积。"},{"k":"组织中毒性缺氧","t":"动脉血氧分压正常但组织不能利用氧，静脉血氧含量反而升高、呈鲜红色；细胞窒息，呼吸中枢先兴奋后抑制。"},{"k":"解毒解救","t":"亚硝酸盐-硫代硫酸钠疗法：亚硝酸盐使 Hb 变成高铁血红蛋白夺取 CN⁻，硫代硫酸钠经硫氰酸酶生成硫氰酸盐排出。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0478","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"简答","years":[],"q":"请解释 DNA 半保留复制的定义，并设计实验证明 DNA 半保留复制","points":[{"k":"半保留定义","t":"亲代 DNA 双链解开，各自作模板按碱基互补合成子链，每个子代分子含一条母链和一条新链。"},{"k":"重同位素标记","t":"Meselson-Stahl 用 ¹⁵NH₄Cl 培养大肠杆菌多代，使 DNA 全部被 ¹⁵N 标记，得到重 DNA。"},{"k":"密度梯度离心","t":"把细菌转入 ¹⁴N 普通培养基，每繁殖一代取样，用 CsCl 平衡密度梯度离心，DNA 按密度分层成带。"},{"k":"结果判定","t":"第一代只出现一条中密度带（一重一轻）；第二代出现中密度与轻密度带各半，与半保留预测一致。"},{"k":"排除另两种模型","t":"全保留模型应始终保留重带并新增轻带；弥散复制只出现一条逐渐变轻的带，均与实验结果不符。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0479","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"请分离以下蛋白质混合物，ABCD，相对分子质量，和等电点不同\nA 68000\nB 18000\nC 45000\nD 28000\n请举出二种蛋白质分离方法，并解释原理","points":[{"k":"凝胶过滤按大小","t":"用 Sephadex G-100 层析，大分子不能进网孔、先洗出，洗出顺序为 A(68k)→C(45k)→D(28k)→B(18k)。"},{"k":"离子交换按电荷","t":"用 DEAE-纤维素，pH 高于各蛋白 pI 时均带负电而结合；pI 越低负电荷越多、结合越牢，用 NaCl 梯度洗脱依次出峰。"},{"k":"等电聚焦按pI","t":"在 pH 梯度中蛋白质迁移至 pH=pI、净电荷为零处停止，分辨率高，可精确分开 pI 相近的组分。"},{"k":"SDS-PAGE鉴定","t":"变性电泳按亚基分子量分离，与 Marker 比较可核对各峰纯度与分子量，验证分离效果。"},{"k":"联合分离策略","t":"先用硫酸铵盐析粗分，再凝胶过滤按大小、离子交换按电荷精分，最后电泳鉴定，即“粗分—细分—鉴定”。"}],"note":"原题只给相对分子质量、未给各蛋白的 pI 数值，故电荷分离只能给出原理与次序原则。","opts":[],"printed_answer":""},{"id":"n0480","subj":"880","chap":"第六章 维生素与辅酶","type":"简答","years":[],"q":"维生素又叫维他命，是人体不可缺少的物质\n（1）从代谢角度 解释为什么维生素是人体必需物质\n（2）请举一个例子说明维生素的生理作用","points":[{"k":"不能自身合成","t":"人体不能合成或合成量不足，必须由食物提供；脂溶性维生素（A、D、E、K）随脂吸收并可在体内储存，水溶性（B 族、C）易随尿排出。"},{"k":"构成辅酶辅基","t":"多数 B 族维生素是辅酶或辅基的前体：B₁→TPP、B₂→FAD/FMN、PP→NAD⁺/NADP⁺、B₆→磷酸吡哆醛、生物素→羧化酶辅基。"},{"k":"调控代谢通路","t":"辅酶参与糖、脂、蛋白质和核酸的氧化还原、脱羧、转氨、羧化等反应；缺乏则相应酶促反应受阻、代谢中间物堆积。"},{"k":"例证维生素B1","t":"TPP 是丙酮酸脱氢酶、α-酮戊二酸脱氢酶和转酮醇酶的辅酶；缺乏使丙酮酸不能氧化、供能不足，引起脚气病、多发性神经炎。"},{"k":"例证维生素C","t":"作为羟化反应辅因子，参与胶原中脯氨酸、赖氨酸羟化；缺乏致坏血病，毛细血管脆性增加、牙龈出血。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0481","subj":"880","chap":"第八章 抗生素与激素","type":"简答","years":[],"q":"请解释青霉素的抗菌机制\n由于抗生素滥用，导致超级细菌容易出现，请解释这种现象，并说你的看法","points":[{"k":"抑制转肽酶","t":"青霉素的 β-内酰胺环与细菌转肽酶（青霉素结合蛋白 PBP）共价结合，使转肽反应不可逆失活。"},{"k":"细胞壁缺损溶菌","t":"肽聚糖链间交联受阻，细胞壁网状结构不能形成；细菌在低渗环境吸水膨胀、破裂死亡，对繁殖期细菌作用最强。"},{"k":"选择性毒性","t":"人体细胞无细胞壁，故对人的毒性小；对已形成厚壁的静止期细菌作用弱，故需足量足疗程。"},{"k":"耐药机制","t":"细菌产生 β-内酰胺酶水解药物、改变 PBP 结构降低亲和力、减少外膜通透性或主动外排；耐药基因可经质粒、转座子水平转移。"},{"k":"选择压力造超级菌","t":"滥用抗生素形成强选择压力，敏感菌被淘汰、耐药株获得繁殖优势并扩散，即“超级细菌”；应严格掌握指征、足量足疗程、必要时联合用药并加强耐药监测。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0482","subj":"880","chap":"第七章 核酸","type":"简答","years":[],"q":"核酸内含了的核酶经研究发现是 RNA，请分析为什么核酶是 RNA，而不是 DNA","points":[{"k":"2′-OH参与催化","t":"核糖 2′-羟基可作氢键供体与受体，参与酸碱催化、稳定过渡态并限制构象，是催化活性的化学基础；DNA 的 2′-H 无此能力。"},{"k":"单链折叠成口袋","t":"RNA 为单链，可自身回折形成锤头、发夹等复杂三级结构，构建活性中心口袋；DNA 多为刚性双链，构象单一。"},{"k":"转录即成活性","t":"RNA 转录后即可直接折叠行使功能，无需解链等额外步骤，响应快、调控灵活。"},{"k":"支持RNA世界","t":"核酶兼具信息储存与催化能力，与 tRNA、rRNA 的加工和肽键形成相关，支持“RNA 世界”假说，早于 DNA-蛋白质体系。"},{"k":"分工决定材质","t":"DNA 双链、2′-H 使磷酸二酯键更稳定，适合长期储存遗传信息；催化任务交给 RNA 与蛋白质，是稳定性与功能性分工的结果。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0483","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":[],"q":"当机体摄入糖类物质不足时，推荐摄入含有奇数碳脂肪酸的脂肪，而不推荐摄入含有偶数碳脂肪酸的脂肪酸，请从营养学分析为什么如此推荐？","points":[{"k":"奇数碳产丙酰CoA","t":"β 氧化每轮切下二碳单位，奇数碳脂肪酸末轮生成丙酰 CoA，而不是乙酰 CoA。"},{"k":"丙酰CoA能生糖","t":"丙酰 CoA 经生物素依赖的羧化酶生成甲基丙二酰 CoA，再变位为琥珀酰 CoA 进入三羧酸循环，可净生成葡萄糖。"},{"k":"偶数碳只生酮","t":"偶数碳脂肪酸只产乙酰 CoA，乙酰 CoA 不能逆行生成丙酮酸，哺乳动物无法净合成糖，只能氧化或生成酮体。"},{"k":"补充血糖前体","t":"糖摄入不足时需糖异生维持血糖，奇数碳脂肪酸提供生糖碳源，减少低血糖风险。"},{"k":"减少酮体堆积","t":"琥珀酰 CoA 补充草酰乙酸，使乙酰 CoA 顺利进入三羧酸循环，酮体生成减少，并可节省蛋白质消耗。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0484","subj":"880","chap":"第十七章 核苷酸代谢","type":"简答","years":[],"q":"5－氟尿嘧啶作为抗癌药物，\n（1）请解释为什么 5－氟尿嘧啶可以抑制癌症。\n（2）往往不推荐病人长期服用 5－氟尿嘧啶，请解释。","points":[{"k":"活化成氟尿苷酸","t":"5-FU 经磷酸核糖转移酶或胸苷磷酸化酶转变为 5-氟尿嘧啶核苷酸，再还原为 5-氟脱氧尿苷酸（5-FdUMP）。"},{"k":"抑制胸苷酸合酶","t":"5-FdUMP 与胸苷酸合酶（TS）及四氢叶酸形成稳定的三元复合物，阻断 dUMP 甲基化为 dTMP。"},{"k":"阻断DNA复制","t":"dTTP 迅速耗竭，DNA 合成受阻，增殖旺盛的肿瘤细胞首先死亡，产生抗肿瘤作用。"},{"k":"掺入RNA干扰","t":"5-FU 还可转变为氟尿苷三磷酸掺入 RNA，干扰 RNA 加工与蛋白质合成，形成双重杀伤。"},{"k":"毒性限制长期用","t":"骨髓、胃肠黏膜、毛囊等增殖快的正常组织同样受抑，长期用致骨髓抑制、腹泻、口腔炎；且肿瘤易产生耐药（TS 高表达、降解酶增强），故需间歇给药并监测血象。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0485","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"考点","years":["21"],"q":"DNA 复制几种酶发生作用的顺序是什么","points":[{"k":"答案","t":"拓扑异构酶→解旋酶（DnaB）→单链结合蛋白（SSB）→引物酶（DnaG）→DNA 聚合酶Ⅲ→DNA 聚合酶Ⅰ→DNA 连接酶。先由拓扑异构酶消除复制叉前方正超螺旋，解旋酶才能拉开双链，SSB 稳定单链，引物酶合成 RNA 引物后聚合酶Ⅲ才可延伸。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0486","subj":"631","chap":"综合","type":"考点","years":["21"],"q":"鹅膏蕈碱对生物的哪一个过程有抑制作用","points":[{"k":"答案","t":"α-鹅膏蕈碱。它特异抑制真核生物 RNA 聚合酶Ⅱ（极低浓度即可），阻断 mRNA 转录；高浓度也抑制 PolⅢ，对 PolⅠ 和原核 RNA 聚合酶无效。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0487","subj":"631","chap":"综合","type":"考点","years":["21"],"q":"写出一段 DNA 序列的互补序列","points":[{"k":"答案","t":"按 A—T、G—C 互补并反向平行书写。如 5'-ATGC-3' 的互补链为 3'-TACG-5'；两条链等长、方向相反。"}],"note":"题干未给具体序列，只能给配对规则与示例。","opts":[],"printed_answer":""},{"id":"n0488","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["21"],"q":"RNA 聚合酶核心酶组成","points":[{"k":"答案","t":"α₂ββ'（另含 ω 小亚基）。核心酶不含 σ 因子，只能催化 RNA 链延长；σ 与核心酶结合成全酶后才能识别启动子。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0489","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["21"],"q":"不依赖于 ρ 因子终止子的结构特征","points":[{"k":"答案","t":"富含 GC 的反向重复序列加下游 AT 富集区。转录出的 RNA 形成发卡（茎环）使聚合酶停顿，其后的寡聚 U 与模板 dA 配对最弱，RNA 自行脱落，不需 ρ 因子。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0490","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"判断","years":["21"],"q":"2020 年诺贝尔化学奖/医学奖因为丙型肝炎获奖的两个人","points":[{"k":"答案","t":"错误（×）。2020 年诺贝尔生理学或医学奖授予 Alter、Houghton、Rice 三人，表彰发现丙型肝炎病毒；当年化学奖为 CRISPR-Cas9 基因编辑（Charpentier 与 Doudna），与丙肝无关。"}],"note":"题干表述含混，按「2020 年因丙肝获奖人数为三而非两人」判定为错。","opts":[],"printed_answer":""},{"id":"n0491","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":["21"],"q":"原核生物有 TATA 盒对不衬","points":[{"k":"答案","t":"错误（×）。原核启动子为 -10 区 Pribnow 盒（TATAAT）与 -35 区（TTGACA）；TATA 盒（TATAAAA）是真核 RNA 聚合酶Ⅱ核心启动子的元件。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0492","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"判断","years":["21"],"q":"启动子就是顺式作用原件对不衬","points":[{"k":"答案","t":"错误（×）。启动子只是顺式作用元件之一，顺式作用元件还包括增强子、沉默子、绝缘子、加尾信号等，二者不能等同。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0493","subj":"631","chap":"五、RNA 的调控机制","type":"名词解释","years":["21"],"q":"miRNA","points":[{"k":"定义","t":"真核生物内源编码的长约 21~23 nt 的非编码单链 RNA，由发夹前体经 Dicer 加工，在转录后水平负调控基因表达。"},{"k":"RISC 抑制或切割","t":"与靶 mRNA 3′UTR 部分互补时抑制翻译，完全互补时经 RISC 切割降解；一个 miRNA 可调控多个靶基因，参与发育与肿瘤发生。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0494","subj":"631","chap":"五、RNA 的调控机制","type":"名词解释","years":["21"],"q":"RNAi","points":[{"k":"定义","t":"外源或内源双链 RNA 经 Dicer 切成小干扰 RNA，装配成 RISC 后特异降解同源 mRNA、导致基因沉默的现象。"},{"k":"Dicer 与 RISC","t":"双链 RNA 先被 Dicer 切成 21~23 nt 的 siRNA，再装配 RISC 降解同源 mRNA；具序列特异性、可扩散、可遗传，由 Fire 和 Mello 发现。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0495","subj":"631","chap":"七、分子生物学技术","type":"名词解释","years":["21"],"q":"酵母双杂交","points":[{"k":"定义","t":"基于 Gal4 转录因子模块化原理检测蛋白质相互作用的遗传学方法，把待测蛋白分别与 DNA 结合域和激活域融合。"},{"k":"重建转录因子活性","t":"两蛋白互作使 BD 与 AD 靠近、重建转录因子活性，激活 LacZ、HIS3 等报告基因；可在体内筛文库，但难检测跨膜或需修饰的互作。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0498","subj":"631","chap":"七、分子生物学技术","type":"名词解释","years":["21"],"q":"基因芯片","points":[{"k":"基因芯片定义","t":"又称 DNA 芯片、DNA 微阵列、寡核苷酸阵列：采用原位合成或显微打印手段，把数以万计的 DNA 探针固化于支持物表面，产生二维 DNA 探针阵列。"},{"k":"原理","t":"与标记的样品进行杂交，通过检测杂交信号实现对生物样品快速、并行、高效的检测或医学诊断。"},{"k":"应用","t":"分析基因型、基因突变与多态性用于疾病诊断治疗；DNA 重测序（杂交测序）；测定基因表达谱；基因来源同一性分析（血型、亲子鉴定）；研究核酸与蛋白质相互作用用于药物研发。"},{"k":"表达分析流程","t":"大规模 PCR 获得 cDNA 插入片段→机械手点样于玻璃板并变性固定→不同组织分离 mRNA 反转录为 cDNA→不同荧光染料分别标记→与芯片杂交→激光扫描、计算机分析数据。"}],"note":"口径：依据《真题分类》资料原文。","opts":[],"printed_answer":"","ref":true},{"id":"n0499","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"名词解释","years":["21"],"q":"实时定量 PCR","points":[{"k":"定义","t":"在 PCR 体系中加入荧光染料或荧光探针，实时监测每轮循环的荧光强度，从而对起始模板进行定量的技术。"},{"k":"Ct 值与模板对数","t":"荧光达阈值所需循环数 Ct 与起始模板量的对数成线性；分 SYBR Green 染料法与 TaqMan 探针法，可作相对或绝对定量。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0500","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"名词解释","years":["21"],"q":"端粒酶","points":[{"k":"定义","t":"由 RNA 组分和逆转录酶组分构成的核糖核蛋白，能以自身 RNA 为模板合成端粒重复序列、延长染色体末端。"},{"k":"逆转录延伸 3′ 端","t":"TERT 以 TERC 为模板逆转录延伸 3′ 悬突，再由聚合酶补齐互补链；生殖细胞、干细胞与多数肿瘤细胞活性高，体细胞低。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0501","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["21"],"q":"基因工程中，DNA 聚合酶、逆转录酶和 RNA 聚合酶功能的异同","points":[{"k":"三者共同点","t":"都以核酸为模板、按碱基互补配对、沿 5′→3′ 方向延伸，催化核苷酸间形成磷酸二酯键，释放焦磷酸。"},{"k":"DNA聚合酶","t":"以 DNA 为模板，需引物 3′-OH，合成 DNA；具 3′→5′ 外切校对活性，用于 PCR、缺口平移、标记探针。"},{"k":"逆转录酶","t":"以 RNA（也可用 DNA）为模板合成 cDNA，需引物，无校对活性，用于 cDNA 文库构建、RT-PCR、cDNA 探针。"},{"k":"RNA聚合酶","t":"以 DNA 为模板，不需引物即可起始，合成 RNA；识别启动子、无校对活性，用于体外转录合成 RNA 探针。"},{"k":"工程中分工","t":"三者构成基因操作的核心工具链：逆转录酶建库取基因、DNA 聚合酶扩增与标记、RNA 聚合酶制备探针与 RNA。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0502","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["21"],"q":"为什么说 DNA 的复制是半保留、半不连续复制","points":[{"k":"半保留含义","t":"亲代双链解开，各自作模板合成子链，子代分子一母一新；Meselson-Stahl ¹⁵N 密度梯度实验直接证实。"},{"k":"半不连续原因","t":"DNA 聚合酶只能沿 5′→3′ 延伸，而两条模板反向平行，故一股能连续合成、另一股只能分段合成。"},{"k":"前导链连续","t":"模板方向与解旋同向，可沿复制叉前进方向连续合成一条长链。"},{"k":"后随链成片段","t":"模板方向相反，只能先合成短的冈崎片段，再由 RNase H/FEN1 去引物、聚合酶 I 填补、连接酶封口。"},{"k":"生物学意义","t":"半保留保证遗传信息准确传给子代，半不连续是 5′→3′ 合成方向限制的必然结果，二者共同维持复制的高保真与连续性。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0503","subj":"631","chap":"一、染色体结构","type":"名词解释","years":[],"q":"nucleasome 核体","points":[{"k":"定义","t":"真核染色质的基本结构单位：146 bp DNA 盘绕在 H2A、H2B、H3、H4 各两分子组成的组蛋白八聚体外约 1.75 圈。"},{"k":"串珠与 30 nm 纤维","t":"相邻核小体经连接 DNA 连成串珠，再折叠压缩为 30 nm 纤维，DNA 压缩 6~7 倍；同时是组蛋白修饰与染色质重塑的靶点。"}],"note":"卷面「nucleasome 核体」应为 nucleosome 核小体，按核小体作答。","opts":[],"printed_answer":""},{"id":"n0504","subj":"631","chap":"综合","type":"名词解释","years":[],"q":"allosteric regulation 别构调节","points":[{"k":"定义","t":"小分子效应剂以非共价方式结合酶的别构位点，引起构象改变，从而改变活性中心对底物亲和力或催化效率的调节。"},{"k":"正负协同 S 形","t":"效应剂与底物结构不同，结合后经亚基间构象传递产生正协同激活或负协同抑制，动力学曲线呈 S 形，如 ATCase、PFK-1。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0505","subj":"631","chap":"七、分子生物学技术","type":"名词解释","years":[],"q":"isoelectric point 等电点","points":[{"k":"定义","t":"使氨基酸处于兼性离子状态、分子净电荷为零、在电场中不迁移时所在溶液的 pH 值，即等电点（pI）。"},{"k":"应用","t":"pH 低于 pI 时带正电、高于 pI 时带负电，可据此进行等电点沉淀、等电聚焦与离子交换层析。"}],"note":"口径：依据《真题分类》资料原文（仅定义）；电荷规律与应用为教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0506","subj":"631","chap":"综合","type":"名词解释","years":[],"q":"glyoxylate cycle 乙醛酸循环","points":[{"k":"定义","t":"植物和微生物中绕开三羧酸循环两步脱羧、以乙酰辅酶 A 为原料净合成琥珀酸进而生成糖的途径。"},{"k":"异柠檬酸裂解酶","t":"异柠檬酸裂解为琥珀酸与乙醛酸，后者与乙酰 CoA 缩合成苹果酸；2 分子乙酰 CoA 净生 1 分子琥珀酸，使脂肪酸碳源转为糖。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0507","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":[],"q":"reverse transcription 逆转录","points":[{"k":"概念定义","t":"以 RNA 为模板、由逆转录酶催化合成互补 DNA（cDNA）的过程，遗传信息流向为 RNA→DNA。"},{"k":"逆转录酶活性","t":"逆转录酶兼具 RNA 指导的 DNA 聚合、DNA 指导的 DNA 聚合与 RNase H 三种活性，需引物。"},{"k":"生物学意义","t":"补充了中心法则中 RNA→DNA 的信息流向；是逆转录病毒复制的机制，也是 cDNA 克隆与 RT-PCR 的基础。"}],"note":"资料无对应原答案，按教材口径。资料该条为「逆转录酶（reverse transcriptase）」，问的是酶；本题问的是逆转录过程，不是同一题，故未采用；末点意义由教材口径补写。","opts":[],"printed_answer":"","ref":false},{"id":"n0508","subj":"631","chap":"综合","type":"名词解释","years":[],"q":"glycolysis 糖酵解","points":[{"k":"定义","t":"指葡萄糖或糖原在无氧条件下分解为丙酮酸的过程，是生物最古老、最原始的一种获能方式，发生于细胞质基质中。"},{"k":"产物与能量","t":"经 10 步反应，1 分子葡萄糖可分解生成 2 分子丙酮酸、2 分子 ATP 和 2 分子 NADH＋H⁺。"}],"note":"口径：依据《真题分类》资料原文（定义与产物）。","opts":[],"printed_answer":"","ref":true},{"id":"n0509","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"名词解释","years":[],"q":"secondary messenger 第二信使","points":[{"k":"定义","t":"第一信使与受体结合后在细胞内生成或释放、把信号转导并逐级放大的小分子，如 cAMP、cGMP、IP₃、DAG、Ca²⁺。"},{"k":"级联放大与终止","t":"由腺苷酸环化酶、磷脂酶 C 等生成，作用于蛋白激酶引起级联磷酸化，实现信号放大、整合与终止，是跨膜转导的核心环节。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0510","subj":"631","chap":"综合","type":"名词解释","years":[],"q":"specificity 特异性","points":[{"k":"定义","t":"酶对底物和所催化反应的高度选择性，一种酶只作用于一种或一类结构相似的底物、催化特定类型的反应。"},{"k":"锁钥与诱导契合","t":"源于活性中心与底物在形状、电荷、基团上的互补；包括底物特异性、反应特异性与立体特异性，是酶鉴别与临床检测的基础。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0511","subj":"631","chap":"一、染色体结构","type":"名词解释","years":[],"q":"ribozyme 核酶","points":[{"k":"定义","t":"核酶是一类具有催化功能的 RNA 分子，可通过催化靶位点 RNA 链中磷酸二酯键的断裂，特异性地剪切底物 RNA 分子，从而阻断基因的表达。"},{"k":"分类与意义","t":"可分为剪切型核酶和剪接型核酶；其发现打破了「酶都是蛋白质」的传统观念，为 RNA 世界假说提供依据。"}],"note":"口径：依据《真题分类》资料原文（定义与分类）；「打破酶都是蛋白质的观念、支持 RNA 世界假说」为教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0512","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":[],"q":"简并性","points":[{"k":"定义","t":"简并性，指遗传密码中一种氨基酸可由两个或两个以上密码子编码的现象；除 Met（AUG）、Trp（UGG）外，多数氨基酸有 2~6 个密码子。"},{"k":"意义","t":"同义密码子多在第 3 位碱基不同，突变后仍编码同一氨基酸，降低突变危害；不同物种对同义密码子的选用存在偏爱性。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0513","subj":"631","chap":"综合","type":"名词解释","years":[],"q":"丝心蛋白","points":[{"k":"定义","t":"丝心蛋白（fibroin），蚕丝的主要结构蛋白，由重链与轻链经二硫键连接，富含 Gly、Ala、Ser，二级结构以反平行 β-折叠为主。"},{"k":"结构特点","t":"重复序列 Gly-Ala-Gly-Ala-Gly-Ser 使 β-折叠片层紧密堆叠，链间氢键密集，赋予纤维高强度与柔性，但缺乏弹性。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0516","subj":"631","chap":"综合","type":"名词解释","years":[],"q":"α-丙酮酸脱氢酶系","points":[{"k":"定义","t":"丙酮酸脱氢酶复合体，多酶体系，由 E1 丙酮酸脱氢酶、E2 二氢硫辛酰胺转乙酰酶、E3 二氢硫辛酰胺脱氢酶组成，催化丙酮酸氧化脱羧生成乙酰 CoA。"},{"k":"辅酶与调节","t":"需 TPP、硫辛酸、CoA、FAD、NAD⁺ 五种辅酶；产物乙酰 CoA、NADH、ATP 反馈抑制，AMP、CoA、NAD⁺ 激活；磷酸化失活、去磷酸化激活。"}],"note":"题干“α-丙酮酸脱氢酶系”疑为“丙酮酸脱氢酶系”之误，按丙酮酸脱氢酶复合体作答。","opts":[],"printed_answer":""},{"id":"n0518","subj":"631","chap":"综合","type":"选择","years":[],"q":"对蛋白质跨线粒体膜描述不正确的是()","points":[{"k":"答案","t":"E。线粒体蛋白属翻译后转运：在胞质中合成完整前体（N 端带导肽）后，经外膜 TOM 与内膜 TIM 复合物耗能跨膜；边翻译边跨膜是内质网共翻译转运的特征。"}],"note":"卷面答案为 E，与教材一致。","opts":["A.是完成翻译后的蛋白质跨线粒体膜的运输","B.通过线粒体膜的蛋白质在运输前端多带有导肽","C.通过线粒体内膜是一个耗能过程","D.导肽中不同片段含有不同跨膜结点","E.蛋白质在肽链合成过程中跨膜"],"printed_answer":"E"},{"id":"n0519","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"考点","years":[],"q":"关于乳糖操纵子描述不正确的是()","points":[{"k":"答案","t":"应选「诱导物（别乳糖）直接与操纵基因结合」这类说法。乳糖经 β-半乳糖苷酶转为别乳糖，结合的是 LacI 阻遏蛋白，使其构象改变并从操纵基因脱落，从而解除阻遏；操纵基因本身不与诱导物结合。"}],"note":"原卷选项缺失，按此类题最常见的错误选项作答。","opts":[],"printed_answer":""},{"id":"n0520","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":[],"q":"试述大肠杆菌DNA复制的起始过程，回答DNA复制起始过程中主要蛋白质和酶的作用，起始位点Oric中错在的转录起始位点的发用。","points":[{"k":"DnaA识别起始点","t":"DnaA 蛋白在 ATP 参与下结合 oriC 的 4 个 DnaA 盒（9 bp 重复序列），使 DNA 弯曲缠绕。"},{"k":"解旋酶开链","t":"DnaA 使邻近 AT 富集区（13 bp 重复）变性，DnaC 把 DnaB 解旋酶装载到单链上，双向解旋形成复制叉。"},{"k":"SSB与引物酶","t":"SSB 结合并稳定单链、防止复性；引物酶（DnaG）合成短 RNA 引物，提供 3′-OH。"},{"k":"聚合酶与连接酶","t":"β 滑动夹把 DNA 聚合酶 III 全酶装载到引物上，前导链连续、后随链分段合成；聚合酶 I 切除引物填补，连接酶封口。"},{"k":"转录激活起始","t":"oriC 内的转录启动子转录出的 RNA 可形成 R 环、造成局部负超螺旋，帮助 DnaA 结合与双链开放，并提供引物，从而促进起始。"},{"k":"起始频率控制","t":"转录也参与调控：GATC 半甲基化与 SeqA 结合、DnaA 的 ATP/ADP 状态共同保证每个细胞周期只起始一次。"}],"note":"题干原文有错字，“起始位点Oric中错在的转录起始位点的发用”应为“oriC 中存在的转录起始位点的作用”。","opts":[],"printed_answer":""},{"id":"n0521","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"试述原核生物和真核生物转录的mRNA主要特点是什么？","points":[{"k":"原核多顺反子","t":"一条 mRNA 常编码多个功能相关蛋白，含多个起始与终止密码，5′端有 SD 序列引导核糖体定位。"},{"k":"原核无帽无尾","t":"5′端为三磷酸、无帽子，3′端无 poly(A) 尾，半衰期短（数分钟），可边转录边翻译。"},{"k":"真核单顺反子","t":"一条 mRNA 只编码一条肽链，具 5′ m⁷G 帽和 3′ poly(A) 尾，有较长的 5′UTR 与 3′UTR。"},{"k":"真核需剪接","t":"前体 hnRNA 含内含子，必须经剪接去掉内含子才能成熟出核；mRNA 寿命长（数小时）。"},{"k":"稳定性差异","t":"帽与尾使真核 mRNA 稳定、翻译效率高；原核靠 SD 序列与 mRNA 二级结构调节翻译起始。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0522","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"试述真核生物mRNA基因的特点，mRNA前体的加工后的作用是什么？","points":[{"k":"断裂基因结构","t":"真核基因由外显子与内含子相间排列组成，转录出的 hnRNA 含内含子，须剪接才能成熟。"},{"k":"单顺反子独立调控","t":"一个基因转录一种 mRNA、编码一条肽链，各有独立启动子与调控区，可单独开关。"},{"k":"调控区远距离作用","t":"上游有 TATA 框、GC 框、CAAT 框，另有增强子、沉默子可在远处甚至内含子中起作用；基因组还存在多基因家族与假基因。"},{"k":"加帽加尾作用","t":"帽保护 5′端、帮助核糖体识别与出核；poly(A) 尾提高稳定性、参与翻译起始与寿命调控。"},{"k":"剪接与可变剪接","t":"剪接去除内含子、连接外显子生成成熟 mRNA；可变剪接使一个基因产生多种蛋白，显著扩展编码能力。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0523","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":[],"q":"利用密码子简并性的原理说明基因在异源宿主表达量低的候，可以用什么途径提高表达量，通过何种技术手段可以这到这个目标？","points":[{"k":"简并性与偏好","t":"一个氨基酸可由 2~6 个密码子编码（Met、Trp 除外），即密码子简并性；不同物种对同义密码子使用频率不同，称密码子偏好性。"},{"k":"稀有密码子阻滞","t":"异源宿主中稀有密码子对应的 tRNA 含量低，翻译时核糖体停滞、发生错配或提前终止，导致表达量低。"},{"k":"密码子优化","t":"在不改变氨基酸序列的前提下，把稀有密码子同义替换为宿主偏好的密码子，可通过全基因合成或定点突变实现。"},{"k":"补充稀有tRNA","t":"共表达携带稀有 tRNA 的辅助质粒（如 pRARE），提高相应 tRNA 丰度，缓解翻译停滞。"},{"k":"其他配套优化","t":"同时优化启动子与 RBS、调整 GC 含量与 mRNA 二级结构、去除内部酶切位点、降低诱导温度以提高可溶性表达。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0524","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":[],"q":"真核生物基因表达调控可以分为几个层次?你认为近几年在哪个层次研究的比较多?为什么？","points":[{"k":"染色质水平","t":"DNA 甲基化、组蛋白乙酰化与甲基化、染色质重塑改变基因的可及性，是最上游的调控层次。"},{"k":"转录水平","t":"转录因子与启动子、增强子、沉默子结合，调控 RNA 聚合酶 II 的招募与起始，是最主要的控制点。"},{"k":"转录后加工","t":"可变剪接、加帽加尾、RNA 编辑与出核转运决定成熟 mRNA 的种类和数量。"},{"k":"翻译水平","t":"通过 eIF2α 磷酸化、miRNA、mRNA 稳定性与胞内定位调节翻译效率。"},{"k":"翻译后修饰","t":"折叠、切割、磷酸化、乙酰化、泛素化与降解决定活性蛋白的数量与寿命。"},{"k":"热点在表观层","t":"近年染色质与表观遗传（增强子 RNA、三维基因组、单细胞多组学）研究最多，因其能解释细胞命运决定与疾病机制，且 ATAC-seq、Hi-C、CRISPR 等技术已成熟。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0525","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":[],"q":"请看以下的物质粒图谱和欲克隆的基因图谱(实体框代表外显子)你的任务是从人肝样品中取得目的基因编码序列并且重组","points":[{"k":"cDNA取编码序列","t":"从人肝组织提取总 RNA，逆转录合成 cDNA，用基因特异引物 PCR 扩增，直接得到不含内含子的编码序列。"},{"k":"引物加酶切位点","t":"在引物 5′端引入与载体多克隆位点匹配的限制酶切位点并加保护碱基，保证后续定向插入。"},{"k":"双酶切定向连接","t":"目的片段与质粒用同一对限制酶双酶切、纯化后用 T4 DNA 连接酶连接，防止载体自连并保证插入方向正确。"},{"k":"转化与筛选","t":"转化感受态大肠杆菌，先用抗生素抗性初筛，再以蓝白斑筛选、菌落 PCR 与双酶切鉴定阳性克隆。"},{"k":"测序与表达","t":"测序确认序列与读框正确，转入表达宿主诱导表达，用 SDS-PAGE 与 Western blot 检测目的蛋白。"}],"note":"原卷的质粒图谱与目的基因图谱（实心框示外显子）未录入，无法确定具体酶切位点与载体元件，故按“cDNA 取编码序列→定向克隆→筛选鉴定→表达验证”通用流程作答。","opts":[],"printed_answer":""},{"id":"n0526","subj":"631","chap":"综合","type":"简答","years":[],"q":"你在本科学习阶段从事（或参与）过什么科研工作，简述其中一项实验的主要目的，试验方法，操作步骤，结果及结论，你的体会。","points":[{"k":"实验目的","t":"例：探究某植物提取物对 α-葡萄糖苷酶的抑制作用，验证其体外降餐后血糖活性并初步确定有效部位。"},{"k":"方法与步骤","t":"超声辅助乙醇提取→大孔树脂分段→PNPG 法测酶抑制率（设阿卡波糖为阳性对照）→计算 IC₅₀→HPLC 初步定性。"},{"k":"实验结果","t":"乙酸乙酯部位抑制率最高，IC₅₀ 为若干 mg/mL，呈明显剂量依赖；HPLC 显示含黄酮类成分。"},{"k":"实验结论","t":"该部位对 α-葡萄糖苷酶有显著抑制作用，可作为降糖功能成分进一步分离与体内验证。"},{"k":"心得与体会","t":"体会到对照与重复设计的重要性，养成规范记录原始数据、异常结果先排查操作与试剂的习惯，提升了实验设计与数据分析能力。"}],"note":"本题为个人经历开放题，以上为可套用模板，须按本人实际参与的项目替换具体名称、方法与数据。","opts":[],"printed_answer":""},{"id":"n0529","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"名词解释","years":["25"],"q":"同裂酶","points":[{"k":"定义","t":"同裂酶（isoschizomer），指来源不同但识别同一 DNA 序列、并在相同位点切割产生相同末端的两种限制性内切酶。"},{"k":"用途","t":"两者对甲基化敏感性常不同，可用于检测 DNA 甲基化；一种酶失活或受抑制时可互为替代。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0530","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":["25"],"q":"假基因","points":[{"k":"定义","t":"假基因，基因组中与功能基因同源、但因缺失启动子、阅读框移位或点突变而失去表达能力的 DNA 序列，不产生有功能的蛋白质或 RNA。"},{"k":"类型与意义","t":"分加工型（逆转座而来、无内含子）与非加工型（基因重复后突变）；可作为分子进化标记，少数仍参与基因表达调控。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0531","subj":"631","chap":"综合","type":"判断","years":["25"],"q":"禽流感病毒是单链 DNA（ ）","points":[{"k":"答案","t":"错误（×）。禽流感病毒属正黏病毒科甲型流感病毒，基因组为 8 个节段的单股负链 RNA，不是单链 DNA。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0532","subj":"631","chap":"综合","type":"考点","years":["25"],"q":"利福平对 RNA PolyⅡ哪个亚基作用？","points":[{"k":"答案","t":"β 亚基（rpoB 基因产物）。利福平结合 β 亚基，阻断转录起始后 2~3 个核苷酸处的 RNA 延伸；对真核 RNA 聚合酶无抑制作用。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0533","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"考点","years":["25"],"q":"DNA 稀有碱基如何形成？","points":[{"k":"答案","t":"复制后由修饰酶催化生成。5-甲基胞嘧啶、N⁶-甲基腺嘌呤等由 DNA 甲基转移酶以 S-腺苷甲硫氨酸为甲基供体，对已合成的碱基进行甲基化、羟化等修饰形成。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0534","subj":"631","chap":"七、分子生物学技术","type":"考点","years":["25"],"q":"DNA 芯片基于哪个研究？","points":[{"k":"答案","t":"核酸分子杂交。芯片把大量已知探针固定于固相支持物，与标记的靶核酸杂交后扫描检测，本质是 Southern 印迹固相杂交原理的高通量微型化。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0535","subj":"631","chap":"一、染色体结构","type":"简答","years":["25"],"q":"DNA 双螺旋结构及其意义","points":[{"k":"反向平行右手螺旋","t":"两条多核苷酸链反向平行围绕同一中心轴盘绕，形成右手双螺旋。"},{"k":"骨架外碱基内","t":"脱氧核糖-磷酸交替骨架位于外侧，碱基对位于内侧，螺旋直径 2 nm。"},{"k":"碱基互补配对","t":"A 与 T 形成 2 个氢键、G 与 C 形成 3 个氢键，嘌呤配嘧啶使螺旋直径恒定。"},{"k":"螺距与大小沟","t":"每圈 10 个碱基对，螺距 3.4 nm，相邻碱基对间距 0.34 nm；表面有大沟与小沟。"},{"k":"稳定与可复性","t":"氢键、碱基堆积力和磷酸二酯骨架共同维持稳定；加热变性后两条链在适当条件下可复性。"},{"k":"生物学意义","t":"互补配对是半保留复制与转录的分子基础，碱基序列即遗传信息；为分子杂交、PCR、基因工程提供理论依据。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0537","subj":"631","chap":"一、染色体结构","type":"简答","years":["25"],"q":"Holliday 中间体是什么，怎么形成和拆开？","points":[{"k":"十字交叉结构","t":"同源重组中两条 DNA 双螺旋交换一条链后形成的十字形四链交叉中间体，交叉点可沿 DNA 滑移，称分支迁移。"},{"k":"RecA介导形成","t":"RecBCD 在双链断裂处降解并产生 3′单链，RecA 包被单链形成核蛋白丝，侵入同源双链置换出 D 环，两分子交叉即形成 Holliday 连接体。"},{"k":"RuvC拆分","t":"RuvC 为特异性核酸酶，在交叉点对称切开两条同向链，再由连接酶连接，完成片段交换（splice）。"},{"k":"解旋酶解离","t":"RuvAB 促进分支迁移，RecG 等可把它解离成两条独立双链（dissolution），不产生交换。"},{"k":"重组意义","t":"决定基因转换与交换的结局，保证同源重组的准确性，也是 DNA 双链断裂修复的核心中间体。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0538","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["25"],"q":"载体的特征？","points":[{"k":"自主复制起点","t":"含复制起点（ori），能在宿主细胞内独立复制，拷贝数可高可低。"},{"k":"选择标记","t":"携带抗生素抗性基因等选择标记，便于筛出转化成功的细胞。"},{"k":"多克隆位点","t":"有密集的单一限制酶切位点区，便于外源片段插入，且插入不破坏复制与选择功能。"},{"k":"装载容量足够","t":"能容纳一定大小的外源 DNA：质粒数 kb、噬菌体十几 kb、BAC/YAC 可达上百 kb。"},{"k":"易转化易回收","t":"分子较小、转化效率高，可从宿主中大量提取回收，便于后续酶切与测序。"},{"k":"表达元件可选","t":"表达载体还需启动子、RBS、终止子、标签序列与多克隆位点，保证转录翻译正常进行。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0539","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["25"],"q":"为什么 DNA 聚合酶具有校对功能，RNA 聚合酶没有？","points":[{"k":"外切酶结构基础","t":"DNA 聚合酶同时具 5′→3′ 聚合中心和 3′→5′ 外切中心；新链 3′端与模板错配时延伸受阻，单链转移到外切位点被切除。"},{"k":"保真要求高","t":"DNA 是遗传信息长期载体，错误会随复制固定并传给子代，故错配率需低至 10⁻⁹ 量级。"},{"k":"RNA酶无外切位点","t":"RNA 聚合酶缺乏 3′→5′ 外切活性中心，结构上没有校对装置，故无校对功能。"},{"k":"焦磷酸解校正","t":"RNA 聚合酶可靠活性中心的焦磷酸解逆向反应切掉错配核苷酸，但效率低，转录错误率约 10⁻⁴~10⁻⁵。"},{"k":"后果决定取舍","t":"DNA 错误永久遗传，必须校对；RNA 是临时拷贝，错误只影响一批蛋白且可降解重合成，进化上无需高保真。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0540","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":["25"],"q":"真核生物和原核生物基因表达调控特点？","points":[{"k":"原核操纵子经济","t":"功能相关基因成簇组成操纵子，共用一个启动子转录多顺反子 mRNA，以阻遏/诱导的负调控为主，经济高效。"},{"k":"真核单基因精细","t":"每个基因有独立启动子、转录单顺反子 mRNA，靠多种转录因子与增强子组合调控，精细且组织特异。"},{"k":"真核多级设控","t":"染色质重塑与表观修饰→转录→加工→出核→翻译→翻译后修饰，层层设控，任一环节都可调节。"},{"k":"原核转录翻译耦联","t":"无核膜分隔，边转录边翻译，调控主要集中在转录起始与衰减作用。"},{"k":"非编码RNA参与","t":"真核有 miRNA、siRNA、lncRNA 参与转录及转录后调控；原核以反义 RNA、核糖开关为主。"},{"k":"时空特异性","t":"真核调控具发育阶段与组织特异性；原核主要响应营养、渗透压、温度等环境变化。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0541","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["25"],"q":"southern 和 Northern 技术的区别原理和应用","points":[{"k":"检测对象不同","t":"Southern 检测 DNA，Northern 检测 RNA，两者都用标记核酸探针做分子杂交。"},{"k":"共同原理","t":"核酸经凝胶电泳按大小分离→转膜固定→与互补标记探针杂交→洗膜后放射自显影或显色，显示特异条带。"},{"k":"Southern流程","t":"DNA 限制酶消化→琼脂糖电泳→碱变性→转尼龙膜→预杂交与杂交→洗膜显影；用于基因拷贝数、缺失、RFLP 与酶切图谱。"},{"k":"Northern流程","t":"提取 RNA（严格防 RNase）→变性凝胶电泳→转膜→杂交；用于检测基因转录水平、mRNA 大小与剪接异构体。"},{"k":"差异要点","t":"起始材料与变性条件不同（DNA 需酶切、RNA 需防降解并用变性剂）；Northern 反映表达量，Southern 反映基因结构。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0542","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["25"],"q":"简述真核生物启动子中 TATA 框的结构特征及其在转录起始中的作用。","points":[{"k":"位置与序列","t":"位于转录起始点上游约 −25~−30 bp，是富含 A/T 的共有序列 TATAAA，属核心启动子元件。"},{"k":"TBP结合小沟","t":"TATA 结合蛋白（TBP，TFIID 的亚基）以鞍形结构结合 DNA 小沟，使 DNA 弯曲约 80°，是装配的起点。"},{"k":"定位起始位点","t":"决定转录从哪一个碱基开始，保证起始位点的精确性；缺失或突变会使起始位点漂移、转录效率下降。"},{"k":"装配前起始复合物","t":"依次招募 TFIIA、TFIIB，再结合 RNA 聚合酶 II 与 TFIIE、TFIIH，形成前起始复合物并启动转录。"},{"k":"决定启动子强度","t":"TATA 框与上下游元件、转录因子协同决定转录效率；无 TATA 框的基因靠 CpG 岛、GC 框等元件定位起始。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0543","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"论述","years":["25"],"q":"（1）问给一段 N 端氨基酸序列，怎样测定该基因全长\n（2）怎么通过基因克隆技术，实现一个基因的表达","points":[{"k":"简并引物设计","t":"按 N 端氨基酸序列反推可能的密码子，合成一组简并寡核苷酸探针或引物，并作同位素或地高辛标记。"},{"k":"文库筛选与RACE","t":"用探针筛 cDNA 文库取阳性克隆；或先用简并引物做 3′-RACE、再 5′-RACE 向两端延伸，获得全长 cDNA。"},{"k":"测序确认全长","t":"测序拼接后确认开放读框，且其编码的 N 端氨基酸序列与已知一致，即得该基因全长编码序列。"},{"k":"引物加酶切位点","t":"据全长序列设计带限制酶位点与 Kozak/RBS 的引物，PCR 扩增开放读框。"},{"k":"定向连接与筛选","t":"目的片段与表达载体双酶切后连接，转化感受态细胞，经抗性筛选、菌落 PCR、双酶切与测序鉴定阳性克隆。"},{"k":"诱导表达与鉴定","t":"转入表达宿主，IPTG 诱导，用 SDS-PAGE、Western blot 与活性测定验证表达量与正确性。"}],"note":"原题第（1）问的 N 端序列与第（2）问的载体信息未给出，答案按通用策略作答。","opts":[],"printed_answer":""},{"id":"n0544","subj":"631","chap":"五、RNA 的调控机制","type":"论述","years":["25"],"q":"（1）microRNA 形成过程\n（2）microRNA 作用机制","points":[{"k":"转录初级前体","t":"由 RNA 聚合酶 II 转录出带帽、带尾并含发夹结构的初级 miRNA（pri-miRNA），多在基因间区或内含子中编码。"},{"k":"核内Drosha切割","t":"Drosha 与 DGCR8 组成的微处理器复合物在核内把 pri-miRNA 切成约 70 nt 的前体 miRNA（pre-miRNA）。"},{"k":"出核与Dicer切割","t":"Exportin-5 依赖 Ran-GTP 将其运出核，胞质中 Dicer 切去末端环，生成约 21~23 nt 的双链 miRNA。"},{"k":"装载RISC","t":"双链解旋，引导链进入 Argonaute 蛋白形成 RNA 诱导沉默复合物（RISC），过客链被降解。"},{"k":"翻译抑制为主","t":"与靶 mRNA 3′UTR 不完全互补配对，抑制翻译起始或使核糖体提前脱落，蛋白表达下降而 mRNA 水平变化不大。"},{"k":"切割与降解","t":"完全互补时 Ago2 直接切割 mRNA；多数情况经脱腺苷化、脱帽后迅速降解，实现转录后沉默。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0545","subj":"880","chap":"第十五章 脂类代谢","type":"问答","years":["21"],"q":"在人体缺少葡萄糖时，选用补充奇数链脂肪酸好，还是偶数链脂肪酸好，为什么？","points":[{"k":"奇数碳能生糖","t":"奇数碳脂肪酸 β 氧化末轮生成丙酰 CoA，经羧化、变位成琥珀酰 CoA 进入三羧酸循环，可净生成葡萄糖。"},{"k":"偶数碳不能生糖","t":"偶数碳脂肪酸只产乙酰 CoA，乙酰 CoA 不能羧化为丙酮酸，哺乳动物无法由其净合成糖。"},{"k":"缺糖需生糖前体","t":"葡萄糖不足时靠糖异生维持血糖，必须补充生糖碳源，奇数碳脂肪酸正好提供。"},{"k":"减少酮体生成","t":"琥珀酰 CoA 补充草酰乙酸，使乙酰 CoA 顺利进入三羧酸循环，酮体堆积减轻，避免酮症酸中毒。"},{"k":"节省蛋白质","t":"提供糖异生碳源，减少肌肉蛋白分解，故营养学上推荐奇数碳脂肪酸。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0546","subj":"880","chap":"第四章 蛋白质","type":"问答","years":["21"],"q":"为什么血红蛋白在 CO 环境中减少了对氧气的需求","points":[{"k":"亲和力极高","t":"CO 与血红蛋白的亲和力约为 O₂ 的 210~250 倍，分压很低即可大量占据血红素。"},{"k":"竞争同一配位位点","t":"CO 与 O₂ 争夺血红素 Fe²⁺ 的第 6 配位位点，形成碳氧血红蛋白（HbCO），使有效携氧的 Hb 减少。"},{"k":"协同效应丧失","t":"部分亚基结合 CO 后，其余亚基的构象转换受阻，氧解离曲线左移、失去 S 形特征，O₂ 难以在组织释放。"},{"k":"携氧释氧双降","t":"血氧含量下降，同时组织处释氧效率降低，造成双重缺氧，故表现为“对氧的需求减少”而实为利用障碍。"},{"k":"高压氧救治","t":"患者皮肤黏膜呈樱桃红色、头痛昏迷；高压氧舱大幅提高 PaO₂，竞争性置换 CO 并加速其排出，是主要治疗手段。"}],"note":"“减少了对氧气的需求”应理解为 Hb 携氧与向组织释放氧的能力下降，而非机体需氧量真的减少。","opts":[],"printed_answer":""},{"id":"n0547","subj":"880","chap":"第十一章 柠檬酸循环","type":"问答","years":["21"],"q":"乙酰 CoA 的去路有哪些，","points":[{"k":"进入三羧酸循环","t":"与草酰乙酸缩合成柠檬酸，经三羧酸循环彻底氧化供能，是主要去路。"},{"k":"合成脂肪酸","t":"在胞质经乙酰 CoA 羧化酶生成丙二酰 CoA，再由脂肪酸合酶催化合成脂肪酸，储存能量。"},{"k":"合成胆固醇","t":"经 HMG-CoA 途径合成胆固醇，进而生成胆汁酸、类固醇激素和维生素 D₃。"},{"k":"生成酮体","t":"在肝线粒体生成乙酰乙酸、β-羟丁酸和丙酮，运往肝外组织氧化利用。"},{"k":"其他代谢去向","t":"与胆碱合成乙酰胆碱，参与蛋白质的乙酰化修饰，并可合成 N-乙酰谷氨酸等小分子。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0548","subj":"880","chap":"第十六章 氨基酸代谢","type":"问答","years":["21"],"q":"蛋白质合成中，丙氨酸和谷氨酰胺为什么含量高于其他氨基酸？","points":[{"k":"丙氨酸运氨","t":"肌肉中氨基酸脱下的氨经转氨交给丙酮酸生成丙氨酸，随血运至肝，构成葡萄糖-丙氨酸循环，故其周转量大。"},{"k":"谷氨酰胺储氨","t":"氨与谷氨酸经谷氨酰胺合成酶（耗 ATP）生成无毒的谷氨酰胺，是血中含量最高的游离氨基酸，承担氮的运输。"},{"k":"肾脏排氨","t":"谷氨酰胺在肾经谷氨酰胺酶释放 NH₃ 直接排入尿，同时生成 HCO₃⁻，起排酸保碱作用，需求量大。"},{"k":"合成供应充足","t":"二者均为非必需氨基酸，可由糖代谢中间物大量合成，氨基酸池容量大、周转快，不易成为翻译的限速因素。"},{"k":"密码子简并偏多","t":"Ala 有 4 个、Gln 有 2 个同义密码子，简并性使其在蛋白质中出现的概率偏高。"}],"note":"若题目指血浆游离氨基酸池，则以氮转运与解毒解释为主；若指蛋白质中残基比例，则主要与密码子简并性有关，答题可两者兼顾。","opts":[],"printed_answer":""},{"id":"n0549","subj":"880","chap":"第六章 维生素与辅酶","type":"问答","years":["21"],"q":"丙氨酸→谷氨酸，需要什么酶，什么辅基？","points":[{"k":"转氨酶催化","t":"丙氨酸与 α-酮戊二酸在丙氨酸氨基转移酶（ALT，即 GPT）催化下互换氨基，生成丙酮酸和谷氨酸。"},{"k":"磷酸吡哆醛","t":"辅基为磷酸吡哆醛（PLP），由维生素 B6 转变而来，是转氨酶的辅酶，靠醛基与氨基可逆结合完成氨基传递。"},{"k":"乒乓机制","t":"反应为双底物乒乓机制：酶先接受丙氨酸的氨基形成磷酸吡哆胺，再把氨基交给 α-酮戊二酸。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0550","subj":"880","chap":"第三章 氨基酸","type":"问答","years":["21"],"q":"根据酶解肽段分析多肽的氨基酸顺序（参考往年真题）","points":[{"k":"N端标记","t":"用丹磺酰氯（DNS-Cl）或 2,4-二硝基氟苯（DNFB，Sanger 试剂）标记 N 端，水解后鉴定带标记的氨基酸。"},{"k":"C端测定","t":"用羧肽酶 A、B、C 从 C 端逐个水解并定时取样分析；或用硼氢化锂还原法确定 C 端残基。"},{"k":"专一性切割","t":"胰蛋白酶切 Lys、Arg 的羧基侧；胰凝乳蛋白酶切 Phe、Tyr、Trp 的羧基侧；V8 蛋白酶切 Glu、Asp 的羧基侧。"},{"k":"重叠拼接","t":"用两套以上不同切法得到互相重叠的肽段，按重叠区对齐，拼出完整顺序。"},{"k":"顺序验证","t":"再用 Edman 降解法或串联质谱（MS/MS）对拼接结果直接测序验证。"}],"note":"本题为方法题，原卷要求「参考往年真题」的操作流程。","opts":[],"printed_answer":""},{"id":"n0551","subj":"880","chap":"第四章 蛋白质","type":"问答","years":["21"],"q":"有个滴定组氨酸的图，（1）A、B 两点时组氨酸的结构式。（2）组氨酸的 pI。（3）C 点时组氨酸的结构。（4）血红蛋白中有组氨酸的作用，","points":[{"k":"三个可解离基团","t":"α-羧基 pKa≈1.8，咪唑基 pKa≈6.0，α-氨基 pKa≈9.2；三个 pKa 把滴定曲线分成三段。"},{"k":"A点全质子化","t":"A 点 pH 低于 pKa1，三个基团都带质子，净电荷 +2，结构为 HisH₃²⁺（α-COOH、咪唑鎓、α-NH₃⁺）。"},{"k":"B点等电形式","t":"B 点 pH 介于 pKa2 与 pKa3 之间，羧基已去质子、咪唑基已去质子、α-氨基仍带正电，净电荷 0，为两性离子。"},{"k":"pI计算","t":"等电点取两性离子两侧 pKa 的平均值：pI=(6.0+9.2)/2≈7.6。"},{"k":"C点去质子","t":"C 点 pH 高于 pKa3，羧基、咪唑基、α-氨基全部去质子，净电荷 −1。"},{"k":"血红蛋白His","t":"近端 His F8（αHis87/βHis92）与 Fe²⁺ 配位固定血红素；远端 His E7（αHis58/βHis63）以氢键稳定 O₂；βHis146 与 Asp94 成盐桥稳定 T 态，参与 Bohr 效应。"}],"note":"原卷滴定图缺失，A、B、C 三点按滴定曲线常规标注（起始低 pH 平台、第一等当点、高 pH 平台）作答。","opts":[],"printed_answer":""},{"id":"n0552","subj":"880","chap":"第七章 核酸","type":"问答","years":["21"],"q":"给出一个 DNA 链。（1）写出 mRNA 链。（2）翻译出的肽链。（3）mRNA 的作用","points":[{"k":"碱基互补","t":"以模板链为模板按 A-U、T-A、G-C、C-G 配对，mRNA 与模板链反向平行，序列与编码链相同、T 换成 U。"},{"k":"起始密码","t":"从 mRNA 5′端第一个 AUG 开始，作为起始密码子并编码甲硫氨酸（原核为甲酰甲硫氨酸）。"},{"k":"按表翻译","t":"每 3 个碱基为一组密码子，对照遗传密码表写出氨基酸，读到 UAA、UAG、UGA 终止。"},{"k":"mRNA的作用","t":"把 DNA 的遗传信息传递到核糖体，作为蛋白质合成的直接模板，决定肽链的氨基酸排列顺序。"},{"k":"结构元件","t":"5′帽和 3′polyA 尾保护 mRNA、提高翻译效率；5′与 3′非翻译区参与稳定性与翻译水平调控。"}],"note":"原卷未印出具体 DNA 序列，只能给出书写 mRNA 与翻译的通用规则。","opts":[],"printed_answer":""},{"id":"n0553","subj":"880","chap":"第七章 核酸","type":"问答","years":["21"],"q":"抗核苷酸代谢的药物、机理。","points":[{"k":"抗叶酸剂","t":"甲氨蝶呤（MTX）抑制二氢叶酸还原酶，四氢叶酸生成受阻，一碳单位供应不足，dTMP 与嘌呤合成均被阻断。"},{"k":"嘧啶类似物","t":"5-氟尿嘧啶经代谢为 FdUMP 抑制胸苷酸合酶；阿糖胞苷（Ara-C）抑制 DNA 聚合酶。"},{"k":"嘌呤类似物","t":"6-巯基嘌呤生成 6-MP 核苷酸，反馈抑制 PRPP 酰胺转移酶，阻断 IMP 转变为 AMP 和 GMP。"},{"k":"谷氨酰胺拮抗","t":"氮杂丝氨酸等拮抗谷氨酰胺，抑制嘌呤环合成中酰胺氮的掺入。"},{"k":"还原酶抑制","t":"羟基脲抑制核糖核苷酸还原酶，使 NDP 不能生成 dNDP，DNA 合成原料断供。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0554","subj":"880","chap":"第一章 糖类","type":"简答","years":["21"],"q":"纤维素和淀粉的结构差别，纤维素在生活中的应用","points":[{"k":"糖苷键构型","t":"淀粉为 α-1,4 糖苷键，支链处为 α-1,6；纤维素为 β-1,4 糖苷键。"},{"k":"链的空间形态","t":"α-键使淀粉卷曲成螺旋；β-键使相邻葡萄糖翻转 180°，形成平直长链，链间氢键聚成微纤维。"},{"k":"人体不能消化","t":"人缺乏纤维素酶（β-葡萄糖苷酶），不能水解 β-1,4 键，故纤维素不提供能量。"},{"k":"膳食纤维作用","t":"促进肠蠕动、增加粪便体积、防治便秘，吸附胆汁酸降低血脂，延缓餐后血糖上升。"},{"k":"工业应用","t":"造纸与棉麻纺织；羧甲基纤维素（CMC）作食品增稠剂；微晶纤维素作药用辅料；纤维素发酵制乙醇。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0555","subj":"880","chap":"第五章 酶","type":"计算","years":["21"],"q":"给出了乳酸脱氢酶双倒数曲线的斜率，纵轴截距。（1）乳酸脱氢酶催化反应的步骤。（2）写出米式方程（3）求 Km 和 Vmax","points":[{"k":"列式","t":"Lineweaver-Burk 方程：1/v =(Km/Vmax)·(1/[S]) + 1/Vmax。"},{"k":"斜率含义","t":"双倒数直线斜率 = Km/Vmax。"},{"k":"截距含义","t":"纵轴截距 = 1/Vmax。"},{"k":"求Vmax","t":"Vmax = 1/纵轴截距，单位为产物浓度每分钟。"},{"k":"求Km","t":"Km = 斜率 × Vmax = 斜率/纵轴截距，单位与底物浓度相同。"}],"note":"原卷图的斜率与纵轴截距数值缺失，只能给出公式与求解步骤；代入原卷数据即可得 Km、Vmax。","opts":[],"printed_answer":""},{"id":"n0556","subj":"880","chap":"第六章 维生素与辅酶","type":"计算","years":["21"],"q":"一分子甘油彻底氧化可产生多少 ATP（NADH 通过 α-磷酸甘油途径穿梭）","points":[{"k":"活化耗能","t":"甘油激酶催化甘油 + ATP → 3-磷酸甘油，消耗 1 个 ATP。"},{"k":"脱氢产FADH₂","t":"线粒体内膜的 3-磷酸甘油脱氢酶（辅基 FAD）将其氧化为磷酸二羟丙酮，生成 1 个 FADH₂，经复合体Ⅱ得 1.5 ATP。"},{"k":"酵解后半段","t":"磷酸二羟丙酮异构为 3-磷酸甘油醛，经酵解生成丙酮酸：底物水平磷酸化得 2 ATP，另生成 1 个 NADH。"},{"k":"丙酮酸氧化","t":"丙酮酸脱氢酶复合体催化生成乙酰 CoA，同时生成 1 个 NADH（2.5 ATP）。"},{"k":"三羧酸循环","t":"1 个乙酰 CoA 经三羧酸循环生成 3 NADH + 1 FADH₂ + 1 GTP = 10 ATP。"},{"k":"合计","t":"胞质 NADH 走 α-磷酸甘油穿梭按 1.5 计：−1 + 1.5 + 1.5 + 2 + 2.5 + 10 = 16.5 ATP。"}],"note":"若胞质 NADH 走苹果酸-天冬氨酸穿梭（按 2.5 计），结果为 17.5 ATP；本题指定 α-磷酸甘油穿梭，故答 16.5。","opts":[],"printed_answer":""},{"id":"n0557","subj":"880","chap":"第十七章 核苷酸代谢","type":"名词解释","years":["21"],"q":"别嘌呤醇","points":[{"k":"定义","t":"别嘌呤醇，次黄嘌呤的异构体，是黄嘌呤氧化酶的抑制药，能减少尿酸生成，临床用于治疗痛风和高尿酸血症。"},{"k":"机制","t":"本身亦被黄嘌呤氧化酶氧化为别黄嘌呤，两者均为竞争性抑制剂，故作用持久；可使黄嘌呤蓄积，偶致黄嘌呤结石与过敏。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0558","subj":"880","chap":"第三章 氨基酸","type":"简答","years":["21"],"q":"a-螺旋，计算","points":[{"k":"每圈残基数","t":"α-螺旋每 3.6 个氨基酸残基旋转一圈。"},{"k":"螺距","t":"螺距（每圈沿轴上升）= 0.54 nm。"},{"k":"每残基上升","t":"每个残基沿螺旋轴上升 0.15 nm（0.54/3.6）。"},{"k":"长度公式","t":"含 n 个残基的螺旋轴长 = 0.15n nm = (n/3.6)×0.54 nm；反之由长度可求残基数 n = L/0.15。"},{"k":"构象参数","t":"螺旋直径约 0.5 nm，为右手螺旋，侧链伸向螺旋外侧；氢键平行于螺旋轴，由第 i 与 i+4 位残基的 C=O 与 N-H 形成。"}],"note":"原卷未给出残基数或螺旋长度，故给出通用计算式与结构参数。","opts":[],"printed_answer":""},{"id":"n0559","subj":"880","chap":"第十三章 磷酸戊糖途径、乙醛酸循环","type":"简答","years":["21"],"q":"日常生活中吃糖多为什么会发胖？","points":[{"k":"能量过剩","t":"吃糖过多造成体内能量物质过剩，一方面减少脂肪的消耗，另一方面过剩能量转向脂肪合成，使体内脂肪含量增加而变胖。"},{"k":"乙酰CoA变脂肪酸","t":"葡萄糖—糖酵解→丙酮酸—氧化脱羧→乙酰 CoA—脂肪酸合成→脂肪酸—脂酰 CoA 合成酶→脂酰 CoA。"},{"k":"磷酸二羟丙酮变甘油","t":"葡萄糖—糖酵解→磷酸二羟丙酮—3-磷酸甘油脱氢酶→3-磷酸甘油，提供甘油骨架。"},{"k":"酯化成甘油三酯","t":"3-磷酸甘油经酰基转移酶逐次加上脂酰 CoA，生成 1-单酰甘油-3-磷酸、1,2-二酰甘油-3-磷酸（磷脂酸），再由磷脂酸磷酸酶脱磷酸成 1,2-二酰甘油，加脂酰 CoA 生成三酰甘油（脂肪）。"},{"k":"补：NADPH与胰岛素","t":"资料未列：磷酸戊糖途径提供的 NADPH 为脂肪酸合成的还原步骤供氢，血糖升高引起的胰岛素分泌增加也促进脂肪合成、抑制脂肪动员。"}],"note":"口径：依据《真题分类》资料原文（原文以三步反应式给出）；末点 NADPH 与胰岛素为教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0562","subj":"880","chap":"第五章 酶","type":"简答","years":["21"],"q":"酶的抑制图分类：抑制剂，竞争抑制剂，非竞争抑制剂，解释。","points":[{"k":"竞争性抑制","t":"抑制剂与底物竞争活性中心，Km 增大、Vmax 不变；双倒数图为一组交于纵轴的直线。"},{"k":"非竞争性抑制","t":"抑制剂结合 E 或 ES 活性中心以外的部位，Km 不变、Vmax 降低；双倒数图交于横轴。"},{"k":"反竞争性抑制","t":"抑制剂只与 ES 结合，Km 与 Vmax 同比例下降；双倒数图为一组平行线。"},{"k":"不可逆抑制","t":"抑制剂以共价键修饰必需基团，透析、稀释均不能恢复活性，Vmax 下降。"},{"k":"判别步骤","t":"先透析或稀释测活：恢复为可逆、不恢复为不可逆；再作双倒数图看交点位置确定抑制类型。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0563","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["21"],"q":"蛋白带，凝胶过滤层析图。","points":[{"k":"柱床体积Vt","t":"Vt 为凝胶柱床的总体积，常称柱床体积。"},{"k":"外水与内水体积","t":"Vo 为外水体积（孔隙体积），Vi 为内水体积。"},{"k":"洗脱体积Ve","t":"Ve 为某一待分离物质组分的洗脱体积。"},{"k":"分配系数Kd","t":"Kd = (Ve − Vo)/Vi，或 Kd = (Ve − Vo)/(Vt − Vo)。"},{"k":"排阻与全进入","t":"完全被排阻的大分子 Ve = Vo、Kd = 0，先被洗脱；完全能进入凝胶孔内的小分子 Ve = Vt、Kd = 1，后被洗脱；Kd 总在 0 与 1 之间。"},{"k":"凝胶介质选择","t":"Kd = 0 或 Kd = 1 的物质处于分级分离范围之外，分子大小虽不同也不能被分开；故须按待分离物与杂质实际的大小差异，计算后选择孔隙合适的凝胶介质。"}],"note":"口径：依据《真题分类》资料原文。资料末段 Ⅰ/Ⅱ/Ⅲ 的对应关系（小分子 Ve=Vo、大分子 Ve=Vt）与 Kd 定义自相矛盾，显系 OCR 颠倒，已按 Kd=0 排阻先出、Kd=1 全进入后出的正确关系更正；「蛋白带」一题资料原文标注为「略」，无可誊录内容。","opts":[],"printed_answer":"","ref":true},{"id":"n0564","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["21"],"q":"脂肪酸合成途径，B-氧化途径异同点（合成部位、代谢的酶、酰基载体等方面）。","points":[{"k":"四点相同","t":"①均需要酰基载体；②均有 4 步循环反应；③均需要转运机制；④均以两个碳原子为单位添加或离去。"},{"k":"场所与转运机制","t":"合成在胞质溶胶，乙酰 CoA 靠三羧酸转运机制出线粒体；β 氧化在线粒体基质，脂酰 CoA 靠肉碱载体系统进入。"},{"k":"反应过程与类型","t":"合成按缩合-还原-脱水-还原进行，属还原反应、需 NADPH 参与；β 氧化按氧化-水合-氧化-裂解进行，属氧化反应、需 FAD 与 NAD⁺ 参与。"},{"k":"方向与酰基载体","t":"合成自甲基端向羧基端延伸、酰基载体为 ACP；β 氧化自羧基端向甲基端降解、载体为辅酶 A；前者另需 CO₂ 与柠檬酸，后者不需。"},{"k":"底物产物与能量","t":"合成循环底物/产物为丙二酰 CoA/脂酰 CoA，每轮加 2 碳，16 碳需 7 次轮回、消耗 7 分子 ATP；β 氧化为脂酰 CoA/乙酰 CoA，每轮减 2 碳，16 碳 7 次轮回、净产生 106 ATP。"},{"k":"构型与限速酶","t":"合成中间物羟脂酰 ACP 为 D-构型，限速酶是乙酰 CoA 羧化酶；β 氧化中间物均为 L-构型，限速酶是肉碱脂酰转移酶。"}],"note":"口径：依据《真题分类》资料原文（原文以对比表给出，此处按点归并）；能量按 16 碳、NADH 2.5／FADH₂ 1.5 口径核为 106 ATP。","opts":[],"printed_answer":"","ref":true},{"id":"n0565","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"名词解释","years":["24"],"q":"DNA 的半保留复制","points":[{"k":"定义","t":"DNA 半保留复制，复制时双链解开，两条亲代链各作模板合成互补链，子代 DNA 中一条链来自亲代、一条为新合成链。"},{"k":"证据与意义","t":"Meselson-Stahl ¹⁵N 密度梯度离心实验证实；保证遗传信息忠实、完整地传给子代。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0566","subj":"631","chap":"五、RNA 的调控机制","type":"名词解释","years":["24"],"q":"非编码 RNA","points":[{"k":"定义","t":"非编码 RNA，指不翻译成蛋白质的 RNA，包括 rRNA、tRNA、snRNA、miRNA、siRNA 等，在转录、剪接、翻译与基因表达调控中发挥作用。"},{"k":"功能举例","t":"miRNA、siRNA 经 RISC 降解或阻抑靶 mRNA 翻译；lncRNA 参与 X 染色体失活、染色质修饰与转录干扰。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0569","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"名词解释","years":["24"],"q":"无义突变","points":[{"k":"定义","t":"无义突变，指编码氨基酸的密码子突变为终止密码子（UAA、UAG、UGA），使肽链合成提前终止、生成截短蛋白质的突变。"},{"k":"后果","t":"多肽缩短、功能丧失，多为致病或致死突变；抑制性 tRNA 或通读药物可部分纠正。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0570","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"名词解释","years":["24"],"q":"泛素蛋白","points":[{"k":"定义","t":"泛素蛋白，由 76 个氨基酸残基构成、高度保守的小分子蛋白，经 E1 激活、E2 结合、E3 连接酶催化，共价连接于靶蛋白的赖氨酸残基。"},{"k":"功能","t":"形成多聚泛素链标记靶蛋白，由 26S 蛋白酶体 ATP 依赖性降解；亦参与 DNA 修复、信号转导与蛋白定位。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0571","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":["24"],"q":"剪接体","points":[{"k":"定义","t":"剪接体，由 U1、U2、U4、U5、U6 等 snRNA 与数十种蛋白质组成的核糖核蛋白复合物，识别 hnRNA 剪接位点，切除内含子并连接外显子。"},{"k":"过程","t":"经两次酯交换完成：先由 branch point 攻击 5′ 位点形成套索，再连接两个外显子；需 ATP 与 snRNP 重排。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0572","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":["24"],"q":"σ因子","points":[{"k":"定义","t":"σ 因子，原核 RNA 聚合酶全酶的组分，识别启动子 −35 区与 −10 区，引导酶结合并起始转录；转录起始后脱落，由核心酶完成延伸。"},{"k":"调控意义","t":"不同 σ 因子（如 σ⁷⁰、σ³² 热休克因子）识别不同启动子，使 RNA 聚合酶选择性转录不同基因，是原核转录调控的重要层次。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0573","subj":"631","chap":"综合","type":"名词解释","years":["24"],"q":"HIV","points":[{"k":"定义","t":"HIV，人类免疫缺陷病毒，属逆转录病毒科慢病毒属，有包膜和两条正链 RNA，携带逆转录酶、整合酶与蛋白酶，主要侵犯 CD4⁺ T 淋巴细胞。"},{"k":"致病","t":"经性接触、血液和母婴传播；病毒 RNA 逆转录为 DNA 后整合入宿主基因组，逐步破坏细胞免疫，最终导致艾滋病（AIDS）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0574","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["24"],"q":"真核生物和原核生物转录的区别。","points":[{"k":"聚合酶不同","t":"原核只用一种 RNA 聚合酶全酶，σ 因子识别启动子；真核有 RNA 聚合酶 Ⅰ、Ⅱ、Ⅲ，并需通用转录因子。"},{"k":"启动子元件","t":"原核靠 −10 区（TATAAT）与 −35 区；真核靠 TATA 框、CAAT 框、GC 框，并受增强子、沉默子调控。"},{"k":"转录翻译关系","t":"原核无核膜，转录与翻译偶联进行；真核在核内转录，加工后运出核才翻译。"},{"k":"产物结构","t":"原核多为多顺反子 mRNA，一条 mRNA 编码多个蛋白；真核为单顺反子 mRNA。"},{"k":"转录后加工","t":"真核需加 5′帽、3′polyA 尾并剪接去除内含子；原核一般不需加工。"},{"k":"终止方式","t":"原核靠 ρ 因子依赖或不依赖 ρ 的转录终止发夹；真核靠 polyA 信号与终止因子。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0575","subj":"631","chap":"一、染色体结构","type":"简答","years":["24"],"q":"染色体具备哪些作为遗传物质的特征？","points":[{"k":"能自我复制","t":"含复制起点，S 期以半保留方式复制，保证遗传信息代代相传。"},{"k":"能储存信息","t":"DNA 碱基序列以密码形式储存生物体全部遗传信息。"},{"k":"能表达信息","t":"经转录、翻译合成蛋白质，实现基因的生物学功能。"},{"k":"能产生变异","t":"可发生基因突变、基因重组和染色体畸变，为物种进化提供原材料。"},{"k":"结构稳定均分","t":"组蛋白包装、着丝粒与端粒保证结构稳定，有丝分裂时染色体均等分配到两个子细胞。"},{"k":"含量恒定","t":"同一物种体细胞染色体数目与 DNA 含量恒定（2n），配子为 n。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0576","subj":"631","chap":"综合","type":"简答","years":["24"],"q":"DNA 结合结构域有哪些。","points":[{"k":"螺旋-转角-螺旋","t":"HTH：两个 α-螺旋由 β 转角连接，靠识别螺旋插入 DNA 大沟，见于原核阻遏蛋白与真核同源域蛋白。"},{"k":"锌指结构","t":"Zn²⁺ 由 Cys₂/His₂ 配位形成指状结构，插入 DNA 大沟，见于 TFⅢA 和类固醇激素受体。"},{"k":"亮氨酸拉链","t":"bZIP：两条 α-螺旋以亮氨酸侧链拉链式二聚化，其碱性区结合 DNA，如 AP-1、CREB。"},{"k":"螺旋-环-螺旋","t":"bHLH：两个 α-螺旋由可变环连接，二聚化后碱性区结合 DNA，如 MyoD、Myc。"},{"k":"同源域","t":"Homeodomain：约 60 个氨基酸组成的三螺旋结构，见于 Hox 基因产物，调控发育。"},{"k":"HMG盒","t":"HMG box 结合 DNA 小沟并使 DNA 弯曲，参与染色质重塑与转录调控。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0577","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["24"],"q":"核糖体的活性中心有哪些。","points":[{"k":"肽酰转移酶中心","t":"由大亚基 23S（原核）/28S（真核）rRNA 催化肽键形成，本质是核酶，是核糖体最核心的活性中心。"},{"k":"A位点","t":"氨酰-tRNA 结合位点，接受新进入的氨酰-tRNA。"},{"k":"P位点","t":"肽酰-tRNA 位点，容纳携带延伸中肽链的 tRNA。"},{"k":"E位点","t":"退出位点，释放卸下氨基酸的空载 tRNA。"},{"k":"mRNA结合位","t":"小亚基（30S/40S）提供 mRNA 结合位点与密码子-反密码子配对场所。"},{"k":"因子结合位","t":"提供起始因子、延伸因子（EF-Tu、EF-G）和终止释放因子的结合区域。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0578","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["24"],"q":"Gateway 大规模克隆技术的原理及步骤。","points":[{"k":"重组原理","t":"基于 λ 噬菌体位点特异性重组：attB×attP 生成 attL+attR（BP 酶催化），attL×attR 生成 attB+attP（LR 酶催化）。"},{"k":"构建入门克隆","t":"PCR 引物两端加 attB 接头，扩增目的基因后与含 attP 的供体载体进行 BP 反应，得到入门克隆。"},{"k":"LR重组","t":"入门克隆与含 attR1-ccdB-attR2 的目的载体进行 LR 反应，目的基因定向转移到表达载体。"},{"k":"正向筛选","t":"ccdB 基因产物对大肠杆菌有毒，未重组的载体使宿主致死，只有重组成功的克隆能存活。"},{"k":"技术优点","t":"不需限制酶和连接酶，定向、高效、可把同一基因平行转移到多种表达载体，适合大规模克隆。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0579","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["24"],"q":"真核 DNA 复制的特征和过程","points":[{"k":"多起点双向","t":"每条染色体有多个复制起点，双向复制形成复制眼，S 期分批激活，缩短复制时间。"},{"k":"起始识别","t":"ORC 结合复制起点，招募 Cdc6、Cdt1 装载 MCM 解旋酶，组装成前复制复合体。"},{"k":"解旋与引发","t":"CDK/DDK 磷酸化激活 MCM 解旋，RPA 稳定单链，DNA 聚合酶 α-引物酶合成 RNA 引物。"},{"k":"链的延伸","t":"DNA 聚合酶 ε 合成前导链，聚合酶 δ 合成滞后链冈崎片段；PCNA 为滑动夹，RFC 负责装载。"},{"k":"引物去除连接","t":"RNase H 与 FEN1 切除 RNA 引物，聚合酶 δ 填补缺口，DNA 连接酶 Ⅰ 封口。"},{"k":"端粒与包装","t":"端粒酶延长 3′端解决末端缩短问题；CAF-1 结合组蛋白装配核小体。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0580","subj":"631","chap":"综合","type":"论述","years":["24"],"q":"CAR-T 细胞疗法原理及优缺点。","points":[{"k":"制备流程","t":"采集患者外周血 T 细胞，用慢病毒或逆转录病毒导入 CAR 基因，体外激活扩增后回输体内。"},{"k":"CAR结构","t":"胞外 scFv 识别抗原，经跨膜区连接胞内 CD3ζ 激活域与 CD28 或 4-1BB 共刺激域。"},{"k":"杀伤原理","t":"scFv 以 MHC 非依赖方式结合肿瘤表面抗原，激活 T 细胞释放穿孔素、颗粒酶，直接杀伤靶细胞。"},{"k":"主要优点","t":"不受 MHC 限制，可识别糖脂和完整膜蛋白；回输后可扩增并形成记忆细胞，对复发难治 B 细胞白血病缓解率高。"},{"k":"毒性反应","t":"细胞因子释放综合征（CRS）、免疫效应细胞相关神经毒性（ICANS），以及 on-target off-tumor 的正常组织损伤。"},{"k":"局限与改进","t":"制备周期长、成本高，实体瘤疗效差，存在抗原逃逸与持久性不足；可用通用型 CAR、双靶点 CAR 改进。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0581","subj":"631","chap":"七、分子生物学技术","type":"论述","years":["24"],"q":"（1）设计实验验证 DNA 是遗传物质。\n（2）一个人淋巴细胞和肝脏中基因组是否相同，蛋白质组是否相同，代谢组是否相同。","points":[{"k":"肺炎链球菌转化","t":"Griffith 发现转化现象；Avery 用蛋白酶、RNase、DNase 分别处理转化因子，只有 DNase 使转化失活，证明转化因子是 DNA。"},{"k":"噬菌体标记","t":"³²P 标记 DNA、³⁵S 标记蛋白质，感染后搅拌离心，³²P 进入菌体、³⁵S 留在上清，证明 DNA 是遗传物质。"},{"k":"实验设计要点","t":"设 DNA 组、蛋白组、RNA 组对照，用专一水解酶处理转化因子，观察转化活性是否消失；放射性同位素标记需短时感染并充分搅拌。"},{"k":"基因组比较","t":"同一个体的淋巴细胞与肝细胞基因组基本相同；但 T、B 细胞存在受体基因重排和体细胞高频突变，属例外。"},{"k":"蛋白质组比较","t":"不同。细胞分化后差异基因表达，肝细胞表达白蛋白、尿素循环酶，淋巴细胞表达免疫相关蛋白。"},{"k":"代谢组比较","t":"不同。肝细胞以糖异生、尿素循环、脂代谢为主；淋巴细胞以糖酵解和核酸合成旺盛为特征。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0585","subj":"631","chap":"七、分子生物学技术","type":"简答","years":["11"],"q":"SDS-PAGE（类似生化）","points":[{"k":"结合SDS","t":"该技术将蛋白质与 SDS（十二烷基硫酸钠）相结合，使其带上大量负电荷。"},{"k":"掩盖电荷差别","t":"SDS 是阴离子、具有很高的负电荷，可掩盖不同蛋白质间原有的电荷差别。"},{"k":"变性伸展","t":"SDS 是变性剂，破坏蛋白质分子中的氢键与疏水作用，使大多数蛋白质分子伸展而呈同样的棒状。"},{"k":"按质量分离","t":"因此分离完全基于蛋白质质量的不同；由于凝胶分子筛效应，迁移率与分子质量的对数呈线性关系。"},{"k":"标准曲线测Mr","t":"用已知分子质量的标准蛋白作标准曲线，可由未知蛋白的迁移率求出其分子质量。"},{"k":"补：还原与局限","t":"需加 β-巯基乙醇或 DTT 还原二硫键使亚基解聚，故还原条件下测的是亚基分子量；该法不能测酶活性，也反映不出天然寡聚状态。"}],"note":"口径：依据《真题分类》资料原文。资料未提还原剂与凝胶系统，末点由教材口径补充（k 前标「补」）。","opts":[],"printed_answer":"","ref":true},{"id":"n0586","subj":"880","chap":"第四章 蛋白质","type":"填空","years":["03"],"q":"蛋白质水溶在 pH6.6 也有缓冲作用，这主要是因为蛋白质分子内（　　）基团的解离作用","points":[{"k":"答案","t":"咪唑基。组氨酸侧链咪唑基 pKa≈6.0，在 pH 6.6 附近半解离、缓冲能力最强；此时 α-羧基（pKa 2~3）已基本解离、ε-氨基（pKa≈10）尚未解离，均无缓冲作用。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0587","subj":"880","chap":"第四章 蛋白质","type":"填空","years":["03"],"q":"一个球状蛋白质，含 100 个氨基酸，估计它的分子量为（　　）±20%","points":[{"k":"答案","t":"11000（约 1.1×10⁴）。按平均残基分子量 110 估算：100×110=11000 Da，球状蛋白取 11000±20% 均在合理范围。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0588","subj":"880","chap":"第三章 氨基酸","type":"填空","years":["03"],"q":"谷胱甘肽由三种氨基酸通过肽键联结而成，这三种氨基酸分别是（　　）和（　　）","points":[{"k":"答案","t":"谷氨酸（Glu）、半胱氨酸（Cys）、甘氨酸（Gly）。谷胱甘肽为三肽 γ-Glu-Cys-Gly，谷氨酸以 γ-羧基成肽键，故含一个非常规的 γ-肽键。"}],"note":"题干只留两个空，实际由三种氨基酸组成，第三空应为甘氨酸。","opts":[],"printed_answer":""},{"id":"n0589","subj":"880","chap":"第十四章 氧化磷酸化","type":"填空","years":["03"],"q":"线粒体由（　　）和（　　）组成，内膜为（　　）只有部分小分子物质可以通过，外膜通透性较大，相对分子量小于（　　）的分子都可以通过，线粒体是生物体进行（　　）和（　　）转换的场所","points":[{"k":"答案","t":"外膜；内膜；半透性（选择透过性）膜；5000；物质代谢；能量。内膜通透性低，需经专一转运体，且含呼吸链与 ATP 合酶；外膜含孔蛋白，Mr<5000 的小分子与离子可自由通过。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0590","subj":"880","chap":"第三章 氨基酸","type":"填空","years":["03"],"q":"茚三酮法是通过测定反应中的释放出来的（　　）的量来计算参与反应的 α-氨基酸的量，产生的（　　）色化合物可以用（　　）法进行定性或定量测定，（　　）氨基酸与茚三酮反应直接生成黄色的化合物","points":[{"k":"答案","t":"CO₂；蓝紫（Ruhemann 紫）；比色（分光光度）；脯氨酸、羟脯氨酸（亚氨基酸）。茚三酮与 α-氨基酸共热脱羧脱氨，放出 CO₂ 和 NH₃，生成蓝紫色化合物，于 570 nm 比色定量；亚氨基酸无游离 α-氨基，生成黄色化合物，于 440 nm 测定。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0591","subj":"880","chap":"第七章 核酸","type":"填空","years":["03"],"q":"Southern 印迹法，Northern 印迹法和 Western 印迹法是分别用于研究（　　）（　　）和（　　）转移和鉴定的几种常规技术","points":[{"k":"答案","t":"DNA、RNA、蛋白质。Southern 检测 DNA、Northern 检测 RNA、Western 检测蛋白质，三者均为电泳分离后转膜，再用核酸探针或抗体识别。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0592","subj":"880","chap":"第七章 核酸","type":"填空","years":["03"],"q":"真核细胞的核糖体由（　　）S 亚基与（　　）S 亚基组成，多聚核糖体由（　　）个 mRNA 与（　　）个核糖体组成","points":[{"k":"答案","t":"60；40；1；多个（n 个）。真核 80S 核糖体由 60S 大亚基与 40S 小亚基组成；多聚核糖体是 1 条 mRNA 上串连多个核糖体同时翻译，提高蛋白质合成效率。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0593","subj":"880","chap":"第十章 糖酵解 糖异生","type":"填空","years":["03"],"q":"（　　）催化（　　）和 ATP 生成果糖 1，6-二磷酸，它的逆反应是由（　　）催化，逆向反应和正向反应不是同一个酶催化，构成了一个（　　）循环","points":[{"k":"答案","t":"磷酸果糖激酶-1（PFK-1）；6-磷酸果糖；果糖-1,6-二磷酸酶（FBPase-1）；底物（无效）循环。正向反应耗 ATP、逆向反应水解 C1 磷酸，两酶受果糖-2,6-二磷酸与激素反向调节，是糖酵解与糖异生的关键调控点。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0594","subj":"880","chap":"第五章 酶","type":"填空","years":["03"],"q":"金属离子对酶的激活作用有两种，一是作为（　　）二是作为（　　）","points":[{"k":"答案","t":"酶的组成成分（金属酶/辅基）；酶的激活剂。前者金属离子牢固结合于活性中心（如羧肽酶 A 的 Zn²⁺）参与催化；后者可逆结合、非必需，能提高酶活性（如 Mg²⁺ 激活激酶）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0595","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"填空","years":["03"],"q":"酶可以分为六类，即（　　）（　　）（　　）\n（　　）和（　　）","points":[{"k":"答案","t":"氧化还原酶、转移酶、水解酶、裂合酶、异构酶、连接酶（合成酶）。按国际酶学委员会（EC）依催化反应类型划分，编号依次为 EC1~EC6。"}],"note":"题干空格仅五处，与六类不符，按六类补全。","opts":[],"printed_answer":""},{"id":"n0596","subj":"880","chap":"第二十二章 基因工程与蛋白质工程","type":"填空","years":["03"],"q":"生物体内各类物质有各自的代谢途径，不同代谢途径可通过交叉点上的关键中间物而相互转化，使各代谢途径得以沟通形成网络，写出其中三个最关键的中介代谢物：\n（　　）（　　）（　　）","points":[{"k":"答案","t":"6-磷酸葡萄糖、丙酮酸、乙酰辅酶 A。6-磷酸葡萄糖是糖酵解、糖异生、磷酸戊糖途径与糖原合成/分解的交汇点；丙酮酸连接糖、脂与氨基酸代谢；乙酰 CoA 是三大物质分解的共同中间物并入三羧酸循环。"}],"note":"亦可答 α-酮戊二酸、草酰乙酸、磷酸二羟丙酮等，能说明途径交汇即可。","opts":[],"printed_answer":""},{"id":"n0597","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"名词解释","years":["06"],"q":"DNA 半保留复制","points":[{"k":"定义","t":"DNA 半保留复制，亲代 DNA 双链分开后各自作模板，按碱基互补配对合成子链，所得两个子代分子均含一条亲代链和一条新链。"},{"k":"意义","t":"是 DNA 复制的基本方式，保证遗传信息稳定传递；由 Meselson-Stahl 实验以 ¹⁵N 标记证实。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0598","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":["06"],"q":"RNA 的剪接（RNA splicing）","points":[{"k":"定义","t":"RNA 剪接，从 DNA 模板链转录出的最初转录产物中除去内含子，并将外显子连接起来形成一个连续 RNA 分子的过程。"},{"k":"方式","t":"核 mRNA 主要经剪接体按 GU-AG 规则剪接；Ⅰ、Ⅱ 类内含子可自我剪接，tRNA 前体由内切酶与连接酶加工。"}],"note":"","opts":[],"printed_answer":"从 DNA 模板链转录出的最初转录产物中除去内含子，并将外显子连接起来形成一个连续的 RNA 分子的过程。"},{"id":"n0599","subj":"631","chap":"七、分子生物学技术","type":"名词解释","years":["06"],"q":"核酸的分子杂交","points":[{"k":"概念定义","t":"利用核酸变性与复性的性质，按碱基互补配对原则，将两条不同来源的核苷酸链在试管中变性后慢慢冷却复性，若某些区域序列相同即可形成杂合双链分子。"},{"k":"杂交类型","t":"杂交可发生于 DNA 与 DNA 之间，也可发生于 DNA 与 RNA 之间。"},{"k":"补：应用","t":"可用于 Southern 印迹（DNA）、Northern 印迹（RNA）与原位杂交等，以标记探针检测特定序列，特异性由温度、盐浓度等杂交严格性控制。"}],"note":"口径：依据《真题分类》资料原文。资料只给定义与杂交类型，第三点应用为教材口径补充（k 前标「补」）。","opts":[],"printed_answer":"","ref":true},{"id":"n0600","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"名词解释","years":["06"],"q":"细菌转化","points":[{"k":"定义","t":"细菌转化，受体菌直接摄取环境中游离的裸露 DNA 片段，使其进入细胞并整合到基因组，从而获得新的遗传性状的过程。"},{"k":"条件与意义","t":"需处于感受态，Ca²⁺ 处理、电击可诱导；Griffith 与 Avery 实验由此证明 DNA 是遗传物质，也是基因工程的基础。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0601","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":["06"],"q":"外显子与内含子","points":[{"k":"定义","t":"外显子与内含子，是真核基因内部的两类序列：外显子为最终保留在成熟 RNA 中的编码序列，内含子为剪接时被切除的非编码间隔序列。"},{"k":"特点","t":"内含子多以 GU 起始、AG 终止，由剪接体去除；外显子-内含子结构使同一基因经可变剪接产生多种蛋白质。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0602","subj":"631","chap":"综合","type":"名词解释","years":["06"],"q":"多基因病","points":[{"k":"定义","t":"多基因病，由两对以上基因与环境因素共同作用所致的疾病，不呈典型孟德尔遗传，表现为家族聚集和性状连续变异，如高血压、糖尿病。"},{"k":"特点","t":"患者同胞再发风险明显高于群体发病率，且随亲缘系数降低而下降；以易患性阈值模型解释，靠连锁分析和全基因组关联研究定位易感基因。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0603","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"名词解释","years":["06"],"q":"基因表达调控","points":[{"k":"定义","t":"基因表达调控，指细胞在转录、转录后加工、翻译及翻译后各水平上，对基因表达的时间、空间和强度进行选择性控制的过程。"},{"k":"层次","t":"原核以操纵子（如 lac 操纵子）为主，主要控制转录起始；真核有染色质重塑、顺式元件与反式因子、表观修饰、可变剪接和 miRNA 等多级调控。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0604","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"名词解释","years":["06"],"q":"基因克隆","points":[{"k":"定义","t":"基因克隆，将目的基因片段与载体在体外重组，导入宿主细胞后随载体一起复制、扩增，获得大量同一 DNA 片段的技术。"},{"k":"基本步骤","t":"目的基因获取（PCR 或酶切）→ 与载体连接 → 转化宿主 → 筛选鉴定（抗性、蓝白斑、探针杂交）；是基因工程的核心环节。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0605","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"填空","years":["06"],"q":"1965 年法国科学家 Jacob 和 Monod 由于提出并（乳糖操纵子）…（mRNA 分子）","points":[{"k":"答案","t":"乳糖操纵子；mRNA 分子。1965 年 Jacob 与 Monod 提出乳糖操纵子模型，首次阐明转录水平的基因表达调控；同年提出信使 RNA 概念，认为 mRNA 携带遗传信息指导蛋白质合成。"}],"note":"","opts":[],"printed_answer":"乳糖操纵子；mRNA 分子"},{"id":"n0606","subj":"631","chap":"一、染色体结构","type":"填空","years":["06"],"q":"核小体连接的念珠状结构是（DNA）和（组蛋白）组成的染色体纤维细丝构成。","points":[{"k":"答案","t":"DNA；组蛋白。核小体为染色质基本单位：146 bp DNA 盘绕组蛋白八聚体（H2A、H2B、H3、H4 各两分子）1.75 圈，H1 结合连接 DNA，串成 10 nm 念珠状纤维。"}],"note":"","opts":[],"printed_answer":"DNA；组蛋白"},{"id":"n0607","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"填空","years":["06"],"q":"tRNA 在蛋白质合成中处于关键地位，它不但为每个（密码子）翻译成氨基酸提供了结合体，还为准确无误的将所有氨基酸搬运到（mRNA 与核糖体复合物）提供了运送载体。","points":[{"k":"答案","t":"密码子；mRNA 与核糖体复合物。tRNA 一端反密码子与 mRNA 密码子互补配对，另一端 3'-CCA 以酯键携带特定氨基酸，把氨基酸运至核糖体按序成肽。"}],"note":"","opts":[],"printed_answer":"密码子；mRNA 与核糖体复合物"},{"id":"n0608","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"填空","years":["06"],"q":"能够诱导操纵子但不是代谢底物的化合物称为（负控）诱导物，这种化合物同（阻遏）蛋白质结合，并使之与操纵基因分离。","points":[{"k":"答案","t":"负控；阻遏。这类化合物不参与代谢、只起诱导作用，与阻遏蛋白结合使其构象改变并从操纵基因解离，从而启动转录。"}],"note":"卷面作「负控诱导物」，教材规范名为「安慰诱导物（gratuitous inducer）」，如 IPTG；正文从卷面。","opts":[],"printed_answer":"负控；阻遏"},{"id":"n0609","subj":"631","chap":"一、染色体结构","type":"填空","years":["06"],"q":"染色体上的蛋白质主要包括 1 的蛋白）和（101 蛋白）（或与 DNA 结合的蛋白可分为组蛋白和非组蛋白）","points":[{"k":"答案","t":"组蛋白；非组蛋白。组蛋白（H1、H2A、H2B、H3、H4）与 DNA 结合构成核小体；非组蛋白种类多、 turnover 快，参与复制、转录调控与染色质高级结构维持。"}],"note":"卷面答案「1 的蛋白／101 蛋白」为扫描乱码，无法采信，按教材正文补正。","opts":[],"printed_answer":"1 的蛋白；101 蛋白（或与 DNA 结合的蛋白可分为组蛋白和非组蛋白）"},{"id":"n0610","subj":"631","chap":"一、染色体结构","type":"填空","years":["06"],"q":"染色体上带有遗传信息的一段 DNA 序列叫（基因），它负责编码一个蛋白质或一条多肽链，但也发现在一些细菌和动物病毒中，同一种 DNA 能携带两种不同蛋白质的信息，这段 DNA 又叫（重叠基因）","points":[{"k":"答案","t":"基因；重叠基因。基因是染色体上携带遗传信息、编码一条多肽链或一种功能 RNA 的 DNA 序列；重叠基因指同一段 DNA 因阅读框不同而编码两种蛋白质，见于部分噬菌体与动物病毒。"}],"note":"","opts":[],"printed_answer":"基因；重叠基因"},{"id":"n0611","subj":"631","chap":"一、染色体结构","type":"填空","years":["06"],"q":"基因扩增是指（一段相同序列基因大量复制）的现象，它使细胞在短期内产生大量的基因产物以满足生长发育，是基因活性调控的一种方式，基因重排是指（不同基因在染色体上的重新排序）。","points":[{"k":"答案","t":"一段相同序列的基因大量复制；不同基因在染色体上的重新排序。基因扩增（如抗药细胞中 DHFR 基因扩增）短期内大量产生基因产物；基因重排（如免疫球蛋白基因重排）改变基因位置与表达组合，二者都属基因活性调控方式。"}],"note":"","opts":[],"printed_answer":"一段相同序列基因大量复制；不同基因在染色体上的重新排序"},{"id":"n0612","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"填空","years":["06"],"q":"基因组克隆的主要载体系统还有（噬菌体载体）和（质粒载体）等。","points":[{"k":"答案","t":"噬菌体载体；质粒载体。λ 噬菌体载体可插入 15~20 kb 片段且筛选方便，质粒载体（如 pBR322、pUC 系列）操作简便、拷贝数高，另有柯斯质粒、YAC 等。"}],"note":"","opts":[],"printed_answer":"噬菌体载体；质粒载体"},{"id":"n0613","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"填空","years":["06"],"q":"重组 DNA 实验中常见的主要工具酶有（限制性内切酶）、（II 型连接酶）和大肠杆菌 DNA 聚合酶 1 等。","points":[{"k":"答案","t":"限制性内切酶；Ⅱ 型连接酶。前者识别回文序列并在特定位点切割双链 DNA，后者封闭相邻片段间的磷酸二酯键切口，两者与 DNA 聚合酶Ⅰ 同为重组 DNA 的基本工具酶。"}],"note":"卷面「Ⅱ 型连接酶」疑为「DNA 连接酶（常用 T4 DNA 连接酶）」之误；正文从卷面。","opts":[],"printed_answer":"限制性内切酶；II 型连接酶"},{"id":"n0614","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"填空","years":["06"],"q":"在蛋白质合成过程中氨酰-tRNA 合成酶是一类催化（tRNA 氨基酸）结合的特异性酶。","points":[{"k":"答案","t":"tRNA 氨基酸，即氨基酸与 tRNA 结合（氨酰化）。氨酰-tRNA 合成酶催化氨基酸羧基与 tRNA 3'-CCA 末端腺苷的 2'/3'-OH 成酯键，并借校对功能保证翻译准确。"}],"note":"","opts":[],"printed_answer":"tRNA 氨基酸"},{"id":"n0615","subj":"631","chap":"综合","type":"选择","years":["06"],"q":"双链 DNA 中碱基对有（）","points":[{"k":"答案","t":"B。双链 DNA 中 A 与 T、G 与 C 互补配对，碱基对只有 A-T（T-A）和 G-C（C-G）两种；A-U 只出现在 RNA 中。"}],"note":"","opts":["A. A-U；C-G","B. C-G；T-A","C. C-A；G-T","D. T-A；U-C"],"printed_answer":"B"},{"id":"n0616","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"选择","years":["06"],"q":"1953 年 Watson 和 Crick 提出（）","points":[{"k":"答案","t":"A。1953 年 Watson 与 Crick 依据 X 线衍射结果提出 DNA 双螺旋结构模型；半保留复制是随后提出的假说，三联体密码由 1961 年 Nirenberg 等实验证明。"}],"note":"","opts":["A. 多核苷酸 DNA 链通过氢键连接成一个双螺旋结构","B. DNA 的复制是半保留的","C. 三个连续的核苷酸代表一个遗传密码","D. 遗传物质是 DNA 而非 RNA"],"printed_answer":"A"},{"id":"n0617","subj":"631","chap":"一、染色体结构","type":"选择","years":["06"],"q":"基因组是（）","points":[{"k":"答案","t":"D（卷面）。基因组指一个生物体单倍体细胞所含的全部遗传信息，即一套染色体的 DNA 序列总和，包含编码区与非编码区，不等于「所有基因的分子总量」。"}],"note":"选项残缺，卷面仅存 A 项；按卷面取 D。","opts":["A. 一个生物体内所有基因的分子总量"],"printed_answer":"D"},{"id":"n0618","subj":"880","chap":"第七章 核酸","type":"选择","years":[],"q":"DNA 分子中碱基配对主要依赖于______。","points":[{"k":"答案","t":"B。碱基对之间由氢键维持（A-T 两个、G-C 三个）；磷酸二酯键才是共价键，二硫键与盐键不参与碱基配对。"}],"note":"","opts":["A.二硫键","B.氢键","C.共价键","D.盐键"],"printed_answer":"B"},{"id":"n0619","subj":"880","chap":"第六章 维生素与辅酶","type":"选择","years":[],"q":"在紫外 340nm 附近有紫外吸收峰的是______。","points":[{"k":"答案","t":"B。NADPH 与 NADH 的还原型烟酰胺环在 340 nm 有特征吸收峰，是脱氢酶活力测定的基础；NAD⁺、NADP⁺ 吸收峰在 260 nm，FAD、FMN 在 450 nm 附近。"}],"note":"","opts":["A.NAD⁺","B.NADPH","C.FAD","D.FMN"],"printed_answer":"B"},{"id":"n0620","subj":"880","chap":"第四章 蛋白质","type":"选择","years":[],"q":"毛发中蛋白质的主要构象是______。","points":[{"k":"答案","t":"A。毛发主要由 α-角蛋白构成，多肽链盘绕成 α-螺旋再组装为原纤维，靠二硫键交联；D 项 α-角蛋白是蛋白质名称而非构象类型。"}],"note":"","opts":["A.α-螺旋","B.β-折叠","C.无规卷曲","D.α-角蛋白"],"printed_answer":"A"},{"id":"n0621","subj":"880","chap":"第七章 核酸","type":"选择","years":[],"q":"在某生物中分离出的核酸，经分析其碱基组成为 A 占 35%，C 占 22%，G 占 23%，T 占 20%，则该核酸为______。","points":[{"k":"答案","t":"C。含 T 不含 U 说明是 DNA；又 A(35%)≠T(20%)、G(23%)≠C(22%)，不符合双链互补规则，故为单链 DNA。"}],"note":"","opts":["A.双链 DNA","B.双链 RNA","C.单链 DNA","D.单链 RNA"],"printed_answer":"C"},{"id":"n0622","subj":"880","chap":"第十一章 柠檬酸循环","type":"选择","years":[],"q":"三羧酸循环中______反应能产生 FADH₂。","points":[{"k":"答案","t":"A。琥珀酸脱氢酶（呼吸链复合体Ⅱ）以 FAD 为辅基，催化琥珀酸→延胡索酸并生成 FADH₂；其余三步生成 NADH 或 GTP。"}],"note":"","opts":["A.琥珀酸→延胡索酸","B.异柠檬酸→α-酮戊二酸","C.α-酮戊二酸→琥珀酰 CoA","D.苹果酸→草酰乙酸"],"printed_answer":"A"},{"id":"n0623","subj":"880","chap":"第三章 氨基酸","type":"选择","years":[],"q":"含有 Val、Asp 和 Arg 的氨基酸混合液在 pH 6.0 时电泳，这些氨基酸从负极到正极的排列顺序为______","points":[{"k":"答案","t":"C（卷面）。按 pI 判断：Arg（10.76）带正电移向负极、Val（5.96）近中性居中、Asp（2.77）带负电移向正极，从负极到正极应为 Arg、Val、Asp。"}],"note":"卷面作 C，但按电泳原理正确答案应为 B（Arg、Val、Asp）；正文从卷面并说明。","opts":["A. Val、Asp、Arg","B. Arg、Asp、Val","C. Asp、Val、Arg","D. Asp、Arg、Val"],"printed_answer":"C"},{"id":"n0624","subj":"880","chap":"第十六章 氨基酸代谢","type":"选择","years":[],"q":"导致苯丙酮尿症是因为婴儿体内缺乏______。","points":[{"k":"答案","t":"B。苯丙氨酸羟化酶缺乏使苯丙氨酸不能羟化为酪氨酸，转而经转氨生成苯丙酮酸由尿排出，即苯丙酮尿症；该酶属加单氧酶，辅因子为四氢生物蝶呤。"}],"note":"","opts":["A.酪氨酸羟化酶","B.苯丙氨酸羟化酶","C.苯丙氨酸转氨酶","D.酪氨酸转氨酶"],"printed_answer":"B"},{"id":"n0625","subj":"880","chap":"第七章 核酸","type":"选择","years":[],"q":"DNA 复制过程中，______是不需要的","points":[{"k":"答案","t":"B。细胞内复制需要解旋酶、引物酶、DNA 聚合酶、连接酶等；限制性内切酶是体外切割 DNA 的工具酶，不参与复制。"}],"note":"","opts":["A. DNA 连接酶","B.限制性内切酶","C.解链酶","D.DNA 聚合酶"],"printed_answer":"B"},{"id":"n0626","subj":"880","chap":"第十章 糖酵解 糖异生","type":"选择","years":[],"q":"位于糖酵解、糖异生、磷酸戊糖途径、糖原合成和分解各条代谢途径交汇点上的化合物是______","points":[{"k":"答案","t":"B。6-磷酸葡萄糖是糖酵解、糖异生、磷酸戊糖途径与糖原合成/分解的共同中间物，位于各途径交汇点，其去向决定代谢流向。"}],"note":"","opts":["A.1-磷酸葡萄糖","B.6-磷酸葡萄糖","C.1,6-二磷酸葡萄糖","D.6-磷酸果糖"],"printed_answer":"B"},{"id":"n0627","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":[],"q":"如果饮食中不含葡萄糖，试问食用奇数脂肪酸好还是偶数脂肪酸好？为什么？","points":[{"k":"选择结论","t":"饮食中不含葡萄糖时应选奇数碳脂肪酸，因为它能净生成糖。"},{"k":"末端产物","t":"奇数脂肪酸 β-氧化终产物为丙酰 CoA，不是乙酰 CoA。"},{"k":"生糖途径","t":"丙酰 CoA → 甲基丙二酰 CoA → 琥珀酰 CoA，进入三羧酸循环生成草酰乙酸，可经糖异生补充血糖。"},{"k":"偶数脂肪酸局限","t":"偶数脂肪酸只产乙酰 CoA，丙酮酸脱氢酶反应不可逆，乙酰 CoA 不能净合成葡萄糖。"},{"k":"酮体风险","t":"缺糖时草酰乙酸被糖异生消耗，乙酰 CoA 堆积转向酮体生成，加重酮症酸中毒。"}],"note":"丙酰 CoA 只占一分子奇数脂肪酸末端一个，生糖量有限；其代谢需维生素 B12 参与甲基丙二酰 CoA 变位酶反应。","opts":[],"printed_answer":""},{"id":"n0628","subj":"880","chap":"第三章 氨基酸","type":"简答","years":[],"q":"某九肽氨基酸组成为两个 Gly 和两个 Phe，及 Tyr、Met、Asp、Arg、Pro，经胰凝乳蛋白酶水解得到四肽和五肽，四肽组成为 Phe、Tyr、Gly 和 Pro。此九肽的 CNBr 处理产物经阳离子交换树脂层析并洗脱得到一组组成为 Arg、Phe 和 Gly 的三肽。该九肽经胰蛋白酶水解得到 Phe，如果用 DNFB 反应后在水解测得 DNP-Tyr。请写出此九肽顺序及解析过程。","points":[{"k":"N端判定","t":"DNFB 反应后水解测得 DNP-Tyr，说明 N 端为 Tyr。"},{"k":"C端判定","t":"胰蛋白酶切 Arg 羧基侧后得到游离 Phe，说明 C 端序列为 -Arg-Phe，Phe 在末端。"},{"k":"CNBr片段","t":"CNBr 切 Met 羧基侧，所得含 Arg、Phe、Gly 的三肽结合 C 端推定即 Gly-Arg-Phe。"},{"k":"胰凝乳片段","t":"胰凝乳蛋白酶切 Phe、Tyr 羧基侧，得四肽（Phe、Tyr、Gly、Pro）和五肽；Tyr-Pro 键因 Pro 阻碍不被水解，四肽为 Tyr-Pro-Gly-Phe。"},{"k":"排出全序","t":"剩余五肽为 Asp-Met-Gly-Arg-Phe，故九肽为 Tyr-Pro-Gly-Phe-Asp-Met-Gly-Arg-Phe。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0629","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"为人体血液中含有大量用于合成蛋白质的氨基酸，但含量并不平衡，为什么天冬酰胺和丙氨酸的含量比其他氨基酸的含量多？","points":[{"k":"丙氨酸循环","t":"肌肉中糖酵解产生的丙酮酸接受支链氨基酸的氨基生成 Ala，经血液运至肝作为糖异生底物。"},{"k":"Asn运氮","t":"肌肉中 Asp 接受氨基生成 Asn；Asn 中性、溶解度高、化学性质稳定，是安全的运氮形式。"},{"k":"肝内释放","t":"肝中天冬酰胺酶水解 Asn 为 Asp 与 NH₃，氨进入尿素循环；Ala 脱氨生成丙酮酸供糖异生。"},{"k":"持续生成","t":"外周组织不断产生、肝不断摄取，二者在血中始终维持较高浓度。"},{"k":"合成原料","t":"两者也是肝合成血浆蛋白的主要原料，血浆蛋白周转快，血中氨基酸池较大。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0630","subj":"880","chap":"第十一章 柠檬酸循环","type":"简答","years":[],"q":"根据下列酶促反应回答问题：\n谷氨酸 + 丙酮酸 → α-酮戊二酸 + 丙氨酸\n（1）写出上述酶促反应所需要的酶及其辅酶\n（2）如果食物中富含 Ala，缺乏 Asp，可是看不到缺乏 Asp 的症状，请你说原因。","points":[{"k":"酶与辅酶","t":"丙氨酸氨基转移酶（ALT，即 GPT），辅酶为磷酸吡哆醛（PLP，维生素 B6）。"},{"k":"转氨方向","t":"谷氨酸 + 丙酮酸 ⇌ α-酮戊二酸 + 丙氨酸，氨基由谷氨酸转给丙酮酸。"},{"k":"Asp内源合成","t":"草酰乙酸经谷草转氨酶（AST）接受氨基即生成 Asp，草酰乙酸来自三羧酸循环。"},{"k":"Asn水解补充","t":"体内 Asn 经天冬酰胺酶水解也生成 Asp，故 Asp 属非必需氨基酸。"},{"k":"Ala促生成","t":"食物富含 Ala，使 α-酮戊二酸大量氨基化生成谷氨酸，为 AST 提供氨基供体，进一步促 Asp 生成。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0631","subj":"880","chap":"第十四章 氧化磷酸化","type":"简答","years":[],"q":"试述为什么煤气（CO）中毒时，为什么人体内耗氧量会下降？","points":[{"k":"占据血红素","t":"CO 与 Hb 的亲和力约为 O₂ 的 210 倍，占据 Fe²⁺ 配位位点形成碳氧血红蛋白（HbCO），携氧容量下降。"},{"k":"曲线左移","t":"CO 使剩余 Hb 对 O₂ 的亲和力升高，氧解离曲线左移，O₂ 难以在组织释放。"},{"k":"抑制细胞色素氧化酶","t":"CO 与细胞色素 c 氧化酶（复合体Ⅳ）的 Fe²⁺ 结合，阻断电子传递，细胞不能利用氧。"},{"k":"内窒息","t":"血氧含量低而组织不能摄氧，静脉血氧分压反而升高，动静脉氧差减小，称内窒息。"},{"k":"耗氧下降","t":"组织缺氧抑制氧化代谢并反射性抑制呼吸循环，整体耗氧量下降。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0632","subj":"880","chap":"第十四章 氧化磷酸化","type":"简答","years":[],"q":"糖酵解中间产物氧化磷酸化的意义？","points":[{"k":"大幅提高产能","t":"1 分子葡萄糖仅靠酵解净得 2 ATP，经氧化磷酸化彻底氧化可得 30~32 ATP，能量利用效率显著提高。"},{"k":"再生NAD⁺","t":"胞质 NADH 经 α-磷酸甘油或苹果酸-天冬氨酸穿梭进入呼吸链氧化，使 NAD⁺ 再生，保证酵解持续进行。"},{"k":"连通三羧酸循环","t":"丙酮酸氧化脱羧生成乙酰 CoA，把糖酵解与三羧酸循环、氧化磷酸化连接成完整氧化通路。"},{"k":"提供合成碳骨架","t":"3-磷酸甘油、磷酸二羟丙酮、丙酮酸可作合成脂肪和氨基酸的碳骨架，起回补反应作用。"},{"k":"调节代谢流","t":"ATP/ADP 与 NADH/NAD⁺ 比值反馈调节磷酸果糖激酶-1 与丙酮酸脱氢酶，控制碳流方向。"}],"note":"题干表述简略，按「糖酵解产生的还原当量与中间产物进入氧化磷酸化的生理意义」作答。","opts":[],"printed_answer":""},{"id":"n0633","subj":"880","chap":"第七章 核酸","type":"简答","years":[],"q":"什么是核苷酸代谢抑制物？有什么作用","points":[{"k":"定义","t":"结构与核苷酸或其前体相似的化合物，能竞争性抑制核苷酸合成酶或掺入核酸，阻断核苷酸代谢。"},{"k":"嘌呤类似物","t":"6-巯基嘌呤、6-硫鸟嘌呤经代谢成核苷酸，反馈抑制 PRPP 酰胺转移酶，并掺入 DNA 使复制出错。"},{"k":"嘧啶类似物","t":"5-氟尿嘧啶抑制胸苷酸合酶，阿糖胞苷抑制 DNA 聚合酶。"},{"k":"叶酸拮抗剂","t":"甲氨蝶呤抑制二氢叶酸还原酶；氮杂丝氨酸拮抗谷氨酰胺，阻断嘌呤环合成。"},{"k":"临床应用","t":"用于抗肿瘤、抗病毒和免疫抑制，如阿昔洛韦治疱疹、别嘌醇抑制黄嘌呤氧化酶降尿酸。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0634","subj":"880","chap":"第五章 酶","type":"名词解释","years":["15"],"q":"Ribozyme","points":[{"k":"定义","t":"核酶是一类具有催化功能的 RNA 分子，可通过催化靶位点 RNA 链中磷酸二酯键的断裂，特异性地剪切底物 RNA 分子，从而阻断基因的表达。"},{"k":"分类与意义","t":"可分为剪切型核酶和剪接型核酶；其发现证明酶并非都是蛋白质，支持 RNA 世界假说。"}],"note":"口径：依据《真题分类》资料原文（定义与分类）；「证明酶并非都是蛋白质、支持 RNA 世界假说」为教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0635","subj":"880","chap":"第十四章 氧化磷酸化","type":"名词解释","years":["15"],"q":"P/O ratio","points":[{"k":"定义","t":"P/O 比值，指氧化磷酸化中每消耗 1 原子氧（1/2 O₂）所生成的 ATP 分子数，用来衡量线粒体氧化与磷酸化的偶联效率。"},{"k":"数值","t":"NADH 经呼吸链氧化 P/O 约 2.5，FADH₂ 约 1.5；解偶联剂使其降低，可据此判断偶联程度。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0636","subj":"880","chap":"第七章 核酸","type":"名词解释","years":["15"],"q":"Melting temperature(Tm)","points":[{"k":"定义","t":"在 DNA 热变性中，紫外吸收增加的中点值所对应的温度称为熔解温度（Tm），也称热解链温度，反映双链的稳定性。"},{"k":"影响因素","t":"Tm 与 G+C 含量正相关（G-C 对有 3 个氢键），随离子强度升高而升高，并与分子大小、核酸类型有关，是 PCR 退火温度设计的依据。"}],"note":"口径：依据《真题分类》资料原文（仅一句定义），影响因素为教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0637","subj":"880","chap":"第五章 酶","type":"名词解释","years":["15"],"q":"Allosteric effect","points":[{"k":"定义","t":"当某些化合物与酶分子中的别构部位可逆结合后，酶分子构象发生改变，使活性部位对底物的结合与催化作用受到影响，从而调节酶促反应速度及代谢过程，这种效应称别构效应（变构效应）。"},{"k":"特点","t":"别构效应一般只存在于多亚基蛋白质中，亚基间的非共价作用是别构效应形成的基础；如 ATP 抑制、AMP 激活磷酸果糖激酶。"}],"note":"口径：依据《真题分类》资料原文（定义与结构基础），磷酸果糖激酶实例为教材补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0638","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"名词解释","years":["15"],"q":"Okazaki fragment","points":[{"k":"定义","t":"相对较短的 DNA 链（约 1000 个核苷酸残基），是在 DNA 滞后链（后随链）不连续合成期间生成的片段，由冈崎发现，故称冈崎片段。"},{"k":"补：成熟与半不连续","t":"资料未列：片段由 RNA 引物起始，RNase H 与 DNA 聚合酶Ⅰ切除引物并填补缺口，DNA 连接酶封口连成长链；因前导链连续、后随链分段合成，故 DNA 复制为半不连续复制。"}],"note":"口径：依据《真题分类》资料原文（仅定义）；片段成熟与半不连续复制为教材补充，真核片段较短（约 100~200 nt）亦属补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0639","subj":"880","chap":"第十章 糖酵解 糖异生","type":"名词解释","years":["15"],"q":"Glycolysis","points":[{"k":"定义","t":"指葡萄糖或糖原在无氧条件下分解为丙酮酸的过程，是生物最古老、最原始的一种获能方式，发生于细胞质基质中。"},{"k":"产物与能量","t":"经 10 步反应，1 分子葡萄糖可分解生成 2 分子丙酮酸、2 分子 ATP 和 2 分子 NADH＋H⁺。"}],"note":"口径：依据《真题分类》资料原文（定义与产物）。","opts":[],"printed_answer":"","ref":true},{"id":"n0640","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["15"],"q":"Ultrafiltration","points":[{"k":"定义","t":"超滤，利用半透膜两侧的压力差（外加压力或离心力）使小分子溶质与溶剂透膜、大分子被截留，从而分离、纯化并浓缩生物大分子的方法。"},{"k":"应用","t":"用于酶与蛋白质的浓缩、脱盐、缓冲液更换及病毒、细胞分离；按截留分子量选膜，须防浓差极化与膜污染。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0642","subj":"880","chap":"综合","type":"选择","years":["15"],"q":"能被 Benedict 试剂或费林试剂氧化？","points":[{"k":"答案","t":"c（两者都是）。葡萄糖有游离醛基，果糖的酮基在 Benedict/Fehling 试剂的碱性条件下经差向异构化为醛糖，二者都能把 Cu²⁺ 还原为砖红色 Cu₂O 沉淀。"}],"note":"","opts":["a. 葡萄糖","b. 果糖","c. 以上两者都是","d. 以上两者都不是"],"printed_answer":""},{"id":"n0643","subj":"880","chap":"第四章 蛋白质","type":"选择","years":["15"],"q":"从赖氨酸中分离出谷氨酸的可能性最小的方法是","points":[{"k":"答案","t":"d（葡萄糖凝胶过滤）。Lys（pI 9.74）与 Glu（pI 3.22）电荷差异大，纸层析、离子交换、电泳均可分离；二者分子量都小且相近，凝胶过滤按分子大小分离，分辨力最差。"}],"note":"","opts":["a. 纸层析","b. 阳离子交换层析","c. 阴离子交换层析","d. 葡萄糖凝胶过滤","e. 电泳"],"printed_answer":""},{"id":"n0644","subj":"880","chap":"综合","type":"选择","years":["15"],"q":"在酶的结构上十分重要，但在催化过程中极不可能和底物相互作用，它是","points":[{"k":"答案","t":"b（胱氨酸）。胱氨酸靠二硫键维持酶的空间构象，侧链无催化基团、不直接与底物作用；Glu、His、Tyr、Ser 的侧链常作为酸碱催化或共价催化的催化残基。"}],"note":"","opts":["a. 谷氨酸","b. 胱氨酸","c. 组氨酸","d. 酪氨酸","e. 丝氨酸"],"printed_answer":""},{"id":"n0645","subj":"880","chap":"第七章 核酸","type":"选择","years":["15"],"q":"在各类核酸核酸中，稀有碱基含量百分比最高的是","points":[{"k":"答案","t":"a（tRNA）。tRNA 含二氢尿嘧啶、假尿苷、次黄嘌呤核苷及多种甲基化碱基，稀有碱基可占核苷酸总数的 10% 以上，远高于 rRNA 与 mRNA。"}],"note":"","opts":["a. tRNA","b. 5SrRNA","c. mRNA"],"printed_answer":""},{"id":"n0646","subj":"880","chap":"第十章 糖酵解 糖异生","type":"选择","years":["15"],"q":"葡萄糖异生作用能使非糖前体在细胞中合成\"新的\"葡萄糖，下列化合物中哪一种除外？","points":[{"k":"答案","t":"d（Leu）。亮氨酸是生酮氨基酸，降解只生成乙酰 CoA 与乙酰乙酸，不能净合成葡萄糖；Asp、Glu、琥珀酸、PEP 均可经草酰乙酸或丙酮酸异生为糖。"}],"note":"","opts":["a. Asp","b. Glu","c. 琥珀酸","d. Leu","e. PEP"],"printed_answer":""},{"id":"n0647","subj":"880","chap":"第六章 维生素与辅酶","type":"选择","years":["15"],"q":"下列哪些化合物含有糖基？\n①ATP ②NAD ③RNA ④acetylCoA","points":[{"k":"答案","t":"e（1+2+3+4）。ATP 含核糖；NAD 含 AMP 部分（核糖+腺嘌呤）；RNA 骨架为核糖；乙酰 CoA 的辅酶 A 含 3'-磷酸腺苷，同样带核糖基，故四者都含糖基。"}],"note":"若只认「糖作为独立组分」而不计核苷酸中的核糖，会误选 a（1+2+3）；按化学组成应选 e。","opts":["a. 1+2+3","b. 1+3","c. 2+4","d. 4","e. 1+2+3+4"],"printed_answer":""},{"id":"n0648","subj":"880","chap":"第一章 糖类","type":"选择","years":["15"],"q":"下列有关多糖的陈述哪些是正确的？\n①多糖是生物的主要能源\n②多糖以线形形式或支链形式存在\n③多糖是细菌细胞壁的重要结构单元\n④多糖是信息分子","points":[{"k":"答案","t":"a（1+2+3）。淀粉、糖原等多糖是生物的主要储能形式；多糖有直链与支链两种存在形式；肽聚糖是细菌细胞壁的结构骨架。信息分子主要是糖蛋白、糖脂的寡糖链，不指多糖本身。"}],"note":"","opts":["a. 1+2+3","b. 1+3","c. 2+4","d. 4","e. 1+2+3+4"],"printed_answer":""},{"id":"n0649","subj":"880","chap":"第十五章 脂类代谢","type":"选择","years":["15"],"q":"下列说法中哪些适用于脂肪酸的 β-氧化作用","points":[{"k":"答案","t":"a、c。脂肪酸须先在胞质活化为脂酰 CoA，再经肉碱穿梭进入线粒体氧化；氧化步骤以 NAD⁺ 和 FAD 为受氢体（不是 NADP⁺），过程本身产能，持续进行不依赖 ATP 持续供应。"}],"note":"","opts":["a. 游离脂肪酸必须经辅酶 A 酯化","b. 该过程包括 NADP⁺ 的还原","c. 氧化在线粒体中进行","d. 持续 β-氧化取决于 ATP 的持续供应"],"printed_answer":""},{"id":"n0650","subj":"880","chap":"第十一章 柠檬酸循环","type":"选择","years":["15"],"q":"TCA 循环和有关的呼吸链反应中能产生 ATP 最多的步骤是什么？","points":[{"k":"答案","t":"c（α-酮戊二酸→琥珀酸）。该段含 α-酮戊二酸脱氢酶复合体生成的 1 NADH（2.5 ATP）、琥珀酰 CoA 合成酶生成的 1 GTP（1 ATP）、琥珀酸脱氢酶生成的 1 FADH₂（1.5 ATP），合计约 5 ATP，为四段中最多。"}],"note":"","opts":["a. 柠檬酸—异柠檬酸","b. 异柠檬酸—α-酮戊二酸","c. α-酮戊二酸—琥珀酸","d. 琥珀酸-苹果酸"],"printed_answer":""},{"id":"n0651","subj":"880","chap":"综合","type":"考点","years":["15"],"q":"哪一种酶属于共价催化？","points":[{"k":"答案","t":"胰凝乳蛋白酶（丝氨酸蛋白酶类）。其 Ser195 羟基与底物羰基碳形成共价酰基-酶中间物，随后水解脱离，属共价催化；糖原磷酸化酶、琥珀酰胆碱酯酶亦属此类。"}],"note":"原卷选项缺失。","opts":[],"printed_answer":""},{"id":"n0652","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"名词解释","years":["23"],"q":"同源重组","points":[{"k":"定义","t":"同源重组，指两条具有同源序列的 DNA 分子间发生断裂、片段交换并重新连接的遗传重组，如减数分裂中的交换和细菌 RecA 介导的重组。"},{"k":"机制","t":"双链断裂→末端加工→RecA/Rad51 介导链侵入形成 D 环与 Holliday 交叉→分支迁移→解离；功能为修复双链断裂、产生遗传多样性、整合外源基因。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0653","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"名词解释","years":["23"],"q":"Nothern 印记","points":[{"k":"定义","t":"Northern 印迹，将 RNA 经变性凝胶电泳按大小分离后转移至固相膜，再用标记探针杂交，检测特定 mRNA 的大小与表达量的技术。"},{"k":"要点","t":"与检测 DNA 的 Southern 印迹对应；可分析基因转录水平与剪接异构体，操作中须严格防止 RNase 污染。"}],"note":"题干“Nothern 印记”为 Northern 印迹的拼写错误，按 Northern 印迹作答。","opts":[],"printed_answer":""},{"id":"n0654","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"考点","years":["23"],"q":"蓝白斑","points":[{"k":"答案","t":"白斑为阳性重组子，蓝斑为含非重组质粒的菌落。载体带 lacZ'，与宿主 lacZΔM15 发生 α 互补产生有活性的 β-半乳糖苷酶，水解 X-gal 生成蓝色产物；外源片段插入多克隆位点破坏 lacZ'，不能互补，故呈白色。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0655","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["23"],"q":"启动子包含(tata 盒)","points":[{"k":"答案","t":"正确（√）。真核 RNA 聚合酶Ⅱ的 Ⅱ 类启动子核心区含 TATA 盒（-25~-30 bp，共有序列 TATAAAA），由 TBP/TFⅡD 识别；原核启动子不含 TATA 盒。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0656","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"考点","years":["23"],"q":"酵母质粒","points":[{"k":"答案","t":"2 μm 质粒（2μ circle）。这是酵母核内约 6.3 kb 的环状双链 DNA，拷贝数高、可自主复制，被改造成 YEp 系列游离型载体；另有 YRp、YCp、YAC 等人工载体。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0657","subj":"631","chap":"综合","type":"考点","years":["23"],"q":"eclo. 切除后得到什么长度的序列","points":[{"k":"答案","t":"按 EcoRI 位点 5'-GAATTC-3' 的个数切开：环状质粒切 n 次得 n 个片段，线状 DNA 切 n 次得 n+1 个片段，各片段长度为相邻位点间的碱基数。"}],"note":"题干为扫描残缺（「eclo.」应为 EcoRI），且未给序列或酶切图谱，无法给出具体片段长度。","opts":[],"printed_answer":""},{"id":"n0658","subj":"631","chap":"综合","type":"考点","years":["23"],"q":"哪个比例的融解温度最高(根据 GC 含量)","points":[{"k":"答案","t":"GC 含量最高的那个比例（Tm 最高）。G≡C 有 3 个氢键、碱基堆积力更强，GC 比例越高双链越难解开，融解温度越高，一般 GC 每增加 1% 约升 0.4 ℃。"}],"note":"原卷选项缺失，只能按 GC 比例判据作答。","opts":[],"printed_answer":""},{"id":"n0659","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"考点","years":["23"],"q":"组蛋白修饰阻止其分解","points":[{"k":"答案","t":"该说法指向「组蛋白修饰不引起其分解」。乙酰化、甲基化、磷酸化等共价修饰只改变染色质构象与转录活性，并不标记组蛋白进入降解途径；组蛋白代谢极慢、半衰期长，其更新不走泛素—蛋白酶体途径。"}],"note":"原卷选项缺失、题干只剩半句，按「组蛋白修饰与降解的关系」作答。","opts":[],"printed_answer":""},{"id":"n0660","subj":"631","chap":"七、分子生物学技术","type":"考点","years":["23"],"q":"电泳原理","points":[{"k":"答案","t":"带电颗粒在电场中向与其电荷相反的电极泳动，迁移率取决于电荷量、分子大小与形状。蛋白质以 pI 为界：pH＞pI 带负电移向正极，pH＜pI 带正电移向负极，pH=pI 净电荷为零不泳动；SDS-PAGE 中则按分子量分离。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0661","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["23"],"q":"载体是什么，有什么，特性","points":[{"k":"定义","t":"载体是能携带外源 DNA 片段进入宿主细胞并自我复制的 DNA 分子。"},{"k":"常见种类","t":"质粒、λ 噬菌体、黏粒、BAC/YAC 人工染色体，以及腺病毒、慢病毒等病毒载体。"},{"k":"自主复制","t":"含复制起点（ori），可在宿主内独立复制，拷贝数高、易于大量提取。"},{"k":"多克隆位点","t":"含多个单一限制酶切位点（MCS），便于外源片段定向插入。"},{"k":"选择标记","t":"带抗药基因或报告基因，用于筛选重组体，如 AmpR、LacZ 蓝白斑筛选。"},{"k":"装载与稳定","t":"分子小、装载量大、传代稳定；表达载体还需启动子、终止子和核糖体结合位点。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0662","subj":"631","chap":"综合","type":"简答","years":["23"],"q":"Pcr 的原理和影响因素","points":[{"k":"变性","t":"94~95 ℃ 使模板双链氢键断裂，解成单链。"},{"k":"退火","t":"降至 50~65 ℃，引物与模板上的互补序列特异性结合。"},{"k":"延伸","t":"72 ℃ 下 Taq DNA 聚合酶以 dNTP 为原料，沿 5′→3′ 方向合成新链。"},{"k":"指数扩增","t":"循环 n 次，目的片段约扩增 2ⁿ 倍，30 个循环可放大 10⁹ 倍。"},{"k":"关键影响因素","t":"引物设计（长度、GC 含量、Tm 差）、Mg²⁺ 浓度、退火温度、dNTP 与酶量、循环数、模板质量。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0663","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"简答","years":["23"],"q":"组蛋白修饰种类","points":[{"k":"乙酰化","t":"组蛋白乙酰转移酶（HAT）在赖氨酸上加乙酰基，中和正电荷、染色质松弛、促进转录；HDAC 作用相反。"},{"k":"甲基化","t":"在 Lys、Arg 上加 1~3 个甲基，可激活或抑制：H3K4me3 激活，H3K9me3、H3K27me3 抑制。"},{"k":"磷酸化","t":"Ser、Thr 残基磷酸化，如 H3S10ph 参与染色体凝集与转录激活。"},{"k":"泛素化","t":"在赖氨酸上加泛素，参与 DNA 损伤修复、转录调控和蛋白降解信号。"},{"k":"SUMO化与变体","t":"SUMO 化调节转录因子活性；还有 ADP-核糖基化，以及 H2A.Z、H3.3、CENP-A 等组蛋白变体替换。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0664","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["23"],"q":"三种 rna 在蛋白质合成中的功能","points":[{"k":"mRNA模板","t":"携带 DNA 的遗传信息，以密码子形式作为蛋白质合成模板；5′帽与 3′polyA 保护并调控翻译。"},{"k":"tRNA搬运","t":"3′端 CCA 结合特定氨基酸，反密码子与 mRNA 密码子互补配对，把氨基酸准确送到核糖体。"},{"k":"tRNA结构","t":"二级结构呈三叶草形，三级结构呈倒 L 形，含氨基酸臂、反密码子臂、TψC 环和 D 环。"},{"k":"rRNA催化","t":"与蛋白质组成核糖体，23S/28S rRNA 构成肽酰转移酶中心，催化肽键形成，本身是核酶。"},{"k":"rRNA定位","t":"小亚基 rRNA 参与 mRNA 结合与密码子识别，大亚基 rRNA 形成 tRNA 结合位点和肽链出口通道。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0665","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["23"],"q":"真核和原核基因表达特点","points":[{"k":"基因组织","t":"原核多为操纵子，功能相关基因成簇共转录为多顺反子；真核为单顺反子，各有独立启动子。"},{"k":"时空关系","t":"原核无核膜，转录与翻译偶联；真核核内转录、加工后出核翻译。"},{"k":"转录后加工","t":"真核需加 5′帽、3′polyA 尾和剪接；原核一般不需加工。"},{"k":"调控层次","t":"原核以转录水平（诱导、阻遏）为主；真核有染色质、转录、转录后、翻译及翻译后多级调控。"},{"k":"调控元件","t":"原核靠 −10/−35 区与操纵基因；真核靠 TATA 框、增强子、沉默子、绝缘子和转录因子。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0666","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["23"],"q":"基因组文库和 cdna 文库的区别和应用","points":[{"k":"构建模板","t":"基因组文库以基因组 DNA 为模板、用限制酶部分酶切构建；cDNA 文库以 mRNA 逆转录的 cDNA 构建。"},{"k":"内容差异","t":"基因组文库含内含子和调控序列、基因完整；cDNA 文库只含外显子，无内含子和启动子。"},{"k":"组织特异性","t":"基因组文库对同一物种各组织相同；cDNA 文库随组织与发育阶段不同，只含表达的基因。"},{"k":"库的容量","t":"基因组文库必须足够大以覆盖全部基因；cDNA 文库较小，但高丰度 mRNA 占比高。"},{"k":"用途","t":"基因组文库用于研究基因结构、启动子和染色体步行；cDNA 文库用于分离编码序列、表达克隆和 EST 分析。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0667","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["23"],"q":"DNA 复制过程中为什么前导链连续复制，滞后链不连续复制","points":[{"k":"聚合方向限制","t":"DNA 聚合酶只能催化 5′→3′ 合成，且不能从头起始，必须由引物提供 3′-OH。"},{"k":"模板反向平行","t":"两条模板链方向相反，复制叉解开后两条模板的走向不同。"},{"k":"前导链连续","t":"其模板为 3′→5′ 走向，聚合酶沿复制叉前进方向连续延伸，只需一个引物。"},{"k":"滞后链分段","t":"其模板为 5′→3′ 走向，聚合酶必须背离复制叉方向合成，随解旋分段生成冈崎片段。"},{"k":"多引物多片段","t":"每个冈崎片段都需新的 RNA 引物，随后切除引物、填补缺口并由连接酶封口。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0668","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"实验","years":["23"],"q":"用现代分子生物学技术基因沉默和基因敲除的原理和应用","points":[{"k":"RNAi原理","t":"双链 RNA 被 Dicer 切成 21~23 nt 的 siRNA，装入 RISC，引导降解同源 mRNA 或抑制翻译。"},{"k":"其他沉默方式","t":"shRNA 载体表达、反义寡核苷酸、核酶，以及 dCas9 融合抑制域（CRISPRi）阻断转录。"},{"k":"敲除原理","t":"在同源臂引导下用同源重组替换靶基因；或用 CRISPR/Cas9 切割后经 NHEJ 产生移码突变。"},{"k":"条件性敲除","t":"Cre-loxP 系统在特定组织或特定时间删除 floxed 等位基因，避免全身敲除致死。"},{"k":"应用","t":"基因功能研究、疾病动物模型、作物品种改良、基因治疗和药物靶点验证。"},{"k":"两者区别","t":"沉默在 RNA 或转录水平抑制表达、可逆；敲除改变 DNA 序列、可遗传且不可逆。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0669","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":[],"q":"患有鸟氨酸循环障碍的病人，请写出建议其饮食习惯，并从代谢途径解释原因。","points":[{"k":"低蛋白饮食","t":"限制蛋白质总量，减少氨基酸分解产生的氨，减轻高氨血症。"},{"k":"限制特定氨基酸","t":"按缺陷酶不同限制相应氨基酸，如 OTC 缺陷需限蛋白并补精氨酸，AS 缺陷需限制精氨酸琥珀酸前体。"},{"k":"补充精氨酸","t":"精氨酸是尿素循环中间物，可维持循环运转、促进氨排出；瓜氨酸也可补充。"},{"k":"氮清除剂","t":"苯甲酸钠与甘氨酸结合成马尿酸排出；苯丁酸钠转为苯乙酸，与谷氨酰胺结合排氮。"},{"k":"保证能量供给","t":"高糖高热量饮食，避免饥饿、感染、手术应激引起的分解代谢，防止内源蛋白分解加重高氨。"},{"k":"代谢解释","t":"尿素循环障碍使氨不能生成尿素，血氨升高引起肝性脑病，故须从减少氨源和增加排氮两条途径处理。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0670","subj":"880","chap":"第一章 糖类","type":"论述","years":[],"q":"（1）减肥人士在减肥期间需要控制糖类物质的摄入，请解释为什么？\n（2）在服用减肥药的时候，是否需要限制糖类物质的摄入？","points":[{"k":"糖转脂肪","t":"糖过量时乙酰 CoA 与 NADPH 增多，激活乙酰 CoA 羧化酶和脂肪酸合成酶，脂肪酸大量合成。"},{"k":"甘油骨架","t":"糖酵解产生的磷酸二羟丙酮还原为 3-磷酸甘油，为甘油三酯合成提供骨架。"},{"k":"激素环境","t":"高糖引起胰岛素升高，促进脂合成、抑制脂肪动员；丙二酰 CoA 抑制 CPT-1，减少脂肪酸氧化。"},{"k":"糖原容量有限","t":"肝糖原约 100 g、肌糖原约 300~400 g，储量有限，多余糖必然转化为脂肪。"},{"k":"服药仍需限糖","t":"需要。奥利司他只抑制肠道脂肪吸收，GLP-1 受体激动剂只抑制食欲；若仍高糖饮食，糖转脂肪照常发生，抵消药效。"},{"k":"综合管理","t":"药物只是辅助，须配合控制总能量、减少精制糖、增加运动，维持能量负平衡。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0671","subj":"880","chap":"第五章 酶","type":"论述","years":[],"q":"（1）请说明酶活性中心的定义，并写出三种检测酶活性中心的方法，且写出原理。\n（2）现有一种酶抑制剂，请判断它是可逆抑制剂、还是非可逆抑制剂","points":[{"k":"定义与组成","t":"活性中心是酶分子中直接结合底物并催化反应的区域，由结合基团和催化基团等必需基团构成，空间上彼此靠近。"},{"k":"化学修饰法","t":"用专一试剂共价修饰特定氨基酸侧链，测酶活性变化，判断该残基是否为活性中心必需基团。"},{"k":"亲和标记法","t":"用以底物类似物为引导、带反应基团的标记物特异结合活性中心并共价标记，分离后鉴定标记肽段。"},{"k":"结构解析法","t":"用 X 射线晶体衍射或 NMR 解析酶与底物类似物复合物结构，直接观察活性中心残基的空间位置。"},{"k":"定点突变法","t":"把候选残基突变为其他氨基酸，比较突变前后活性，验证其在催化中的作用。"},{"k":"抑制类型判断","t":"透析或超滤后测活：活性恢复为可逆抑制、不恢复为不可逆（共价）抑制；再作双倒数图，交于纵轴为竞争性、交于横轴为非竞争性。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0672","subj":"880","chap":"第十五章 脂类代谢","type":"计算","years":[],"q":"在鱼藤酮存在情况下，人体肝脏细胞中，一分子软脂酸（16 碳）完全氧化是产生多少分子 ATP？请写出计算过程和依据","points":[{"k":"抑制位点","t":"鱼藤酮阻断复合体Ⅰ（NADH-泛醌还原酶），NADH 不能氧化；FADH₂ 仍可经复合体Ⅱ进入呼吸链。"},{"k":"活化消耗","t":"软脂酸活化为软脂酰 CoA，消耗 2 个 ATP。"},{"k":"β氧化产能","t":"16 碳经 7 轮 β-氧化，每轮产 1 FADH₂（1.5 ATP）、NADH 被阻断计 0，共 7×1.5 = 10.5 ATP。"},{"k":"乙酰CoA产能","t":"8 个乙酰 CoA，每个经 TCA 产 3 NADH（0）+ 1 FADH₂（1.5）+ 1 GTP（1）= 2.5 ATP，共 20 ATP。"},{"k":"合计","t":"−2 + 10.5 + 20 = 28.5 ATP。"}],"note":"按 NADH=2.5、FADH₂=1.5 计。若用旧 P/O（3 与 2）：7×2 + 8×(2+1) − 2 = 36 ATP。","opts":[],"printed_answer":""},{"id":"n0673","subj":"880","chap":"第五章 酶","type":"计算","years":[],"q":"现有以下数据，底物浓度 mmol/L，每分钟生成产物浓度，并作出图像，判断加入的抑制剂是竞争类抑制剂，还是非竞争抑制剂。写出计算过程，依据、步骤\n\n| 底物浓度 | 2 | 3 | 4 | 14 | 18 |\n| --- | --- | --- | --- | --- | --- |\n| （未加抑制剂）每分钟生成产物浓度 | 6.1 | 8.1 |  |  | 18.9 |\n| （加入抑制剂）每分钟生成产物浓度 | 3.9 |  |  |  |  |","points":[{"k":"数据整理","t":"取 1/[S] 与 1/v 作双倒数图；未加抑制剂组用 [S]=2、3、18 三点拟合直线。"},{"k":"未抑制组拟合","t":"斜率 ≈ 0.25，纵轴截距 ≈ 0.039，故 Vmax ≈ 25.6 mmol/(L·min)，Km ≈ 6.4 mmol/L。"},{"k":"加点判断","t":"加抑制剂后 [S]=2 时 v=3.9，1/v=0.256；若纵轴截距仍为 0.039，则表观 Km 增大到约 11，Vmax 不变。"},{"k":"结论","t":"纵轴截距不变、Km 增大，符合竞争性抑制：抑制剂与底物竞争酶的活性中心。"},{"k":"判别依据","t":"竞争性：双倒数图交于纵轴，Vmax 不变、Km 增大；非竞争性：交于横轴，Km 不变、Vmax 降低。"}],"note":"原卷表格多处缺数（[S]=4、14 及加抑制剂组只有一个数据），上述结论按「纵截距不变」推定，需补全数据后用双倒数图确认。","opts":[],"printed_answer":""},{"id":"n0674","subj":"880","chap":"第八章 抗生素与激素","type":"简答","years":["22"],"q":"糖代谢和脂代谢的区别与相同点","points":[{"k":"共同枢纽","t":"两者都经乙酰 CoA 进入三羧酸循环，最终氧化为 CO₂ 和 H₂O，经氧化磷酸化生成 ATP。"},{"k":"辅因子相同","t":"都依赖 NAD⁺、FAD 传递氢，都受胰岛素与胰高血糖素的双向调节。"},{"k":"发生部位","t":"糖酵解在胞质、三羧酸循环在线粒体；脂肪酸合成在胞质、β-氧化在线粒体。"},{"k":"关键酶不同","t":"糖代谢关键酶为磷酸果糖激酶-1、丙酮酸激酶；脂代谢为乙酰 CoA 羧化酶、肉碱脂酰转移酶Ⅰ。"},{"k":"储能效率不同","t":"脂肪完全氧化约 9 kcal/g，糖约 4 kcal/g，脂肪是主要的储能形式。"},{"k":"转化不对称","t":"糖可大量转变为脂肪（提供乙酰 CoA、NADPH 和 3-磷酸甘油）；乙酰 CoA 不能净生成糖，脂肪生糖受限。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0675","subj":"880","chap":"第七章 核酸","type":"简答","years":["22"],"q":"核酸检测的原理（northern boltting）","points":[{"k":"变性电泳","t":"RNA 用甲醛或乙二醛变性后经琼脂糖凝胶电泳，按分子大小分离，消除二级结构干扰。"},{"k":"转膜固定","t":"用毛细管或真空转移把 RNA 印迹到尼龙膜或硝酸纤维素膜上，紫外交联或烘烤固定。"},{"k":"探针杂交","t":"用同位素或地高辛标记的 DNA/RNA 探针与膜上互补序列杂交形成双链。"},{"k":"洗膜显影","t":"控制盐浓度与温度洗去非特异结合，再放射自显影或显色检测条带。"},{"k":"结果判读","t":"条带位置反映转录本大小，条带深浅反映表达丰度；用 GAPDH、β-actin 等内参归一化。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0676","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["22"],"q":"酮血症的原因？","points":[{"k":"脂肪动员增强","t":"饥饿、糖尿病或高脂低糖饮食时胰岛素降低、胰高血糖素升高，脂肪酶激活，游离脂肪酸大量释放入血。"},{"k":"肝内氧化旺盛","t":"脂肪酸在肝内 β-氧化生成大量乙酰 CoA，超过三羧酸循环的处理能力。"},{"k":"草酰乙酸不足","t":"糖异生大量消耗草酰乙酸，乙酰 CoA 不能与之缩合成柠檬酸，转而生成酮体。"},{"k":"酮体生成增加","t":"HMG-CoA 合酶活性升高，生成乙酰乙酸、β-羟丁酸和丙酮。"},{"k":"血酮升高","t":"酮体生成超过外周利用，血酮升高形成酮血症；超过肾阈值出现酮尿，丙酮经肺呼出呈烂苹果味。"},{"k":"酮症酸中毒","t":"酮体为有机酸，大量堆积消耗碱储备，导致酮症酸中毒。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0678","subj":"880","chap":"第十章 糖酵解 糖异生","type":"论述","years":["22"],"q":"为什么脑部组织主要进行糖酵解（脑部毛细血管少，氧气少，主要进行糖酵解）","points":[{"k":"前提纠正","t":"“脑部毛细血管少、只能糖酵解”的说法不成立：生理条件下脑以葡萄糖有氧氧化为主，约占全身耗氧 20%，毛细血管密度高并有 GLUT1/GLUT3 转运。"},{"k":"脑的燃料","t":"脑几乎不储糖原，血糖是常规燃料；脂肪酸难透血脑屏障，长期饥饿时以酮体代偿。"},{"k":"何时糖酵解增强","t":"缺氧、缺血或肿瘤等病理状态下，氧化磷酸化受限，糖酵解通量上调以维持 ATP 供应。"},{"k":"乳酸生成","t":"此时 NADH/乙酰 CoA 升高抑制丙酮酸脱氢酶复合体，丙酮酸由乳酸脱氢酶还原为乳酸，同时再生 NAD⁺ 维持酵解。"},{"k":"HIF-1α 调控","t":"缺氧时 HIF-1α 不被降解，上调 GLUT 与己糖激酶、PFK-1、丙酮酸激酶等酵解酶基因。"}],"note":"本题原卷前提有误，正文先纠正前提再答“病理状态下为何转向糖酵解”，考场若按原前提作答也可，但需点明前提。","opts":[],"printed_answer":""},{"id":"n0679","subj":"880","chap":"第十五章 脂类代谢","type":"论述","years":["22"],"q":"还有一个糖代谢和脂代谢相关的题，类似简答题的那个，好像是说一下两者的关系","points":[{"k":"糖转脂三途径","t":"糖过量时：①乙酰CoA→脂肪酸；②磷酸二羟丙酮→甘油-3-磷酸→甘油；③磷酸戊糖途径产 NADPH 供还原性合成。"},{"k":"脂供能主途径","t":"脂肪动员释出脂肪酸，经β氧化生成乙酰CoA 入三羧酸循环，经氧化磷酸化供能，是饥饿时的主要能源。"},{"k":"甘油可生糖","t":"甘油→甘油-3-磷酸→磷酸二羟丙酮，逆行糖异生生成葡萄糖，是脂肪中唯一能净生糖的部分。"},{"k":"脂肪酸难生糖","t":"乙酰CoA 不能羧化生成丙酮酸；动物无乙醛酸循环，故偶数碳脂肪酸不能净合成糖，只能经 TCA 氧化。"},{"k":"乙酰CoA为枢纽","t":"二者通过乙酰CoA 与柠檬酸相连：柠檬酸激活乙酰CoA 羧化酶促脂合成，脂肪酸氧化产生的 ATP 抑制 PFK-1，糖脂互相制约。"},{"k":"失调出现酮症","t":"糖供不足时草酰乙酸被糖异生抽走，乙酰CoA 转向酮体生成，出现酮血症、酮尿与酸中毒。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0680","subj":"880","chap":"第五章 酶","type":"计算","years":["22"],"q":"酶的计算，比活力，纯化倍数这种计算，与生化课本配套的练习册上有类似的题，把练习册上的题会了就行。","points":[{"k":"测定酶活力","t":"在规定温度、pH、饱和底物下测初速度，1 个酶活力单位（U）为每分钟催化 1 μmol 底物转化的酶量。"},{"k":"求总活力总蛋白","t":"总活力（U）= 酶液体积（mL）× 活力浓度（U/mL）；总蛋白（mg）= 体积 × 蛋白浓度（mg/mL），每步单独计算。"},{"k":"比活力","t":"比活力 = 总活力/总蛋白，单位 U/mg，随纯化步骤逐级升高，是纯度的量度。"},{"k":"纯化倍数","t":"纯化倍数 = 某步比活力/粗酶液比活力；提取率（回收率）= 该步总活力/粗酶总活力×100%，两者一升一降共同评价。"},{"k":"先算总量再相除","t":"必须用总体积折算总活力与总蛋白后再相除，不能直接用浓度比值，否则体积变化会带入误差。"}],"note":"原卷只描述题型未给数据，此处给通用解法；答题时按题给体积、吸光度（或活力浓度）、蛋白浓度代入。","opts":[],"printed_answer":""},{"id":"n0681","subj":"880","chap":"第十五章 脂类代谢","type":"计算","years":["22"],"q":"脂肪能量的计算，这个很简单。","points":[{"k":"单位质量产能","t":"脂肪完全氧化约释放 39 kJ/g（9.3 kcal/g），是糖和蛋白质（约 17 kJ/g）的 2.3 倍，因碳氢比例高、高度还原。"},{"k":"碳链折算ATP","t":"脂肪酸每 2 个碳经一轮 β-氧化产 1 FADH₂、1 NADH、1 乙酰 CoA；乙酰 CoA 入 TCA 再产 10 ATP。"},{"k":"甘油骨架另计","t":"甘油三酯的甘油部分经甘油激酶耗 1 ATP 入糖酵解，彻底氧化净生 16.5 ATP（旧 P/O 下约 20），不可漏算。"},{"k":"换算成焦耳","t":"可用能 = 总 ATP 摩尔数 × 30.5 kJ/mol；储能总量 = 摩尔质量 × 39 kJ/g，两者之比即能量转化效率约 40%。"}],"note":"题目未给具体数值，此处按 39 kJ/g 与 1 mol ATP ≈ 30.5 kJ 的通行为准。","opts":[],"printed_answer":""},{"id":"n0682","subj":"880","chap":"第十七章 核苷酸代谢","type":"考点","years":["22"],"q":"人体嘌呤最后排出的方式尿酸","points":[{"k":"答案","t":"尿酸。嘌呤核苷酸先水解为嘌呤碱基，再脱氨（腺嘌呤→次黄嘌呤、鸟嘌呤→黄嘌呤），经黄嘌呤氧化酶氧化生成尿酸；人缺乏尿酸酶不能进一步分解为尿囊素，故以尿酸随尿排出。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0683","subj":"880","chap":"综合","type":"考点","years":["22"],"q":"白化病是因为缺什么酶","points":[{"k":"答案","t":"酪氨酸酶（含铜的单酚/双酚氧化酶）。该酶基因突变使酪氨酸不能羟化为多巴、进而生成黑色素，皮肤、毛发、虹膜色素缺失而成白化病。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0684","subj":"880","chap":"综合","type":"考点","years":["22"],"q":"屠呦呦诺贝尔奖青蒿素是治疗什么的","points":[{"k":"答案","t":"疟疾。青蒿素是抗疟药，对耐氯喹的恶性疟及脑型疟有效；其过氧桥结构在疟原虫体内血红素铁作用下产生自由基，烷基化虫体蛋白并损伤膜系。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0685","subj":"880","chap":"第五章 酶","type":"选择","years":["22"],"q":"哪种是可逆抑制剂","points":[{"k":"答案","t":"D 抗癌药。有机汞、有机磷、氰化物均与酶活性中心共价结合而不可逆抑制（汞结合巯基、有机磷结合丝氨酸羟基、氰化物结合细胞色素氧化酶铁）；抗癌药如甲氨蝶呤与二氢叶酸还原酶可逆竞争性结合。"}],"note":"","opts":["有机汞化物","有机磷","氰化物","抗癌药"],"printed_answer":""},{"id":"n0686","subj":"880","chap":"第六章 维生素与辅酶","type":"简答","years":["22"],"q":"为机体提供能量的过程，解释提供能量的机制","points":[{"k":"糖酵解产ATP","t":"葡萄糖→2 分子丙酮酸，净生 2 ATP、2 NADH，在胞质进行，不需氧，是快速供能通路。"},{"k":"氧化脱羧入线粒体","t":"丙酮酸经丙酮酸脱氢酶复合体氧化脱羧，生成乙酰CoA、NADH 与 CO₂，不可逆，是糖有氧氧化的限速关卡。"},{"k":"三羧酸循环","t":"乙酰CoA 与草酰乙酸缩合成柠檬酸，一轮产 3 NADH、1 FADH₂、1 GTP 和 2 CO₂，是三大物质的共同末端通路。"},{"k":"氧化磷酸化","t":"呼吸链传递电子时泵出 H⁺ 形成跨膜质子梯度，H⁺ 经 ATP 合酶回流驱动 ADP 磷酸化（化学渗透学说）。"},{"k":"脂肪β氧化","t":"脂肪动员后脂肪酸活化为脂酰CoA，经肉碱穿梭入线粒体，每轮β氧化切下乙酰CoA 并产 NADH、FADH₂。"},{"k":"氨基酸与磷酸肌酸","t":"氨基酸脱氨基后碳骨架转为丙酮酸、乙酰CoA 或 TCA 中间物；肌肉用磷酸肌酸/肌酸激酶缓冲 ATP 的瞬时波动。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0687","subj":"880","chap":"第八章 抗生素与激素","type":"简答","years":["22"],"q":"有氧运动可以减肥,解释生物原理","points":[{"k":"激素启动脂解","t":"运动使肾上腺素、去甲肾上腺素、胰高血糖素升高、胰岛素下降，激活激素敏感脂酶，甘油三酯水解为脂肪酸和甘油。"},{"k":"有氧氧化耗脂","t":"脂肪酸经β氧化、三羧酸循环和氧化磷酸化彻底氧化为 CO₂ 与 H₂O，输出大量 ATP，全过程需充足氧。"},{"k":"强度决定比例","t":"中低强度长时间运动脂肪供能比例最高；强度过高时糖酵解占优、乳酸堆积反而抑制脂解，故减肥宜慢跑等有氧运动。"},{"k":"糖原耗竭增效","t":"运动 30 min 后肌糖原下降，脂肪供能比例上升，故需持续 40 min 以上才能显著动员脂肪。"},{"k":"热量负平衡","t":"减脂本质是消耗大于摄入：运动增加能耗，并提高基础代谢率、增加肌肉量，使静息耗能也上升。"},{"k":"运动后过量耗氧","t":"运动后过量氧耗（EPOC）使恢复期体温、心率、儿茶酚胺仍高，继续消耗能量，脂肪氧化延续数小时。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0688","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["22"],"q":"三种蛋白质分子根据相对分子质量和等电点分离","points":[{"k":"SDS-PAGE测分子量","t":"SDS 使蛋白变性并按约 1.4 g/g 结合，带均一负电荷，迁移率只与相对分子质量（Mr）的对数呈线性，与标准品比对读数。"},{"k":"等电聚焦测pI","t":"两性电解质在凝胶中建立 pH 梯度，各蛋白迁移至 pH=pI、净电荷为零处停止，聚焦成窄带而分离。"},{"k":"双向电泳联用","t":"第一维按等电点（IEF）、第二维按 Mr（SDS-PAGE），两个参数正交，可一次分辨上千种蛋白并定位。"},{"k":"层析法备选","t":"凝胶过滤按 Mr 分离（大分子先出柱）；离子交换层析按电荷差异，改变 pH 使 pI 不同的蛋白带不同电荷而先后洗脱。"},{"k":"双参数定位","t":"以 pI 与 Mr 两个参数在双向图谱上定位，与数据库或已知标准比对即可鉴定三种蛋白。"}],"note":"题干只说“三种蛋白”，未给具体 Mr 与 pI 数值，故按方法学作答。","opts":[],"printed_answer":""},{"id":"n0689","subj":"880","chap":"第八章 抗生素与激素","type":"简答","years":["22"],"q":"酮尿症机制","points":[{"k":"肝内生成酮体","t":"肝以乙酰CoA 为原料经乙酰CoA 羧化酶、HMG-CoA 合酶途径生成乙酰乙酸、β-羟丁酸和丙酮，肝内缺乏利用酮体的酶。"},{"k":"脂解亢进","t":"糖尿病胰岛素缺乏或长期饥饿时胰高血糖素升高，脂肪大量动员，游离脂肪酸入肝显著增多。"},{"k":"草酰乙酸被抽空","t":"糖异生旺盛大量消耗草酰乙酸，乙酰CoA 不能顺利与草酰乙酸缩合成柠檬酸，在肝内堆积。"},{"k":"转向酮体生成","t":"堆积的乙酰CoA 经 HMG-CoA 途径转向酮体，生成量超过肝外组织的利用能力，血酮升高。"},{"k":"超肾阈成酮尿","t":"酮体为有机酸，血浓度超过肾小管重吸收阈值即随尿排出形成酮尿，并消耗碱储备引起酮症酸中毒、呼气烂苹果味。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0690","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["22"],"q":"新冠病毒核酸和抗体检测的方法和原理","points":[{"k":"核酸检测原理","t":"取鼻咽/口咽拭子提取病毒 RNA，逆转录为 cDNA，用针对 ORF1ab、N 基因的特异引物与 TaqMan 探针做实时荧光 PCR。"},{"k":"Ct值判读","t":"每循环读取荧光，达阈值所经循环数即 Ct 值；Ct 小于试剂盒临界值（多为 35~40）判阳性，Ct 越小病毒载量越高。"},{"k":"抗原检测","t":"胶体金免疫层析：金标抗体与样本中 N 蛋白结合，复合物在检测线被捕获抗体截留显色，15 min 出结果，适合现场快筛。"},{"k":"抗体检测","t":"取血清用胶体金或化学发光法测 IgM、IgG：IgM 提示近期感染，IgG 提示既往感染或疫苗接种，用于流行病学与免疫评估。"},{"k":"窗口期差异","t":"核酸最早可检出（感染后 1~3 天），抗原需较高病毒载量、灵敏度低，抗体出现最晚，故阴性均不能完全排除感染。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0691","subj":"880","chap":"第十七章 核苷酸代谢","type":"简答","years":["22"],"q":"5-氟尿嘧啶抗癌机制","points":[{"k":"需代谢活化","t":"5-氟尿嘧啶（5-FU）本身无活性，经磷酸核糖转移酶转为 FUMP，再变成 FdUMP、FUTP、FdUTP 才发挥作用。"},{"k":"抑制胸苷酸合酶","t":"FdUMP 与胸苷酸合酶（TS）及四氢叶酸形成稳定三元复合物，阻断 dUMP 甲基化为 dTMP。"},{"k":"胸腺嘧啶饥饿","t":"dTTP 迅速枯竭，DNA 复制停滞于 S 期，细胞因“胸腺嘧啶饥饿”而死亡，故为 S 期特异性药物。"},{"k":"掺入RNA干扰","t":"FUTP 掺入 RNA，干扰 rRNA 加工、mRNA 剪接与翻译，是其细胞毒作用的重要部分。"},{"k":"掺入DNA致断裂","t":"FdUTP 掺入 DNA 后被尿嘧啶糖苷酶切除，产生无碱基位点与链断裂，加重损伤。"},{"k":"亚叶酸钙增效","t":"合用亚叶酸钙（四氢叶酸）可稳定三元复合物、延长对 TS 的抑制，是经典的生化调节增效方案。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0692","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":["22"],"q":"尿素循环缺乏相关酶可以通过食低分子蛋白质来缓解，解释原因","points":[{"k":"酶缺陷致高氨","t":"尿素循环某一酶（如 CPS-1、OTC、ASS、ASL、精氨酸酶）活性降低，氨不能转变为尿素，血氨升高，出现呕吐、嗜睡甚至脑病。"},{"k":"氨主要来自蛋白","t":"体内氨主要来自氨基酸脱氨基及肠道细菌分解，蛋白摄入量直接决定氨的生成负荷。"},{"k":"限蛋白减底物","t":"低蛋白饮食从源头减少氨基酸供应，降低氨的生成速率，是治疗的核心措施。"},{"k":"补足热量防分解","t":"同时给足糖和脂肪供能，避免自身蛋白分解供能，防止内源性氨进一步升高。"},{"k":"补充循环中间物","t":"补充精氨酸、瓜氨酸可维持尿素循环通量、促进氨以尿素形式排出，精氨酸还为 CPS-1 变构激活所需。"},{"k":"旁路排氮药物","t":"苯甲酸钠、苯丁酸钠与甘氨酸、谷氨酰胺结合生成马尿酸、苯乙酰谷氨酰胺，经肾排出，绕开缺陷酶排氮。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0693","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["22"],"q":"根据 DNA 排列顺序写 mrna，翻译的氨基酸，及哪种氨基酸在蛋白质分子内部","points":[{"k":"确定模板链","t":"mRNA 与模板链反向平行互补（A-U、T-A、G-C、C-G），序列与编码链相同、仅 T 换 U；先判断题给的是哪条链。"},{"k":"锁定起始密码","t":"从 5′ 端扫描第一个 ATG，对应 mRNA 的 AUG，由此确定阅读框，避免移码读错。"},{"k":"按密码表翻译","t":"以三联体密码子逐个查遗传密码表，遇到 UAA、UAG、UGA 终止；注意密码子的简并性与摆动性。"},{"k":"判定内部残基","t":"埋于蛋白内部或跨膜的多为非极性疏水氨基酸（Leu、Val、Ile、Phe、Ala、Met），亲水带电残基多分布在表面。"}],"note":"原卷未附 DNA 序列，此处给通用解题步骤；答题时按题给序列写出 mRNA 与肽链并圈出疏水残基。","opts":[],"printed_answer":""},{"id":"n0694","subj":"880","chap":"第四章 蛋白质","type":"论述","years":["22"],"q":"某溶液可能含有核酸，蛋白质，还原糖,确定含有哪些,, 若样品是蛋白质，写两种方法测量其相对分子质量和浓度","points":[{"k":"核酸鉴定","t":"260 nm 有强紫外吸收，A260/A280≈1.8（纯 DNA）或 2.0（纯 RNA）；地衣酚法测 RNA、二苯胺法测 DNA 显色定性。"},{"k":"蛋白质鉴定","t":"双缩脲反应呈紫红色、Folin-酚或 Bradford 法显色；280 nm 吸收来自 Trp、Tyr，可作快速判断。"},{"k":"还原糖鉴定","t":"斐林试剂或 Benedict 试剂沸水浴生成砖红色 Cu₂O 沉淀；DNS 法显色可定量，3,5-二硝基水杨酸被还原。"},{"k":"排除相互干扰","t":"先用颜色反应与光谱定性，再用相应标准曲线定量；核酸污染由 A260/A280 判断，高浓度蛋白会干扰 260 nm 读数。"},{"k":"测相对分子质量","t":"SDS-PAGE 与标准分子量对照读数，或凝胶过滤测天然 Mr，MALDI-TOF 质谱可精确测定。"},{"k":"测蛋白浓度","t":"Bradford 法（考马斯亮蓝 G-250，595 nm）、BCA 法或 A280 消光系数法，以牛血清白蛋白作标准曲线。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0695","subj":"880","chap":"第十章 糖酵解 糖异生","type":"论述","years":["22"],"q":"癌细胞不含有毛细血管网，请解释癌细胞需要吸收大量葡萄糖和产生过量糖酵解酶的原因","points":[{"k":"缺氧稳定HIF-1α","t":"肿瘤团块无毛细血管网，内部氧分压极低，HIF-1α 脯氨酸羟化受阻、不被降解，入核启动下游基因转录。"},{"k":"葡萄糖摄取上调","t":"GLUT1、GLUT3 表达升高，癌细胞葡萄糖摄取量可达正常细胞的数十倍，为酵解提供充足底物。"},{"k":"酵解酶大量表达","t":"己糖激酶2（HK2）、PFK-1、丙酮酸激酶 M2（PKM2）、乳酸脱氢酶 A 均上调，糖酵解通量大幅提高，即 Warburg 效应。"},{"k":"快速供能与前体","t":"酵解虽每分子葡萄糖只产 2 ATP，但速率快；中间产物分流至磷酸戊糖途径产核糖、生成丝氨酸与甘油，满足快速增殖的生物合成需求。"},{"k":"乳酸促侵袭","t":"乳酸经单羧酸转运体排出，酸化微环境，促进血管新生、侵袭转移，并抑制 T 细胞与巨噬细胞功能。"},{"k":"FDG显像依据","t":"18F-氟代脱氧葡萄糖（FDG）被高摄取的癌细胞浓聚且不易排出，是 PET-CT 肿瘤显像的生化基础。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0696","subj":"880","chap":"第十五章 脂类代谢","type":"计算","years":["22"],"q":"一摩尔十八碳甘油三酯完全氧化产生的能量","points":[{"k":"活化耗能","t":"硬脂酸（18C）活化生成硬脂酰 CoA，消耗 2 个高能磷酸键。"},{"k":"八轮β氧化","t":"18C 经 8 轮：8 FADH₂（12）+ 8 NADH（20）+ 9 乙酰 CoA（90），减活化 2 = 120 ATP/分子。"},{"k":"甘油部分","t":"甘油经甘油激酶 −1，脱氢 1.5，酵解段 2 + 1.5（穿梭），丙酮酸氧化 2.5，TCA 10 = 16.5 ATP。"},{"k":"合计","t":"3 × 120 + 16.5 = 376.5 mol ATP。"},{"k":"折合能量","t":"三硬脂酸甘油酯 Mr ≈ 891，按 39 kJ/g 计约 3.47×10⁴ kJ/mol（约 8300 kcal）。"}],"note":"按 3-磷酸甘油穿梭计。若改按苹果酸-天冬氨酸穿梭，甘油为 17.5，合计 377.5 mol ATP（注意：脱氢那步是 FADH₂，恒为 1.5，不随穿梭改变）。","opts":[],"printed_answer":""},{"id":"n0697","subj":"880","chap":"第五章 酶","type":"计算","years":["22"],"q":"酶活的提取率和纯化倍数","points":[{"k":"算总活力","t":"总活力（U）= 酶液体积（mL）× 活力浓度（U/mL）；每步都要用当时的体积重新折算，不能沿用上一步。"},{"k":"算总蛋白","t":"总蛋白（mg）= 体积 × 蛋白浓度（mg/mL），常用 Bradford 法或 A280 测定，注意扣除空白。"},{"k":"算比活力","t":"比活力 = 该步总活力/该步总蛋白（U/mg），纯度越高数值越大。"},{"k":"算提取率","t":"提取率 = 该步总活力/初始总活力×100%，随步骤下降，反映酶活损失。"},{"k":"算纯化倍数","t":"纯化倍数 = 该步比活力/初始比活力；与提取率配合判断：纯度升、回收降，取兼顾二者的步骤。"}],"note":"原卷未给具体数据，此处给计算框架；代入时统一单位为 U 与 mg。","opts":[],"printed_answer":""},{"id":"n0699","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["14"],"q":"蛋白质的等电点","points":[{"k":"定义","t":"蛋白质的等电点，指蛋白质分子上所带正、负电荷相等、净电荷为零时溶液的 pH 值，以 pI 表示，此时分子在电场中不移动、溶解度最低。"},{"k":"应用","t":"是等电聚焦、电泳分离和等电点沉淀的依据；pI 由分子中酸性、碱性氨基酸残基的比例决定。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0700","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"名词解释","years":["14"],"q":"逆转录","points":[{"k":"定义","t":"逆转录，以 RNA 为模板、在逆转录酶催化下合成互补 DNA（cDNA）的过程，引物为 tRNA 或寡聚脱氧核苷酸。"},{"k":"意义","t":"补充了中心法则（RNA→DNA）；逆转录酶来自逆转录病毒，是构建 cDNA 文库、RT-PCR 与基因工程的重要工具。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0701","subj":"880","chap":"第十三章 磷酸戊糖途径、乙醛酸循环","type":"名词解释","years":["14"],"q":"磷酸戊糖途径","points":[{"k":"定义","t":"磷酸戊糖途径，在细胞质中以葡糖-6-磷酸脱氢生成 6-磷酸葡糖酸内酯起始，最终生成 NADPH 与磷酸戊糖的代谢途径，又称磷酸己糖旁路。"},{"k":"功能","t":"产生 NADPH 供脂肪酸等还原性合成及谷胱甘肽还原，提供核糖-5-磷酸供核苷酸合成；关键酶葡糖-6-磷酸脱氢酶受 NADPH 抑制。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0702","subj":"880","chap":"第三章 氨基酸","type":"判断","years":["14"],"q":"酶的活性中心由一级结构上相邻的氨基酸残基构成","points":[{"k":"答案","t":"错。活性中心由空间构象上彼此靠近的几个残基组成，它们在一级结构上往往相隔很远（如溶菌酶、胰凝乳蛋白酶），靠肽链折叠把催化基团与结合基团聚拢成催化口袋。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0703","subj":"880","chap":"第十五章 脂类代谢","type":"判断","years":["14"],"q":"只有偶数脂肪酸才能被氧化成为乙酰辅酶 A","points":[{"k":"答案","t":"错。奇数碳脂肪酸同样可β-氧化，末轮生成丙酰CoA，经羧化生成甲基丙二酰CoA、再异构为琥珀酰CoA进入 TCA 循环；只有带甲基分支、不能β-氧化的脂肪酸才需先行α-氧化。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0704","subj":"880","chap":"第十四章 氧化磷酸化","type":"判断","years":["14"],"q":"解偶联剂抑制呼吸链中的电子传递","points":[{"k":"答案","t":"错。解偶联剂（2,4-二硝基苯酚等）作为质子载体把 H⁺ 顺梯度带回基质，消除跨膜质子梯度，使氧化与磷酸化脱节；电子传递不受抑制，反因失去反馈抑制而加快，P/O 比值下降、能量以热能散失。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0705","subj":"880","chap":"第六章 维生素与辅酶","type":"判断","years":["14"],"q":"维生素 E 不容易被氧化，因此常作为抗氧化剂","points":[{"k":"答案","t":"错。正因它本身易被氧化（生育酚苯环上酚羟基的氢易脱去），才能优先与自由基反应、终止链式氧化，保护不饱和脂肪酸与膜蛋白，并与维生素 C、谷胱甘肽协同再生。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0706","subj":"880","chap":"第十章 糖酵解 糖异生","type":"判断","years":["14"],"q":"生物氧化过程一定需要氧气的参与","points":[{"k":"答案","t":"错。生物氧化包括需氧与不需氧两类：底物水平磷酸化、发酵（乳酸、乙醇）和无氧呼吸都能在无氧条件下完成脱氢氧化，氧只是最终电子受体之一，并非必要条件。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0707","subj":"880","chap":"第七章 核酸","type":"判断","years":["14"],"q":"DNA 的碱解和酶解，都只能得到 5'-核苷酸","points":[{"k":"答案","t":"错。稀碱水解 RNA 得 2'-与 3'-核苷酸；DNA 无 2'-OH 不能形成 2',3'-环磷酸中间体，碱解主要断裂生成 3'-核苷酸。只有 DNase Ⅰ 等酶解产物才是 5'-核苷酸，故「都得 5'-核苷酸」不成立。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0708","subj":"880","chap":"第七章 核酸","type":"判断","years":["14"],"q":"DNA 双链中，一条链的碱基顺序为 pGpApCpCp，则另一条链的碱基顺序，为 pCpGpCpGpA","points":[{"k":"答案","t":"错。按反向平行互补，5'-pGpApCpCp-3' 的互补碱基为 C、T、G、G，反向后另一条链应为 5'-pGpGpTpCp-3'。题干给出的 pCpGpCpGpA 既未互补也未反向。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0709","subj":"880","chap":"第四章 蛋白质","type":"判断","years":["14"],"q":"双缩脲反应是肽和蛋白质特有的反应，因此二肽也有双缩脲反应","points":[{"k":"答案","t":"错。双缩脲反应需分子中至少两个肽键与 Cu²⁺ 形成紫红色络合物，二肽只有一个肽键，不呈色；三肽以上及蛋白质才阳性（故可用于蛋白质定量）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0710","subj":"880","chap":"综合","type":"判断","years":["14"],"q":"酶反应时间越长，则所需最适温度越高，酶反应时间越短，所需温度越低。","points":[{"k":"答案","t":"错。关系正好相反：作用时间短可用较高温度（瞬时高温提高反应速率），保温时间长则须降低温度以减缓酶的热失活，最适温度随反应时间延长而下降。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0711","subj":"880","chap":"第一章 糖类","type":"判断","years":["14"],"q":"α-淀粉酶和 β-淀粉酶的区别在于 a-淀粉酶水解 a-1,4 糖苷键，而 β-淀粉酶水解 β-1,4 糖苷键","points":[{"k":"答案","t":"错。α-淀粉酶与β-淀粉酶都只水解 α-1,4 糖苷键，差别在作用方式：α-淀粉酶是内切酶随机切断，β-淀粉酶从非还原端外切、每次切下麦芽糖，遇 α-1,6 分支点即停。β 指产物β-麦芽糖的变旋，不是切β键。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0712","subj":"880","chap":"第一章 糖类","type":"问答","years":["14"],"q":"直链淀粉和纤维素都是由葡萄糖分子聚合而成，为何物理性质差别如此之大？","points":[{"k":"糖苷键不同","t":"直链淀粉为 α-1,4-糖苷键（支链淀粉另有 α-1,6 分支），纤维素为 β-1,4-糖苷键。"},{"k":"链构象不同","t":"α 键使葡萄糖单元同向排列、链盘曲成螺旋；β 键使相邻葡萄糖翻转 180°，链成平直伸展的带状。"},{"k":"氢键与结晶","t":"纤维素带与带之间形成密集链间氢键，聚成微纤丝、高度结晶、不溶于水；淀粉链松散，只形成颗粒，加热即糊化。"},{"k":"水性与黏度","t":"淀粉吸水膨胀、加热糊化成胶体，可被酸和酶降解；纤维素只溶胀不糊化，化学性质稳定，抗酸碱能力强。"},{"k":"酶解与营养","t":"人分泌 α-淀粉酶可水解 α-1,4 键，淀粉可消化供能；人体无纤维素酶，β 键不能水解，纤维素只作膳食纤维。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0713","subj":"880","chap":"第五章 酶","type":"问答","years":["14"],"q":"丙二酸是 TCA 循环中琥珀酸脱氢酶的抑制剂，预测丙二酸是琥珀酸脱氢酶的抑制剂的类型，为什么?加入丙二酸到反应体系后动力学常数和反应速度的变化?如何消除这种影响?","points":[{"k":"竞争性抑制","t":"丙二酸与琥珀酸结构相似（同为二羧酸），竞争琥珀酸脱氢酶的底物结合部位，属可逆的竞争性抑制。"},{"k":"Km增大","t":"表观 Km 升高（1/Km 减小），最大反应速度 Vmax 不变，双倒数图交于纵轴同一点。"},{"k":"速度下降","t":"在固定底物浓度下，加入丙二酸后反应速度降低；抑制程度取决于抑制剂与底物的浓度比。"},{"k":"加底物解除","t":"提高琥珀酸浓度可竞争性逆转抑制，抑制可被高浓度底物消除，这是竞争性抑制的判别依据。"},{"k":"代谢后果","t":"琥珀酸堆积、延胡索酸生成减少，三羧酸循环受阻，NADH 与 ATP 生成下降。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0714","subj":"880","chap":"第十三章 磷酸戊糖途径、乙醛酸循环","type":"问答","years":["14"],"q":"乙醛酸循环是什么?有什么生物学意义?","points":[{"k":"定义","t":"以异柠檬酸裂解酶和苹果酸合酶为特有酶，将 2 分子乙酰CoA 缩合为 1 分子琥珀酸（草酰乙酸）的循环途径。"},{"k":"关键两步","t":"异柠檬酸→琥珀酸+乙醛酸；乙醛酸+乙酰CoA→苹果酸，苹果酸再脱氢生成草酰乙酸，循环继续。"},{"k":"净反应","t":"2 乙酰CoA+NAD⁺+FAD→草酰乙酸+2 CoA+NADH+FADH₂，绕过 TCA 中两次脱羧，故碳净保留。"},{"k":"分布","t":"存在于植物、真菌和细菌中；动物细胞缺乏异柠檬酸裂解酶，故无此途径，不能由脂肪酸净生糖。"},{"k":"生物学意义","t":"使脂肪（乙酰CoA）净转变为糖，供油料种子萌发时胚生长；与 TCA 共享前半段，兼具回补草酰乙酸的作用。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0715","subj":"880","chap":"第七章 核酸","type":"问答","years":["14"],"q":"DNA 的复制精确度大于 RNA 转录的大于蛋白质翻译的，简述 DNA 复制保持高度忠实性的主要机制。","points":[{"k":"碱基互补选择","t":"模板与 dNTP 严格按 A-T、G-C 配对，聚合酶活性中心按几何形状筛选取代基大小，初始错配率约 10⁻⁴~10⁻⁵。"},{"k":"3′外切校对","t":"DNA 聚合酶具 3′→5′ 外切酶活性，能即时切除错配的末端核苷酸再延伸，使错误率降至约 10⁻⁷。"},{"k":"错配修复","t":"MutS、MutL、MutH 识别子代链错配，切去含错碱基片段，由 DNA 聚合酶Ⅲ和连接酶补齐，再降 2~3 个数量级。"},{"k":"尿嘧啶切除","t":"dUTP 误掺后由尿嘧啶-DNA 糖苷酶切除，经碱基切除修复纠正，防止 U 代替 T 造成突变。"},{"k":"与转录翻译比较","t":"RNA 转录无外切校对、错误率约 10⁻⁴；翻译靠氨酰-tRNA 合成酶的氨基酸校对，错误率约 10⁻⁴~10⁻⁵，故保真性 DNA 复制>转录>翻译。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0716","subj":"880","chap":"第十章 糖酵解 糖异生","type":"问答","years":["14"],"q":"糖酵解的中间产物在其他代谢途径中的应用有哪些?","points":[{"k":"磷酸戊糖途径","t":"葡糖-6-磷酸分流进入磷酸戊糖途径，产 NADPH（还原力）与核糖-5-磷酸（核苷酸合成原料）。"},{"k":"糖原合成","t":"葡糖-6-磷酸→葡糖-1-磷酸→UDP-葡糖，作为糖原合成的直接供体。"},{"k":"甘油与磷脂","t":"磷酸二羟丙酮还原为甘油-3-磷酸，用于合成甘油三酯和甘油磷脂的骨架。"},{"k":"丝氨酸与一碳","t":"3-磷酸甘油酸→3-磷酸羟基丙酮酸→丝氨酸，进而提供甘氨酸、半胱氨酸和一碳单位。"},{"k":"丙酮酸多去向","t":"丙酮酸→乙酰CoA（脂肪酸、胆固醇、酮体、乙酰胆碱）；→草酰乙酸（糖异生、补充 TCA）；→丙氨酸（转氨）。"},{"k":"芳香族氨基酸","t":"磷酸烯醇式丙酮酸与赤藓糖-4-磷酸经莽草酸途径合成芳香族氨基酸（植物与微生物）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0717","subj":"880","chap":"第七章 核酸","type":"问答","years":["14"],"q":"碱基堆积力在稳定核酸结构中非常重要。\n(1)碱基堆积力的化学本质究竟是什么。\n(2)嘌呤和嘧啶中哪种碱基堆积力的作用更强，为什么。\n(3)在 RNA 结构中，经常看到结合的金属元素，它们所起的作用是什么?","points":[{"k":"疏水与范德华力","t":"(1) 化学本质是碱基环之间的疏水作用与范德华力（含 π-π 偶极作用），碱基像硬币层叠以避开水相。"},{"k":"嘌呤作用更强","t":"(2) 嘌呤为双环，环面积大、极化率高、疏水性强，堆积接触面积与作用能均大于单环的嘧啶。"},{"k":"稳定双螺旋主力","t":"堆积力使碱基间距保持 0.34 nm、螺旋半径恒定，是维持双螺旋与单链折叠的主要作用力，贡献大于碱基间氢键。"},{"k":"金属离子中和电荷","t":"(3) Mg²⁺、K⁺ 等中和磷酸骨架负电荷，削弱链段间静电排斥，使 RNA 能紧密折叠出三级结构（如 tRNA 的 L 形）。"},{"k":"特异性结合与催化","t":"RNA 折叠形成金属结合口袋，可特异性配位金属离子并参与催化（核酶、核糖体肽酰转移酶中心）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0718","subj":"880","chap":"第二十一章 细胞代谢与基因表达","type":"问答","years":["14"],"q":"在下列培养基条件下，大肠杆菌中 lac 操纵子的转录速度是怎么变化的\n(a)乳糖和葡萄糖 (b)葡萄糖 (c)乳糖","points":[{"k":"乳糖加葡萄糖","t":"(a) 转录很低：异乳糖解除阻遏，但葡萄糖代谢使 cAMP 低、CAP 不能结合启动子上游，仅维持基础水平（降解物阻遏）。"},{"k":"只有葡萄糖","t":"(b) 转录极低：无诱导物，LacI 阻遏蛋白结合操纵基因（O₁），RNA 聚合酶不能前进。"},{"k":"只有乳糖","t":"(c) 转录高水平：异乳糖解除阻遏，同时无葡萄糖使 cAMP 升高，CAP-cAMP 结合并激活转录，可达基础水平的上千倍。"},{"k":"双重控制","t":"lac 操纵子受负调控（阻遏蛋白）与正调控（cAMP-CAP）双重控制，两者同时满足才高效转录。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0719","subj":"880","chap":"第四章 蛋白质","type":"问答","years":["14"],"q":"什么是蛋白质变性和蛋白质复性?蛋白质变性后哪些性质会发生改变?","points":[{"k":"变性定义","t":"在热、酸碱、有机溶剂、尿素等理化因素作用下，蛋白质的空间构象被破坏，理化性质改变、生物活性丧失，但一级结构不变。"},{"k":"复性定义","t":"变性程度较轻时去除变性因素，肽链可按一级结构信息自发重新折叠，恢复天然构象与生物活性。"},{"k":"溶解度下降","t":"疏水基团外露，分子间疏水聚集而沉淀，在等电点附近最易沉淀析出。"},{"k":"光学性质改变","t":"280 nm 紫外吸收增强（增色效应），旋光度改变，黏度增加，扩散系数与沉降系数下降。"},{"k":"活性与易酶解","t":"酶活、激素活性等生物功能丧失；肽键暴露使更易被蛋白酶水解，侧链基团反应性增强，失去结晶能力。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0720","subj":"880","chap":"第十七章 核苷酸代谢","type":"问答","years":["14"],"q":"嘌呤和嘧啶核苷酸的合成过程各有什么特点?其中分别有哪些氨基酸的参与?","points":[{"k":"嘌呤在PRPP上建环","t":"以 5-磷酸核糖-1-焦磷酸（PRPP）为骨架逐步添加原子，先合成次黄嘌呤核苷酸（IMP），再转变为 AMP 与 GMP。"},{"k":"嘌呤的氨基酸","t":"甘氨酸提供 C4、C5、N7；谷氨酰胺提供 N3、N9；天冬氨酸提供 N1；另需 CO₂ 与一碳单位（N10-甲酰四氢叶酸）。"},{"k":"嘧啶先成环","t":"嘧啶先由氨甲酰磷酸与天冬氨酸缩合成乳清酸环，再与 PRPP 结合生成尿苷酸（UMP），进而转为 CTP、dTMP。"},{"k":"嘧啶的氨基酸","t":"谷氨酰胺提供 N3 及氨甲酰磷酸的氮，天冬氨酸提供 N1 和环上部分碳，其余碳来自 CO₂。"},{"k":"调节与补救","t":"嘌呤受 PRPP 与终产物反馈抑制，嘧啶受天冬氨酸转氨甲酰酶终产物反馈；均有补救途径（HGPRT、APRT、嘧啶磷酸核糖转移酶）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0721","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"选择","years":[],"q":"下列处于顺式作用元件的是()","points":[{"k":"答案","t":"A 启动子。启动子、增强子、沉默子都在 DNA 上，只调控同一条链上的基因，属顺式作用元件；结构基因是被调控的序列，RNA 聚合酶是可扩散的反式因子，复制子指复制起点及其复制单位。"}],"note":"","opts":["A. 启动子","B. 结构基因","C. RNA 聚合酶","D. 复制子"],"printed_answer":"A"},{"id":"n0722","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"判断","years":[],"q":"DNA 的复制中沿 5'→3'进行","points":[{"k":"答案","t":"√。DNA 聚合酶只能沿新生链的 5′→3′ 方向延伸，这是复制的通行表述；模板链则按 3′→5′ 被阅读。"},{"k":"补充","t":"“半不连续”指后随链分段合成，与“延伸方向 5′→3′”并不矛盾。"}],"note":"原卷判错，但就“新生链延伸方向”而言该说法成立，本库判对并在题下说明。","opts":[],"printed_answer":"×"},{"id":"n0723","subj":"631","chap":"一、染色体结构","type":"判断","years":[],"q":"原核生物 DNA 的合成是单点起始，真核生物为多点起始。","points":[{"k":"答案","t":"√。原核染色体环状、只有一个复制起点 oriC，单点起始双向复制；真核染色体很长，含多个复制起点（多复制子）同时启动，以缩短 S 期复制时间。"}],"note":"","opts":[],"printed_answer":"√"},{"id":"n0724","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":[],"q":"真核生物基因组中，不编码序列只占整个基因组的较小部分","points":[{"k":"答案","t":"×。恰好相反：真核基因组中不编码蛋白质的序列（内含子、重复序列、基因间序列）占绝大部分，人类编码序列不足 2%，非编码部分在 90% 以上。"}],"note":"","opts":[],"printed_answer":"×"},{"id":"n0725","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":[],"q":"真核生物 mRNA 的多聚核苷酸化发生在转录终止后","points":[{"k":"答案","t":"√。RNA 聚合酶Ⅱ转录出的前体在 AAUAAA 下游被特异核酸酶切割，再由多聚腺苷酸聚合酶（PAP）加上 80~250 个腺苷酸，属转录终止后的加工步骤。"}],"note":"","opts":[],"printed_answer":"√"},{"id":"n0726","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":[],"q":"细菌启动子也有活性强弱分区。","points":[{"k":"答案","t":"√。细菌启动子的强弱由 -10 区（TATAAT）与 -35 区（TTGACA）和共有序列的接近程度决定，越接近共有序列、两区间距越合适（16~19 bp），启动子越强，转录起始频率越高。"}],"note":"","opts":[],"printed_answer":"√"},{"id":"n0727","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":[],"q":"一个 tRNA 只能携带一种氨基酸","points":[{"k":"答案","t":"√。一种 tRNA 只被一种氨酰-tRNA 合成酶识别，3'端只接一种氨基酸；但一种氨基酸可由 2~6 种同工 tRNA 携带，这正是密码子简并性的分子基础。"}],"note":"","opts":[],"printed_answer":"√"},{"id":"n0728","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"判断","years":[],"q":"冈崎片段的合成需要 RNA 引物","points":[{"k":"答案","t":"√。DNA 聚合酶不能从头起始，须由引物酶（DnaG）先合成约 10 nt 的 RNA 引物提供 3'-OH，聚合酶Ⅲ才能延伸；引物随后由聚合酶Ⅰ切除填补、连接酶封口。"}],"note":"","opts":[],"printed_answer":"√"},{"id":"n0729","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"判断","years":[],"q":"限制与修饰现象是宿主的一种保护体系，它是通过对外额 DNA 的修饰和对自身 DNA 的【…?】现的。","points":[{"k":"答案","t":"错，题干表述颠倒。宿主用限制性内切酶切割、降解外源 DNA，同时用相应的甲基化酶（Dam、Dcm 等）修饰自身 DNA，使其不被自身限制酶识别而受保护；应是「对自身 DNA 修饰、对外源 DNA 切割」。"}],"note":"题干「外额」为「外源」之误，且「自身 DNA 的【…?】」处缺字，按限制—修饰系统的通行表述作答。","opts":[],"printed_answer":""},{"id":"n0730","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"问答","years":[],"q":"试比较真核生物和原核生物基因组的特点。","points":[{"k":"大小与基因数","t":"真核基因组大（10⁷~10¹⁰ bp），基因数多且非编码序列占绝大部分；原核基因组小（10⁶ bp 级），基因密度高、间隔短。"},{"k":"基因结构","t":"真核多为断裂基因，含内含子与外显子，转录后需剪接；原核基因连续，一般无内含子。"},{"k":"重复序列","t":"真核含大量高度、中度重复序列、卫星 DNA 与转座元件；原核重复序列少，主要是插入序列和 rRNA 操纵子多拷贝。"},{"k":"DNA 组织形式","t":"真核 DNA 与组蛋白组装成核小体、线性多染色体，有端粒与着丝粒；原核为环状 DNA，结合类组蛋白形成类核，另有质粒。"},{"k":"转录单位","t":"真核以单顺反子为主，核内转录并加工后出核翻译；原核以多顺反子操纵子为主，转录与翻译偶联进行。"},{"k":"表达调控","t":"真核有增强子、沉默子、甲基化与染色质重塑等复杂多层次调控；原核以操纵子（阻遏/衰减）调控为主，并有质粒介导的水平转移。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0731","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"问答","years":[],"q":"简述 cDNA 文库的构建组合。","points":[{"k":"分离mRNA","t":"用 oligo(dT)-纤维素亲和层析，借 mRNA 3′ 端 poly(A) 尾与 oligo(dT) 互补配对，分离去除 rRNA、tRNA。"},{"k":"逆转录第一链","t":"以 oligo(dT) 或随机引物为引物，逆转录酶以 mRNA 为模板合成第一条 cDNA 链，形成 RNA-DNA 杂合分子。"},{"k":"合成第二链","t":"RNase H 在杂合链的 RNA 上切口作引物，DNA 聚合酶Ⅰ合成第二链，S1 核酸酶切去发夹环，得双链 cDNA。"},{"k":"加接头连载体","t":"末端补平后加 EcoRI 接头（或同聚物尾），先甲基化保护内部酶切位点，再与噬菌体或质粒载体连接。"},{"k":"转化与扩增","t":"体外包装后转染大肠杆菌，或直接转化，扩增后得到可长期保存、可筛选用 cDNA 文库。"},{"k":"与基因组文库区别","t":"cDNA 文库只含表达的基因、无内含子与启动子，具组织与发育时期特异性；基因组文库含全部 DNA 片段。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0732","subj":"631","chap":"七、分子生物学技术","type":"问答","years":[],"q":"简述基因芯片的原理、优势及主要应用。","points":[{"k":"杂交原理","t":"把大量已知序列的探针高密度有序固定在固相基片（玻片、尼龙膜）上，与荧光标记的样品核酸杂交，扫描荧光强度反映丰度。"},{"k":"操作流程","t":"样品 RNA 逆转录并荧光标记→与芯片杂交→洗脱→激光共聚焦扫描→图像处理与归一化分析。"},{"k":"芯片类型","t":"分 cDNA 芯片（PCR 产物点样）与寡核苷酸芯片（原位光刻合成，如 Affymetrix 的短寡核苷酸阵列）。"},{"k":"主要优势","t":"可并行检测成千上万基因，高通量、样品用量少、自动化程度高，结果可定量比较。"},{"k":"主要应用","t":"基因表达谱分析、SNP 与突变检测、拷贝数变异、病原体分型与耐药基因、药物靶点筛选及个体化用药。"},{"k":"局限","t":"成本较高，探针交叉杂交会产生假阳性，结果依赖生物信息学分析与验证（qPCR、测序）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0733","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"问答","years":[],"q":"列举出 8 个影响分子生物技术发展的重大发现和技术发明。","points":[{"k":"遗传物质与结构","t":"①1944 年 Avery 肺炎球菌转化实验证明 DNA 是遗传物质；②1953 年 Watson-Crick 提出 DNA 双螺旋模型；③1958 年 Meselson-Stahl 证实半保留复制。"},{"k":"密码与中心法则","t":"④1961 年 Nirenberg 等破译遗传密码，确立中心法则。"},{"k":"工具酶与重组","t":"⑤1970 年 Smith 发现限制性内切酶；⑥1973 年 Cohen-Boyer 建立重组 DNA 技术（质粒载体+转化）；⑦1967 年 Gellert 发现 DNA 连接酶。"},{"k":"测序与扩增","t":"⑧1977 年 Sanger 建立双脱氧链终止测序法；⑨1983 年 Mullis 发明聚合酶链反应（PCR）。"},{"k":"基因组与编辑","t":"⑩2001 年人类基因组计划草图完成；⑪2012 年 CRISPR-Cas9 基因编辑问世。Southern 印迹（1975）、基因芯片（1995）、RNAi（1998）亦可列举。"}],"note":"题目只要求列举 8 项，年份按主流教材记载，不同资料表述略有出入。","opts":[],"printed_answer":""},{"id":"n0734","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"问答","years":[],"q":"Sanger 双脱氧核苷酸终止法测序的原理是什么？","points":[{"k":"双脱氧终止","t":"ddNTP 的 2′、3′ 位均脱氧，缺乏 3′-OH，掺入后无法与下一个 dNTP 形成磷酸二酯键，链延伸就此终止。"},{"k":"四管反应体系","t":"单链模板+引物+DNA 聚合酶+四种 dNTP，分四管各加入少量 ddATP、ddTTP、ddGTP、ddCTP 之一。"},{"k":"片段长度分离","t":"每管得到以同一碱基结尾、长度连续递增的一组片段，经高分辨聚丙烯酰胺凝胶电泳或毛细管电泳按长度分离。"},{"k":"由短到长读序","t":"从凝胶最下端（最短片段）向上依次读取条带所在泳道的碱基，即得新合成链的 5′→3′ 序列，取互补得模板序列。"},{"k":"荧光自动化","t":"四色荧光 ddNTP 单管反应、毛细管电泳与激光检测实现自动化，是第一代测序的主流，也是人类基因组计划的核心技术。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0735","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"问答","years":[],"q":"简述色氨酸操纵子的衰减效应。","points":[{"k":"前导区结构","t":"trp 操纵子启动子下游有前导区，编码含 2 个连续 Trp 的前导肽，其 mRNA 可分 1、2、3、4 四个互补区段。"},{"k":"高Trp终止","t":"Trp 充足时核糖体快速通过前导肽，1 区被占据，2 区游离后与 3 区不能配对，3 区与 4 区配对形成终止发夹并带 polyU，转录提前终止。"},{"k":"低Trp通读","t":"Trp 缺乏时核糖体停滞在 1 区的 Trp 密码子，2 区与 3 区配对形成抗终止发夹，4 区不能形成终止子，聚合酶通读结构基因。"},{"k":"与阻遏协同","t":"Trp 充足时阻遏与衰减同时作用，转录降到极低；Trp 不足时两者同时解除，形成两级串联的精细调控。"},{"k":"生物学意义","t":"衰减比单纯阻遏响应更快、幅度更大（可再降 10 倍），避免浪费氨基酸与能量去合成不需要的酶。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0736","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"问答","years":[],"q":"什么是 RNA 编辑，其有什么生物学意义?","points":[{"k":"定义","t":"RNA 编辑是转录后对 RNA 序列进行核苷酸插入、删除或替换，使产物序列与 DNA 模板不完全一致的过程。"},{"k":"碱基替换型","t":"胞嘧啶脱氨为尿嘧啶（C→U，APOBEC 家族），腺嘌呤脱氨为次黄嘌呤（A→I，ADAR 酶），A→I 被翻译机器读作 G，改变密码子。"},{"k":"插入删除型","t":"锥虫线粒体由 guide RNA 指导，经编辑体（editosome）在 mRNA 中插入或删除尿苷酸，重建可读框。"},{"k":"生物学意义","t":"扩充遗传信息容量，一个基因产生多种蛋白；校正移码、调控翻译效率；参与神经发育、免疫与昼夜节律。"},{"k":"与疾病及技术","t":"编辑异常与肿瘤、神经退行性疾病、自身免疫相关；机制被用于 RNA 药物设计与基因治疗。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0737","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"问答","years":[],"q":"现要将一段外源基因构建到表达载体上，以下为经 PCR 扩增出的外源基因的一段序列图\n5'-CACGGATCCATGATCCATCTCGTTGGACA....TTCGAGTGGCCGAATGCATTAGAAGCTTCAT\n3'-GTGCCTAGGTACTAGGTAGAGCAACCTGT....AAGCTCACCGGCTTACGTAATCTTCGAAGTA\nA\n(1)请写出或在上序列图上用线框出构建在基因两端的两个限制性内切酶的识别序列\n(2)请写出一对能扩散以上序列的 PCR 引物，要求各包含基因序列的 16 个。。。\n(3)……","points":[{"k":"识别两个位点","t":"(1) 5′ 端 CAC 之后为 GGATCC，是 BamHI 识别位点；3′ 端含 AAGCTT，是 HindIII 识别位点，二者均为回文序列。"},{"k":"正向引物","t":"(2) 5′-CGCGGATCCATGATCCATCTCGTTGGACA-3′：5′ 加 CG 保护碱基+BamHI 位点+起始密码 ATG 起的基因 5′ 端序列。"},{"k":"反向引物","t":"5′-CCCAAGCTTCTAATGCATTC-3′：5′ 加保护碱基+HindIII 位点+基因 3′ 末端序列的反向互补，与模板反向平行。"},{"k":"引物设计要点","t":"长度 18~25 nt，GC 含量 40%~60%，两条 Tm 相近；5′ 端酶切位点外侧需加 2~4 个保护碱基，避免引物自身二聚体和发夹。"},{"k":"克隆策略","t":"(3) PCR 产物与表达载体同用 BamHI/HindIII 双酶切，定向连接，避免载体自连；插入片段需与载体读框一致并保留终止密码子。"}],"note":"原卷序列中间以省略号省略，引物按所给的 5′、3′ 两端序列设计；保护碱基种类与数目可据酶切效率调整。","opts":[],"printed_answer":""},{"id":"n0738","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"论述","years":[],"q":"关于 SD 编码序列的","points":[{"k":"SD序列定义","t":"SD 序列（Shine-Dalgarno 序列）是原核 mRNA 5′ 非翻译区中富含嘌呤的保守序列，典型为 AGGAGG，位于起始密码上游。"},{"k":"与16S rRNA配对","t":"与 30S 亚基中 16S rRNA 3′ 端的 anti-SD 序列（ACCUCCU）互补配对，把核糖体定位到起始密码子上。"},{"k":"位置与效率","t":"距起始密码 8~13 nt 时起始效率最高；间距过近过远、互补过强（不易释放）或过弱（结合不牢）都会降低翻译水平。"},{"k":"多顺反子识别","t":"原核多顺反子 mRNA 每个顺反子各有 SD 序列，可独立起始翻译，是操纵子中各基因协同表达的翻译基础。"},{"k":"真核的对应","t":"真核 mRNA 无 SD 序列，靠 5′ 帽子结合 eIF4E 与 Kozak 序列（ACCAUGG）引导 40S 亚基扫描定位起始密码。"}],"note":"题干仅写“关于 SD 编码序列的”，信息不完整，此处按 SD 序列的核心考点作答。","opts":[],"printed_answer":""},{"id":"n0739","subj":"880","chap":"第十章 糖酵解 糖异生","type":"填空","years":["99"],"q":"在糖酵解途径中，有三个酶是调节控制酶，它们分别是（          ）（          ）（          ）","points":[{"k":"答案","t":"①己糖激酶（肝内为葡萄糖激酶）②磷酸果糖激酶-1（PFK-1）③丙酮酸激酶。三者催化的反应都不可逆，其中 PFK-1 为最重要限速酶，受 ATP、柠檬酸抑制，AMP、果糖-2,6-二磷酸激活。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0740","subj":"880","chap":"第四章 蛋白质","type":"填空","years":["99"],"q":"α 亚基是（          ）酶的一个亚基，其主要功能与（          ）有关","points":[{"k":"答案","t":"大肠杆菌 RNA 聚合酶的 α 亚基；主要功能与核心酶组装及启动子（UP 元件）识别有关。全酶为 α₂ββ'σω，α 亚基参与核心酶装配，并与 β 亚基一起结合上游 UP 元件。"}],"note":"题干未指明是哪种酶，按通行教材（大肠杆菌 RNA 聚合酶）作答；若指 ATP 合酶，α 亚基则参与 F₁ 头部结构组成、结合核苷酸而无催化活性。","opts":[],"printed_answer":""},{"id":"n0741","subj":"880","chap":"第七章 核酸","type":"填空","years":["99"],"q":"DNA 作为遗传物质的直接证据是（          ），间接证据是（          ）（          ）（          ）","points":[{"k":"答案","t":"直接证据：肺炎链球菌转化实验（Griffith 体内转化、Avery 体外转化）及 Hershey-Chase 噬菌体同位素标记实验。间接证据：①同种生物各组织细胞的 DNA 含量恒定，体细胞为精子（单倍体）的 2 倍；②DNA 代谢稳定，不受年龄、营养与环境改变；③DNA 的紫外吸收峰 260 nm 与诱变最有效波长一致；④DNA 只在 S 期复制并均分子细胞。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0742","subj":"880","chap":"第十章 糖酵解 糖异生","type":"填空","years":["99"],"q":"在 TCA 循环中，唯一一步底物磷酸化的步骤是（          ）联系糖酵解和 TCA 循环的物质是（          ）","points":[{"k":"答案","t":"①琥珀酰CoA→琥珀酸，由琥珀酰CoA合成酶（硫激酶）催化，生成 GTP（动物）或 ATP，是 TCA 循环唯一一步底物水平磷酸化；②联系糖酵解与 TCA 循环的物质是丙酮酸，经丙酮酸脱氢酶复合体氧化脱羧成乙酰CoA 后进入循环。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0743","subj":"880","chap":"第五章 酶","type":"填空","years":["99"],"q":"米氏方程中 Km 的物理意义是（          ）其单位为（          ）根据 1/Km 的大小，可以推断酶与底物（          ）","points":[{"k":"答案","t":"Km 是反应速度达最大速度一半（v=Vmax/2）时的底物浓度，反映酶与底物的亲和力；单位为浓度单位 mol/L（常用 mmol/L）；1/Km 越大（Km 越小）亲和力越强，1/Km 越小亲和力越弱。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0744","subj":"880","chap":"第七章 核酸","type":"填空","years":["99"],"q":"DNA 重组的步骤包括（          ）（          ）（          ）（          ）","points":[{"k":"答案","t":"①切断：内切酶/重组酶在特定位点制造断裂，如 RecBCD 产生 3'单链末端；②侵入与交换：单链侵入同源双链形成 D-loop，发生链交换；③连接：DNA 连接酶封闭切口，形成 Holliday 交叉；④交叉迁移、切开与修复，得到重组分子。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0745","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"填空","years":["99"],"q":"AUG 这一密码子编码（          ）氨酸，同时它又是（          ）密码子","points":[{"k":"答案","t":"甲硫氨酸（蛋氨酸）；同时又是起始密码子。原核以甲酰甲硫氨酸（fMet）起始，真核以 Met 起始；AUG 在链内仍编码 Met。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0746","subj":"880","chap":"第七章 核酸","type":"简答","years":["99"],"q":"哪些因素会引起 DNA 损伤?何谓诱导修复?","points":[{"k":"物理因素","t":"紫外线可使 DNA 同一条链上两个相邻胸腺嘧啶之间形成二聚体（环丁烷结构），CT、CC 之间也可少量形成，导致复制、转录受阻；电离辐射等物理因素亦可造成损伤。"},{"k":"化学诱变剂","t":"①碱基类似物：如 5-溴尿嘧啶，复制时可取代正常碱基掺入并与互补链碱基配对；②碱基修饰剂：如烷化剂，修饰碱基而改变其配对性质；③嵌入染料：如溴化乙锭，插入碱基对之间造成两条链错位，引起移码突变。"},{"k":"诱导修复定义","t":"细胞 DNA 受到严重损伤或复制系统受抑制的紧急情况下，由应急反应（SOS）诱导出一种缺乏校对功能的 DNA 聚合酶、跨越损伤进行合成修复的过程；因不具备校正功能而极易引入突变，故也称易错修复，但允许错配可增加存活机会、避免细胞死亡。"},{"k":"SOS诱导过程","t":"严重损伤激活 RecA，RecA 促进 LexA 自分解而解除抑制，引发基因表达并进行 DNA 修复；同时激活 P53→产生 P21→抑制 E₂F，使细胞分裂停止在 G1 期检查点、等待修复完成。"},{"k":"修复的代价","t":"该修复以允许错配通过损伤位点为代价，保命而不保真，是突变的重要来源。"}],"note":"口径：依据《真题分类》资料原文（物理因素、化学诱变剂三类、诱导修复定义与 SOS 过程）；末点对代价的概括由原文「极易引入突变」引出。","opts":[],"printed_answer":"","ref":true},{"id":"n0747","subj":"880","chap":"第九章 生物膜","type":"简答","years":["99"],"q":"简述什么是生物膜，其主要生理功能有哪些?","points":[{"k":"生物膜定义","t":"是细胞、细胞器和其他环境接界的所有膜结构的总称，为镶嵌有蛋白质和糖类（统称糖蛋白）的磷脂双分子层，起着划分和分隔细胞与细胞器的作用，其上含大量酶的结合位点。"},{"k":"屏障与区室化","t":"将细胞与外界环境隔开，为生命活动提供相对稳定的内环境；内膜系统还把胞内空间区域化，形成若干小区室，利于进行特定生化反应。"},{"k":"能量转换","t":"如光合磷酸化与氧化磷酸化，这些能量转换都与生物膜直接相关。"},{"k":"物质运输","t":"生物膜是细胞与外界物质交换的必经之地，对物质进出有高度选择性，因膜上有专一的运送载体、酶系与通道；方式主要有简单运输、协助扩散、主动运输、胞吞胞吐。"},{"k":"识别与信息传递","t":"质膜上存在多种专一受体，接受激素的作用信息并传入细胞内部，或介导细胞与细胞之间的连接。"},{"k":"合成与分解","t":"生物膜形成庞大表面积，为多种酶提供结合位点，使酶促反应高效有序进行，如粗糙内质网膜上合成蛋白质、细菌质膜上合成核酸、质膜外表面附着水解酶类。"}],"note":"口径：依据《真题分类》资料原文，五项生理功能照录。","opts":[],"printed_answer":"","ref":true},{"id":"n0748","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["99"],"q":"什么是蛋白质的变性与复性?在变性过程中，往往有哪些现象出现?","points":[{"k":"变性","t":"蛋白质在某些物理和化学因素作用下其特定的空间构象被改变，导致理化性质改变和生物活性丧失；变性不破坏一级结构，只破坏二级以上的高级结构。"},{"k":"复性","t":"若变性条件不剧烈则变性可逆，除去变性因素后在适当条件下变性蛋白可恢复天然构象与生物活性；若变性条件剧烈持久则不可逆。"},{"k":"溶解度下降","t":"疏水基团外露，导致溶解度降低而产生沉淀。"},{"k":"流体性质改变","t":"分子不对称性增加，使黏度增加、扩散系数降低。"},{"k":"活性丧失易酶解","t":"生物活性降低甚至丧失；次级键被破坏、分子结构松散，不能形成结晶，且易被蛋白酶水解。"}],"note":"口径：依据《真题分类》资料原文，变性现象按原文五类表述归并。","opts":[],"printed_answer":"","ref":true},{"id":"n0749","subj":"880","chap":"第四章 蛋白质","type":"简答","years":["99"],"q":"什么是抗体?简述其结构特点（可用简图表示）","points":[{"k":"抗体定义","t":"在抗原物质刺激下，由 B 细胞分化成的浆细胞所产生、可与相应抗原发生特异性结合反应的免疫球蛋白。"},{"k":"四链Y形","t":"由两两对称的四条多肽链借二硫键和非共价键连接成「Y」形，两条长的为重链、两条短的为轻链；轻链与重链之间、重链与重链之间均由二硫键连接。"},{"k":"可变区与结合部位","t":"轻链 N 端为可变区（V 区）、氨基酸序列多变，C 端为恒定区（C 区）、序列保守，重链由一个 V 区和 3 个 C 区组成；轻、重链 V 区共同构成抗原结合部位，位于「Y」的两个分叉顶端，每个单体有 2 个结合部位、为二价。"},{"k":"铰链区与片段","t":"基部和两个分叉的连接处为铰链区，可被蛋白酶断裂：基部为 Fc 片段（一般容易结晶），两个分叉为 Fab，也称抗原结合片段。"},{"k":"五类抗体","t":"按 C 区氨基酸序列及抗原性的差异，抗体可分为 IgG、IgA、IgM、IgD 和 IgE。"}],"note":"口径：依据《真题分类》资料原文。简图：画「Y」形，标注重链、轻链、V 区、C 区、铰链区及 Fab、Fc 两部分。","opts":[],"printed_answer":"","ref":true},{"id":"n0750","subj":"880","chap":"第三章 氨基酸","type":"简答","years":["99"],"q":"简述从 AA 混合物中分离鉴定 AA 的方法（AA 表示氨基酸）","points":[{"k":"层析法","t":"纸层析或薄层层析利用各氨基酸在两相中分配系数不同而分离，以 Rf 值（相对迁移率）与标准品比对定性。"},{"k":"离子交换层析","t":"按 pI 与电荷差异，用阳离子/阴离子交换树脂并加 pH 或盐梯度洗脱，氨基酸分析仪即用此原理分离柱。"},{"k":"电泳法","t":"高压电泳按电荷/质量比分离；双向电泳（电泳+层析）分辨力更高，茚三酮显色定位斑点。"},{"k":"分子筛","t":"凝胶过滤按相对分子质量分离，大分子先出柱，适用于肽段与较大分子的分离。"},{"k":"显色与定量","t":"茚三酮显色（多数氨基酸蓝紫色，脯氨酸黄色）定性并比色定量；紫外 280 nm、凯氏定氮可辅助。"},{"k":"自动化方法","t":"氨基酸自动分析仪（柱后茚三酮或 OPA 衍生）+高效液相色谱，或 LC-MS/MS 精确定量与鉴定。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0751","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["02"],"q":"A. pribnow 盒既是 TATA 盒","points":[{"k":"答案","t":"不是同一元件。Pribnow 盒是原核启动子 −10 区的共有序列 TATAAT，由 σ 因子识别；TATA 盒是真核 Ⅱ 类启动子 −25~−30 区的 TATAAA，由 TFⅡD（TBP）识别。"},{"k":"共同点","t":"两者都富含 A/T、位于起点上游、参与解链与聚合酶定位，功能相当但序列、位置与识别蛋白均不同。"}],"note":"原题选项在转录中丢失，此处按考点形式给出正误判断。","opts":[],"printed_answer":"A"},{"id":"n0752","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"考点","years":["02"],"q":"A 记住抗体是由基因重排产生就可以","points":[{"k":"答案","t":"A。抗体多样性主要由基因重排产生：B 细胞发育中 V、D、J 片段经 RAG 重组酶重排，加上连接多样性（N/P 区）与体细胞高频突变，形成海量不同特异性的 Ig。"}],"note":"","opts":[],"printed_answer":"A"},{"id":"n0753","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["02"],"q":"B 真核基因组中非编码序列占 90%以上","points":[{"k":"答案","t":"B。真核基因组绝大部分不编码蛋白质：人类编码序列不足 2%，内含子、重复序列与基因间序列合计占 90% 以上，故「非编码序列占 90% 以上」成立。"}],"note":"","opts":[],"printed_answer":"B"},{"id":"n0754","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"考点","years":["02"],"q":"对一克隆的 DNA 构型图谱分析，需要（B）B、限制性核酸内切酶","points":[{"k":"答案","t":"B 限制性核酸内切酶。它识别 DNA 特异序列并在固定位点切割，产生长度确定的片段，是构建限制性构型图谱的核心工具；电泳只负责分离片段，连接酶、聚合酶不产生位点特异性切割。"}],"note":"","opts":[],"printed_answer":"B"},{"id":"n0755","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"考点","years":["02"],"q":"DNA 甲基化是()","points":[{"k":"答案","t":"DNA 甲基化是一种表观遗传修饰：在 DNA 甲基转移酶催化下，CpG 岛胞嘧啶的 5 位碳被甲基化为 5-甲基胞嘧啶。它不改变碱基序列而抑制基因转录，参与 X 染色体失活、基因组印记与肿瘤发生。"}],"note":"原卷选项缺失。","opts":[],"printed_answer":""},{"id":"n0756","subj":"631","chap":"一、染色体结构","type":"考点","years":["02"],"q":"D 所谓 DNaseI 保护足迹分析（可用于名词解释）DNaseI 是通用的脱氧核糖核酸酶，可以消化 DNA，在用其消化真核 DNA 时，由于 DNA，在用其消化真核 DNA 时，由于 DNA 有【…?】的核小体及更高级别的折叠结构，会发现切割仅发生在部分因转录而变疏松的部位，因此可用此进行研究转录活性区域。同时也可研究 DNA 与蛋白质的相互作用（DNaseI 保护足迹分析 DNaseI 足迹法）即用蛋白质和 DNA 结合后，再用酶消化，同蛋白质结合的 DNA 区段会因受保护而不被切割而得以保留，除去结合蛋白质进行电泳即可得到可结合蛋白质 DNA 区段。","points":[{"k":"答案","t":"D。DNase Ⅰ 足迹法：蛋白质与 DNA 结合后，结合区段受保护而不被 DNase Ⅰ 切割；除去蛋白后电泳，胶上出现一段缺失的「足迹」，据此定位蛋白结合位点、研究 DNA-蛋白质相互作用，也可借切割敏感性判断转录活跃的疏松染色质区。"}],"note":"","opts":[],"printed_answer":"D"},{"id":"n0757","subj":"631","chap":"七、分子生物学技术","type":"考点","years":["02"],"q":"酵母双杂交系统可用于研究蛋白质的（D）D、相互作用","points":[{"k":"答案","t":"D 相互作用。酵母双杂交把诱饵蛋白与猎物蛋白分别连在 GAL4 的 DNA 结合域与激活域上，只有两蛋白结合才能重建转录因子、激活报告基因，用于检测蛋白质—蛋白质相互作用并筛选互作蛋白。"}],"note":"","opts":[],"printed_answer":"D"},{"id":"n0758","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["02"],"q":"蛋白质内含子是（）A 只在前体 RNA 中存在的内容子","points":[{"k":"答案","t":"A。蛋白质内含子（intein）是翻译产物中一段可自我剪接去除的肽段，剪接在蛋白质水平完成，两侧外显肽直接以肽键相连，不需剪接体参与；它与 RNA 水平的内含子不是一回事。"}],"note":"原卷选项文字残缺（记为「只在前体 RNA 中存在的内容子」），按「蛋白质内含子＝intein」的定义作答。","opts":[],"printed_answer":"A"},{"id":"n0759","subj":"631","chap":"综合","type":"考点","years":["02"],"q":"分子伴侣是（）A 一种蛋白质","points":[{"k":"答案","t":"A 一种蛋白质。分子伴侣（Hsp70、Hsp60、GroEL/ES 等）帮助新生肽链或变性蛋白正确折叠、组装与跨膜转运，只加速正确构象的形成，不构成终产物，也不提供折叠信息。"}],"note":"","opts":[],"printed_answer":"A"},{"id":"n0760","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"考点","years":["02"],"q":"基因工程技术的创建是由于发现了（）C、II 型限制性内切酶","points":[{"k":"答案","t":"C Ⅱ型限制性内切酶。它识别 4~8 bp 的回文序列并在识别位点内切割，产生黏性末端，可稳定切割任意来源的 DNA，与连接酶配合实现体外重组，是基因工程诞生的技术基石。"}],"note":"","opts":[],"printed_answer":"C"},{"id":"n0761","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["02"],"q":"真核生物的 II 类启动子可含有 TATA 区、起始子、下游元件和（）C 上游元件","points":[{"k":"答案","t":"C 上游元件。真核Ⅱ类启动子由 TATA 区、起始子（Inr）、下游元件（DPE）和上游元件（GC 盒、CAAT 盒）组成；上游元件位于 -100 附近，可提高转录起始频率。"}],"note":"","opts":[],"printed_answer":"C"},{"id":"n0762","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"考点","years":["02"],"q":"色氨酸操纵子的弱化作用是通过前导区的（C 翻译）而达成","points":[{"k":"答案","t":"C 翻译。弱化作用依赖前导区（trpL）所编码前导肽的翻译：色氨酸充足时核糖体顺利通过两个 Trp 密码子并占据 2 区，2-3 不能配对，3-4 配对形成终止子发夹，转录提前终止；色氨酸缺乏时核糖体停滞在 1 区，2 区空出与 3 区配对，3-4 无法形成终止结构，RNA 聚合酶继续转录结构基因。"}],"note":"","opts":[],"printed_answer":"C"},{"id":"n0763","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["02"],"q":"原核生物启动子中-10 区域-35 区域的最佳距离是（）B17bp。解析：16-19bp","points":[{"k":"答案","t":"B 17 bp。原核启动子 -10 区与 -35 区最佳间距为 16~19 bp（约 17 bp），相当于 B 型 DNA 约 1.5 圈，便于同一 σ 因子同时识别两个区；间距增减都会显著降低启动子活性。"}],"note":"","opts":[],"printed_answer":"B"},{"id":"n0764","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":["02"],"q":"原核生物有三种 RNA 聚合酶","points":[{"k":"答案","t":"错。原核生物只有一种 RNA 聚合酶（核心酶 α₂ββ'ω，结合 σ 成全酶 holoenzyme），靠更换 σ 因子识别不同启动子；具有Ⅰ、Ⅱ、Ⅲ 三种核 RNA 聚合酶的是真核生物。"}],"note":"","opts":[],"printed_answer":"错"},{"id":"n0765","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":["02"],"q":"一个基因可以编码不同的蛋白质","points":[{"k":"答案","t":"对。同一基因可通过可变剪接、不同启动子或不同 poly(A) 位点生成多种 mRNA，翻译出不同蛋白质，如降钙素基因在甲状腺产降钙素、在神经组织产 CGRP。"}],"note":"","opts":[],"printed_answer":"对"},{"id":"n0766","subj":"631","chap":"综合","type":"判断","years":["02"],"q":"细胞质中 RNA 的 poly(A)长度通常比细胞核中 RNA 的 poly(A)长度要短","points":[{"k":"答案","t":"对。mRNA 进入细胞质后 poly(A) 尾在核酸酶作用下逐步缩短，去腺苷酸化是 mRNA 降解的限速步骤，故胞质 mRNA 的 poly(A) 明显短于核内前体。"}],"note":"","opts":[],"printed_answer":"对"},{"id":"n0767","subj":"631","chap":"五、RNA 的调控机制","type":"判断","years":["02"],"q":"gRNA 与 RNA 干涉有关","points":[{"k":"答案","t":"错。gRNA 介导的是 RNA 编辑，如锥虫线粒体以 gRNA 为模板通过插入或删除 U 改写 mRNA 序列；RNA 干涉由 siRNA、miRNA 与 RISC 介导，与 gRNA 无关。"}],"note":"","opts":[],"printed_answer":"错"},{"id":"n0768","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":["02"],"q":"转录后调控这种基因表达的调控方式只见于真核生物","points":[{"k":"答案","t":"错。原核同样有转录后调控：mRNA 二级结构形成的衰减子、RNase 决定的 mRNA 半衰期、反义 RNA（MicF、OxyS）及 sRNA-伴侣蛋白系统都作用于转录之后。"}],"note":"","opts":[],"printed_answer":"错"},{"id":"n0769","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":["02"],"q":"在细菌中 RNA 聚合酶通过变化 σ 因子就可以转录不同基因","points":[{"k":"答案","t":"错。更换 σ 因子只改变启动子识别特异性（如热休克 σ³²），转录还须核心酶及激活蛋白、操纵子系统的配合；不同基因的转录水平还取决于启动子强度与阻遏状态，不能只靠换 σ 因子。"}],"note":"","opts":[],"printed_answer":"错"},{"id":"n0770","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":["02"],"q":"snRNA 主要参与核 mRNA 前体的加工","points":[{"k":"答案","t":"对。snRNA（U1、U2、U4、U5、U6）与蛋白质组装成 snRNP，通过与 5'剪接点、分支点配对催化剪接体装配和内含子切除，主要参与核内 mRNA 前体的加工。"}],"note":"","opts":[],"printed_answer":"对"},{"id":"n0771","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":["02"],"q":"由于密码子不是重叠的。故所有基因都不是重叠的","points":[{"k":"答案","t":"错。密码子不重叠指同一阅读框内三联体不重叠，与基因是否重叠是两回事：φX174、SV40 等存在重叠基因，同一段 DNA 以不同阅读框编码不同蛋白质。"}],"note":"","opts":[],"printed_answer":"错"},{"id":"n0772","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"判断","years":["02"],"q":"DNA 的复制需要 DNA 聚合酶和 RNA 聚合酶","points":[{"k":"答案","t":"对。延伸由 DNA 聚合酶催化，但起始必须先由引物酶（一种 RNA 聚合酶，原核为 DnaG）合成 RNA 引物提供 3'-OH，故 DNA 聚合酶与 RNA 聚合酶都需要。"}],"note":"","opts":[],"printed_answer":"对"},{"id":"n0773","subj":"631","chap":"综合","type":"判断","years":["02"],"q":"一个顺反子相当于一个基因","points":[{"k":"答案","t":"对。顺反子（cistron）是顺反测验确定的功能单位，即编码一条多肽链的基因；一个顺反子相当于一个基因，多顺反子 mRNA 则含多个基因。"}],"note":"","opts":[],"printed_answer":"对"},{"id":"n0774","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"判断","years":["02"],"q":"嘧啶二聚体的修复过程不涉及磷酸二酯键的切断和重生","points":[{"k":"答案","t":"卷面判对。光复活修复中光复活酶吸收可见光，直接断裂胸腺嘧啶二聚体的环丁烷环、恢复原来碱基，全程不涉及磷酸二酯键的切断与重接。"}],"note":"若走核苷酸切除修复途径，则需核酸酶切开二聚体两侧的磷酸二酯键、聚合酶填补后由连接酶重接；卷面按光复活作答。","opts":[],"printed_answer":"对"},{"id":"n0775","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"判断","years":["02"],"q":"细菌的终止子前一段都有茎环结构","points":[{"k":"答案","t":"错（依赖 ρ 的终止子没有富 GC 回文结构，也没有寡聚 U，\"都有茎环\"不成立）。细菌不依赖 ρ 因子的终止子，其转录产物含富含 GC 的反向重复序列，可形成茎环（发夹）结构，其后紧跟富含 U 的序列；发夹使聚合酶停顿，rU-dA 配错（依赖 ρ 的终止子没有富 GC 回文结构，也没有寡聚 U，\"都有茎环\"不成立）弱促使酶与模板解离。"}],"note":"","opts":[],"printed_answer":"对"},{"id":"n0776","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["02"],"q":"说明 DNA 聚合酶、限制性内切酶、连接酶催化的反应，各自的生物功能及生物应用","points":[{"k":"聚合酶催化的反应","t":"以单链 DNA 为模板、引物 3′-OH 为起点，沿 5′→3′ 方向把 dNTP 的 α-磷酸与引物末端羟基形成磷酸二酯键，释放焦磷酸；另具 3′→5′ 外切酶校对活性。"},{"k":"聚合酶功能与应用","t":"体内参与 DNA 复制、修复与重组；体外用于 PCR、Sanger 测序、缺口平移标记、cDNA 第二链合成。"},{"k":"限制酶催化的反应","t":"识别双链 DNA 特定回文序列，水解两个核苷酸间的磷酸二酯键，产生黏性末端或平末端；体内降解外源 DNA 起防御作用。"},{"k":"限制酶应用","t":"基因克隆与载体构建、DNA 指纹与 RFLP 分析、限制酶图谱绘制、Southern 杂交探针制备。"},{"k":"连接酶催化的反应","t":"以 ATP（或 NAD⁺）供能，催化相邻的 3′-OH 与 5′-磷酸形成磷酸二酯键，封闭缺口或连接互补黏末端。"},{"k":"连接酶应用","t":"重组 DNA 中连接载体与插入片段、TA 克隆、加接头、构建测序文库，并参与体内 DNA 修复。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0777","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["02"],"q":"简述肽链的翻译后加工过程都有哪些","points":[{"k":"切除与剪切","t":"切去 N 端甲硫氨酸、信号肽或前导序列；胰岛素切除 C 肽，酶原经有限水解激活（胰蛋白酶原→胰蛋白酶）。"},{"k":"折叠与二硫键","t":"分子伴侣（Hsp70、GroEL/ES）辅助折叠，蛋白质二硫键异构酶（PDI）催化二硫键的正确配对与重排。"},{"k":"化学修饰","t":"磷酸化、糖基化、乙酰化、甲基化、羟基化（脯氨酸、赖氨酸）、γ-羧化（谷氨酸）、泛素化等，调节活性与稳定性。"},{"k":"亚基装配","t":"多亚基蛋白需组装成四级结构，如血红蛋白 α₂β₂、免疫球蛋白 H₂L₂，装配错误则无活性。"},{"k":"辅基结合与靶向","t":"结合血红素、金属离子、辅酶等辅基；靠信号肽、转运肽定向运至内质网、线粒体、叶绿体、细胞核或分泌出胞。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0778","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["02"],"q":"简述大肠杆菌翻译时掺入一个氨基酸的过程","points":[{"k":"氨基酸活化","t":"氨酰-tRNA 合成酶催化氨基酸+ATP→氨酰-AMP→氨酰-tRNA，水解放出 AMP，具校对功能保证专一性（第二遗传密码）。"},{"k":"起始复合物","t":"30S 亚基经 SD 序列结合 mRNA，fMet-tRNA 进入 P 位，再结合 50S 形成 70S 起始复合物，消耗 GTP。"},{"k":"进位","t":"EF-Tu·GTP 携带氨酰-tRNA 进入 A 位，反密码子与密码子配对，GTP 水解后 EF-Tu·GDP 释放。"},{"k":"成肽","t":"23S rRNA 具肽酰转移酶活性，把 P 位肽酰基转移到 A 位氨酰-tRNA 的氨基上，形成肽键并延长一个残基。"},{"k":"转位","t":"EF-G·GTP 驱动核糖体沿 mRNA 前移一个密码子，肽酰-tRNA 移至 P 位，A 位空出迎接下一个氨酰-tRNA。"},{"k":"终止与释放","t":"终止密码子进入 A 位，RF1/RF2 识别并促使肽链水解释放，RRF 与 EF-G 使核糖体解体，mRNA 与 tRNA 脱落。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0779","subj":"880","chap":"第四章 蛋白质","type":"实验","years":[],"q":"（1）简述其基本原理；\n（2）现有蛋白质 A 和 B，其分子量均为 100 kDa，A 蛋白由两个亚基构成，大亚基 70 kDa，小亚基 30 kDa；B 蛋白由两个 50 kDa 的亚基构成。现对 A、B 蛋白进行 SDS-PAGE 电泳，在下图中划出可能出现的电泳条带结果。（DNA Marker 和示例条带已给出）\n[图：SDS-PAGE 电泳胶示意图，泳道自左至右依次为 Marker、蛋白A、蛋白B、条带示例；左侧竖排标注\"分子量\"，Marker 泳道自上而下 7 条条带，其中 4 条条带左侧标有分子量 80kDa、50kDa、40kDa、20kDa；条带示例泳道内 1 条条带；蛋白A、蛋白B 泳道空白待填]","points":[{"k":"SDS-PAGE原理","t":"(1) SDS 与蛋白按约 1.4 g/g 结合，使蛋白变性并带大量负电荷，电荷/质量比恒定，消除原有电荷差异。"},{"k":"按分子量分离","t":"在聚丙烯酰胺凝胶中迁移率只取决于分子大小，与 Mr 的对数呈线性；凝胶的孔径起分子筛作用，小分子跑得快。"},{"k":"还原剂断二硫键","t":"样品缓冲液加 β-巯基乙醇或二硫苏糖醇（DTT）并煮沸，还原链间二硫键，多亚基蛋白解离为单条肽链。"},{"k":"A蛋白两条带","t":"(2) A 由 70 kDa 与 30 kDa 亚基组成，还原后出现 70 kDa 和 30 kDa 两条带，位置与 Marker 的 80、40 kDa 条带之间和相近处对应。"},{"k":"B蛋白一条带","t":"B 为两个 50 kDa 亚基，还原后只出现 50 kDa 一条带，与 Marker 的 50 kDa 条带齐平、条带较粗。"},{"k":"非还原条件","t":"若不加还原剂，二硫键未断，A 与 B 均停留在 100 kDa 处呈单一条带，这是判断亚基组成的关键对照。"}],"note":"原卷为示意图，Marker 标 80、50、40、20 kDa 四条；此处按加还原剂的常规考法作答。","opts":[],"printed_answer":""},{"id":"n0780","subj":"880","chap":"第三章 氨基酸","type":"论述","years":[],"q":"现有一六肽，其中含有 3 个 Gly、1 个 Arg、1 个 Ala 和 1 个 Phe。\n已知：\n用糜蛋白酶处理后生成两个三肽；\n用胰蛋白酶处理后生成 Ala；\n用 DNFB 处理后生成 DNP-Gly。\n试写出该六肽的氨基酸序列，并说明推导过程。","points":[{"k":"定N端","t":"DNFB（Sanger 试剂）与 N 端游离氨基结合，酸水解后得到 DNP-Gly，故 N 端为 Gly。"},{"k":"糜蛋白酶定位","t":"糜蛋白酶切芳香族残基（Phe、Trp、Tyr）的羧基侧肽键，只生成两个三肽，说明切点在 3/4 位之间，Phe 为第 3 位。"},{"k":"胰蛋白酶定位","t":"胰蛋白酶切 Arg、Lys 的羧基侧，产物中出现游离 Ala，说明 Arg 在第 5 位、Ala 为第 6 位（C 端）。"},{"k":"补齐序列","t":"第 2、4 位由剩余 2 个 Gly 占据，得序列 Gly-Gly-Phe-Gly-Arg-Ala。"},{"k":"回验题设","t":"糜蛋白酶切 Phe-Gly 得 Gly-Gly-Phe 与 Gly-Arg-Ala 两个三肽；胰蛋白酶切 Arg-Ala 得五肽+游离 Ala；DNFB 得 DNP-Gly，全部吻合。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0781","subj":"880","chap":"综合","type":"论述","years":[],"q":"酶联免疫吸附测定（ELISA）有多种方法。请从直接法、间接法、夹心法、竞争法中任选一种，阐述其基本原理，并简述其应用。","points":[{"k":"夹心法原理","t":"抗原同时被固相上的捕获抗体与酶标检测抗体结合，形成“抗体-抗原-抗体”夹心复合物，加底物显色，颜色深浅反映抗原量。"},{"k":"操作步骤","t":"包被捕获抗体→封闭（BSA/脱脂奶）→加待测样品→加酶标二抗（识别另一表位）→洗涤→加 TMB 底物→加酸终止→读 OD450。"},{"k":"定量关系","t":"OD 值与抗原浓度正相关，用系列标准品绘制标准曲线，据样品 OD 反查浓度；灵敏度可达 pg/mL 级。"},{"k":"主要应用","t":"检测血清 HBsAg、hCG（早孕）、细胞因子（IL-6、TNF-α）、肿瘤标志物（AFP、CEA）及病原体抗原。"},{"k":"优缺点","t":"特异性高、可测复杂样本；但需一对识别不同表位的配对抗体，小分子半抗原因表位单一不适用。"},{"k":"其他三法要点","t":"直接法酶标一抗、步骤少；间接法酶标二抗、可信号放大、常用于测抗体；竞争法信号与待测物含量负相关，适合小分子。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0782","subj":"880","chap":"第十一章 柠檬酸循环","type":"论述","years":[],"q":"试述为什么三羧酸循环是糖类、脂类和蛋白质三大营养物质代谢的共同通路和中心枢纽。","points":[{"k":"三大物质汇入","t":"糖→丙酮酸→乙酰CoA；脂肪→甘油+脂肪酸→乙酰CoA；蛋白质→氨基酸→乙酰CoA、丙酮酸、α-酮戊二酸、琥珀酰CoA、延胡索酸或草酰乙酸。"},{"k":"共同末端通路","t":"乙酰CoA 与草酰乙酸缩合成柠檬酸进入循环，是糖、脂、蛋白质彻底氧化为 CO₂ 和 H₂O 的共同途径。"},{"k":"产能中心","t":"每轮产 3 NADH、1 FADH₂、1 GTP，还原当量经呼吸链氧化磷酸化生成大量 ATP，是细胞供能的主要环节。"},{"k":"合成前体来源","t":"草酰乙酸→糖异生；α-酮戊二酸→谷氨酸；琥珀酰CoA→血红素；乙酰CoA→脂肪酸、胆固醇；Asp、谷氨酰胺→嘌呤嘧啶。"},{"k":"回补反应","t":"丙酮酸羧化酶、磷酸烯醇式丙酮酸羧激酶、谷氨酸脱氢酶等补充草酰乙酸，保证中间物被抽走时循环仍能运转。"},{"k":"双向调节","t":"循环受 NADH/ATP 抑制、ADP 与 Ca²⁺ 激活，关键酶为柠檬酸合酶、异柠檬酸脱氢酶、α-酮戊二酸脱氢酶；既分解又供给合成，处于代谢网络中心。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0783","subj":"880","chap":"综合","type":"计算","years":[],"q":"已知反应如下：\n磷酸肌酸 + ADP → 肌酸 + ATP\n题目给出磷酸肌酸、ADP、肌酸、ATP 的浓度，以及有关标准自由能变化、温度、pH、RT 和对数换算参数。\n试计算该反应在题设条件下的实际自由能变化ΔG，并写出计算过程。","points":[{"k":"列式","t":"ΔG=ΔG°′+RT·ln([肌酸][ATP]/([磷酸肌酸][ADP]))，Q 为产物浓度积与反应物浓度积之比。"},{"k":"求标准自由能","t":"由磷酸肌酸水解 ΔG°′=−43.1 kJ/mol 与 ATP 水解 −30.5 kJ/mol 相减，得该反应 ΔG°′≈−12.6 kJ/mol。"},{"k":"代入","t":"25 ℃ 时 R=8.314 J/(mol·K)、RT≈2.478 kJ/mol，将题给四种浓度代入求 Q，取自然对数后乘 RT 与 ΔG°′ 相加。"},{"k":"结论判读","t":"算得 ΔG<0 则反应自发向右，说明磷酸肌酸可有效再生 ATP；若 ΔG>0 则需与 ATP 水解偶联推动。"}],"note":"原卷的浓度、温度与 RT 数值未转写，此处给公式与标准自由能；实际作答按题给数据代入，结果带 kJ/mol。","opts":[],"printed_answer":""},{"id":"n0784","subj":"880","chap":"第七章 核酸","type":"简答","years":["20"],"q":"写一段 DNA 的互补链，并阐述 PCR 的原理","points":[{"k":"互补规则","t":"两条链反向平行，碱基互补 A-T、G-C；写互补链须按 5′→3′ 方向反向书写，切勿顺向照抄。"},{"k":"示例","t":"如模板 5′-ATGCCTAG-3′，其互补链为 3′-TACGGATC-5′，规范写作 5′-CTAGGCAT-3′。"},{"k":"变性","t":"94~95 ℃ 加热使双链间氢键断裂，模板解成单链，为引物结合暴露碱基。"},{"k":"退火","t":"降温至 50~60 ℃，一对引物按碱基互补与模板两端特异结合，温度过高结合不牢、过低则非特异扩增。"},{"k":"延伸","t":"72 ℃ 时 Taq DNA 聚合酶以 dNTP 为原料，从引物 3′-OH 起沿 5′→3′ 方向合成新链；体系还需 Mg²⁺、缓冲液与模板。"},{"k":"指数扩增","t":"变性—退火—延伸循环 25~35 次，产物按 2ⁿ 累积，可达百万倍以上，最后经琼脂糖凝胶电泳检测目的条带。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0785","subj":"880","chap":"第三章 氨基酸","type":"简答","years":["20"],"q":"根据酶解肽段分析多肽的氨基酸顺序，","points":[{"k":"全水解定组成","t":"6 mol/L HCl、110℃ 水解 24 h 使肽链完全断裂，氨基酸分析仪测各残基摩尔比，只得组成、不得顺序。"},{"k":"专一酶切片段","t":"用专一性蛋白酶定点切断：胰蛋白酶切 Lys/Arg 羧基侧，胰凝乳蛋白酶切 Phe/Tyr/Trp 羧基侧，胃蛋白酶切芳香族与酸性残基间，得若干小肽。"},{"k":"逐级降解法测序","t":"各小肽用 Edman 降解法（异硫氰酸苯酯 PITC）从 N 端逐个切下并鉴定，得到每条肽的完整序列。"},{"k":"重叠片段拼接","t":"换用另一种专一性不同的酶再切一套肽段，两套肽段互相重叠比对，即可确定各片段前后次序。"},{"k":"二硫键定位","t":"另取样品不还原直接酶解，找出含胱氨酸的肽，确定链内与链间二硫键位置及亚基连接方式。"},{"k":"拼出全程比对","t":"重叠法拼成完整一级结构，再与基因序列或数据库比对核实，末端用羧肽酶确认 C 端。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0786","subj":"880","chap":"第一章 糖类","type":"简答","years":["20"],"q":"阐述纤维素和淀粉的结构特点，以及纤维素在生活中的应用","points":[{"k":"α-1,4糖苷键","t":"淀粉以 D-葡萄糖为单位，主链靠 α-1,4 糖苷键连接，键角使链卷曲成螺旋，遇碘显蓝色。"},{"k":"α-1,6分支点","t":"支链淀粉每 24~30 个残基有一个 α-1,6 分支，分支多、末端多、水溶性好、酶解快；直链淀粉无分支。"},{"k":"β-1,4直链","t":"纤维素为 β-1,4 糖苷键，二糖重复单位为纤维二糖，链笔直无分支，每条链 300~15000 个葡萄糖。"},{"k":"氢键成微纤丝","t":"β 键使链呈伸展带状，链间大量氢键平行堆叠成结晶性微纤丝，不溶于水、抗拉强度高。"},{"k":"人体不能消化","t":"人分泌 α-淀粉酶与糖化酶，只认 α 键；无纤维素酶不能切 β 键，故纤维素不供能，仅作膳食纤维促肠蠕动。"},{"k":"工业应用广","t":"造纸、纺织、木材、生物质乙醇；衍生物有羧甲基纤维素（CMC，增稠）、微晶纤维素（药用辅料、色谱填料）、醋酸纤维、硝化纤维。"}],"note":"题干问“纤维素在生活中的应用”，实际作答把淀粉与纤维素一并比较，二者差异的根源即 α/β 糖苷键。","opts":[],"printed_answer":""},{"id":"n0787","subj":"880","chap":"第五章 酶","type":"简答","years":["20"],"q":"解释在米氏方程推导中 Km 和 Vmax 的含义，写出米氏方程，并根据双倒数曲线图判断抑制剂的类型，说明其抑制的特点","points":[{"k":"米氏方程","t":"v = Vmax[S]/(Km+[S])；前提是稳态假设、单一底物、快速平衡、初速度测定。"},{"k":"Km的物理意义","t":"Km 是 v = Vmax/2 时的底物浓度，单位为 mol/L；Km 越小酶与底物亲和力越大，Km 是酶的特征常数，与酶浓度无关。"},{"k":"Vmax的意义","t":"Vmax 是底物饱和、全部酶以 ES 形式存在时的最大速度，正比于酶浓度，单位与速度相同（μmol/min）。"},{"k":"双倒数作图","t":"取倒数得 1/v = (Km/Vmax)(1/[S]) + 1/Vmax；纵截距 1/Vmax，横截距 −1/Km，斜率 Km/Vmax。"},{"k":"竞争性抑制","t":"抑制剂与底物争活性中心，增大[S]可解除；双倒数图交于纵轴，Vmax 不变、Km 增大、斜率增大。"},{"k":"非竞争与反竞争","t":"非竞争性交于横轴：Km 不变、Vmax 下降、斜率不变；反竞争性两线平行：Km 与 Vmax 同倍数下降。"}],"note":"题干附“双倒数曲线图”但原卷无图，按三类可逆抑制的通式作答，考试时按图中交点位置对号入座。","opts":[],"printed_answer":""},{"id":"n0788","subj":"880","chap":"第十五章 脂类代谢","type":"论述","years":["20"],"q":"阐述高等生物中乙酰 CoA 的代谢去路","points":[{"k":"入三羧酸循环","t":"与草酰乙酸缩合成柠檬酸，经 TCA 彻底氧化为 CO₂，还原当量经氧化磷酸化供能，是主要去路。"},{"k":"合成脂肪酸","t":"乙酰CoA 羧化酶（生物素辅基）催化生成丙二酰CoA，再经脂肪酸合成酶系缩合还原，生成软脂酸并延长去饱和。"},{"k":"合成胆固醇","t":"两分子乙酰CoA 缩合成乙酰乙酰CoA，经 HMG-CoA、HMG-CoA 还原酶（限速）生成甲羟戊酸，进而合成胆固醇。"},{"k":"生成酮体","t":"肝线粒体内乙酰CoA 过量时两两缩合成乙酰乙酸、β-羟丁酸、丙酮，经血运至肝外组织氧化利用。"},{"k":"合成乙酰胆碱","t":"胆碱乙酰转移酶催化乙酰CoA 与胆碱结合生成乙酰胆碱，供神经递质用。"},{"k":"乙酰化解毒","t":"与磺胺、异烟肼等外源物结合成乙酰化产物排出；N-乙酰谷氨酸又是尿素循环氨甲酰磷酸合成酶Ⅰ的变构激活剂。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0789","subj":"880","chap":"第十五章 脂类代谢","type":"论述","years":["20"],"q":"写出一轮 β-氧化的代谢过程，并计算软脂酸（16C）彻底氧化分解的净合成的 ATP","points":[{"k":"活化耗两键","t":"脂酰CoA合成酶催化：软脂酸 + CoA + ATP → 软脂酰CoA + AMP + PPi，焦磷酸水解拉动，相当于消耗 2 个高能磷酸键。"},{"k":"肉碱穿梭入线粒体","t":"经 CPT-Ⅰ、肉碱-脂酰肉碱转位酶、CPT-Ⅱ 三步，长链脂酰CoA 转入线粒体基质，是β氧化的限速环节。"},{"k":"脱氢生成双键","t":"① 脂酰CoA脱氢酶（FAD 为辅基）催化 α、β 碳脱氢，生成反式Δ²-烯脂酰CoA 与 FADH₂。"},{"k":"水化再脱氢","t":"② 烯脂酰CoA水化酶加水生成 L-β-羟脂酰CoA；③ β-羟脂酰CoA脱氢酶（NAD⁺）再脱氢生成β-酮脂酰CoA 与 NADH+H⁺。"},{"k":"硫解断链","t":"④ β-酮脂酰CoA硫解酶加 CoA 断裂，生成 1 分子乙酰CoA 和缩短 2 个碳的脂酰CoA，进入下一轮。"},{"k":"能量计算","t":"16C 需 7 轮：7 FADH₂×1.5=10.5，7 NADH×2.5=17.5，8 乙酰CoA×10=80，合计 108；减活化 2，净生成 106 ATP。"}],"note":"能量按新口径（FADH₂=1.5、NADH=2.5）计为 106 ATP；旧教材用 2 与 3 计则为 129 ATP，答题时可注明所用标准。","opts":[],"printed_answer":""},{"id":"n0790","subj":"880","chap":"第六章 维生素与辅酶","type":"简答","years":[],"q":"丙酮酸羧化酶","points":[{"k":"定位于线粒体","t":"存在于线粒体基质，是糖异生的第一个限速酶，也是回补 TCA 循环中间产物的关键酶。"},{"k":"生物素辅基","t":"以生物素（维生素 B7）为共价辅基，先将 CO₂ 活化为羧基生物素，再转给丙酮酸；反应需 ATP 与 Mg²⁺。"},{"k":"乙酰CoA激活","t":"乙酰CoA 为必需变构激活剂，乙酰CoA 升高说明能量充足，促糖异生；缺乏乙酰CoA 时酶几乎无活性。"},{"k":"三大生理意义","t":"①丙酮酸→草酰乙酸，为糖异生提供起始物；②补充 TCA 的草酰乙酸；③连接糖、脂、氨基酸三大代谢。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0791","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":[],"q":"磷酸葡萄糖异构酶","points":[{"k":"催化可逆异构","t":"催化 6-磷酸葡萄糖 ⇌ 6-磷酸果糖，是糖酵解第二步，也是糖异生的倒数第二步，反应完全可逆、不耗能。"},{"k":"烯二醇中间体","t":"机制为碱催化开环生成顺式烯二醇中间体，C1 与 C2 之间发生质子转移，再闭环生成酮糖。"},{"k":"不需辅因子","t":"该酶不需 ATP、不需金属离子或辅酶，与己糖激酶、PFK-1 不同，故不是限速酶。"},{"k":"糖酵解糖异生共用","t":"因反应可逆，糖酵解与糖异生共用此酶，是两条通路少数共用步骤之一。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0792","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":[],"q":"烯脂酰 CoA 水化酶","points":[{"k":"β氧化第二步","t":"催化反式Δ²-烯脂酰CoA 加水，生成 L-β-羟脂酰CoA，位于脂酰CoA脱氢酶之后、β-羟脂酰CoA脱氢酶之前。"},{"k":"反马氏加水","t":"H 加在 α 碳、OH 加在 β 碳，符合反马氏规则；对双键有严格的顺反与立体专一性，只产出 L 型。"},{"k":"不耗能可逆","t":"属水合酶类，不需 ATP、不需辅酶，反应可逆，逆反应即脱水。"},{"k":"四酶之一","t":"与脂酰CoA脱氢酶、β-羟脂酰CoA脱氢酶、β-酮脂酰CoA硫解酶共同组成β氧化四酶体系。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0793","subj":"880","chap":"第三章 氨基酸","type":"简答","years":[],"q":"Asp：① pH=2. pH=6 解离\n② 阳离子交换树脂 lys. phe. Asp. pH=7","points":[{"k":"三个pKa值","t":"Asp 的 α-COOH pKa=1.88、侧链 β-COOH pKa=3.65、α-NH₃⁺ pKa=9.60，等电点 pI=(1.88+3.65)/2≈2.77。"},{"k":"pH2带正电","t":"pH 2 时 α-COOH 部分解离（约 57% 为 COO⁻）、β-COOH 基本未解离、α-NH₃⁺ 全质子化，净电荷约 +0.4，主要以阳离子存在。"},{"k":"pH6带负电","t":"pH 6 时两个羧基全部解离（−2）、α-氨基仍质子化（+1），净电荷约 −1，以阴离子存在。"},{"k":"pH7电荷排序","t":"pH 7 时净电荷：Lys≈+1（pI 9.74）、Phe≈−0.9（pI 5.48）、Asp≈−2（pI 2.77）。"},{"k":"阳离子交换出峰序","t":"阳离子交换树脂（带负电）中，带负电的 Asp 被排斥最先流出，近中性的 Phe 次之，带正电的 Lys 结合最牢、最后被高盐洗脱。"}],"note":"第一小问题干只写“pH=2、pH=6 解离”，按解离状态与净电荷作答；pKa 取常用教材值（Berg/Lehninger）。","opts":[],"printed_answer":""},{"id":"n0794","subj":"880","chap":"第十六章 氨基酸代谢","type":"简答","years":[],"q":"氨基酸代谢和 VB","points":[{"k":"磷酸吡哆醛核心","t":"维生素 B6（吡哆醇）转变为磷酸吡哆醛（PLP），是所有转氨酶与氨基酸脱羧酶的辅酶，以 Schiff 碱形式稳定碳负离子。"},{"k":"黄素酶氧化脱氨","t":"维生素 B2（FAD/FMN）参与 L-氨基酸氧化酶、D-氨基酸氧化酶、单胺氧化酶，催化氧化脱氨产 α-酮酸与 NH₃。"},{"k":"NAD⁺脱氢","t":"维生素 PP（烟酸/烟酰胺）构成 NAD⁺，是谷氨酸脱氢酶的辅酶，催化 Glu 氧化脱氨生成 α-酮戊二酸。"},{"k":"一碳单位叶酸B12","t":"叶酸与 B12 参与 Ser↔Gly 互变、Met 循环与 dTMP 合成，是一碳单位代谢的载体，缺乏致巨幼细胞贫血。"},{"k":"生物素与TPP","t":"生物素是羧化酶辅基（丙酮酸羧化酶、丙酰CoA羧化酶）；维生素 B1 的 TPP 是支链α-酮酸脱氢酶与 α-酮戊二酸脱氢酶的辅酶。"},{"k":"泛酸构成CoA","t":"维生素 B5（泛酸）构成辅酶 A，是氨基酸碳骨架进入 TCA 与乙酰化的枢纽。"}],"note":"题干“氨基酸代谢和 VB”过于简略，按“维生素作为氨基酸代谢酶辅酶”的对应关系作答。","opts":[],"printed_answer":""},{"id":"n0795","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":[],"q":"肉碱转移体系","points":[{"k":"内膜三步穿梭","t":"长链脂酰CoA 不能直接过线粒体内膜，需经肉碱棕榈酰转移酶Ⅰ（CPT-Ⅰ）、肉碱-脂酰肉碱转位酶、CPT-Ⅱ 三步转运。"},{"k":"CPT-Ⅰ转酯","t":"内膜外侧 CPT-Ⅰ 催化脂酰CoA + 肉碱 → 脂酰肉碱 + CoA，释出的 CoA 留在胞质循环使用。"},{"k":"转位酶交换","t":"脂酰肉碱与基质内肉碱经转位酶 1:1 反向交换穿膜，是载体介导的被动交换。"},{"k":"CPT-Ⅱ复原","t":"基质侧 CPT-Ⅱ 催化脂酰肉碱 + CoA → 脂酰CoA + 肉碱，脂酰CoA 进入β氧化，肉碱返回胞质。"},{"k":"限速与调控","t":"CPT-Ⅰ 为限速酶，受丙二酰CoA 抑制——糖充足时丙二酰CoA 高，抑制脂肪酸入线粒体，避免糖脂同时大量分解。"},{"k":"缺陷致肌病","t":"CPT-Ⅱ 或肉碱转运体缺陷引起脂质沉积性肌病、运动性肌红蛋白尿、低酮性低血糖。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0796","subj":"880","chap":"第十九章 RNA 生物合成与加工","type":"简答","years":[],"q":"mRNA 真核生物转录后加工","points":[{"k":"5′加帽","t":"转录不久即在 5′端加 7-甲基鸟苷，以 5′-5′ 三磷酸键连接；保护 5′端免受外切酶降解，并作为翻译起始与出核的识别信号。"},{"k":"3′加尾","t":"3′端在 AAUAAA 信号下游切割，由多聚腺苷酸聚合酶加 80~250 个腺苷酸，稳定 mRNA、助出核与翻译效率。"},{"k":"剪接除内含子","t":"剪接体（U1、U2、U4、U5、U6 snRNP）识别 GU-AG 规则，经两次酯交换切除内含子并连接外显子。"},{"k":"可变剪接","t":"同一前体经不同剪接方式产生多种成熟 mRNA，是高等生物蛋白多样性、组织特异表达的重要来源。"},{"k":"碱基编辑修饰","t":"包括 A→I 的 RNA 编辑、m6A 甲基化等，可改变密码子含义、影响稳定性与翻译。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0797","subj":"880","chap":"第十一章 柠檬酸循环","type":"简答","years":[],"q":"Glu → α-酮戊二酸\n丙氨酸\n① 酶+辅酶　Vit B6\n② 有 Ala. 缺乏 Asp. 为什么不缺乏 Asp","points":[{"k":"ALT转氨产丙氨酸","t":"谷丙转氨酶（ALT/GPT）催化 Glu + 丙酮酸 ⇌ α-酮戊二酸 + 丙氨酸，是可逆的氨基转移。"},{"k":"PLP为B6辅酶","t":"两种转氨酶均以磷酸吡哆醛（PLP，维生素 B6）为辅酶，经 Schiff 碱与吡哆胺循环传递氨基。"},{"k":"GDH氧化脱氨","t":"Glu 也可经谷氨酸脱氢酶（NAD⁺/NADP⁺ 为辅酶）氧化脱氨，直接生成 α-酮戊二酸、NH₃ 与 NADH。"},{"k":"Asp由草酰乙酸来","t":"草酰乙酸经天冬氨酸转氨酶（AST）接受 Glu 的氨基即生成 Asp，TCA 循环不断供应草酰乙酸，来源充足。"},{"k":"另两条补给","t":"天冬酰胺酶水解 Asn 可生成 Asp；尿素循环中天冬氨酸的氨基转入尿素后生成延胡索酸，延胡索酸经 TCA 生成草酰乙酸，再经转氨生成 Asp，故体内 Asp 不易缺乏。"},{"k":"Ala为生糖氨基酸","t":"Ala 与 Asp 都是生糖氨基酸，碳骨架可经 TCA 或丙酮酸异生为糖，氨基最终以尿素排出。"}],"note":"第二小问题意应为“Ala 缺乏时为何不缺 Asp”，按 Asp 的多来源（转氨、Asn 水解、尿素循环）作答。","opts":[],"printed_answer":""},{"id":"n0798","subj":"880","chap":"第五章 酶","type":"简答","years":[],"q":"酶动力学曲线","points":[{"k":"矩形双曲线","t":"以 v 对[S] 作图得矩形双曲线：低[S] 时 v 与[S] 成正比（一级反应），高[S] 时趋于 Vmax（零级反应，酶被饱和）。"},{"k":"双倒数直线化","t":"取双倒数后为直线，纵截距 1/Vmax、横截距 −1/Km，斜率 Km/Vmax，便于求常数与判别抑制类型。"},{"k":"三类抑制图形","t":"竞争性交于纵轴、非竞争性交于横轴、反竞争性两线平行；仅凭交点位置即可定性。"},{"k":"pH钟形曲线","t":"酶活性对 pH 呈钟形，有最适 pH；偏离时活性中心基团解离状态改变、酶变性，活性下降。"},{"k":"温度先升后降","t":"温度升高反应加快，超过最适温度后酶蛋白变性失活，曲线骤降；最适温度非酶的特征常数。"},{"k":"变构酶S形","t":"变构酶不服从米氏方程，v-[S] 呈 S 形，有正协同效应，Hill 系数 >1，双倒数图不呈直线。"}],"note":"题干“酶动力学曲线”范围宽，按 v-[S]、双倒数、抑制、pH、温度、变构六类曲线作答。","opts":[],"printed_answer":""},{"id":"n0799","subj":"880","chap":"第四章 蛋白质","type":"简答","years":[],"q":"H⁺. CO₂. BPG. 对 Mb. Hb 的结合位点 P50","points":[{"k":"P50含义","t":"P50 是氧饱和度达 50% 时的氧分压，是亲和力的量度；P50 越小亲和力越大，曲线越靠左。"},{"k":"Mb单亚基不调节","t":"肌红蛋白为单链、无亚基间协同，氧解离曲线为双曲线，P50≈2.8 mmHg；无中央孔，H⁺、CO₂、BPG 均不能影响其结合。"},{"k":"Hb四聚体协同","t":"血红蛋白为 α₂β₂ 四聚体，氧结合诱导 T 态转 R 态，曲线呈 S 形，P50≈26 mmHg。"},{"k":"H⁺波尔效应","t":"H⁺ 结合 β 链 His146 等残基，形成盐桥稳定 T 态，P50 升高、曲线右移；肺部高 pH 时左移、促结合。"},{"k":"CO₂成氨基甲酸Hb","t":"CO₂ 与 α 链 N 端缬氨酸的 α-氨基可逆结合成氨基甲酸血红蛋白，释出 H⁺ 稳定 T 态，使 P50 升高、右移。"},{"k":"BPG稳T态","t":"2,3-二磷酸甘油酸（BPG）带负电，结合 β 链中央孔的正电荷残基（Lys82、His143、N 端 Val1），稳定 T 态，降低亲和力、促组织释氧。"}],"note":"三者均使 Hb 的 P50 升高、曲线右移；Mb 无四级结构故三者均无效，这是二者最本质的区别。","opts":[],"printed_answer":""},{"id":"n0800","subj":"880","chap":"第七章 核酸","type":"简答","years":[],"q":"mRNA. 转录. 翻译\n举例 5'-ATCG-3'\n3'-TAGC-5'","points":[{"k":"碱基互补配对","t":"A 与 T（RNA 中为 U）、G 与 C 配对；已知 5′-ATCG-3′ 的互补链为 3′-TAGC-5′，两链反向平行。"},{"k":"转录T换U","t":"以 3′-TAGC-5′ 为模板，按反向互补合成 5′-AUCG-3′ 的 mRNA；若 5′-ATCG-3′ 为编码链，mRNA 与其序列相同，只是 T 换成 U。"},{"k":"密码子三联体","t":"翻译时 mRNA 从 5′向 3′每三个碱基读作一个密码子，AUC 编码异亮氨酸；本题只有 4 个碱基，不构成完整读框。"},{"k":"起始与终止","t":"真核起始密码子为 AUG（甲硫氨酸），终止密码子为 UAA、UAG、UGA，读框由起始密码子确定。"},{"k":"复制半保留","t":"复制时两条母链各自作模板合成互补子链，每个子代分子含一条母链一条新链，故子代序列与亲代完全相同。"}],"note":"题干仅给 4 bp 示例序列，不足以推出完整肽链，故只演示配对规则与读框方法。","opts":[],"printed_answer":""},{"id":"n0801","subj":"880","chap":"第四章 蛋白质","type":"实验","years":[],"q":"阐述凝胶过滤、离子交换色谱法，亲和层析用来分离纯化蛋白质的原理","points":[{"k":"凝胶过滤原理","t":"又称分子筛、大小排阻层析，基于蛋白质的大小（相对分子质量）与形状不同进行分离，也可用于相对分子质量的测定。"},{"k":"排阻与滞留","t":"凝胶颗粒的交联介质排阻大分子、只允许小分子进入颗粒内部；大分子只能在颗粒间空隙中通过，流经体积小、先流出。"},{"k":"小分子后流出","t":"小分子能进入凝胶颗粒内部，必须通过全部床体积才能流出，流经体积大、路程长，按洗脱时间不同而将各组分分离。"},{"k":"离子交换原理","t":"基于电荷行为，利用离子交换剂上可解离基团对各种离子亲和力不同而达到分离的层析技术。"},{"k":"两类交换树脂","t":"阳离子交换树脂含酸性基团、可解离出 H⁺，与溶液中其他阳离子交换而使其结合在树脂上；阴离子交换树脂含碱性基团、可解离出 OH⁻，与阴离子交换而使其结合在树脂上。"},{"k":"亲和层析原理","t":"利用生物学的特异亲和力分离纯化，如凝集素亲和（糖蛋白）、免疫亲和（抗原）、金属螯合（含金属蛋白）；层析前需插入连接臂减少位阻，层析后用特异配体亲和洗脱回收产物。"}],"note":"口径：依据《真题分类》资料原文。资料列亲和层析两个优点（可从复杂混合物中一步分离目标蛋白、纯度和产率高；可排除已失活的目标蛋白），已并入末点未删。","opts":[],"printed_answer":"","ref":true},{"id":"n0802","subj":"880","chap":"第三章 氨基酸","type":"考点","years":["18"],"q":"pH 与 pI 的关系","points":[{"k":"答案","t":"pH 与 pI 决定蛋白质的解离状态和电泳行为：pH=pI 时净电荷为零，不向任一极泳动，溶解度最低易沉淀；pH＞pI 时带负电移向正极；pH＜pI 时带正电移向负极。"}],"note":"原卷选项缺失。","opts":[],"printed_answer":""},{"id":"n0803","subj":"880","chap":"第七章 核酸","type":"考点","years":["18"],"q":"GC 碱基配对","points":[{"k":"答案","t":"G 与 C 配对形成 3 个氢键（G≡C），A 与 T 只形成 2 个氢键。故 GC 含量越高双链越稳定、Tm 越高，这也是 CpG 岛（GC 富集区）难解链的原因。"}],"note":"原卷选项缺失。","opts":[],"printed_answer":""},{"id":"n0804","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"考点","years":["18"],"q":"镰刀型红细胞贫血症的病因","points":[{"k":"答案","t":"β-珠蛋白基因第 6 位密码子发生 GAG→GTG 点突变，谷氨酸被缬氨酸取代，形成 HbS。脱氧状态下 HbS 分子间以疏水补位聚合成长纤维，红细胞镰变、变形性下降而溶血。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0805","subj":"880","chap":"第十章 糖酵解 糖异生","type":"考点","years":["18"],"q":"糖酵解的关键酶","points":[{"k":"答案","t":"己糖激酶（肝为葡萄糖激酶）、磷酸果糖激酶-1（PFK-1）、丙酮酸激酶。这三个酶催化的反应都不可逆，是糖酵解的三个限速步骤，也是调节位点。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0808","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":["18"],"q":"糖酵解的三大步骤","points":[{"k":"己糖激酶步骤","t":"葡萄糖 + ATP ─己糖激酶/Mg²⁺→ 6-磷酸葡萄糖 + ADP + H⁺；资料列激活剂为无机磷酸、柠檬酸、ATP，抑制剂为 6-磷酸葡萄糖、ADP。"},{"k":"PFK步骤","t":"6-磷酸果糖 + ATP ─磷酸果糖激酶（PFK）/Mg²⁺→ 1,6-二磷酸果糖 + ADP + H⁺；激活剂为 AMP、ADP、6-磷酸果糖（前馈激活）与 2,6-二磷酸果糖（强激活剂），抑制剂为高浓度 ATP、H⁺、柠檬酸。"},{"k":"丙酮酸激酶步骤","t":"磷酸烯醇式丙酮酸 + ADP ─丙酮酸激酶/Mg²⁺→ 丙酮酸 + ATP；激活剂为 1,6-二磷酸果糖、磷酸烯醇式丙酮酸、高浓度葡萄糖，抑制剂为高浓度 ATP、长链脂肪酸、乙酰 CoA、丙氨酸。"},{"k":"补：三步共性","t":"三步均为不可逆的限速步骤，均受变构与激素调节，构成糖酵解的调控阀门；其余反应可逆，糖异生需另用旁路酶绕过。"}],"note":"口径：依据《真题分类》资料原文。资料只列三步方程式与调节物，未写共同特征，末点由教材口径补充（k 前标「补」）；资料将 ATP 列入己糖激酶激活剂，此处按原文保留未改。","opts":[],"printed_answer":"","ref":true},{"id":"n0809","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["18"],"q":"高等生物代谢产生的乙酰 CoA 参与的代谢途径","points":[{"k":"进入TCA氧化","t":"乙酰-CoA 经 TCA 循环氧化为 CO₂ 与 ATP，并产生 NADH、FADH₂，再经氧化磷酸化产能，是主要去路。"},{"k":"合成酮体","t":"经乙酰-CoA 硫解酶生成乙酰乙酰-CoA，再由 HMG-CoA 合酶生成 HMG-CoA，经 HMG-CoA 裂解酶生成乙酰乙酸，进而生成 D-β-羟丁酸与丙酮。"},{"k":"合成脂肪酸","t":"通过脂肪酸合成途径合成脂肪酸，并可与胆固醇进一步合成其他脂类物质。"},{"k":"合成胆固醇","t":"通过类似于合成酮体的途径合成胆固醇，再进一步合成其他脂类。"},{"k":"乙醛酸循环","t":"植物中特有：2 分子乙酰-CoA 经乙醛酸循环生成草酰乙酸，再经糖异生生成葡萄糖。"},{"k":"不能合成氨基酸","t":"乙酰-CoA 不能合成氨基酸和糖类（动物中），因其不能净生成草酰乙酸等糖异生中间物。"}],"note":"口径：依据《真题分类》资料原文“去路”部分。原文另列乙酰-CoA 的三类来源（糖、脂、蛋白质），题干只问参与的代谢途径，故未收入。末点原文表述为“乙酰-CoA 不能合成氨基酸和糖类”，动物细胞中括号内说明按教材口径补充。","opts":[],"printed_answer":"","ref":true},{"id":"n0810","subj":"880","chap":"第十三章 磷酸戊糖途径、乙醛酸循环","type":"简答","years":["18"],"q":"6-磷酸葡萄糖参与的代谢途径","points":[{"k":"糖酵解通路","t":"经磷酸葡萄糖异构酶转为 6-磷酸果糖，进入糖酵解生成丙酮酸，是葡萄糖供能的入口。"},{"k":"合成糖原","t":"经磷酸葡萄糖变位酶转为 1-磷酸葡萄糖，再生成 UDPG，由糖原合酶加到糖原引物上储存。"},{"k":"磷酸戊糖途径","t":"由 6-磷酸葡萄糖脱氢酶（限速，NADP⁺ 为辅酶）脱氢生成 6-磷酸葡萄糖酸内酯，产出 NADPH 与核糖-5-磷酸。"},{"k":"糖异生释糖","t":"在肝、肾由葡萄糖-6-磷酸酶水解成游离葡萄糖，补充血糖；肌肉缺乏此酶，只能自用。"},{"k":"糖醛酸途径","t":"经 UDP-葡萄糖醛酸生成葡萄糖醛酸，用于与胆红素、药物结合解毒，并合成糖胺聚糖。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0811","subj":"880","chap":"第二章 脂类","type":"简答","years":["18"],"q":"胆固醇的偏见等。","points":[{"k":"生理重要性","t":"胆固醇是细胞膜重要组成成分，可影响膜流动性；是胆汁酸的前体，胆汁酸为两亲物质可促进小肠对脂肪与脂溶性维生素的吸收；还是皮质醇、醛固酮、睾酮、雌二醇等激素及维生素 D 的前体。"},{"k":"过多的危害","t":"胆固醇不断在血管壁上沉积、破坏血管内膜，使血管腔逐渐变窄，逐步形成动脉粥样硬化。"},{"k":"心脑血管栓塞","t":"病情加重时沉积的胆固醇出现断层，断层处形成血栓，引发心脑血管疾病，危及生命。"},{"k":"胆固醇的来源","t":"一是膳食摄取，如动物肝脏、肥肉、蛋黄；二是自身合成，可在肝脏或肠壁中以乙酰 CoA 为原料从头合成。"},{"k":"正确对待胆固醇","t":"膳食获取的胆固醇只占 20%~30%，大部分由人体自身合成，仅靠减少摄入不能从根本上治疗高胆固醇；胆固醇正常者可正常膳食以避免缺乏，高胆固醇者仍可少量摄入以补充其他营养元素。"}],"note":"口径：依据《真题分类》资料原文。题干“胆固醇的偏见等”疑为转录误识，资料原文按“胆固醇的重要性、过多危害、来源与正确对待”作答，二者为同一题，故据此改写（旧稿按“代谢与转化”作答，已弃用）。","opts":[],"printed_answer":"","ref":true},{"id":"n0812","subj":"880","chap":"第十五章 脂类代谢","type":"论述","years":["18"],"q":"写出 TCA 循环与脂肪酸氧化的相似步骤并解释原因，要求代谢式两边用结构式表示","points":[{"k":"第一步FAD脱氢","t":"TCA：HOOC-CH₂-CH₂-COOH（琥珀酸）→ HOOC-CH=CH-COOH（延胡索酸）+ FADH₂；β 氧化：R-CH₂-CH₂-CO~SCoA → R-CH=CH-CO~SCoA + FADH₂。"},{"k":"第二步加水","t":"TCA：延胡索酸 + H₂O → HOOC-CH₂-CH(OH)-COOH（L-苹果酸）；β 氧化：R-CH=CH-CO~SCoA + H₂O → R-CH(OH)-CH₂-CO~SCoA。"},{"k":"第三步NAD脱氢","t":"TCA：L-苹果酸 → HOOC-CH₂-CO-COOH（草酰乙酸）+ NADH + H⁺；β 氧化：R-CH(OH)-CH₂-CO~SCoA → R-CO-CH₂-CO~SCoA + NADH + H⁺。"},{"k":"第四步断键","t":"TCA：草酰乙酸 + CH₃CO~SCoA → HOOC-CH₂-C(OH)(COOH)-CH₂-COOH（柠檬酸）+ CoA-SH；β 氧化：R-CO-CH₂-CO~SCoA + CoA-SH → R-CO~SCoA + CH₃CO~SCoA。"},{"k":"原因","t":"二者均为循环式反应，须在一轮之后为下一轮创造条件：β 氧化要在 β 碳上重新生成羰基，以得到少 2 个碳的脂酰 CoA；TCA 要把琥珀酸转变成 α 碳带羰基的草酰乙酸，以便与乙酰 CoA 缩合成柠檬酸。故二者均经“脱氢→水合→再脱氢”在适当位置引入羰基，保证后续反应进行。"}],"note":"口径：依据《真题分类》资料原文（该条原文“相似步骤参考上一题”“结构式参考《知识点总结》”，未给具体式）。结构式按教材口径补全，原因段照录原文。","opts":[],"printed_answer":"","ref":true},{"id":"n0813","subj":"880","chap":"第七章 核酸","type":"问答","years":["18"],"q":"考察的是复制翻译内容。给出一段 DNA 序列，让写出复制出的序列，假设那段序列为编码链，推测其翻译出的氨基酸序列，并由氨基酸序列判断其能形成什么二级结构，还","points":[{"k":"双链互补复制","t":"示例 DNA 双链为 3′-GAGAATTCGT-5′ 与 5′-CTCTTAAGCA-3′；复制按 A-T、G-C 互补、反向平行，子链与母链互补，序列与亲代一致。"},{"k":"转录方向与产物","t":"由右向左转录时，以资料给出的 DNA 链为模板合成 3′-GAGAAUUCGU-5′ 的 RNA，mRNA 为 5′-GCACAUGCAAAAUUACUUGUAGCGCA-3′；RNA 聚合酶沿模板链 3′→5′ 方向、即从右向左移动。"},{"k":"查表定氨基酸","t":"从 AUG 起 5′→3′ 每三个碱基为一密码子查表，得 N-Met-Gln-Asn-Tyr-Leu-C，C 端氨基酸为 Leu。"},{"k":"反密码子配对","t":"tRNA 反密码子 5′-CUU-3′ 与密码子 5′-AAG-3′ 反向互补配对，该 tRNA 转运 Lys。"},{"k":"ProGly中断螺旋","t":"不同氨基酸形成 α 螺旋的倾向不同，Ala 倾向最大，Pro 与 Gly 最小：Pro 结构过于刚性、没有酰胺氢参与氢键键合，且易呈顺式构型；Gly 构象柔性大、不产生空间位阻，二者都易形成 β 转角和无规卷曲。"},{"k":"电荷与位阻限制","t":"相隔 3/4 个残基的 R 基带同种电荷相互排斥（如多聚 Glu、Lys）不能形成链内氢键；多聚 Thr 的极性侧链竞争氢键；Ile、Val、Trp 等侧链体积大有空间位阻；N 端带正电也使螺旋不稳定。"}],"note":"口径：依据《真题分类》资料原文。原题未给具体序列，资料自带示例序列与判断依据，已按资料保留；末点合并了资料中静电排斥、极性基团、空间位阻、螺旋两端荷电性四项。","opts":[],"printed_answer":"","ref":true},{"id":"n0814","subj":"880","chap":"第五章 酶","type":"问答","years":["18"],"q":"酶的比活力的计算，怎样算酶的提纯效率高","points":[{"k":"比活力定义","t":"比活力 = 总活力（U）/总蛋白（mg），单位 U/mg；表示每毫克蛋白所含的酶活力单位数，是酶纯度的量度。"},{"k":"总活力与总蛋白","t":"总活力 = 酶液体积（mL）× 活力浓度（U/mL）；总蛋白 = 体积 × 蛋白浓度（mg/mL，Lowry 或 Bradford 法测）。"},{"k":"纯化倍数","t":"纯化倍数 = 该步比活力 / 粗酶液比活力，随纯化步骤逐级升高。"},{"k":"回收率","t":"回收率 = 该步总活力 / 粗酶液总活力 ×100%，反映活性损失，与纯化倍数需同时看。"},{"k":"提纯效率高判据","t":"纯化倍数高而回收率不显著下降即为高效率；再以 SDS-PAGE 单一条带、HPLC 单峰、比活性达文献值佐证纯度。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0815","subj":"880","chap":"第二章 脂类","type":"问答","years":["18"],"q":"一道关于磷脂双分子层的题，好像问到其特点","points":[{"k":"两亲性自组装","t":"磷脂头部亲水、两条疏水尾，水中自发排列成双层：尾对尾向内、头朝水相，可自发闭合形成囊泡或脂质体。"},{"k":"流动性","t":"脂质可侧向扩散、旋转、摆动，跨层翻转极少；不饱和脂肪酸多、链短、温度高则流动性大，胆固醇双向调节。"},{"k":"不对称性","t":"内外两层脂质组成不同：磷脂酰丝氨酸（PS）、磷脂酰乙醇胺多在内层，磷脂酰胆碱、鞘磷脂多在外层；糖脂只朝外。"},{"k":"屏障与选择通透","t":"疏水核心阻挡离子和极性大分子，水、O₂、CO₂、乙醇等小分子可自由扩散；葡萄糖、离子需载体或通道。"},{"k":"流动镶嵌模型","t":"膜蛋白以镶嵌、半嵌入或跨膜方式分布于脂双层中，脂与蛋白均可侧向移动，膜具自封闭与融合能力。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0816","subj":"880","chap":"第七章 核酸","type":"问答","years":["18"],"q":"多聚谷氨酸，在 pH 2.0 以下成双螺旋，大于 6.0 时就结构成伸展状态","points":[{"k":"侧链羧基决定","t":"多聚谷氨酸每个残基带一个 γ-羧基，pKa≈4.3；pH 改变使侧链质子化解离状态改变，进而改变链间静电作用与氢键。"},{"k":"低pH成螺旋","t":"pH<2 时侧链全部质子化为 COOH，不带电、无同性电荷排斥，肽键间 i→i+4 氢键得以维持，形成 α 螺旋（题称双螺旋）。"},{"k":"高pH伸展","t":"pH>6 时侧链全部解离为 COO⁻，同号负电荷强烈互斥，撑开链间作用、破坏氢键，变为无规卷曲的伸展构象。"},{"k":"中间态渐变","t":"pH 2~6 之间为部分解离，螺旋与无规卷曲共存，随 pH 升高螺旋含量连续下降，呈协同的解链转变。"},{"k":"构象由电荷定","t":"这是“侧链电荷排斥破坏氢键”的经典例证，说明多肽的高级结构由侧链性质与环境 pH 共同决定；多聚赖氨酸趋势相反。"}],"note":"题干“双螺旋”应为 α-螺旋（单链螺旋），按 α-螺旋作答；若原意指两条链缠绕的双螺旋，则机理相同。","opts":[],"printed_answer":""},{"id":"n0817","subj":"880","chap":"第十八章 DNA 复制、修复、重组","type":"问答","years":["18"],"q":"重组质粒哪些特征有利于在宿主细胞内复制","points":[{"k":"有复制起点","t":"须含宿主可识别的原核复制起点（如 pBR322 的 ori、pUC 的 pMB1 ori），否则不能在细菌内自主复制。"},{"k":"松弛型多拷贝","t":"采用松弛型复制起点，拷贝数可达数百（pUC 系列 500~700），外源基因剂量高、产量大。"},{"k":"分子小易转化","t":"质粒小于 10 kb，转化效率高、不易断裂，限制酶切位点少而清晰，便于操作。"},{"k":"选择标记","t":"带抗性基因（Amp^r、Kan^r、Tet^r）用于筛选转化子；配合 lacZ′ 蓝白斑筛选重组子。"},{"k":"多克隆位点","t":"集中排列多个单一限制酶切位点（MCS），且位于报告基因内，插入后不破坏复制与抗性功能。"},{"k":"安全不接合","t":"去除 mob 等转移基因（mob⁻），不能在自然环境中自主接合传播，符合生物安全要求。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0818","subj":"880","chap":"第十章 糖酵解 糖异生","type":"问答","years":["18"],"q":"说明乳酸脱氢酶催化的化学反应，并怎样测该酶的活性","points":[{"k":"催化可逆反应","t":"LDH 催化乳酸 + NAD⁺ ⇌ 丙酮酸 + NADH + H⁺ 的可逆氧化还原反应。"},{"k":"四聚体同工酶","t":"由两种亚基按一定比例组成四聚体，体内同工酶有 5 种，在不同器官或组织中功能不同但催化相同反应，是糖酵解途径的关键酶之一。"},{"k":"紫外分光法","t":"NADH 与 NAD⁺ 在 340 nm 及 260 nm 处各有最大吸收峰，故可用 340 nm 处光吸收值的改变定量测定酶量，紫外分光光度法简单快速。"},{"k":"活力单位定义","t":"25℃、pH 7.5 条件下，A340nm/min 下降为 1.0 的酶量定为 1 个单位。"},{"k":"测定操作","t":"从肌肉匀浆提取 LDH 并以缓冲液保存；对照杯加酶与缓冲液于 340 nm 调零；样品杯依次加丙酮酸钠、NADH，摇匀后加稀释酶液 10 μL，立即于 340 nm 读数，每 0.5 min 一次连续 3 min。"},{"k":"数据处理","t":"以 A 对时间作图取反应最初线性部分求 A340nm/min 减少值；比活力（U/mL）= ΔA₃₄₀ × 稀释倍数 / 酶液加入量（10 μL）× 10⁻³，总活力 = 比活力 × 总体积（mL）。"}],"note":"口径：依据《真题分类》资料原文。反应式方向按资料写作「乳酸 + NAD⁺ ⇌ 丙酮酸 + NADH + H⁺」；活力单位与计算公式中的温度、pH、10 μL、时间均逐字照录。","opts":[],"printed_answer":"","ref":true},{"id":"n0819","subj":"880","chap":"第十七章 核苷酸代谢","type":"问答","years":["18"],"q":"为什么用嘌呤和嘧啶可以做抗癌药物","points":[{"k":"抗代谢物原理","t":"嘌呤、嘧啶类似物结构与天然碱基或核苷相似，可竞争性抑制核苷酸合成酶或被误认为底物掺入核酸，阻断 DNA 复制。"},{"k":"抑制关键酶","t":"5-氟尿嘧啶转为 5-FdUMP 抑制胸苷酸合酶，断绝 dTMP；6-巯基嘌呤抑制 PRPP 酰胺转移酶与 IMP 脱氢酶；甲氨蝶呤抑制二氢叶酸还原酶。"},{"k":"伪底物掺入","t":"6-巯基嘌呤、8-氮杂鸟嘌呤掺入 DNA 造成错配；阿糖胞苷（Ara-C）作为链终止剂掺入 DNA 阻断延伸。"},{"k":"S期特异性","t":"肿瘤细胞增殖快、核苷酸需求大，药物主要作用于 S 期，故对分裂旺盛的组织（骨髓、胃肠黏膜、毛囊）毒性也大。"},{"k":"联合与耐药","t":"与叶酸拮抗剂、烷化剂联用可协同增效；肿瘤经扩增靶酶、减少摄取或增强修复产生耐药。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0820","subj":"880","chap":"第三章 氨基酸","type":"考点","years":["15"],"q":"D-Y-R　P-K-A-S-F-H-W　用胰凝乳蛋白酶和胰蛋白酶水解后得","points":[{"k":"答案","t":"得 4 个肽段：D-Y、R-P-K、A-S-F、H-W。胰蛋白酶只切 Lys、Arg 的羧基侧肽键，故在 R、K 后断开；胰凝乳蛋白酶切芳香族氨基酸羧基侧，故在 Y、F 后断开。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0821","subj":"880","chap":"综合","type":"考点","years":["15"],"q":"Na⁺, K⁺-ATP泵，1分子ATP水解时同时泵出(　)个Na⁺ 泵入( 3 )个K⁺","points":[{"k":"答案","t":"泵出 3 个 Na⁺（泵入 2 个 K⁺）。Na⁺,K⁺-ATP 酶每水解 1 分子 ATP，按 3Na⁺ 出、2K⁺ 入的化学计量转运，形成跨膜 Na⁺ 高外、K⁺ 高内的梯度。"}],"note":"题干「泵入（3）个 K⁺」与通行口径不符，K⁺ 应为 2 个；卷面答案 3 对应的是 Na⁺ 那个空。","opts":[],"printed_answer":"3"},{"id":"n0822","subj":"880","chap":"第十六章 氨基酸代谢","type":"考点","years":["15"],"q":"苯丙酮尿症是由于缺乏( Phe羟化酶 )酶","points":[{"k":"答案","t":"苯丙氨酸羟化酶（Phe 羟化酶）。该酶缺陷使 Phe 不能羟化为酪氨酸，血 Phe 升高，经转氨基生成苯丙酮酸由尿排出，并影响脑发育。"}],"note":"","opts":[],"printed_answer":"Phe羟化酶"},{"id":"n0823","subj":"880","chap":"第四章 蛋白质","type":"考点","years":["15"],"q":"肽链平面　[图：肽键平面示意，Cα-C-N-Cα，C 上方双键 O，N 下方 H]　Cα-C-N-Cα","points":[{"k":"答案","t":"肽键 C—N 具部分双键性质、不能自由旋转，使 Cα—C—O—N—H—Cα 六个原子共处一个刚性平面（肽键平面）。平面内只有绕两个 Cα 的单键（φ、ψ）可以转动。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0824","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"考点","years":["15"],"q":"tRNA二级结构　三叶草","points":[{"k":"答案","t":"三叶草形（四臂三环）。含氨基酸臂、DHU 环、反密码子环、TΨC 环和可变环，3′ 端为共同的 —CCA—OH，用于连接氨基酸。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0825","subj":"880","chap":"第七章 核酸","type":"考点","years":["15"],"q":"与Tm有关因素","points":[{"k":"答案","t":"主要取决于 G-C 对含量：G≡C 有 3 个氢键且堆积力强，GC 比例越高 Tm 越高（每增 1% 约升 0.4 ℃）。此外分子越长、离子强度越高 Tm 越高，pH 异常或加尿素、甲酰胺则降低。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0826","subj":"880","chap":"第五章 酶","type":"考点","years":["15"],"q":"与Vmax有关因素","points":[{"k":"答案","t":"只与酶的总浓度有关。Vmax = kcat·[E]t，底物浓度只改变反应速度 v，不改变 Vmax；不可逆抑制剂、极端 pH 或高温因减少活性酶量而使 Vmax 下降。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0827","subj":"880","chap":"第十四章 氧化磷酸化","type":"考点","years":["15"],"q":"Ⅱ型呼吸链","points":[{"k":"答案","t":"即以 FAD 为辅基的 FADH₂ 氧化呼吸链。底物（琥珀酸、脂酰 CoA、α-磷酸甘油）经复合体Ⅱ（琥珀酸-泛醌还原酶）→Q→复合体Ⅲ→Cyt c→复合体Ⅳ→O₂，P/O 为 1.5。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0828","subj":"880","chap":"第十四章 氧化磷酸化","type":"考点","years":["15"],"q":"化学渗透学说 H⁺","points":[{"k":"答案","t":"呼吸链把 H⁺ 泵到内膜外侧（膜间隙），形成跨膜质子电化学梯度，即质子动力势。H⁺ 顺梯度经 ATP 合酶 F₀ 通道回流时释放能量，驱动 F₁ 催化 ADP 磷酸化生成 ATP。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0829","subj":"880","chap":"第七章 核酸","type":"考点","years":["15"],"q":"引物分子合成(核糖)　至少含4个游离碱基","points":[{"k":"答案","t":"引物是核糖核苷酸链（RNA）。引物酶以 DNA 为模板合成十余个核苷酸的 RNA 引物，其 3′-OH 供 DNA 聚合酶Ⅲ 添加脱氧核苷酸、起始延伸。"}],"note":"","opts":[],"printed_answer":"核糖"},{"id":"n0830","subj":"880","chap":"第十七章 核苷酸代谢","type":"考点","years":["15"],"q":"嘧啶+嘌呤 ——>都需要　Asp. CO₂. Gln.","points":[{"k":"答案","t":"谷氨酰胺、天冬氨酸、CO₂。嘧啶环与嘌呤环的氮原子分别由 Gln 的酰胺氮、Asp 的氨基氮提供，成环碳则由 CO₂ 提供（另需 PRPP 提供磷酸核糖）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0831","subj":"880","chap":"第十四章 氧化磷酸化","type":"考点","years":["15"],"q":"氧化磷酸化抑制剂","points":[{"k":"呼吸链抑制剂","t":"鱼藤酮、抗霉素 A 阻断电子传递链的相应部位；氰化物、CO、叠氮化物抑制细胞色素氧化酶，电子不能传给氧。"},{"k":"解偶联剂","t":"2,4-二硝基苯酚使氧化与磷酸化脱偶联，电子传递照常进行而 ATP 不能生成，能量以热散失。"},{"k":"ATP合酶抑制剂","t":"寡霉素抑制 ATP 合酶，阻断质子经 F₀ 回流，ATP 生成受阻。"}],"note":"资料无对应原答案，按教材口径。资料该条为「氧化磷酸化」的名词解释，与本题「氧化磷酸化抑制剂」不是同一题。","opts":[],"printed_answer":"","ref":false},{"id":"n0832","subj":"880","chap":"第十七章 核苷酸代谢","type":"考点","years":["15"],"q":"氨甲蝶呤 抗代谢物","points":[{"k":"答案","t":"甲氨蝶呤（MTX）是叶酸拮抗剂类抗代谢物。它抑制二氢叶酸还原酶，使 FH₄ 缺乏，一碳单位转移受阻，dTMP 与嘌呤合成被阻断，从而抑制肿瘤细胞增殖。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0833","subj":"880","chap":"第十章 糖酵解 糖异生","type":"考点","years":["15"],"q":"糖酵解特征","points":[{"k":"部位与条件","t":"在细胞质（胞液）中进行，不需氧，是葡萄糖无氧分解生成丙酮酸的途径。"},{"k":"净生成产物","t":"1 分子葡萄糖净生成 2 ATP、2 NADH 和 2 分子丙酮酸；缺氧时丙酮酸还原为乳酸。"},{"k":"三个关键酶","t":"受己糖激酶、磷酸果糖激酶-1、丙酮酸激酶三个关键酶调节，三步反应均不可逆。"}],"note":"资料无对应原答案，按教材口径。资料该条为「糖酵解」的名词解释，本题问的是特征，要点不全，故未采用。","opts":[],"printed_answer":"","ref":false},{"id":"n0834","subj":"880","chap":"第十五章 脂类代谢","type":"考点","years":["15"],"q":"内质网. 肝　胞内:ACAT. 胞外:LCAT","points":[{"k":"答案","t":"胆固醇酯化分胞内、胞外两条途径：胞内由 ACAT（脂酰 CoA 胆固醇酰基转移酶）用脂酰 CoA 酯化；血浆中由 LCAT（卵磷脂胆固醇酰基转移酶）把卵磷脂 2 位脂酸转给胆固醇。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0835","subj":"880","chap":"第一章 糖类","type":"考点","years":["15"],"q":"纤维素，键","points":[{"k":"答案","t":"β-1,4-糖苷键。纤维素由 β-D-葡萄糖以 β-1,4 糖苷键连成不分支直链，人缺乏 β-葡萄糖苷酶，故不能消化利用。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0836","subj":"880","chap":"第十三章 磷酸戊糖途径、乙醛酸循环","type":"考点","years":["15"],"q":"5-P-核糖生成途径","points":[{"k":"答案","t":"主要走磷酸戊糖途径。6-磷酸葡萄糖经 G-6-P 脱氢酶、内酯酶等生成核酮糖-5-磷酸，再由异构酶、差向异构酶转变为 5-磷酸核糖；也可由糖酵解中间物经转酮、转醛反应生成。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0837","subj":"880","chap":"第十章 糖酵解 糖异生","type":"考点","years":["15"],"q":"糖酵解　1,6-2-P果糖","points":[{"k":"答案","t":"由 PFK-1 催化 6-磷酸果糖磷酸化生成，是糖酵解的限速步骤；随后醛缩酶把 1,6-二磷酸果糖裂解为 3-磷酸甘油醛和磷酸二羟丙酮。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0838","subj":"880","chap":"第十六章 氨基酸代谢","type":"考点","years":["15"],"q":"尿素中2N来源　氨分子. Asp　Asp. 氨甲酰磷酸","points":[{"k":"答案","t":"一个来自氨（氨甲酰磷酸），一个来自天冬氨酸。尿素循环中氨甲酰磷酸与天冬氨酸缩合，两个氮最终都进入尿素分子。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0839","subj":"880","chap":"第七章 核酸","type":"考点","years":["15"],"q":"DNA变性后性质","points":[{"k":"答案","t":"①氢键断裂、双链解为单链，共价键不断；②A₂₆₀ 升高（增色效应）；③黏度下降、沉降系数增大；④生物活性丧失，但缓慢复性可部分恢复。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0840","subj":"880","chap":"第十一章 柠檬酸循环","type":"考点","years":["15"],"q":"乙酰CoA.　脂酸→途径.　柠檬酸—丙酮酸循环","points":[{"k":"答案","t":"经柠檬酸-丙酮酸循环转运。线粒体内乙酰 CoA 与草酰乙酸缩合成柠檬酸运出，胞液 ATP-柠檬酸裂解酶释放出乙酰 CoA 供脂肪酸合成，草酰乙酸经苹果酸酶生成丙酮酸返回线粒体。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0841","subj":"880","chap":"第十五章 脂类代谢","type":"考点","years":["15"],"q":"甘油磷脂合成途径　A. CDP-二脂酰甘油　C..　B. CMP- ..　D..","points":[{"k":"答案","t":"CDP-二脂酰甘油（DAG）途径。CDP-胆碱或 CDP-乙醇胺与 DAG 缩合生成磷脂酰胆碱、磷脂酰乙醇胺，是甘油磷脂合成的主要途径。"}],"note":"原卷只残留 A、B 两选项片段，按「CDP-二脂酰甘油途径」作答。","opts":[],"printed_answer":""},{"id":"n0842","subj":"631","chap":"综合","type":"简答","years":["15"],"q":"简述证实 DNA 是遗传信息携带者的两个经典实验设计。","points":[{"k":"格里菲斯转化","t":"肺炎链球菌体内转化实验：加热杀死的 S 型菌与活的 R 型菌混合注入小鼠，小鼠死亡并分离出活 S 型菌，说明存在“转化因子”。"},{"k":"艾弗里酶解定性","t":"体外纯化转化因子，分别用 DNase、RNase、蛋白酶处理：仅 DNase 使转化活性消失，证明转化因子是 DNA 而非蛋白质或 RNA。"},{"k":"同位素双标记","t":"赫尔希-蔡斯噬菌体实验：³⁵S 标蛋白质、³²P 标 DNA，分别感染大肠杆菌，短时搅拌离心后测放射性去向。"},{"k":"子代追踪","t":"结果 ³²P 主要进入菌体并传给子代噬菌体，³⁵S 留在菌壳外，说明进入宿主并指导子代合成的是 DNA。"},{"k":"结论与补充","t":"两个实验共同确证 DNA 是遗传物质；后来烟草花叶病毒重建实验证明某些病毒以 RNA 为遗传物质。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0843","subj":"631","chap":"一、染色体结构","type":"简答","years":["15"],"q":"双螺旋结构模型的特点","points":[{"k":"反向平行右手螺旋","t":"两条多核苷酸链反向平行，绕同一中心轴右手盘绕，形成 B 型双螺旋。"},{"k":"骨架在外碱基在内","t":"磷酸-脱氧核糖骨架位于外侧，碱基位于内侧，碱基平面垂直于螺旋轴。"},{"k":"碱基互补配对","t":"A 与 T 形成 2 个氢键，G 与 C 形成 3 个氢键；嘌呤必与嘧啶配对，使螺旋直径恒为 2 nm。"},{"k":"螺旋参数","t":"螺距 3.4 nm，每圈 10 个碱基对，相邻碱基对间距 0.34 nm，相邻碱基对夹角 36°。"},{"k":"大小沟","t":"表面形成宽 2.2 nm 的大沟与宽 1.2 nm 的小沟，是蛋白质与 DNA 特异结合、识别碱基序列的部位。"},{"k":"稳定力","t":"横向靠碱基间氢键，纵向靠碱基堆积力（主要），外侧靠磷酸基与阳离子的离子键，共三力维持。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0844","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["15"],"q":"DNA复制时为什么前导链是连续复制，而后随链是以不连续的方式复制？并请以大肠杆菌为例简述后随链复制的各个步骤。","points":[{"k":"聚合酶单向性","t":"DNA 聚合酶只能把 dNTP 加到已有 3′-OH 上，延伸方向只能是 5′→3′，且模板必须反向平行读取。"},{"k":"两链方向相反","t":"复制叉解开后两条模板反向平行，一条模板的 3′→5′ 方向与解旋方向一致，可顺着复制叉连续延伸，即前导链。"},{"k":"后随链分段","t":"另一条模板方向与复制叉前进方向相反，只能等模板暴露一段后“倒退”合成一小段，故不连续，形成冈崎片段。"},{"k":"解旋与引物","t":"解旋酶 DnaB 解链，SSB 稳定单链，拓扑异构酶消除正超螺旋；引物酶 DnaG 合成约 10 nt RNA 引物。"},{"k":"Pol III延伸片段","t":"DNA 聚合酶Ⅲ以 β 夹持器提高持续合成能力，沿模板 5′→3′ 延伸冈崎片段（约 1000~2000 nt）至前一引物处。"},{"k":"Pol I换引物连接","t":"DNA 聚合酶Ⅰ以 5′→3′ 外切酶活性切除 RNA 引物并填补缺口，DNA 连接酶消耗 ATP 封闭缺口，形成完整子链。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0845","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["15"],"q":"DNA 复制和蛋白质合成是重要的生物学过程，请试述这两个过程的忠实性是如何保持的。","points":[{"k":"碱基互补选择","t":"复制时按 A-T、G-C 的几何形状与氢键供受体匹配选择 dNTP，是忠实性的第一道关卡。"},{"k":"聚合酶校对","t":"DNA 聚合酶具 3′→5′ 外切酶活性，错配时延伸受阻，切下错误核苷酸重来，使错误率降至约 10⁻⁷。"},{"k":"错配与甲基化修复","t":"复制后 MutS-L-H 系统识别错配，按模板链甲基化标记切除新链错误碱基，进一步降误差至 10⁻⁹~10⁻¹⁰。"},{"k":"氨酰tRNA双重识别","t":"氨酰-tRNA 合成酶既识别氨基酸又识别 tRNA，并有编辑位点水解误载产物，保证 amino acid 与密码子对应。"},{"k":"核糖体动力学校对","t":"EF-Tu 递送氨酰-tRNA 后，正确配对才触发 GTP 水解与构象稳定，错误者被拒绝；A 位监测与肽基转移酶专一性再筛一次。"},{"k":"终止准确","t":"释放因子 RF1/RF2 特异识别终止密码子，保证肽链在正确位置终止，不产生通读。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0846","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"论述","years":["15"],"q":"操纵子学说是原核生物基因结构及其表达调控的学说，请以乳糖操纵子为例，论述其如何调控基因表达。","points":[{"k":"操纵子组成","t":"调节基因 lacI、启动子 P、操纵基因 O，以及结构基因 lacZ（β-半乳糖苷酶）、lacY（乳糖通透酶）、lacA（转乙酰酶）。"},{"k":"无诱导物时关闭","t":"LacI 表达阻遏蛋白四聚体，结合于 O 位，空间上阻碍 RNA 聚合酶从 P 前移，结构基因不转录。"},{"k":"诱导物解除阻遏","t":"乳糖经少量 β-半乳糖苷酶转为异乳糖，结合阻遏蛋白使其构象改变、亲和力下降而从 O 脱落，转录启动。"},{"k":"CAP正调控","t":"葡萄糖缺乏时 cAMP 升高，cAMP-CAP 复合物结合启动子上游，招募 RNA 聚合酶，转录效率提高数十倍。"},{"k":"葡萄糖效应","t":"葡萄糖充足时 cAMP 低、CAP 不能结合，即使有乳糖也仅低水平转录，表现为分解代谢物阻遏。"},{"k":"双信号逻辑","t":"只有“有乳糖且无葡萄糖”时高效表达，相当于与门；体现原核生物按底物经济性调控基因表达的策略。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0847","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"简答","years":["15"],"q":"简述荧光定量 PCR 的原理及应用。","points":[{"k":"实时监测荧光","t":"在 PCR 体系中加入荧光基团，每轮循环后检测荧光强度，实时反映扩增产物量，不需电泳。"},{"k":"Ct值与定量","t":"荧光达阈值所需循环数为 Ct；起始模板越多，Ct 越小，Ct 与起始拷贝数的对数成线性反比。"},{"k":"绝对与相对定量","t":"用已知浓度标准品作标准曲线求绝对拷贝数；用内参基因作相对定量，按 2^-ΔΔCt 计算表达差异。"},{"k":"两类荧光化学","t":"SYBR Green 非特异结合双链 DNA，便宜但需熔解曲线核对；TaqMan 探针带报告与淬灭基团，Taq 酶外切水解释放荧光，特异更强。"},{"k":"主要应用","t":"病原体载量（HBV、HCV、结核、新冠）、基因表达分析、拷贝数与 SNP 分型、突变与融合基因检测、转基因成分鉴定。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0848","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"简答","years":["15"],"q":"简述原核生物转录终止的两种主要机制。","points":[{"k":"不依赖ρ的终止","t":"模板含富含 GC 的反向重复序列，转录出的 RNA 形成发夹（茎环）结构，使 RNA 聚合酶暂停。"},{"k":"寡聚U弱配对","t":"发夹之后紧跟一段寡聚 U，rU-dA 杂合体最不稳定，RNA 与模板解离，转录终止并释放聚合酶。"},{"k":"依赖ρ的终止","t":"ρ 因子为六聚体、ATP 依赖的解旋酶，识别新生 RNA 上富含 C 少 G 的 rut 位点并结合。"},{"k":"ρ追赶解离","t":"ρ 沿 RNA 5′→3′ 移动追赶聚合酶，ATP 水解提供能量解开 RNA-DNA 杂合体，使转录复合体解体。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0849","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"简答","years":["15"],"q":"何为 DNA 重组技术？其主要步骤为何？","points":[{"k":"概念","t":"在体外把目的基因与载体 DNA 拼接成重组分子，导入宿主细胞扩增并表达的技术，即基因工程的核心。"},{"k":"分取目的基因","t":"获取目的基因：PCR 扩增、限制酶切基因组、逆转录合成 cDNA、化学合成或基因文库筛选。"},{"k":"酶切产生末端","t":"用限制性内切酶分别切割目的基因与载体，产生匹配的粘性末端或平末端，必要时去磷酸化防自身环化。"},{"k":"连接重组分子","t":"T4 DNA 连接酶催化形成磷酸二酯键，把目的片段插入载体，构建重组质粒。"},{"k":"导入宿主细胞","t":"转化（CaCl₂ 法或电穿孔）导入大肠杆菌，或用显微注射、病毒载体导入真核细胞。"},{"k":"筛选鉴定表达","t":"抗性筛选、蓝白斑筛选、菌落 PCR、酶切图谱、测序鉴定重组子；再诱导表达并纯化蛋白。"}],"note":"可用“分、切、接、转、选”五字概括。","opts":[],"printed_answer":""},{"id":"n0850","subj":"631","chap":"五、RNA 的调控机制","type":"简答","years":["15"],"q":"何为 RNA 干扰？其作用机制怎样？","points":[{"k":"定义","t":"由双链 RNA 引发的、序列特异的转录后基因沉默现象（PTGS），可在细胞间与世代间传递。"},{"k":"Dicer切割","t":"dsRNA 被 RNaseⅢ 家族核酸酶 Dicer 切割成 21~23 nt 的小干扰 RNA（siRNA），具 3′ 两碱基突出端与 5′磷酸。"},{"k":"RISC组装","t":"siRNA 与 Argonaute 等蛋白组装成 RNA 诱导沉默复合体（RISC），解链后保留引导链、丢弃乘客链。"},{"k":"降解靶mRNA","t":"引导链与靶 mRNA 完全互补时，AGO2（Slicer）在互补区中部切割 mRNA，随后被外切酶降解。"},{"k":"翻译抑制与放大","t":"不完全互补时改为抑制翻译、促进去腺苷酸化；RdRP 以 siRNA 为引物合成次级 siRNA，实现信号放大。"},{"k":"意义与应用","t":"天然功能为抗病毒、抑制转座子、调控发育；应用包括基因功能研究、作物改良与 siRNA 药物（如 patisiran）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0851","subj":"880","chap":"第一章 糖类","type":"选择","years":[],"q":"下列关于乳糖说法错误的是","points":[{"k":"答案","t":"B。乳糖是半乳糖以 β-1,4 糖苷键连于葡萄糖，不是 α-1,4 键；A、C、D 均正确（甜度约为蔗糖的 1/6，不同晶型物理性质不同）。"}],"note":"","opts":["A. 分解为半乳糖和葡萄糖","B. 以 α-1，4糖苷键连接","C. 乳糖的形态不同导致不同形态具有不同的物理性质","D. 甜度相当于蔗糖的六分之一"],"printed_answer":""},{"id":"n0852","subj":"880","chap":"第七章 核酸","type":"选择","years":[],"q":"下列不含有戊糖单位的物质是","points":[{"k":"答案","t":"A 肝素。肝素由葡萄糖胺与糖醛酸（艾杜糖醛酸、葡萄糖醛酸）构成，属糖胺聚糖，不含戊糖；DNA、RNA 含脱氧核糖/核糖，FMN 含核糖醇。"}],"note":"FMN 的糖部分为核糖醇，属戊糖醇而非戊糖，按题意仍取 A。","opts":["A. 肝素","B. DNA","C. RNA","D. FMN"],"printed_answer":""},{"id":"n0853","subj":"880","chap":"第十五章 脂类代谢","type":"选择","years":[],"q":"不参与脂肪酸氧化的物质是","points":[{"k":"答案","t":"C NADP⁺。脂酸 β 氧化需 FAD（脂酰 CoA 脱氢酶）、NAD⁺（β-羟脂酰 CoA 脱氢酶）和肉碱（转运），NADPH 只供合成代谢，不参与氧化。"}],"note":"严格按 β 氧化本身，FMN 亦不直接参与；本题按题库口径取唯一与呼吸链递氢相关的 NADP⁺。","opts":["A. FAD","B. FMN","C. NADP","D. 肉碱"],"printed_answer":""},{"id":"n0854","subj":"880","chap":"综合","type":"选择","years":[],"q":"不慎服用水银后，紧急服用牛奶后，在使用催吐剂催吐，请问在此过程中形成了","points":[{"k":"答案","t":"A 生成不溶性蛋白盐。Hg²⁺ 等重金属与牛奶蛋白的 —SH、—COO⁻ 结合，使蛋白变性生成不溶性蛋白盐沉淀，减少毒物吸收，再催吐排出。"}],"note":"","opts":["A. 生成不溶性蛋白盐","B. 盐析","C. 凝固","D. 透析"],"printed_answer":""},{"id":"n0855","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"选择","years":[],"q":"tRNA 可以携带氨基酸的关键结构","points":[{"k":"答案","t":"D —CCA—3′OH 末端。氨基酸以酯键连在该末端腺苷酸核糖的 3′-OH 上，即氨基酸臂；反密码子环只负责与 mRNA 密码子配对。"}],"note":"","opts":["A. TΨC 环","B. 反密码子环","C. 额外环","D. —CCA—3'OH 末端"],"printed_answer":""},{"id":"n0856","subj":"880","chap":"第一章 糖类","type":"简答","years":["16"],"q":"淀粉液化和糖化的酶及水解特点","points":[{"k":"液化用α淀粉酶","t":"α-淀粉酶为内切酶，随机水解 α-1,4 糖苷键，迅速降低黏度，产物为糊精与少量麦芽糖，需 Ca²⁺，最适 pH 5.5~7、70~90℃。"},{"k":"糖化用糖化酶","t":"葡萄糖淀粉酶（糖化酶）为外切酶，从非还原端逐个切下葡萄糖，也能缓慢切 α-1,6，最适 pH 4.0~4.5、60℃。"},{"k":"辅助脱支","t":"普鲁兰酶专切 α-1,6 分支点，β-淀粉酶从非还原端切麦芽糖，二者与糖化酶配合可提高葡萄糖得率。"},{"k":"内切外切之别","t":"液化是内切降黏、产物分子量迅速下降；糖化是外切产糖、产物以葡萄糖为主，二者顺序不可颠倒。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0857","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["16"],"q":"脂肪酸 b 氧化酶和产物","points":[{"k":"脂酰CoA脱氢","t":"以 FAD 为辅基，催化 α、β 碳脱氢生成反式Δ²-烯脂酰CoA，产生 FADH₂。"},{"k":"烯脂酰水化","t":"烯脂酰CoA水化酶加水生成 L-β-羟脂酰CoA，不耗能、立体专一。"},{"k":"羟脂酰再脱氢","t":"β-羟脂酰CoA脱氢酶以 NAD⁺ 为辅酶再脱氢，生成 β-酮脂酰CoA 与 NADH+H⁺。"},{"k":"硫解酶断链","t":"β-酮脂酰CoA硫解酶加 CoA 断裂，生成 1 分子乙酰CoA 与缩短 2 碳的脂酰CoA。"},{"k":"每轮产物","t":"每轮产出 1 FADH₂、1 NADH+H⁺、1 乙酰CoA，碳链缩短 2 个碳，循环往复直至全部降解。"},{"k":"活化与转运","t":"起始需脂酰CoA合成酶活化（耗 2 个高能键）与肉碱穿梭转运；不饱和脂肪酸另需异构酶与还原酶，奇数碳末轮产丙酰CoA。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0858","subj":"880","chap":"第十五章 脂类代谢","type":"简答","years":["16"],"q":"脂肪酸吃奇数碳好还是偶数碳好","points":[{"k":"天然以偶数为主","t":"体内脂肪酸多为 16C、18C 偶数碳，β氧化全部产乙酰CoA，可彻底氧化入 TCA，产能高、无残余。"},{"k":"奇数碳产丙酰CoA","t":"奇数碳脂肪酸末轮生成丙酰CoA，需生物素依赖的丙酰CoA羧化酶转为 D-甲基丙二酰CoA，再由变位酶（B12 为辅酶）转为琥珀酰CoA 入 TCA。"},{"k":"B12依赖是短板","t":"维生素 B12 缺乏时甲基丙二酸堆积（MMA 升高），可致神经髓鞘损伤；奇数碳摄入增多会加重这一负担。"},{"k":"奇数碳可净生糖","t":"丙酰CoA→琥珀酰CoA→草酰乙酸可异生为糖，是奇数碳脂肪酸独有的“生糖”能力，偶数碳则不能。"},{"k":"结论","t":"从供能效率与代谢负担看偶数碳更“好”（彻底氧化、不需 B12）；奇数碳并非有害，只是多两步反应并依赖 B12，反刍动物乳脂中天然存在。"}],"note":"“好与不好”无绝对标准，按代谢效率与营养学主流观点作答。","opts":[],"printed_answer":""},{"id":"n0859","subj":"880","chap":"第十章 糖酵解 糖异生","type":"简答","years":["16"],"q":"菊芋的主要糖类及结构特点，用菊芋发酵生成乳酸的相应反应","points":[{"k":"主糖为菊粉","t":"菊芋块茎主要糖类为菊粉（inulin），属果聚糖，占干重 70%~80%，是植物储藏的果糖聚合物。"},{"k":"β-2,1果糖苷键","t":"由 D-果糖以 β-2,1 糖苷键连成直链，末端接一个葡萄糖（由蔗糖起始），聚合度 2~60，平均 10~20，可带少量 β-2,6 分支。"},{"k":"人体不能消化","t":"人缺菊粉酶，菊粉不被消化吸收，属可溶性膳食纤维与益生元，低热量、促双歧杆菌生长、不影响血糖。"},{"k":"酶解为单糖","t":"菊粉酶（内切型切链、外切型切末端）水解 β-2,1 键，生成 D-果糖与少量葡萄糖。"},{"k":"同型乳酸发酵","t":"果糖、葡萄糖经糖酵解生成 2 分子丙酮酸，再由乳酸脱氢酶还原为 2 分子乳酸：C₆H₁₂O₆ → 2 C₃H₆O₃，理论转化率 100%。"},{"k":"总反应式","t":"(C₆H₁₀O₅)n + nH₂O → nC₆H₁₂O₆ → 2nC₃H₆O₃；工业上常采用菊粉酶与乳酸菌同步糖化发酵（SSF）以减少产物抑制。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0860","subj":"880","chap":"第五章 酶","type":"简答","years":["16"],"q":"深海生物的葡萄糖-6-磷酸\n(1)首先，利用大肠杆菌生产该酶的技术和步骤\n(2)其次，提取大肠杆菌的酶，设计实验并表明测酶的表征量\n(3) 以 NADP 为底物、2mol 酶，双倒数曲线P图\n求:\n(a) 计算 Vmax, Km\n(b) Y=ax+b 的方程\n(c) NADP 的中文名\n(d) NADP 的维生素前体\n(e) 加入竞争抑制剂的曲线","points":[{"k":"基因获取与优化","t":"对深海样品宏基因组测序，筛出葡萄糖-6-磷酸脱氢酶（G6PD）开放读框；按大肠杆菌偏好做密码子优化并去掉稀有密码子。"},{"k":"构建表达载体","t":"两端加 NdeI/XhoI 位点，插入 pET-28a 获得 N 端 6×His 标签，测序确认读框正确。"},{"k":"转化与诱导表达","t":"转化 E. coli BL21(DE3)，IPTG 诱导；深海酶多为低温活性，采用 15~25℃、低浓度 IPTG 过夜表达以减少包涵体。"},{"k":"提纯与表征","t":"高压或超声破碎→离心取上清→Ni-NTA 亲和纯化→透析除咪唑；SDS-PAGE 看纯度与分子量，Bradford 法测蛋白，测比活力。"},{"k":"测酶表征量","t":"表征 Km、Vmax、kcat/Km、最适 pH 与温度、热稳定性、盐与金属离子影响、亚基数与寡聚状态。"},{"k":"双倒数求解","t":"(a) 纵截距=1/Vmax 求 Vmax，横截距=−1/Km 求 Km；(b) Y=(Km/Vmax)X + 1/Vmax，即 a=Km/Vmax、b=1/Vmax。NADP 为烟酰胺腺嘌呤二核苷酸磷酸（辅酶Ⅱ），维生素前体是维生素 PP（烟酸）。"},{"k":"竞争抑制图形","t":"(e) 加竞争性抑制剂后，双倒数图纵截距不变（Vmax 不变）、横截距右移（Km 增大）、斜率增大，各线交于纵轴。"}],"note":"原卷未给具体速度-底物浓度数据与“2mol 酶”的准确含义，“求 Vmax、Km”只能给公式与作图法，无法给出数值；竞争抑制曲线特征按标准图形作答。","opts":[],"printed_answer":""},{"id":"n0861","subj":"880","chap":"第五章 酶","type":"填空","years":["11"],"q":"米氏方程的表达式为______________。","points":[{"k":"答案","t":"v = Vmax[S]/(Km + [S])。当 [S]≫Km 时 v≈Vmax，当 [S]≪Km 时 v≈(Vmax/Km)[S]，呈一级反应。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0862","subj":"880","chap":"第十章 糖酵解 糖异生","type":"填空","years":["11"],"q":"糖酵解中的三个关键酶是________、________、________。","points":[{"k":"答案","t":"己糖激酶（肝为葡萄糖激酶）、磷酸果糖激酶-1（PFK-1）、丙酮酸激酶。三者催化不可逆反应，是糖酵解的限速酶。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0863","subj":"880","chap":"第十六章 氨基酸代谢","type":"填空","years":["11"],"q":"联合脱氢是由________和________两步组成。","points":[{"k":"答案","t":"转氨基作用与 L-谷氨酸氧化脱氨基。氨基酸先经转氨酶把氨基交给 α-酮戊二酸生成谷氨酸，再由 L-谷氨酸脱氢酶氧化脱氨，是体内脱氨的主要方式。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0864","subj":"880","chap":"第二十章 遗传密码与蛋白质的合成","type":"填空","years":["11"],"q":"遗传密码具有________、________、________等特点。","points":[{"k":"答案","t":"连续性、简并性、通用性。此外还有方向性（5′→3′ 阅读）、摆动性（第三位碱基可摆动配对）和不重叠、无标点。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0865","subj":"880","chap":"第十章 糖酵解 糖异生","type":"填空","years":["11"],"q":"两个丙酮酸分子异生为葡萄糖，共消耗________分子 ATP 当量。","points":[{"k":"答案","t":"6 个。每分子丙酮酸异生耗 3 个高能磷酸键：丙酮酸羧化酶耗 1 ATP、PEP 羧激酶耗 1 GTP、磷酸甘油酸激酶耗 1 ATP，2 分子共 4 ATP + 2 GTP，另需 2 NADH。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0866","subj":"880","chap":"第十五章 脂类代谢","type":"填空","years":["11"],"q":"柠檬酸________乙酰 CoA 羧化酶，从而促进________合成。","points":[{"k":"答案","t":"激活；脂肪酸。柠檬酸是乙酰 CoA 羧化酶的变构激活剂，促使其催化生成丙二酰 CoA，加速脂肪酸合成。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0867","subj":"880","chap":"第十六章 氨基酸代谢","type":"填空","years":["11"],"q":"肝炎患者一般检测________水平。","points":[{"k":"答案","t":"丙氨酸氨基转移酶（ALT/GPT）。肝细胞损伤时 ALT 释入血，是肝炎最敏感的酶学指标（胆红素、白蛋白亦常查）。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0868","subj":"880","chap":"第十五章 脂类代谢","type":"填空","years":["11"],"q":"酮体是指________、________和________。","points":[{"k":"答案","t":"乙酰乙酸、β-羟丁酸和丙酮。三者由肝以乙酰 CoA 为原料生成，经血运至肝外组织氧化利用。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0869","subj":"880","chap":"第七章 核酸","type":"填空","years":["11"],"q":"hp RNA 的中文名称是________。","points":[{"k":"答案","t":"核内不均一 RNA（hnRNA）。即细胞核内未经剪接加工的 mRNA 前体，分子大小不一。"}],"note":"题干「hp RNA」应为 hnRNA 的笔误。","opts":[],"printed_answer":""},{"id":"n0870","subj":"880","chap":"第九章 生物膜","type":"选择","years":["11"],"q":"下列关于跨膜主动运输说法错误的是:","points":[{"k":"答案","t":"C。主动运输也可双向进行，如 Na⁺,K⁺-ATP 酶同时泵出 Na⁺、泵入 K⁺，故「只能单向运输」错误；A、B 为主动运输的固有特征。"}],"note":"D「需要输送物具有跨膜梯度」表述亦不严谨，主动运输可逆梯度进行，但本题唯一明显错误项为 C。","opts":["A. 都需要载体参与","B. 需要消耗能量","C. 对同一物质只能单向运输","D. 需要输送物具有跨膜梯度"],"printed_answer":""},{"id":"n0871","subj":"880","chap":"第三章 氨基酸","type":"选择","years":["11"],"q":"中性条件下带有净正电荷的氨基酸是","points":[{"k":"答案","t":"C 精氨酸。其胍基 pKa≈12.5，等电点约 10.8，中性 pH 下带净正电荷；酪氨酸、甲硫氨酸近中性，天冬氨酸带负电。"}],"note":"","opts":["A. 酪氨酸","B. 天冬氨酸","C. 精氨酸","D. 甲硫氨酸"],"printed_answer":""},{"id":"n0872","subj":"880","chap":"综合","type":"选择","years":["11"],"q":"某没对底物的化学键及该键一端的基团有严格要求，则其转移性属于:","points":[{"k":"答案","t":"A 相对专一性。只要求特定化学键且对键一端的基团有选择，属基团（族）专一性，归入相对专一性；绝对专一性则对整个底物结构都严格。"}],"note":"","opts":["A. 相对专一性","B. 立体专一性","C. 绝对专一性","D. 键专一性"],"printed_answer":""},{"id":"n0875","subj":"880","chap":"第四章 蛋白质","type":"实验","years":["11"],"q":"阐述凝胶过滤，离子交换，亲和层析的原理","points":[{"k":"凝胶过滤按大小","t":"多孔凝胶珠（Sephadex、Sepharose）中，大分子不能入孔、走颗粒间隙先被洗出；小分子进入孔内路径长、后出，用于按分子大小分离与脱盐。"},{"k":"离子交换按电荷","t":"DEAE-纤维素带正电（阴离子交换）、CM-纤维素带负电（阳离子交换）；蛋白在合适 pH 下带相应电荷而与反离子竞争结合，电荷多者结合牢。"},{"k":"盐梯度洗脱","t":"提高 NaCl 浓度或改变 pH 使蛋白逐步解吸附，电荷少者先出、多者后出，分辨率高、载量大。"},{"k":"亲和层析特异","t":"配体（底物类似物、抗体、Ni²⁺、凝集素）共价固定，只与目标蛋白特异可逆结合，杂蛋白直接流出，用游离配体或咪唑、低 pH 洗脱，纯度最高。"}],"note":"与 n0801 同题，实验题按“原理—操作要点—适用场景”作答。","opts":[],"printed_answer":""},{"id":"n0877","subj":"631","chap":"七、分子生物学技术","type":"名词解释","years":["10"],"q":"核酸杂交","points":[{"k":"定义","t":"核酸杂交，变性后的单链核酸在适宜条件下与互补序列按碱基配对原则复性，形成双链杂交分子的过程，可检测特定 DNA 或 RNA 序列。"},{"k":"类型","t":"分 Southern、Northern、斑点杂交与原位杂交；关键是探针标记、预杂交封闭及温度、盐浓度等杂交严格性控制。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0878","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":["10"],"q":"报告基因","points":[{"k":"定义","t":"报告基因，指编码产物易于检测、与待研究的调控序列融合后导入细胞，用以反映该序列转录活性的基因，如 lacZ、GFP、荧光素酶基因。"},{"k":"应用","t":"分析启动子与增强子活性、基因表达水平及信号通路；要求背景低、检测灵敏、对宿主细胞无明显毒性。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0879","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"名词解释","years":["10"],"q":"同义突变","points":[{"k":"定义","t":"同义突变，指碱基改变后密码子所编码的氨基酸不变（多发生在第 3 位碱基），蛋白质一级结构不发生改变的突变。"},{"k":"影响","t":"一般不改变表型，但可影响剪接、mRNA 稳定性与翻译速率，故并非完全中性。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0880","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"名词解释","years":["10"],"q":"切除答复","points":[{"k":"定义","t":"切除修复，DNA 损伤后由核酸酶切除含损伤的片段，再以互补链为模板由 DNA 聚合酶填补缺口、连接酶封口，使序列恢复的修复方式。"},{"k":"类型","t":"碱基切除修复（BER）由糖苷酶和 AP 核酸酶切除单个碱基；核苷酸切除修复（NER）切除约 25~30 nt 寡核苷酸，缺陷可致着色性干皮病。"}],"note":"题干“切除答复”应为“切除修复”（OCR 误识），按切除修复作答。","opts":[],"printed_answer":""},{"id":"n0881","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":["10"],"q":"Enhancer","points":[{"k":"定义","t":"增强子，真核基因组中能显著提高靶基因转录效率的顺式作用元件，可位于启动子上游、下游或内含子内，作用方向无关。"},{"k":"特点","t":"由多个模块组成，结合特异反式因子后经 DNA 环化靠近启动子起作用；常具组织特异性，如 SV40 增强子、免疫球蛋白基因增强子。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0882","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"名词解释","years":["10"],"q":"同工 RNA","points":[{"k":"定义","t":"同工 tRNA，指携带同一种氨基酸但反密码子不同、即识别该氨基酸不同密码子的一组 tRNA，由不同的 tRNA 基因编码。"},{"k":"意义","t":"与密码子简并性相适应，使同一氨基酸可由多个密码子带入；各同工 tRNA 含量不同，形成密码子使用偏爱性。"}],"note":"题干“同工 RNA”应为“同工 tRNA”（OCR 缺字），按同工 tRNA 作答。","opts":[],"printed_answer":""},{"id":"n0883","subj":"631","chap":"综合","type":"考点","years":["10"],"q":"证明 DNA 是遗传物质的两个关键性实验","points":[{"k":"答案","t":"肺炎链球菌转化实验与噬菌体感染实验。前者（Griffith 体内转化、Avery 等体外转化）证明转化因子是 DNA；后者用 ³²P/³⁵S 标记证明只有 DNA 进入细菌。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0884","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["10"],"q":"SD 序列的作用是与 16SrRNA 结合","points":[{"k":"答案","t":"正确：SD 序列（AGGAGG）与 16S rRNA 3′ 端的 anti-SD 序列互补配对，把 mRNA 定位到 30S 亚基上，确定起始密码子 AUG 的位置。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0885","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["10"],"q":"真核生物 DNA 中对密码子甲基化修饰，绝大多数基因甲基化发生在(CG)C","points":[{"k":"答案","t":"C（CpG）。真核基因甲基化绝大多数发生在 CpG 二核苷酸中胞嘧啶的第 5 位碳，生成 5-甲基胞嘧啶，多集中于 CpG 岛。"}],"note":"","opts":[],"printed_answer":"C"},{"id":"n0886","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["10"],"q":"以下关于遗传密码的叙述错误的是 D","points":[{"k":"答案","t":"D。遗传密码连续、不重叠无标点、具简并性与通用性，D 项说法与其中一条相悖，故为错误项。"}],"note":"原卷只留答案字母，选项内容缺失，按字母作答。","opts":[],"printed_answer":"D"},{"id":"n0887","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"考点","years":["10"],"q":"大肠杆菌 DNA 聚合酶 II 的(3'-5'外切酶活性)使 DNA 复制","points":[{"k":"答案","t":"3′→5′ 外切酶活性。该活性从新生链 3′ 端切除错配核苷酸，起校对作用，使 DNA 复制保持高保真度。"}],"note":"","opts":[],"printed_answer":"3'-5'外切酶活性"},{"id":"n0888","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"选择","years":["10"],"q":"以下关于真核生物基因表达调控特点的论述错误的是（）C","points":[{"k":"答案","t":"C。真核 mRNA 寿命明显长于原核 mRNA（原核常仅数分钟），C 项把长短说反；A、B、D 均符合真核调控特点。"}],"note":"","opts":["A. 真核生物的 RNA 聚合酶一般不直接同启动子结合","B. 相比于原核生物以负调控为主，真核生物主要是正调控。","C. 真核生物 mRNA 相比原核生物寿命短，所以调控更加精密。","D. 各基因一般是作为独立的转录单位单独调控。"],"printed_answer":"C"},{"id":"n0889","subj":"631","chap":"二、DNA 复制、突变、修复、重组","type":"考点","years":["10"],"q":"关于双向复制，错误的是()","points":[{"k":"答案","t":"双向复制指从复制起点向两侧各形成一个复制叉、两叉相向推进。凡称「只有一个复制叉」「两条子链同向连续合成」者即错误。"}],"note":"原卷选项缺失，只能指出错误说法的判别标准。","opts":[],"printed_answer":""},{"id":"n0890","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"选择","years":["10"],"q":"以下不属于终止密码子的是（）D","points":[{"k":"答案","t":"D GUA。终止密码子为 UAA、UAG、UGA，GUA 是缬氨酸的密码子，故不属于终止密码子。"}],"note":"","opts":["A. UAA","B. UAG","C. UGA","D. GUA"],"printed_answer":"D"},{"id":"n0891","subj":"631","chap":"四、基因表达调控（原核、真核）","type":"选择","years":["10"],"q":"当培养基中同时存在葡萄糖和乳糖时，乳糖操纵子调控的状态是()B","points":[{"k":"答案","t":"B。乳糖经 β-半乳糖苷酶转为别乳糖，结合阻遏蛋白使其构象改变、脱离操纵基因，故不再结合启动子附近；但葡萄糖使 cAMP 降低、CAP 不能结合，转录水平仍很低。"}],"note":"","opts":["A. 阻遏蛋白质同启动子附近结合","B. 阻遏蛋白质不再结合在启动子附近","C. cAMP 同代谢物激活蛋白质形成复合体结合在启动子区域","D. B+C"],"printed_answer":"B"},{"id":"n0892","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"选择","years":["10"],"q":"原核生物启动子的-10 区相当于真核生物启动子的()C","points":[{"k":"答案","t":"C TATA 盒。原核 −10 区（TATAAT，Pribnow 盒）富含 AT、易解链，功能与真核 TATA 盒相当，都是转录起始复合物的识别位点。"}],"note":"","opts":["A. CG 盒","B. CAAT 盒","C. TATA 盒","D. 八聚体盒"],"printed_answer":"C"},{"id":"n0893","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"选择","years":["10"],"q":"真核生物和原核生物翻译过程相同处是()C","points":[{"k":"答案","t":"C。两类翻译共用 UAA、UAG、UGA 三个终止密码子；起始 tRNA（原核 fMet-tRNA、真核 Met-tRNAi）与翻译因子均不同，原核靠 SD 序列而真核靠 5′ 帽。"}],"note":"","opts":["A. 起始 tRNA 相同","B. 翻译因子相同","C. 终止密码子相同","D. 都在 Rbs 位上"],"printed_answer":"C"},{"id":"n0894","subj":"631","chap":"一、染色体结构","type":"选择","years":["10"],"q":"核小体的八聚体组蛋白核心不包括()D","points":[{"k":"答案","t":"D H1。核小体核心八聚体由 H2A、H2B、H3、H4 各 2 分子组成，H1 结合于核心之外、锁住进出核心的 DNA。"}],"note":"","opts":["A. H2A","B. H2B","C. H3","D. H1"],"printed_answer":"D"},{"id":"n0895","subj":"631","chap":"七、分子生物学技术","type":"选择","years":["10"],"q":"酵母双杂交系统被用来研究()A","points":[{"k":"答案","t":"A 蛋白质与蛋白质之间的相互作用。诱饵蛋白连 DNA 结合域、猎物蛋白连激活域，只有两蛋白互作才能重建转录因子并激活报告基因。"}],"note":"","opts":["A. 蛋白质与蛋白质之间的相互作用","B. DNA 与蛋白质之间的相互作用","C. DNA 和 RNA 之间的相互作用","D. DNA 与 DNA 之间的相互作用"],"printed_answer":"A"},{"id":"n0896","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"选择","years":["10"],"q":"真核生物中用有限基因产生多种蛋白质的主要方式是()B","points":[{"k":"答案","t":"B 选择性剪接。同一前体 mRNA 选择不同外显子组合，产生多种成熟 mRNA 与蛋白质，是真核有限基因编码多样蛋白质的主要方式。"}],"note":"","opts":["A. RNA 编辑","B. 选择性剪切","C. 基因重组","D. 基因扩散"],"printed_answer":"B"},{"id":"n0897","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"选择","years":["10"],"q":"可用于检测基因表达水平的是（）B","points":[{"k":"答案","t":"B RT-PCR。先反转录成 cDNA 再 PCR 扩增，可灵敏、定量地检测 mRNA 表达水平；单纯反转录（C）只制备 cDNA，不能定量。"}],"note":"基因芯片（A）同样用于表达谱检测，卷面取 B，按卷面作答。","opts":["A. 基因芯片","B. RT-PCR","C. 反转录","D. B+C"],"printed_answer":"B"},{"id":"n0898","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"考点","years":["10"],"q":"可用于快速进行 DNA 表达差异筛选的是()A","points":[{"k":"答案","t":"A（卷面）。快速筛选 DNA 表达差异的常用手段是 mRNA 差异显示 PCR、抑制消减杂交、基因芯片等高通量比较方法。"}],"note":"原卷选项缺失，只能按卷面字母 A 作答，具体技术名以选项内容为准。","opts":[],"printed_answer":"A"},{"id":"n0899","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["17"],"q":"原核与真核基因组对比","points":[{"k":"答案","t":"原核基因组小、环状双链、基因连续无内含子、按操纵子成串排列、多为单拷贝、基因密度高；真核基因组大、线状多染色体、基因不连续含内含子、重复序列与非编码区占比高、以单顺反子转录。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0900","subj":"631","chap":"一、染色体结构","type":"考点","years":["17"],"q":"真核基因组结构特点","points":[{"k":"答案","t":"①基因不连续，含内含子与外显子；②大量重复序列（高度、中度、单拷贝）；③存在多基因家族与假基因；④与组蛋白结合成核小体、构成线状染色体；⑤非编码序列比例高，编码序列仅占少部分。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0901","subj":"631","chap":"三、基因表达（转录、转录后加工、翻译、翻译后加工）","type":"考点","years":["17"],"q":"内含子外显子定义","points":[{"k":"答案","t":"外显子是基因中保留在成熟 mRNA 里的序列，参与编码蛋白；内含子是转录后被剪接除去的间隔序列。两者相间排列，构成真核断裂基因。"}],"note":"","opts":[],"printed_answer":""},{"id":"n0902","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"实验","years":["17"],"q":"关于基因工程的实验设计题","points":[{"k":"明确目的","t":"将目的基因定向克隆至表达载体，在宿主中高效表达并通过标签纯化获得目标蛋白（或构建敲除、过表达株）。"},{"k":"获取目的片段","t":"设计 5′端带保护碱基与酶切位点的引物，高保真酶 PCR 扩增，琼脂糖凝胶电泳鉴定并胶回收。"},{"k":"双酶切与连接","t":"目的片段与载体分别用两种限制酶双切，胶回收后 T4 DNA 连接酶 16℃ 过夜连接，构建重组质粒。"},{"k":"转化与筛选","t":"CaCl₂ 法或电穿孔转化 E. coli，涂布含抗生素的平板；挑单菌落做菌落 PCR 与质粒酶切初筛。"},{"k":"鉴定与表达","t":"阳性克隆送测序确认序列与读框；转入表达宿主，IPTG 诱导，SDS-PAGE 与 Western blot 验证表达。"},{"k":"对照与判定","t":"设空载体、无插入、未诱导三组对照；判定标准为测序正确、酶切片段大小相符、目标条带分子量正确。"},{"k":"注意事项","t":"酶切位点在载体与插入片段中均唯一、读框一致；载体去磷酸化防自身环化；全程无菌操作并遵守生物安全规定。"}],"note":"原题干仅写“关于基因工程的实验设计题”，无具体目的基因与载体信息，按通用克隆表达流程作答；若卷面给出具体基因，需替换相应酶切位点与筛选标记。","opts":[],"printed_answer":""},{"id":"n0016","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["00"],"q":"抗体酶","points":[{"k":"定义","t":"也叫催化性抗体，是抗体的高度选择性和酶的高效催化能力巧妙结合的产物，本质上是一类具有催化能力的免疫球蛋白，在其可变区赋予了酶的属性"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0017","subj":"880","chap":"六、DNA 克隆技术（基因工程）","type":"名词解释","years":["00"],"q":"基因文库","points":[{"k":"定义","t":"是某一生物体全部或部分基因的集合，将某个生物的基因组 DNA 或 cDNA 片段与适当载体在体外重组后，转化宿主细胞，所得的菌落或噬菌体的集合即为该生物的基因文库"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0028","subj":"631","chap":"第七章 核酸","type":"名词解释","years":["07"],"q":"半保留复制","points":[{"k":"定义","t":"DNA 在复制时，首先两条链之间的氢键断裂，两条链分开，然后以每一条链分别做模板，各自合成一条新的 DNA 链，这样合成的子代 DNA 中一条链来自亲代 DNA，另一条链是新合成的，这种复制方式称为半保留复制"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0032","subj":"631","chap":"第十九章 RNA 生物合成与加工","type":"名词解释","years":["07"],"q":"可变剪接","points":[{"k":"定义","t":"也叫选择性剪接，是指一个基因的转录产物在不同的发育阶段、分化细胞和生理状态下，通过不同的剪接方式，可以得到不同的 mRNA 和翻译产物（所产生的蛋白质产物称为同源体），是基因表达调控的一种重要方式"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0033","subj":"631","chap":"第七章 核酸","type":"名词解释","years":["07"],"q":"增强子","points":[{"k":"定义","t":"位于真核基因中远离转录起始点，能明显增强启动子转录效率的特殊 DNA 序列。它可位于被增强的转录基因的上游或下游，也可相距靶基因较远。"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0058","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["13"],"q":"β-转角","points":[{"k":"定义","t":"为多肽链中常见的二级结构，是一种可连接蛋白质分子中的其他二级结构（如α螺旋和β折叠）并使肽链走向改变的非重复多肽区，一般含有 2-16 个氨基酸残基，其中含有 5 个氨基酸残基以上的转角又常称之为环（loops），常见的转角含有 4 个氨基酸残基，有两种类型，特点为：第 1 个氨基酸残基的羰基氧与第 4 个残基的酰胺氮之间形成氢键；第 2 个残基大部分是脯氨酸，而第 3 个残基往往是甘氨酸"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0060","subj":"880","chap":"第七章 核酸","type":"名词解释","years":["13"],"q":"增色效应","points":[{"k":"定义","t":"指 DNA 在其变性解链过程中，由于碱基之中的共轭双键被暴露出来，使 DNA 在 260nm 波长处的紫外吸光值增加的现象"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0061","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["13"],"q":"亲和层析","points":[{"k":"定义","t":"是一种利用共价连接有特异配体的层析介质，分离蛋白质混合物中能特异结合配体的目的蛋白质或其他分子的层析技术，如免疫亲和层析、凝集素亲和层析等"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0063","subj":"880","chap":"第五章 酶","type":"名词解释","years":["13"],"q":"别构蛋白","points":[{"k":"定义","t":"寡聚蛋白质一般具有多个结合部位，结合在蛋白质分子的特定部位上的配体对该分子的其他部位所产生的影响，称为别构效应，具有别构效应的蛋白质称为“别构蛋白”"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0070","subj":"880","chap":"综合","type":"名词解释","years":["01"],"q":"第二信使","points":[{"k":"定义","t":"指第一信使（如激素）作用于靶细胞后刺激胞浆内产生的信息分子，将获得的信息增强、分化、整合、放大后传递给效应器产生效应，是胞外信息与胞内效应之间必不可少的中介物，第二信使主要包括：cAMP、cGMP、肌醇三磷酸、二酰甘油、Ca²⁺"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0071","subj":"880","chap":"第七章 核酸","type":"名词解释","years":["01"],"q":"分子杂交","points":[{"k":"分子杂交","t":"利用核酸变性与复性的性质，按碱基互补配对原则，将两条不同来源的核苷酸链在试管中经变性后慢慢冷却复性，若异源 DNA 在某些区域有相同序列，即形成杂合双链分子。"},{"k":"发生范围","t":"杂交可发生于 DNA 与 DNA 之间，也可发生于 DNA 与 RNA 之间。"}],"note":"口径：依据《真题分类》资料原文（名词解释）。","opts":[],"printed_answer":"","ref":true},{"id":"n0072","subj":"880","chap":"第七章 核酸","type":"名词解释","years":["01"],"q":"核糖体","points":[{"k":"定义","t":"是一种无膜包裹的颗粒状细胞器，具有合成蛋白质的功能，外层为蛋白质，内层为 RNA，每个细胞中有大量的核糖体，原核生物具有 70S 核糖体，而真核生物则有 80S 核糖体"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0073","subj":"880","chap":"六、DNA 克隆技术（基因工程）","type":"名词解释","years":["01"],"q":"基因工程","points":[{"k":"定义","t":"也称重组 DNA 技术，即利用限制性内切酶和载体，按照预先设计的要求，将一种生物的某种目的基因和载体 DNA 重组后，转入另一生物细胞中，进行复制、转录和表达的技术"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0148","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["19"],"q":"波尔效应","points":[{"k":"定义","t":"增加 CO₂ 浓度和降低 pH 都能提高血红蛋白亚基的协同效应，引起红细胞内血红蛋白氧亲和力下降，促进血红蛋白释放氧，反之，增加氧气的浓度，使血红蛋白释放 H⁺及 CO₂，这种 pH 和 CO₂ 对血红蛋白氧亲和力的影响称为波尔效应。波尔效应可以促进血红蛋白在组织中释放氧气，从而提高其运氧能力"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0164","subj":"880","chap":"第五章 酶","type":"名词解释","years":["11"],"q":"竞争性抑制作用","points":[{"k":"概念定义","t":"抑制剂与底物结构相似，二者竞争同一酶的活性中心，抑制剂占据活性中心后阻碍底物结合，从而使酶促反应速度降低。"},{"k":"动力学特征","t":"增大底物浓度可减弱甚至解除抑制，故 Vmax 不变、表观 Km 增大。"},{"k":"与自杀抑制区别","t":"竞争性抑制剂不与酶共价结合，可通过透析、稀释解除；自杀抑制剂则经酶催化生成产物后共价修饰酶，不可逆地使酶失活。"}],"note":"资料无对应原答案，按教材口径。资料该条为「自杀抑制作用」，与本题「竞争性抑制作用」不是同一题，仅在末点用于区分。","opts":[],"printed_answer":"","ref":false},{"id":"n0165","subj":"880","chap":"第十五章 脂类代谢","type":"名词解释","years":["11"],"q":"必需脂肪酸","points":[{"k":"定义","t":"是机体必需，但又不能自身合成或合成量不足，必须由食物提供的脂肪酸，称为“必需脂肪酸”，包括：亚油酸、α-亚麻酸（、花生四烯 酸）"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0169","subj":"880","chap":"第三章 氨基酸","type":"名词解释","years":["12"],"q":"等电点","points":[{"k":"定义","t":"使氨基酸处于兼性离子状态，在电场中不迁移（分子的静电荷为零）的 pH 值。处于等电点时，溶质静电荷为零，分子间排斥电位降低，吸引力增大，能相互聚集起来，沉淀析出，此时溶质的溶解度最低"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0170","subj":"880","chap":"第五章 酶","type":"名词解释","years":["12"],"q":"巴斯德效应","points":[{"k":"定义","t":"在厌氧条件下，向高速发酵的培养基中通入氧气，则葡萄糖消耗减少。这种抑制发酵产物积累的现象称为“巴斯德效应”，其原理是细菌进行有氧呼吸，所得的能量远大于等量糖进行发酵所得的能量，因此葡萄糖消耗量减少，发酵产物的积累受到抑制"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0172","subj":"880","chap":"第十四章 氧化磷酸化","type":"名词解释","years":["12"],"q":"光合作用","points":[{"k":"定义","t":"绿色植物利用太阳光能，将吸收的二氧化碳和水制造成有机物质，并释放出氧气的过程，光合作用分为两个部分，即光反应和暗反应，光反应阶段是将光能转化为 ATP 中的化学能，暗反应阶段是将光反应阶段产生的 ATP 转化为有机物中稳定的化学能"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0177","subj":"631","chap":"第七章 核酸","type":"名词解释","years":["20"],"q":"重叠基因","points":[{"k":"定义","t":"具有部分共用核苷酸序列的基因，即同一段 DNA 携带了两种或两种以上不同蛋白质的编码信息。重叠的序列可以是调控基因，也可以是结构基因部分，常见于病毒和噬菌体基因组中"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0218","subj":"880","chap":"第十四章 氧化磷酸化","type":"名词解释","years":["04"],"q":"线粒体","points":[{"k":"定义","t":"一种由双层膜包裹的、执行氧化磷酸化产能反应的重要细胞器，一般呈杆菌状，数量很多，由内外两层膜包裹，内膜向内伸展，形成许多嵴，其上着生许多基粒（即为 ATP 合成酶复合体）以及 4 种脂蛋白复合物（呼吸链成分），在线粒体的基质内含有 TCA 酶系、一套半自主复制的双链环状 DNA，以及 70S 核糖体"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0219","subj":"880","chap":"一、染色体结构","type":"名词解释","years":["04"],"q":"核小体","points":[{"k":"定义","t":"是染色质的基本结构单位，也是染色质包装的一级结构，由大约 200bp 的 DNA 和组蛋白八聚体（H2A、H2B、H3、H4 各两分子）以及一个组蛋白 H1 分子所组成"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0223","subj":"880","chap":"第三章 氨基酸","type":"名词解释","years":[],"q":"等电点聚焦电泳","points":[{"k":"pH梯度建立","t":"利用特殊的一种缓冲液（两性电解质），在聚丙烯酰胺凝胶内制造一个 pH 梯度作为支持介质。"},{"k":"迁移至pI","t":"电泳时每种蛋白质向各自等电点所在位置迁移，到达梯度中某一 pH 处不再带有净的正或负电荷时即停止移动。"},{"k":"分离与测pI","t":"不同蛋白质 pI 不同，各自聚焦于相应 pH 位置而被分离，该技术同时可用于蛋白质等电点的测定。"}],"note":"口径：依据《真题分类》资料原文。本题原无要点，按资料原文成稿；等电点测定一句取自同条资料（等电聚焦电泳）原文。","opts":[],"printed_answer":"","ref":true},{"id":"n0225","subj":"880","chap":"综合","type":"名词解释","years":[],"q":"肽聚糖","points":[{"k":"定义","t":"由 N-乙酰葡糖胺和 N-乙酰唾液酸交替连接的杂多糖，与 4-5 个不同组成的短肽交叉连接形成的多层网状大分子结构，是细菌细胞壁的主要成分"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0276","subj":"880","chap":"第四章 蛋白质","type":"名词解释","years":["10"],"q":"蛋白质结构域","points":[{"k":"定义","t":"结构域介于超二级结构和三级结构之间，是多肽链在超二级结构的基础上进一步盘绕折叠，形成紧密的近乎于球状的结构，称为“结构域”，结构域与结构域之间关系松懈，常常由称为“铰链区”的一段长短不等的肽链相连"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0299","subj":"631","chap":"六、DNA 克隆技术（基因工程）","type":"名词解释","years":["22"],"q":"基因组文库","points":[{"k":"定义","t":"是某一生物体全部或部分基因的集合，将某个生物的基因组 DNA 或 cDNA 片段与适当载体在体外重组后，转化宿主细胞，所得的菌落或噬菌体的集合即为该生物的基因文库"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0322","subj":"631","chap":"第十九章 RNA 生物合成与加工","type":"名词解释","years":["08"],"q":"管家基因","points":[{"k":"管家基因定义","t":"指所有细胞中均要表达的一类基因，其产物是对维持细胞基本生命活动所必需的。"},{"k":"表达特征","t":"是一类始终保持着低水平甲基化、并一直处于活性转录状态的基因。"}],"note":"口径：依据《真题分类》资料原文（名词解释）。","opts":[],"printed_answer":"","ref":true},{"id":"n0354","subj":"631","chap":"第七章 核酸","type":"名词解释","years":["13"],"q":"表观调控","points":[{"k":"定义","t":"与 DNA 排列顺序的变化无关的，调节基因表达的频率、速度或者表达程度的过程，如 DNA 甲基化、组蛋白修饰、基因组印记、基因沉默等，这种调节不能通过种系或生殖细胞传递，但可通过细胞分裂传给子代，在静止细胞的细胞质中也能稳定地自我繁殖"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0355","subj":"631","chap":"一、染色体结构","type":"名词解释","years":["13"],"q":"组蛋白密码","points":[{"k":"定义","t":"是指核小体核心组蛋白末端被修饰氨基酸的种类、位置和修饰类型（如乙酰化、甲基化、磷酸化等），它可影响核小体的结构，并改变染色体的结构和功能，从而决定基因表达调控的状态"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0356","subj":"631","chap":"第七章 核酸","type":"名词解释","years":["13"],"q":"RNA 干扰","points":[{"k":"定义","t":"是将一段短双链的 RNA 序列导入机体或细胞中，使机体或细胞中与之有同源序列的 mRNA 的翻译受到抑制，或使其降解，从而导致基因的表达活性受到抑制，甚至完全丧失的现象"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0358","subj":"631","chap":"一、染色体结构","type":"名词解释","years":["13"],"q":"联会体","points":[{"k":"定义","t":"是减数分裂Ⅰ的偶线期中，配对的两条同源染色体之间形成的一种复合结构，主要由侧生组分、中间区和连接侧生组分与中间区的 SC 纤维组成，它与染色体的配对、交换和分离密切相关"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0400","subj":"880","chap":"第七章 核酸","type":"名词解释","years":["02"],"q":"蛋白质的可逆变性","points":[{"k":"定义","t":"蛋白质在除去变形因素之后，在适当的条件下蛋白质的构象可以由变性状态恢复到天然状态，这种现象称为“蛋白质的可逆变性”"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0401","subj":"880","chap":"第十四章 氧化磷酸化","type":"名词解释","years":["02"],"q":"离子载体抗生素","points":[{"k":"定义","t":"是一些具有特殊结构的复杂分子，它具有改变膜通透性，促进离子过膜运输的作用，如缬氨霉素、短杆菌肽等，可以作为解偶联剂，抑制氧化磷酸化作用，影响细菌的能量代谢系统，从而杀死细菌"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0402","subj":"880","chap":"第五章 酶","type":"名词解释","years":["02"],"q":"反馈抑制","points":[{"k":"定义","t":"指酶作用的产物对酶本身的活性产生抑制作用，称为“酶的反馈抑制”"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0403","subj":"880","chap":"第七章 核酸","type":"名词解释","years":["02"],"q":"反义 RNA","points":[{"k":"定义","t":"是一种与 mRNA 互补的 RNA 分子，它是反义基因或基因的反义转录产物，与 mRNA 结合后，可阻断 mRNA 的翻译，这是在翻译水平调控基因表达的一种方式，原核生物中普遍存在反义 RNA 的调节系统"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0496","subj":"631","chap":"第四章 蛋白质","type":"名词解释","years":["21"],"q":"外显子","points":[{"k":"定义","t":"是真核生物基因的一部分，它在剪接后仍会被保存下来，并可在蛋白质生物合成过程中表达为蛋白质"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0497","subj":"631","chap":"第七章 核酸","type":"名词解释","years":["21"],"q":"转录因子","points":[{"k":"定义","t":"是一类能识别并结合转录起始位点的上游序列或远端增强子元件，通过 DNA-蛋白质相互作用而调节转录活性，从而保证目的基因以特定的强度，在特定的时间与空间表达的蛋白质分子。包括转录激活因子和转录阻遏因子"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0514","subj":"631","chap":"第三章 氨基酸","type":"名词解释","years":[],"q":"等电聚焦电泳","points":[{"k":"pH梯度介质","t":"在具有 pH 梯度的介质中进行的电泳，梯度由两性电解质在支持介质中形成。"},{"k":"按pI分离","t":"根据不同蛋白质具有不同的等电点，各自迁移并停留在与其 pI 相等的 pH 区带，净电荷为零而不再移动。"},{"k":"测等电点","t":"由此把混合蛋白质分开，同时该技术也常用于蛋白质等电点的测定。"}],"note":"口径：依据《真题分类》资料原文。本题原无要点，按资料原文成稿，三点为同一条资料原意的分拆，未加新事实。","opts":[],"printed_answer":"","ref":true},{"id":"n0515","subj":"631","chap":"第十四章 氧化磷酸化","type":"名词解释","years":[],"q":"生物氧化","points":[{"k":"生物氧化定义","t":"糖、脂肪、蛋白质等物质在生物体内通过酶的催化，实现的一系列释放能量的化学反应过程。"},{"k":"本质","t":"本质是有机物逐步氧化分解、脱氢脱羧，释放的能量部分储存于 ATP，其余以热的形式散发。"}],"note":"口径：依据《真题分类》资料原文（仅一句定义）。第二个要点为按教材口径补充的“本质”，原资料未涉及。","opts":[],"printed_answer":"","ref":true},{"id":"n0517","subj":"631","chap":"第四章 蛋白质","type":"名词解释","years":[],"q":"G蛋白","points":[{"k":"定义","t":"在细胞内信号传导途径中起着重要作用的 GTP 结合蛋白，具有内源 GTP 酶活性，由α，β，γ三个不同亚基组成。激素与激素受体结合诱导 GTP 跟 G 蛋白结合的 GDP 进行交换，结果激活位于信号传导途径中下游的腺苷酸环化酶。 G 蛋白将细胞外的第一信使肾上腺素等激素和细胞内的腺苷酸环化酶催化的腺苷酸环化生成的第二信使 cAMP 联系起来。"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0527","subj":"631","chap":"第二十二章 基因工程与蛋白质工程","type":"名词解释","years":["25"],"q":"穿梭载体","points":[{"k":"定义","t":"是人工构建的一类具有两种不同复制起点和选择记号，因而可以在两种不同寄主细胞中存活和复制的（质粒）载体"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0528","subj":"631","chap":"第四章 蛋白质","type":"名词解释","years":["25"],"q":"反式作用因子","points":[{"k":"反式作用因子","t":"指能直接或间接地识别或结合在各类顺式作用元件核心序列上、参与调控靶基因转录效率的蛋白质。"},{"k":"作用方式","t":"其本身不直接决定基因表达，而是通过结合顺式元件、阻断或改变来自上、下游的调控效应而发挥调节作用。"}],"note":"口径：依据《真题分类》资料原文（名词解释）。原文后半句表述较绕，此处按原意复述，未改变含义。","opts":[],"printed_answer":"","ref":true},{"id":"n0567","subj":"631","chap":"第三章 氨基酸","type":"名词解释","years":["24"],"q":"信号肽","points":[{"k":"定义","t":"是分泌蛋白新生肽链 N 端的一段疏水性氨基酸残基组成的肽段，可引导蛋白质进入内质网，一般在蛋白质进入内质网不久后便被酶切除掉"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0568","subj":"631","chap":"第七章 核酸","type":"名词解释","years":["24"],"q":"遗传密码","points":[{"k":"定义","t":"核酸中的核苷酸残基序列与蛋白质中的氨基酸残基序列 之间的对应关系。；连续的 3 个核苷酸残基序列为一个密码子，特指一个氨基酸。标准的遗传密码是由 64 个密码子组成的，几乎为所有生物通用。"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0582","subj":"631","chap":"一、染色体结构","type":"名词解释","years":["11"],"q":"染色体步移","points":[{"k":"定义","t":"利用已知的基因或分子标记来筛选大片段基因组文库获得阳性克隆，如此得到的阳性克隆是\"一步克隆\"，再利用获得的克隆作探针对文库进行第二次杂交，得到与探针具有重复序列的阳性克隆称为\"二次克隆\"，如此反复即可取到需要的克隆，获得目的基因"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0583","subj":"631","chap":"第二十二章 基因工程与蛋白质工程","type":"名词解释","years":["11"],"q":"DNA 疫苗","points":[{"k":"概念定义","t":"将编码抗原蛋白的外源基因克隆到真核表达载体中，直接导入机体，在体内表达抗原蛋白以诱导特异性免疫应答的一类核酸疫苗。"},{"k":"免疫特点","t":"抗原在体内持续表达，可同时诱导体液免疫与细胞免疫，效果类似减毒活疫苗，但无活病原感染与回复的风险。"},{"k":"构建与接种","t":"由真核启动子驱动的抗原基因质粒构成，可用肌肉注射或基因枪导入，常配合佐剂以提高摄取与表达效率。"},{"k":"优点与局限","t":"制备简便、成本低、耐热便于储运、便于构建多价疫苗；局限为表达效率与免疫原性个体差异较大，并有整合入基因组的理论顾虑。"}],"note":"资料无对应原答案，按教材口径。资料该条为「DNA 复性」，与本题「DNA 疫苗」不是同一题；本题原无要点，按教材口径成稿。","opts":[],"printed_answer":"","ref":false},{"id":"n0584","subj":"631","chap":"第七章 核酸","type":"名词解释","years":["11"],"q":"表观遗传","points":[{"k":"定义","t":"指在 DNA 序列不发生改变的情况下，由于某些因素的改变，基因功能可发生可遗传的变化，最终导致表型变异的遗传现象及其本质。染色质重塑构成了表观遗传的基础，如组蛋白修饰、DNA甲基化、基因组印记、基因沉默、母体效应等"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""},{"id":"n0698","subj":"880","chap":"第十四章 氧化磷酸化","type":"名词解释","years":["14"],"q":"底物水平磷酸化","points":[{"k":"底物水平磷酸化","t":"ATP 的形成直接与一中间代谢物上的磷酸基团的转移相偶联的作用。"},{"k":"要点","t":"其特点是不经电子传递链与跨膜质子梯度，能量直接来自高能中间代谢物上磷酸基团的转移。"}],"note":"口径：依据《真题分类》资料原文（名词解释）。第二个要点由原文“直接与中间代谢物上磷酸基团转移相偶联”展开，未加新数据。","opts":[],"printed_answer":"","ref":true},{"id":"n0876","subj":"631","chap":"第七章 核酸","type":"名词解释","years":["10"],"q":"密码子","points":[{"k":"定义","t":"mRNA 上每 3 个核苷酸翻译成多肽链上的一个氨基酸，这 3 个核苷酸就成为一个密码子（三联子密码）。mRNA 的三联密码子可与 tRNA 的反密码子互补，经其解读后将核酸序列信息转换成氨基酸序列。"}],"note":"口径：依据资料名词解释条目","opts":[],"printed_answer":""}],"terms":[{"subj":"880","term":"蛋白质二级结构","years":["00","05"],"def":"是指蛋白质分子中某一段肽链的局部空间结构，也就是该段肽链主链骨架原子的相对空间位置，而不包括氨基酸残基侧链构象的内容和与其他肽链的关系。二级结构主要借主链原子之间形成的氢键维系构象稳定，主要有：α螺旋、β折叠、β转角、无规卷曲等常见形式","src":"资料"},{"subj":"880","term":"抗体酶","years":["00"],"def":"也叫催化性抗体，是抗体的高度选择性和酶的高效催化能力巧妙结合的产物，本质上是一类具有催化能力的免疫球蛋白，在其可变区赋予了酶的属性","src":"资料"},{"subj":"880","term":"基因文库","years":["00"],"def":"是某一生物体全部或部分基因的集合，将某个生物的基因组 DNA 或 cDNA 片段与适当载体在体外重组后，转化宿主细胞，所得的菌落或噬菌体的集合即为该生物的基因文库","src":"资料"},{"subj":"880","term":"冈崎片段","years":["00","05","13"],"def":"相对较短的 DNA 链（大约 1000 核苷酸残基），是在 DNA 的滞后链（后随链）的不连续合成期间生成的片段，由冈崎发现，因此称为“冈崎片段”","src":"资料"},{"subj":"880","term":"寡糖","years":["00"],"def":"指由 2-10 个单糖经脱水缩合，以糖苷键连接形成的具有直链或支链的低度聚合糖类的总称，较常见的寡糖主要为二糖，如：蔗糖、麦芽糖、乳糖、海藻糖等","src":"资料"},{"subj":"880","term":"别构效应","years":["01","12"],"def":"当某些化合物与酶分子中的别构部位可逆结合后，酶分子的构象发生改变，使酶活性部位对底物的结合与催化作用受到影响，从而调节酶促反应速度及代谢过程，这种效应称为“别构效应”，也称变构效应，别构效应一般只存在于多亚基蛋白质中，亚基间的非共价作用是别构效应形成的基础","src":"资料"},{"subj":"880","term":"第二信使","years":["01"],"def":"指第一信使（如激素）作用于靶细胞后刺激胞浆内产生的信息分子，将获得的信息增强、分化、整合、放大后传递给效应器产生效应，是胞外信息与胞内效应之间必不可少的中介物，第二信使主要包括：cAMP、cGMP、肌醇三磷酸、二酰甘油、Ca²⁺","src":"资料"},{"subj":"880","term":"分子杂交","years":["01"],"def":"利用核酸变性、复性的性质，根据碱基互补配对原则，将两条不同来源的核酸链在试管中经变性后，慢慢冷却让其复性，若这些异源 DNA 之间在某些区域有相同的序列，则可形成杂合双链分子，分子杂交可发生于 DNA 之间或 DNA 与 RNA 之间","src":"资料"},{"subj":"880","term":"核糖体","years":["01"],"def":"是一种无膜包裹的颗粒状细胞器，具有合成蛋白质的功能，外层为蛋白质，内层为 RNA，每个细胞中有大量的核糖体，原核生物具有 70S 核糖体，而真核生物则有 80S 核糖体","src":"资料"},{"subj":"880","term":"基因工程","years":["01"],"def":"也称重组 DNA 技术，即利用限制性内切酶和载体，按照预先设计的要求，将一种生物的某种目的基因和载体 DNA 重组后，转入另一生物细胞中，进行复制、转录和表达的技术","src":"资料"},{"subj":"880","term":"蛋白质的可逆变性","years":["02"],"def":"蛋白质在除去变形因素之后，在适当的条件下蛋白质的构象可以由变性状态恢复到天然状态，这种现象称为“蛋白质的可逆变性”","src":"资料"},{"subj":"880","term":"离子载体抗生素","years":["02"],"def":"是一些具有特殊结构的复杂分子，它具有改变膜通透性，促进离子过膜运输的作用，如缬氨霉素、短杆菌肽等，可以作为解偶联剂，抑制氧化磷酸化作用，影响细菌的能量代谢系统，从而杀死细菌","src":"资料"},{"subj":"880","term":"反馈抑制","years":["02"],"def":"指酶作用的产物对酶本身的活性产生抑制作用，称为“酶的反馈抑制”","src":"资料"},{"subj":"880","term":"反义 RNA","years":["02"],"def":"是一种与 mRNA 互补的 RNA 分子，它是反义基因或基因的反义转录产物，与 mRNA 结合后，可阻断 mRNA 的翻译，这是在翻译水平调控基因表达的一种方式，原核生物中普遍存在反义 RNA 的调节系统","src":"资料"},{"subj":"880","term":"质粒","years":["02"],"def":"是存在于细胞质中染色体（核质）以外的遗传物质，为双股环状 DNA 分子，称为 cccDNA，可携带遗传信息，控制细菌某些特定的遗传性状","src":"资料"},{"subj":"880","term":"线粒体","years":["04"],"def":"一种由双层膜包裹的、执行氧化磷酸化产能反应的重要细胞器，一般呈杆菌状，数量很多，由内外两层膜包裹，内膜向内伸展，形成许多嵴，其上着生许多基粒（即为 ATP 合成酶复合体）以及 4 种脂蛋白复合物（呼吸链成分），在线粒体的基质内含有 TCA 酶系、一套半自主复制的双链环状 DNA，以及 70S 核糖体","src":"资料"},{"subj":"880","term":"全酶","years":["04"],"def":"酶蛋白和辅助因子结合后形成的复合物称为“全酶”，即全酶=酶蛋白+辅助因子，其中酶蛋白具有底物结合能力，决定酶催化的专一性，而辅因子常起电子、原子或某些化学基团的传递作用，决定酶催化的反应类型","src":"资料"},{"subj":"880","term":"核小体","years":["04"],"def":"是染色质的基本结构单位，也是染色质包装的一级结构，由大约 200bp 的 DNA 和组蛋白八聚体（H2A、H2B、H3、H4 各两分子）以及一个组蛋白 H1 分子所组成","src":"资料"},{"subj":"880","term":"Km","years":["04"],"def":"即米氏常数，其物理意义为酶促反应速率达到最大反应速率一半时的底物浓度，单位为 mol/L，其数值的大小还可近似反应酶对底物亲和力的大小，即 Km 越大，酶对底物亲和力越小"},{"subj":"880","term":"酮体","years":["04","19"],"def":"是在肝脏中由乙酰 CoA 合成而来的燃料分子，包括乙酰乙酸、丙酮、β-羟基丁酸，在饥饿期间，酮体是包括脑在内的许多组织的燃料，但酮体过多会导致酮尿症和酸中毒","src":"资料"},{"subj":"880","term":"高尔基体","years":["05"],"def":"是一种由数个平行堆叠的扁平膜囊和大小不等的囊泡所组成的膜聚合体，具有合成、分泌糖蛋白和脂蛋白，对某些蛋白质原进行酶切加工，以及对新细胞壁和细胞膜提供合成原料等多种功能","src":"资料"},{"subj":"880","term":"酶的比活力","years":["05","10"],"def":"酶的比活力也称为比活性，是指每毫克酶蛋白所具有的活力单位数，有时也用每克酶制剂或每毫升酶制剂所含的活力单位数来表示，比活力是表示酶制剂纯度的一个重要指标，对同一种酶来说，酶的比活力越高，纯度越高","src":"资料"},{"subj":"880","term":"等电点聚焦电泳","years":["05"],"def":"利用特殊的一种缓冲液（两性电解质）在聚丙烯酰胺凝胶内制造一个 pH 梯度，电泳时每种蛋白质就将迁移到它的等电点（pI）处，即梯度中的某一 pH 时，就不再带有净的正或负电荷了","src":"资料"},{"subj":"880","term":"肽聚糖","years":["05"],"def":"由 N-乙酰葡糖胺和 N-乙酰唾液酸交替连接的杂多糖，与 4-5 个不同组成的短肽交叉连接形成的多层网状大分子结构，是细菌细胞壁的主要成分","src":"资料"},{"subj":"880","term":"底物磷酸化","years":["10"],"def":"代谢物在脱氢、脱水过程中，底物分子内部能量重新分布，直接将代谢物分子中高能磷酸键转移给 ADP，生成 ATP 的过程","src":"资料"},{"subj":"880","term":"呼吸链","years":["10"],"def":"是由一系列的递氢体和电子传递体按一定的顺序（电子亲和力增大的顺序）排列所组成的连续反应体系，它将代谢物脱下的成对电子交给氧生成水，同时释放的能量用于形成质子梯度，经 ATP 合酶生成 ATP","src":"资料"},{"subj":"880","term":"盐析","years":["10"],"def":"是一种通过向蛋白质溶液中加入高浓度的中性盐，破坏蛋白质在 水溶液中的稳定性因素，从而析出蛋白质的方法，其原理：中性盐会破坏蛋白质的水化层和双电子层，从而导致蛋白质疏水基团外露，相互聚集而形成沉淀","src":"资料"},{"subj":"880","term":"构型","years":["10"],"def":"指有机分子中各个原子特有的固定的空间排列，构型的异构包括：结构异构和立体异构（几何异构、旋光异构），与构象不同的是，构型的转变必须经共价键的断裂和重新形成","src":"资料"},{"subj":"880","term":"蛋白质结构域","years":["10"],"def":"结构域介于超二级结构和三级结构之间，是多肽链在超二级结构的基础上进一步盘绕折叠，形成紧密的近乎于球状的结构，称为“结构域”，结构域与结构域之间关系松懈，常常由称为“铰链区”的一段长短不等的肽链相连","src":"资料"},{"subj":"880","term":"竞争性抑制作用","years":["10","11"],"def":"有些抑制剂与酶的底物结构相似，与底物竞争同一个酶的结合部位，从而抑制底物与酶的结合，抑制酶的催化活性，此种抑制作用称为“竞争性抑制作用”，这种抑制使 Km 增大，而 Vmax 不变，并可以通过增加底物浓度来减少抑制","src":"资料"},{"subj":"880","term":"同工酶","years":["10","11","19"],"def":"催化相同的化学反应，但其在蛋白质分子结构、理化性质和免疫性能等方面都存在着明显差异的一组酶，同工酶的变化有助于某些疾病的临床诊断，如血清中磷酸肌酸激酶和乳酸脱氢酶的同工酶检测，可用于心肌梗死的早期诊断","src":"资料"},{"subj":"880","term":"波尔效应","years":["10","11","12","19"],"def":"增加 CO₂ 浓度和降低 pH 都能提高血红蛋白亚基的协同效应，引起红细胞内血红蛋白氧亲和力下降，促进血红蛋白释放氧，反之，增加氧气的浓度，使血红蛋白释放 H⁺及 CO₂，这种 pH 和 CO₂ 对血红蛋白氧亲和力的影响称为波尔效应。波尔效应可以促进血红蛋白在组织中释放氧气，从而提高其运氧能力","src":"资料"},{"subj":"880","term":"巴斯德效应","years":["10","12"],"def":"在厌氧条件下，向高速发酵的培养基中通入氧气，则葡萄糖消耗减少。这种抑制发酵产物积累的现象称为“巴斯德效应”，其原理是细菌进行有氧呼吸，所得的能量远大于等量糖进行发酵所得的能量，因此葡萄糖消耗量减少，发酵产物的积累受到抑制","src":"资料"},{"subj":"880","term":"抗体","years":["11"],"def":"是由浆细胞（B 细胞分化而来）合成分泌的，能与相应抗原发生反应的免疫球蛋白，由 4 条多肽链组成，2 条较长、相对分子量较大的称为重链，2 条较短、相对分子量较小的称为轻链，形成类似于“Y”的形状，Y 型结构的两个“分叉”的顶端含有两个抗原结合部位，可特异性结合抗原，从而引起免疫应答反应","src":"资料"},{"subj":"880","term":"必需脂肪酸","years":["11"],"def":"是机体必需，但又不能自身合成或合成量不足，必须由食物提供的脂肪酸，称为“必需脂肪酸”，包括：亚油酸、α-亚麻酸（、花生四烯 酸）","src":"资料"},{"subj":"880","term":"等电点","years":["12","19"],"def":"使氨基酸处于兼性离子状态，在电场中不迁移（分子的静电荷为零）的 pH 值。处于等电点时，溶质静电荷为零，分子间排斥电位降低，吸引力增大，能相互聚集起来，沉淀析出，此时溶质的溶解度最低","src":"资料"},{"subj":"880","term":"Tm","years":["12"],"def":"DNA 变性过程中，紫外光吸收值增加到最大值的 50%时的温度称为 DNA 的解链温度 (Tm)，在此温度时，DNA 分子内 50%的双链结构被解开。Tm 值受 DNA 的分子大小（类型）、溶液离子强度和 GC 碱基含量等因素影响"},{"subj":"880","term":"氧化磷酸化","years":["12","19"],"def":"底物在氧化过程中产生高能电子，通过线粒体内膜电子传递链，将高能电子的能量释放出来，转换成质子动力势，进而合成 ATP 的过程。其中电子传递过程即为氧化过程，ATP 合酶生成 ATP 的过程即为磷酸化过程，二者偶联即为氧化磷酸化过程","src":"资料"},{"subj":"880","term":"减色效应","years":["12"],"def":"核酸复性后，260nm 处紫外吸收值明显减少的现象，称为“减色效应”，其原理是：由于复性后，单链核酸通过碱基互补配对形成双链，碱基埋藏在双螺旋内部，使得碱基的共轭双键被屏蔽，因此紫外吸收值明显减少。","src":"资料"},{"subj":"880","term":"光合作用","years":["12"],"def":"绿色植物利用太阳光能，将吸收的二氧化碳和水制造成有机物质，并释放出氧气的过程，光合作用分为两个部分，即光反应和暗反应，光反应阶段是将光能转化为 ATP 中的化学能，暗反应阶段是将光反应阶段产生的 ATP 转化为有机物中稳定的化学能","src":"资料"},{"subj":"880","term":"糖异生","years":["12"],"def":"指体内由简单的非糖类物质转变为葡萄糖和糖原的过程。虽然由丙酮酸开始的糖异生利用了糖酵解中的七步进似平衡反应的逆反应，但还必需利用另外四步酵解中不曾出现的酶促反应，绕过酵解过程中不可逆的三个反应。因此糖异生不是糖酵解的简单逆转","src":"资料"},{"subj":"880","term":"启动子","years":["12"],"def":"与基因表达启动相关的顺式作用元件，是结构基因的重要成分。它是一段位于转录起始点 5'端上游区 100bp-200bp 以内的具有独立功能的 DNA 序列，能活化 RNA 聚合酶，使之与模板 DNA 准确地相结合，并具有转录起始的特异性，可以控制基因转录的起始时间和表达的程度","src":"资料"},{"subj":"880","term":"丙氨酸-葡萄糖循环","years":["13"],"def":"运动时，骨骼肌内糖分解生成的丙酮酸与蛋白质分解释放的支链氨基酸之间发生转氨基作用，丙酮酸生成丙氨酸释放入血，随血液循环进入肝脏，经糖异生作用合成葡萄糖，并转运到骨骼肌的代谢过程","src":"资料"},{"subj":"880","term":"γ-谷氨酰胺循环","years":["13"],"def":"是体内氨转运的一种形式，即脑和骨骼肌中的谷氨酸与游离氨结合形成谷氨酰胺，并通过血液循环运输至肝或肾中重新分解为谷氨酸和氨的过程，其中谷氨酰胺为中性无毒物质，容易透过细胞膜，因此是氨的主要运输形式","src":"资料"},{"subj":"880","term":"β-转角","years":["13"],"def":"为多肽链中常见的二级结构，是一种可连接蛋白质分子中的其他二级结构（如α螺旋和β折叠）并使肽链走向改变的非重复多肽区，一般含有 2-16 个氨基酸残基，其中含有 5 个氨基酸残基以上的转角又常称之为环（loops），常见的转角含有 4 个氨基酸残基，有两种类型，特点为：第 1 个氨基酸残基的羰基氧与第 4 个残基的酰胺氮之间形成氢键；第 2 个残基大部分是脯氨酸，而第 3 个残基往往是甘氨酸","src":"资料"},{"subj":"880","term":"磷氧比","years":["13"],"def":"在氧化磷酸化中，一对电子经呼吸链传递至氧时，所产生的 ATP 分子数，即每消耗 1mol 氧原子所产生的 ATP 的摩尔数","src":"资料"},{"subj":"880","term":"增色效应","years":["13"],"def":"指 DNA 在其变性解链过程中，由于碱基之中的共轭双键被暴露出来，使 DNA 在 260nm 波长处的紫外吸光值增加的现象","src":"资料"},{"subj":"880","term":"亲和层析","years":["13"],"def":"是一种利用共价连接有特异配体的层析介质，分离蛋白质混合物中能特异结合配体的目的蛋白质或其他分子的层析技术，如免疫亲和层析、凝集素亲和层析等","src":"资料"},{"subj":"880","term":"操纵子","years":["13"],"def":"是指原核生物中由一个或多个相关基因以及转录翻译调控元件组成的基因表达单元，其组成包括：结构基因、调节基因、以及由调节基因产物所识别的控制序列（操纵基因），功能相关的基因串联排列在染色体上共同表达，转录产物为多顺反子 mRNA，操纵子只存在于原核生物中，真核生物不存在","src":"资料"},{"subj":"880","term":"分子伴侣","years":["13"],"def":"是细胞中一类能够识别并结合到不完全折叠或装配的蛋白质上，以帮助这些多肽正确折叠、转运或防止它们聚集的蛋白质，其本身不参与最终产物的形成，只起陪伴的作用，因此得名为“分子伴侣”","src":"资料"},{"subj":"880","term":"别构蛋白","years":["13"],"def":"寡聚蛋白质一般具有多个结合部位，结合在蛋白质分子的特定部位上的配体对该分子的其他部位所产生的影响，称为别构效应，具有别构效应的蛋白质称为“别构蛋白”","src":"资料"},{"subj":"880","term":"主动运输","years":["13"],"def":"指物质逆浓度梯度或电化学梯度跨膜转运的过程。这一过程的进行需要能量的供给和载体蛋白的协助，根据能量来源的不同，可将主动运输分为：一级主动运输（依靠水解 ATP 供能）、二级主动运输（利用浓度梯度或电化学梯度提供能 量，也称协同运输）","src":"资料"},{"subj":"880","term":"乙醛酸循环","years":["18"],"def":"该途径只存在于某些植物和微生物中，是柠檬酸循环的一个修改形式，即由 2 分子乙酰 CoA 净合成 1 分子草酰乙酸的过程，因产生重要中间代谢物—乙醛酸，故称“乙醛酸循环”。（其过程为：在异柠檬酸裂解酶的催化下，异柠檬酸直接分解为乙醛酸和琥珀酸，琥珀酸参与 TCA 循环，而乙醛酸与另一分子乙酰 CoA 生成苹果酸，进而氧化生成草酰乙酸，并经糖异生途径合成葡萄糖。其意义在于：使萌发的种子中贮存的脂质转变为糖类，为种子生长提供充足的能源）","src":"资料"},{"subj":"880","term":"酮症","years":["18"],"def":"当糖尿病加重时，脂肪分解加速，大量脂肪酸在肝脏经β-氧化产生大量乙酰 CoA，乙酰 CoA 进入柠檬酸循环受阻，转而产生酮体。血中酮体浓度增高，称为酮血症；尿中酮体增高，称为酮尿症，临床上统称为“酮症”","src":"资料"},{"subj":"880","term":"半不连续复制","years":["18"],"def":"子代 DNA 中的一条链以 3'-5'母链为模板连续合成，称为前导链；另一条链以 5'-3'母链为模板，先合成若干冈崎片段，再相连接形成完整的新链，称为后随链，为不连续合成，因此 DNA 复制时，一条链连续合成，另一条链不连续合成，故称为“半不连续复制”","src":"资料"},{"subj":"880","term":"糖酵解","years":["19"],"def":"指葡萄糖或糖原在无氧条件下，分解为丙酮酸的过程。是生物最古老、最原始的一种获能方式，该途径发生于细胞质基质中，经 10 步反应，1 分子葡萄糖可分解生成 2 分子丙酮酸、2 分子 ATP 和 2 分子 NADH+H⁺","src":"资料"},{"subj":"880","term":"转换数","years":[],"def":"当酶被底物饱和时，每秒钟每个酶分子或每个活性部位（亚基）将底物转化为产物的分子数，称为转换数（TN），也称催化常数（Kcat），Kcat 值愈大表示酶的催化效率愈高。","src":"资料"},{"subj":"880","term":"六大酶类","years":[],"def":"氧转水裂异连（简记）。","src":"资料"},{"subj":"880","term":"模体","years":[],"def":"表示具有特定功能的，或作为一个独立结构域一部分的相邻的二级结构的聚合体，它一般被称为功能模体，或结构模体，相当于超二级结构"},{"subj":"880","term":"酶活力","years":[],"def":"也称酶活性，是指酶催化某一化学反应的能力，其大小可用在一定条件下，酶催化某一化学反应的速率来表示，酶催化反应速率愈大，酶活力愈高","src":"资料"},{"subj":"880","term":"酶活力单位","years":[],"def":"简称酶单位，即酶含量的多少，是衡量酶活力大小的计量单位。酶活力国际单位（IU）定义为：在最适反应条件下（25℃），每分钟内催化 1 微摩尔（μmol）底物转化为产物所需的酶量，即 1IU=1μmol/min","src":"资料"},{"subj":"880","term":"乳化作用","years":[],"def":"指通过表面活性剂（油包水型或水包油型乳化剂），使一种液体（分散相）分散在另一种不相混溶的液体（连续相）中，并能稳定存在的作用。乳化剂多为两亲物质，即一侧亲水，一侧亲脂，因此可以使油水互溶","src":"资料"},{"subj":"880","term":"酸败现象","years":[],"def":"指油脂在贮存期间，因氧气、日光、微生物、酶等作用，发生过氧化，产生挥发性的醛和酸等物质，从而产生酸臭、苦涩等难闻的刺激性气味，这种现象称为“酸败现象”","src":"资料"},{"subj":"880","term":"碘值","years":[],"def":"100g 油脂卤化时所能吸收碘的量（g），其反应实质为碘与脂肪酸的双键发生加成反应，因此碘值可反应出三酰甘油中不饱和键的多少"},{"subj":"880","term":"皂化值","years":[],"def":"1g 油脂被皂化所需的 KOH 量（mg），可以反映三酰甘油的摩尔数，或其平均相对分子质量","src":"资料"},{"subj":"880","term":"自由基","years":[],"def":"泛指生物体自身代谢产生的一些带有未配对电子的基团或分子，它们是不稳定的、化学活性很高的基团或分子，包括含氧自由基和非含氧自由基，可引发自由基链式反应，如脂质过氧化","src":"资料"},{"subj":"880","term":"色谱","years":[],"def":"也称层析法，是利用不同物质在两相介质中具有不同的分配系数，通过两相介质的相对运动实现物质分离的一类方法，也广泛用于物质的分析研究。根据使用介质的不同，可分为柱层析、纸层析、和薄层层析"},{"subj":"880","term":"进化树","years":[],"def":"采用物种之间的最小突变距离构建而成的一种树状结构，可以表示不同物种的进化关系和程度，也称为“种系发生树”。一般是当不同物种蛋白质的氨基酸差异进一步以核苷酸的改变来度量时，可用最小突变距离表示","src":"资料"},{"subj":"880","term":"固定化酶","years":[],"def":"指通过物理化学手段将生物提取的酶固定在介质上，或包埋在微胶囊中，从而形成不溶于水并具有酶活性的状态，可提高酶的热稳定性、提高酶的重复使用率、降低分离纯化难度，固定的方式可分为物理法（包埋法、吸附法）和化学法（共价偶联法、交联法）","src":"资料"},{"subj":"880","term":"亚基","years":[],"def":"体内许多功能性蛋白质含有 2 条或 2 条以上的肽链，其中每一条多肽链都具有完整的三级结构，称为亚基。由亚基缔合而成的蛋白质具有四级结构"},{"subj":"880","term":"氧分数饱和度","years":[],"def":"即血红蛋白氧饱和度，是指血红蛋白与氧结合达到饱和程度的百分比值，其公式为：氧分数饱和度 = 氧合Hb/总Hb ×100%","src":"资料"},{"subj":"880","term":"抗原决定簇","years":[],"def":"抗原物质上能够刺激淋巴细胞产生应答，并与其产物特异反应的化学基团，也称为表位（epitope），大多存在于抗原物质的表面，一个天然抗原物质可能有多种和多个决定簇，因此一般抗原分子越大，决定簇的数目越多","src":"资料"},{"subj":"880","term":"盐溶","years":[],"def":"在蛋白质水溶液中，加入少量的中性盐，如硫酸铵等，会增加蛋白质分子表面的电荷，增强蛋白质分子与水分子的作用，从而使蛋白质在水溶液中的溶解度增大，这种现象称为\"盐溶\""},{"subj":"880","term":"酶的最适 pH","years":[],"def":"在某一特定 pH 时，酶促反应具有最大反应速率，高于或低于此值，反应速率均下降，通常称此 pH 值为酶的最适 pH 值，但酶的最适 pH 并不是一个常数，只是在一定的条件下才具意义","src":"资料"},{"subj":"880","term":"定向效应","years":[],"def":"指在酶活性部位中，催化基团与底物分子反应基团之间，形成了正确的定向排列，使分子间的反应按正确的方向相互作用，从而形成中间产物","src":"资料"},{"subj":"880","term":"酶原","years":[],"def":"有些酶，如参与消化的各种蛋白酶（如胃蛋白酶、胰蛋白酶、胰凝乳蛋白酶等），在最初合成和分泌时，由于活性中心未形成或未暴露，而没有催化活性，这种没有活性的酶的前体，被称为\"酶原\""},{"subj":"880","term":"Chargaff 规则","years":[],"def":"是关于 DNA 分子中碱基组成的规则，一、腺嘌呤与胸腺嘧啶的摩尔数总是相等（A=T）、鸟嘌呤的含量总是与胞嘧啶相等（G=C）；二、不同生物种属的 DNA 碱基组成不同；三、同一个体不同器官、不同组织的 DNA 具有相同的碱基组成","src":"资料"},{"subj":"880","term":"抗生素","years":[],"def":"是在低浓度下即可抑制或杀死病原体的小分子化学物质，广义的抗生素还包括一些抗肿瘤药、杀虫剂和除草剂等","src":"资料"},{"subj":"880","term":"顺式作用元件","years":[],"def":"是存在于基因旁侧序列中能影响基因表达的序列，包括启动子、增强子、调控序列和可诱导元件等，它们的作用是参与基因表达的调控。顺式作用元件本身不编码任何蛋白质，仅仅提供一个作用位点，要与反式作用因子相互作用而起作用。","src":"资料"},{"subj":"880","term":"反式作用因子","years":[],"def":"是指能直接或间接地识别或结合在各类顺式作用元件核心序列上参与调控靶基因转录效率的蛋白质，其本身对基因表达没有调控作用，只是阻断来自上、下游的调控效应。","src":"资料"},{"subj":"880","term":"核苷酸的从头合成和补救途径","years":[],"def":"体内嘌呤核苷酸的合成有两条途径，一是利用磷酸核糖、氨基酸、一碳单位及 CO₂ 等简单物质为原料合成嘌呤核苷酸的过程，称为从头合成，是体内的主要合成途径。二是利用体内游离嘌呤或嘌呤核苷，经简单反应过程生成嘌呤核苷酸的过程，称补救途径。","src":"资料"},{"subj":"880","term":"基因敲除","years":[],"def":"外源 DNA 与受体细胞基因组中序列相同或相近的基因发生同源重组，从而代替受体细胞基因组中的相同或相似的基因序列，整合入受体细胞的基因组中，产生基因的精确突变的过程","src":"资料"},{"subj":"880","term":"有意义链和反意义链","years":[],"def":"双链 DNA 中，不能进行转录的那一条链称为有意义链，也称为编码链；按照碱基配对原则指导 RNA 合成的那一条链称为反意义链，也称为模板链","src":"资料"},{"subj":"880","term":"自杀抑制作用","years":[],"def":"底物类似物经酶催化生成的产物变成了该酶的抑制剂","src":"资料"},{"subj":"880","term":"管家基因","years":[],"def":"是指所有细胞中均要表达的一类基因，其产物是对维持细胞基本生命活动所必需的，是一类始终保持着低水平甲基化并且一直处于活性转录状态的基因","src":"资料"},{"subj":"880","term":"氨基酸","years":[],"def":"是含有一个碱性氨基（-NH 2）和一个酸性羧基（-COOH）的有机化合物，氨基一般连在α- 碳上。氨基酸是蛋白质的构件分子。","src":"资料"},{"subj":"880","term":"必需氨基酸","years":[],"def":"指人体不能合成或合成数量不能满足机体需要，必需由膳食提供的氨基酸，包括：缬氨酸、亮氨酸、异亮氨酸、蛋氨酸（甲硫氨酸）、苯丙氨酸、色氨酸、苏氨酸、赖氨酸，婴幼儿还包括组氨酸","src":"资料"},{"subj":"880","term":"非必需氨基酸","years":[],"def":"指人（或其它脊椎动物）自己能由简单的前体合成，不需要从食物中获得的氨基酸。","src":"资料"},{"subj":"880","term":"茚三酮反应","years":[],"def":"在加热条件下，氨基酸或肽与茚三酮反应生成紫色（与脯氨酸及羟脯氨酸反应生成黄色）化合物的反应。","src":"资料"},{"subj":"880","term":"层析","years":[],"def":"按照在移动相和固定相（可以是气体或液体）之间的分配 比例将混合成分分开的技术。","src":"资料"},{"subj":"880","term":"离子交换层析","years":[],"def":"一种用离子交换树脂作支持剂的层析技术。","src":"资料"},{"subj":"880","term":"透析","years":[],"def":"利用蛋白质分子不能通过半透膜的性质，使蛋白质和其他小分子物质如无机盐、单糖等分开的一种分离纯化技术。","src":"资料"},{"subj":"880","term":"高压液相层析","years":[],"def":"使用颗粒极细的介质，在高压下分离蛋白质或其他分子混合物的层析技术。","src":"资料"},{"subj":"880","term":"凝胶电泳","years":[],"def":"以凝胶为介质，在电场作用下分离蛋白质或核酸的分离纯化技术。","src":"资料"},{"subj":"880","term":"SDS- 聚丙烯酰胺凝胶电泳","years":[],"def":"在去污剂十二烷基硫酸钠存在下的聚丙烯酰胺凝胶电泳。SDS-PAGE 只是按照分子的大小，而不是根据分子所带的电荷大小分离的。","src":"资料"},{"subj":"880","term":"等电聚焦电泳","years":[],"def":"是在具有 pH 梯度的介质中进行的，根据不同蛋白质具有不同的等电点，而将蛋白质进行分离的一种技术，同时，该技术也常用于蛋白质等电点的测定","src":"资料"},{"subj":"880","term":"双向电泳","years":[],"def":"等电聚焦电泳和 SDS-PAGE 的组合，即先进行等电聚焦电泳（按照 pI）分离，然后再进行 SDS-PAGE（按照分子大小分离）。经染色得到的电泳图是二维分布的蛋白质图，因此也称为“二维电泳。","src":"资料"},{"subj":"880","term":"Edman 降解","years":[],"def":"从多肽链游离的 N 末端测定氨基酸残基的序列的过程。N 末端氨基酸残基被苯异硫氰酸酯（PITC）修饰，然后从多肽链上切下修饰的残基，再经层析鉴定，余下的多肽链（少了一个残基）被回收再进行下一轮降解循环。","src":"资料"},{"subj":"880","term":"同源蛋白质","years":[],"def":"在不同生物体内行使相同或相似功能的蛋白质，例如血红蛋白。","src":"资料"},{"subj":"880","term":"构象","years":[],"def":"由于单键旋转引起的组成原子的不同排列。一种构象改变为另一种构象时，不要求共价键的断裂和重新形成。构象改变不会改变分子的光学活性。","src":"资料"},{"subj":"880","term":"蛋白质一级结构","years":[],"def":"指氨基酸在肽键中的排列顺序和二硫键的数目和位置。一级结构是最基本的结构，其氨基酸序列中贮存着蛋白质折叠的全部信息，因此 一级结构决定蛋白质的高级结构（二级结构、三级结构）","src":"资料"},{"subj":"880","term":"超二级结构","years":[],"def":"在蛋白质中，特别是球蛋白中，经常可以看到由若干相邻的二级结构单元组合在一起，彼此相互作用，形成有规则的，种类不多的二级结构组合或二级结构串，在各种蛋白质中充当三级结构的构件。分为 αα，βαβ，ββ 三种","src":"资料"},{"subj":"880","term":"结构域","years":[],"def":"多肽链在二级结构或超二级结构的基础上形成三级结构的局部折叠区，它是相对独立的紧密球状实体。","src":"资料"},{"subj":"880","term":"蛋白质三级结构","years":[],"def":"指一条多肽链在二级结构（超二级结构及结构域）的基础上，进一步的盘绕、折叠，从而产生特定的球状分子结构，即多肽链中所有原子的空间排布位置。维系三级结构的力有疏水作用力、氢键、盐键（静电作用力）、范德华力，此外二硫键在某些蛋白质中也起非常重要的作用","src":"资料"},{"subj":"880","term":"蛋白质四级结构","years":[],"def":"是由两条或者两条以上具有独立三级结构的亚基，通过一些非共价键结合成的多聚体。维系四级结构的力有疏水作用力、氢键、范德华力、盐键（静电作用力），具有四级结构的蛋白质可具有单体蛋白不具备的别构效应，如血红蛋白","src":"资料"},{"subj":"880","term":"α-螺旋","years":[],"def":"是蛋白质中常见的一种二级结构，肽链主链绕假想的中心轴盘旋成螺旋状，一般都是右手螺旋结构，螺旋是靠链内氢键维持的，即每个氨基酸残基的羰基氧与多肽链 C 端方向的第 4 个残基的酰胺氮形成氢键。在典型的右手α-螺旋结构中，螺距为 0.54nm，每一圈含有 3.6 个氨基酸残基，每个残基沿着螺旋的长轴上升 0.15nm","src":"资料"},{"subj":"880","term":"β-折叠","years":[],"def":"是蛋白质中常见的二级结构，是由伸展的多肽链组成的。折叠片的构象是通过一个肽键的羰基氧和位于同一个肽链或相邻肽链的另一个酰胺氢之间形成的氢键维持的，这些肽链可以平行排列，也可以是反平行排列","src":"资料"},{"subj":"880","term":"疏水相互作用","years":[],"def":"水介质中球状蛋白质的折叠总是倾向于把疏水残基埋藏在分子的内部的现象。","src":"资料"},{"subj":"880","term":"蛋白质变性","years":[],"def":"天然蛋白质受到某些物理因素如加热、紫外线照射、高温和表面张力等或化学因素如有机溶剂、脲、胍、酸、碱等的影响时，生物活性丧失，溶解度降低，不对称程度增高以及其他的物理化学常数发生改变，这种过程称蛋白质变性。其实质是次级键被破坏，但一级结构仍完好。 DONE 880名解_01 页=12 题=115 字符数=13518","src":"资料"},{"subj":"880","term":"蛋白质的三维结构","years":[],"def":"蛋白质分子所有原子和基团在三维空间结构的构象及走向。","src":"资料"},{"subj":"880","term":"肌红蛋白","years":[],"def":"是由一条肽链和一个血红素辅基组成的结合蛋白，是肌肉内储存氧的蛋白质，它的氧饱和曲线为双曲线型。","src":"资料"},{"subj":"880","term":"复性","years":[],"def":"当变性因素除去后，变性的生物大分子恢复成具有生物活性的天然构象的现象。","src":"资料"},{"subj":"880","term":"血红蛋白","years":[],"def":"是由含有血红素辅基的 4 个亚基组成的结合蛋白。血红蛋白负责将氧由肺运输到外周组织，它的氧饱和曲线为 S 型。","src":"资料"},{"subj":"880","term":"酶","years":[],"def":"由活细胞产生的在细胞内、外一定条件下，都能起催化作用，具有极高的催化效率的高度专一性的生物大分子。它使错综复杂的生化反应变得顺利和迅速。","src":"资料"},{"subj":"880","term":"活性部位","years":[],"def":"酶中含有底物结合部位和参与催化底物转化为产物的氨基酸残基部分。活性部位通常位于蛋白质的结构域或亚基之间的裂隙或是蛋白质表面的凹陷部位，通常都是由在一级结构上相距较远，但在三维空间上靠得很近的一些氨基酸残基组成。","src":"资料"},{"subj":"880","term":"酸 - 碱催化","years":[],"def":"质子转移加速反应的催化作用。","src":"资料"},{"subj":"880","term":"共价催化","years":[],"def":"一个底物或底物的一部分与催化剂形成共价键，然后被转移给第二个底物。许多酶催化的基团转移反应都是通过共价催化方式进行的。","src":"资料"},{"subj":"880","term":"靠近效应","years":[],"def":"非酶促催化反应或酶促反应速度的增加是由于底物靠近活性部位，使得活性部位处反应剂有效浓度增大的结果，这将导致更频繁地形成过度态。","src":"资料"},{"subj":"880","term":"寡聚蛋白质","years":[],"def":"两条或两条以上的具三级结构的多肽链组成的蛋白质。","src":"资料"},{"subj":"880","term":"米氏方程","years":[],"def":"表示一个酶促反应的起始速度（u）与底物浓度（[s]）关系的速度方程：u = u max [s]/(Km+[s])","src":"资料"},{"subj":"880","term":"米氏常数","years":[],"def":"对于一个给定的反应，酶促反应的起始速度（u0）达到最大反应速度（u max）一半时的底物浓度。","src":"资料"},{"subj":"880","term":"有氧氧化","years":[],"def":"葡萄糖在有氧条件下彻底氧化成 H₂O 和 CO₂ 并放出大量能量的过程。","src":"资料"},{"subj":"880","term":"双倒数作图","years":[],"def":"又称为 Lineweaver_Burk 作图。一个酶促反应的速度的倒数（1/V）对底物浓度的倒数（1/LSF）的作图。 x 和 y 轴上的截距分别代表米氏常数和最大反应速度的倒数。","src":"资料"},{"subj":"880","term":"非竞争性抑制作用","years":[],"def":"抑制剂和底物与酶结合在不同位点，不存在竞争性结合，因此是一种抑制剂不仅与游离酶结合，也可以与酶 - 底物复合物结合的酶促反应抑制作用，这种抑制使 Km 不变，而 V max 变小。","src":"资料"},{"subj":"880","term":"反竞争性抑制作用","years":[],"def":"抑制剂必须在底物与酶结构后才能结合在酶上，因此是一种抑制剂只与酶 - 底物复合物结合而不与游离的酶结合的酶促反应抑制作用。这种抑制使 Km 和 V max 都变小，但 V max/Km 不变。","src":"资料"},{"subj":"880","term":"调节酶","years":[],"def":"位于一个或多个代谢途径内的一个关键部位的酶，它的活性根据代谢的需要而增加或降低。","src":"资料"},{"subj":"880","term":"别构酶","years":[],"def":"活性受结合在活性部位以外的部位的其它分子调节的酶。","src":"资料"},{"subj":"880","term":"别构调节酶 / 剂","years":[],"def":"称为别构效应物。结合在别构酶的调节部位，调节酶催化活性的生物分子。别构调节物可以是是激活剂，也可以是抑制剂。","src":"资料"},{"subj":"880","term":"维生素","years":[],"def":"维持细胞正常功能所必需的需要量很小、机体不能合成或合成量很小，需由食物中供给的一类小分子有机化合物。","src":"资料"},{"subj":"880","term":"水溶性维生素","years":[],"def":"一类能溶于水的有机营养分子。其中包括在酶的催化中起着重要作用的 B 族维生素、抗坏血酸（维生素 C）以及硫辛酸。","src":"资料"},{"subj":"880","term":"脂溶性维生素","years":[],"def":"由长的碳氢链或稠环组成的聚戊二烯化合物。脂溶性维生素包括 A ， D ， E ，和 K，这类维生素能被贮存于动物的肝脏中。","src":"资料"},{"subj":"880","term":"辅酶","years":[],"def":"某些酶在发挥催化作用时所需的一类辅助因子，其成分中往往含有维生素。辅酶与酶结合松散，可以通过透析除去。","src":"资料"},{"subj":"880","term":"辅基","years":[],"def":"是与酶蛋白质共价结合的金属离子或一类有机化合物，用透析法不能除去。辅基在整个酶促反应过程中始终与酶的特定部位结合。","src":"资料"},{"subj":"880","term":"硫胺素焦磷酸","years":[],"def":"是维生素 B1 的辅酶形式，参与转醛基反应。","src":"资料"},{"subj":"880","term":"黄素腺嘌呤二核苷酸","years":[],"def":"是某些氧化还原反应的辅酶，含有核黄素。","src":"资料"},{"subj":"880","term":"磷酸吡哆醛","years":[],"def":"是维生素 B6 （吡哆醇）的衍生物，是转氨酶，脱羧酶和消旋酶的酶。","src":"资料"},{"subj":"880","term":"生物素","years":[],"def":"参与脱羧反应的一种酶的辅助因子。","src":"资料"},{"subj":"880","term":"辅酶 A","years":[],"def":"一种含有泛酸的辅酶，在某些酶促反应中作为酰基的载体。","src":"资料"},{"subj":"880","term":"转氨酶","years":[],"def":"称为氨基转移酶，在该酶的催化下，一个α - 氨基酸的氨基可转移给另一个α - 酮酸。","src":"资料"},{"subj":"880","term":"糖类","years":[],"def":"多羟醛或多羟酮及其缩聚物和某些衍生物的总称。"},{"subj":"880","term":"变旋","years":[],"def":"一种具旋光性的物质的溶液，经放置，其旋光率发生改变的现象。","src":"资料"},{"subj":"880","term":"糖苷","years":[],"def":"单糖半缩醛羟基与另一个分子的羟基，胺基或巯基缩合形成的含糖衍生物。","src":"资料"},{"subj":"880","term":"糖蛋白","years":[],"def":"含有共价连接的葡萄糖残基的蛋白质。","src":"资料"},{"subj":"880","term":"糖胺聚糖","years":[],"def":"由含己糖醛酸和己糖胺成分的重复二糖单位构成。","src":"资料"},{"subj":"880","term":"蛋白聚糖","years":[],"def":"一类特殊的糖蛋白，由一条或多条糖胺聚糖和一个核心蛋白共价连接而成。","src":"资料"},{"subj":"880","term":"三脂酰甘油","years":[],"def":"称为甘油三酯。一种含有与甘油酯化的三个脂酰基的酯。脂肪和油是三脂酰甘油的混合物。","src":"资料"},{"subj":"880","term":"生物膜","years":[],"def":"是细胞、细胞器和其他环境接界的所有膜结构的总 称，生物膜是镶嵌有蛋白质和糖类（统称糖蛋白）的磷脂双分子层，起着划分和分隔细胞和细胞器作用，其上还含有大量的酶结合位点，是许多能量转化和细胞内通讯有关的重要部位","src":"资料"},{"subj":"880","term":"内在膜蛋白","years":[],"def":"插入脂双层的疏水核和完全跨越脂双层的膜蛋白。","src":"资料"},{"subj":"880","term":"外周膜蛋白","years":[],"def":"通过与膜脂的极性头部或内在的膜蛋白的离子相互作用和形成氢键与膜的内或外表面弱结合的膜蛋白。","src":"资料"},{"subj":"880","term":"流动镶嵌模型","years":[],"def":"针对生物膜的结构提出的一种模型。在这个模型中，生物膜被描述成镶嵌有蛋白质的流体脂双层，脂双层在结构和功能上都表现出不对称性。有的蛋白质“镶”在脂双层表面，有的则部分或全部嵌入其内部，有的则横跨整个膜。另外脂和膜蛋白可以进行横向扩散。","src":"资料"},{"subj":"880","term":"通透系数","years":[],"def":"是离子或小分子扩散过脂双层膜能力的一种量度。通透系数大小与这些离子或分子在非极性溶液中的溶解度成比例。","src":"资料"},{"subj":"880","term":"通道蛋白","years":[],"def":"是带有中央水相通道的内在膜蛋白，它可以使大小适合的离子或分子从膜的任一方向穿过膜。","src":"资料"},{"subj":"880","term":"孔蛋白","years":[],"def":"其含意与膜通道蛋白类似，只是该术语常用于细菌。","src":"资料"},{"subj":"880","term":"被动转运","years":[],"def":"是小分子物质顺浓度梯度，不消耗能量所进行的跨膜运输方式，其运输动力来自质膜内、外侧物质的浓度梯度势能或电位差。被动运输可分为简单扩散和协助扩散，其中协助扩散还需要载体蛋白的参与","src":"资料"},{"subj":"880","term":"主动转运","years":[],"def":"指物质逆浓度梯度或电化学梯度跨膜转运的过程。这一过程的进行需要能量的供给和载体蛋白的协助，根据能量来源的不同，可将主动运输分为：一级主动运输（依靠水解 ATP 供能）、二级主动运输（利用浓度梯度或电化学梯度提供能量，也称协同运输）","src":"资料"},{"subj":"880","term":"协同运输","years":[],"def":"两种不同溶质的跨膜的偶联转运。可以通过一个转运蛋白进行同一方向（同向转运）或反方向（反向转运）转运。其能量来自电化学梯度，属于次级主动运输","src":"资料"},{"subj":"880","term":"胞吞","years":[],"def":"物质被质膜吞入并以膜衍生出的脂囊泡形成（物质在囊泡内）被带入到细胞内的过程。","src":"资料"},{"subj":"880","term":"核苷","years":[],"def":"是嘌呤或嘧啶碱通过共价键与戊糖连接组成的化合物。核糖与碱基一般都是由糖的异头碳与嘧啶的 N-1 或嘌呤的 N-9 之间形成的β-N- 糖键连接。","src":"资料"},{"subj":"880","term":"核苷酸","years":[],"def":"核苷的戊糖成分中的羟基磷酸化形成的化合物。","src":"资料"},{"subj":"880","term":"cAMP","years":[],"def":"3',5'- 环腺苷酸，是细胞内的第二信使，由于某部些激素或 其它分子信号刺激激活腺苷酸环化酶催化 ATP 环化形成的。","src":"资料"},{"subj":"880","term":"磷酸二酯键","years":[],"def":"一种化学基团，指一分子磷酸与两个醇（羟基）酯化形成的两个酯键。该酯键成了两个醇之间的桥梁。例如一个核苷的 3'羟基与另一个核苷的 5'羟基与同一分子磷酸酯化，就形成了一个磷酸二酯键。","src":"资料"},{"subj":"880","term":"脱氧核糖核酸","years":[],"def":"含有特殊脱氧核糖核苷酸序列的聚脱氧核苷酸，脱氧核苷酸之间是是通过 3',5'- 磷酸二酯键连接的。 DNA 是遗传信息的载体。","src":"资料"},{"subj":"880","term":"核糖核酸","years":[],"def":"通过 3',5'- 磷酸二酯键连接形成的特殊核糖核苷酸序列的聚核糖核苷酸。","src":"资料"},{"subj":"880","term":"转化","years":[],"def":"一个外源 DNA 通过某种途径导入一个宿主菌，引起该菌的遗传特性改变的作用。","src":"资料"},{"subj":"880","term":"转导","years":[],"def":"借助于病毒载体，遗传信息从一个细胞转移到另一个细胞。","src":"资料"},{"subj":"880","term":"碱基对","years":[],"def":"通过碱基之间氢键配对的核酸链中的两个核苷酸，例如 A 与 T 或 U，以及 G 与 C 配对 。","src":"资料"},{"subj":"880","term":"DNA 的双螺旋","years":[],"def":"两条反向平行的多核苷酸链相互缠绕形成一个右手的双螺旋结构。碱基位于双螺旋内侧，磷酸与糖基在外侧，通过磷酸二酯键相连，形成核酸的骨架.双螺旋的直径为 2nm ，碱基堆积距离是 0.34nm ，两核苷酸之间的夹角是 36°，每对螺旋由 10 对碱基组成，碱基按 A=T ， G-C 配对互补，彼此以氢键相联系。维持 DNA 双螺旋结构的稳定的力主要是碱基堆积力。","src":"资料"},{"subj":"880","term":"DNA 变性","years":[],"def":"在某些理化因素，如强酸强碱、高温、变性剂等的 作用下， DNA 双链的互补碱基对之间的氢键断裂，使 DNA 双螺旋的两条互补链松散而成为单链，从而导致 DNA 的理化性质及生物学性质发生改变，这种现象称 DNA 的变性。","src":"资料"},{"subj":"880","term":"DNA 复性","years":[],"def":"变性的 DNA 在适当的条件下又可使两条分开的链重新缔合成为双螺旋结构的过程。","src":"资料"},{"subj":"880","term":"增色效应 hyperchromic effect","years":[],"def":"当 DNA 变性后，对 260nm 处紫外光光吸收度增加的现象。","src":"资料"},{"subj":"880","term":"核酸内切酶","years":[],"def":"核糖核酸酶和脱氧核糖核酸酶中能够水解核酸分子内磷酸二酯键的酶。","src":"资料"},{"subj":"880","term":"核酸外切酶","years":[],"def":"从核酸链的一端逐个水解核苷酸的酶。","src":"资料"},{"subj":"880","term":"限制性内切酶","years":[],"def":"一种在特殊核苷酸序列处水解双链 DNA 的内切酶。Ⅰ型限制性内切酶既能催化宿主 DNA 的甲基化，又催化非甲基化的 DNA 的水解，而Ⅱ型限制性内切酶只催化非甲基化的 DNA 的水解。Ⅲ型限制性内切酶同时具有修饰及切割的作用","src":"资料"},{"subj":"880","term":"重组 DNA 技术","years":[],"def":"也称之为基因工程（genomic engineering）。利用限制性内切酶和载体，按照预先设计的要求，将一种生物的某种目的基因和载体 DNA 重组后转入另一生物细胞中进行复制、转录和表达的技术。","src":"资料"},{"subj":"880","term":"基因","years":[],"def":"泛指被转录的一个 DNA 片段。在某些情况下，基因常用来指编码一个功能蛋白或 RNA 片段。","src":"资料"},{"subj":"880","term":"新陈代谢","years":[],"def":"生物体与外界环境不断进行的物质和能量交换过程。","src":"资料"},{"subj":"880","term":"糖醛酸途径","years":[],"def":"从葡萄糖 -6- 磷酸或葡萄糖 -1- 磷酸开始，经 UDP- 葡萄糖醛酸生成葡萄糖醛酸和抗坏血酸的途径。但只有在植物和那些可以合成抗坏血酸的动物体内，才可以通过该途径合成维生素 C 。","src":"资料"},{"subj":"880","term":"呼吸电子传递链 /呼吸链","years":[],"def":"需氧细胞内代谢物被脱氢酶脱氢，经一系列电子传递体（递氢体 + 递电子体）传递作用，最终将质子和电子传递给被激活的氧原子，从而生成 H₂O，并放出能量的全过程","src":"资料"},{"subj":"880","term":"生物固氮作用","years":[],"def":"大气中的氮被还原为氨的过程。生物固氮只发生在少数的细菌和藻类中。","src":"资料"},{"subj":"880","term":"尿素循环","years":[],"def":"是将含氮化合物分解产生的氨（游离氨和天冬氨酸的氮）转变为尿素的过程。由于其中间产物——鸟氨酸可循环再生，因此尿素循环也称鸟氨酸循环。此循环是发生在脊椎动物的肝脏中的一个代谢循环，也是人体中主要的排氨方式","src":"资料"},{"subj":"880","term":"脱氨","years":[],"def":"在酶的催化下从生物分子（氨基酸或核苷酸）中除去氨基的过程。","src":"资料"},{"subj":"880","term":"氧化脱氨","years":[],"def":"α - 氨基酸在酶的催化下脱氨生成相应的α - 酮酸的过程。氧化脱氨实际上包括氧化和脱氨两个步骤。（脱氨和水解）","src":"资料"},{"subj":"880","term":"转氨","years":[],"def":"一个α - 氨基酸的α - 氨基借助转氨酶的催化作用转移到一个α - 酮酸的过程。在体内通常以α - 酮戊二酸作为氨的受体，而形成谷氨酸","src":"资料"},{"subj":"880","term":"生糖氨基酸","years":[],"def":"降解可生成能作为糖异生前体的分子，例如丙酮酸或柠檬酸循环中间代谢物的氨基酸。","src":"资料"},{"subj":"880","term":"生酮氨基酸","years":[],"def":"降解可生成乙酰 CoA 或酮体的氨基酸。","src":"资料"},{"subj":"880","term":"核苷酸磷酸化酶","years":[],"def":"能分解核苷生成含氮碱基和戊糖的磷酸酯的酶。","src":"资料"},{"subj":"880","term":"核苷水解酶","years":[],"def":"能分解核苷生成含氮碱基和戊糖的酶。","src":"资料"},{"subj":"880","term":"从头合成","years":[],"def":"生物体内用简单的前体物质合成生物分子的途径，例如核苷酸的从头合成。","src":"资料"},{"subj":"880","term":"激素","years":[],"def":"一类由内分泌器官合成的微量的化学物质，它由血液运输到靶组织起着信使的作用，调节靶组织（或器官）的功能。","src":"资料"},{"subj":"880","term":"激素受体","years":[],"def":"位于细胞表面或细胞内，结合特异激素并引发细胞响应的蛋白质。","src":"资料"},{"subj":"880","term":"级联放大","years":[],"def":"在体内的不同部位，通过一系列酶的酶促反应来传递一个信息，并且初始信息在传递到系列反应的最后时，信号得到放大，这样的一个系列叫作级联系统。","src":"资料"},{"subj":"880","term":"G 蛋白","years":[],"def":"在细胞内信号传导途径中起着重要作用的 GTP 结合蛋白，具有内源 GTP 酶活性，由α，β，γ三个不同亚基组成。激素与激素受体结合诱导 GTP 跟 G 蛋白结合的 GDP 进行交换，结果激活位于信号传导途径中下游的腺苷酸环化酶。 G 蛋白将细胞外的第一信使肾上腺素等激素和细胞内的腺苷酸环化酶催化的腺苷酸环化生成的第二信使 cAMP 联系起来。","src":"资料"},{"subj":"880","term":"半保留复制","years":[],"def":"DNA 在复制时，首先两条链之间的氢键断裂，两条链分开，然后以每一条链分别做模板，各自合成一条新的 DNA 链，这样合成的子代 DNA 中一条链来自亲代 DNA，另一条链是新合成的，这种复制方式称为半保留复制","src":"资料"},{"subj":"880","term":"DNA 聚合酶","years":[],"def":"是一种以 DNA 为模板，以四种 dNTP 为原料，借助引物，可催化核苷酸残基加到已存在的聚核苷酸 3'末端反应的酶。某些 DNA 聚合酶具有外切核酸酶的活性，可用来校正新合成的核苷酸的序列。","src":"资料"},{"subj":"880","term":"前导链","years":[],"def":"与复制叉移动的方向一致，通过连续的 5'-3'聚合合成的新的 DNA 链。","src":"资料"},{"subj":"880","term":"滞后链","years":[],"def":"与复制叉移动的方向相反，通过不连续的 5'-3'聚合，先合成冈崎片段，再通过 DNA 连接酶连接成完整的新的 DNA 链。","src":"资料"},{"subj":"880","term":"复制体","years":[],"def":"一种多蛋白复合体，包含 DNA 聚合酶，引发酶，解旋酶，单链结合蛋白和其它辅助因子。复制体位于每个复制叉处进行细菌染色体 DNA 复制的聚合反应。","src":"资料"},{"subj":"880","term":"单链结合蛋白","years":[],"def":"一种与单链 DNA 结合紧密的蛋白，它的结构可以防止复制叉处单链 DNA 本身重新折叠回双链区，但其本身不具备解链活性","src":"资料"},{"subj":"880","term":"逆转录酶","years":[],"def":"一种催化以 RNA 为模板合成 DNA 的 DNA 聚合酶，具有 RNA 指导的 DNA 合成，水解 RNA 和 DNA 指导的 DNA 合成的三种酶活性。","src":"资料"},{"subj":"880","term":"互补 DNA","years":[],"def":"通过逆转录酶由 mRNA 模板合成的双链 DNA 。","src":"资料"},{"subj":"880","term":"聚合酶链式反应","years":[],"def":"PCR 是一种体外扩增特定 DNA 的技术。其原理是，根据待扩增 DNA 片段两端的核苷酸序列，设计并人工合成两个分别与 DNA 片段两端互补的寡核苷酸引物，在有过量的引物、过量的底物（dNTP）、耐热的 DNA 聚合酶（Taq DNA 聚合酶）以及模板的反应体系中，经过高温变性（DNA 解链）、低温退火（引物与模板 DNA 结合）和适温延伸（DNA 合成）三个阶段的循环周期反应，使模板 DNA 以几何级数扩增","src":"资料"},{"subj":"880","term":"遗传学中心法则","years":[],"def":"描述从一个基因到相应蛋白质的信息流的途径。遗传信息贮存在 DNA 中， DNA 被复制传给子代细胞，信息被拷贝或由 DNA 转 录成 RNA ，然后 RNA 翻译成多肽。不过，由于逆转录酶的反应，也可以以 RNA 为模板合成 DNA 。","src":"资料"},{"subj":"880","term":"转录","years":[],"def":"在由 RNA 聚合酶和辅助因子组成的转录复合物的催化下，从双链 DNA 分子中拷贝生物信息生成一条 RNA 链的过程。","src":"资料"},{"subj":"880","term":"模板链","years":[],"def":"可作为模板转录为 RNA 的那条链该链与转录的 RNA 碱基互补（A-U ， G-C）。在转录过程中，RNA 聚合酶与模板链结合，并沿着模板链的 3'→5'方向移动，按照 5'→3'方向催化 RNA 的合成。","src":"资料"},{"subj":"880","term":"编码链","years":[],"def":"双链 DNA 中，不能进行转录的那一条 DNA 链，该链的核苷酸序列与转录生成的 RNA 的序列一致（在 RNA 中是以 U 取代了 DNA 中的 T）。","src":"资料"},{"subj":"880","term":"核心酶","years":[],"def":"大肠杆菌的 RNA 聚合酶全酶由 5 个亚基组成（α 2β'βωσ），没有 σ 基的酶叫核心酶。核心酶只能使已开始合成的 RNA 链延长，但不具有起始合成 RNA 的能力，必须加入 σ 基才表现出全部聚合酶的活性。","src":"资料"},{"subj":"880","term":"RNA 聚合酶","years":[],"def":"以一条 DNA 链或 RNA 为模板催化由核苷 -5'- 三磷酸合成 RNA 的酶。","src":"资料"},{"subj":"880","term":"内含子","years":[],"def":"是一个基因中非编码 DNA 片段，它将相邻的外显子分割开来。即内含子是阻断基因线性表达的序列","src":"资料"},{"subj":"880","term":"外显子","years":[],"def":"是真核生物基因的一部分，它在剪接后仍会被保存下来，并可在蛋白质生物合成过程中表达为蛋白质","src":"资料"},{"subj":"880","term":"终止因子","years":[],"def":"协助 RNA 聚合酶识别终止信号的的辅助因子（蛋白质）。","src":"资料"},{"subj":"880","term":"核酶","years":[],"def":"核酶是一类具有催化功能的 RNA 分子，可通过催化靶位点 RNA 链中磷酸二酯键的断裂，特异性地剪切底物 RNA 分子，从而阻断基因的表达。可分为剪切型核酶和剪接型核酶","src":"资料"},{"subj":"880","term":"翻译","years":[],"def":"在蛋白质合成期间，将存在于 mRNA 上代表一个多肽的核苷酸残基序列转换为多肽链氨基酸残基序列的过程。","src":"资料"},{"subj":"880","term":"遗传密码","years":[],"def":"核酸中的核苷酸残基序列与蛋白质中的氨基酸残基序列 之间的对应关系。；连续的 3 个核苷酸残基序列为一个密码子，特指一个氨基酸。标准的遗传密码是由 64 个密码子组成的，几乎为所有生物通用。","src":"资料"},{"subj":"880","term":"起始密码子","years":[],"def":"指定蛋白质合成起始位点的密码子。最常见的起始密码子是蛋氨酸密码: AUG 。","src":"资料"},{"subj":"880","term":"终止密码子","years":[],"def":"任何 tRNA 分子都不能正常识别的，但可被特殊的蛋白结合并引起新合成的肽链从翻译机器上释放的密码子。存在三个终止密码子：UAG，UAA 和 UGA 。","src":"资料"},{"subj":"880","term":"密码子","years":[],"def":"mRNA 上每 3 个核苷酸翻译成多肽链上的一个氨基酸，这 3 个核苷酸就成为一个密码子（三联子密码）。mRNA 的三联密码子可与 tRNA 的反密码子互补，经其解读后将核酸序列信息转换成氨基酸序列。","src":"资料"},{"subj":"880","term":"反密码子","years":[],"def":"tRNA 分子的反密码子环上的三联体核苷酸残基序列。在翻译期间，反密码子与 mRNA 中的互补密码子结合。","src":"资料"},{"subj":"880","term":"简并密码子","years":[],"def":"也称为同义密码子。是指编码相同的氨基酸的几个不同的密码子。","src":"资料"},{"subj":"880","term":"SD 序列","years":[],"def":"是一段富含嘌呤的短核苷酸（4-7bp）保守序列，一般位于原核生物 mRNA 起始密码子 AUG 的上游 7-12（5-10）个碱基处，可与核糖体小亚基 16S rRNA 3'端的序列互补结合，可将 mRNA 的起始密码子 AUG 置于核糖体的适当位置，以便起始翻译作用，因此 SD 序列在翻译的正确起始和起始效率的调控中起重要作用，1974 年由 J.Shine 和 L.Dalgarno 发现，故命名为“SD 序列”","src":"资料"},{"subj":"880","term":"信号肽","years":[],"def":"是分泌蛋白新生肽链 N 端的一段疏水性氨基酸残基组成的肽段，可引导蛋白质进入内质网，一般在蛋白质进入内质网不久后便被酶切除掉","src":"资料"},{"subj":"880","term":"转录因子","years":[],"def":"是一类能识别并结合转录起始位点的上游序列或远端增强子元件，通过 DNA-蛋白质相互作用而调节转录活性，从而保证目的基因以特定的强度，在特定的时间与空间表达的蛋白质分子。包括转录激活因子和转录阻遏因子","src":"资料"},{"subj":"880","term":"操纵因子","years":[],"def":"与特定阻遏蛋白相互作用，从而调控一个基因或一组基因表达的 DNA 区。","src":"资料"},{"subj":"880","term":"结构基因","years":[],"def":"编码一个蛋白质或一个 RNA 的基因。","src":"资料"},{"subj":"880","term":"阻遏物","years":[],"def":"与一个基因的调控序列或操纵基因结合以阻止该基因转录的一类蛋白质。","src":"资料"},{"subj":"880","term":"脂肪动员","years":[],"def":"贮存在脂肪细胞中的甘油三酯中激素敏感脂肪酶（HSL）的催化下水解并释放出脂肪酸，供给全身各组织细胞摄取利用的过程。","src":"资料"},{"subj":"880","term":"α-氧化","years":[],"def":"脂肪酸在微粒体中由单加氧酶和脱羧酶催化生成α - 羟脂肪酸或少一个碳原子的脂肪酸的过程。","src":"资料"},{"subj":"880","term":"三羧酸循环","years":[],"def":"简称 TCA 循环，是由 4C 原子的草酰乙酸和 2C 原子的乙酰 CoA 缩合生成 6C 原子的柠檬酸，而后经四次脱氢、2 次脱羧等一系列反应，使乙酰基彻底氧化分解，生成 CO₂ 和还原型物质，最终以草酰乙酸的再生为结束的过程，由于循环中首先生成含有三个羧基的柠檬酸，因此称为“三羧酸循环”或“柠檬酸循环”","src":"资料"},{"subj":"880","term":"DNA 探针","years":[],"def":"被 ³²P 、 ³⁵S 或生物素标记单链末端或全链的一小段多聚单链核苷酸。","src":"资料"},{"subj":"880","term":"酶的专一性","years":[],"def":"酶对催化的反应和反应物有严格的选择性，其往往只能催一种或一类反应，作用于一种或一类物质。包括结构专一性和立体异构专一性（旋光异构专一性 + 几何异构专一性）。","src":"资料"},{"subj":"880","term":"多酶体系","years":[],"def":"是由几种酶彼此嵌合形成的复合体。它有利于一系列反应的连续进行。","src":"资料"},{"subj":"880","term":"逆向转录","years":[],"def":"在逆转录酶作用下，以 RNA 为模板，按照 RNA 中的核苷酸顺序合成 DNA ，这与通常转录过程中遗传信息流从 DNA 到 RNA 的方向相反。","src":"资料"},{"subj":"880","term":"不对称转录","years":[],"def":"转录通常只在 DNA 的任一条链上进行。","src":"资料"},{"subj":"880","term":"戊糖磷酸途径","years":[],"def":"葡萄糖在细胞质内直接氧化分解，并以戊糖磷酸为重要中间产物的有氧呼吸途径。又称己糖单磷酸途径（HMP）。是体内产生核糖和还原力（NADPH）的重要途径","src":"资料"},{"subj":"880","term":"糖异生作用","years":[],"def":"生物体中多种非糖物质（乳酸、丙酮酸、生糖氨基酸及甘油）转变为糖的过程。人体内，糖异生主要发生于肝和肾脏中，用于补充血糖、维持血糖水平的稳定","src":"资料"},{"subj":"880","term":"生物氧化","years":[],"def":"糖、脂肪、蛋白质等物质在生物体内通过酶的催化，实现的一系列释放能量的化学反应过程。","src":"资料"},{"subj":"880","term":"底物水平磷酸化","years":[],"def":"ATP 的形成直接与一中间代谢物上的磷酸基团的转移相偶联的作用。","src":"资料"},{"subj":"880","term":"P/O 比","years":[],"def":"在氧化磷酸化中，一对电子呼吸链传递至氧时所产生的 ATP 分子数，即每消耗 1mol 氧原子产生 ATP 的摩尔数。","src":"资料"},{"subj":"880","term":"反馈调节","years":[],"def":"指反应体系中的某些中间产物或终产物对其前面某一步反应速度的影响。使反应加速的物质称为正效应物，使反应速度受到抑制的物质称为负效应物","src":"资料"},{"subj":"880","term":"温度系数","years":[],"def":"表示生物体内的生化反应与温度关系的指标，指温度每升高 10 ℃ 呼吸速率所增加的倍数。其关系式为： Q 10 =(t+10)℃ 时的速率 /t ℃ 时的速率。","src":"资料"},{"subj":"880","term":"乳酸循环","years":[],"def":"肌肉缺氧条件下产生大量乳酸，大部分经血运到肝脏，通过糖异生作用生成葡萄糖补充血糖，血糖可再被肌肉利用，这样形成的循环称乳酸循环。","src":"资料"},{"subj":"880","term":"肽平面","years":[],"def":"由于肽键具有部分双键性质，不能自由旋转，所以连接在肽键两端的基团处于一个平面上，这个平面称为肽平面。","src":"资料"},{"subj":"880","term":"联合脱氨基作用","years":[],"def":"许多氨基酸不能直接进行氧化脱氨基作用，但可以和α - 酮戊二酸进行转氨基作用，生成相应的α - 酮酸和谷氨酸。谷氨酸可在谷氨酸脱氢酶的作用下进行氧化脱氨基作用，又生成α - 酮戊二酸，并放出氨，谷氨酸脱出的氨实际来自α - 酮戊二酸进行转氨基作用的氨基酸。可见，转氨基作用与谷氨酸氧化脱氨作用联合作用，此过程称氨基酸的联合脱氨基作用。凡能与α - 酮戊二酸进行转氨基作用的氨基酸，都可以通过联合脱氨基作用分解为α - 酮酸和氨，所以这种作用是谷氨酸以外的多种氨基酸脱氨基的主要方式。","src":"资料"},{"subj":"880","term":"谷胱甘肽","years":[],"def":"是由谷氨酸、半胱氨酸和甘氨酸组成的三肽。半胱氨酸的巯基是该化合物的主要功能基团。 GSH 的巯基具有还原性，可作为体内重要的还原剂保护体内蛋白质或酶分子中巯基免被氧化，使蛋白质或酶处于活性状态。","src":"资料"},{"subj":"880","term":"脂肪酸的 β-氧化","years":[],"def":"长链脂肪酸降解首先在邻近羧基的第二个 C 原子（β位）开始脱氢氧化后，经一系列反应逐步氧化成乙酰 CoA 的过程，由于氧化作用是从β-C 开始的，故称β - 氧化。","src":"资料"},{"subj":"880","term":"粘性末端","years":[],"def":"当一种限制性内切酶在一个特异性的碱基序列处切断 DNA 时，就可在切口处留下几个未配对的核苷酸，叫做粘性末端。 DONE 880名解_02 页=12 题=163 字符数=14780","src":"资料"},{"subj":"880","term":"DNA 半保留半不连续复制","years":[],"def":"DNA 复制时子链双链中有一条链来源于母链，故称半保留复制。以 DNA 母链双链为模板合成子链时，其中一条子链的合成是不连续的，而另一条链的合成是连续的，故称半不连续复制，合称半保留半不连续复制。","src":"资料"},{"subj":"880","term":"共价修饰调节","years":[],"def":"酶蛋白分子中的某些基团可以在其他酶的催化下发生共价修饰，从而导致酶活性的改变，称为共价修饰调节。其特点是：①酶以两种不同修饰和不同活性的形式存在；②有共价键的变化；③受其他调节因素的影响（如激素）；④一般为耗能过程；⑤存在放大效应。","src":"资料"},{"subj":"880","term":"寡聚酶","years":[],"def":"有几个或多个亚基组成的酶。其中亚基可以相同，也可以不同，亚基间以共价键结合，容易为酸碱及高浓度的盐或其他的变性剂分离。","src":"资料"},{"subj":"880","term":"增强子","years":[],"def":"位于真核基因中远离转录起始点，能明显增强启动子转录效率的特殊 DNA 序列。它可位于被增强的转录基因的上游或下游，也可相距靶基因较远。","src":"资料"},{"subj":"880","term":"C3 植物","years":[],"def":"植物通过还原型戊糖磷酸循环而进行 CO2 固定的植物。"},{"subj":"880","term":"同促效应","years":[],"def":"别构效应可分为同促效应和异促效应两类。当底物作为效应物与酶结合时，该催化部位构象发生变化，并对其他催化部位产生调节效应，即为“同促效应” DONE 880名解_03 页=1 题=6 字符数=428","src":"资料"},{"subj":"631","term":"穿梭载体","years":["10"],"def":"是人工构建的一类具有两种不同复制起点和选择记号，因而可以在两种不同寄主细胞中存活和复制的（质粒）载体"},{"subj":"631","term":"染色体步移","years":["10"],"def":"利用已知的基因或分子标记来筛选大片段基因组文库获得阳性克隆，如此得到的阳性克隆是\"一步克隆\"，再利用获得的克隆作探针对文库进行第二次杂交，得到与探针具有重复序列的阳性克隆称为\"二次克隆\"，如此反复即可取到需要的克隆，获得目的基因"},{"subj":"631","term":"DNA疫苗","years":["10"],"def":"也称基因疫苗或核酸疫苗，属于基因药物中的一种，是将含有编码某种抗原蛋白的基因序列的质粒作为疫苗，直接导入人或动物体内，让其在宿主细胞中表达抗原蛋白，诱导宿主产生对抗该抗原蛋白的免疫应答，从而达到免疫的目的"},{"subj":"631","term":"基因组文库","years":["10"],"def":"是某一生物体全部或部分基因的集合，将某个生物的基因组 DNA 或 cDNA 片段与适当载体在体外重组后，转化宿主细胞，所得的菌落或噬菌体的集合即为该生物的基因文库","src":"资料"},{"subj":"631","term":"表观遗传","years":["10"],"def":"指在 DNA 序列不发生改变的情况下，由于某些因素的改变，基因功能可发生可遗传的变化，最终导致表型变异的遗传现象及其本质。染色质重塑构成了表观遗传的基础，如组蛋白修饰、DNA甲基化、基因组印记、基因沉默、母体效应等"},{"subj":"631","term":"表观调控","years":["13"],"def":"与 DNA 排列顺序的变化无关的，调节基因表达的频率、速度或者表达程度的过程，如 DNA 甲基化、组蛋白修饰、基因组印记、基因沉默等，这种调节不能通过种系或生殖细胞传递，但可通过细胞分裂传给子代，在静止细胞的细胞质中也能稳定地自我繁殖"},{"subj":"631","term":"启动子","years":["13","19"],"def":"与基因表达启动相关的顺式作用元件，是结构基因的重要成分。它是一段位于转录起始点 5'端上游区 100bp-200bp 以内的具有独立功能的 DNA 序列，能活化 RNA 聚合酶，使之与模板 DNA 准确地相结合，并具有转录起始的特异性，可以控制基因转录的起始时间和表达的程度","src":"资料"},{"subj":"631","term":"组蛋白密码","years":["13","19"],"def":"是指核小体核心组蛋白末端被修饰氨基酸的种类、位置和修饰类型（如乙酰化、甲基化、磷酸化等），它可影响核小体的结构，并改变染色体的结构和功能，从而决定基因表达调控的状态"},{"subj":"631","term":"RNA干扰","years":["13"],"def":"是将一段短双链的 RNA 序列导入机体或细胞中，使机体或细胞中与之有同源序列的 mRNA 的翻译受到抑制，或使其降解，从而导致基因的表达活性受到抑制，甚至完全丧失的现象"},{"subj":"631","term":"转化","years":["13"],"def":"是指某一基因型的细胞从周围介质中吸收来自另一基因型的细胞的 DNA 而使它的基因型和表现型发生相应变化的现象。（或在基因工程中，将外源基因导入受体细胞的过程）"},{"subj":"631","term":"联会体","years":["13"],"def":"是减数分裂Ⅰ的偶线期中，配对的两条同源染色体之间形成的一种复合结构，主要由侧生组分、中间区和连接侧生组分与中间区的 SC 纤维组成，它与染色体的配对、交换和分离密切相关"},{"subj":"631","term":"可变剪接","years":["13"],"def":"也叫选择性剪接，是指一个基因的转录产物在不同的发育阶段、分化细胞和生理状态下，通过不同的剪接方式，可以得到不同的 mRNA 和翻译产物（所产生的蛋白质产物称为同源体），是基因表达调控的一种重要方式"},{"subj":"631","term":"转录因子","years":["18"],"def":"是一类能识别并结合转录起始位点的上游序列或远端增强子元件，通过 DNA-蛋白质相互作用而调节转录活性，从而保证目的基因以特定的强度，在特定的时间与空间表达的蛋白质分子。包括转录激活因子和转录阻遏因子","src":"资料"},{"subj":"631","term":"转座子","years":["18"],"def":"是存在于染色体 DNA 上可自主复制和位移的基本单位，能够在没有序列相关性的情况下独立插入基因组新位点，可带来一些遗传学效应，如引起基因突变失活、产生染色体畸变、调控基因表达活性、或产生新的基因、引起生物进化等"},{"subj":"631","term":"错配修复","years":["18"],"def":"是对 DNA 错配区的修复，通过母链甲基化原则找出母链与子链，从而保护母链，修正子链上错配的碱基"},{"subj":"631","term":"SNP","years":["18"],"def":"即单核苷酸的多态性，是指由于单个核苷酸改变而导致的核酸序列多态，表现在基因组中不同个体的 DNA 序列上的单个碱基差异。其中同一位置上的每个碱基类型叫做一个等位位点，SNP 可用于 DNA 遗传标记，从而绘制人类单倍型图、分析易感基因、进行基因分型和个性化用药等"},{"subj":"631","term":"重叠基因","years":["19"],"def":"具有部分共用核苷酸序列的基因，即同一段 DNA 携带了两种或两种以上不同蛋白质的编码信息。重叠的序列可以是调控基因，也可以是结构基因部分，常见于病毒和噬菌体基因组中"},{"subj":"880","term":"凝集素","years":["16"],"def":"凝集素是从植物、无脊椎动物和高等动物中提纯的一类糖蛋白或结合糖的蛋白，能专一识别并结合糖基。 因可与红细胞膜上的血型糖抗原结合而使红细胞凝集（含血型物质），故名凝集素。"},{"subj":"880","term":"氨基酸等电点","years":["12","19"],"def":"在某一 pH 溶液中，氨基酸解离成阳离子和阴离子的趋势及程度相等，成为兼性离子、净电荷为零，此时溶液的 pH 称该氨基酸的等电点（pI）。 等电点时氨基酸在电场中既不向正极也不向负极移动，溶解度最低、最易沉淀析出。"},{"subj":"880","term":"波尔效应（Bohr effect）","years":["10","12","19"],"def":"增加 CO₂ 浓度和降低 pH 都能提高血红蛋白亚基的协同效应，引起红细胞内血红蛋白氧亲和力下降，促进血红蛋白释放氧，反之，增加氧气的浓度，使血红蛋白释放 H⁺及 CO₂，这种 pH 和 CO₂ 对血红蛋白氧亲和力的影响称为波尔效应。波尔效应可以促进血红蛋白在组织中释放氧气，从而提高其运氧能力","src":"资料"},{"subj":"880","term":"β-转角（β-turn）","years":["13"],"def":"为多肽链中常见的二级结构，是一种可连接蛋白质分子中的其他二级结构（如α螺旋和β折叠）并使肽链走向改变的非重复多肽区，一般含有 2-16 个氨基酸残基，其中含有 5 个氨基酸残基以上的转角又常称之为环（loops），常见的转角含有 4 个氨基酸残基，有两种类型，特点为：第 1 个氨基酸残基的羰基氧与第 4 个残基的酰胺氮之间形成氢键；第 2 个残基大部分是脯氨酸，而第 3 个残基往往是甘氨酸","src":"资料"},{"subj":"880","term":"亲和层析（affinity chromatography）","years":["13"],"def":"根据生物大分子与配体间的特异性亲和力（如酶与底物、抗体与抗原、激素与受体），把某种配体连接在载体上作固定相，对能特异结合该配体的生物大分子进行分离的层析技术。 目标蛋白特异结合、杂蛋白直接流走，再用游离配体或改变 pH、离子强度洗脱，选择性高、步骤少。"},{"subj":"880","term":"别构蛋白（allosteric protein）","years":["13"],"def":"寡聚蛋白质一般具有多个结合部位，结合在蛋白质分子的特定部位上的配体对该分子的其他部位所产生的影响，称为别构效应，具有别构效应的蛋白质称为“别构蛋白”","src":"资料"},{"subj":"880","term":"竞争性抑制","years":["10","11"],"def":"抑制剂与底物结构相似，可与底物竞争酶的活性中心、把底物排斥在反应中心之外，从而抑制酶促反应。 增大底物浓度可竞争性解除抑制；动力学上 Km 增大、Vmax 不变。"},{"subj":"880","term":"增色效应（hyperchromic effect）","years":["13"],"def":"天然 DNA 在热变性等条件下双螺旋被破坏、碱基暴露，在 260 nm 波长处的紫外吸收明显增加，此现象称增色效应。 完全变性后 A260 可升高 25%~40%（约 1.3 倍），是判断 DNA 变性与复性最常用的指标。"},{"subj":"631","term":"DNA 光复活修复","years":["07"],"def":"DNA 受紫外线照射形成嘧啶二聚体后，由光裂合酶在可见光下直接解开二聚体、恢复原结构的修复方式，属直接修复。 光裂合酶先与二聚体结合，吸收光能以电子传递断裂环丁烷环，恢复两个嘧啶单体；不切碱基、不产生错配，属无误修复。"},{"subj":"631","term":"锌指结构域","years":["07"],"def":"真核转录因子中常见的小型 DNA 结合结构域，约 30 个氨基酸借 1 个 Zn²⁺ 与 2 个 Cys、2 个 His 配位，折叠成指状构象。 α-螺旋嵌入 DNA 大沟，靠氨基酸侧链与碱基特异识别；常串联重复出现，重复越多识别序列越长，为转录因子的典型模块。"},{"subj":"631","term":"ρ 因子","years":["07"],"def":"原核生物中参与转录终止的六聚体蛋白，具依赖 ATP 的 RNA-DNA 解旋酶活性，介导不依赖终止因子的 ρ 依赖性终止。 ρ 结合新生 RNA 5′ 端 rut 位点，沿 RNA 5′→3′ 移动并水解 ATP，追上暂停的聚合酶，解开 RNA-DNA 杂交体而释放 RNA。"},{"subj":"880","term":"Y-谷氨酰胺循环","years":["13"],"def":"是体内氨转运的一种形式，即脑和骨骼肌中的谷氨酸与游离氨结合形成谷氨酰胺，并通过血液循环运输至肝或肾中重新分解为谷氨酸和氨的过程，其中谷氨酰胺为中性无毒物质，容易透过细胞膜，因此是氨的主要运输形式","src":"资料"},{"subj":"880","term":"P/O 比值","years":["13"],"def":"氧化磷酸化中每消耗 1 原子氧所生成的 ATP 分子数，即磷与氧的消耗比，用于衡量氧化磷酸化的偶联效率。 数值由各复合体泵出的质子数与 ATP 合酶 c 环质子数之比决定：NADH 经Ⅰ、Ⅲ、Ⅳ 为 2.5，FADH₂ 经Ⅱ、Ⅲ、Ⅳ 为 1.5。"},{"subj":"631","term":"核糖开关（英文）","years":["20"],"def":"mRNA 5′ 非翻译区中能直接结合小分子代谢物、并因此改变自身构象以调控下游基因表达的 RNA 元件（riboswitch）。 由适体（aptamer）与表达平台组成，配体结合后构象重排，形成或破坏终止子/抗终止子、或遮蔽 SD 序列，在转录或翻译水平开关基因。"},{"subj":"631","term":"切口平移","years":["20"],"def":"利用 DNA 聚合酶Ⅰ的 5′→3′ 外切酶活性与聚合活性，从双链 DNA 的单链切口处边切边补、使切口沿链移动的反应。 切口 5′ 端被外切酶水解，聚合酶在 3′ 端延伸；体系中加标记 dNTP 即可把标记掺入 DNA，常用于制备放射性或荧光探针。"},{"subj":"631","term":"基因家族（英文）","years":["20"],"def":"真核基因组中由同一祖先基因经重复和变异而来、序列高度同源、编码产物结构与功能相似的一组基因（gene family）。 成员常成簇排列（组蛋白、rRNA、珠蛋白基因家族），重复拷贝累积突变可分化为新功能基因或成为假基因。"},{"subj":"631","term":"表观遗传学","years":["20"],"def":"研究 DNA 序列不变而基因表达发生可遗传改变的学科，主要涉及 DNA 甲基化、组蛋白修饰、染色质重塑和非编码 RNA。 CpG 岛甲基化抑制转录，组蛋白乙酰化激活、甲基化因位点而异；参与细胞分化、X 染色体失活、基因组印记与肿瘤发生。"},{"subj":"880","term":"酶促反应的前馈与反馈","years":["04"],"def":"前馈，一般指前馈激活，即代谢途径中的一个酶被该途径中前面产生的代谢物激活的现象，可促进反应进行，减少底物积累；反馈，主要指反馈抑制，即反应体系中的某些中间产物或终产物，对其前面催化某一步反应的酶的抑制作用，可抑制反应进行，减少产物积累，是酶活调节的一种主要方式","src":"资料"},{"subj":"880","term":"高尔夫基体","years":[],"def":"是一种由数个平行堆叠的扁平膜囊和大小不等的囊泡所组成的膜聚合体，具有合成、分泌糖蛋白和脂蛋白，对某些蛋白质原进行酶切加工，以及对新细胞壁和细胞膜提供合成原料等多种功能","src":"资料"},{"subj":"880","term":"蛋白质的二级结构","years":[],"def":"是指蛋白质分子中某一段肽链的局部空间结构，也就是该段肽链主链骨架原子的相对空间位置，而不包括氨基酸残基侧链构象的内容和与其他肽链的关系。二级结构主要借主链原子之间形成的氢键维系构象稳定，主要有：α螺旋、β折叠、β转角、无规卷曲等常见形式","src":"资料"},{"subj":"880","term":"Cori 循环","years":["16"],"def":"肌肉糖酵解产生的乳酸经血液运至肝、在肝内异生为葡萄糖后再返回肌肉利用的循环，又称乳酸循环。 肌内 NAD⁺ 得以再生、乳酸不至堆积中毒；肝中乳酸异生为糖需耗 6 分子 ATP，相当于把产能负担由肌肉转给肝。"},{"subj":"880","term":"葡萄糖-丙氨酸循环","years":["16"],"def":"肌肉氨基酸以丙氨酸形式经血运至肝，肝内脱氨并将碳骨架异生为葡萄糖后送回肌肉的循环，兼运氨与补糖。 肌内丙酮酸经转氨生成丙氨酸入血，肝中脱氨后碳骨架糖异生、氨进尿素循环；与 Cori 循环共同构成肌肉-肝代谢协作。"},{"subj":"631","term":"QNT 测序技术","years":["22"],"def":"牛津纳米孔技术（ONT）单分子测序：单链核酸穿过膜上纳米孔时引起特征性电流变化，据此实时直接读出碱基序列。 无需 PCR 与荧光标记，读长可达数十至上百 kb，可直读 RNA 及甲基化修饰；早期单次准确率偏低，需生物信息学校正。"},{"subj":"631","term":"同源基因","years":["08"],"def":"由共同祖先基因经进化分化而来、序列与功能具相似性的一组基因，含种间的直系同源与种内的旁系同源。 直系同源源于物种形成、功能多相同；旁系同源源于基因重复、易分化新功能；序列一致性是推断功能与构建进化树的基础。"},{"subj":"631","term":"生物大分子","years":["08"],"def":"由许多小分子单体以共价键聚合而成、相对分子质量巨大（通常大于 10⁴）的有机分子，如蛋白质、核酸、多糖。 单体经脱水缩合形成肽键、磷酸二酯键、糖苷键；空间结构决定功能，是遗传信息表达与生命活动的物质基础。"},{"subj":"631","term":"蛋白质组学","years":["08"],"def":"研究特定细胞或生物体在特定时空表达的全部蛋白质的组成、结构、修饰、相互作用与功能的一门学科。 核心路线为分离—鉴定—定量：双向电泳或色谱分离，质谱（MALDI-TOF、串联质谱）鉴定，配合数据库检索，可高通量找差异蛋白。"},{"subj":"631","term":"TATAbox","years":["08"],"def":"真核Ⅱ类基因启动子中位于转录起始点上游约 −25~−30 bp 处、富含 A/T 的保守序列（TATAAA）。 TATA 结合蛋白（TBP，属 TFⅡD）识别并结合 TATA box，使 TFⅡD 定位、组装前起始复合物，决定转录起始位点的准确性。"},{"subj":"631","term":"转录单位","years":["08"],"def":"从启动子开始到终止子结束、被 RNA 聚合酶完整转录为一条 RNA 的 DNA 片段，是基因转录的结构与功能单位。 一个转录单位可只含一个基因，也可含多个基因（操纵子、多顺反子 mRNA）；产物可为 mRNA、tRNA 或 rRNA，界限由启动子与终止子界定。"},{"subj":"631","term":"基本转录因子","years":["08"],"def":"真核 RNA 聚合酶Ⅱ 转录所必需、与 TATA box 及起始位点结合并组装成前起始复合物的一组通用转录因子。 TFⅡD 含 TBP 识别 TATA box，TFⅡB 桥接聚合酶，TFⅡH 具解旋与 CTD 激酶活性；与聚合酶装配成前起始复合物，为Ⅱ类基因共用。"},{"subj":"631","term":"转分化","years":["13"],"def":"一种已分化的细胞跨谱系转变为另一种分化细胞类型的现象，如成纤维细胞转为肌细胞、肝细胞转为胆管细胞。 需关闭原谱系基因、开启新谱系基因，常经去分化或直接重编程，由 MyoD、C/EBP 等转录因子组合诱导，是再生医学的基础。"},{"subj":"880","term":"active transport","years":["13"],"def":"物质逆浓度梯度或电化学梯度跨膜转运、需消耗代谢能并由膜转运蛋白介导的过程，如 Na⁺-K⁺-ATP 酶。 原发性直接水解 ATP（P 型、V 型、F 型泵）；继发性借离子梯度（同向或反向转运）；均具饱和性、特异性和竞争性抑制。"},{"subj":"880","term":"allosteric protein","years":["13"],"def":"含两个以上亚基、除活性中心外还有别构位点，别构效应剂非共价结合后引起构象改变而改变活性的蛋白质。 遵循 MWC 齐变或 KNF 序变模型，配体结合一个亚基即改变其余亚基亲和力，动力学呈 S 形，是代谢快速调节与信号传递的基础。"},{"subj":"880","term":"磷氧比值","years":["13"],"def":"即 P/O 比值，指氧化磷酸化中每消耗 1 原子氧所生成的 ATP 分子数，反映电子传递与 ATP 合成的偶联程度。 数值由泵出质子数与 ATP 合酶质子回流比决定，NADH 为 2.5、FADH₂ 为 1.5；比值下降提示解偶联或呼吸链损伤。"},{"subj":"880","term":"密码子的简并性","years":["17"],"def":"一种氨基酸可由两个或两个以上不同密码子编码的现象，除 Met 与 Trp 外多数氨基酸都有多个密码子。 同义密码子多在第 3 位碱基不同，按摆动假说配对可减少突变对蛋白质的影响、提高翻译容错；不同物种存在密码子使用偏好。"},{"subj":"880","term":"PCR","years":["17"],"def":"聚合酶链式反应：体外以 DNA 为模板，用一对特异引物和耐热 DNA 聚合酶，经变性、退火、延伸循环使目的片段指数扩增。 每轮循环产物约加倍，n 轮后扩增约 2ⁿ 倍；关键要素为模板、引物、dNTP、Mg²⁺、Taq 酶与温度程序。"},{"subj":"631","term":"miRNA","years":["21"],"def":"真核生物内源编码的长约 21~23 nt 的非编码单链 RNA，由发夹前体经 Dicer 加工，在转录后水平负调控基因表达。 与靶 mRNA 3′UTR 部分互补时抑制翻译，完全互补时经 RISC 切割降解；一个 miRNA 可调控多个靶基因，参与发育与肿瘤发生。"},{"subj":"631","term":"RNAi","years":["21"],"def":"外源或内源双链 RNA 经 Dicer 切成小干扰 RNA，装配成 RISC 后特异降解同源 mRNA、导致基因沉默的现象。 双链 RNA 先被 Dicer 切成 21~23 nt 的 siRNA，再装配 RISC 降解同源 mRNA；具序列特异性、可扩散、可遗传，由 Fire 和 Mello 发现。"},{"subj":"631","term":"酵母双杂交","years":["21"],"def":"基于 Gal4 转录因子模块化原理检测蛋白质相互作用的遗传学方法，把待测蛋白分别与 DNA 结合域和激活域融合。 两蛋白互作使 BD 与 AD 靠近、重建转录因子活性，激活 LacZ、HIS3 等报告基因；可在体内筛文库，但难检测跨膜或需修饰的互作。"},{"subj":"631","term":"基因芯片","years":["21"],"def":"把大量已知序列的核酸探针高密度、有序地固定在固相支持物上，与标记样品杂交后并行检测信号的微型器件。 杂交信号强度反映靶序列丰度，经扫描与软件分析得表达谱或基因型；用于差异表达、SNP 分型、突变与病原体检测。"},{"subj":"631","term":"实时定量 PCR","years":["21"],"def":"在 PCR 体系中加入荧光染料或荧光探针，实时监测每轮循环的荧光强度，从而对起始模板进行定量的技术。 荧光达阈值所需循环数 Ct 与起始模板量的对数成线性；分 SYBR Green 染料法与 TaqMan 探针法，可作相对或绝对定量。"},{"subj":"631","term":"端粒酶","years":["21"],"def":"由 RNA 组分和逆转录酶组分构成的核糖核蛋白，能以自身 RNA 为模板合成端粒重复序列、延长染色体末端。 TERT 以 TERC 为模板逆转录延伸 3′ 悬突，再由聚合酶补齐互补链；生殖细胞、干细胞与多数肿瘤细胞活性高，体细胞低。"},{"subj":"631","term":"nucleasome 核体","years":[],"def":"真核染色质的基本结构单位：146 bp DNA 盘绕在 H2A、H2B、H3、H4 各两分子组成的组蛋白八聚体外约 1.75 圈。 相邻核小体经连接 DNA 连成串珠，再折叠压缩为 30 nm 纤维，DNA 压缩 6~7 倍；同时是组蛋白修饰与染色质重塑的靶点。"},{"subj":"631","term":"allosteric regulation 别构调节","years":[],"def":"小分子效应剂以非共价方式结合酶的别构位点，引起构象改变，从而改变活性中心对底物亲和力或催化效率的调节。 效应剂与底物结构不同，结合后经亚基间构象传递产生正协同激活或负协同抑制，动力学曲线呈 S 形，如 ATCase、PFK-1。"},{"subj":"631","term":"isoelectric point 等电点","years":[],"def":"两性分子在溶液中净电荷为零、正负电荷相等时所在溶液的 pH 值，用 pI 表示，此时在电场中不迁移。 pI 由可解离基团 pKa 决定；pH<pI 带正电、pH>pI 带负电，据此做等电聚焦电泳、等电点沉淀与离子交换层析。"},{"subj":"631","term":"glyoxylate cycle 乙醛酸循环","years":[],"def":"植物和微生物中绕开三羧酸循环两步脱羧、以乙酰辅酶 A 为原料净合成琥珀酸进而生成糖的途径。 异柠檬酸裂解为琥珀酸与乙醛酸，后者与乙酰 CoA 缩合成苹果酸；2 分子乙酰 CoA 净生 1 分子琥珀酸，使脂肪酸碳源转为糖。"},{"subj":"631","term":"reverse transcription 逆转录","years":[],"def":"以 RNA 为模板、由逆转录酶催化合成互补 DNA（cDNA）的过程，遗传信息流向为 RNA→DNA。 逆转录酶兼具 RNA 指导的 DNA 聚合、DNA 指导的 DNA 聚合与 RNase H 活性，需引物；是 cDNA 克隆与 RT-PCR 的基础。"},{"subj":"631","term":"glycolysis 糖酵解","years":[],"def":"在细胞质中经 10 步酶促反应将 1 分子葡萄糖分解为 2 分子丙酮酸，净生成 2 ATP 和 2 NADH 的途径。 分耗能的准备阶段与产能阶段，己糖激酶、PFK-1、丙酮酸激酶为关键调节酶；无氧时丙酮酸还原为乳酸以再生 NAD⁺。"},{"subj":"631","term":"secondary messenger 第二信使","years":[],"def":"第一信使与受体结合后在细胞内生成或释放、把信号转导并逐级放大的小分子，如 cAMP、cGMP、IP₃、DAG、Ca²⁺。 由腺苷酸环化酶、磷脂酶 C 等生成，作用于蛋白激酶引起级联磷酸化，实现信号放大、整合与终止，是跨膜转导的核心环节。"},{"subj":"631","term":"specificity 特异性","years":[],"def":"酶对底物和所催化反应的高度选择性，一种酶只作用于一种或一类结构相似的底物、催化特定类型的反应。 源于活性中心与底物在形状、电荷、基团上的互补；包括底物特异性、反应特异性与立体特异性，是酶鉴别与临床检测的基础。"},{"subj":"631","term":"ribozyme 核酶","years":[],"def":"核酶（ribozyme），具有催化功能的 RNA 分子，可催化自身或其他 RNA 的磷酸二酯键断裂与连接，如四膜虫 Ⅰ 类内含子。 打破“酶都是蛋白质”的传统观念，为 RNA 世界假说提供依据；催化效率低于蛋白酶，但可反复使用。"},{"subj":"631","term":"简并性","years":[],"def":"简并性，指遗传密码中一种氨基酸可由两个或两个以上密码子编码的现象；除 Met（AUG）、Trp（UGG）外，多数氨基酸有 2~6 个密码子。 同义密码子多在第 3 位碱基不同，突变后仍编码同一氨基酸，降低突变危害；不同物种对同义密码子的选用存在偏爱性。"},{"subj":"631","term":"丝心蛋白","years":[],"def":"丝心蛋白（fibroin），蚕丝的主要结构蛋白，由重链与轻链经二硫键连接，富含 Gly、Ala、Ser，二级结构以反平行 β-折叠为主。 重复序列 Gly-Ala-Gly-Ala-Gly-Ser 使 β-折叠片层紧密堆叠，链间氢键密集，赋予纤维高强度与柔性，但缺乏弹性。"},{"subj":"631","term":"α-丙酮酸脱氢酶系","years":[],"def":"丙酮酸脱氢酶复合体，多酶体系，由 E1 丙酮酸脱氢酶、E2 二氢硫辛酰胺转乙酰酶、E3 二氢硫辛酰胺脱氢酶组成，催化丙酮酸氧化脱羧生成乙酰 CoA。 需 TPP、硫辛酸、CoA、FAD、NAD⁺ 五种辅酶；产物乙酰 CoA、NADH、ATP 反馈抑制，AMP、CoA、NAD⁺ 激活；磷酸化失活、去磷酸化激活。"},{"subj":"631","term":"同裂酶","years":["25"],"def":"同裂酶（isoschizomer），指来源不同但识别同一 DNA 序列、并在相同位点切割产生相同末端的两种限制性内切酶。 两者对甲基化敏感性常不同，可用于检测 DNA 甲基化；一种酶失活或受抑制时可互为替代。"},{"subj":"631","term":"假基因","years":["25"],"def":"假基因，基因组中与功能基因同源、但因缺失启动子、阅读框移位或点突变而失去表达能力的 DNA 序列，不产生有功能的蛋白质或 RNA。 分加工型（逆转座而来、无内含子）与非加工型（基因重复后突变）；可作为分子进化标记，少数仍参与基因表达调控。"},{"subj":"880","term":"别嘌呤醇","years":["21"],"def":"别嘌呤醇，次黄嘌呤的异构体，是黄嘌呤氧化酶的抑制药，能减少尿酸生成，临床用于治疗痛风和高尿酸血症。 本身亦被黄嘌呤氧化酶氧化为别黄嘌呤，两者均为竞争性抑制剂，故作用持久；可使黄嘌呤蓄积，偶致黄嘌呤结石与过敏。"},{"subj":"631","term":"DNA 的半保留复制","years":["24"],"def":"DNA 半保留复制，复制时双链解开，两条亲代链各作模板合成互补链，子代 DNA 中一条链来自亲代、一条为新合成链。 Meselson-Stahl ¹⁵N 密度梯度离心实验证实；保证遗传信息忠实、完整地传给子代。"},{"subj":"631","term":"非编码 RNA","years":["24"],"def":"非编码 RNA，指不翻译成蛋白质的 RNA，包括 rRNA、tRNA、snRNA、miRNA、siRNA 等，在转录、剪接、翻译与基因表达调控中发挥作用。 miRNA、siRNA 经 RISC 降解或阻抑靶 mRNA 翻译；lncRNA 参与 X 染色体失活、染色质修饰与转录干扰。"},{"subj":"631","term":"无义突变","years":["24"],"def":"无义突变，指编码氨基酸的密码子突变为终止密码子（UAA、UAG、UGA），使肽链合成提前终止、生成截短蛋白质的突变。 多肽缩短、功能丧失，多为致病或致死突变；抑制性 tRNA 或通读药物可部分纠正。"},{"subj":"631","term":"泛素蛋白","years":["24"],"def":"泛素蛋白，由 76 个氨基酸残基构成、高度保守的小分子蛋白，经 E1 激活、E2 结合、E3 连接酶催化，共价连接于靶蛋白的赖氨酸残基。 形成多聚泛素链标记靶蛋白，由 26S 蛋白酶体 ATP 依赖性降解；亦参与 DNA 修复、信号转导与蛋白定位。"},{"subj":"631","term":"剪接体","years":["24"],"def":"剪接体，由 U1、U2、U4、U5、U6 等 snRNA 与数十种蛋白质组成的核糖核蛋白复合物，识别 hnRNA 剪接位点，切除内含子并连接外显子。 经两次酯交换完成：先由 branch point 攻击 5′ 位点形成套索，再连接两个外显子；需 ATP 与 snRNP 重排。"},{"subj":"631","term":"σ因子","years":["24"],"def":"σ 因子，原核 RNA 聚合酶全酶的组分，识别启动子 −35 区与 −10 区，引导酶结合并起始转录；转录起始后脱落，由核心酶完成延伸。 不同 σ 因子（如 σ⁷⁰、σ³² 热休克因子）识别不同启动子，使 RNA 聚合酶选择性转录不同基因，是原核转录调控的重要层次。"},{"subj":"631","term":"HIV","years":["24"],"def":"HIV，人类免疫缺陷病毒，属逆转录病毒科慢病毒属，有包膜和两条正链 RNA，携带逆转录酶、整合酶与蛋白酶，主要侵犯 CD4⁺ T 淋巴细胞。 经性接触、血液和母婴传播；病毒 RNA 逆转录为 DNA 后整合入宿主基因组，逐步破坏细胞免疫，最终导致艾滋病（AIDS）。"},{"subj":"631","term":"DNA 半保留复制","years":["06"],"def":"DNA 半保留复制，亲代 DNA 双链分开后各自作模板，按碱基互补配对合成子链，所得两个子代分子均含一条亲代链和一条新链。 是 DNA 复制的基本方式，保证遗传信息稳定传递；由 Meselson-Stahl 实验以 ¹⁵N 标记证实。"},{"subj":"631","term":"RNA 的剪接（RNA splicing）","years":["06"],"def":"RNA 剪接，从 DNA 模板链转录出的最初转录产物中除去内含子，并将外显子连接起来形成一个连续 RNA 分子的过程。 核 mRNA 主要经剪接体按 GU-AG 规则剪接；Ⅰ、Ⅱ 类内含子可自我剪接，tRNA 前体由内切酶与连接酶加工。"},{"subj":"631","term":"核酸的分子杂交","years":["06"],"def":"核酸的分子杂交，指变性成单链的核酸在适宜条件下与互补序列按碱基配对复性，形成双链杂交体的过程，可用于检测特定核酸序列。 Southern 印迹（DNA）、Northern 印迹（RNA）、斑点杂交与原位杂交；探针标记及温度、盐浓度等严格性决定特异性。"},{"subj":"631","term":"细菌转化","years":["06"],"def":"细菌转化，受体菌直接摄取环境中游离的裸露 DNA 片段，使其进入细胞并整合到基因组，从而获得新的遗传性状的过程。 需处于感受态，Ca²⁺ 处理、电击可诱导；Griffith 与 Avery 实验由此证明 DNA 是遗传物质，也是基因工程的基础。"},{"subj":"631","term":"外显子与内含子","years":["06"],"def":"外显子与内含子，是真核基因内部的两类序列：外显子为最终保留在成熟 RNA 中的编码序列，内含子为剪接时被切除的非编码间隔序列。 内含子多以 GU 起始、AG 终止，由剪接体去除；外显子-内含子结构使同一基因经可变剪接产生多种蛋白质。"},{"subj":"631","term":"多基因病","years":["06"],"def":"多基因病，由两对以上基因与环境因素共同作用所致的疾病，不呈典型孟德尔遗传，表现为家族聚集和性状连续变异，如高血压、糖尿病。 患者同胞再发风险明显高于群体发病率，且随亲缘系数降低而下降；以易患性阈值模型解释，靠连锁分析和全基因组关联研究定位易感基因。"},{"subj":"631","term":"基因表达调控","years":["06"],"def":"基因表达调控，指细胞在转录、转录后加工、翻译及翻译后各水平上，对基因表达的时间、空间和强度进行选择性控制的过程。 原核以操纵子（如 lac 操纵子）为主，主要控制转录起始；真核有染色质重塑、顺式元件与反式因子、表观修饰、可变剪接和 miRNA 等多级调控。"},{"subj":"631","term":"基因克隆","years":["06"],"def":"基因克隆，将目的基因片段与载体在体外重组，导入宿主细胞后随载体一起复制、扩增，获得大量同一 DNA 片段的技术。 目的基因获取（PCR 或酶切）→ 与载体连接 → 转化宿主 → 筛选鉴定（抗性、蓝白斑、探针杂交）；是基因工程的核心环节。"},{"subj":"880","term":"Ribozyme","years":["15"],"def":"核酶（ribozyme），具有催化活性的 RNA 分子，能催化自身或其他 RNA 分子中磷酸二酯键的断裂与连接，如四膜虫 Ⅰ 类内含子。 证明酶并非都是蛋白质，支持 RNA 世界假说；多为分子内剪接，Km 较大、转换数较低。"},{"subj":"880","term":"P/O ratio","years":["15"],"def":"P/O 比值，指氧化磷酸化中每消耗 1 原子氧（1/2 O₂）所生成的 ATP 分子数，用来衡量线粒体氧化与磷酸化的偶联效率。 NADH 经呼吸链氧化 P/O 约 2.5，FADH₂ 约 1.5；解偶联剂使其降低，可据此判断偶联程度。"},{"subj":"880","term":"Melting temperature(Tm)","years":["15"],"def":"熔解温度（Tm），指 DNA 双链受热变性时，增色效应达到最大增幅一半、即一半双链解开时所对应的温度，反映双链的稳定性。 与 G+C 含量正相关（Tm≈69.3+0.41×GC%），随离子强度升高而升高，与片段长度和碱基错配有关；是 PCR 退火温度设计的依据。"},{"subj":"880","term":"Allosteric effect","years":["15"],"def":"别构效应，指寡聚蛋白的调节部位结合配体后，通过亚基构象改变影响活性部位对底物的亲和力或催化效率的现象。 动力学曲线呈 S 形，有协同效应；如血红蛋白结合 O₂、磷酸果糖激酶受 ATP 抑制与 AMP 激活；别构剂不占据活性中心。"},{"subj":"880","term":"Okazaki fragment","years":["15"],"def":"冈崎片段，DNA 半不连续复制中随从链上沿 5′→3′ 方向分段合成的短 DNA 片段，真核长约 100~200 个核苷酸，原核约 1000~2000 个。 由 RNA 引物起始，RNase H 与 DNA 聚合酶 Ⅰ 切除引物并填补缺口，DNA 连接酶封口连成长链。"},{"subj":"880","term":"Glycolysis","years":["15"],"def":"糖酵解，在细胞质中经 10 步反应将 1 分子葡萄糖降解为 2 分子丙酮酸，净生成 2 分子 ATP 和 2 分子 NADH 的代谢途径。 不需氧，分耗能（1~5 步）与产能（6~10 步）两阶段；限速酶为己糖激酶、磷酸果糖激酶-1、丙酮酸激酶，受能荷调节。"},{"subj":"880","term":"Ultrafiltration","years":["15"],"def":"超滤，利用半透膜两侧的压力差（外加压力或离心力）使小分子溶质与溶剂透膜、大分子被截留，从而分离、纯化并浓缩生物大分子的方法。 用于酶与蛋白质的浓缩、脱盐、缓冲液更换及病毒、细胞分离；按截留分子量选膜，须防浓差极化与膜污染。"},{"subj":"880","term":"Hyperchromic effect","years":["15"],"def":"增色效应，DNA 由双链变性为单链时，碱基间的堆积作用被破坏，其在 260 nm 处的紫外吸收值升高的现象。 用于监测变性复性、测定 Tm、判断 DNA 纯度与含量（A260/A280）；与复性时的减色效应相对。"},{"subj":"631","term":"同源重组","years":["23"],"def":"同源重组，指两条具有同源序列的 DNA 分子间发生断裂、片段交换并重新连接的遗传重组，如减数分裂中的交换和细菌 RecA 介导的重组。 双链断裂→末端加工→RecA/Rad51 介导链侵入形成 D 环与 Holliday 交叉→分支迁移→解离；功能为修复双链断裂、产生遗传多样性、整合外源基因。"},{"subj":"631","term":"Nothern 印记","years":["23"],"def":"Northern 印迹，将 RNA 经变性凝胶电泳按大小分离后转移至固相膜，再用标记探针杂交，检测特定 mRNA 的大小与表达量的技术。 与检测 DNA 的 Southern 印迹对应；可分析基因转录水平与剪接异构体，操作中须严格防止 RNase 污染。"},{"subj":"880","term":"蛋白质的等电点","years":["14"],"def":"蛋白质的等电点，指蛋白质分子上所带正、负电荷相等、净电荷为零时溶液的 pH 值，以 pI 表示，此时分子在电场中不移动、溶解度最低。 是等电聚焦、电泳分离和等电点沉淀的依据；pI 由分子中酸性、碱性氨基酸残基的比例决定。"},{"subj":"880","term":"逆转录","years":["14"],"def":"一种催化以 RNA 为模板合成 DNA 的 DNA 聚合酶，具有 RNA 指导的 DNA 合成，水解 RNA 和 DNA 指导的 DNA 合成的三种酶活性。","src":"资料"},{"subj":"880","term":"磷酸戊糖途径","years":["14"],"def":"磷酸戊糖途径，在细胞质中以葡糖-6-磷酸脱氢生成 6-磷酸葡糖酸内酯起始，最终生成 NADPH 与磷酸戊糖的代谢途径，又称磷酸己糖旁路。 产生 NADPH 供脂肪酸等还原性合成及谷胱甘肽还原，提供核糖-5-磷酸供核苷酸合成；关键酶葡糖-6-磷酸脱氢酶受 NADPH 抑制。"},{"subj":"631","term":"核酸杂交","years":["10"],"def":"核酸杂交，变性后的单链核酸在适宜条件下与互补序列按碱基配对原则复性，形成双链杂交分子的过程，可检测特定 DNA 或 RNA 序列。 分 Southern、Northern、斑点杂交与原位杂交；关键是探针标记、预杂交封闭及温度、盐浓度等杂交严格性控制。"},{"subj":"631","term":"报告基因","years":["10"],"def":"报告基因，指编码产物易于检测、与待研究的调控序列融合后导入细胞，用以反映该序列转录活性的基因，如 lacZ、GFP、荧光素酶基因。 分析启动子与增强子活性、基因表达水平及信号通路；要求背景低、检测灵敏、对宿主细胞无明显毒性。"},{"subj":"631","term":"同义突变","years":["10"],"def":"同义突变，指碱基改变后密码子所编码的氨基酸不变（多发生在第 3 位碱基），蛋白质一级结构不发生改变的突变。 一般不改变表型，但可影响剪接、mRNA 稳定性与翻译速率，故并非完全中性。"},{"subj":"631","term":"切除答复","years":["10"],"def":"切除修复，DNA 损伤后由核酸酶切除含损伤的片段，再以互补链为模板由 DNA 聚合酶填补缺口、连接酶封口，使序列恢复的修复方式。 碱基切除修复（BER）由糖苷酶和 AP 核酸酶切除单个碱基；核苷酸切除修复（NER）切除约 25~30 nt 寡核苷酸，缺陷可致着色性干皮病。"},{"subj":"631","term":"Enhancer","years":["10"],"def":"增强子，真核基因组中能显著提高靶基因转录效率的顺式作用元件，可位于启动子上游、下游或内含子内，作用方向无关。 由多个模块组成，结合特异反式因子后经 DNA 环化靠近启动子起作用；常具组织特异性，如 SV40 增强子、免疫球蛋白基因增强子。"},{"subj":"631","term":"同工 RNA","years":["10"],"def":"同工 tRNA，指携带同一种氨基酸但反密码子不同、即识别该氨基酸不同密码子的一组 tRNA，由不同的 tRNA 基因编码。 与密码子简并性相适应，使同一氨基酸可由多个密码子带入；各同工 tRNA 含量不同，形成密码子使用偏爱性。"}],"kps":[{"subj":"880","chap":"糖类","name":"淀粉与纤维素的结构差异","stars":2,"years":["20","21"],"points":["两者都是葡萄糖的聚合物，唯一区别是糖苷键构型：淀粉用 α-1,4（可被人体 α-淀粉酶水解），纤维素用 β-1,4（人体缺乏纤维素酶，即内切/外切 β-1,4-葡聚糖酶，无法切断 β-1,4 主链，故不能消化）。一个键型之差，决定了“粮食”与“膳食纤维”两种命运。","纤维素的应用（3 条，直接背）：① 调整肠道微生态——作为菌群发酵底物，促益生菌、抑有害菌；② 刺激肠道蠕动——机械刺激，防治便秘；③ 增加饱腹感——吸水膨胀，减少能量摄入，防治肥胖。"]},{"subj":"880","chap":"糖类","name":"糖类名解与小题","stars":1,"years":["10","16"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"氨基酸","name":"氨基酸等电点 pI","stars":2,"years":["12","19","21"],"points":["① 无侧链解离（中性氨基酸）：pI = (pK₁ + pK₂) / 2 —— 取两侧 pK 的均值。 ② 酸性氨基酸（Asp、Glu）：pI = (pK_α-COOH + pK_R) / 2 —— 取两个最低的 pK。 ③ 碱性氨基酸（Lys、Arg、His）：pI = (pK_R + pK_α-NH₃⁺) / 2 —— 取两个最高的 pK。","His 的咪唑基 pK_R ≈ 6.0，是唯一在生理 pH 附近缓冲的侧链。因此：① 在红细胞中作为质子供体/受体参与 Hb 的 Bohr 效应（His146 与 His122 是关键）；② 在酶活性中心执行酸碱催化；③ 其咪唑基可与血红素 Fe²⁺ 配位，影响 T→R 转变。"]},{"subj":"880","chap":"氨基酸","name":"20 种氨基酸的分类与特殊性质","stars":2,"years":["17","18","19","20"],"points":["非极性脂肪族：Gly、Ala、Pro、Val、Leu、Ile、Met（7） 芳香族：Phe、Tyr、Trp（3） 极性不带电：Ser、Thr、Cys、Asn、Gln（5） 极性带正电（碱性）：Lys、Arg、His（3） 极性带负电（酸性）：Asp、Glu（2）"]},{"subj":"880","chap":"氨基酸","name":"肽链序列测定","stars":2,"years":["21"],"points":["定 N 端：DNFB（Sanger 试剂）标记游离 α-氨基，水解后得 DNP-Tyr → N 端是 Tyr。","用专一性切割定位：胰凝乳蛋白酶切 Phe/Tyr/Trp 的 C 端；因 N 端为 Tyr 且切成 5+4 两段，故第一刀在 Tyr 之后，四肽以 Tyr 开头。","用 CNBr 定位 Met：CNBr 切 Met 的 C 端；本题用于确定 Met 的位置（结合片段组成排除）。","用胰蛋白酶收尾：切 Arg/Lys 的 C 端，得到单个 Phe → 说明 Arg 紧邻 Phe 的 N 侧。"]},{"subj":"880","chap":"蛋白质","name":"蛋白质的结构层次与二级结构","stars":3,"years":["19"],"points":["一级：氨基酸的排列顺序（含二硫键位置），由肽键维系。 二级：主链骨架局部盘绕折叠的构象，由主链氢键维系（不涉及侧链）。 三级：整条肽链在二级/超二级基础上折叠成紧密球状构象，由疏水作用（主要）、氢键、离子键、二硫键共同维系。 四级：多个亚基通过非共价键缔合成特定空间排布（Hb 是典型）。"]},{"subj":"880","chap":"蛋白质","name":"蛋白质变性","stars":3,"years":["11"],"points":["本质：受物理/化学因素影响，空间构象（二级以上）被破坏，非共价键断裂，一级结构不变（肽键未断）。","现象（4 条）：① 生物活性丧失（最重要标志）；② 分子形状改变、肽链松散、易被酶水解；③ 疏水基团外露 → 水化层破坏 → 溶解度下降、易沉淀、黏度增加、紫外吸收改变；④ 丧失结晶能力。","原因：加热、强酸强碱、有机溶剂（乙醇/丙酮）、尿素与盐酸胍（破坏氢键）、SDS（去污剂）、重金属离子、紫外线、剧烈震荡/剪切。","复性：变性较轻时去除变性因素可恢复构象（Anfinsen 核糖核酸酶实验证明“一级结构决定高级结构”）。"]},{"subj":"880","chap":"蛋白质","name":"Hb 与 Mb：别构、协同、Bohr 效应","stars":3,"years":["10","12","13","19","20"],"points":["CO₂ 浓度升高及相应 pH 降低，能降低血红蛋白对氧的亲和性，使 p50 升高，这一现象称波尔效应。 分子基础：CO₂ 与 N 端氨基形成氨基甲酸酯，以及 H⁺ 质子化 His146，形成盐桥稳定 T 态，从而降低氧亲和力。 生理意义：在代谢旺盛的组织（低 pH、高 CO₂）促氧释放，在肺部（高 pH、低 CO₂）促氧结合——“需要氧的地方给氧”。","① 2,3-BPG：结合在 β 链中央空穴，稳定 T 态，降低亲和力（高原、慢性缺氧时升高，利于放氧）；② 温度：升高降低亲和力；③ H⁺（pH）：即 Bohr 效应；④ CO₂：直接结合 + 间接降 pH；⑤ CO：竞争性结合，亲和力高约 300 倍。","原理：CO 与 Hb 的亲和力比 O₂ 大 约 210 倍（教材口径 210~250 倍），且形成 CO-Hb 后协同效应消失、剩余亚基更难结合 O₂（别构抑制），使血液携氧能力与释氧能力双降。 处理：迅速脱离中毒环境 → 高浓度/高压氧吸入（提高 O₂ 分压竞争置换 CO）→ 必要时输血/换血。 2022 年变式问法：用生化解释 CO 中毒时机体耗氧量减少——除 Hb 外，CO 与肌红蛋白亲和力也极高，使肌肉不能正常贮氧，进一步减少组织可利用氧。"]},{"subj":"880","chap":"蛋白质","name":"分离纯化：四大原理与五种方法","stars":3,"years":["11","19","20","22"],"points":["方法一：SDS-PAGE / 凝胶过滤（按分子量）。SDS-PAGE 中迁移率与 lg M 成反比 → 分子量由大到小依次排列（大分子跑得慢、在上方）；凝胶过滤中则大分子先洗脱。 方法二：离子交换层析 / 等电聚焦（按电荷）。按 pI 与 pH 的关系决定带电量与结合强度，电荷差异越大分离越开。"]},{"subj":"880","chap":"蛋白质","name":"蛋白质含量测定：五法 + 三聚氰胺","stars":3,"years":["11"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"蛋白质","name":"SDS-PAGE 的“四个为什么”","stars":3,"years":["12","13"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"酶","name":"酶的结构与活性中心","stars":2,"years":["10","19"],"points":["按组成：简单酶（仅蛋白）与缀合酶/全酶= 脱辅酶（蛋白部分，决定专一性、结合底物）+ 辅因子（非蛋白，决定反应类型、传递电子/基团）。辅因子又分 辅酶（非共价、可透析除去）与 辅基（共价、需化学处理才能除去）。","按功能：活性部位（结合部位 + 催化部位，个别酶另有调节部位）与非活性部位。活性部位六大特点：① 只占分子很小一部分；② 是三维实体；③ 位于表面空穴/裂缝，内部疏水（低介电常数），但含极性残基参与催化；④ 与底物诱导契合而非“锁钥”刚性互补；⑤ 靠多种次级键结合底物；⑥ 具有柔性/可运动性。","① 化学修饰法——用特异试剂共价修饰侧链基团（巯基、咪唑基、羧基），活性显著下降者该基团为必需基团；② 动力学法——测 pH-活性曲线推断关键基团 pK；③ X 射线衍射——解析酶-底物类似物复合物，直接看空间构象；④ 蛋白质工程/定点突变——逐个替换氨基酸，看活性变化（最精确）。"]},{"subj":"880","chap":"酶","name":"米氏方程与 Km 的意义","stars":3,"years":["10","13","19","21"],"points":["稳态假设：ES 生成速率 = 分解速率 → d[ES]/dt = 0 → 解出 [ES]，代入 v = k₂[ES]。","① 物理意义：v = ½Vmax 时的底物浓度，单位是浓度；② 反映亲和力：Km 越小，酶与底物亲和力越大；③ 反映酶的种类（是酶的特征常数，与酶浓度无关，随 pH、温度、底物种类改变）。","双倒数式：1/v = (Km/Vmax)(1/[S]) + 1/Vmax 截距 1/Vmax = 0.02 → Vmax = 50 μM·min⁻¹；斜率 Km/Vmax = 1.2×10⁻³ → Km = 1.2×10⁻³ × 50 = 0.06 μM。 米氏方程：v = 50[S] / (0.06 + [S])。","为什么用紫外分光光度法：LDH 催化 丙酮酸 + NADH + H⁺ → 乳酸 + NAD⁺；NADH 在 340 nm 有吸收，NAD⁺ 没有，故监测 340 nm 吸光度的下降速率即可反映酶活。"]},{"subj":"880","chap":"酶","name":"三种可逆抑制","stars":3,"years":["10","11","12"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"酶","name":"酶活力、比活力与纯化计算","stars":3,"years":["19","22"],"points":["酶活力（U）：一定条件下每分钟催化 1 μmol 底物转化所需的酶量。 比活力：每毫克蛋白所含的酶活力单位（U/mg），代表纯度。 回收率（提取率）：纯化后总活力 ÷ 纯化前总活力 × 100%。 纯化倍数：纯化后比活力 ÷ 纯化前比活力。"]},{"subj":"880","chap":"酶","name":"酶的调节：别构、共价修饰、酶原激活 名解 12","stars":2,"years":["12","16"],"points":["① 别构调节：调节物结合调节部位（非活性中心），引起构象改变 → 活性升高/降低；动力学曲线呈 S 形（正协同），不服从米氏方程；别构酶通常是代谢通路的关键酶/限速酶，多为寡聚酶，受反馈抑制。 ② 共价修饰：可逆的磷酸化/去磷酸化（激酶/磷酸酶）、腺苷化、二硫键互变——级联放大，效率极高（如糖原磷酸化酶）。 ③ 酶原激活：无活性的酶原经专一性水解切除一段肽段后暴露活性中心（胰蛋白酶原 → 胰蛋白酶、胃蛋白酶原、凝血酶原）。意义：避免自身消化、便于储存与快速启动。","同工酶（名解 2010/2011/2017/2019，四星高频）：催化相同化学反应，但分子结构、理化性质、免疫特性不同的一组酶。经典例子 LDH₁~LDH₅（四聚体，H/M 亚基不同组合）：心肌以 LDH₁ 为主，肝以 LDH₅ 为主——临床用来定位组织损伤。"]},{"subj":"880","chap":"核酸","name":"变性、复性与 Tm","stars":3,"years":["12","13","19"],"points":["变性：双链间氢键断裂、碱基堆积力破坏，双链解为单链，不涉及一级结构（磷酸二酯键）改变。因素：加热、强酸强碱、尿素/甲酰胺、乙醇。 增色效应：变性后碱基充分暴露，260 nm 吸光度升高（因碱基间的电子相互作用消失）。 复性：缓慢降温，互补单链重新配对成双链（退火）。 减色效应：复性时 260 nm 吸光度下降，回到天然水平。 Tm（熔解温度）：吸光度上升到最大增幅一半（即双螺旋有一半被解开）时的温度。","① G+C 含量：G≡C 有 3 个氢键、堆积力强 → GC 越高，Tm 越高。经验式：Tm = 69.3 + 0.41×(G+C)%。 ② 链长：越长 Tm 越高（<100 bp 时明显）。 ③ 离子强度：盐浓度越高，磷酸基负电荷被屏蔽，Tm 越高（所以杂交缓冲液要加盐）。 ④ pH：极端 pH 破坏氢键，Tm 降低；⑤ 变性剂（尿素、甲酰胺）降低 Tm。"]},{"subj":"880","chap":"核酸","name":"核酸含量测定与纯度判断","stars":2,"years":["20"],"points":["纯 DNA：A260/A280 ≈ 1.8；纯 RNA ≈ 2.0；若比值明显低于 1.8（如 1.5）→ 提示蛋白质污染；若 A260/A230 < 2.0 → 提示多糖/酚/胍盐残留。","标准作答顺序：① 先测 A260/A280 初判 → ② 双缩脲显色确认蛋白存在 → ③ 考马斯亮蓝法（标准曲线）定量蛋白 → ④ 紫外法或二苯胺法定量 DNA → ⑤ 琼脂糖电泳看完整性（有无降解拖尾）。"]},{"subj":"880","chap":"核酸","name":"Sanger 双脱氧链终止法","stars":2,"years":["13"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"生物膜","name":"膜的组成与流动镶嵌模型","stars":2,"years":["13","18"],"points":["① 膜脂：磷脂（甘油磷脂为主：PC、PE、PS、PI）、鞘脂（鞘磷脂、脑苷脂、神经节苷脂）、固醇（动物为胆固醇，植物为谷固醇，细菌一般不含）。 ② 膜蛋白：外周蛋白（ peripheral，靠离子键/氢键附着表面）、整合蛋白（跨膜，疏水段埋入脂双层）、脂锚定蛋白。膜蛋白是膜功能的体现者。 ③ 膜糖：以糖蛋白/糖脂形式存在于膜外表面，构成糖萼，参与识别、黏附、免疫。","流动性（脂分子侧向扩散、翻转极少；蛋白可侧向移动）与 不对称性（脂、蛋白、糖在两侧分布不同）。 影响因素：胆固醇双向调节（低温防凝固、高温防过流动）；不饱和脂肪酸越多越流动；温度升高流动性增大。"]},{"subj":"880","chap":"生物膜","name":"物质运输：被动、主动、协同 名解","stars":2,"years":["13"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"糖酵解与糖异生","name":"糖酵解十步与三步不可逆","stars":3,"years":["18","19","20"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"糖酵解与糖异生","name":"三个限速酶与它们的调节物","stars":3,"years":["18","20"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"糖酵解与糖异生","name":"6-磷酸葡萄糖：糖代谢的十字路口","stars":3,"years":["18","19"],"points":["① 糖酵解：葡萄糖经己糖激酶/葡萄糖激酶磷酸化； ② 糖原分解：糖原 → 1-磷酸葡萄糖 →（变位酶）→ G6P； ③ 糖异生：乳酸、甘油、生糖氨基酸异生为 G6P。","① 糖酵解/有氧氧化 → 丙酮酸 → 乳酸或乙酰 CoA → TCA； ② 磷酸戊糖途径 → 5-磷酸核糖 + NADPH； ③ 糖原合成：G6P → G1P → UDPG → 糖原； ④ 释放葡萄糖：肝/肾的6-磷酸葡萄糖酶水解成葡萄糖入血（肌肉无此酶，故肌糖原不能直接补血糖）。"]},{"subj":"880","chap":"糖酵解与糖异生","name":"糖异生：3 步绕行、4 个关键酶","stars":3,"years":["12"],"points":["能量账：由 2 分子丙酮酸合成 1 分子葡萄糖，消耗 4 ATP + 2 GTP = 6 个高能键；而糖酵解只净得 2 ATP——糖异生是“亏本生意”，所以只在肝、肾进行且受严格调控。","原料：乳酸、甘油、生糖氨基酸、丙酸。 乳酸循环（Cori 循环）：肌肉产乳酸 → 血液 → 肝异生为葡萄糖 → 回肌肉。"]},{"subj":"880","chap":"三羧酸循环","name":"八步反应与能量结算","stars":3,"years":[],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"三羧酸循环","name":"TCA 的三调控酶与调节物","stars":3,"years":["20"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"三羧酸循环","name":"TCA 为什么是代谢枢纽","stars":3,"years":["17"],"points":["① 共同的“最终氧化通路”：糖 → 丙酮酸 → 乙酰 CoA；脂肪 → 甘油 → 丙酮酸、脂肪酸 → β-氧化 → 乙酰 CoA；蛋白质 → 氨基酸脱氨后碳骨架 → 乙酰 CoA/α-KG/琥珀酰 CoA/延胡索酸/OAA。四类物质最终都汇入 TCA 彻底氧化。","② 共同的“合成原料库”：OAA → 糖异生 → 葡萄糖；乙酰 CoA → 脂肪酸/胆固醇；α-KG、OAA → 转氨生成氨基酸；琥珀酰 CoA → 血红素；OAA + 乙酰 CoA → 柠檬酸 → 运出线粒体供脂肪酸合成。","③ 三大关键中间产物：6-磷酸葡萄糖、丙酮酸、乙酰 CoA（这三个是各大类物质互变的“关卡”，纲要明确要求）。","④ 两用代谢途径（amphibolic）：既分解又合成，因此其中间物必须靠添补反应补充。"]},{"subj":"880","chap":"氧化磷酸化","name":"呼吸链与 P/O 比 名解 10、12/19","stars":2,"years":["10","12","13","19"],"points":["NADH 呼吸链：NADH → 复合体Ⅰ（NADH 脱氢酶，泵 4H⁺）→ CoQ → 复合体Ⅲ（细胞色素 bc₁，泵 4H⁺）→ Cyt c → 复合体Ⅳ（细胞色素氧化酶，泵 2H⁺）→ O₂。 FADH₂ 呼吸链：FADH₂ → 复合体Ⅱ（琥珀酸脱氢酶，不泵质子）→ CoQ → Ⅲ → Cyt c → Ⅳ → O₂。","P/O 比：每消耗 1 mol 氧原子所消耗的无机磷摩尔数（即生成的 ATP 数）。NADH = 2.5，FADH₂ = 1.5（旧值 3 与 2）。 化学渗透假说（Mitchell）：电子传递泵出 H⁺ 形成跨膜质子电化学梯度，H⁺ 经 ATP 合酶（F₀F₁）回流驱动 ADP + Pi → ATP。"]},{"subj":"880","chap":"氧化磷酸化","name":"抑制剂与解偶联剂","stars":2,"years":["10","22"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"磷酸戊糖途径与乙醛酸循环","name":"PPP 的两大产物 · 乙醛酸循环 名解","stars":2,"years":["18"],"points":["氧化阶段（不可逆）：G6P →（6-磷酸葡萄糖脱氢酶 G6PDH，限速）→ 6-磷酸葡萄糖酸内酯 →（6-磷酸葡萄糖酸脱氢酶）→ 5-磷酸核酮糖 + 2 NADPH + CO₂。 非氧化阶段（可逆）：核酮糖-5-P ⇌ 核糖-5-P ⇌ 木酮糖-5-P，经转酮醇酶（TPP）、转醛醇酶重排为己糖、丙糖。","生理意义（必背 3 条）：① 产生 NADPH——供脂肪酸/胆固醇合成、维持谷胱甘肽还原（保护红细胞）；② 产生 5-磷酸核糖——核苷酸合成的原料；③ 连接糖酵解与核苷酸代谢（C3、C4、C5、C6、C7 互通）。 临床：G6PDH 缺陷 → NADPH 不足 → 谷胱甘肽不能还原 → 红细胞膜脂过氧化 → 蚕豆病（溶血性贫血）。","定义：植物、微生物中，脂肪酸 β-氧化产生的乙酰 CoA 在乙醛酸体（glyoxysome）内，经异柠檬酸裂解酶与苹果酸合酶两步特有反应生成琥珀酸，进而异生为糖的途径。","关键点：① 绕过 TCA 的两个脱羧步骤（不产生 CO₂、不损失碳）；② 净结果：2 乙酰 CoA → 1 琥珀酸 → OAA → 葡萄糖，实现了“脂肪变糖”；③ 动物没有这两个酶，故动物不能把脂肪酸净转化为糖（这是“只吃脂肪不吃糖会酮症”的根本原因）。"]},{"subj":"880","chap":"脂类代谢","name":"β-氧化的四步与肉碱穿梭","stars":3,"years":["12","13","19"],"points":["① 脱氢：脂酰 CoA → 反-Δ²-烯脂酰 CoA，FAD → FADH₂（脂酰 CoA 脱氢酶） ② 水合：加水生成 L-β-羟脂酰 CoA（烯脂酰 CoA 水合酶） ③ 再脱氢：→ β-酮脂酰 CoA，NAD⁺ → NADH（β-羟脂酰 CoA 脱氢酶） ④ 硫解：+CoA → 乙酰 CoA + 少 2 碳的脂酰 CoA（β-酮脂酰 CoA 硫解酶）","活化与转运：胞质中 脂肪酸 + CoA + ATP → 脂酰 CoA（消耗 2 个高能键，即“−2 ATP”）；长链脂酰 CoA 不能直接过线粒体内膜，须经肉碱穿梭：CPTⅠ（肉碱棕榈酰转移酶Ⅰ，限速酶，受丙二酰 CoA 抑制）→ 肉碱-脂酰肉碱 → CPTⅡ → 线粒体基质。"]},{"subj":"880","chap":"脂类代谢","name":"产能计算","stars":3,"years":["19","20","21","22"],"points":["设碳数 n（偶数）： ① β-氧化轮数 = n/2 − 1；② 乙酰 CoA 数 = n/2；③ 每轮产 1 FADH₂ + 1 NADH。","软脂酸 C16：8×10 + 7×4 − 2 = 80 + 28 − 2 = 106 ATP。 硬脂酸 C18：9×10 + 8×4 − 2 = 90 + 32 − 2 = 120 ATP。 甘油：−1（甘油激酶）+ 2（糖酵解底物水平）+ 2×1.5（胞质 NADH 经 3-磷酸甘油穿梭）+ 12.5（丙酮酸→TCA）= 16.5 ATP。 十八碳甘油三酯：16.5 + 3×120 = 376.5 ATP。"]},{"subj":"880","chap":"脂类代谢","name":"酮体与酮症","stars":3,"years":["10","13","16","19","21"],"points":["酮体 = 乙酰乙酸、β-羟丁酸、丙酮（肝内生成，肝外利用；肝缺乏 β-酮脂酰 CoA 转移酶，不能利用酮体——这是“肝造不自用”的经典考点）。","因果链：饥饿/糖尿病 → 血糖不足 → 胰高血糖素↑ → ① 脂肪动员、β-氧化加速 → 乙酰 CoA 大量生成；② 糖异生加速 → 草酰乙酸被大量消耗 → 乙酰 CoA 无法进入 TCA → 转向酮体生成 → 血酮升高 → 酮血症、酮尿症。","异味：丙酮易挥发，经肺排出，故呼气有“烂苹果味”。 酸中毒：乙酰乙酸、β-羟丁酸是有机酸，滴定消耗血中 HCO₃⁻、阴离子间隙增大，使血液 pH 下降（注意：酮症酸中毒时总体钾缺乏但血清钾常正常或偏高，不要写成“血钾被消耗”）。 危害：酸中毒抑制酶活性、扰乱水盐代谢，严重时昏迷（糖尿病酮症酸中毒 DKA）。","奇数碳为什么更好：奇数碳脂肪酸 β-氧化除产生乙酰 CoA 外，末轮产生 丙酰 CoA →（羧化，生物素）→ 甲基丙二酰 CoA →（变位酶，B₁₂）→ 琥珀酰 CoA → 补充 TCA 中间物 → 生成 OAA → 可异生为葡萄糖；偶数碳只能产乙酰 CoA，无法净补充草酰乙酸。"]},{"subj":"880","chap":"脂类代谢","name":"脂肪酸合成 vs 降解","stars":2,"years":["12"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"氨基酸代谢","name":"三种脱氨基方式","stars":3,"years":[],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"氨基酸代谢","name":"尿素循环","stars":3,"years":["10"],"points":["① NH₃ + CO₂ + 2 ATP → 氨甲酰磷酸（氨甲酰磷酸合成酶Ⅰ，限速，需 N-乙酰谷氨酸 NAG 激活） ② 氨甲酰磷酸 + 鸟氨酸 → 瓜氨酸（鸟氨酸转氨甲酰酶）→ 出线粒体 ③ 瓜氨酸 + 天冬氨酸 + ATP → 精氨酸琥珀酸（精氨酸琥珀酸合成酶） ④ 精氨酸琥珀酸 → 精氨酸 + 延胡索酸（精氨酸琥珀酸裂解酶） ⑤ 精氨酸 + H₂O → 尿素 + 鸟氨酸（精氨酸酶）","耗能：3 ATP（2 个用于 ①，1 个用于 ③，实际消耗 4 个高能键，因 AMP→ADP 需再耗 1 个）。 两个氮的来源：一个来自游离氨（①），一个来自天冬氨酸（③）。"]},{"subj":"880","chap":"氨基酸代谢","name":"碳骨架的去路：生糖与生酮氨基酸","stars":2,"years":[],"points":["生酮氨基酸（2 个）：Leu、Lys——只能生成乙酰 CoA/乙酰乙酸，不能净生成糖。 生糖兼生酮（5 个）：Ile、Phe、Tyr、Trp、Thr——碳骨架分裂后一部分进 TCA（生糖）、一部分生成乙酰 CoA/乙酰乙酸（生酮）。 生糖氨基酸（其余 13 个）：Ala、Arg、Asp、Asn、Cys、Glu、Gln、Gly、His、Met、Pro、Ser、Val。 口诀：“住（Leu）宿（Lys）不生糖”；“异苯酪色苏，又糖又酮”。"]},{"subj":"880","chap":"氨基酸代谢","name":"氨的转运：丙氨酸-葡萄糖循环 名解","stars":3,"years":["13","16","19"],"points":["肌肉：氨基酸转氨给丙酮酸 → 丙氨酸（无毒转运形式）→ 血液 → 肝：丙氨酸再转氨给 α-KG → 丙酮酸（用于糖异生）+ 谷氨酸（释放氨进尿素循环）。生成的葡萄糖经血液回肌肉，形成循环。 意义：把肌肉的氨以无毒形式运到肝，同时把碳骨架用于肝糖异生——“一箭双雕”。这也是 2021/2023 年“为什么血中 Ala 和 Gln 浓度最高”的答案：二者是氨的运输载体。","γ-谷氨酰循环（名解 13）：小肠/肾中经谷胱甘肽转运氨基酸的循环（γ-谷氨酰基转移、再合成谷胱甘肽）。"]},{"subj":"880","chap":"核苷酸代谢","name":"从头合成 vs 补救途径","stars":2,"years":[],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"核苷酸代谢","name":"嘌呤分解与痛风 纲要明确“重点掌握”","stars":3,"years":[],"points":["分解路径：AMP → 次黄嘌呤；GMP → 鸟嘌呤 →（脱氨）黄嘌呤 →（黄嘌呤氧化酶）→ 尿酸（人类终产物，因缺乏尿酸氧化酶）。","痛风成因：尿酸生成过多或排泄不足 → 血尿酸 > 饱和浓度 → 以尿酸盐结晶沉积于关节、软组织、肾 → 激活炎症小体 → 急性关节炎（第一跖趾关节最常见）。 治疗：① 别嘌呤醇——次黄嘌呤类似物，竞争性抑制黄嘌呤氧化酶（也属机制性/“自杀性”灭活，做题写“竞争性抑制”最稳），减少尿酸生成；② 促排泄药（丙磺舒）；③ 碱化尿液、低嘌呤饮食、多饮水。"]},{"subj":"880","chap":"DNA 复制、修复与重组","name":"半保留复制与半不连续复制","stars":3,"years":["10","12","18"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"DNA 复制、修复与重组","name":"复制所需的酶与蛋白因子","stars":3,"years":["17"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"DNA 复制、修复与重组","name":"端粒与端粒酶","stars":2,"years":["09","10"],"points":["概念：端粒酶是含 RNA 的逆转录酶，以自身 RNA 为模板合成端粒 DNA（TTAGGG 重复），延长因复制而缩短的端粒。 功能：① 稳定染色体末端、防止染色体间融合与降解；② 补偿后随链 5' 端去除 RNA 引物后的空缺（解决末端复制问题）；③ 维持基因组完整与细胞增殖能力。 分布与双刃剑：正常体细胞活性极低，仅造血细胞、干细胞、生殖细胞有活性；肿瘤细胞中重新激活 → 无限增殖（抗癌靶点）。"]},{"subj":"880","chap":"DNA 复制、修复与重组","name":"DNA 损伤与修复","stars":2,"years":[],"points":["五种修复系统的对照表见《631 分子生物学手册》第 ④ 节，此处只记880 常考的三句话：① 错配修复靠母链甲基化识别新旧链；② 切除修复分 BER（切单个碱基）与 NER（切一段寡核苷酸，缺陷致着色性干皮病）；③ SOS 修复由 RecA 促 LexA 自切割启动，属易错修复，突变率升高。"]},{"subj":"880","chap":"RNA 的生物合成与加工","name":"启动子与操纵子 启动子 12/17/19 · 操纵子","stars":3,"years":["12","16","17","19"],"points":["DNA 链上能指示转录起始的序列，是 RNA 聚合酶识别与结合的部位。 原核：−10 区（TATAAT） + −35 区（TTGACA），由 σ 因子识别。 真核：TATA 盒（−25~−30）+ CAAT 盒、GC 盒等上游元件，由 TFⅡD 识别。","原核生物在转录水平控制基因表达的协调单位，由启动子 P + 操纵基因 O + 功能相关的一组结构基因组成（另可有调节基因）。 一个操纵子转录出一条多顺反子 mRNA。真核生物没有操纵子。"]},{"subj":"880","chap":"RNA 的生物合成与加工","name":"转录终止的两种机制","stars":3,"years":["10"],"points":["结构：回文对称、富含 GC 的序列（转录出发夹）+ 结尾 约 6 个 U。 机制：发夹使 RNAP 暂停；rU-dA 配对最弱（2 个氢键），杂合双链易解开 → RNA 释放。","结构：回文区不含富 GC，之后无寡聚 U。 机制：ρ 因子（六聚体解旋酶）结合新生 RNA 的 rut 位点，耗 ATP 沿 RNA 5'→3' 追赶；RNAP 在终止子处暂停时，ρ 追上并解旋 RNA-DNA 杂合体，释放 RNA。"]},{"subj":"880","chap":"RNA 的生物合成与加工","name":"两道“为什么”型辨析题","stars":2,"years":["12","13"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"880","chap":"RNA 的生物合成与加工","name":"真核 mRNA 加工","stars":3,"years":[],"points":["加 m⁷G 帽（5'-5' 三磷酸键）→ 3' 端在 AAUAAA 信号后切割并加 poly(A) → 剪接（去除内含子，GU-AG 规则，剪接体 U1/U2/U4/U5/U6）→ 可选RNA 编辑。 帽子功能：保护 5' 端、翻译起始识别、核输出；尾巴功能：稳定性、核输出、翻译效率。详见《631 手册》第 ⑤ 节。"]},{"subj":"880","chap":"遗传密码与蛋白质合成","name":"给 DNA 写 mRNA 再翻译","stars":3,"years":["21","22"],"points":["分清链：题目给的是编码链（有义链，与 mRNA 同序列，只是 T→U）；若是模板链，则需先互补。","写出 mRNA：编码链 5'→3' 直接把 T 换成 U：5'-ACUAGUAAUUUUGCAUGU-3'。","找起始密码子 AUG，按三联体从 AUG 开始读，遇终止密码子（UAA/UAG/UGA）停止。"]},{"subj":"880","chap":"基因表达调控与基因工程","name":"PCR：条件、原理、应用","stars":3,"years":["12","19","20"],"points":["循环次数：25~35 次。太少产量不足；太多进入平台期（dNTP/引物耗尽、酶失活、产物抑制），且非特异产物与突变增多。 体系五要素：模板、一对引物、dNTP、耐热 Taq DNA 聚合酶、Mg²⁺（辅因子）+ 缓冲液。 引物设计：18~25 nt、GC 40%~60%、3' 端避免互补、两引物 Tm 接近、避免形成发夹。","① 基因/探针的扩增合成；② DNA 测序与二代建库；③ RT-PCR（RNA→cDNA，检测基因转录）；④ 实时定量 PCR（SYBR Green / TaqMan）；⑤ 基因突变（易错 PCR、定点诱变）与重组 PCR；⑥ 未知序列扩增（反向 PCR、染色体步移）；⑦ 医学诊断、法医鉴定、转基因检测。"]},{"subj":"880","chap":"基因表达调控与基因工程","name":"限制酶与质粒","stars":2,"years":["13"],"points":["① 细菌同时拥有限制酶 + 甲基化酶（限制-修饰系统），自身 DNA 的识别位点已被甲基化，修饰后不被切割；② 有些菌株基因组中本就不含该识别序列；③ 极少数被切时由修复系统补救。这是细菌防御外源 DNA 的机制。","① 有自主复制起点（与宿主匹配的复制元件）；② 有易筛选的选择标记（抗药性、营养、显色）；③ 有多个单一限制酶切位点（MCS）；④ 分子尽可能小，便于导入与扩增；⑤ 使用安全（宿主范围有限、不随意转移、不产生有害性状）。"]},{"subj":"880","chap":"基因表达调控与基因工程","name":"操纵子调控","stars":2,"years":[],"points":["乳糖操纵子（可诱导、负控 + CAP 正控）与色氨酸操纵子（可阻遏、负控 + 弱化子）的完整机制、四象限表、弱化子 1-2-3-4 配对规则，见《631 手册》第 ⑧ 节——两科共用同一套答案，背一次，两科都能用。","真核调控多级性：染色质水平（甲基化/组蛋白修饰）→ 转录水平（转录因子、增强子）→ 转录后（可变剪接）→ 翻译水平（miRNA）→ 翻译后（降解/修饰）。"]},{"subj":"880","chap":"生化实验专题（大纲第 18 条）","name":"实验一：蛋白质的分离提取","stars":3,"years":[],"points":["选材与破碎：选富含目标蛋白的组织/菌体；用匀浆、超声、高压、冻融、溶菌酶破细胞。","提取：低温（0~4 ℃）、合适 pH 与离子强度的缓冲液；加蛋白酶抑制剂（PMSF）与还原剂（DTT/β-巯基乙醇）防降解与氧化。","粗分级（按溶解度）：盐析（硫酸铵分段：20%~40% 去杂蛋白，40%~60% 收目标蛋白）、有机溶剂沉淀、等电点沉淀。","细分级（按大小/电荷/亲和）：透析/超滤脱盐 → 凝胶过滤（按 Mr）或 离子交换（按电荷）或 亲和层析（按特异性）。","浓缩与鉴定：PEG/超滤浓缩 → SDS-PAGE 看纯度与 Mr → 测比活力算纯化倍数。"]},{"subj":"880","chap":"生化实验专题（大纲第 18 条）","name":"实验二：SDS-PAGE 全流程","stars":3,"years":["12","13"],"points":["① 配胶（分离胶 pH 8.8，浓缩胶 pH 6.8）→ ② 上样（样品 + 上样缓冲液，含 SDS、β-巯基乙醇、溴酚蓝、甘油，沸水浴 3~5 min）→ ③ 电泳（恒压/恒流，溴酚蓝前沿到胶底停止）→ ④ 考马斯亮蓝 R-250 染色 → ⑤ 脱色 → ⑥ 拍照/扫描，与标准分子量 Marker 比对读数。","判读：条带越靠上 Mr 越大；单一条带说明纯度高；若条带数多于预期，说明有降解或杂蛋白。注意：SDS-PAGE 测的是亚基分子量（二硫键被还原），不是天然分子量。"]},{"subj":"880","chap":"生化实验专题（大纲第 18 条）","name":"实验三：考马斯亮蓝 G-250 测蛋白含量","stars":3,"years":["11","20"],"points":["① 酸性条件下染料呈棕红色（最大吸收 465 nm）；② 与蛋白质通过疏水作用结合后变为蓝色，最大吸收移至 595 nm；③ 在一定范围内，A595 的增加与蛋白浓度成正比。","① 配 0~100 μg/mL 的牛血清白蛋白（BSA）标准series，各管补足体积；② 每管加考马斯亮蓝试剂，混匀，室温静置 5~15 min；③ 以试剂空白调零，测 A595；④ 以浓度为横坐标、A595 为纵坐标作图（线性回归）；⑤ 同样处理待测样品，用标准曲线反算浓度，再乘以稀释倍数与总体积得总蛋白量。","注意事项：染料会吸附比色皿（宜用一次性塑料皿）；去污剂（SDS、Triton）与强碱干扰；显色不稳定，需在 1 h 内读完。"]},{"subj":"880","chap":"生化实验专题（大纲第 18 条）","name":"实验四：核酸的提取与鉴定","stars":3,"years":["20"],"points":["① 裂解：SDS + 蛋白酶 K 破细胞、消化蛋白；② 抽提：等体积苯酚/氯仿/异戊醇（25:24:1），变性蛋白留在有机相或界面；③ 离心分层，取上层水相；④ 沉淀：加 0.1 体积 3 mol/L NaAc + 2 倍体积无水乙醇（−20 ℃），DNA 成絮状析出；⑤ 洗涤：70% 乙醇洗盐 → 干燥 → 溶于 TE 缓冲液（含 EDTA 抑制核酸酶）。","RNA 提取：需抑制 RNase（DEPC 处理、异硫氰酸胍、酸性酚），全程低温、无 RNase 环境。","① A260/A280：DNA 约 1.8、RNA 约 2.0，偏低提示蛋白污染；② A260/A230 > 2.0，偏低提示多糖/酚残留；③ 琼脂糖电泳：条带清晰、无拖尾、无 RNA 污染（DNA 样品中 28S/18S 带说明 RNA 未除净）；④ 限制酶消化：能被完全切开说明纯度合格。"]},{"subj":"880","chap":"生化实验专题（大纲第 18 条）","name":"实验五：琼脂糖凝胶电泳","stars":2,"years":["18","19"],"points":["原理：琼脂糖凝胶是带孔隙的分子筛；DNA 带负电（磷酸骨架），在电场中向正极迁移；迁移率与lg 分子量成反比（大分子受阻大、跑得慢）。","操作：配胶（0.8%~1% 琼脂糖 + 电泳缓冲液 TAE/TBE）→ 加核酸染料（EB/ GelRed）→ 上样（样品 + 上样缓冲液，含甘油增重、溴酚蓝指示）→ 电泳（5~10 V/cm）→ 紫外凝胶成像。","判断：与 DNA Marker 比对可估大小与浓度；质粒因构型不同可呈三条带——超螺旋（最快）> 线性 > 开环（最慢）；基因组 DNA 应呈单一高分子量条带，若出现拖尾说明降解。"]},{"subj":"880","chap":"生化实验专题（大纲第 18 条）","name":"实验六：酶的分离提取与酶活测定","stars":3,"years":["16","19","21","22"],"points":["① 全程低温（0~4 ℃）防酶失活；② 缓冲液加金属离子螯合剂（EDTA）与还原剂（DTT），防金属催化与氧化；③ 加蛋白酶抑制剂；④ 尽量缩短操作时间；⑤ 有的酶需加辅因子/底物稳定活性构象。","① 在最适 pH 与最适温度下测；② 测初速度（底物消耗 < 5%，避免产物抑制与逆反应）；③ 底物浓度应饱和（≫Km，保证零级动力学）；④ 用连续分光光度法（如 NADH 在 340 nm 的变化）或终止法。","计算链：酶活力(U/mL) = (ΔA/min × V总) / (ε × d × V酶) / 10⁶ … 实际考试只需掌握： 总活力 = 活力 × 体积；比活力 = 总活力/总蛋白；回收率 = 总活力₂/总活力₁；纯化倍数 = 比活力₂/比活力₁"]},{"subj":"631","chap":"染色体与核酸结构","name":"核小体结构特征","stars":2,"years":["18"],"points":["定性：核小体是染色体的基本结构单位，是 DNA 压缩的第一级。","组成：组蛋白八聚体核心（H2A、H2B、H3、H4 各 2 分子）+ 1 分子 H1 + 约 200 bp DNA。","装配顺序：H3、H4 先形成四聚体 (H3-H4)₂ → 两个 (H2A-H2B) 异二聚体结合在四聚体两侧 → 形成八聚体核心。","DNA 走向：约 146 bp 的 DNA 以左手超螺旋在八聚体上盘绕约 1.75 圈。","H1 的位置与作用：核心颗粒两端 DNA 各约 11 bp（各教材口径 10~20 bp）与 H1 结合；H1 结合在核小体外侧的接头处，使结构更紧凑。"]},{"subj":"631","chap":"染色体与核酸结构","name":"DNA 双螺旋模型的特点","stars":2,"years":[],"points":["反向平行的两条多核苷酸链，围绕同一中心轴形成右手双螺旋。","直径 2 nm，螺距 3.4 nm，每圈 10 个碱基对，相邻碱基对上升 0.34 nm，夹角 36°。","磷酸-脱氧核糖骨架在外侧，碱基在内侧；碱基对平面与轴垂直。","表面有大沟（2.2 nm）与小沟（1.2 nm），是蛋白质识别 DNA 的部位。","维持力：碱基对间氢键（A=T 两个、G≡C 三个）+ 碱基堆积力（主要）+ 磷酸基负电荷与阳离子/组蛋白的中和。"]},{"subj":"631","chap":"染色体与核酸结构","name":"核酶","stars":2,"years":[],"points":["结构：核酶的催化功能依赖其空间结构。已发现的多种自我切割型核酶，其活性中心为锤头结构：由三个茎区（茎Ⅰ、Ⅱ、Ⅲ，互补碱基构成的局部双链）包围一个由 11~13 个保守核苷酸构成的催化中心；底物为切割位点两端的核苷酸，与茎Ⅰ、茎Ⅲ配对。","意义（三条，缺一扣分）：① 是对中心法则的重要修正——RNA 既是遗传物质又是催化剂，打破了“酶一定是蛋白质”的观念；② 为生命起源的“RNA 世界”假说提供依据；③ 有应用价值——可设计核酶切割有害基因/病毒 RNA，用于肿瘤与抗病毒治疗。"]},{"subj":"631","chap":"染色体与核酸结构","name":"断裂基因 / 重叠基因 / 联会体 / 转化","stars":1,"years":[],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"DNA 复制","name":"后随链的复制","stars":2,"years":["10"],"points":["解旋 + 引发：解旋酶沿复制叉方向解开双链；引发酶（引发体）识别模板上的引发序列，合成一段短的 RNA 引物。","绕环：后随链模板绕成回环，使 Pol Ⅲ 的两个核心酶可以同时在同一方向工作；Pol Ⅲ 通过 β 夹子（滑动夹）和 γ 复合物（夹 loader）结合到模板上，把 dNTP 加到引物 3'-OH 端。","延伸至前一片段引物处停止，Pol Ⅲ 与模板脱离 → 一个冈崎片段合成完毕。","切除引物 + 填补：Pol Ⅰ 识别引物 5' 端，用 5'→3' 外切酶活性切除 RNA 引物，同时用聚合酶活性填补缺口。","连接：主链上残留的缺口由 DNA 连接酶形成磷酸二酯键封闭，两个片段连成一条链。"]},{"subj":"631","chap":"DNA 复制","name":"DNA 聚合酶如何维持复制忠实性","stars":2,"years":["13"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"DNA 复制","name":"端粒、端粒酶与末端复制问题","stars":2,"years":["13"],"points":["取材：外周血白细胞（最能反映生理/病理状态）。","提 DNA：苯酚/氯仿抽提总 DNA。","酶切：HinfⅠ（识别 GANTC，5 bp）或 RsaⅠ（识别 GTAC，4 bp），两者都切得频繁消化，使亚端粒区尽可能短。","电泳 + 转膜：琼脂糖电泳分离，转硝酸纤维素膜/尼龙膜。","杂交：³²P 或生物素/碱性磷酸酶标记的端粒探针 (CCCTAA)ₙ 杂交。"]},{"subj":"631","chap":"DNA 复制","name":"真核 vs 原核复制差异 / 拓扑异构酶 / ColE1","stars":1,"years":[],"points":["拓扑异构酶：通过切断—转移—重接磷酸二酯键改变 DNA 拓扑状态。Ⅰ 型切一条链、不需 ATP、改变连环数 ±1；Ⅱ 型（旋转酶）切两条链、需 ATP、每次改变 ±2，负责解除复制叉前的正超螺旋。","ColE1：拷贝数 20~30，依赖宿主 Pol Ⅰ。质粒编码两个负调控因子——RNA1（与引物 RNA 前体 5' 端互补，阻止 RNase H 加工出活性引物）与 Rop 蛋白（增强 RNA1 与引物前体的配对）。拷贝数越高，RNA1 越多，复制被抑制——典型的负反馈。"]},{"subj":"631","chap":"突变 · 修复 · 重组","name":"六种 DNA 修复系统","stars":2,"years":[],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"突变 · 修复 · 重组","name":"转座子：类型与遗传学效应","stars":2,"years":["18"],"points":["定义：染色体（或基因组）上能改变自身位置的 DNA 元件（复制型或非复制型），能在没有序列同源性的情况下独立插入基因组新位点。","结构：两端为反向重复序列 IR，中间为转座酶基因；插入后靶位点两侧产生正向重复序列 DR（长度固定，是“转座足迹”）。","遗传学效应（5 条）：① 引起基因突变失活（插入外显子/调控区）；② 产生染色体畸变（缺失、倒位、重复、易位）；③ 调控基因表达（带启动子/增强子/终止信号）；④ 产生新基因（外显子改组）；⑤ 促进生物进化与基因组可塑性。"]},{"subj":"631","chap":"突变 · 修复 · 重组","name":"同源重组 / 位点特异性重组 / 抗生素抗性","stars":1,"years":[],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"转录与转录后加工","name":"启动子","stars":3,"years":["13","19"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"转录与转录后加工","name":"RNA 聚合酶与转录过程","stars":3,"years":[],"points":["起始：σ 因子引导全酶识别 −35/−10 区并与之结合，形成闭合复合物 → DNA 局部解链形成开放复合物（转录泡，约 17 bp）→ 首个核苷酸加入，σ 因子释放，进入延伸。","延伸：核心酶沿模板 3'→5' 移动，RNA 按 5'→3' 合成；转录泡内形成 RNA-DNA 杂合双链（约 8 bp），后方 DNA 重新配对，前方解链。"]},{"subj":"631","chap":"转录与转录后加工","name":"转录终止的两种机制","stars":2,"years":["10"],"points":["结构：① 一段回文对称、富含 G-C 的序列 → 转录出发夹结构；② 发夹之后紧跟约 6 个 U（寡聚 U）。","机制：发夹结构使 RNA 聚合酶停顿，随后 rU-dA 弱配对（只有两个氢键）使杂合双链易解离，酶脱落。","ρ 是环状六聚体解旋酶，结合在新转录 RNA 的 rut 位点（富含 C、少 G、无二级结构），消耗 ATP 沿 RNA 5'→3' 追尾。","当 RNAP 在终止子处暂停时，ρ 追上并解旋 RNA-DNA 杂合体，释放 RNA，终止转录。"]},{"subj":"631","chap":"转录与转录后加工","name":"真核 mRNA 加工与原核-真核 mRNA 差异","stars":3,"years":[],"points":["5' 帽：① 保护 mRNA 免受 5' 外切酶降解；② 作为翻译起始的识别信号（eIF4E 结合帽）；③ 参与 mRNA 核输出；④ 影响剪接与前体加工。 3' poly(A) 尾：① 增加稳定性（抗 3' 外切酶）；② 参与核输出；③ 影响翻译效率（PABP 与 eIF4G 互作形成“闭环”）。"]},{"subj":"631","chap":"RNA 剪接与 RNA 编辑","name":"四类内含子与两种自剪接","stars":2,"years":[],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"RNA 剪接与 RNA 编辑","name":"剪接体的组分与组装","stars":2,"years":[],"points":["E 复合物：U1 结合 5' 剪接位点 GU；U2AF 结合 3' 剪接位点 AG 及多聚嘧啶区；SF1 结合分支点 A。","A 复合物：U2 与分支点 A 结合（ATP 依赖），A 的 2'-OH 突出。","B 复合物：U4/U6·U5 三聚体加入；U4 与 U6 配对，抑制 U6 活性（“分子开关”关闭状态）。","激活 → C 复合物：U1、U4 解离，U6 与 U2 配对形成催化核心；第一步转酯：分支点 A 的 2'-OH 攻击 5' 剪接位点 → 游离外显子 1 + 套索-外显子 2。","第二步转酯：外显子 1 的 3'-OH 攻击 3' 剪接位点 → 外显子连接，套索内含子释放并降解。"]},{"subj":"631","chap":"RNA 剪接与 RNA 编辑","name":"可变剪接","stars":2,"years":["13"],"points":["模式：① 外显子跳跃（最常见）；② 内含子保留；③ 可变 5'/3' 剪接位点；④ 互斥外显子。 意义：一个基因 → 多种蛋白，是蛋白质组多样性的主要来源（人类约 95% 多外显子基因存在可变剪接）；与组织特异性、发育阶段、疾病（如 tau 外显子 10 剪接异常）相关。 调控：SR 蛋白（增强剪接，结合外显子剪接增强子 ESE）与 hnRNP（抑制剪接）的相对浓度决定选择。"]},{"subj":"631","chap":"RNA 剪接与 RNA 编辑","name":"RNA 编辑","stars":2,"years":[],"points":["定义：转录后通过插入/删除/替换核苷酸改变 mRNA 序列，使产物与 DNA 模板不一致的现象。","方式：① 碱基替换（编辑酶脱氨：C→U、A→I），如 apoB 基因在肝/肠产生不同产物；② 插入/删除（以 gRNA 为模板），见于锥虫线粒体。","gRNA 机制：gRNA 与 mRNA 前体互补配对，其“锚定区”配对后，指导在 mRNA 中插入尿嘧啶（U）（或删除多余的 U），形成新的密码子，产生功能不同的 mRNA。"]},{"subj":"631","chap":"翻译与遗传密码","name":"遗传密码的特点","stars":2,"years":[],"points":["三联体：3 个相邻核苷酸编码 1 个氨基酸，共 64 个密码子。","连续性 / 无重叠：密码子首尾相接、不重叠、无标点（除终止）。","简并性：一个氨基酸可由多个密码子编码（Leu、Ser、Arg 各 6 个）；只有 Met（AUG） 和 Trp（UGG） 唯一。","通用性 / 近乎通用：从病毒到人基本共用一套；例外：线粒体（UGA=Trp、AGA/AGG=终止）、部分原核。","起始与终止：起始 AUG（原核也用小 GUG/UUG）；终止 UAA（赭石）、UAG（琥珀）、UGA（蛋白石），不编码氨基酸。"]},{"subj":"631","chap":"翻译与遗传密码","name":"确保翻译精确性的机制","stars":2,"years":[],"points":["能量保障：每形成 1 个肽键至少水解 4 个高能磷酸键（2 ATP 用于氨酰化 + 1 GTP 用于进位 + 1 GTP 用于移位），高耗能换取高保真。","氨酰-tRNA 合成酶的双重校对：既识别 tRNA（反密码子、 acceptor 臂），又识别氨基酸（活性中心“筛子”排除相近氨基酸）；错误时水解校正（化学校对与动力学校对）。","核糖体：小亚基译码中心（16S rRNA 与密码子-反密码子小沟作用）监控配对；错误时通过动力学校对（aa-tRNA 解离速率差异）剔除。","蛋白因子：起始因子保证只有 fMet-tRNA / Met-tRNAᵢ 进入 P 位；延伸因子（EF-Tu）保证其余 aa-tRNA 只进 A 位。","密码子简并性：同义密码子使突变后氨基酸性质变化最小（“安全性”）。"]},{"subj":"631","chap":"翻译与遗传密码","name":"原核 vs 真核翻译起始差异","stars":1,"years":[],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"原核基因调控（操纵子）","name":"乳糖操纵子","stars":3,"years":["10","13"],"points":["调节基因 lacI（上游，组成型表达）→ 启动子 P → 操纵基因 O → 结构基因 lacZ（β-半乳糖苷酶）、lacY（通透酶）、lacA（转乙酰基酶）。三个结构基因共转录为一条多顺反子 mRNA。","无乳糖：lacI 产生的阻遏蛋白（四聚体）结合 O 区，物理阻挡 RNAP 结合/前移 → 转录关闭（本底表达极低）。 有乳糖：乳糖经 β-半乳糖苷酶转化为别乳糖（allolactose），作为诱导物结合阻遏蛋白 → 构象改变 → 从 O 区解离 → 转录开启。这是可诱导的负调控。","葡萄糖缺乏 → cAMP 升高 → cAMP 与 CAP（CRP）结合 → CAP 构象改变 → 结合 P 上游的 CAP 位点 → 促进 RNAP 结合，转录效率提高 50 倍。 葡萄糖充足 → cAMP 低 → CAP 不结合 → 即使去阻遏，转录也很弱。"]},{"subj":"631","chap":"原核基因调控（操纵子）","name":"色氨酸操纵子与弱化子","stars":3,"years":["18"],"points":["调节基因 trpR → P → O → 前导区（trpL，含弱化子 att） → E、D、C、B、A 五个结构基因（邻氨基苯甲酸合成酶、PRPP 转移酶等的亚基）。","Trp 充足 → Trp 作为辅阻遏物与阻遏蛋白结合 → 结合 O 区 → 关闭转录；Trp 缺乏 → 阻遏蛋白无活性（apo 形式不结合 O）→ 转录开启。注意：与 lac 相反，这里 Trp 是辅阻遏物而非诱导物。","前导区转录出 1、2、3、4 四段可互补序列，其中 3-4 配对 = 终止发夹（弱化子），2-3 配对 = 抗终止发夹。前导肽第 10、11 位是两个相邻的 Trp 密码子，因此翻译速度直接反映 Trp-tRNA 水平：","④ 协同：阻遏系统控制起始（粗调，经济）；弱化系统控制起始后是否继续（细调，快速响应），两者叠加使表达量可跨 约 600 倍 范围调节。"]},{"subj":"631","chap":"原核基因调控（操纵子）","name":"其它原核调控方式","stars":2,"years":[],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"真核基因调控与表观遗传","name":"表观遗传 / 表观调控 / 组蛋白密码","stars":3,"years":["10","13","19"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"真核基因调控与表观遗传","name":"转录因子与顺式/反式元件","stars":2,"years":["18"],"points":["DNA 结合结构域：锌指（C2H2，最常见）、同源域（helix-turn-helix）、bZIP（亮氨酸拉链）、bHLH、HMG。","转录激活结构域：酸性（如 Gal4）、富含 Gln/Pro 型；通过招募 共激活因子/中介体（Mediator）/HAT 起效。","二聚化结构域（部分因子）：形成同/异二聚体，扩大调控组合的多样性。"]},{"subj":"631","chap":"真核基因调控与表观遗传","name":"真核调控的多级层次","stars":2,"years":[],"points":["染色质水平：核小体排布、组蛋白修饰、DNA 甲基化、染色质重塑（“开关是否可及”）。","转录水平：转录因子 + 增强子/沉默子/绝缘子 + Mediator；最主要的调控点。","转录后水平：可变剪接、可变加尾、RNA 编辑、mRNA 稳定性（AU-rich 元件）。","翻译水平：5'UTR 二级结构、uORF、miRNA 抑制、起始因子磷酸化。","翻译后水平：蛋白酶体降解、磷酸化/泛素化修饰、定位信号。"]},{"subj":"631","chap":"真核基因调控与表观遗传","name":"其它真核调控元件与现象","stars":1,"years":[],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"调控 RNA 与非编码 RNA","name":"RNA 干扰","stars":3,"years":["13","19"],"points":["引入/产生：外源 dsRNA（或转基因、病毒）进入细胞。","Dicer 加工：RNase Ⅲ 家族酶 Dicer 将 dsRNA 切成 21~23 nt 的 siRNA（带 5' 磷酸、3' 两个突出碱基）。","装配 RISC：siRNA 与 Argonaute 等蛋白组装成 RNA 诱导沉默复合体（RISC）；siRNA 双链解旋，引导链保留、过客链降解。","执行沉默（三条路径）：① 切割——AGO2 的“Slicer”活性切割完全互补的靶 mRNA；② 翻译抑制——不完全互补时阻滞翻译（多见于 miRNA）；③ 染色质沉默——与基因组序列配对，招募组蛋白/DNA 甲基化酶，形成异染色质。"]},{"subj":"631","chap":"调控 RNA 与非编码 RNA","name":"snRNA / miRNA / gRNA / siRNA 辨析","stars":2,"years":["10"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"调控 RNA 与非编码 RNA","name":"反义 RNA 的五种作用方式","stars":2,"years":[],"points":["与 mRNA 前体结合 → 影响成熟与核输出。","与靶 RNA 结合 → 激活 RNase（如 RNase H）→ 加速降解。","与 起始密码子区域结合 → 阻止翻译起始。","作用于 SD 区 → 阻止核糖体结合（原核特有）。","作用于 DNA → 形成三链或阻断转录（转录水平抑制）。"]},{"subj":"631","chap":"分子生物学技术","name":"Southern / Northern / Western 印迹","stars":3,"years":["18"],"points":["① 限制酶消化 DNA → ② 琼脂糖凝胶电泳分离 → ③ 碱变性（原位解链）→ ④ 毛细管/电转移至硝酸纤维素膜或尼龙膜 → ⑤ 烘烤或 UV 交联固定 → ⑥ 预杂交（鲑鱼精 DNA 封闭非特异位点）→ ⑦ 与标记探针杂交 → ⑧ 洗膜、放射自显影/显色。","原理：具有一定同源性的两条单链核酸在适宜条件下按碱基互补形成双链（杂交高度特异）+ 探针的高灵敏度检测。","应用：遗传病基因诊断、DNA 指纹/图谱分析、转基因检测、PCR 产物验证、基因拷贝数分析。"]},{"subj":"631","chap":"分子生物学技术","name":"PCR：原理、体系、条件、应用","stars":3,"years":["19"],"points":["根据待扩增片段两端序列设计一对互补寡核苷酸引物；在模板、引物、dNTP、耐热 DNA 聚合酶（Taq）、Mg²⁺ 体系中，经 高温变性—低温退火—适温延伸 循环，使目标片段以 2ⁿ 几何级数扩增。"]},{"subj":"631","chap":"分子生物学技术","name":"DNA-蛋白质相互作用的四大方法","stars":2,"years":["10"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"分子生物学技术","name":"基因芯片 · 蛋白质组学 · SDS-PAGE","stars":2,"years":["10","19"],"points":["原理：原位合成或显微打印，把数以万计的 DNA 探针固化在支持物上形成二维阵列，与标记样品杂交，检测杂交信号实现快速、并行、高通量检测。 应用：基因型/突变/多态性分析、表达谱分析、杂交测序、同源性与身份鉴定（亲子/血型）、核酸-蛋白互作与药物筛选。 表达谱流程：PCR 扩增 cDNA 片段 → 点样变性固定 → 各组织提 mRNA 逆转录并用不同荧光标记 → 杂交 → 激光扫描 → 软件分析差异表达。","定义：以蛋白质组（一个基因组所表达的全套蛋白质）为对象，研究其组成与变化规律；本质是大规模研究蛋白表达水平、翻译后修饰、蛋白-蛋白互作。","核心方法：双向电泳（2-DE）——第一维等电聚焦（按 pI 分离）+ 第二维 SDS-PAGE（按分子量分离）；质谱——一级肽指纹图谱 PMF、二级肽段碎片指纹 PFF、串联质谱测序。 流程：2-DE 分离 → 取点 → 酶切（胰蛋白酶）→ HPLC 分离 → 质谱 → 数据库比对。 2D-DIGE：三种荧光染料（Cy2/Cy3/Cy5）分别标记不同样本，同一块胶电泳，加内标（IS）消除胶间误差。","两条理由：① SDS 是阴离子去污剂，大量结合使各蛋白带相同密度的负电荷，掩盖原有电荷差异；② SDS 是变性剂，破坏氢键与疏水作用，使蛋白伸展为同样的棒状。因此迁移率只取决于分子量，且与分子量的对数呈线性关系。 三个“为什么”（期末原题）：加巯基乙醇——还原二硫键，解离亚基；沸水煮沸——充分变性并助 SDS 结合；凝胶前抽气——除去气泡，避免聚合不均与条带畸变。"]},{"subj":"631","chap":"分子生物学技术","name":"核酸质量检测与电泳图判读","stars":1,"years":["18","19"],"points":["质量检测三法：① 琼脂糖凝胶电泳——看条带是否清晰、有无降解拖尾、有无 RNA/蛋白污染；② 紫外吸收——A260/A280 ≈ 1.8（纯 DNA）、A260/A230 > 2.0（无多糖/酚残留）；③ 限制酶消化——能被完全切开说明纯度合格。","电泳图判读：质粒分子量小、迁移最快，跑在最前；同一质粒因提取损伤可呈三种构型——共价闭合环状（超螺旋，最快、最亮）> 线性 > 开环状（最慢）。细菌染色体 DNA 大，滞留在加样孔附近。"]},{"subj":"631","chap":"克隆与基因工程","name":"分子克隆路线","stars":3,"years":["18","19"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"克隆与基因工程","name":"基因组文库 vs cDNA 文库","stars":3,"years":["10","19"],"points":["① 只含功能基因，文库小、减少筛选工作量；② 假阳性低，阳性信号基本有意义；③ 由成熟 mRNA 逆转录而来，无内含子，可直接在原核中表达真核基因；④ 保留丰度差异与组织特异性，可研究差异表达。"]},{"subj":"631","chap":"克隆与基因工程","name":"蓝白斑筛选","stars":3,"years":["19"],"points":["β-半乳糖苷酶可分成两部分：α 肽段（N 端 146 aa，基因在载体上，且含不影响 ORF 的多克隆位点 MCS）与 C 段（基因在宿主菌 DH5α 染色体上）。两者在同一菌株表达时可互补成有活性的酶，切割无色底物 X-gal 产生深蓝色产物（5,5'-二溴-4,4'-二氯靛蓝）。","插入失活：外源基因插入 MCS → 改变 α 肽段 ORF → 不能互补 → 无酶活性 → 菌落白色。"]},{"subj":"631","chap":"克隆与基因工程","name":"外源基因的高效表达","stars":3,"years":["10"],"points":["A. 强化表达元件（载体层面）：① 强启动子（如 tac、T7）；② 强 RBS/SD 序列，注意与起始密码子的间距及上下游序列；③ 强终止子（避免过长 mRNA 浪费能量、干扰翻译）；④ 使用增强子；⑤ 使用宿主偏爱密码子。","B. 提高基因剂量：⑥ 选松弛型质粒提高拷贝数。","C. 保护产物：⑦ 选蛋白酶缺陷宿主（如 lon⁻、ompT⁻）；⑧ 以融合蛋白形式表达（防降解、便于纯化）。","D. 减轻负担与促折叠：⑨ 用可诱导表达载体，把菌体生长与表达分期，避免代谢负荷；⑩ 宿主高表达分子伴侣促正确折叠；另可分泌表达（融合信号肽，便于纯化）或以包涵体形式表达后复性。"]},{"subj":"631","chap":"克隆与基因工程","name":"载体、限制酶与转化","stars":2,"years":["13","19"],"points":["① 有自主复制起点（与宿主匹配的复制元件），能在宿主中独立复制；② 有易于筛选的选择标记（抗药性、营养、显色）；③ 有多个单一限制酶切位点（MCS），便于插入而不破坏必需区；④（加分）分子小、拷贝数高、易转化、易从宿主中回收。","① 自身 DNA 的识别位点已被甲基化修饰（对应甲基化酶），修饰后不被切割；② 酶与修饰酶成对存在（限制-修饰系统），是细菌防御外源 DNA 的机制；③ 极少数会被切，靠修复系统补救。","常见载体：质粒（≤10 kb）、λ 噬菌体（约 20 kb）、柯斯质粒 cosmid（35~45 kb）、YAC（酵母人工染色体，1 Mb）、BAC（细菌人工染色体，100~300 kb）。"]},{"subj":"631","chap":"克隆与基因工程","name":"营养缺陷型筛选 · 菌落原位杂交","stars":2,"years":["13"],"points":["① 淘汰野生型（富集）：青霉素法/环丝氨酸法——抗生素只杀正在生长的细菌，休止的缺陷型存活。 ② 检出：影印法——完全培养基长出的菌落影印到基本培养基，对比：完全培养基有、基本培养基无 → 缺陷型；夹层法——先铺基本培养基，再覆一层完全培养基，后长出的多为缺陷型。 ③ 鉴定：在基本培养基上分别加单一氨基酸/维生素，看哪个能恢复生长，确定缺陷类型。","① 菌落影印到硝酸纤维素膜并标记方位 → ② NaOH 裂解细胞、变性 DNA、降解 RNA/蛋白 → ③ 中和并洗去碎片（DNA 固定于膜）→ ④ 80 ℃ 烘烤固定 → ⑤ 鲑鱼精 DNA 预杂交封闭 → ⑥ 与标记探针杂交 → ⑦ 洗膜去未结合探针 → ⑧ 放射自显影，黑点即阳性菌落，回找原平板扩大培养。"]},{"subj":"631","chap":"克隆与基因工程","name":"穿梭载体 / 染色体步移 / DNA 疫苗","stars":1,"years":["10"],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]},{"subj":"631","chap":"疾病与人类健康","name":"iPS 细胞","stars":1,"years":["13"],"points":["是什么：用病毒载体把四个转录因子 Oct4、Sox2、Klf4、c-Myc 导入已分化的体细胞，使其重编程为类似胚胎干细胞的多能状态（induced pluripotent stem cells）。","意义：① 可获得病人特异/疾病特异的多能干细胞 → 避免移植免疫排斥；② 绕开胚胎干细胞的伦理争议；③ 可作为疾病模型研究发病机制、做个体化药物评估、发现新靶点。"]},{"subj":"631","chap":"疾病与人类健康","name":"原癌基因与活化途径","stars":2,"years":[],"points":["定义：正常细胞中存在的、参与细胞生长分化调控的基因（原癌基因/细胞癌基因 c-onc），其产物（生长因子、受体、信号分子、转录因子、细胞周期蛋白）促进正常增殖；突变或异常激活后变成癌基因。","四条活化途径：① 点突变（如 Ras G12V，丧失 GTP 酶活性）；② 基因扩增（如 Myc、HER2 拷贝数增加）；③ 染色体易位/重排（如 Burkitt 淋巴瘤 t(8;14) 使 Myc 置于 Ig 增强子下；慢粒 Ph 染色体 t(9;22) BCR-ABL 融合基因）；④ 插入激活（逆转录病毒 LTR/转座子插入附近）。","与抑癌基因的区别：原癌基因是显性、功能获得（一个等位突变即够）；抑癌基因（p53、Rb）是隐性、功能丢失（需两次打击，Knudson 假说）。"]},{"subj":"631","chap":"疾病与人类健康","name":"HIV / SARS-CoV-2 / 基因治疗","stars":2,"years":[],"points":["该考点在手册中以对照表/名词组呈现，请打开对应手册章节通读一遍。"]}]};
